import type { User } from '@supabase/auth-helpers-nextjs';

interface AuthState {
  user: User | null;
  loading: boolean;
  error: string | null;
}

interface AuthMiddlewareProps {
  children: React.ReactNode;
  requireAuth?: boolean;
  redirectTo?: string;
  allowedRoles?: string[];
}

const LoadingSkeleton = () => (
  <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
    <div className="w-full max-w-md space-y-6">
      <div className="text-center space-y-4">
        <div className="w-16 h-16 bg-[rgb(241,245,249)] rounded-full mx-auto animate-pulse" />
        <div className="space-y-2">
          <div className="h-6 bg-[rgb(241,245,249)] rounded animate-pulse" />
          <div className="h-4 bg-[rgb(241,245,249)] rounded w-3/4 mx-auto animate-pulse" />
        </div>
      </div>
      <div className="space-y-3">
        <div className="h-12 bg-[rgb(241,245,249)] rounded animate-pulse" />
        <div className="h-12 bg-[rgb(241,245,249)] rounded animate-pulse" />
      </div>
    </div>
  </div>
);

const ErrorState = ({ 
  message, 
  onRetry 
}: { 
  message: string; 
  onRetry: () => void; 
}) => (
  <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
    <div className="w-full max-w-md text-center space-y-6">
      <div className="space-y-4">
        <div className="w-16 h-16 bg-[rgb(239,68,68)] bg-opacity-10 rounded-full mx-auto flex items-center justify-center">
          <svg 
            className="w-8 h-8 text-[rgb(239,68,68)]" 
            fill="none" 
            stroke="currentColor" 
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path 
              strokeLinecap="round" 
              strokeLinejoin="round" 
              strokeWidth={2} 
              d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" 
            />
          </svg>
        </div>
        <div className="space-y-2">
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
            Authentication Error
          </h2>
          <p className="text-sm text-[rgb(15,23,42)] opacity-70 font-[Inter,system-ui,sans-serif]">
            {message}
          </p>
        </div>
      </div>
      <button
        onClick={onRetry}
        className="w-full h-12 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium font-[Inter,system-ui,sans-serif] hover:bg-[rgb(34,139,34)]/90 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors touch-manipulation"
        aria-label="Retry authentication"
      >
        Try Again
      </button>
    </div>
  </div>
);

const UnauthorizedState = ({ 
  redirectTo 
}: { 
  redirectTo: string; 
}) => {
  const router = useRouter();

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
      <div className="w-full max-w-md text-center space-y-6">
        <div className="space-y-4">
          <div className="w-16 h-16 bg-[rgb(245,158,11)] bg-opacity-10 rounded-full mx-auto flex items-center justify-center">
            <svg 
              className="w-8 h-8 text-[rgb(245,158,11)]" 
              fill="none" 
              stroke="currentColor" 
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path 
                strokeLinecap="round" 
                strokeLinejoin="round" 
                strokeWidth={2} 
                d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" 
              />
            </svg>
          </div>
          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
              Access Required
            </h2>
            <p className="text-sm text-[rgb(15,23,42)] opacity-70 font-[Inter,system-ui,sans-serif]">
              Please sign in to access this feature and start planning your off-road adventures.
            </p>
          </div>
        </div>
        <button
          onClick={() => router.push(redirectTo)}
          className="w-full h-12 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium font-[Inter,system-ui,sans-serif] hover:bg-[rgb(34,139,34)]/90 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors touch-manipulation"
          aria-label="Sign in to continue"
        >
          Sign In
        </button>
      </div>
    </div>
  );
};

export default function AuthMiddleware({
  children,
  requireAuth = true,
  redirectTo = '/auth/signin',
  allowedRoles = []
}: AuthMiddlewareProps) {
  const [authState, setAuthState] = useState<AuthState>({
    user: null,
    loading: true,
    error: null
  });

  const router = useRouter();
  const pathname = usePathname();
  const supabase = createClientComponentClient();

  const checkAuth = async () => {
    try {
      setAuthState(prev => ({ ...prev, loading: true, error: null }));

      const { data: { session }, error: sessionError } = await supabase.auth.getSession();

      if (sessionError) {
        throw new Error(sessionError.message);
      }

      if (!session?.user && requireAuth) {
        setAuthState({
          user: null,
          loading: false,
          error: null
        });
        return;
      }

      // Check user roles if specified
      if (session?.user && allowedRoles.length > 0) {
        const { data: profile, error: profileError } = await supabase
          .from('profiles')
          .select('role')
          .eq('id', session.user.id)
          .single();

        if (profileError || !profile?.role || !allowedRoles.includes(profile.role)) {
          throw new Error('Insufficient permissions to access this resource');
        }
      }

      setAuthState({
        user: session?.user || null,
        loading: false,
        error: null
      });

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Authentication failed';
      setAuthState({
        user: null,
        loading: false,
        error: errorMessage
      });
    }
  };

  useEffect(() => {
    checkAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (event === 'SIGNED_OUT' || event === 'TOKEN_REFRESHED') {
          await checkAuth();
        } else if (event === 'SIGNED_IN') {
          setAuthState({
            user: session?.user || null,
            loading: false,
            error: null
          });
        }
      }
    );

    return () => {
      subscription.unsubscribe();
    };
  }, [pathname]);

  // Handle loading state
  if (authState.loading) {
    return <LoadingSkeleton />;
  }

  // Handle error state
  if (authState.error) {
    return (
      <ErrorState 
        message={authState.error} 
        onRetry={checkAuth}
      />
    );
  }

  // Handle unauthorized access
  if (requireAuth && !authState.user) {
    return <UnauthorizedState redirectTo={redirectTo} />;
  }

  // Handle insufficient permissions
  if (authState.user && allowedRoles.length > 0) {
    // This check is already done in checkAuth, but keeping for safety
    return children;
  }

  // Render protected content
  return <>{children}</>;
}

