'use client'

import React, { useState, useEffect } from 'react'
import { Menu, X, MapPin, Calendar, Users, MessageCircle, ChefHat, Settings } from 'lucide-react'
import { cn } from '@/lib/utils'

interface NavigationItem {
  id: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  href: string
  badge?: number
}

interface AppLayoutProps {
  children: React.ReactNode
  currentPath?: string
}

const AppLayout: React.FC<AppLayoutProps> = ({ children, currentPath = '/' }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isOnline, setIsOnline] = useState(true)

  const navigationItems: NavigationItem[] = [
    { id: 'trips', label: 'Trips', icon: MapPin, href: '/trips' },
    { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
    { id: 'group', label: 'Group', icon: Users, href: '/group' },
    { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat', badge: 3 },
    { id: 'meals', label: 'Meals', icon: ChefHat, href: '/meals' },
    { id: 'settings', label: 'Settings', icon: Settings, href: '/settings' }
  ]

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const handleNavigation = (href: string) => {
    setIsMobileMenuOpen(false)
    // Navigation will be handled by Next.js router
    window.location.href = href
  }

  const handleKeyDown = (event: React.KeyboardEvent, action: () => void) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      action()
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Offline Indicator */}
      {!isOnline && (
        <div 
          className="bg-[rgb(239,68,68)] text-[rgb(255,255,255)] px-4 py-2 text-center text-sm font-medium"
          role="alert"
          aria-live="polite"
        >
          You're offline. Some features may be limited.
        </div>
      )}

      {/* Top Navigation */}
      <header className="bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] sticky top-0 z-50 shadow-sm">
        <div className="flex items-center justify-between px-4 py-3">
          {/* Logo */}
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-lg flex items-center justify-center">
              <MapPin className="w-5 h-5 text-[rgb(255,255,255)]" />
            </div>
            <h1 className="text-lg font-bold text-[rgb(15,23,42)]">TrailPlan</h1>
          </div>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex items-center gap-1" role="navigation" aria-label="Main navigation">
            {navigationItems.map((item) => {
              const Icon = item.icon
              const isActive = currentPath === item.href

              return (
                <button
                  key={item.id}
                  onClick={() => handleNavigation(item.href)}
                  onKeyDown={(e) => handleKeyDown(e, () => handleNavigation(item.href))}
                  className={cn(
                    "flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors",
                    "focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2",
                    "min-h-[44px] min-w-[44px]",
                    isActive
                      ? "bg-[rgb(34,139,34)] text-[rgb(255,255,255)]"
                      : "text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]"
                  )}
                  aria-current={isActive ? 'page' : undefined}
                  aria-label={`Navigate to ${item.label}${item.badge ? ` (${item.badge} notifications)` : ''}`}
                >
                  <Icon className="w-4 h-4" />
                  <span className="hidden lg:inline">{item.label}</span>
                  {item.badge && (
                    <span 
                      className="bg-[rgb(239,68,68)] text-[rgb(255,255,255)] text-xs rounded-full px-1.5 py-0.5 min-w-[18px] text-center"
                      aria-label={`${item.badge} notifications`}
                    >
                      {item.badge}
                    </span>
                  )}
                </button>
              )
            })}
          </nav>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            onKeyDown={(e) => handleKeyDown(e, () => setIsMobileMenuOpen(!isMobileMenuOpen))}
            className={cn(
              "md:hidden p-2 rounded-lg text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]",
              "focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2",
              "min-h-[44px] min-w-[44px] flex items-center justify-center"
            )}
            aria-expanded={isMobileMenuOpen}
            aria-controls="mobile-menu"
            aria-label={isMobileMenuOpen ? 'Close menu' : 'Open menu'}
          >
            {isMobileMenuOpen ? (
              <X className="w-5 h-5" />
            ) : (
              <Menu className="w-5 h-5" />
            )}
          </button>
        </div>

        {/* Mobile Navigation Menu */}
        {isMobileMenuOpen && (
          <div 
            id="mobile-menu"
            className="md:hidden border-t border-[rgb(226,232,240)] bg-[rgb(255,255,255)]"
            role="navigation"
            aria-label="Mobile navigation"
          >
            <div className="px-4 py-2 space-y-1">
              {navigationItems.map((item) => {
                const Icon = item.icon
                const isActive = currentPath === item.href

                return (
                  <button
                    key={item.id}
                    onClick={() => handleNavigation(item.href)}
                    onKeyDown={(e) => handleKeyDown(e, () => handleNavigation(item.href))}
                    className={cn(
                      "w-full flex items-center gap-3 px-3 py-3 rounded-lg text-sm font-medium transition-colors",
                      "focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2",
                      "min-h-[44px]",
                      isActive
                        ? "bg-[rgb(34,139,34)] text-[rgb(255,255,255)]"
                        : "text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]"
                    )}
                    aria-current={isActive ? 'page' : undefined}
                    aria-label={`Navigate to ${item.label}${item.badge ? ` (${item.badge} notifications)` : ''}`}
                  >
                    <Icon className="w-5 h-5" />
                    <span className="flex-1 text-left">{item.label}</span>
                    {item.badge && (
                      <span 
                        className="bg-[rgb(239,68,68)] text-[rgb(255,255,255)] text-xs rounded-full px-2 py-1 min-w-[20px] text-center"
                        aria-label={`${item.badge} notifications`}
                      >
                        {item.badge}
                      </span>
                    )}
                  </button>
                )
              })}
            </div>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main 
        className="flex-1 min-h-[calc(100vh-73px)]"
        role="main"
        aria-label="Main content"
      >
        {children}
      </main>

      {/* Bottom Navigation for Mobile */}
      <nav 
        className="md:hidden fixed bottom-0 left-0 right-0 bg-[rgb(255,255,255)] border-t border-[rgb(226,232,240)] z-40"
        role="navigation"
        aria-label="Bottom navigation"
      >
        <div className="flex items-center justify-around px-2 py-2">
          {navigationItems.slice(0, 5).map((item) => {
            const Icon = item.icon
            const isActive = currentPath === item.href

            return (
              <button
                key={item.id}
                onClick={() => handleNavigation(item.href)}
                onKeyDown={(e) => handleKeyDown(e, () => handleNavigation(item.href))}
                className={cn(
                  "flex flex-col items-center gap-1 px-2 py-2 rounded-lg text-xs font-medium transition-colors",
                  "focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2",
                  "min-h-[44px] min-w-[44px] relative",
                  isActive
                    ? "text-[rgb(34,139,34)]"
                    : "text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)]"
                )}
                aria-current={isActive ? 'page' : undefined}
                aria-label={`Navigate to ${item.label}${item.badge ? ` (${item.badge} notifications)` : ''}`}
              >
                <Icon className="w-5 h-5" />
                <span className="truncate max-w-[60px]">{item.label}</span>
                {item.badge && (
                  <span 
                    className="absolute -top-1 -right-1 bg-[rgb(239,68,68)] text-[rgb(255,255,255)] text-xs rounded-full px-1.5 py-0.5 min-w-[18px] text-center"
                    aria-label={`${item.badge} notifications`}
                  >
                    {item.badge}
                  </span>
                )}
              </button>
            )
          })}
        </div>
      </nav>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div
          className="md:hidden fixed inset-0 bg-black bg-opacity-50 z-30"
          onClick={() => setIsMobileMenuOpen(false)}
          onKeyDown={(e) => handleKeyDown(e, () => setIsMobileMenuOpen(false))}
          role="button"
          tabIndex={0}
          aria-label="Close mobile menu"
        />
      )}
    </div>
  )
}

export default AppLayout

