'use client';

import { useState, useEffect } from 'react';
import { z } from 'zod';

// TypeScript interfaces for Trip data model
export interface TripLocation {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  description?: string;
  difficulty?: 'easy' | 'moderate' | 'difficult' | 'extreme';
  terrain?: string[];
  amenities?: string[];
}

export interface TripMember {
  id: string;
  name: string;
  email: string;
  phone?: string;
  avatar?: string;
  role: 'organizer' | 'member';
  rsvpStatus: 'pending' | 'accepted' | 'declined';
  joinedAt: Date;
}

export interface TripTask {
  id: string;
  title: string;
  description?: string;
  assignedTo: string[]; // Member IDs
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other';
  dueDate?: Date;
  completed: boolean;
  priority: 'low' | 'medium' | 'high';
  createdAt: Date;
  updatedAt: Date;
}

export interface TripMeal {
  id: string;
  name: string;
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  scheduledFor: Date;
  description?: string;
  ingredients?: string[];
  servings: number;
  prepTime?: number; // minutes
  cookingMethod?: string;
  assignedChef?: string; // Member ID
  dietaryRestrictions?: string[];
}

export interface WeatherForecast {
  date: Date;
  temperature: {
    high: number;
    low: number;
  };
  condition: string;
  precipitation: number;
  windSpeed: number;
  humidity: number;
  uvIndex: number;
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  content: string;
  timestamp: Date;
  type: 'text' | 'image' | 'location' | 'system';
  attachments?: {
    url: string;
    type: string;
    name: string;
  }[];
}

export interface Trip {
  id: string;
  title: string;
  description?: string;
  startDate: Date;
  endDate: Date;
  location: TripLocation;
  organizer: string; // Member ID
  members: TripMember[];
  tasks: TripTask[];
  meals: TripMeal[];
  weather?: WeatherForecast[];
  chatMessages: ChatMessage[];
  status: 'planning' | 'confirmed' | 'in-progress' | 'completed' | 'cancelled';
  maxParticipants?: number;
  difficulty: 'easy' | 'moderate' | 'difficult' | 'extreme';
  requiredEquipment?: string[];
  emergencyContacts?: {
    name: string;
    phone: string;
    relationship: string;
  }[];
  meetingPoint?: {
    name: string;
    address: string;
    coordinates: {
      latitude: number;
      longitude: number;
    };
    time: Date;
  };
  budget?: {
    total: number;
    perPerson: number;
    breakdown: {
      category: string;
      amount: number;
    }[];
  };
  rules?: string[];
  cancellationPolicy?: string;
  createdAt: Date;
  updatedAt: Date;
}

// Validation schemas
export const TripLocationSchema = z.object({
  id: z.string(),
  name: z.string().min(1, 'Location name is required'),
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  description: z.string().optional(),
  difficulty: z.enum(['easy', 'moderate', 'difficult', 'extreme']).optional(),
  terrain: z.array(z.string()).optional(),
  amenities: z.array(z.string()).optional(),
});

export const TripMemberSchema = z.object({
  id: z.string(),
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Valid email is required'),
  phone: z.string().optional(),
  avatar: z.string().url().optional(),
  role: z.enum(['organizer', 'member']),
  rsvpStatus: z.enum(['pending', 'accepted', 'declined']),
  joinedAt: z.date(),
});

export const TripTaskSchema = z.object({
  id: z.string(),
  title: z.string().min(1, 'Task title is required'),
  description: z.string().optional(),
  assignedTo: z.array(z.string()),
  category: z.enum(['food', 'equipment', 'logistics', 'safety', 'other']),
  dueDate: z.date().optional(),
  completed: z.boolean(),
  priority: z.enum(['low', 'medium', 'high']),
  createdAt: z.date(),
  updatedAt: z.date(),
});

export const TripMealSchema = z.object({
  id: z.string(),
  name: z.string().min(1, 'Meal name is required'),
  type: z.enum(['breakfast', 'lunch', 'dinner', 'snack']),
  scheduledFor: z.date(),
  description: z.string().optional(),
  ingredients: z.array(z.string()).optional(),
  servings: z.number().min(1),
  prepTime: z.number().min(0).optional(),
  cookingMethod: z.string().optional(),
  assignedChef: z.string().optional(),
  dietaryRestrictions: z.array(z.string()).optional(),
});

export const TripSchema = z.object({
  id: z.string(),
  title: z.string().min(1, 'Trip title is required'),
  description: z.string().optional(),
  startDate: z.date(),
  endDate: z.date(),
  location: TripLocationSchema,
  organizer: z.string(),
  members: z.array(TripMemberSchema),
  tasks: z.array(TripTaskSchema),
  meals: z.array(TripMealSchema),
  status: z.enum(['planning', 'confirmed', 'in-progress', 'completed', 'cancelled']),
  maxParticipants: z.number().min(1).optional(),
  difficulty: z.enum(['easy', 'moderate', 'difficult', 'extreme']),
  requiredEquipment: z.array(z.string()).optional(),
  meetingPoint: z.object({
    name: z.string(),
    address: z.string(),
    coordinates: z.object({
      latitude: z.number(),
      longitude: z.number(),
    }),
    time: z.date(),
  }).optional(),
  budget: z.object({
    total: z.number(),
    perPerson: z.number(),
    breakdown: z.array(z.object({
      category: z.string(),
      amount: z.number(),
    })),
  }).optional(),
  rules: z.array(z.string()).optional(),
  cancellationPolicy: z.string().optional(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

// Trip Model class with business logic
export class TripModel {
  private trip: Trip;

  constructor(trip: Trip) {
    this.trip = { ...trip };
  }

  // Getters
  get data(): Trip {
    return { ...this.trip };
  }

  get id(): string {
    return this.trip.id;
  }

  get title(): string {
    return this.trip.title;
  }

  get status(): Trip['status'] {
    return this.trip.status;
  }

  get duration(): number {
    return Math.ceil((this.trip.endDate.getTime() - this.trip.startDate.getTime()) / (1000 * 60 * 60 * 24));
  }

  get memberCount(): number {
    return this.trip.members.length;
  }

  get acceptedMembers(): TripMember[] {
    return this.trip.members.filter(member => member.rsvpStatus === 'accepted');
  }

  get pendingMembers(): TripMember[] {
    return this.trip.members.filter(member => member.rsvpStatus === 'pending');
  }

  get completedTasks(): TripTask[] {
    return this.trip.tasks.filter(task => task.completed);
  }

  get pendingTasks(): TripTask[] {
    return this.trip.tasks.filter(task => !task.completed);
  }

  get overdueTasks(): TripTask[] {
    const now = new Date();
    return this.trip.tasks.filter(task => 
      !task.completed && 
      task.dueDate && 
      task.dueDate < now
    );
  }

  get upcomingMeals(): TripMeal[] {
    const now = new Date();
    return this.trip.meals
      .filter(meal => meal.scheduledFor > now)
      .sort((a, b) => a.scheduledFor.getTime() - b.scheduledFor.getTime());
  }

  get isActive(): boolean {
    const now = new Date();
    return this.trip.startDate <= now && this.trip.endDate >= now;
  }

  get isUpcoming(): boolean {
    const now = new Date();
    return this.trip.startDate > now;
  }

  get isCompleted(): boolean {
    const now = new Date();
    return this.trip.endDate < now || this.trip.status === 'completed';
  }

  // Member management
  addMember(member: Omit<TripMember, 'id' | 'joinedAt'>): TripMember {
    const newMember: TripMember = {
      ...member,
      id: crypto.randomUUID(),
      joinedAt: new Date(),
    };

    this.trip.members.push(newMember);
    this.trip.updatedAt = new Date();

    return newMember;
  }

  removeMember(memberId: string): boolean {
    const initialLength = this.trip.members.length;
    this.trip.members = this.trip.members.filter(member => member.id !== memberId);

    if (this.trip.members.length < initialLength) {
      // Remove member from all task assignments
      this.trip.tasks.forEach(task => {
        task.assignedTo = task.assignedTo.filter(id => id !== memberId);
      });

      // Remove member as chef from meals
      this.trip.meals.forEach(meal => {
        if (meal.assignedChef === memberId) {
          meal.assignedChef = undefined;
        }
      });

      this.trip.updatedAt = new Date();
      return true;
    }

    return false;
  }

  updateMemberRSVP(memberId: string, status: TripMember['rsvpStatus']): boolean {
    const member = this.trip.members.find(m => m.id === memberId);
    if (member) {
      member.rsvpStatus = status;
      this.trip.updatedAt = new Date();
      return true;
    }
    return false;
  }

  getMember(memberId: string): TripMember | undefined {
    return this.trip.members.find(member => member.id === memberId);
  }

  // Task management
  addTask(task: Omit<TripTask, 'id' | 'createdAt' | 'updatedAt'>): TripTask {
    const newTask: TripTask = {
      ...task,
      id: crypto.randomUUID(),
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    this.trip.tasks.push(newTask);
    this.trip.updatedAt = new Date();

    return newTask;
  }

  updateTask(taskId: string, updates: Partial<Omit<TripTask, 'id' | 'createdAt'>>): boolean {
    const task = this.trip.tasks.find(t => t.id === taskId);
    if (task) {
      Object.assign(task, updates, { updatedAt: new Date() });
      this.trip.updatedAt = new Date();
      return true;
    }
    return false;
  }

  completeTask(taskId: string): boolean {
    return this.updateTask(taskId, { completed: true });
  }

  deleteTask(taskId: string): boolean {
    const initialLength = this.trip.tasks.length;
    this.trip.tasks = this.trip.tasks.filter(task => task.id !== taskId);

    if (this.trip.tasks.length < initialLength) {
      this.trip.updatedAt = new Date();
      return true;
    }

    return false;
  }

  getTasksByMember(memberId: string): TripTask[] {
    return this.trip.tasks.filter(task => task.assignedTo.includes(memberId));
  }

  getTasksByCategory(category: TripTask['category']): TripTask[] {
    return this.trip.tasks.filter(task => task.category === category);
  }

  // Meal management
  addMeal(meal: Omit<TripMeal, 'id'>): TripMeal {
    const newMeal: TripMeal = {
      ...meal,
      id: crypto.randomUUID(),
    };

    this.trip.meals.push(newMeal);
    this.trip.updatedAt = new Date();

    return newMeal;
  }

  updateMeal(mealId: string, updates: Partial<Omit<TripMeal, 'id'>>): boolean {
    const meal = this.trip.meals.find(m => m.id === mealId);
    if (meal) {
      Object.assign(meal, updates);
      this.trip.updatedAt = new Date();
      return true;
    }
    return false;
  }

  deleteMeal(mealId: string): boolean {
    const initialLength = this.trip.meals.length;
    this.trip.meals = this.trip.meals.filter(meal => meal.id !== mealId);

    if (this.trip.meals.length < initialLength) {
      this.trip.updatedAt = new Date();
      return true;
    }

    return false;
  }

  getMealsByDay(date: Date): TripMeal[] {
    const startOfDay = new Date(date);
    startOfDay.setHours(0, 0, 0, 0);

    const endOfDay = new Date(date);
    endOfDay.setHours(23, 59, 59, 999);

    return this.trip.meals.filter(meal => 
      meal.scheduledFor >= startOfDay && meal.scheduledFor <= endOfDay
    ).sort((a, b) => a.scheduledFor.getTime() - b.scheduledFor.getTime());
  }

  getMealsByType(type: TripMeal['type']): TripMeal[] {
    return this.trip.meals.filter(meal => meal.type === type);
  }

  // Chat management
  addChatMessage(message: Omit<ChatMessage, 'id' | 'timestamp'>): ChatMessage {
    const newMessage: ChatMessage = {
      ...message,
      id: crypto.randomUUID(),
      timestamp: new Date(),
    };

    this.trip.chatMessages.push(newMessage);
    this.trip.updatedAt = new Date();

    return newMessage;
  }

  getChatMessages(limit?: number): ChatMessage[] {
    const messages = [...this.trip.chatMessages].sort((a, b) => 
      b.timestamp.getTime() - a.timestamp.getTime()
    );

    return limit ? messages.slice(0, limit) : messages;
  }

  // Weather management
  updateWeather(forecasts: WeatherForecast[]): void {
    this.trip.weather = forecasts;
    this.trip.updatedAt = new Date();
  }

  getWeatherForDate(date: Date): WeatherForecast | undefined {
    if (!this.trip.weather) return undefined;

    return this.trip.weather.find(forecast => {
      const forecastDate = new Date(forecast.date);
      return forecastDate.toDateString() === date.toDateString();
    });
  }

  // Trip status management
  updateStatus(status: Trip['status']): void {
    this.trip.status = status;
    this.trip.updatedAt = new Date();
  }

  canStart(): boolean {
    const now = new Date();
    return this.trip.startDate <= now && this.trip.status === 'confirmed';
  }

  canComplete(): boolean {
    const now = new Date();
    return this.trip.endDate <= now && this.trip.status === 'in-progress';
  }

  // Validation
  validate(): { isValid: boolean; errors: string[] } {
    try {
      TripSchema.parse(this.trip);
      return { isValid: true, errors: [] };
    } catch (error) {
      if (error instanceof z.ZodError) {
        return {
          isValid: false,
          errors: error.errors.map(err => `${err.path.join('.')}: ${err.message}`)
        };
      }
      return { isValid: false, errors: ['Unknown validation error'] };
    }
  }

  // Serialization
  toJSON(): string {
    return JSON.stringify(this.trip, null, 2);
  }

  static fromJSON(json: string): TripModel {
    const data = JSON.parse(json);

    // Convert date strings back to Date objects
    data.startDate = new Date(data.startDate);
    data.endDate = new Date(data.endDate);
    data.createdAt = new Date(data.createdAt);
    data.updatedAt = new Date(data.updatedAt);

    data.members.forEach((member: any) => {
      member.joinedAt = new Date(member.joinedAt);
    });

    data.tasks.forEach((task: any) => {
      if (task.dueDate) task.dueDate = new Date(task.dueDate);
      task.createdAt = new Date(task.createdAt);
      task.updatedAt = new Date(task.updatedAt);
    });

    data.meals.forEach((meal: any) => {
      meal.scheduledFor = new Date(meal.scheduledFor);
    });

    if (data.weather) {
      data.weather.forEach((forecast: any) => {
        forecast.date = new Date(forecast.date);
      });
    }

    data.chatMessages.forEach((message: any) => {
      message.timestamp = new Date(message.timestamp);
    });

    if (data.meetingPoint?.time) {
      data.meetingPoint.time = new Date(data.meetingPoint.time);
    }

    return new TripModel(data);
  }

  // Clone
  clone(): TripModel {
    return TripModel.fromJSON(this.toJSON());
  }
}

// Factory function for creating new trips
export function createTrip(
  title: string,
  location: TripLocation,
  startDate: Date,
  endDate: Date,
  organizer: Omit<TripMember, 'id' | 'joinedAt' | 'role' | 'rsvpStatus'>
): TripModel {
  const organizerMember: TripMember = {
    ...organizer,
    id: crypto.randomUUID(),
    role: 'organizer',
    rsvpStatus: 'accepted',
    joinedAt: new Date(),
  };

  const trip: Trip = {
    id: crypto.randomUUID(),
    title,
    startDate,
    endDate,
    location,
    organizer: organizerMember.id,
    members: [organizerMember],
    tasks: [],
    meals: [],
    chatMessages: [],
    status: 'planning',
    difficulty: 'moderate',
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  return new TripModel(trip);
}

