// TypeScript Interfaces
export interface GroupMember {
  id: string;
  name: string;
  email: string;
  phone?: string;
  avatar?: string;
  role: 'organizer' | 'member';
  status: 'active' | 'inactive' | 'pending';
  joinedAt: Date;
  lastActive?: Date;
  preferences: {
    notifications: boolean;
    emailUpdates: boolean;
    smsUpdates: boolean;
  };
  skills: string[];
  emergencyContact?: {
    name: string;
    phone: string;
    relationship: string;
  };
}

export interface Group {
  id: string;
  name: string;
  description: string;
  avatar?: string;
  createdAt: Date;
  updatedAt: Date;
  members: GroupMember[];
  settings: {
    isPrivate: boolean;
    requireApproval: boolean;
    allowMemberInvites: boolean;
    maxMembers: number;
  };
  stats: {
    totalTrips: number;
    upcomingTrips: number;
    totalMembers: number;
    activeMembers: number;
  };
}

export interface GroupInvite {
  id: string;
  groupId: string;
  invitedBy: string;
  invitedEmail: string;
  status: 'pending' | 'accepted' | 'declined' | 'expired';
  createdAt: Date;
  expiresAt: Date;
  message?: string;
}

interface GroupModelProps {
  groups: Group[];
  currentUserId: string;
  onCreateGroup: (group: Omit<Group, 'id' | 'createdAt' | 'updatedAt' | 'stats'>) => Promise<void>;
  onUpdateGroup: (groupId: string, updates: Partial<Group>) => Promise<void>;
  onDeleteGroup: (groupId: string) => Promise<void>;
  onInviteMember: (groupId: string, email: string, message?: string) => Promise<void>;
  onRemoveMember: (groupId: string, memberId: string) => Promise<void>;
  onUpdateMemberRole: (groupId: string, memberId: string, role: GroupMember['role']) => Promise<void>;
  onJoinGroup: (inviteId: string) => Promise<void>;
  onLeaveGroup: (groupId: string) => Promise<void>;
}

export default function GroupModel({
  groups,
  currentUserId,
  onCreateGroup,
  onUpdateGroup,
  onDeleteGroup,
  onInviteMember,
  onRemoveMember,
  onUpdateMemberRole,
