      {/* Tables */}
      <Tabs value={selectedTable} onValueChange={setSelectedTable} className="w-full">
        <TabsList className="grid w-full grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-1 h-auto p-1">
          {schema.tables.map((table) => (
