                                  <Link className="h-3 w-3" style={{ color: 'rgb(34, 139, 34)' }} aria-label="Foreign key" />
                                )}
                              </div>
                              <span className="font-medium truncate">{column.name}</span>
                            </div>
                            <div className="flex flex-wrap items-center gap-2">
                              <Badge className={`text-xs ${getTypeColor(column.type)}`}>
