'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, Smile, MoreVertical, ArrowLeft } from 'lucide-react';

interface User {
  id: string;
  name: string;
  avatar?: string;
  isOnline: boolean;
}

interface Message {
  id: string;
  userId: string;
  content: string;
  timestamp: Date;
  type: 'text' | 'image' | 'file';
  attachmentUrl?: string;
  attachmentName?: string;
}

interface ChatPageProps {
  tripId?: string;
  currentUserId: string;
}

const ChatPage: React.FC<ChatPageProps> = ({ tripId, currentUserId }) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      userId: 'user1',
      content: 'Hey everyone! Just confirmed the campsite reservation for this weekend 🏕️',
      timestamp: new Date(Date.now() - 3600000),
      type: 'text'
    },
    {
      id: '2',
      userId: 'user2',
      content: 'Awesome! Should I bring the portable grill?',
      timestamp: new Date(Date.now() - 3000000),
      type: 'text'
    },
    {
      id: '3',
      userId: currentUserId,
      content: 'Yes please! And don\'t forget the propane tank',
      timestamp: new Date(Date.now() - 2400000),
      type: 'text'
    },
    {
      id: '4',
      userId: 'user3',
      content: 'Weather looks perfect for the weekend. Sunny with highs in the 70s ☀️',
      timestamp: new Date(Date.now() - 1800000),
      type: 'text'
    }
  ]);

  const [newMessage, setNewMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const users: Record<string, User> = {
    'user1': { id: 'user1', name: 'Sarah Chen', isOnline: true },
    'user2': { id: 'user2', name: 'Mike Rodriguez', isOnline: true },
    'user3': { id: 'user3', name: 'Alex Thompson', isOnline: false },
    [currentUserId]: { id: currentUserId, name: 'You', isOnline: true }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = () => {
    if (!newMessage.trim()) return;

    const message: Message = {
      id: Date.now().toString(),
      userId: currentUserId,
      content: newMessage.trim(),
      timestamp: new Date(),
      type: 'text'
    };

    setMessages(prev => [...prev, message]);
    setNewMessage('');

    if (inputRef.current) {
      inputRef.current.style.height = 'auto';
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewMessage(e.target.value);

    // Auto-resize textarea
    const textarea = e.target;
    textarea.style.height = 'auto';
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
  };

  const formatTime = (date: Date) => {
    const now = new Date();
    const diffInHours = (now.getTime() - date.getTime()) / (1000 * 60 * 60);

    if (diffInHours < 24) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else {
      return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
    }
  };

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').toUpperCase();
  };

  return (
    <div className="flex flex-col h-screen bg-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-white">
        <div className="flex items-center gap-3">
          <button
            className="lg:hidden p-2 -ml-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors"
            aria-label="Go back"
          >
            <ArrowLeft className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>
          <div>
            <h1 className="text-lg font-semibold text-[rgb(15,23,42)]">
              Trip Chat
            </h1>
            <p className="text-sm text-gray-500">
              {Object.values(users).filter(u => u.isOnline).length} online
            </p>
          </div>
        </div>
        <button
          className="p-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors"
          aria-label="More options"
        >
          <MoreVertical className="w-5 h-5 text-[rgb(15,23,42)]" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => {
          const user = users[message.userId];
          const isCurrentUser = message.userId === currentUserId;
          const showAvatar = index === 0 || messages[index - 1].userId !== message.userId;

          return (
            <div
              key={message.id}
              className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : ''}`}
            >
              {/* Avatar */}
              <div className={`flex-shrink-0 ${showAvatar ? '' : 'invisible'}`}>
                {user?.avatar ? (
                  <img
                    src={user.avatar}
                    alt={user.name}
                    className="w-8 h-8 rounded-full"
                  />
                ) : (
                  <div className="w-8 h-8 rounded-full bg-[rgb(34,139,34)] flex items-center justify-center">
                    <span className="text-xs font-medium text-white">
                      {getInitials(user?.name || 'U')}
                    </span>
                  </div>
                )}
              </div>

              {/* Message Content */}
              <div className={`flex-1 max-w-xs sm:max-w-sm md:max-w-md ${isCurrentUser ? 'text-right' : ''}`}>
                {showAvatar && !isCurrentUser && (
                  <div className="text-xs font-medium text-[rgb(15,23,42)] mb-1">
                    {user?.name}
                  </div>
                )}

                <div
                  className={`inline-block px-4 py-2 rounded-2xl ${
                    isCurrentUser
                      ? 'bg-[rgb(34,139,34)] text-white rounded-br-md'
                      : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-bl-md'
                  }`}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">
                    {message.content}
                  </p>
                </div>

                <div className={`text-xs text-gray-500 mt-1 ${isCurrentUser ? 'text-right' : ''}`}>
                  {formatTime(message.timestamp)}
                </div>
              </div>
            </div>
          );
        })}

        {isTyping && (
          <div className="flex gap-3">
            <div className="w-8 h-8 rounded-full bg-gray-300 animate-pulse" />
            <div className="bg-[rgb(241,245,249)] rounded-2xl rounded-bl-md px-4 py-2">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="border-t border-[rgb(226,232,240)] bg-white p-4">
        <div className="flex items-end gap-3">
          <button
            className="p-2 text-gray-500 hover:text-[rgb(15,23,42)] transition-colors"
            aria-label="Attach file"
          >
            <Paperclip className="w-5 h-5" />
          </button>

          <div className="flex-1 relative">
            <textarea
              ref={inputRef}
              value={newMessage}
              onChange={handleInputChange}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 pr-12 border border-[rgb(226,232,240)] rounded-2xl resize-none focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-sm leading-relaxed"
              style={{ minHeight: '48px', maxHeight: '120px' }}
              rows={1}
            />
            <button
              className="absolute right-3 bottom-3 p-1 text-gray-500 hover:text-[rgb(15,23,42)] transition-colors"
              aria-label="Add emoji"
            >
              <Smile className="w-4 h-4" />
            </button>
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-white rounded-full hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatPage;

