'use client';

import React from 'react';
export interface TaskModel {
  id: string;
  title: string;
  description?: string;
  category: TaskCategory;
  priority: TaskPriority;
  status: TaskStatus;
  assignedTo?: string[];
  dueDate?: Date;
  estimatedDuration?: number; // in minutes
  dependencies?: string[]; // task IDs
  tripId: string;
  createdBy: string;
  createdAt: Date;
  updatedAt: Date;
  completedAt?: Date;
  completedBy?: string;
  notes?: TaskNote[];
  attachments?: TaskAttachment[];
  location?: TaskLocation;
  recurring?: TaskRecurrence;
}

export interface TaskNote {
  id: string;
  content: string;
  authorId: string;
  createdAt: Date;
}

export interface TaskAttachment {
  id: string;
  name: string;
  url: string;
  type: string;
  size: number;
  uploadedBy: string;
  uploadedAt: Date;
}

export interface TaskLocation {
  name?: string;
  coordinates?: {
    lat: number;
    lng: number;
  };
  address?: string;
}

export interface TaskRecurrence {
  pattern: 'daily' | 'weekly' | 'monthly';
  interval: number;
  endDate?: Date;
  occurrences?: number;
}

export type TaskCategory = 
  | 'setup'
  | 'meals'
  | 'safety'
  | 'navigation'
  | 'maintenance'
  | 'cleanup'
  | 'entertainment'
  | 'supplies'
  | 'emergency'
  | 'other';

export type TaskPriority = 'low' | 'medium' | 'high' | 'critical';

export type TaskStatus = 
  | 'pending'
  | 'in_progress'
  | 'completed'
  | 'cancelled'
  | 'blocked'
  | 'overdue';

export interface TaskFilter {
  status?: TaskStatus[];
  category?: TaskCategory[];
  priority?: TaskPriority[];
  assignedTo?: string[];
  dueDate?: {
    start?: Date;
    end?: Date;
  };
  search?: string;
}

export interface TaskSort {
  field: 'title' | 'dueDate' | 'priority' | 'status' | 'createdAt';
  direction: 'asc' | 'desc';
}

export interface TaskStats {
  total: number;
  completed: number;
  inProgress: number;
  overdue: number;
  byCategory: Record<TaskCategory, number>;
  byPriority: Record<TaskPriority, number>;
  completionRate: number;
}

export interface TaskTemplate {
  id: string;
  name: string;
  description?: string;
  category: TaskCategory;
  priority: TaskPriority;
  estimatedDuration?: number;
  dependencies?: string[];
  isDefault: boolean;
  createdBy: string;
  createdAt: Date;
}

export interface TaskAssignment {
  taskId: string;
  userId: string;
  assignedBy: string;
  assignedAt: Date;
  acceptedAt?: Date;
  declinedAt?: Date;
  reason?: string;
}

export interface TaskComment {
  id: string;
  taskId: string;
  content: string;
  authorId: string;
  createdAt: Date;
  updatedAt?: Date;
  parentId?: string; // for replies
  mentions?: string[]; // user IDs
}

export interface TaskProgress {
  taskId: string;
  percentage: number;
  milestones?: TaskMilestone[];
  lastUpdated: Date;
  updatedBy: string;
}

export interface TaskMilestone {
  id: string;
  title: string;
  completed: boolean;
  completedAt?: Date;
  order: number;
}

export interface TaskNotification {
  id: string;
  taskId: string;
  type: 'assigned' | 'due_soon' | 'overdue' | 'completed' | 'comment';
  recipientId: string;
  message: string;
  read: boolean;
  createdAt: Date;
}

export interface TaskHistory {
  id: string;
  taskId: string;
  action: 'created' | 'updated' | 'assigned' | 'completed' | 'cancelled';
  changes?: Record<string, { old: any; new: any }>;
  performedBy: string;
  performedAt: Date;
  description?: string;
}

export interface TaskDependency {
  id: string;
  dependentTaskId: string;
  prerequisiteTaskId: string;
  type: 'finish_to_start' | 'start_to_start' | 'finish_to_finish' | 'start_to_finish';
  lag?: number; // in minutes
}

export interface TaskResource {
  id: string;
  name: string;
  type: 'equipment' | 'vehicle' | 'person' | 'location' | 'material';
  available: boolean;
  capacity?: number;
  cost?: number;
  description?: string;
}

export interface TaskResourceAllocation {
  taskId: string;
  resourceId: string;
  quantity: number;
  startTime?: Date;
  endTime?: Date;
  allocatedBy: string;
  allocatedAt: Date;
}

export const TASK_CATEGORIES: Record<TaskCategory, { label: string; icon: string; color: string }> = {
  setup: { label: 'Setup', icon: '⛺', color: 'rgb(34, 139, 34)' },
  meals: { label: 'Meals', icon: '🍽️', color: 'rgb(245, 158, 11)' },
  safety: { label: 'Safety', icon: '🦺', color: 'rgb(239, 68, 68)' },
  navigation: { label: 'Navigation', icon: '🧭', color: 'rgb(59, 130, 246)' },
  maintenance: { label: 'Maintenance', icon: '🔧', color: 'rgb(107, 114, 128)' },
  cleanup: { label: 'Cleanup', icon: '🧹', color: 'rgb(34, 197, 94)' },
  entertainment: { label: 'Entertainment', icon: '🎵', color: 'rgb(168, 85, 247)' },
  supplies: { label: 'Supplies', icon: '📦', color: 'rgb(245, 158, 11)' },
  emergency: { label: 'Emergency', icon: '🚨', color: 'rgb(239, 68, 68)' },
  other: { label: 'Other', icon: '📝', color: 'rgb(107, 114, 128)' }
};

export const TASK_PRIORITIES: Record<TaskPriority, { label: string; color: string; weight: number }> = {
  low: { label: 'Low', color: 'rgb(107, 114, 128)', weight: 1 },
  medium: { label: 'Medium', color: 'rgb(245, 158, 11)', weight: 2 },
  high: { label: 'High', color: 'rgb(249, 115, 22)', weight: 3 },
  critical: { label: 'Critical', color: 'rgb(239, 68, 68)', weight: 4 }
};

export const TASK_STATUSES: Record<TaskStatus, { label: string; color: string }> = {
  pending: { label: 'Pending', color: 'rgb(107, 114, 128)' },
  in_progress: { label: 'In Progress', color: 'rgb(59, 130, 246)' },
  completed: { label: 'Completed', color: 'rgb(34, 197, 94)' },
  cancelled: { label: 'Cancelled', color: 'rgb(107, 114, 128)' },
  blocked: { label: 'Blocked', color: 'rgb(239, 68, 68)' },
  overdue: { label: 'Overdue', color: 'rgb(239, 68, 68)' }
};

export class TaskModelUtils {
  static isOverdue(task: TaskModel): boolean {
    if (!task.dueDate || task.status === 'completed' || task.status === 'cancelled') {
      return false;
    }
    return new Date() > task.dueDate;
  }

  static getDaysUntilDue(task: TaskModel): number | null {
    if (!task.dueDate) return null;
    const now = new Date();
    const due = new Date(task.dueDate);
    const diffTime = due.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  static canComplete(task: TaskModel, dependencies: TaskModel[]): boolean {
    if (task.status === 'completed' || task.status === 'cancelled') {
      return false;
    }

    if (!task.dependencies || task.dependencies.length === 0) {
      return true;
    }

    return task.dependencies.every(depId => {
      const dependency = dependencies.find(dep => dep.id === depId);
      return dependency?.status === 'completed';
    });
  }

  static calculateProgress(task: TaskModel): number {
    if (task.status === 'completed') return 100;
    if (task.status === 'cancelled') return 0;
    if (task.status === 'pending') return 0;
    if (task.status === 'in_progress') return 50;
    if (task.status === 'blocked') return 0;
    return 0;
  }

  static getEstimatedCompletionTime(tasks: TaskModel[]): Date | null {
    const incompleteTasks = tasks.filter(task => 
      task.status !== 'completed' && task.status !== 'cancelled'
    );

    if (incompleteTasks.length === 0) return null;

    const totalDuration = incompleteTasks.reduce((sum, task) => 
      sum + (task.estimatedDuration || 60), 0
    );

    const now = new Date();
    return new Date(now.getTime() + totalDuration * 60 * 1000);
  }

  static groupByCategory(tasks: TaskModel[]): Record<TaskCategory, TaskModel[]> {
    return tasks.reduce((groups, task) => {
      if (!groups[task.category]) {
        groups[task.category] = [];
      }
      groups[task.category].push(task);
      return groups;
    }, {} as Record<TaskCategory, TaskModel[]>);
  }

  static sortTasks(tasks: TaskModel[], sort: TaskSort): TaskModel[] {
    return [...tasks].sort((a, b) => {
      let comparison = 0;

      switch (sort.field) {
        case 'title':
          comparison = a.title.localeCompare(b.title);
          break;
        case 'dueDate':
          if (!a.dueDate && !b.dueDate) comparison = 0;
          else if (!a.dueDate) comparison = 1;
          else if (!b.dueDate) comparison = -1;
          else comparison = a.dueDate.getTime() - b.dueDate.getTime();
          break;
        case 'priority':
          comparison = TASK_PRIORITIES[b.priority].weight - TASK_PRIORITIES[a.priority].weight;
          break;
        case 'status':
          comparison = a.status.localeCompare(b.status);
          break;
        case 'createdAt':
          comparison = a.createdAt.getTime() - b.createdAt.getTime();
          break;
      }

      return sort.direction === 'desc' ? -comparison : comparison;
    });
  }

  static filterTasks(tasks: TaskModel[], filter: TaskFilter): TaskModel[] {
    return tasks.filter(task => {
      if (filter.status && !filter.status.includes(task.status)) {
        return false;
      }

      if (filter.category && !filter.category.includes(task.category)) {
        return false;
      }

      if (filter.priority && !filter.priority.includes(task.priority)) {
        return false;
      }

      if (filter.assignedTo && filter.assignedTo.length > 0) {
        if (!task.assignedTo || !task.assignedTo.some(id => filter.assignedTo!.includes(id))) {
          return false;
        }
      }

      if (filter.dueDate) {
        if (!task.dueDate) return false;
        if (filter.dueDate.start && task.dueDate < filter.dueDate.start) return false;
        if (filter.dueDate.end && task.dueDate > filter.dueDate.end) return false;
      }

      if (filter.search) {
        const searchLower = filter.search.toLowerCase();
        return task.title.toLowerCase().includes(searchLower) ||
               task.description?.toLowerCase().includes(searchLower);
      }

      return true;
    });
  }

  static generateStats(tasks: TaskModel[]): TaskStats {
    const total = tasks.length;
    const completed = tasks.filter(t => t.status === 'completed').length;
    const inProgress = tasks.filter(t => t.status === 'in_progress').length;
    const overdue = tasks.filter(t => this.isOverdue(t)).length;

    const byCategory = tasks.reduce((acc, task) => {
      acc[task.category] = (acc[task.category] || 0) + 1;
      return acc;
    }, {} as Record<TaskCategory, number>);

    const byPriority = tasks.reduce((acc, task) => {
      acc[task.priority] = (acc[task.priority] || 0) + 1;
      return acc;
    }, {} as Record<TaskPriority, number>);

    return {
      total,
      completed,
      inProgress,
      overdue,
      byCategory,
      byPriority,
      completionRate: total > 0 ? (completed / total) * 100 : 0
    };
  }
}

export default TaskModel;

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, Smile, MoreVertical, Users, MapPin } from 'lucide-react';

// TypeScript Interfaces
interface ChatMessage {
  id: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  content: string;
  timestamp: Date;
  type: 'text' | 'image' | 'location' | 'task' | 'system';
  metadata?: {
    taskId?: string;
    locationId?: string;
    imageUrl?: string;
  };
}

interface ChatUser {
  id: string;
  name: string;
  avatar?: string;
  isOnline: boolean;
  lastSeen?: Date;
}

interface ChatModelProps {
  tripId: string;
  currentUserId: string;
  messages: ChatMessage[];
  users: ChatUser[];
  onSendMessage: (content: string, type?: ChatMessage['type'], metadata?: ChatMessage['metadata']) => void;
  onTyping?: (isTyping: boolean) => void;
  className?: string;
}

// Sub-components
const MessageBubble: React.FC<{
  message: ChatMessage;
  isOwn: boolean;
  user?: ChatUser;
}> = ({ message, isOwn, user }) => {
  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    }).format(date);
  };

  const renderMessageContent = () => {
    switch (message.type) {
      case 'location':
        return (
          <div className="flex items-center gap-2 p-3 bg-[rgb(248,250,252)] rounded-lg">
            <MapPin className="w-4 h-4 text-[rgb(34,139,34)]" />
            <span className="text-sm font-medium">Shared location</span>
          </div>
        );
      case 'task':
        return (
          <div className="flex items-center gap-2 p-3 bg-[rgb(245,158,11)] bg-opacity-10 rounded-lg">
            <Users className="w-4 h-4 text-[rgb(245,158,11)]" />
            <span className="text-sm font-medium">Task assignment updated</span>
          </div>
        );
      case 'system':
        return (
          <div className="text-center text-sm text-[rgb(100,116,139)] italic">
            {message.content}
          </div>
        );
      default:
        return <p className="text-sm leading-relaxed">{message.content}</p>;
    }
  };

  if (message.type === 'system') {
    return (
      <div className="flex justify-center my-4">
        {renderMessageContent()}
      </div>
    );
  }

  return (
    <div className={`flex gap-3 mb-4 ${isOwn ? 'flex-row-reverse' : 'flex-row'}`}>
      {!isOwn && (
        <div className="flex-shrink-0">
          {user?.avatar ? (
            <img
              src={user.avatar}
              alt={user.name}
              className="w-8 h-8 rounded-full object-cover"
            />
          ) : (
            <div className="w-8 h-8 rounded-full bg-[rgb(34,139,34)] flex items-center justify-center">
              <span className="text-xs font-medium text-white">
                {user?.name?.charAt(0).toUpperCase() || 'U'}
              </span>
            </div>
          )}
        </div>
      )}

      <div className={`flex flex-col max-w-[75%] ${isOwn ? 'items-end' : 'items-start'}`}>
        {!isOwn && (
          <span className="text-xs text-[rgb(100,116,139)] mb-1 font-medium">
            {user?.name || 'Unknown User'}
          </span>
        )}

        <div
          className={`px-4 py-2 rounded-2xl ${
            isOwn
              ? 'bg-[rgb(34,139,34)] text-white rounded-br-md'
              : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-bl-md'
          }`}
        >
          {renderMessageContent()}
        </div>

        <span className="text-xs text-[rgb(100,116,139)] mt-1">
          {formatTime(message.timestamp)}
        </span>
      </div>
    </div>
  );
};

const TypingIndicator: React.FC<{ users: string[] }> = ({ users }) => {
  if (users.length === 0) return null;

  return (
    <div className="flex items-center gap-2 mb-4 px-4">
      <div className="flex gap-1">
        <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
        <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
        <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
      </div>
      <span className="text-sm text-[rgb(100,116,139)]">
        {users.length === 1 ? `${users[0]} is typing...` : `${users.length} people are typing...`}
      </span>
    </div>
  );
};

const MessageInput: React.FC<{
  onSend: (message: string) => void;
  onTyping?: (isTyping: boolean) => void;
  disabled?: boolean;
}> = ({ onSend, onTyping, disabled = false }) => {
  const [message, setMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const typingTimeoutRef = useRef<NodeJS.Timeout>();

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setMessage(value);

    // Handle typing indicator
    if (onTyping) {
      if (!isTyping && value.length > 0) {
        setIsTyping(true);
        onTyping(true);
      }

      // Clear existing timeout
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }

      // Set new timeout
      typingTimeoutRef.current = setTimeout(() => {
        setIsTyping(false);
        onTyping(false);
      }, 1000);
    }
  };

  const handleSend = () => {
    if (message.trim() && !disabled) {
      onSend(message.trim());
      setMessage('');
      if (onTyping && isTyping) {
        setIsTyping(false);
        onTyping(false);
      }
      inputRef.current?.focus();
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.style.height = 'auto';
      inputRef.current.style.height = `${inputRef.current.scrollHeight}px`;
    }
  }, [message]);

  return (
    <div className="border-t border-[rgb(226,232,240)] bg-white p-4">
      <div className="flex items-end gap-3">
        <button
          type="button"
          className="flex-shrink-0 p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors touch-manipulation"
          aria-label="Attach file"
          style={{ minHeight: '44px', minWidth: '44px' }}
        >
          <Paperclip className="w-5 h-5" />
        </button>

        <div className="flex-1 relative">
          <textarea
            ref={inputRef}
            value={message}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            placeholder="Type a message..."
            disabled={disabled}
            className="w-full px-4 py-3 border border-[rgb(226,232,240)] rounded-2xl resize-none focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] max-h-32 overflow-y-auto"
            style={{ minHeight: '44px' }}
            rows={1}
          />
        </div>

        <button
          type="button"
          className="flex-shrink-0 p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors touch-manipulation"
          aria-label="Add emoji"
          style={{ minHeight: '44px', minWidth: '44px' }}
        >
          <Smile className="w-5 h-5" />
        </button>

        <button
          type="button"
          onClick={handleSend}
          disabled={!message.trim() || disabled}
          className="flex-shrink-0 p-3 bg-[rgb(34,139,34)] text-white rounded-full hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors touch-manipulation"
          aria-label="Send message"
          style={{ minHeight: '44px', minWidth: '44px' }}
        >
          <Send className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
};

// Main Component
const ChatModel: React.FC<ChatModelProps> = ({
  tripId,
  currentUserId,
  messages,
  users,
  onSendMessage,
  onTyping,
  className = '',
}) => {
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (content: string) => {
    onSendMessage(content, 'text');
  };

  const handleTyping = (isTyping: boolean) => {
    if (onTyping) {
      onTyping(isTyping);
    }
  };

  const onlineUsers = users.filter(user => user.isOnline);
  const sortedMessages = [...messages].sort((a, b) => 
    new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
  );

  return (
    <div className={`flex flex-col h-full bg-white ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-white">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            {onlineUsers.slice(0, 3).map((user) => (
              <div key={user.id} className="relative">
                {user.avatar ? (
                  <img
                    src={user.avatar}
                    alt={user.name}
                    className="w-8 h-8 rounded-full border-2 border-white object-cover"
                  />
                ) : (
                  <div className="w-8 h-8 rounded-full bg-[rgb(34,139,34)] border-2 border-white flex items-center justify-center">
                    <span className="text-xs font-medium text-white">
                      {user.name.charAt(0).toUpperCase()}
                    </span>
                  </div>
                )}
                <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-[rgb(34,139,34)] border-2 border-white rounded-full" />
              </div>
            ))}
            {onlineUsers.length > 3 && (
              <div className="w-8 h-8 rounded-full bg-[rgb(100,116,139)] border-2 border-white flex items-center justify-center">
                <span className="text-xs font-medium text-white">
                  +{onlineUsers.length - 3}
                </span>
              </div>
            )}
          </div>
          <div>
            <h3 className="font-semibold text-[rgb(15,23,42)]">Trip Chat</h3>
            <p className="text-sm text-[rgb(100,116,139)]">
              {onlineUsers.length} online
            </p>
          </div>
        </div>

        <button
          type="button"
          className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] transition-colors touch-manipulation"
          aria-label="Chat options"
          style={{ minHeight: '44px', minWidth: '44px' }}
        >
          <MoreVertical className="w-5 h-5" />
        </button>
      </div>

      {/* Messages */}
      <div 
        ref={messagesContainerRef}
        className="flex-1 overflow-y-auto p-4 space-y-1"
        style={{ scrollBehavior: 'smooth' }}
      >
        {sortedMessages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center py-12">
            <div className="w-16 h-16 bg-[rgb(248,250,252)] rounded-full flex items-center justify-center mb-4">
              <Users className="w-8 h-8 text-[rgb(100,116,139)]" />
            </div>
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">Start the conversation</h3>
            <p className="text-sm text-[rgb(100,116,139)] max-w-sm">
              Share updates, coordinate plans, and stay connected with your trip group.
            </p>
          </div>
        ) : (
          <>
            {sortedMessages.map((message) => {
              const user = users.find(u => u.id === message.userId);
              const isOwn = message.userId === currentUserId;

              return (
                <MessageBubble
                  key={message.id}
                  message={message}
                  isOwn={isOwn}
                  user={user}
                />
              );
            })}
            <TypingIndicator users={typingUsers} />
            <div ref={messagesEndRef} />
          </>
        )}
      </div>

      {/* Input */}
      <MessageInput
        onSend={handleSendMessage}
        onTyping={handleTyping}
      />
    </div>
  );
};

export default ChatModel;

'use client';

import React, { useState, useEffect } from 'react';
import { X, Check, Clock, Users, MapPin, Calendar } from 'lucide-react';

interface RSVPStatus {
  id: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  status: 'pending' | 'accepted' | 'declined' | 'maybe';
  respondedAt?: Date;
  notes?: string;
}

interface TripDetails {
  id: string;
  title: string;
  location: string;
  startDate: Date;
  endDate: Date;
  description?: string;
  maxParticipants?: number;
}

interface RSVPModelProps {
  isOpen: boolean;
  onClose: () => void;
  trip: TripDetails;
  rsvpList: RSVPStatus[];
  currentUserId: string;
  onRSVPUpdate: (tripId: string, status: RSVPStatus['status'], notes?: string) => Promise<void>;
  onSendReminder: (tripId: string, userIds: string[]) => Promise<void>;
}

const RSVPModel: React.FC<RSVPModelProps> = ({
  isOpen,
  onClose,
  trip,
  rsvpList,
  currentUserId,
  onRSVPUpdate,
  onSendReminder
}) => {
  const [selectedStatus, setSelectedStatus] = useState<RSVPStatus['status']>('pending');
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showReminder, setShowReminder] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState<string[]>([]);

  const currentUserRSVP = rsvpList.find(rsvp => rsvp.userId === currentUserId);

  useEffect(() => {
    if (currentUserRSVP) {
      setSelectedStatus(currentUserRSVP.status);
      setNotes(currentUserRSVP.notes || '');
    }
  }, [currentUserRSVP]);

  const handleSubmitRSVP = async () => {
    setIsSubmitting(true);
    try {
      await onRSVPUpdate(trip.id, selectedStatus, notes);
      onClose();
    } catch (error) {
      console.error('Failed to update RSVP:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSendReminder = async () => {
    if (selectedUsers.length === 0) return;

    try {
      await onSendReminder(trip.id, selectedUsers);
      setShowReminder(false);
      setSelectedUsers([]);
    } catch (error) {
      console.error('Failed to send reminder:', error);
    }
  };

  const getStatusColor = (status: RSVPStatus['status']) => {
    switch (status) {
      case 'accepted':
        return 'text-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10';
      case 'declined':
        return 'text-[rgb(239,68,68)] bg-[rgb(239,68,68)]/10';
      case 'maybe':
        return 'text-[rgb(245,158,11)] bg-[rgb(245,158,11)]/10';
      default:
        return 'text-[rgb(15,23,42)] bg-[rgb(241,245,249)]';
    }
  };

  const getStatusIcon = (status: RSVPStatus['status']) => {
    switch (status) {
      case 'accepted':
        return <Check className="w-4 h-4" />;
      case 'declined':
        return <X className="w-4 h-4" />;
      case 'maybe':
        return <Clock className="w-4 h-4" />;
      default:
        return <Clock className="w-4 h-4" />;
    }
  };

  const statusCounts = rsvpList.reduce((acc, rsvp) => {
    acc[rsvp.status] = (acc[rsvp.status] || 0) + 1;
    return acc;
  }, {} as Record<RSVPStatus['status'], number>);

  const pendingUsers = rsvpList.filter(rsvp => rsvp.status === 'pending');

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50">
      <div className="w-full max-w-2xl max-h-[90vh] overflow-hidden bg-[rgb(255,255,255)] rounded-lg shadow-lg">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-[rgb(226,232,240)]">
          <div className="flex-1">
            <h2 className="text-xl font-semibold text-[rgb(15,23,42)] font-medium">
              Trip RSVP
            </h2>
            <p className="text-sm text-[rgb(15,23,42)]/60 mt-1">
              {trip.title}
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-[rgb(241,245,249)] rounded-md transition-colors"
            aria-label="Close RSVP modal"
          >
            <X className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>
        </div>

        <div className="overflow-y-auto max-h-[calc(90vh-120px)]">
          {/* Trip Details */}
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <div className="space-y-3">
              <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/80">
                <MapPin className="w-4 h-4" />
                <span>{trip.location}</span>
              </div>
              <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/80">
                <Calendar className="w-4 h-4" />
                <span>
                  {trip.startDate.toLocaleDateString()} - {trip.endDate.toLocaleDateString()}
                </span>
              </div>
              {trip.description && (
                <p className="text-sm text-[rgb(15,23,42)]/80 mt-2">
                  {trip.description}
                </p>
              )}
            </div>
          </div>

          {/* RSVP Summary */}
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <div className="flex items-center gap-2 mb-4">
              <Users className="w-5 h-5 text-[rgb(15,23,42)]" />
              <h3 className="font-medium text-[rgb(15,23,42)]">
                Response Summary ({rsvpList.length} invited)
              </h3>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="text-center p-3 bg-[rgb(34,139,34)]/10 rounded-lg">
                <div className="text-lg font-semibold text-[rgb(34,139,34)]">
                  {statusCounts.accepted || 0}
                </div>
                <div className="text-xs text-[rgb(15,23,42)]/60">Going</div>
              </div>
              <div className="text-center p-3 bg-[rgb(239,68,68)]/10 rounded-lg">
                <div className="text-lg font-semibold text-[rgb(239,68,68)]">
                  {statusCounts.declined || 0}
                </div>
                <div className="text-xs text-[rgb(15,23,42)]/60">Can't Go</div>
              </div>
              <div className="text-center p-3 bg-[rgb(245,158,11)]/10 rounded-lg">
                <div className="text-lg font-semibold text-[rgb(245,158,11)]">
                  {statusCounts.maybe || 0}
                </div>
                <div className="text-xs text-[rgb(15,23,42)]/60">Maybe</div>
              </div>
              <div className="text-center p-3 bg-[rgb(241,245,249)] rounded-lg">
                <div className="text-lg font-semibold text-[rgb(15,23,42)]">
                  {statusCounts.pending || 0}
                </div>
                <div className="text-xs text-[rgb(15,23,42)]/60">Pending</div>
              </div>
            </div>
          </div>

          {/* Your Response */}
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <h3 className="font-medium text-[rgb(15,23,42)] mb-4">Your Response</h3>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
              {(['accepted', 'declined', 'maybe', 'pending'] as const).map((status) => (
                <button
                  key={status}
                  onClick={() => setSelectedStatus(status)}
                  className={`p-3 rounded-lg border-2 transition-all ${
                    selectedStatus === status
                      ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10'
                      : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
                  }`}
                  aria-label={`Select ${status} status`}
                >
                  <div className={`flex items-center justify-center gap-2 ${getStatusColor(status)}`}>
                    {getStatusIcon(status)}
                    <span className="text-sm font-medium capitalize">
                      {status === 'accepted' ? 'Going' : status === 'declined' ? "Can't Go" : status}
                    </span>
                  </div>
                </button>
              ))}
            </div>

            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Add a note (optional)"
              className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg resize-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
              rows={3}
              aria-label="RSVP notes"
            />

            <button
              onClick={handleSubmitRSVP}
              disabled={isSubmitting}
              className="w-full mt-4 p-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              aria-label="Submit RSVP response"
            >
              {isSubmitting ? 'Updating...' : 'Update Response'}
            </button>
          </div>

          {/* All Responses */}
          <div className="p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-medium text-[rgb(15,23,42)]">All Responses</h3>
              {pendingUsers.length > 0 && (
                <button
                  onClick={() => setShowReminder(!showReminder)}
                  className="text-sm text-[rgb(34,139,34)] hover:text-[rgb(34,139,34)]/80 font-medium"
                  aria-label="Send reminder to pending users"
                >
                  Send Reminder
                </button>
              )}
            </div>

            {showReminder && pendingUsers.length > 0 && (
              <div className="mb-4 p-4 bg-[rgb(248,250,252)] rounded-lg">
                <h4 className="text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Send reminder to:
                </h4>
                <div className="space-y-2 mb-3">
                  {pendingUsers.map((user) => (
                    <label key={user.userId} className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        checked={selectedUsers.includes(user.userId)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedUsers([...selectedUsers, user.userId]);
                          } else {
                            setSelectedUsers(selectedUsers.filter(id => id !== user.userId));
                          }
                        }}
                        className="rounded border-[rgb(226,232,240)] text-[rgb(34,139,34)] focus:ring-[rgb(34,139,34)]"
                      />
                      <span className="text-sm text-[rgb(15,23,42)]">{user.userName}</span>
                    </label>
                  ))}
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handleSendReminder}
                    disabled={selectedUsers.length === 0}
                    className="px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-md text-sm font-medium hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Send
                  </button>
                  <button
                    onClick={() => setShowReminder(false)}
                    className="px-4 py-2 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-md text-sm font-medium hover:bg-[rgb(226,232,240)]"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            <div className="space-y-3">
              {rsvpList.map((rsvp) => (
                <div key={rsvp.userId} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium">
                      {rsvp.userName.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <div className="text-sm font-medium text-[rgb(15,23,42)]">
                        {rsvp.userName}
                      </div>
                      {rsvp.notes && (
                        <div className="text-xs text-[rgb(15,23,42)]/60 mt-1">
                          {rsvp.notes}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(rsvp.status)}`}>
                    {getStatusIcon(rsvp.status)}
                    <span className="capitalize">
                      {rsvp.status === 'accepted' ? 'Going' : rsvp.status === 'declined' ? "Can't Go" : rsvp.status}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RSVPModel;

code.auth:
'use client';

import React, { useState, useEffect } from 'react';
import { Eye, EyeOff, Mail, Lock, User, Mountain } from 'lucide-react';

interface User {
  id: string;
  email: string;
  name: string;
  avatar?: string;
}

interface AuthFormData {
  email: string;
  password: string;
  name?: string;
  confirmPassword?: string;
}

interface AuthSystemProps {
  onAuthSuccess?: (user: User) => void;
  redirectUrl?: string;
}

interface FormErrors {
  email?: string;
  password?: string;
  name?: string;
  confirmPassword?: string;
  general?: string;
}

const AuthSystem: React.FC<AuthSystemProps> = ({ 
  onAuthSuccess,
  redirectUrl = '/dashboard'
}) => {
  const [isLogin, setIsLogin] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState<AuthFormData>({
    email: '',
    password: '',
    name: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState<FormErrors>({});

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePassword = (password: string): boolean => {
    return password.length >= 8;
  };

  const validateForm = (): FormErrors => {
    const newErrors: FormErrors = {};

    if (!formData.email) {
      newErrors.email = 'Email is required';
    } else if (!validateEmail(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (!formData.password) {
      newErrors.password = 'Password is required';
    } else if (!validatePassword(formData.password)) {
      newErrors.password = 'Password must be at least 8 characters';
    }

    if (!isLogin) {
      if (!formData.name || formData.name.trim().length < 2) {
        newErrors.name = 'Name must be at least 2 characters';
      }

      if (!formData.confirmPassword) {
        newErrors.confirmPassword = 'Please confirm your password';
      } else if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = 'Passwords do not match';
      }
    }

    return newErrors;
  };

  const handleInputChange = (field: keyof AuthFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    setIsLoading(true);
    setErrors({});

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Mock successful authentication
      const mockUser: User = {
        id: '1',
        email: formData.email,
        name: formData.name || formData.email.split('@')[0]
      };

      onAuthSuccess?.(mockUser);

      // In a real app, this would redirect
      console.log('Redirecting to:', redirectUrl);

    } catch (error) {
      setErrors({ general: 'Authentication failed. Please try again.' });
    } finally {
      setIsLoading(false);
    }
  };

  const toggleAuthMode = () => {
    setIsLogin(!isLogin);
    setFormData({
      email: '',
      password: '',
      name: '',
      confirmPassword: ''
    });
    setErrors({});
  };

  const InputField: React.FC<{
    type: string;
    placeholder: string;
    value: string;
    onChange: (value: string) => void;
    error?: string;
    icon: React.ReactNode;
    showPasswordToggle?: boolean;
    showPassword?: boolean;
    onTogglePassword?: () => void;
    'aria-label': string;
  }> = ({ 
    type, 
    placeholder, 
    value, 
    onChange, 
    error, 
    icon, 
    showPasswordToggle,
    showPassword,
    onTogglePassword,
    'aria-label': ariaLabel
  }) => (
    <div className="space-y-1">
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <div className="text-gray-400">
            {icon}
          </div>
        </div>
        <input
          type={showPasswordToggle ? (showPassword ? 'text' : 'password') : type}
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          aria-label={ariaLabel}
          aria-invalid={!!error}
          aria-describedby={error ? `${ariaLabel}-error` : undefined}
          className={`
            w-full pl-10 pr-${showPasswordToggle ? '12' : '4'} py-3 
            border rounded-lg font-medium text-base
            bg-white text-[rgb(15,23,42)]
            placeholder-gray-400
            focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2
            transition-colors duration-200
            ${error 
              ? 'border-[rgb(239,68,68)] focus:border-[rgb(239,68,68)]' 
              : 'border-[rgb(226,232,240)] focus:border-[rgb(34,139,34)]'
            }
          `}
          style={{ minHeight: '44px' }}
        />
        {showPasswordToggle && (
          <button
            type="button"
            onClick={onTogglePassword}
            aria-label={showPassword ? 'Hide password' : 'Show password'}
            className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 rounded"
          >
            {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
          </button>
        )}
      </div>
      {error && (
        <p 
          id={`${ariaLabel}-error`}
          className="text-sm text-[rgb(239,68,68)] font-medium"
          role="alert"
        >
          {error}
        </p>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-[rgb(248,250,252)] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Logo and Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-[rgb(34,139,34)] rounded-xl mb-4">
            <Mountain className="w-8 h-8 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">
            {isLogin ? 'Welcome Back' : 'Join the Adventure'}
          </h1>
          <p className="text-gray-600 font-medium">
            {isLogin 
              ? 'Sign in to plan your next off-road adventure' 
              : 'Create your account to start planning trips'
            }
          </p>
        </div>

        {/* Auth Form */}
        <div className="bg-white rounded-xl shadow-md p-6">
          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <InputField
                type="text"
                placeholder="Full Name"
                value={formData.name || ''}
                onChange={(value) => handleInputChange('name', value)}
                error={errors.name}
                icon={<User size={20} />}
                aria-label="Full Name"
              />
            )}

            <InputField
              type="email"
              placeholder="Email Address"
              value={formData.email}
              onChange={(value) => handleInputChange('email', value)}
              error={errors.email}
              icon={<Mail size={20} />}
              aria-label="Email Address"
            />

            <InputField
              type="password"
              placeholder="Password"
              value={formData.password}
              onChange={(value) => handleInputChange('password', value)}
              error={errors.password}
              icon={<Lock size={20} />}
              showPasswordToggle
              showPassword={showPassword}
              onTogglePassword={() => setShowPassword(!showPassword)}
              aria-label="Password"
            />

            {!isLogin && (
              <InputField
                type="password"
                placeholder="Confirm Password"
                value={formData.confirmPassword || ''}
                onChange={(value) => handleInputChange('confirmPassword', value)}
                error={errors.confirmPassword}
                icon={<Lock size={20} />}
                showPasswordToggle
                showPassword={showConfirmPassword}
                onTogglePassword={() => setShowConfirmPassword(!showConfirmPassword)}
                aria-label="Confirm Password"
              />
            )}

            {errors.general && (
              <div 
                className="p-3 bg-red-50 border border-[rgb(239,68,68)] rounded-lg"
                role="alert"
              >
                <p className="text-sm text-[rgb(239,68,68)] font-medium">
                  {errors.general}
                </p>
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              aria-label={isLogin ? 'Sign in to your account' : 'Create your account'}
              className={`
                w-full py-3 px-4 rounded-lg font-semibold text-base
                bg-[rgb(34,139,34)] text-white
                hover:bg-[rgb(29,120,29)] 
                focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2
                disabled:opacity-50 disabled:cursor-not-allowed
                transition-colors duration-200
                ${isLoading ? 'cursor-wait' : ''}
              `}
              style={{ minHeight: '44px' }}
            >
              {isLoading ? (
                <div className="flex items-center justify-center">
                  <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mr-2"></div>
                  {isLogin ? 'Signing In...' : 'Creating Account...'}
                </div>
              ) : (
                isLogin ? 'Sign In' : 'Create Account'
              )}
            </button>
          </form>

          {/* Toggle Auth Mode */}
          <div className="mt-6 text-center">
            <p className="text-gray-600 font-medium">
              {isLogin ? "Don't have an account?" : 'Already have an account?'}
              <button
                type="button"
                onClick={toggleAuthMode}
                className="ml-2 text-[rgb(34,139,34)] font-semibold hover:underline focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 rounded"
                aria-label={isLogin ? 'Switch to sign up' : 'Switch to sign in'}
              >
                {isLogin ? 'Sign Up' : 'Sign In'}
              </button>
            </p>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-8 text-center">
          <p className="text-sm text-gray-500 font-medium">
            By continuing, you agree to our Terms of Service and Privacy Policy
          </p>
        </div>
      </div>
    </div>
  );
};

export default AuthSystem;

