'use client'

import React, { useState, useEffect } from 'react'
import { Calendar, MapPin, Users, Clock, MessageSquare, Utensils, CheckCircle, AlertCircle, Sun, Cloud, CloudRain } from 'lucide-react'
import Image from 'next/image'

// TypeScript Interfaces
interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  imageUrl: string
  status: 'planning' | 'confirmed' | 'in-progress' | 'completed'
}

interface Participant {
  id: string
  name: string
  avatar: string
  status: 'confirmed' | 'pending' | 'declined'
}

interface Task {
  id: string
  title: string
  assignee: string
  dueDate: string
  status: 'pending' | 'in-progress' | 'completed'
  category: 'food' | 'equipment' | 'logistics' | 'other'
}

interface WeatherData {
  date: string
  condition: 'sunny' | 'cloudy' | 'rainy'
  high: number
  low: number
}

interface Meal {
  id: string
  name: string
  date: string
  time: string
  assignee: string
}

interface TripOverviewProps {
  tripId: string
}

const TripOverview: React.FC<TripOverviewProps> = ({ tripId }) => {
  const [trip, setTrip] = useState<Trip | null>(null)
  const [participants, setParticipants] = useState<Participant[]>([])
  const [tasks, setTasks] = useState<Task[]>([])
  const [weather, setWeather] = useState<WeatherData[]>([])
  const [meals, setMeals] = useState<Meal[]>([])
  const [activeTab, setActiveTab] = useState<'overview' | 'tasks' | 'meals' | 'chat'>('overview')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const fetchTripData = async () => {
      try {
        setLoading(true)
        // Simulated API calls - replace with actual API endpoints
        const [tripData, participantsData, tasksData, weatherData, mealsData] = await Promise.all([
          fetch(`/api/trips/${tripId}`).then(res => res.json()),
          fetch(`/api/trips/${tripId}/participants`).then(res => res.json()),
          fetch(`/api/trips/${tripId}/tasks`).then(res => res.json()),
          fetch(`/api/trips/${tripId}/weather`).then(res => res.json()),
          fetch(`/api/trips/${tripId}/meals`).then(res => res.json())
        ])

        setTrip(tripData)
        setParticipants(participantsData)
        setTasks(tasksData)
        setWeather(weatherData)
        setMeals(mealsData)
      } catch (err) {
        setError('Failed to load trip data. Please try again.')
      } finally {
        setLoading(false)
      }
    }

    fetchTripData()
  }, [tripId])

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return <Sun className="w-5 h-5 text-yellow-500" />
      case 'cloudy': return <Cloud className="w-5 h-5 text-gray-500" />
      case 'rainy': return <CloudRain className="w-5 h-5 text-[rgb(34, 139, 34)]" />
      default: return <Sun className="w-5 h-5 text-yellow-500" />
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
      case 'pending': return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
      case 'declined': return 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
      case 'completed': return 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
      case 'in-progress': return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
      default: return 'bg-[rgb(226,232,240)] text-[rgb(15,23,42)]'
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
        <div className="animate-pulse">
          <div className="h-64 bg-[rgb(241,245,249)] rounded-lg mb-6"></div>
          <div className="space-y-4">
            <div className="h-8 bg-[rgb(241,245,249)] rounded w-3/4"></div>
            <div className="h-4 bg-[rgb(241,245,249)] rounded w-1/2"></div>
            <div className="grid grid-cols-2 gap-4">
              <div className="h-24 bg-[rgb(241,245,249)] rounded"></div>
              <div className="h-24 bg-[rgb(241,245,249)] rounded"></div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  if (error || !trip) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center font-medium">
        <div className="text-center p-6">
          <AlertCircle className="w-12 h-12 text-[rgb(239,68,68)] mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)] mb-2">
            {error || 'Trip not found'}
          </h2>
          <button 
            onClick={() => window.location.reload()}
            className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-6 py-3 rounded-lg font-medium hover:opacity-90 transition-opacity min-h-[44px]"
            aria-label="Retry loading trip data"
          >
            Try Again
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Hero Section */}
      <div className="relative h-64 md:h-80 overflow-hidden rounded-lg mb-6">
        <Image
          src={trip.imageUrl || '/placeholder-trip.jpg'}
          alt={`${trip.name} location`}
          fill
          className="object-cover"
          priority
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
        <div className="absolute bottom-4 left-4 right-4 text-white">
          <h1 className="text-2xl md:text-3xl font-bold mb-2">{trip.name}</h1>
          <div className="flex items-center gap-2 text-sm">
            <MapPin className="w-4 h-4" />
            <span>{trip.location}</span>
          </div>
        </div>
      </div>

      {/* Status Banner */}
      <div className={`p-4 rounded-lg mb-6 ${getStatusColor(trip.status)}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle className="w-5 h-5" />
            <span className="font-semibold capitalize">{trip.status.replace('-', ' ')}</span>
          </div>
          <div className="flex items-center gap-2 text-sm">
            <Calendar className="w-4 h-4" />
            <span>{new Date(trip.startDate).toLocaleDateString()} - {new Date(trip.endDate).toLocaleDateString()}</span>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-[rgb(226,232,240)] mb-6 overflow-x-auto">
        {[
          { id: 'overview', label: 'Overview', icon: MapPin },
          { id: 'tasks', label: 'Tasks', icon: CheckCircle },
          { id: 'meals', label: 'Meals', icon: Utensils },
          { id: 'chat', label: 'Chat', icon: MessageSquare }
        ].map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            onClick={() => setActiveTab(id as any)}
            className={`flex items-center gap-2 px-4 py-3 font-medium whitespace-nowrap min-h-[44px] ${
              activeTab === id
                ? 'border-b-2 border-[rgb(34,139,34)] text-[rgb(34,139,34)]'
                : 'text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)]'
            }`}
            aria-label={`View ${label} tab`}
          >
            <Icon className="w-4 h-4" />
            <span>{label}</span>
          </button>
        ))}
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div className="space-y-6">
          {/* Quick Stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
                <span className="text-sm text-[rgb(15,23,42)]">Participants</span>
              </div>
              <div className="text-2xl font-bold text-[rgb(15,23,42)]">{participants.length}</div>
            </div>
            <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
                <span className="text-sm text-[rgb(15,23,42)]">Tasks</span>
              </div>
              <div className="text-2xl font-bold text-[rgb(15,23,42)]">
                {tasks.filter(t => t.status === 'completed').length}/{tasks.length}
              </div>
            </div>
            <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Clock className="w-5 h-5 text-[rgb(34,139,34)]" />
                <span className="text-sm text-[rgb(15,23,42)]">Days Left</span>
              </div>
              <div className="text-2xl font-bold text-[rgb(15,23,42)]">
                {Math.ceil((new Date(trip.startDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))}
              </div>
            </div>
            <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Utensils className="w-5 h-5 text-[rgb(34,139,34)]" />
                <span className="text-sm text-[rgb(15,23,42)]">Meals</span>
              </div>
              <div className="text-2xl font-bold text-[rgb(15,23,42)]">{meals.length}</div>
            </div>
          </div>

          {/* Weather Forecast */}
          <div className="bg-[rgb(248,250,252)] p-6 rounded-lg">
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Weather Forecast</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {weather.slice(0, 4).map((day, index) => (
                <div key={index} className="text-center">
                  <div className="text-sm text-[rgb(15,23,42)] mb-2">
                    {new Date(day.date).toLocaleDateString('en-US', { weekday: 'short' })}
                  </div>
                  <div className="flex justify-center mb-2">
                    {getWeatherIcon(day.condition)}
                  </div>
                  <div className="text-sm">
                    <span className="font-semibold">{day.high}°</span>
                    <span className="text-[rgb(15,23,42)]/60 ml-1">{day.low}°</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Participants */}
          <div className="bg-[rgb(248,250,252)] p-6 rounded-lg">
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Participants</h3>
            <div className="space-y-3">
              {participants.map((participant) => (
                <div key={participant.id} className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                      {participant.name.charAt(0)}
                    </div>
                    <span className="font-medium text-[rgb(15,23,42)]">{participant.name}</span>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(participant.status)}`}>
                    {participant.status}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {activeTab === 'tasks' && (
        <div className="space-y-4">
