'use client';

import { useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Loader2, Mail, Send, CheckCircle, AlertCircle, Users } from 'lucide-react';

interface EmailTemplate {
  id: string;
  name: string;
  subject: string;
  content: string;
  type: 'invitation' | 'reminder' | 'update' | 'cancellation';
}

interface EmailRecipient {
  email: string;
  name: string;
  role?: string;
}

interface EmailSendRequest {
  to: EmailRecipient[];
  subject: string;
  content: string;
  templateId?: string;
  tripId?: string;
}

interface EmailSendResponse {
  success: boolean;
  messageId?: string;
  error?: string;
  failedRecipients?: string[];
}

interface ResendServiceProps {
  tripId?: string;
  onEmailSent?: (response: EmailSendResponse) => void;
  className?: string;
}

const EMAIL_TEMPLATES: EmailTemplate[] = [
  {
    id: 'trip-invitation',
    name: 'Trip Invitation',
    subject: 'You\'re Invited: {{tripName}} Off-Road Adventure',
    content: `Hi {{recipientName}},

You're invited to join us for an exciting off-road adventure!

Trip Details:
- Location: {{location}}
- Date: {{startDate}} - {{endDate}}
- Meeting Point: {{meetingPoint}}

Please RSVP by {{rsvpDeadline}} so we can plan accordingly.

Looking forward to an amazing adventure together!

Best regards,
{{organizerName}}`,
    type: 'invitation'
  },
  {
    id: 'trip-reminder',
    name: 'Trip Reminder',
    subject: 'Reminder: {{tripName}} is Coming Up!',
    content: `Hi {{recipientName}},

Just a friendly reminder that our off-road trip is coming up soon!

Trip Details:
- Date: {{startDate}} - {{endDate}}
- Meeting Time: {{meetingTime}}
- Location: {{meetingPoint}}

Don't forget to bring:
- Your vehicle registration and insurance
- Camping gear (if overnight)
- Food and water
- Recovery equipment

See you there!

{{organizerName}}`,
    type: 'reminder'
  },
  {
    id: 'trip-update',
    name: 'Trip Update',
    subject: 'Update: {{tripName}} - Important Information',
    content: `Hi {{recipientName}},

We have an important update regarding our upcoming trip:

{{updateMessage}}

Updated Trip Details:
- Date: {{startDate}} - {{endDate}}
- Meeting Point: {{meetingPoint}}
- Weather Forecast: {{weather}}

Please let us know if you have any questions.

{{organizerName}}`,
    type: 'update'
  }
];

export default function ResendService({ tripId, onEmailSent, className = '' }: ResendServiceProps) {
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate | null>(null);
  const [recipients, setRecipients] = useState<EmailRecipient[]>([]);
  const [subject, setSubject] = useState('');
  const [content, setContent] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [lastResponse, setLastResponse] = useState<EmailSendResponse | null>(null);
  const [newRecipientEmail, setNewRecipientEmail] = useState('');
  const [newRecipientName, setNewRecipientName] = useState('');

  const addRecipient = useCallback(() => {
    if (newRecipientEmail && newRecipientName) {
      const newRecipient: EmailRecipient = {
        email: newRecipientEmail.trim(),
        name: newRecipientName.trim()
      };

      if (!recipients.find(r => r.email === newRecipient.email)) {
        setRecipients(prev => [...prev, newRecipient]);
        setNewRecipientEmail('');
        setNewRecipientName('');
      }
    }
  }, [newRecipientEmail, newRecipientName, recipients]);

  const removeRecipient = useCallback((email: string) => {
    setRecipients(prev => prev.filter(r => r.email !== email));
  }, []);

  const selectTemplate = useCallback((template: EmailTemplate) => {
    setSelectedTemplate(template);
    setSubject(template.subject);
    setContent(template.content);
  }, []);

  const sendEmail = useCallback(async () => {
    if (!recipients.length || !subject || !content) return;

    setIsLoading(true);
    try {
      const request: EmailSendRequest = {
        to: recipients,
        subject,
        content,
        templateId: selectedTemplate?.id,
        tripId
      };

      // Simulate API call to Resend service
      const response = await fetch('/api/email/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
      });

      const result: EmailSendResponse = await response.json();

      setLastResponse(result);
      onEmailSent?.(result);

      if (result.success) {
        // Clear form on success
        setRecipients([]);
        setSubject('');
        setContent('');
        setSelectedTemplate(null);
      }
    } catch (error) {
      const errorResponse: EmailSendResponse = {
        success: false,
        error: 'Failed to send email. Please try again.'
      };
      setLastResponse(errorResponse);
      onEmailSent?.(errorResponse);
    } finally {
      setIsLoading(false);
    }
  }, [recipients, subject, content, selectedTemplate, tripId, onEmailSent]);

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Email Templates */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader className="pb-4">
          <CardTitle className="text-[rgb(15,23,42)] font-medium text-lg flex items-center gap-2">
            <Mail className="w-5 h-5 text-[rgb(34,139,34)]" />
            Email Templates
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Choose a template to get started quickly
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {EMAIL_TEMPLATES.map((template) => (
              <Button
                key={template.id}
                variant={selectedTemplate?.id === template.id ? "default" : "outline"}
                className={`h-auto p-4 justify-start text-left ${
                  selectedTemplate?.id === template.id 
                    ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)] border-[rgb(34,139,34)]' 
                    : 'bg-[rgb(255,255,255)] text-[rgb(15,23,42)] border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)]'
                }`}
                onClick={() => selectTemplate(template)}
                aria-label={`Select ${template.name} template`}
              >
                <div className="space-y-1">
                  <div className="font-medium text-sm">{template.name}</div>
                  <Badge 
                    variant="secondary" 
                    className="text-xs bg-[rgb(241,245,249)] text-[rgb(71,85,105)]"
                  >
                    {template.type}
                  </Badge>
                </div>
              </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Recipients */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader className="pb-4">
          <CardTitle className="text-[rgb(15,23,42)] font-medium text-lg flex items-center gap-2">
            <Users className="w-5 h-5 text-[rgb(34,139,34)]" />
            Recipients
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Add people to send the email to
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div className="space-y-2">
              <Label htmlFor="recipient-name" className="text-[rgb(15,23,42)] font-medium">
                Name
              </Label>
              <Input
                id="recipient-name"
                value={newRecipientName}
                onChange={(e) => setNewRecipientName(e.target.value)}
                placeholder="Enter name"
                className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                onKeyDown={(e) => e.key === 'Enter' && addRecipient()}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="recipient-email" className="text-[rgb(15,23,42)] font-medium">
                Email
              </Label>
              <div className="flex gap-2">
                <Input
                  id="recipient-email"
                  type="email"
                  value={newRecipientEmail}
                  onChange={(e) => setNewRecipientEmail(e.target.value)}
                  placeholder="Enter email address"
                  className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                  onKeyDown={(e) => e.key === 'Enter' && addRecipient()}
                />
                <Button
                  onClick={addRecipient}
                  disabled={!newRecipientEmail || !newRecipientName}
                  className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] hover:bg-[rgb(22,101,22)] min-h-[44px] px-4"
                  aria-label="Add recipient"
                >
                  Add
                </Button>
              </div>
            </div>
          </div>

          {recipients.length > 0 && (
            <div className="space-y-2">
              <Label className="text-[rgb(15,23,42)] font-medium">
                Recipients ({recipients.length})
              </Label>
              <div className="flex flex-wrap gap-2">
                {recipients.map((recipient) => (
                  <Badge
                    key={recipient.email}
                    variant="secondary"
                    className="bg-[rgb(241,245,249)] text-[rgb(15,23,42)] px-3 py-1 cursor-pointer hover:bg-[rgb(226,232,240)]"
                    onClick={() => removeRecipient(recipient.email)}
                  >
                    {recipient.name} ({recipient.email}) ×
                  </Badge>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Email Content */}
      <Card className="border-[rgb(226,232,240)] shadow-md">
        <CardHeader className="pb-4">
          <CardTitle className="text-[rgb(15,23,42)] font-medium text-lg">
            Email Content
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Customize your email message
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="email-subject" className="text-[rgb(15,23,42)] font-medium">
              Subject
            </Label>
            <Input
              id="email-subject"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Enter email subject"
              className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="email-content" className="text-[rgb(15,23,42)] font-medium">
              Message
            </Label>
            <Textarea
              id="email-content"
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Enter your message"
              rows={8}
              className="border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 resize-none"
            />
          </div>
        </CardContent>
      </Card>

      {/* Send Button and Status */}
      <div className="space-y-4">
        <Button
          onClick={sendEmail}
          disabled={isLoading || !recipients.length || !subject || !content}
          className="w-full bg-[rgb(34,139,34)] text-[rgb(255,255,255)] hover:bg-[rgb(22,101,22)] min-h-[44px] font-medium"
          aria-label="Send email to all recipients"
        >
          {isLoading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Sending Email...
            </>
          ) : (
            <>
              <Send className="w-4 h-4 mr-2" />
              Send Email ({recipients.length} recipient{recipients.length !== 1 ? 's' : ''})
            </>
          )}
        </Button>

        {lastResponse && (
          <Alert className={`border ${
            lastResponse.success 
              ? 'border-[rgb(34,139,34)] bg-[rgb(240,253,244)]' 
              : 'border-[rgb(239,68,68)] bg-[rgb(254,242,242)]'
          }`}>
            {lastResponse.success ? (
              <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
            ) : (
              <AlertCircle className="w-4 h-4 text-[rgb(239,68,68)]" />
            )}
            <AlertDescription className={
              lastResponse.success 
                ? 'text-[rgb(21,128,61)]' 
                : 'text-[rgb(185,28,28)]'
            }>
              {lastResponse.success 
                ? `Email sent successfully! Message ID: ${lastResponse.messageId}`
                : lastResponse.error
              }
              {lastResponse.failedRecipients && lastResponse.failedRecipients.length > 0 && (
                <div className="mt-2">
                  Failed to send to: {lastResponse.failedRecipients.join(', ')}
                </div>
              )}
            </AlertDescription>
          </Alert>
        )}
      </div>
    </div>
  );
}

