'use client';

import { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Calendar, Clock, Users, MapPin, AlertCircle, CheckCircle, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

interface CalendarEvent {
  id: string;
  summary: string;
  description?: string;
  start: {
    dateTime?: string;
    date?: string;
    timeZone?: string;
  };
  end: {
    dateTime?: string;
    date?: string;
    timeZone?: string;
  };
  location?: string;
  attendees?: Array<{
    email: string;
    displayName?: string;
    responseStatus?: 'needsAction' | 'declined' | 'tentative' | 'accepted';
  }>;
  status?: 'confirmed' | 'tentative' | 'cancelled';
  htmlLink?: string;
}

interface CreateEventData {
  title: string;
  description: string;
  startDate: string;
  startTime: string;
  endDate: string;
  endTime: string;
  location: string;
  attendees: string[];
  timeZone: string;
}

interface CalendarAvailability {
  email: string;
  busy: Array<{
    start: string;
    end: string;
  }>;
}

interface GoogleCalendarApiProps {
  onEventCreated?: (event: CalendarEvent) => void;
  onAvailabilityChecked?: (availability: CalendarAvailability[]) => void;
  defaultAttendees?: string[];
  className?: string;
}

export default function GoogleCalendarApi({
  onEventCreated,
  onAvailabilityChecked,
  defaultAttendees = [],
  className = ''
}: GoogleCalendarApiProps) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [availability, setAvailability] = useState<CalendarAvailability[]>([]);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [createEventData, setCreateEventData] = useState<CreateEventData>({
    title: '',
    description: '',
    startDate: '',
    startTime: '',
    endDate: '',
    endTime: '',
    location: '',
    attendees: defaultAttendees,
    timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
  });

  // Initialize Google Calendar API
  useEffect(() => {
    const initializeGapi = async () => {
      try {
        if (typeof window !== 'undefined' && window.gapi) {
          await window.gapi.load('auth2', () => {
            window.gapi.auth2.init({
              client_id: process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID
            });
          });

          await window.gapi.load('client', () => {
            window.gapi.client.init({
              apiKey: process.env.NEXT_PUBLIC_GOOGLE_API_KEY,
              clientId: process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID,
              discoveryDocs: ['https://www.googleapis.com/discovery/v1/apis/calendar/v3/rest'],
              scope: 'https://www.googleapis.com/auth/calendar'
            });
          });

          const authInstance = window.gapi.auth2.getAuthInstance();
          setIsAuthenticated(authInstance.isSignedIn.get());
        }
      } catch (error) {
        console.error('Failed to initialize Google API:', error);
        toast.error('Failed to initialize calendar integration');
      }
    };

    initializeGapi();
  }, []);

  const handleSignIn = useCallback(async () => {
    try {
      setIsLoading(true);
      const authInstance = window.gapi.auth2.getAuthInstance();
      await authInstance.signIn();
      setIsAuthenticated(true);
      toast.success('Successfully connected to Google Calendar');
    } catch (error) {
      console.error('Sign in failed:', error);
      toast.error('Failed to connect to Google Calendar');
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSignOut = useCallback(async () => {
    try {
      const authInstance = window.gapi.auth2.getAuthInstance();
      await authInstance.signOut();
      setIsAuthenticated(false);
      setEvents([]);
      setAvailability([]);
      toast.success('Disconnected from Google Calendar');
    } catch (error) {
      console.error('Sign out failed:', error);
      toast.error('Failed to disconnect from Google Calendar');
    }
  }, []);

  const fetchEvents = useCallback(async (timeMin?: string, timeMax?: string) => {
    if (!isAuthenticated) return;

    try {
      setIsLoading(true);
      const response = await window.gapi.client.calendar.events.list({
        calendarId: 'primary',
        timeMin: timeMin || new Date().toISOString(),
        timeMax: timeMax || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        showDeleted: false,
        singleEvents: true,
        orderBy: 'startTime'
      });

      setEvents(response.result.items || []);
    } catch (error) {
      console.error('Failed to fetch events:', error);
      toast.error('Failed to fetch calendar events');
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated]);

  const checkAvailability = useCallback(async (emails: string[], timeMin: string, timeMax: string) => {
    if (!isAuthenticated || emails.length === 0) return;

    try {
      setIsLoading(true);
      const response = await window.gapi.client.calendar.freebusy.query({
        timeMin,
        timeMax,
        items: emails.map(email => ({ id: email }))
      });

      const availabilityData: CalendarAvailability[] = Object.entries(response.result.calendars || {}).map(
        ([email, data]: [string, any]) => ({
          email,
          busy: data.busy || []
        })
      );

      setAvailability(availabilityData);
      onAvailabilityChecked?.(availabilityData);
    } catch (error) {
      console.error('Failed to check availability:', error);
      toast.error('Failed to check availability');
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated, onAvailabilityChecked]);

  const createEvent = useCallback(async () => {
    if (!isAuthenticated) return;

    try {
      setIsLoading(true);

      const startDateTime = `${createEventData.startDate}T${createEventData.startTime}:00`;
      const endDateTime = `${createEventData.endDate}T${createEventData.endTime}:00`;

      const event = {
        summary: createEventData.title,
        description: createEventData.description,
        location: createEventData.location,
        start: {
          dateTime: startDateTime,
          timeZone: createEventData.timeZone
        },
        end: {
          dateTime: endDateTime,
          timeZone: createEventData.timeZone
        },
        attendees: createEventData.attendees.map(email => ({ email })),
        reminders: {
          useDefault: false,
          overrides: [
            { method: 'email', minutes: 24 * 60 },
            { method: 'popup', minutes: 30 }
          ]
        }
      };

      const response = await window.gapi.client.calendar.events.insert({
        calendarId: 'primary',
        resource: event,
        sendUpdates: 'all'
      });

      const createdEvent = response.result;
      setEvents(prev => [...prev, createdEvent]);
      onEventCreated?.(createdEvent);

      setShowCreateForm(false);
      setCreateEventData({
        title: '',
        description: '',
        startDate: '',
        startTime: '',
        endDate: '',
        endTime: '',
        location: '',
        attendees: defaultAttendees,
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      });

      toast.success('Trip event created and invites sent!');
    } catch (error) {
      console.error('Failed to create event:', error);
      toast.error('Failed to create calendar event');
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated, createEventData, onEventCreated, defaultAttendees]);

  const formatEventTime = (event: CalendarEvent) => {
    const start = event.start.dateTime || event.start.date;
    const end = event.end.dateTime || event.end.date;

    if (!start) return 'No time specified';

    const startDate = new Date(start);
    const endDate = new Date(end || start);

    if (event.start.date) {
      return startDate.toLocaleDateString();
    }

    return `${startDate.toLocaleDateString()} ${startDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - ${endDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
  };

  if (!isAuthenticated) {
    return (
      <Card className={`w-full ${className}`}>
        <CardHeader className="text-center">
          <Calendar className="w-12 h-12 mx-auto mb-4 text-[rgb(34,139,34)]" />
          <CardTitle className="font-medium text-[rgb(15,23,42)]">Connect Google Calendar</CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Sync your calendar to check availability and send trip invites
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Button
            onClick={handleSignIn}
            disabled={isLoading}
            className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white font-medium h-11 touch-manipulation"
            aria-label="Connect to Google Calendar"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Connecting...
              </>
            ) : (
              <>
                <Calendar className="w-4 h-4 mr-2" />
                Connect Calendar
              </>
            )}
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <Card>
        <CardHeader className="pb-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
              <div>
                <CardTitle className="text-lg font-medium text-[rgb(15,23,42)]">Calendar Connected</CardTitle>
                <CardDescription className="text-sm text-[rgb(100,116,139)]">
                  Manage trip events and check availability
                </CardDescription>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleSignOut}
              className="text-[rgb(100,116,139)] border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)]"
            >
              Disconnect
            </Button>
          </div>
        </CardHeader>
        <CardContent className="pt-0">
          <div className="flex flex-col sm:flex-row gap-3">
            <Button
              onClick={() => setShowCreateForm(!showCreateForm)}
              className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white font-medium h-11 touch-manipulation"
              aria-label="Create new trip event"
            >
              <Calendar className="w-4 h-4 mr-2" />
              Create Trip Event
            </Button>
            <Button
              variant="outline"
              onClick={() => fetchEvents()}
              disabled={isLoading}
              className="border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)] h-11 touch-manipulation"
              aria-label="Refresh calendar events"
            >
              {isLoading ? (
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              ) : (
                <Clock className="w-4 h-4 mr-2" />
              )}
              Refresh Events
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Create Event Form */}
      {showCreateForm && (
        <Card>
          <CardHeader>
            <CardTitle className="font-medium text-[rgb(15,23,42)]">Create Trip Event</CardTitle>
            <CardDescription className="text-[rgb(100,116,139)]">
              Schedule your off-road adventure and invite the group
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="event-title" className="text-sm font-medium text-[rgb(15,23,42)]">
                Trip Title
              </Label>
              <Input
                id="event-title"
                value={createEventData.title}
                onChange={(e) => setCreateEventData(prev => ({ ...prev, title: e.target.value }))}
                placeholder="Weekend Off-Road Adventure"
                className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                aria-describedby="event-title-desc"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="event-description" className="text-sm font-medium text-[rgb(15,23,42)]">
                Description
              </Label>
              <Textarea
                id="event-description"
                value={createEventData.description}
                onChange={(e) => setCreateEventData(prev => ({ ...prev, description: e.target.value }))}
                placeholder="Trail details, meeting point, what to bring..."
                className="min-h-[80px] border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                aria-describedby="event-description-desc"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="event-location" className="text-sm font-medium text-[rgb(15,23,42)]">
                Location
              </Label>
              <Input
                id="event-location"
                value={createEventData.location}
                onChange={(e) => setCreateEventData(prev => ({ ...prev, location: e.target.value }))}
                placeholder="Trailhead address or coordinates"
                className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="start-date" className="text-sm font-medium text-[rgb(15,23,42)]">
                  Start Date
                </Label>
                <Input
                  id="start-date"
                  type="date"
                  value={createEventData.startDate}
                  onChange={(e) => setCreateEventData(prev => ({ ...prev, startDate: e.target.value }))}
                  className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="start-time" className="text-sm font-medium text-[rgb(15,23,42)]">
                  Start Time
                </Label>
                <Input
                  id="start-time"
                  type="time"
                  value={createEventData.startTime}
                  onChange={(e) => setCreateEventData(prev => ({ ...prev, startTime: e.target.value }))}
                  className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="end-date" className="text-sm font-medium text-[rgb(15,23,42)]">
                  End Date
                </Label>
                <Input
                  id="end-date"
                  type="date"
                  value={createEventData.endDate}
                  onChange={(e) => setCreateEventData(prev => ({ ...prev, endDate: e.target.value }))}
                  className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="end-time" className="text-sm font-medium text-[rgb(15,23,42)]">
                  End Time
                </Label>
                <Input
                  id="end-time"
                  type="time"
                  value={createEventData.endTime}
                  onChange={(e) => setCreateEventData(prev => ({ ...prev, endTime: e.target.value }))}
                  className="h-11 border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="attendees" className="text-sm font-medium text-[rgb(15,23,42)]">
                Attendees (Email addresses, comma separated)
              </Label>
              <Textarea
                id="attendees"
                value={createEventData.attendees.join(', ')}
                onChange={(e) => setCreateEventData(prev => ({ 
                  ...prev, 
                  attendees: e.target.value.split(',').map(email => email.trim()).filter(Boolean)
                }))}
                placeholder="john@example.com, jane@example.com"
                className="min-h-[60px] border-[rgb(226,232,240)] focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              />
            </div>

            <div className="flex flex-col sm:flex-row gap-3 pt-4">
              <Button
                onClick={createEvent}
                disabled={isLoading || !createEventData.title || !createEventData.startDate}
                className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white font-medium h-11 touch-manipulation"
                aria-label="Create calendar event and send invites"
              >
                {isLoading ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <Calendar className="w-4 h-4 mr-2" />
                    Create & Send Invites
                  </>
                )}
              </Button>
              <Button
                variant="outline"
                onClick={() => setShowCreateForm(false)}
                className="border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)] h-11 touch-manipulation"
              >
                Cancel
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Upcoming Events */}
      {events.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="font-medium text-[rgb(15,23,42)]">Upcoming Trip Events</CardTitle>
            <CardDescription className="text-[rgb(100,116,139)]">
              Your scheduled off-road adventures
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {events.slice(0, 5).map((event) => (
                <div
                  key={event.id}
                  className="flex items-start gap-3 p-4 rounded-lg border border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)] transition-colors"
                >
                  <Calendar className="w-5 h-5 text-[rgb(34,139,34)] mt-0.5 flex-shrink-0" />
                  <div className="flex-1 min-w-0">
                    <h4 className="font-medium text-[rgb(15,23,42)] truncate">{event.summary}</h4>
                    <div className="flex items-center gap-2 mt-1 text-sm text-[rgb(100,116,139)]">
                      <Clock className="w-4 h-4" />
                      <span>{formatEventTime(event)}</span>
                    </div>
                    {event.location && (
                      <div className="flex items-center gap-2 mt-1 text-sm text-[rgb(100,116,139)]">
                        <MapPin className="w-4 h-4" />
                        <span className="truncate">{event.location}</span>
                      </div>
                    )}
                    {event.attendees && event.attendees.length > 0 && (
                      <div className="flex items-center gap-2 mt-2">
                        <Users className="w-4 h-4 text-[rgb(100,116,139)]" />
                        <div className="flex flex-wrap gap-1">
                          {event.attendees.slice(0, 3).map((attendee, index) => (
                            <Badge
                              key={index}
                              variant="secondary"
                              className="text-xs bg-[rgb(241,245,249)] text-[rgb(100,116,139)]"
                            >
                              {attendee.displayName || attendee.email.split('@')[0]}
                            </Badge>
                          ))}
                          {event.attendees.length > 3 && (
                            <Badge
                              variant="secondary"
                              className="text-xs bg-[rgb(241,245,249)] text-[rgb(100,116,139)]"
                            >
                              +{event.attendees.length - 3} more
                            </Badge>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Availability Check */}
      {availability.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="font-medium text-[rgb(15,23,42)]">Group Availability</CardTitle>
            <CardDescription className="text-[rgb(100,116,139)]">
              Check when your group members are free
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {availability.map((person) => (
                <div
                  key={person.email}
                  className="flex items-center justify-between p-3 rounded-lg border border-[rgb(226,232,240)]"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-[rgb(34,139,34)] text-white flex items-center justify-center text-sm font-medium">
                      {person.email.charAt(0).toUpperCase()}
                    </div>
                    <span className="font-medium text-[rgb(15,23,42)]">
                      {person.email.split('@')[0]}
                    </span>
                  </div>
                  <Badge
                    variant={person.busy.length === 0 ? "default" : "secondary"}
                    className={
                      person.busy.length === 0
                        ? "bg-[rgb(34,139,34)] text-white"
                        : "bg-[rgb(245,158,11)] text-white"
                    }
                  >
                    {person.busy.length === 0 ? "Available" : `${person.busy.length} conflicts`}
                  </Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Empty State */}
      {events.length === 0 && !showCreateForm && (
        <Card>
          <CardContent className="text-center py-12">
            <Calendar className="w-12 h-12 mx-auto mb-4 text-[rgb(148,163,184)]" />
            <h3 className="font-medium text-[rgb(15,23,42)] mb-2">No upcoming trip events</h3>
            <p className="text-[rgb(100,116,139)] mb-6">
              Create your first off-road adventure and invite your group
            </p>
            <Button
              onClick={() => setShowCreateForm(true)}
              className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white font-medium h-11 touch-manipulation"
            >
              <Calendar className="w-4 h-4 mr-2" />
              Create Trip Event
            </Button>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

