'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Skeleton } from '@/components/ui/skeleton';
import { 
  Cloud, 
  Sun, 
  CloudRain, 
  CloudSnow, 
  CloudLightning, 
  Wind, 
  Eye, 
  Droplets, 
  Thermometer,
  AlertTriangle,
  RefreshCw,
  MapPin
} from 'lucide-react';

interface WeatherData {
  current: {
    temp: number;
    feels_like: number;
    humidity: number;
    visibility: number;
    wind_speed: number;
    wind_deg: number;
    weather: Array<{
      id: number;
      main: string;
      description: string;
      icon: string;
    }>;
  };
  daily: Array<{
    dt: number;
    temp: {
      min: number;
      max: number;
    };
    weather: Array<{
      id: number;
      main: string;
      description: string;
      icon: string;
    }>;
    pop: number;
  }>;
  alerts?: Array<{
    sender_name: string;
    event: string;
    start: number;
    end: number;
    description: string;
  }>;
}

interface WeatherServiceProps {
  latitude: number;
  longitude: number;
  locationName?: string;
  onWeatherUpdate?: (weather: WeatherData) => void;
}

interface WeatherError {
  message: string;
  code?: string;
}

const WEATHER_ICONS: Record<string, React.ComponentType<any>> = {
  '01d': Sun,
  '01n': Sun,
  '02d': Cloud,
  '02n': Cloud,
  '03d': Cloud,
  '03n': Cloud,
  '04d': Cloud,
  '04n': Cloud,
  '09d': CloudRain,
  '09n': CloudRain,
  '10d': CloudRain,
  '10n': CloudRain,
  '11d': CloudLightning,
  '11n': CloudLightning,
  '13d': CloudSnow,
  '13n': CloudSnow,
  '50d': Cloud,
  '50n': Cloud,
};

const WeatherSkeleton = () => (
  <div className="space-y-4">
    <Skeleton className="h-8 w-48" />
    <div className="grid grid-cols-2 gap-4">
      <Skeleton className="h-24" />
      <Skeleton className="h-24" />
    </div>
    <Skeleton className="h-32" />
    <div className="grid grid-cols-7 gap-2">
      {Array.from({ length: 7 }).map((_, i) => (
        <Skeleton key={i} className="h-20" />
      ))}
    </div>
  </div>
);

const WeatherAlert = ({ alert }: { alert: WeatherData['alerts'][0] }) => (
  <Alert className="border-[rgb(239,68,68)] bg-red-50 mb-4">
    <AlertTriangle className="h-4 w-4 text-[rgb(239,68,68)]" />
    <AlertDescription className="font-medium text-[rgb(15,23,42)]">
      <div className="font-semibold text-[rgb(239,68,68)]">{alert.event}</div>
      <div className="text-sm mt-1">{alert.description}</div>
      <div className="text-xs text-gray-600 mt-2">
        {new Date(alert.start * 1000).toLocaleDateString()} - {new Date(alert.end * 1000).toLocaleDateString()}
      </div>
    </AlertDescription>
  </Alert>
);

const CurrentWeather = ({ weather }: { weather: WeatherData['current'] }) => {
  const IconComponent = WEATHER_ICONS[weather.weather[0]?.icon] || Cloud;

  return (
    <Card className="shadow-md border-[rgb(226,232,240)]">
      <CardHeader className="pb-3">
        <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)] flex items-center gap-2">
          <IconComponent className="h-6 w-6 text-[rgb(34,139,34)]" />
          Current Conditions
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-3xl font-bold text-[rgb(15,23,42)]">
              {Math.round(weather.temp)}°F
            </div>
            <div className="text-sm text-gray-600">
              Feels like {Math.round(weather.feels_like)}°F
            </div>
            <div className="text-sm font-medium text-[rgb(15,23,42)] capitalize">
              {weather.weather[0]?.description}
            </div>
          </div>
          <IconComponent className="h-16 w-16 text-[rgb(34,139,34)]" />
        </div>

        <div className="grid grid-cols-2 gap-4 pt-4 border-t border-[rgb(226,232,240)]">
          <div className="flex items-center gap-2">
            <Wind className="h-4 w-4 text-[rgb(34,139,34)]" />
            <div>
              <div className="text-sm font-medium text-[rgb(15,23,42)]">
                {Math.round(weather.wind_speed)} mph
              </div>
              <div className="text-xs text-gray-600">Wind</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Droplets className="h-4 w-4 text-[rgb(34,139,34)]" />
            <div>
              <div className="text-sm font-medium text-[rgb(15,23,42)]">
                {weather.humidity}%
              </div>
              <div className="text-xs text-gray-600">Humidity</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Eye className="h-4 w-4 text-[rgb(34,139,34)]" />
            <div>
              <div className="text-sm font-medium text-[rgb(15,23,42)]">
                {Math.round(weather.visibility / 1000)} km
              </div>
              <div className="text-xs text-gray-600">Visibility</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Thermometer className="h-4 w-4 text-[rgb(34,139,34)]" />
            <div>
              <div className="text-sm font-medium text-[rgb(15,23,42)]">
                {Math.round(weather.feels_like)}°F
              </div>
              <div className="text-xs text-gray-600">Feels like</div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

const WeatherForecast = ({ forecast }: { forecast: WeatherData['daily'] }) => (
  <Card className="shadow-md border-[rgb(226,232,240)]">
    <CardHeader className="pb-3">
      <CardTitle className="text-lg font-semibold text-[rgb(15,23,42)]">
        7-Day Forecast
      </CardTitle>
    </CardHeader>
    <CardContent>
      <div className="grid grid-cols-1 sm:grid-cols-7 gap-3">
        {forecast.slice(0, 7).map((day, index) => {
          const IconComponent = WEATHER_ICONS[day.weather[0]?.icon] || Cloud;
          const date = new Date(day.dt * 1000);
          const dayName = index === 0 ? 'Today' : date.toLocaleDateString('en-US', { weekday: 'short' });

          return (
            <div 
              key={day.dt} 
              className="text-center p-3 rounded-lg bg-[rgb(248,250,252)] border border-[rgb(226,232,240)]"
            >
              <div className="text-sm font-medium text-[rgb(15,23,42)] mb-2">
                {dayName}
              </div>
              <IconComponent className="h-8 w-8 text-[rgb(34,139,34)] mx-auto mb-2" />
              <div className="text-xs text-gray-600 mb-1 capitalize">
                {day.weather[0]?.description}
              </div>
              <div className="text-sm font-semibold text-[rgb(15,23,42)]">
                {Math.round(day.temp.max)}°
              </div>
              <div className="text-xs text-gray-600">
                {Math.round(day.temp.min)}°
              </div>
              {day.pop > 0 && (
                <div className="text-xs text-[rgb(34,139,34)] mt-1">
                  {Math.round(day.pop * 100)}%
                </div>
              )}
            </div>
          );
        })}
      </div>
    </CardContent>
  </Card>
);

export default function OpenWeatherMapService({ 
  latitude, 
  longitude, 
  locationName,
  onWeatherUpdate 
}: WeatherServiceProps) {
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<WeatherError | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchWeather = async () => {
    try {
      setLoading(true);
      setError(null);

      const apiKey = process.env.NEXT_PUBLIC_OPENWEATHER_API_KEY;
      if (!apiKey) {
        throw new Error('OpenWeather API key not configured');
      }

      const response = await fetch(
        `https://api.openweathermap.org/data/3.0/onecall?lat=${latitude}&lon=${longitude}&exclude=minutely,hourly&appid=${apiKey}&units=imperial`,
        {
          headers: {
            'Cache-Control': 'no-cache',
          },
        }
      );

      if (!response.ok) {
        if (response.status === 401) {
          throw new Error('Invalid API key');
        } else if (response.status === 404) {
          throw new Error('Location not found');
        } else {
          throw new Error(`Weather service error: ${response.status}`);
        }
      }

      const data: WeatherData = await response.json();
      setWeather(data);
      setLastUpdated(new Date());
      onWeatherUpdate?.(data);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch weather data';
      setError({ message: errorMessage });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (latitude && longitude) {
      fetchWeather();
    }
  }, [latitude, longitude]);

  const handleRefresh = () => {
    fetchWeather();
  };

  if (loading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Weather</h2>
        </div>
        <WeatherSkeleton />
      </div>
    );
  }

  if (error) {
    return (
      <Card className="shadow-md border-[rgb(226,232,240)]">
        <CardContent className="p-6 text-center">
          <AlertTriangle className="h-12 w-12 text-[rgb(239,68,68)] mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">
            Weather Unavailable
          </h3>
          <p className="text-gray-600 mb-4">{error.message}</p>
          <Button 
            onClick={handleRefresh}
            className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white font-medium"
            aria-label="Retry fetching weather data"
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Try Again
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (!weather) {
    return null;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Weather</h2>
          {locationName && (
            <div className="flex items-center gap-1 text-sm text-gray-600">
              <MapPin className="h-4 w-4" />
              {locationName}
            </div>
          )}
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={handleRefresh}
          className="border-[rgb(226,232,240)] hover:bg-[rgb(248,250,252)]"
          aria-label="Refresh weather data"
        >
          <RefreshCw className="h-4 w-4" />
        </Button>
      </div>

      {weather.alerts && weather.alerts.length > 0 && (
        <div className="space-y-2">
          {weather.alerts.map((alert, index) => (
            <WeatherAlert key={index} alert={alert} />
          ))}
        </div>
      )}

      <CurrentWeather weather={weather.current} />

      <WeatherForecast forecast={weather.daily} />

      {lastUpdated && (
        <div className="text-xs text-gray-500 text-center">
          Last updated: {lastUpdated.toLocaleTimeString()}
        </div>
      )}
    </div>
  );
}

