'use client';

import { useState, useEffect } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface Group {
  id: string;
  name: string;
  description?: string;
  created_by: string;
  created_at: string;
  updated_at: string;
}

interface GroupMember {
  id: string;
  group_id: string;
  user_id: string;
  role: 'admin' | 'member';
  joined_at: string;
  user?: {
    id: string;
    email: string;
    full_name?: string;
  };
}

interface CreateGroupData {
  name: string;
  description?: string;
}

interface InviteData {
  email: string;
  role: 'admin' | 'member';
}

interface GroupAPIResponse<T> {
  data: T | null;
  error: string | null;
  loading: boolean;
}

// Custom hook for group operations
export function useGroupAPI() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const supabase = createClientComponentClient();

  // Create a new group
  const createGroup = async (groupData: CreateGroupData): Promise<GroupAPIResponse<Group>> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('groups')
        .insert({
          name: groupData.name,
          description: groupData.description,
          created_by: user.id,
        })
        .select()
        .single();

      if (error) throw error;

      // Add creator as admin member
      await supabase
        .from('group_members')
        .insert({
          group_id: data.id,
          user_id: user.id,
          role: 'admin',
        });

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to create group';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Get user's groups
  const getUserGroups = async (): Promise<GroupAPIResponse<Group[]>> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('groups')
        .select(`
          *,
          group_members!inner(user_id)
        `)
        .eq('group_members.user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch groups';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Get group by ID
  const getGroup = async (groupId: string): Promise<GroupAPIResponse<Group>> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('groups')
        .select('*')
        .eq('id', groupId)
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch group';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Update group
  const updateGroup = async (groupId: string, updates: Partial<CreateGroupData>): Promise<GroupAPIResponse<Group>> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('groups')
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq('id', groupId)
        .select()
        .single();

      if (error) throw error;

      setLoading(false);
      return { data, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update group';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Delete group
  const deleteGroup = async (groupId: string): Promise<GroupAPIResponse<boolean>> => {
    setLoading(true);
    setError(null);

    try {
      // First delete all group members
      await supabase
        .from('group_members')
        .delete()
        .eq('group_id', groupId);

      // Then delete the group
      const { error } = await supabase
        .from('groups')
        .delete()
        .eq('id', groupId);

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to delete group';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Get group members
  const getGroupMembers = async (groupId: string): Promise<GroupAPIResponse<GroupMember[]>> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('group_members')
        .select(`
          *,
          user:users(id, email, full_name)
        `)
        .eq('group_id', groupId)
        .order('joined_at', { ascending: true });

      if (error) throw error;

      setLoading(false);
      return { data: data || [], error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch group members';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Invite user to group
  const inviteToGroup = async (groupId: string, inviteData: InviteData): Promise<GroupAPIResponse<boolean>> => {
    setLoading(true);
    setError(null);

    try {
      // Check if user exists
      const { data: userData, error: userError } = await supabase
        .from('users')
        .select('id')
        .eq('email', inviteData.email)
        .single();

      if (userError || !userData) {
        throw new Error('User not found with this email');
      }

      // Check if user is already a member
      const { data: existingMember } = await supabase
        .from('group_members')
        .select('id')
        .eq('group_id', groupId)
        .eq('user_id', userData.id)
        .single();

      if (existingMember) {
        throw new Error('User is already a member of this group');
      }

      // Add user to group
      const { error } = await supabase
        .from('group_members')
        .insert({
          group_id: groupId,
          user_id: userData.id,
          role: inviteData.role,
        });

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to invite user';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Remove member from group
  const removeMember = async (groupId: string, userId: string): Promise<GroupAPIResponse<boolean>> => {
    setLoading(true);
    setError(null);

    try {
      const { error } = await supabase
        .from('group_members')
        .delete()
        .eq('group_id', groupId)
        .eq('user_id', userId);

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to remove member';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Update member role
  const updateMemberRole = async (groupId: string, userId: string, role: 'admin' | 'member'): Promise<GroupAPIResponse<boolean>> => {
    setLoading(true);
    setError(null);

    try {
      const { error } = await supabase
        .from('group_members')
        .update({ role })
        .eq('group_id', groupId)
        .eq('user_id', userId);

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update member role';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  // Leave group
  const leaveGroup = async (groupId: string): Promise<GroupAPIResponse<boolean>> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { error } = await supabase
        .from('group_members')
        .delete()
        .eq('group_id', groupId)
        .eq('user_id', user.id);

      if (error) throw error;

      setLoading(false);
      return { data: true, error: null, loading: false };
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to leave group';
      setError(errorMessage);
      setLoading(false);
      return { data: null, error: errorMessage, loading: false };
    }
  };

  return {
    loading,
    error,
    createGroup,
    getUserGroups,
    getGroup,
    updateGroup,
    deleteGroup,
    getGroupMembers,
    inviteToGroup,
    removeMember,
    updateMemberRole,
    leaveGroup,
  };
}

