'use client';

import { useState, useCallback } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

// Types
interface RSVPStatus {
  id: string;
  trip_id: string;
  user_id: string;
  status: 'attending' | 'not_attending' | 'maybe' | 'pending';
  dietary_restrictions?: string;
  notes?: string;
  created_at: string;
  updated_at: string;
}

interface RSVPResponse {
  id: string;
  trip_id: string;
  user_id: string;
  status: 'attending' | 'not_attending' | 'maybe' | 'pending';
  dietary_restrictions?: string;
  notes?: string;
  user?: {
    id: string;
    email: string;
    full_name?: string;
    avatar_url?: string;
  };
  created_at: string;
  updated_at: string;
}

interface CreateRSVPRequest {
  trip_id: string;
  status: 'attending' | 'not_attending' | 'maybe';
  dietary_restrictions?: string;
  notes?: string;
}

interface UpdateRSVPRequest {
  status?: 'attending' | 'not_attending' | 'maybe';
  dietary_restrictions?: string;
  notes?: string;
}

interface RSVPSummary {
  attending: number;
  not_attending: number;
  maybe: number;
  pending: number;
  total: number;
}

interface RSVPAPIError {
  message: string;
  code?: string;
  details?: any;
}

// Custom hook for RSVP API operations
export function useRSVPAPI() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<RSVPAPIError | null>(null);
  const supabase = createClientComponentClient();

  const handleError = useCallback((error: any): RSVPAPIError => {
    console.error('RSVP API Error:', error);

    if (error?.message) {
      return { message: error.message, code: error.code, details: error };
    }

    return { 
      message: 'An unexpected error occurred. Please try again.',
      details: error 
    };
  }, []);

  // Create or update RSVP
  const createOrUpdateRSVP = useCallback(async (
    tripId: string, 
    rsvpData: CreateRSVPRequest
  ): Promise<RSVPResponse | null> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      // Check if RSVP already exists
      const { data: existingRSVP } = await supabase
        .from('rsvps')
        .select('id')
        .eq('trip_id', tripId)
        .eq('user_id', user.id)
        .single();

      let result;

      if (existingRSVP) {
        // Update existing RSVP
        const { data, error } = await supabase
          .from('rsvps')
          .update({
            status: rsvpData.status,
            dietary_restrictions: rsvpData.dietary_restrictions,
            notes: rsvpData.notes,
            updated_at: new Date().toISOString()
          })
          .eq('id', existingRSVP.id)
          .select(`
            *,
            user:profiles(id, email, full_name, avatar_url)
          `)
          .single();

        if (error) throw error;
        result = data;
      } else {
        // Create new RSVP
        const { data, error } = await supabase
          .from('rsvps')
          .insert({
            trip_id: tripId,
            user_id: user.id,
            status: rsvpData.status,
            dietary_restrictions: rsvpData.dietary_restrictions,
            notes: rsvpData.notes
          })
          .select(`
            *,
            user:profiles(id, email, full_name, avatar_url)
          `)
          .single();

        if (error) throw error;
        result = data;
      }

      return result;
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return null;
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  // Get RSVP for current user and trip
  const getUserRSVP = useCallback(async (tripId: string): Promise<RSVPResponse | null> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('rsvps')
        .select(`
          *,
          user:profiles(id, email, full_name, avatar_url)
        `)
        .eq('trip_id', tripId)
        .eq('user_id', user.id)
        .single();

      if (error && error.code !== 'PGRST116') { // PGRST116 is "not found"
        throw error;
      }

      return data || null;
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return null;
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  // Get all RSVPs for a trip
  const getTripRSVPs = useCallback(async (tripId: string): Promise<RSVPResponse[]> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('rsvps')
        .select(`
          *,
          user:profiles(id, email, full_name, avatar_url)
        `)
        .eq('trip_id', tripId)
        .order('created_at', { ascending: true });

      if (error) throw error;

      return data || [];
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return [];
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  // Get RSVP summary for a trip
  const getRSVPSummary = useCallback(async (tripId: string): Promise<RSVPSummary | null> => {
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('rsvps')
        .select('status')
        .eq('trip_id', tripId);

      if (error) throw error;

      const summary: RSVPSummary = {
        attending: 0,
        not_attending: 0,
        maybe: 0,
        pending: 0,
        total: data?.length || 0
      };

      data?.forEach((rsvp) => {
        summary[rsvp.status as keyof Omit<RSVPSummary, 'total'>]++;
      });

      return summary;
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return null;
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  // Delete RSVP
  const deleteRSVP = useCallback(async (tripId: string): Promise<boolean> => {
    setLoading(true);
    setError(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('User not authenticated');
      }

      const { error } = await supabase
        .from('rsvps')
        .delete()
        .eq('trip_id', tripId)
        .eq('user_id', user.id);

      if (error) throw error;

      return true;
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return false;
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  // Send RSVP reminders
  const sendRSVPReminders = useCallback(async (tripId: string): Promise<boolean> => {
    setLoading(true);
    setError(null);

    try {
      // Get trip members who haven't responded
      const { data: tripMembers } = await supabase
        .from('trip_members')
        .select(`
          user_id,
          user:profiles(id, email, full_name)
        `)
        .eq('trip_id', tripId);

      const { data: rsvps } = await supabase
        .from('rsvps')
        .select('user_id')
        .eq('trip_id', tripId);

      const respondedUserIds = new Set(rsvps?.map(r => r.user_id) || []);
      const pendingMembers = tripMembers?.filter(
        member => !respondedUserIds.has(member.user_id)
      ) || [];

      // Create pending RSVPs for members who haven't responded
      if (pendingMembers.length > 0) {
        const pendingRSVPs = pendingMembers.map(member => ({
          trip_id: tripId,
          user_id: member.user_id,
          status: 'pending' as const
        }));

        const { error } = await supabase
          .from('rsvps')
          .upsert(pendingRSVPs, {
            onConflict: 'trip_id,user_id',
            ignoreDuplicates: true
          });

        if (error) throw error;
      }

      // Here you would typically trigger email notifications
      // This could be done via a Supabase Edge Function or external service

      return true;
    } catch (err) {
      const apiError = handleError(err);
      setError(apiError);
      return false;
    } finally {
      setLoading(false);
    }
  }, [supabase, handleError]);

  return {
    loading,
    error,
    createOrUpdateRSVP,
    getUserRSVP,
    getTripRSVPs,
    getRSVPSummary,
    deleteRSVP,
    sendRSVPReminders,
    clearError: () => setError(null)
  };
}

// Main RSVP API component
export default function RSVPAPI() {
  const {
    loading,
    error,
    createOrUpdateRSVP,
    getUserRSVP,
    getTripRSVPs,
    getRSVPSummary,
    deleteRSVP,
    sendRSVPReminders,
    clearError
  } = useRSVPAPI();

  return (
    <div className="w-full max-w-md mx-auto p-4 bg-white rounded-lg shadow-md">
      <div className="space-y-4">
        <div className="text-center">
          <h2 className="text-xl font-semibold text-slate-900 font-medium">
            RSVP API
          </h2>
          <p className="text-sm text-slate-600 mt-1">
            Manage trip RSVPs and responses
          </p>
        </div>

        {error && (
          <div 
            className="p-3 bg-red-50 border border-red-200 rounded-md"
            role="alert"
            aria-live="polite"
          >
            <div className="flex items-center justify-between">
              <p className="text-sm text-red-800 font-medium">
                {error.message}
              </p>
              <button
                onClick={clearError}
                className="text-[rgb(255, 255, 255)] hover:text-red-800 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 rounded"
                aria-label="Dismiss error"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          </div>
        )}

        {loading && (
          <div className="flex items-center justify-center p-4">
            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-green-600"></div>
            <span className="ml-2 text-sm text-slate-600">Processing...</span>
          </div>
        )}

        <div className="space-y-2">
          <h3 className="text-sm font-medium text-slate-700">Available Methods:</h3>
          <ul className="text-xs text-slate-600 space-y-1 pl-4">
            <li>• createOrUpdateRSVP(tripId, rsvpData)</li>
            <li>• getUserRSVP(tripId)</li>
            <li>• getTripRSVPs(tripId)</li>
            <li>• getRSVPSummary(tripId)</li>
            <li>• deleteRSVP(tripId)</li>
            <li>• sendRSVPReminders(tripId)</li>
          </ul>
        </div>

        <div className="text-xs text-slate-500 text-center">
          Use the useRSVPAPI hook to access these methods in your components
        </div>
      </div>
    </div>
  );
}

