'use client';

import React from 'react';
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

export interface Task {
  id: string;
  trip_id: string;
  title: string;
  description?: string;
  assigned_to?: string;
  assigned_to_name?: string;
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other';
  priority: 'low' | 'medium' | 'high';
  due_date?: string;
  completed: boolean;
  completed_at?: string;
  completed_by?: string;
  created_at: string;
  updated_at: string;
  created_by: string;
}

export interface CreateTaskRequest {
  trip_id: string;
  title: string;
  description?: string;
  assigned_to?: string;
  category: Task['category'];
  priority: Task['priority'];
  due_date?: string;
}

export interface UpdateTaskRequest {
  title?: string;
  description?: string;
  assigned_to?: string;
  category?: Task['category'];
  priority?: Task['priority'];
  due_date?: string;
  completed?: boolean;
}

export interface TaskFilters {
  trip_id?: string;
  assigned_to?: string;
  category?: Task['category'];
  priority?: Task['priority'];
  completed?: boolean;
}

export interface TaskStats {
  total: number;
  completed: number;
  pending: number;
  overdue: number;
  by_category: Record<Task['category'], number>;
  by_priority: Record<Task['priority'], number>;
}

class TaskAPI {
  async getTasks(filters: TaskFilters = {}): Promise<Task[]> {
    try {
      let query = supabase
        .from('tasks')
        .select(`
          *,
          assigned_user:profiles!tasks_assigned_to_fkey(
            id,
            display_name
          )
        `)
        .order('created_at', { ascending: false });

      if (filters.trip_id) {
        query = query.eq('trip_id', filters.trip_id);
      }

      if (filters.assigned_to) {
        query = query.eq('assigned_to', filters.assigned_to);
      }

      if (filters.category) {
        query = query.eq('category', filters.category);
      }

      if (filters.priority) {
        query = query.eq('priority', filters.priority);
      }

      if (filters.completed !== undefined) {
        query = query.eq('completed', filters.completed);
      }

      const { data, error } = await query;

      if (error) {
        throw new Error(`Failed to fetch tasks: ${error.message}`);
      }

      return (data || []).map(task => ({
        ...task,
        assigned_to_name: task.assigned_user?.display_name || null
      }));
    } catch (error) {
      console.error('Error fetching tasks:', error);
      throw error;
    }
  }

  async getTask(id: string): Promise<Task | null> {
    try {
      const { data, error } = await supabase
        .from('tasks')
        .select(`
          *,
          assigned_user:profiles!tasks_assigned_to_fkey(
            id,
            display_name
          )
        `)
        .eq('id', id)
        .single();

      if (error) {
        if (error.code === 'PGRST116') {
          return null;
        }
        throw new Error(`Failed to fetch task: ${error.message}`);
      }

      return {
        ...data,
        assigned_to_name: data.assigned_user?.display_name || null
      };
    } catch (error) {
      console.error('Error fetching task:', error);
      throw error;
    }
  }

  async createTask(taskData: CreateTaskRequest): Promise<Task> {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const newTask = {
        ...taskData,
        completed: false,
        created_by: user.id,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };

      const { data, error } = await supabase
        .from('tasks')
        .insert(newTask)
        .select(`
          *,
          assigned_user:profiles!tasks_assigned_to_fkey(
            id,
            display_name
          )
        `)
        .single();

      if (error) {
        throw new Error(`Failed to create task: ${error.message}`);
      }

      return {
        ...data,
        assigned_to_name: data.assigned_user?.display_name || null
      };
    } catch (error) {
      console.error('Error creating task:', error);
      throw error;
    }
  }

  async updateTask(id: string, updates: UpdateTaskRequest): Promise<Task> {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const updateData = {
        ...updates,
        updated_at: new Date().toISOString()
      };

      if (updates.completed !== undefined && updates.completed) {
        updateData.completed_at = new Date().toISOString();
        updateData.completed_by = user.id;
      } else if (updates.completed === false) {
        updateData.completed_at = null;
        updateData.completed_by = null;
      }

      const { data, error } = await supabase
        .from('tasks')
        .update(updateData)
        .eq('id', id)
        .select(`
          *,
          assigned_user:profiles!tasks_assigned_to_fkey(
            id,
            display_name
          )
        `)
        .single();

      if (error) {
        throw new Error(`Failed to update task: ${error.message}`);
      }

      return {
        ...data,
        assigned_to_name: data.assigned_user?.display_name || null
      };
    } catch (error) {
      console.error('Error updating task:', error);
      throw error;
    }
  }

  async deleteTask(id: string): Promise<void> {
    try {
      const { error } = await supabase
        .from('tasks')
        .delete()
        .eq('id', id);

      if (error) {
        throw new Error(`Failed to delete task: ${error.message}`);
      }
    } catch (error) {
      console.error('Error deleting task:', error);
      throw error;
    }
  }

  async completeTask(id: string): Promise<Task> {
    return this.updateTask(id, { completed: true });
  }

  async uncompleteTask(id: string): Promise<Task> {
    return this.updateTask(id, { completed: false });
  }

  async assignTask(id: string, userId: string): Promise<Task> {
    return this.updateTask(id, { assigned_to: userId });
  }

  async unassignTask(id: string): Promise<Task> {
    return this.updateTask(id, { assigned_to: null });
  }

  async getTaskStats(tripId: string): Promise<TaskStats> {
    try {
      const tasks = await this.getTasks({ trip_id: tripId });

      const stats: TaskStats = {
        total: tasks.length,
        completed: 0,
        pending: 0,
        overdue: 0,
        by_category: {
          food: 0,
          equipment: 0,
          logistics: 0,
          safety: 0,
          other: 0
        },
        by_priority: {
          low: 0,
          medium: 0,
          high: 0
        }
      };

      const now = new Date();

      tasks.forEach(task => {
        if (task.completed) {
          stats.completed++;
        } else {
          stats.pending++;

          if (task.due_date && new Date(task.due_date) < now) {
            stats.overdue++;
          }
        }

        stats.by_category[task.category]++;
        stats.by_priority[task.priority]++;
      });

      return stats;
    } catch (error) {
      console.error('Error fetching task stats:', error);
      throw error;
    }
  }

  async bulkUpdateTasks(taskIds: string[], updates: UpdateTaskRequest): Promise<Task[]> {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const updateData = {
        ...updates,
        updated_at: new Date().toISOString()
      };

      if (updates.completed !== undefined && updates.completed) {
        updateData.completed_at = new Date().toISOString();
        updateData.completed_by = user.id;
      } else if (updates.completed === false) {
        updateData.completed_at = null;
        updateData.completed_by = null;
      }

      const { data, error } = await supabase
        .from('tasks')
        .update(updateData)
        .in('id', taskIds)
        .select(`
          *,
          assigned_user:profiles!tasks_assigned_to_fkey(
            id,
            display_name
          )
        `);

      if (error) {
        throw new Error(`Failed to bulk update tasks: ${error.message}`);
      }

      return (data || []).map(task => ({
        ...task,
        assigned_to_name: task.assigned_user?.display_name || null
      }));
    } catch (error) {
      console.error('Error bulk updating tasks:', error);
      throw error;
    }
  }

  async duplicateTask(id: string, tripId?: string): Promise<Task> {
    try {
      const originalTask = await this.getTask(id);

      if (!originalTask) {
        throw new Error('Task not found');
      }

      const duplicateData: CreateTaskRequest = {
        trip_id: tripId || originalTask.trip_id,
        title: `${originalTask.title} (Copy)`,
        description: originalTask.description,
        category: originalTask.category,
        priority: originalTask.priority,
        due_date: originalTask.due_date
      };

      return this.createTask(duplicateData);
    } catch (error) {
      console.error('Error duplicating task:', error);
      throw error;
    }
  }

  subscribeToTasks(tripId: string, callback: (tasks: Task[]) => void) {
    const subscription = supabase
      .channel(`tasks-${tripId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'tasks',
          filter: `trip_id=eq.${tripId}`
        },
        () => {
          this.getTasks({ trip_id: tripId }).then(callback);
        }
      )
      .subscribe();

    return () => {
      subscription.unsubscribe();
    };
  }
}

export const taskAPI = new TaskAPI();
export default taskAPI;

