'use client';

import { useState, useEffect } from 'react';

// Types and Interfaces
interface WeatherCondition {
  id: number;
  main: string;
  description: string;
  icon: string;
}

interface CurrentWeather {
  location: string;
  temperature: number;
  feelsLike: number;
  humidity: number;
  windSpeed: number;
  windDirection: number;
  visibility: number;
  pressure: number;
  uvIndex: number;
  condition: WeatherCondition;
  timestamp: number;
}

interface DailyForecast {
  date: string;
  high: number;
  low: number;
  condition: WeatherCondition;
  precipitation: number;
  windSpeed: number;
  humidity: number;
}

interface WeatherAlert {
  id: string;
  title: string;
  description: string;
  severity: 'minor' | 'moderate' | 'severe' | 'extreme';
  start: number;
  end: number;
  areas: string[];
}

interface WeatherData {
  current: CurrentWeather | null;
  forecast: DailyForecast[];
  alerts: WeatherAlert[];
  lastUpdated: number;
}

interface WeatherServiceConfig {
  apiKey: string;
  baseUrl: string;
  units: 'metric' | 'imperial';
  language: string;
}

interface LocationCoords {
  latitude: number;
  longitude: number;
}

// Weather Service Class
class WeatherService {
  private config: WeatherServiceConfig;
  private cache: Map<string, { data: WeatherData; expiry: number }>;
  private readonly CACHE_DURATION = 10 * 60 * 1000; // 10 minutes

  constructor(config: WeatherServiceConfig) {
    this.config = config;
    this.cache = new Map();
  }

  private getCacheKey(coords: LocationCoords): string {
    return `${coords.latitude.toFixed(4)},${coords.longitude.toFixed(4)}`;
  }

  private isValidCache(cacheEntry: { data: WeatherData; expiry: number }): boolean {
    return Date.now() < cacheEntry.expiry;
  }

  private async fetchWithRetry(url: string, retries = 3): Promise<Response> {
    for (let i = 0; i < retries; i++) {
      try {
        const response = await fetch(url, {
          headers: {
            'Accept': 'application/json',
          },
        });

        if (response.ok) {
          return response;
        }

        if (response.status === 429) {
          // Rate limited, wait before retry
          await new Promise(resolve => setTimeout(resolve, 1000 * (i + 1)));
          continue;
        }

        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      } catch (error) {
        if (i === retries - 1) throw error;
        await new Promise(resolve => setTimeout(resolve, 1000 * (i + 1)));
      }
    }
    throw new Error('Max retries exceeded');
  }

  private mapWeatherCondition(condition: any): WeatherCondition {
    return {
      id: condition.id || 0,
      main: condition.main || 'Unknown',
      description: condition.description || 'No description',
      icon: condition.icon || '01d',
    };
  }

  private mapCurrentWeather(data: any, location: string): CurrentWeather {
    return {
      location,
      temperature: Math.round(data.main?.temp || 0),
      feelsLike: Math.round(data.main?.feels_like || 0),
      humidity: data.main?.humidity || 0,
      windSpeed: Math.round((data.wind?.speed || 0) * 3.6), // Convert m/s to km/h
      windDirection: data.wind?.deg || 0,
      visibility: Math.round((data.visibility || 0) / 1000), // Convert m to km
      pressure: data.main?.pressure || 0,
      uvIndex: 0, // UV index requires separate API call
      condition: this.mapWeatherCondition(data.weather?.[0] || {}),
      timestamp: Date.now(),
    };
  }

  private mapDailyForecast(data: any): DailyForecast[] {
    if (!data.list) return [];

    const dailyData = new Map<string, any>();

    // Group forecast data by date
    data.list.forEach((item: any) => {
      const date = new Date(item.dt * 1000).toISOString().split('T')[0];
      if (!dailyData.has(date)) {
        dailyData.set(date, {
          date,
          temps: [],
          conditions: [],
          precipitation: 0,
          windSpeeds: [],
          humidity: [],
        });
      }

      const dayData = dailyData.get(date)!;
      dayData.temps.push(item.main.temp);
      dayData.conditions.push(item.weather[0]);
      dayData.precipitation += item.rain?.['3h'] || item.snow?.['3h'] || 0;
      dayData.windSpeeds.push(item.wind?.speed || 0);
      dayData.humidity.push(item.main.humidity);
    });

    return Array.from(dailyData.values()).slice(0, 7).map(day => ({
      date: day.date,
      high: Math.round(Math.max(...day.temps)),
      low: Math.round(Math.min(...day.temps)),
      condition: this.mapWeatherCondition(day.conditions[0]),
      precipitation: Math.round(day.precipitation),
      windSpeed: Math.round(day.windSpeeds.reduce((a: number, b: number) => a + b, 0) / day.windSpeeds.length * 3.6),
      humidity: Math.round(day.humidity.reduce((a: number, b: number) => a + b, 0) / day.humidity.length),
    }));
  }

  private mapWeatherAlerts(data: any): WeatherAlert[] {
    if (!data.alerts) return [];

    return data.alerts.map((alert: any) => ({
      id: alert.id || `alert-${Date.now()}`,
      title: alert.event || 'Weather Alert',
      description: alert.description || 'No description available',
      severity: this.mapAlertSeverity(alert.severity),
      start: alert.start * 1000,
      end: alert.end * 1000,
      areas: alert.areas || [],
    }));
  }

  private mapAlertSeverity(severity: string): 'minor' | 'moderate' | 'severe' | 'extreme' {
    const severityMap: Record<string, 'minor' | 'moderate' | 'severe' | 'extreme'> = {
      'minor': 'minor',
      'moderate': 'moderate',
      'severe': 'severe',
      'extreme': 'extreme',
    };
    return severityMap[severity?.toLowerCase()] || 'moderate';
  }

  async getCurrentWeather(coords: LocationCoords, locationName?: string): Promise<CurrentWeather> {
    const cacheKey = this.getCacheKey(coords);
    const cached = this.cache.get(cacheKey);

    if (cached && this.isValidCache(cached) && cached.data.current) {
      return cached.data.current;
    }

    const url = `${this.config.baseUrl}/weather?lat=${coords.latitude}&lon=${coords.longitude}&appid=${this.config.apiKey}&units=${this.config.units}&lang=${this.config.language}`;

    try {
      const response = await this.fetchWithRetry(url);
      const data = await response.json();

      const current = this.mapCurrentWeather(data, locationName || `${coords.latitude.toFixed(2)}, ${coords.longitude.toFixed(2)}`);

      // Update cache
      const existingCache = this.cache.get(cacheKey);
      const weatherData: WeatherData = {
        current,
        forecast: existingCache?.data.forecast || [],
        alerts: existingCache?.data.alerts || [],
        lastUpdated: Date.now(),
      };

      this.cache.set(cacheKey, {
        data: weatherData,
        expiry: Date.now() + this.CACHE_DURATION,
      });

      return current;
    } catch (error) {
      throw new Error(`Failed to fetch current weather: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  async getForecast(coords: LocationCoords): Promise<DailyForecast[]> {
    const cacheKey = this.getCacheKey(coords);
    const cached = this.cache.get(cacheKey);

    if (cached && this.isValidCache(cached) && cached.data.forecast.length > 0) {
      return cached.data.forecast;
    }

    const url = `${this.config.baseUrl}/forecast?lat=${coords.latitude}&lon=${coords.longitude}&appid=${this.config.apiKey}&units=${this.config.units}&lang=${this.config.language}`;

    try {
      const response = await this.fetchWithRetry(url);
      const data = await response.json();

      const forecast = this.mapDailyForecast(data);

      // Update cache
      const existingCache = this.cache.get(cacheKey);
      const weatherData: WeatherData = {
        current: existingCache?.data.current || null,
        forecast,
        alerts: existingCache?.data.alerts || [],
        lastUpdated: Date.now(),
      };

      this.cache.set(cacheKey, {
        data: weatherData,
        expiry: Date.now() + this.CACHE_DURATION,
      });

      return forecast;
    } catch (error) {
      throw new Error(`Failed to fetch forecast: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  async getWeatherAlerts(coords: LocationCoords): Promise<WeatherAlert[]> {
    const cacheKey = this.getCacheKey(coords);
    const cached = this.cache.get(cacheKey);

    if (cached && this.isValidCache(cached)) {
      return cached.data.alerts;
    }

    // Note: OpenWeatherMap's One Call API includes alerts, but requires a different endpoint
    const url = `${this.config.baseUrl}/onecall?lat=${coords.latitude}&lon=${coords.longitude}&appid=${this.config.apiKey}&units=${this.config.units}&lang=${this.config.language}`;

    try {
      const response = await this.fetchWithRetry(url);
      const data = await response.json();

      const alerts = this.mapWeatherAlerts(data);

      // Update cache
      const existingCache = this.cache.get(cacheKey);
      const weatherData: WeatherData = {
        current: existingCache?.data.current || null,
        forecast: existingCache?.data.forecast || [],
        alerts,
        lastUpdated: Date.now(),
      };

      this.cache.set(cacheKey, {
        data: weatherData,
        expiry: Date.now() + this.CACHE_DURATION,
      });

      return alerts;
    } catch (error) {
      // If One Call API fails, return empty alerts array
      console.warn('Weather alerts unavailable:', error);
      return [];
    }
  }

  async getCompleteWeatherData(coords: LocationCoords, locationName?: string): Promise<WeatherData> {
    try {
      const [current, forecast, alerts] = await Promise.allSettled([
        this.getCurrentWeather(coords, locationName),
        this.getForecast(coords),
        this.getWeatherAlerts(coords),
      ]);

      return {
        current: current.status === 'fulfilled' ? current.value : null,
        forecast: forecast.status === 'fulfilled' ? forecast.value : [],
        alerts: alerts.status === 'fulfilled' ? alerts.value : [],
        lastUpdated: Date.now(),
      };
    } catch (error) {
      throw new Error(`Failed to fetch weather data: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  clearCache(): void {
    this.cache.clear();
  }

  getCacheSize(): number {
    return this.cache.size;
  }
}

// React Hook for Weather Service
interface UseWeatherServiceOptions {
  apiKey: string;
  baseUrl?: string;
  units?: 'metric' | 'imperial';
  language?: string;
}

interface UseWeatherServiceReturn {
  weatherService: WeatherService;
  isOnline: boolean;
  clearCache: () => void;
  getCacheSize: () => number;
}

export function useWeatherService(options: UseWeatherServiceOptions): UseWeatherServiceReturn {
  const [isOnline, setIsOnline] = useState(true);

  const weatherService = new WeatherService({
    apiKey: options.apiKey,
    baseUrl: options.baseUrl || 'https://api.openweathermap.org/data/2.5',
    units: options.units || 'metric',
    language: options.language || 'en',
  });

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Initial check
    setIsOnline(navigator.onLine);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return {
    weatherService,
    isOnline,
    clearCache: () => weatherService.clearCache(),
    getCacheSize: () => weatherService.getCacheSize(),
  };
}

// Weather Service Provider Component
interface WeatherServiceProviderProps {
  children: React.ReactNode;
  apiKey: string;
  baseUrl?: string;
  units?: 'metric' | 'imperial';
  language?: string;
}

export function WeatherServiceProvider({
  children,
  apiKey,
  baseUrl = 'https://api.openweathermap.org/data/2.5',
  units = 'metric',
  language = 'en',
}: WeatherServiceProviderProps) {
  const weatherServiceData = useWeatherService({
    apiKey,
    baseUrl,
    units,
    language,
  });

  return (
    <div className="weather-service-provider">
      {children}
    </div>
  );
}

// Export types and service
export type {
  WeatherCondition,
  CurrentWeather,
  DailyForecast,
  WeatherAlert,
  WeatherData,
  LocationCoords,
  WeatherServiceConfig,
  UseWeatherServiceOptions,
  UseWeatherServiceReturn,
};

export { WeatherService };
export default WeatherService;

