class CalendarService {
  private static instance: CalendarService;
  private events: Map<string, CalendarEvent> = new Map();
  private invites: Map<string, CalendarInvite> = new Map();

  static getInstance(): CalendarService {
    if (!CalendarService.instance) {
      CalendarService.instance = new CalendarService();
    }
    return CalendarService.instance;
  }

  async createEvent(eventData: Omit<CalendarEvent, 'id' | 'createdAt' | 'updatedAt'>): Promise<CalendarEvent> {
    try {
      const event: CalendarEvent = {
        ...eventData,
        id: this.generateId(),
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      this.events.set(event.id, event);

      // Send calendar invites to attendees
      await this.sendInvites(event);

      return event;
    } catch (error) {
      console.error('Failed to create calendar event:', error);
      throw new Error('Failed to create calendar event');
    }
  }

  async updateEvent(eventId: string, updates: Partial<CalendarEvent>): Promise<CalendarEvent> {
    try {
      const existingEvent = this.events.get(eventId);
      if (!existingEvent) {
        throw new Error('Event not found');
      }

      const updatedEvent: CalendarEvent = {
        ...existingEvent,
        ...updates,
        id: eventId,
        updatedAt: new Date(),
      };

      this.events.set(eventId, updatedEvent);

      // Send updated invites if attendees changed
      if (updates.attendees) {
        await this.sendInvites(updatedEvent);
      }

      return updatedEvent;
    } catch (error) {
      console.error('Failed to update calendar event:', error);
      throw new Error('Failed to update calendar event');
