'use client';

import { useState, useEffect } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';
import { Database } from '@/types/supabase';

type Supabase = ReturnType<typeof createClientComponentClient<Database>>;

export interface MenuItem {
  id: string;
  trip_id: string;
  meal_type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  meal_name: string;
  description?: string;
  ingredients: string[];
  serves: number;
  prep_time_minutes: number;
  assigned_to?: string;
  scheduled_date: string;
  dietary_restrictions: string[];
  shopping_list: string[];
  created_at: string;
  updated_at: string;
}

export interface MenuItemCreate {
  trip_id: string;
  meal_type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  meal_name: string;
  description?: string;
  ingredients: string[];
  serves: number;
  prep_time_minutes: number;
  assigned_to?: string;
  scheduled_date: string;
  dietary_restrictions?: string[];
  shopping_list?: string[];
}

export interface MenuItemUpdate {
  meal_type?: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  meal_name?: string;
  description?: string;
  ingredients?: string[];
  serves?: number;
  prep_time_minutes?: number;
  assigned_to?: string;
  scheduled_date?: string;
  dietary_restrictions?: string[];
  shopping_list?: string[];
}

export interface MenuFilters {
  trip_id?: string;
  meal_type?: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  assigned_to?: string;
  date_range?: {
    start: string;
    end: string;
  };
}

export interface MenuAPIResponse<T = any> {
  data: T | null;
  error: string | null;
  loading: boolean;
}

export interface ShoppingListItem {
  item: string;
  quantity: string;
  category: string;
  assigned_to?: string;
  purchased: boolean;
}

export interface MenuStats {
  total_meals: number;
  meals_by_type: Record<string, number>;
  total_people_served: number;
  unassigned_meals: number;
  shopping_list_items: number;
}

class MenuAPI {
  private supabase: Supabase;

  constructor() {
    this.supabase = createClientComponentClient<Database>();
  }

  async getMenuItems(filters?: MenuFilters): Promise<MenuAPIResponse<MenuItem[]>> {
    try {
      let query = this.supabase
        .from('menu_items')
        .select('*')
        .order('scheduled_date', { ascending: true });

      if (filters?.trip_id) {
        query = query.eq('trip_id', filters.trip_id);
      }

      if (filters?.meal_type) {
        query = query.eq('meal_type', filters.meal_type);
      }

      if (filters?.assigned_to) {
        query = query.eq('assigned_to', filters.assigned_to);
      }

      if (filters?.date_range) {
        query = query
          .gte('scheduled_date', filters.date_range.start)
          .lte('scheduled_date', filters.date_range.end);
      }

      const { data, error } = await query;

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: data as MenuItem[], error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to fetch menu items',
        loading: false
      };
    }
  }

  async getMenuItem(id: string): Promise<MenuAPIResponse<MenuItem>> {
    try {
      const { data, error } = await this.supabase
        .from('menu_items')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: data as MenuItem, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to fetch menu item',
        loading: false
      };
    }
  }

  async createMenuItem(menuItem: MenuItemCreate): Promise<MenuAPIResponse<MenuItem>> {
    try {
      const { data, error } = await this.supabase
        .from('menu_items')
        .insert({
          ...menuItem,
          dietary_restrictions: menuItem.dietary_restrictions || [],
          shopping_list: menuItem.shopping_list || [],
        })
        .select()
        .single();

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: data as MenuItem, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to create menu item',
        loading: false
      };
    }
  }

  async updateMenuItem(id: string, updates: MenuItemUpdate): Promise<MenuAPIResponse<MenuItem>> {
    try {
      const { data, error } = await this.supabase
        .from('menu_items')
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: data as MenuItem, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to update menu item',
        loading: false
      };
    }
  }

  async deleteMenuItem(id: string): Promise<MenuAPIResponse<boolean>> {
    try {
      const { error } = await this.supabase
        .from('menu_items')
        .delete()
        .eq('id', id);

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: true, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to delete menu item',
        loading: false
      };
    }
  }

  async getShoppingList(tripId: string): Promise<MenuAPIResponse<ShoppingListItem[]>> {
    try {
      const { data: menuItems, error } = await this.supabase
        .from('menu_items')
        .select('shopping_list, assigned_to')
        .eq('trip_id', tripId);

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      const consolidatedList: ShoppingListItem[] = [];
      const itemMap = new Map<string, ShoppingListItem>();

      menuItems?.forEach((item) => {
        item.shopping_list?.forEach((listItem: string) => {
          const [itemName, quantity = '1'] = listItem.split(' - ');
          const category = this.categorizeItem(itemName);
          const key = `${itemName.toLowerCase()}-${category}`;

          if (itemMap.has(key)) {
            const existing = itemMap.get(key)!;
            existing.quantity = this.combineQuantities(existing.quantity, quantity);
          } else {
            itemMap.set(key, {
              item: itemName,
              quantity,
              category,
              assigned_to: item.assigned_to,
              purchased: false,
            });
          }
        });
      });

      consolidatedList.push(...itemMap.values());

      return { data: consolidatedList, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to generate shopping list',
        loading: false
      };
    }
  }

  async getMenuStats(tripId: string): Promise<MenuAPIResponse<MenuStats>> {
    try {
      const { data: menuItems, error } = await this.supabase
        .from('menu_items')
        .select('meal_type, serves, assigned_to, shopping_list')
        .eq('trip_id', tripId);

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      const stats: MenuStats = {
        total_meals: menuItems?.length || 0,
        meals_by_type: {},
        total_people_served: 0,
        unassigned_meals: 0,
        shopping_list_items: 0,
      };

      menuItems?.forEach((item) => {
        // Count meals by type
        stats.meals_by_type[item.meal_type] = (stats.meals_by_type[item.meal_type] || 0) + 1;

        // Sum people served
        stats.total_people_served += item.serves || 0;

        // Count unassigned meals
        if (!item.assigned_to) {
          stats.unassigned_meals += 1;
        }

        // Count shopping list items
        stats.shopping_list_items += item.shopping_list?.length || 0;
      });

      return { data: stats, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to calculate menu stats',
        loading: false
      };
    }
  }

  async duplicateMenuItem(id: string, newDate: string): Promise<MenuAPIResponse<MenuItem>> {
    try {
      const { data: original, error: fetchError } = await this.supabase
        .from('menu_items')
        .select('*')
        .eq('id', id)
        .single();

      if (fetchError) {
        return { data: null, error: fetchError.message, loading: false };
      }

      const { id: _, created_at, updated_at, ...menuItemData } = original;

      const { data, error } = await this.supabase
        .from('menu_items')
        .insert({
          ...menuItemData,
          scheduled_date: newDate,
        })
        .select()
        .single();

      if (error) {
        return { data: null, error: error.message, loading: false };
      }

      return { data: data as MenuItem, error: null, loading: false };
    } catch (error) {
      return {
        data: null,
        error: error instanceof Error ? error.message : 'Failed to duplicate menu item',
        loading: false
      };
    }
  }

  private categorizeItem(item: string): string {
    const categories = {
      'Protein': ['chicken', 'beef', 'pork', 'fish', 'turkey', 'bacon', 'sausage', 'eggs'],
      'Vegetables': ['onion', 'garlic', 'tomato', 'pepper', 'carrot', 'celery', 'potato', 'lettuce'],
      'Dairy': ['milk', 'cheese', 'butter', 'yogurt', 'cream'],
      'Pantry': ['flour', 'sugar', 'salt', 'pepper', 'oil', 'vinegar', 'spices'],
      'Beverages': ['water', 'juice', 'soda', 'beer', 'wine', 'coffee', 'tea'],
    };

    const itemLower = item.toLowerCase();

    for (const [category, items] of Object.entries(categories)) {
      if (items.some(categoryItem => itemLower.includes(categoryItem))) {
        return category;
      }
    }

    return 'Other';
  }

  private combineQuantities(qty1: string, qty2: string): string {
    // Simple quantity combination - in production, this would be more sophisticated
    const num1 = parseFloat(qty1) || 1;
    const num2 = parseFloat(qty2) || 1;
    return (num1 + num2).toString();
  }
}

