  badge?: number;
}

interface MobileNavigationProps {
  activeRoute?: string;
  onNavigate?: (route: string) => void;
  className?: string;
}

const navigationItems: NavigationItem[] = [
  {
    id: 'trips',
    label: 'Trips',
    icon: MapIcon,
    activeIcon: MapIconSolid,
    href: '/trips'
  },
  {
    id: 'calendar',
