'use client';

import React, { useState, useEffect } from 'react';
import { ChevronDownIcon, MapPinIcon, CalendarIcon, UsersIcon, MessageCircleIcon, UtensilsIcon, CloudIcon } from '@heroicons/react/24/outline';

// TypeScript Interfaces
interface Trip {
  id: string;
  name: string;
  location: string;
  startDate: string;
  endDate: string;
  participants: Participant[];
  tasks: Task[];
  meals: Meal[];
  weather?: WeatherData;
}

interface Participant {
  id: string;
  name: string;
  email: string;
  rsvpStatus: 'pending' | 'accepted' | 'declined';
  avatar?: string;
}

interface Task {
  id: string;
  title: string;
  assignedTo?: string;
  dueDate: string;
  completed: boolean;
  category: 'food' | 'equipment' | 'logistics' | 'other';
}

interface Meal {
  id: string;
  name: string;
  date: string;
  time: string;
  assignedTo?: string;
  ingredients: string[];
}

interface WeatherData {
  temperature: number;
  condition: string;
  humidity: number;
  windSpeed: number;
}

interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: string;
}

// Main Component
const TripPlannerApp: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'tasks' | 'meals' | 'chat' | 'weather'>('overview');
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  // Mock data initialization
  useEffect(() => {
    const mockTrip: Trip = {
      id: '1',
      name: 'Moab Adventure',
      location: 'Moab, Utah',
      startDate: '2024-03-15',
      endDate: '2024-03-17',
      participants: [
        { id: '1', name: 'John Doe', email: 'john@example.com', rsvpStatus: 'accepted' },
        { id: '2', name: 'Jane Smith', email: 'jane@example.com', rsvpStatus: 'pending' },
        { id: '3', name: 'Mike Johnson', email: 'mike@example.com', rsvpStatus: 'accepted' },
      ],
      tasks: [
        { id: '1', title: 'Bring firewood', assignedTo: '1', dueDate: '2024-03-15', completed: false, category: 'equipment' },
        { id: '2', title: 'Saturday lunch prep', assignedTo: '2', dueDate: '2024-03-16', completed: false, category: 'food' },
        { id: '3', title: 'Check tire pressure', assignedTo: '3', dueDate: '2024-03-14', completed: true, category: 'logistics' },
      ],
      meals: [
        { id: '1', name: 'Friday Dinner', date: '2024-03-15', time: '18:00', assignedTo: '1', ingredients: ['Steaks', 'Potatoes', 'Vegetables'] },
        { id: '2', name: 'Saturday Breakfast', date: '2024-03-16', time: '08:00', assignedTo: '2', ingredients: ['Eggs', 'Bacon', 'Toast'] },
        { id: '3', name: 'Saturday Lunch', date: '2024-03-16', time: '12:00', assignedTo: '2', ingredients: ['Sandwiches', 'Chips', 'Fruit'] },
      ],
      weather: {
        temperature: 72,
        condition: 'Sunny',
        humidity: 45,
        windSpeed: 8,
      },
    };

    const mockMessages: Message[] = [
      { id: '1', sender: 'John Doe', content: 'Looking forward to this trip!', timestamp: '2024-03-10T10:30:00Z' },
      { id: '2', sender: 'Jane Smith', content: 'Should I bring extra water?', timestamp: '2024-03-10T11:15:00Z' },
      { id: '3', sender: 'Mike Johnson', content: 'I can handle the vehicle maintenance tasks', timestamp: '2024-03-10T14:20:00Z' },
    ];

    setTimeout(() => {
      setCurrentTrip(mockTrip);
      setMessages(mockMessages);
      setIsLoading(false);
    }, 1000);
  }, []);

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      const message: Message = {
        id: Date.now().toString(),
        sender: 'You',
        content: newMessage,
        timestamp: new Date().toISOString(),
      };
      setMessages([...messages, message]);
      setNewMessage('');
    }
  };

  const toggleTaskComplete = (taskId: string) => {
    if (!currentTrip) return;

    const updatedTasks = currentTrip.tasks.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    );

    setCurrentTrip({ ...currentTrip, tasks: updatedTasks });
  };

  if (isLoading) {
    return <LoadingSkeleton />;
  }

  if (!currentTrip) {
    return <EmptyState />;
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <header className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] p-4 shadow-md">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold">{currentTrip.name}</h1>
            <div className="flex items-center gap-2 text-sm opacity-90">
              <MapPinIcon className="w-4 h-4" />
              <span>{currentTrip.location}</span>
            </div>
          </div>
          <div className="text-right text-sm">
            <div>{new Date(currentTrip.startDate).toLocaleDateString()}</div>
            <div>to {new Date(currentTrip.endDate).toLocaleDateString()}</div>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="bg-[rgb(248,250,252)] border-b border-[rgb(226,232,240)] overflow-x-auto">
        <div className="flex">
          {[
            { id: 'overview', label: 'Overview', icon: CalendarIcon },
            { id: 'tasks', label: 'Tasks', icon: UsersIcon },
            { id: 'meals', label: 'Meals', icon: UtensilsIcon },
            { id: 'chat', label: 'Chat', icon: MessageCircleIcon },
            { id: 'weather', label: 'Weather', icon: CloudIcon },
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex items-center gap-2 px-4 py-3 text-sm font-medium whitespace-nowrap min-w-[44px] min-h-[44px] ${
                activeTab === id
                  ? 'text-[rgb(34,139,34)] border-b-2 border-[rgb(34,139,34)] bg-[rgb(255,255,255)]'
                  : 'text-[rgb(15,23,42)] hover:text-[rgb(34,139,34)]'
              }`}
              aria-label={`Switch to ${label} tab`}
            >
              <Icon className="w-4 h-4" />
              <span className="hidden sm:inline">{label}</span>
            </button>
          ))}
        </div>
      </nav>

      {/* Content */}
      <main className="p-4 pb-20">
        {activeTab === 'overview' && <OverviewTab trip={currentTrip} />}
        {activeTab === 'tasks' && <TasksTab tasks={currentTrip.tasks} onToggleComplete={toggleTaskComplete} participants={currentTrip.participants} />}
        {activeTab === 'meals' && <MealsTab meals={currentTrip.meals} participants={currentTrip.participants} />}
        {activeTab === 'chat' && (
          <ChatTab 
            messages={messages} 
            newMessage={newMessage} 
            setNewMessage={setNewMessage} 
            onSendMessage={handleSendMessage} 
          />
        )}
        {activeTab === 'weather' && <WeatherTab weather={currentTrip.weather} />}
      </main>
    </div>
  );
};

// Overview Tab Component
