          <div className="space-y-2">
            <label 
              htmlFor="style-select"
              className="block text-sm font-medium text-[rgb(15,23,42)]"
            >
              Style
            </label>
            <select
              id="style-select"
              value={config.style}
              onChange={(e) => handleConfigChange('style', e.target.value)}
              className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-md 
                         bg-[rgb(255,255,255)] text-[rgb(15,23,42)] text-sm
                         focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2
                         min-h-[44px]"
              aria-label="Select component style"
            >
              <option value="default">Default</option>
              <option value="new-york">New York</option>
