          </div>

          <div className="flex items-center space-x-3">
            <input
              type="checkbox"
              id="tsx-toggle"
              checked={config.tsx}
              onChange={(e) => handleConfigChange('tsx', e.target.checked)}
              className="w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded
                         focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="Use TypeScript"
            />
            <label htmlFor="tsx-toggle" className="text-sm text-[rgb(15,23,42)]">
              Use TypeScript
            </label>
          </div>

          <div className="flex items-center space-x-3">
            <input
              type="checkbox"
              id="css-vars-toggle"
              checked={config.tailwind.cssVariables}
              onChange={(e) => handleConfigChange('tailwind', {
                ...config.tailwind,
                cssVariables: e.target.checked
