        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {availableComponents.map((component) => {
            const isInstalled = installedComponents.has(component.name);

            return (
              <div
                key={component.name}
                className="border border-[rgb(226,232,240)] rounded-lg p-4 space-y-3
