                <div className="text-xs font-mono bg-[rgb(241,245,249)] p-2 rounded 
                               text-[rgb(15,23,42)] break-all">
                  {getInstallCommand(component.name)}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Installation Instructions */}
      <div className="bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg p-6">
        <h2 className="text-lg font-semibold mb-4 text-[rgb(15,23,42)]">
          Installation Instructions
        </h2>

        <div className="space-y-4">
          <div>
            <h3 className="font-medium text-[rgb(15,23,42)] mb-2">
              1. Initialize shadcn/ui
            </h3>
            <div className="bg-[rgb(15,23,42)] text-[rgb(255,255,255)] p-3 rounded-md 
                           font-mono text-sm overflow-x-auto">
              npx shadcn-ui@latest init
            </div>
          </div>

          <div>
            <h3 className="font-medium text-[rgb(15,23,42)] mb-2">
              2. Install components
            </h3>
            <div className="bg-[rgb(15,23,42)] text-[rgb(255,255,255)] p-3 rounded-md 
                           font-mono text-sm overflow-x-auto">
              npx shadcn-ui@latest add button card input label
            </div>
          </div>

          <div>
            <h3 className="font-medium text-[rgb(15,23,42)] mb-2">
