              {`import { Button } from "@/components/ui/button"`}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShadcnSetup;

'use client';

import React, { useState, useEffect } from 'react';
import { Check, X, Clock, Users, Calendar, MessageCircle } from 'lucide-react';

interface RSVPResponse {
  id: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  status: 'attending' | 'not-attending' | 'maybe' | 'pending';
  respondedAt?: Date;
  notes?: string;
}

interface Trip {
  id: string;
  title: string;
  startDate: Date;
  endDate: Date;
  location: string;
}

interface RSVPStatusProps {
  tripId: string;
  trip: Trip;
  responses: RSVPResponse[];
  currentUserId: string;
  onUpdateRSVP: (status: RSVPResponse['status'], notes?: string) => Promise<void>;
  onSendReminder: (userIds: string[]) => Promise<void>;
  isLoading?: boolean;
  className?: string;
}

const RSVPStatus: React.FC<RSVPStatusProps> = ({
  tripId,
  trip,
  responses,
  currentUserId,
  onUpdateRSVP,
  onSendReminder,
  isLoading = false,
  className = ''
}) => {
  const [selectedStatus, setSelectedStatus] = useState<RSVPResponse['status'] | null>(null);
  const [notes, setNotes] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const [showNotes, setShowNotes] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState<string[]>([]);

  const currentUserResponse = responses.find(r => r.userId === currentUserId);
  const attendingCount = responses.filter(r => r.status === 'attending').length;
  const notAttendingCount = responses.filter(r => r.status === 'not-attending').length;
  const maybeCount = responses.filter(r => r.status === 'maybe').length;
  const pendingCount = responses.filter(r => r.status === 'pending').length;

  useEffect(() => {
    if (currentUserResponse) {
      setSelectedStatus(currentUserResponse.status);
      setNotes(currentUserResponse.notes || '');
    }
  }, [currentUserResponse]);

  const handleStatusUpdate = async (status: RSVPResponse['status']) => {
    if (isUpdating) return;

    setIsUpdating(true);
    try {
      await onUpdateRSVP(status, notes);
      setSelectedStatus(status);
      setShowNotes(false);
    } catch (error) {
      console.error('Failed to update RSVP:', error);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleSendReminder = async () => {
    if (selectedUsers.length === 0) return;

    try {
      await onSendReminder(selectedUsers);
      setSelectedUsers([]);
    } catch (error) {
      console.error('Failed to send reminder:', error);
    }
  };

  const getStatusIcon = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending':
        return <Check className="w-4 h-4" />;
      case 'not-attending':
        return <X className="w-4 h-4" />;
      case 'maybe':
        return <Clock className="w-4 h-4" />;
      default:
        return <Clock className="w-4 h-4" />;
    }
  };

  const getStatusColor = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending':
        return 'text-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10';
      case 'not-attending':
        return 'text-[rgb(239,68,68)] bg-[rgb(239,68,68)]/10';
      case 'maybe':
        return 'text-[rgb(245,158,11)] bg-[rgb(245,158,11)]/10';
      default:
        return 'text-[rgb(15,23,42)] bg-[rgb(241,245,249)]';
    }
  };

  if (isLoading) {
    return (
      <div className={`bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)] p-6 ${className}`}>
        <div className="animate-pulse space-y-4">
          <div className="h-6 bg-[rgb(241,245,249)] rounded w-1/3"></div>
          <div className="space-y-3">
            <div className="h-4 bg-[rgb(241,245,249)] rounded w-full"></div>
            <div className="h-4 bg-[rgb(241,245,249)] rounded w-3/4"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)] shadow-md ${className}`}>
      {/* Header */}
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
            RSVP Status
          </h2>
          <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]">
            <Users className="w-4 h-4" />
            <span>{responses.length} invited</span>
          </div>
        </div>

        {/* Trip Info */}
        <div className="bg-[rgb(248,250,252)] rounded-lg p-4 mb-4">
          <h3 className="font-medium text-[rgb(15,23,42)] mb-2">{trip.title}</h3>
          <div className="flex items-center gap-4 text-sm text-[rgb(15,23,42)]">
            <div className="flex items-center gap-1">
              <Calendar className="w-4 h-4" />
              <span>
                {trip.startDate.toLocaleDateString()} - {trip.endDate.toLocaleDateString()}
              </span>
            </div>
            <span className="text-[rgb(15,23,42)]/60">{trip.location}</span>
          </div>
        </div>

        {/* Summary Stats */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <div className="text-center p-3 bg-[rgb(34,139,34)]/10 rounded-lg">
            <div className="text-lg font-semibold text-[rgb(34,139,34)]">{attendingCount}</div>
            <div className="text-xs text-[rgb(15,23,42)]/60">Attending</div>
          </div>
          <div className="text-center p-3 bg-[rgb(245,158,11)]/10 rounded-lg">
            <div className="text-lg font-semibold text-[rgb(245,158,11)]">{maybeCount}</div>
            <div className="text-xs text-[rgb(15,23,42)]/60">Maybe</div>
          </div>
          <div className="text-center p-3 bg-[rgb(239,68,68)]/10 rounded-lg">
            <div className="text-lg font-semibold text-[rgb(239,68,68)]">{notAttendingCount}</div>
            <div className="text-xs text-[rgb(15,23,42)]/60">Not Going</div>
          </div>
          <div className="text-center p-3 bg-[rgb(241,245,249)] rounded-lg">
            <div className="text-lg font-semibold text-[rgb(15,23,42)]">{pendingCount}</div>
            <div className="text-xs text-[rgb(15,23,42)]/60">Pending</div>
          </div>
        </div>
      </div>

      {/* Your Response */}
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <h3 className="font-medium text-[rgb(15,23,42)] mb-4">Your Response</h3>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-4">
          <button
            onClick={() => handleStatusUpdate('attending')}
            disabled={isUpdating}
            className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 transition-all duration-200 min-h-[44px] ${
              selectedStatus === 'attending'
                ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] text-[rgb(15,23,42)] hover:border-[rgb(34,139,34)]'
            } disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2`}
            aria-label="Mark as attending"
          >
            <Check className="w-4 h-4" />
            <span className="font-medium">Attending</span>
          </button>

          <button
            onClick={() => handleStatusUpdate('maybe')}
            disabled={isUpdating}
            className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 transition-all duration-200 min-h-[44px] ${
              selectedStatus === 'maybe'
                ? 'border-[rgb(245,158,11)] bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] text-[rgb(15,23,42)] hover:border-[rgb(245,158,11)]'
            } disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(245,158,11)] focus:ring-offset-2`}
            aria-label="Mark as maybe attending"
          >
            <Clock className="w-4 h-4" />
            <span className="font-medium">Maybe</span>
          </button>

          <button
            onClick={() => handleStatusUpdate('not-attending')}
            disabled={isUpdating}
            className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 transition-all duration-200 min-h-[44px] ${
              selectedStatus === 'not-attending'
                ? 'border-[rgb(239,68,68)] bg-[rgb(239,68,68)] text-[rgb(255,255,255)]'
                : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] text-[rgb(15,23,42)] hover:border-[rgb(239,68,68)]'
            } disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(239,68,68)] focus:ring-offset-2`}
            aria-label="Mark as not attending"
          >
            <X className="w-4 h-4" />
            <span className="font-medium">Can't Go</span>
          </button>
        </div>

        {/* Notes Section */}
        <div className="space-y-3">
          <button
            onClick={() => setShowNotes(!showNotes)}
            className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/60 hover:text-[rgb(15,23,42)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 rounded p-1"
            aria-label="Toggle notes section"
          >
            <MessageCircle className="w-4 h-4" />
            <span>Add a note (optional)</span>
          </button>

          {showNotes && (
            <div className="space-y-3">
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Let the group know about dietary restrictions, arrival time, etc..."
                className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]"
                rows={3}
                aria-label="RSVP notes"
              />
              <button
                onClick={() => handleStatusUpdate(selectedStatus || 'pending')}
                disabled={isUpdating}
                className="px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 font-medium min-h-[44px]"
                aria-label="Save notes"
              >
                {isUpdating ? 'Saving...' : 'Save Note'}
              </button>
            </div>
          )}
        </div>
      </div>

      {/* All Responses */}
      <div className="p-6">
        <h3 className="font-medium text-[rgb(15,23,42)] mb-4">All Responses</h3>

        <div className="space-y-3">
          {responses.map((response) => (
            <div
              key={response.id}
              className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg"
            >
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium">
                  {response.userName.charAt(0).toUpperCase()}
                </div>
                <div>
                  <div className="font-medium text-[rgb(15,23,42)]">{response.userName}</div>
                  {response.notes && (
                    <div className="text-sm text-[rgb(15,23,42)]/60 mt-1">{response.notes}</div>
                  )}
                </div>
              </div>

              <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(response.status)}`}>
                {getStatusIcon(response.status)}
                <span className="capitalize">{response.status.replace('-', ' ')}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Send Reminders */}
        {pendingCount > 0 && (
          <div className="mt-6 pt-6 border-t border-[rgb(226,232,240)]">
            <button
              onClick={handleSendReminder}
              className="w-full sm:w-auto px-6 py-3 bg-[rgb(245,158,11)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(245,158,11)]/90 transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(245,158,11)] focus:ring-offset-2 font-medium min-h-[44px]"
              aria-label="Send reminder to pending users"
            >
              Send Reminder to Pending ({pendingCount})
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default RSVPStatus;

'use client';

import React, { useState, useEffect } from 'react';
import { Cloud, CloudRain, Sun, CloudSnow, Wind, Thermometer, Droplets, Eye, AlertTriangle } from 'lucide-react';

interface WeatherData {
  current: {
    temperature: number;
    condition: string;
    humidity: number;
    windSpeed: number;
    visibility: number;
    feelsLike: number;
    icon: string;
  };
  forecast: Array<{
    date: string;
    high: number;
    low: number;
    condition: string;
    icon: string;
    precipitation: number;
  }>;
  alerts: Array<{
    id: string;
    title: string;
    description: string;
    severity: 'minor' | 'moderate' | 'severe' | 'extreme';
    expires: string;
  }>;
  location: string;
}

interface WeatherWidgetProps {
  location?: string;
  className?: string;
}

const WeatherWidget: React.FC<WeatherWidgetProps> = ({ 
  location = "Current Location", 
  className = "" 
}) => {
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDay, setSelectedDay] = useState(0);

  useEffect(() => {
    const fetchWeatherData = async () => {
      try {
        setLoading(true);
        setError(null);

        // Simulated API call - replace with actual weather API
        await new Promise(resolve => setTimeout(resolve, 1000));

        const mockData: WeatherData = {
          current: {
            temperature: 72,
            condition: "Partly Cloudy",
            humidity: 65,
            windSpeed: 8,
            visibility: 10,
            feelsLike: 75,
            icon: "partly-cloudy"
          },
          forecast: [
            { date: "Today", high: 78, low: 62, condition: "Partly Cloudy", icon: "partly-cloudy", precipitation: 10 },
            { date: "Tomorrow", high: 82, low: 65, condition: "Sunny", icon: "sunny", precipitation: 0 },
