            { date: "Sun", high: 81, low: 66, condition: "Sunny", icon: "sunny", precipitation: 0 }
          ],
          alerts: [
            {
              id: "1",
              title: "High Wind Advisory",
              description: "Winds up to 35 mph expected this afternoon",
              severity: "moderate",
              expires: "6:00 PM"
            }
          ],
          location: location
        };

        setWeatherData(mockData);
      } catch (err) {
        setError("Failed to load weather data. Please try again.");
      } finally {
        setLoading(false);
      }
    };

    fetchWeatherData();
  }, [location]);

  const getWeatherIcon = (iconType: string, size: number = 24) => {
    const iconProps = { 
      size, 
      className: "text-[rgb(34,139,34)]",
      'aria-hidden': true 
    };

    switch (iconType) {
      case 'sunny':
        return <Sun {...iconProps} />;
      case 'partly-cloudy':
        return <Cloud {...iconProps} />;
      case 'cloudy':
        return <Cloud {...iconProps} className="text-[rgb(100,116,139)]" />;
      case 'rainy':
        return <CloudRain {...iconProps} className="text-[rgb(59,130,246)]" />;
      case 'snowy':
        return <CloudSnow {...iconProps} className="text-[rgb(148,163,184)]" />;
      default:
        return <Sun {...iconProps} />;
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'minor':
        return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]';
      case 'moderate':
        return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]';
      case 'severe':
        return 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]';
      case 'extreme':
        return 'bg-[rgb(239,68,68)] text-[rgb(255,255,255)]';
      default:
        return 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]';
    }
  };

  if (loading) {
    return (
      <div className={`bg-[rgb(255,255,255)] rounded-lg shadow-md border border-[rgb(226,232,240)] p-4 ${className}`}>
        <div className="animate-pulse">
          <div className="h-6 bg-[rgb(241,245,249)] rounded mb-4"></div>
          <div className="h-20 bg-[rgb(241,245,249)] rounded mb-4"></div>
          <div className="grid grid-cols-7 gap-2">
            {[...Array(7)].map((_, i) => (
              <div key={i} className="h-16 bg-[rgb(241,245,249)] rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`bg-[rgb(255,255,255)] rounded-lg shadow-md border border-[rgb(226,232,240)] p-4 ${className}`}>
        <div className="text-center py-8">
          <AlertTriangle className="mx-auto mb-2 text-[rgb(239,68,68)]" size={32} aria-hidden="true" />
          <p className="text-[rgb(239,68,68)] font-medium mb-2">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-md font-medium hover:bg-[rgb(22,101,52)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors"
            aria-label="Retry loading weather data"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  if (!weatherData) return null;

  return (
    <div className={`bg-[rgb(255,255,255)] rounded-lg shadow-md border border-[rgb(226,232,240)] overflow-hidden ${className}`}>
      {/* Header */}
      <div className="p-4 border-b border-[rgb(226,232,240)]">
        <h2 className="text-lg font-semibold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
          Weather
        </h2>
        <p className="text-sm text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">
          {weatherData.location}
        </p>
      </div>

      {/* Weather Alerts */}
      {weatherData.alerts.length > 0 && (
        <div className="p-4 border-b border-[rgb(226,232,240)]">
          {weatherData.alerts.map((alert) => (
            <div
              key={alert.id}
              className={`p-3 rounded-md mb-2 last:mb-0 ${getSeverityColor(alert.severity)}`}
              role="alert"
              aria-live="polite"
            >
              <div className="flex items-start gap-2">
                <AlertTriangle size={16} className="mt-0.5 flex-shrink-0" aria-hidden="true" />
                <div className="min-w-0 flex-1">
                  <p className="font-medium text-sm">{alert.title}</p>
                  <p className="text-xs opacity-90 mt-1">{alert.description}</p>
                  <p className="text-xs opacity-75 mt-1">Expires: {alert.expires}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Current Weather */}
      <div className="p-4 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            {getWeatherIcon(weatherData.current.icon, 32)}
            <div>
              <p className="text-2xl font-bold text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
                {weatherData.current.temperature}°F
              </p>
              <p className="text-sm text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">
                {weatherData.current.condition}
              </p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-sm text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">
              Feels like {weatherData.current.feelsLike}°F
            </p>
          </div>
        </div>

        {/* Current Conditions Grid */}
        <div className="grid grid-cols-2 gap-4">
          <div className="flex items-center gap-2">
            <Droplets size={16} className="text-[rgb(59,130,246)]" aria-hidden="true" />
            <div>
              <p className="text-xs text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">Humidity</p>
              <p className="text-sm font-medium text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
                {weatherData.current.humidity}%
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Wind size={16} className="text-[rgb(34,139,34)]" aria-hidden="true" />
            <div>
              <p className="text-xs text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">Wind</p>
              <p className="text-sm font-medium text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
                {weatherData.current.windSpeed} mph
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* 7-Day Forecast */}
      <div className="p-4">
        <h3 className="text-sm font-semibold text-[rgb(15,23,42)] mb-3 font-[Inter,system-ui,sans-serif]">
          7-Day Forecast
        </h3>
        <div className="grid grid-cols-7 gap-1">
          {weatherData.forecast.map((day, index) => (
            <button
              key={index}
              onClick={() => setSelectedDay(index)}
              className={`p-2 rounded-md text-center transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                selectedDay === index
                  ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                  : 'hover:bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
              }`}
              aria-label={`Weather for ${day.date}: ${day.condition}, high ${day.high}, low ${day.low}`}
              style={{ minHeight: '44px' }}
            >
              <div className="text-xs font-medium mb-1 font-[Inter,system-ui,sans-serif]">
                {day.date}
              </div>
              <div className="flex justify-center mb-1">
                {getWeatherIcon(day.icon, 16)}
              </div>
              <div className="text-xs font-[Inter,system-ui,sans-serif]">
                <div className="font-medium">{day.high}°</div>
                <div className="opacity-75">{day.low}°</div>
              </div>
            </button>
          ))}
        </div>

        {/* Selected Day Details */}
        {selectedDay !== null && weatherData.forecast[selectedDay] && (
          <div className="mt-4 p-3 bg-[rgb(248,250,252)] rounded-md">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-[rgb(15,23,42)] font-[Inter,system-ui,sans-serif]">
                  {weatherData.forecast[selectedDay].date}
                </p>
                <p className="text-sm text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">
                  {weatherData.forecast[selectedDay].condition}
                </p>
              </div>
              <div className="text-right">
                <p className="text-sm text-[rgb(100,116,139)] font-[Inter,system-ui,sans-serif]">
                  Precipitation: {weatherData.forecast[selectedDay].precipitation}%
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default WeatherWidget;

