      members: [
        { id: '1', name: 'Alex Johnson', email: 'alex@example.com' },
        { id: '2', name: 'Sarah Chen', email: 'sarah@example.com' },
        { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com' },
        { id: '4', name: 'Emma Davis', email: 'emma@example.com' }
      ],
      tasks: [
        { id: '1', title: 'Bring firewood', assignedTo: { id: '2', name: 'Sarah Chen', email: 'sarah@example.com' }, dueDate: '2024-03-15', completed: false, category: 'equipment' },
        { id: '2', title: 'Saturday lunch prep', assignedTo: { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com' }, dueDate: '2024-03-16', completed: true, category: 'food' }
      ],
      meals: [
        { id: '1', name: 'Campfire Breakfast', day: '2024-03-16', time: 'breakfast', assignedTo: { id: '1', name: 'Alex Johnson', email: 'alex@example.com' } },
        { id: '2', name: 'Trail Sandwiches', day: '2024-03-16', time: 'lunch', assignedTo: { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com' } }
      ],
      chat: [
        { id: '1', user: { id: '2', name: 'Sarah Chen', email: 'sarah@example.com' }, message: 'Excited for this trip!', timestamp: new Date('2024-03-10T10:00:00') },
        { id: '2', user: { id: '1', name: 'Alex Johnson', email: 'alex@example.com' }, message: 'Weather looks perfect for the weekend', timestamp: new Date('2024-03-10T11:30:00') }
      ],
      weather: {
        temperature: 72,
        condition: 'Sunny',
        forecast: [
          { date: '2024-03-15', high: 75, low: 45, condition: 'Sunny' },
          { date: '2024-03-16', high: 78, low: 48, condition: 'Partly Cloudy' },
          { date: '2024-03-17', high: 73, low: 46, condition: 'Clear' }
        ]
      }
    };

    setTimeout(() => {
      setTrip(mockTrip);
      setLoading(false);
    }, 1000);
  }, []);

  const handleSendMessage = () => {
    if (!newMessage.trim() || !trip) return;

    const message: ChatMessage = {
      id: Date.now().toString(),
      user: { id: '1', name: 'You', email: 'you@example.com' },
      message: newMessage,
      timestamp: new Date()
    };

    setTrip(prev => prev ? {
      ...prev,
      chat: [...prev.chat, message]
    } : null);
    setNewMessage('');
  };

  const toggleTaskComplete = (taskId: string) => {
    setTrip(prev => prev ? {
      ...prev,
      tasks: prev.tasks.map(task =>
        task.id === taskId ? { ...task, completed: !task.completed } : task
      )
    } : null);
  };

  const handleRSVP = (status: 'attending' | 'not-attending' | 'maybe') => {
    const newRSVP: RSVP = {
      userId: '1',
      status,
      response: new Date().toISOString()
    };
    setRsvpResponses(prev => [...prev.filter(r => r.userId !== '1'), newRSVP]);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-[rgb(34,139,34)] border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!trip) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
        <div className="text-center">
          <h2 className="text-xl font-medium text-[rgb(15,23,42)] mb-2">Trip not found</h2>
          <p className="text-[rgb(100,116,139)]">Please check your trip details and try again.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      {/* Header */}
      <header className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] p-4 shadow-md">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-semibold">{trip.name}</h1>
            <div className="flex items-center gap-2 text-sm opacity-90">
              <MapPin size={16} />
              <span>{trip.location.name}</span>
            </div>
          </div>
          <div className="text-right text-sm">
            <div>{new Date(trip.startDate).toLocaleDateString()} - {new Date(trip.endDate).toLocaleDateString()}</div>
            <div className="flex items-center gap-1 justify-end">
              <Users size={14} />
              <span>{trip.members.length} members</span>
            </div>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="bg-[rgb(248,250,252)] border-b border-[rgb(226,232,240)] overflow-x-auto">
        <div className="flex">
          {[
            { id: 'overview', label: 'Overview', icon: Calendar },
            { id: 'tasks', label: 'Tasks', icon: CheckSquare },
            { id: 'meals', label: 'Meals', icon: Utensils },
            { id: 'chat', label: 'Chat', icon: MessageCircle },
            { id: 'rsvp', label: 'RSVP', icon: Users }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex items-center gap-2 px-4 py-3 text-sm font-medium whitespace-nowrap min-w-[44px] min-h-[44px] ${
                activeTab === id
                  ? 'text-[rgb(34,139,34)] border-b-2 border-[rgb(34,139,34)] bg-[rgb(255,255,255)]'
                  : 'text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
              }`}
              aria-label={`Switch to ${label} tab`}
            >
              <Icon size={18} />
              <span>{label}</span>
            </button>
          ))}
        </div>
      </nav>

      {/* Content */}
      <main className="p-4 pb-20">
        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Weather Card */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
              <div className="flex items-center gap-2 mb-3">
                <Cloud className="text-[rgb(34,139,34)]" size={20} />
                <h3 className="font-semibold text-[rgb(15,23,42)]">Weather Forecast</h3>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {trip.weather?.forecast.map((day, index) => (
                  <div key={index} className="text-center p-3 bg-[rgb(248,250,252)] rounded-lg">
                    <div className="text-sm text-[rgb(100,116,139)] mb-1">
                      {new Date(day.date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
                    </div>
                    <div className="font-semibold text-[rgb(15,23,42)]">{day.high}°/{day.low}°</div>
                    <div className="text-sm text-[rgb(100,116,139)]">{day.condition}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
                <div className="text-2xl font-bold text-[rgb(34,139,34)]">{trip.tasks.filter(t => !t.completed).length}</div>
                <div className="text-sm text-[rgb(100,116,139)]">Pending Tasks</div>
              </div>
              <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
                <div className="text-2xl font-bold text-[rgb(34,139,34)]">{trip.meals.length}</div>
                <div className="text-sm text-[rgb(100,116,139)]">Planned Meals</div>
              </div>
            </div>

            {/* Recent Activity */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
              <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Recent Activity</h3>
              <div className="space-y-3">
                {trip.chat.slice(-3).map((message) => (
                  <div key={message.id} className="flex gap-3">
                    <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium">
                      {message.user.name.charAt(0)}
                    </div>
                    <div className="flex-1">
                      <div className="text-sm font-medium text-[rgb(15,23,42)]">{message.user.name}</div>
                      <div className="text-sm text-[rgb(100,116,139)]">{message.message}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'tasks' && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
              <button
                onClick={() => setShowNewTaskModal(true)}
                className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg flex items-center gap-2 min-h-[44px] shadow-md"
                aria-label="Add new task"
              >
                <Plus size={16} />
                <span>Add Task</span>
              </button>
            </div>

            <div className="space-y-3">
              {trip.tasks.map((task) => (
                <div key={task.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
                  <div className="flex items-start gap-3">
                    <button
                      onClick={() => toggleTaskComplete(task.id)}
                      className={`w-6 h-6 rounded border-2 flex items-center justify-center min-w-[44px] min-h-[44px] ${
                        task.completed
                          ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                          : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                      }`}
                      aria-label={task.completed ? 'Mark task as incomplete' : 'Mark task as complete'}
                    >
                      {task.completed && <Check size={14} />}
                    </button>
                    <div className="flex-1">
                      <div className={`font-medium ${task.completed ? 'line-through text-[rgb(100,116,139)]' : 'text-[rgb(15,23,42)]'}`}>
                        {task.title}
                      </div>
                      {task.assignedTo && (
                        <div className="text-sm text-[rgb(100,116,139)] mt-1">
                          Assigned to: {task.assignedTo.name}
                        </div>
                      )}
                      <div className="text-sm text-[rgb(100,116,139)] mt-1">
                        Due: {new Date(task.dueDate).toLocaleDateString()}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'meals' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Meal Plan</h2>
            <div className="space-y-3">
              {trip.meals.map((meal) => (
                <div key={meal.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="font-medium text-[rgb(15,23,42)]">{meal.name}</div>
                      <div className="text-sm text-[rgb(100,116,139)] capitalize">
                        {new Date(meal.day).toLocaleDateString('en-US', { weekday: 'long' })} • {meal.time}
                      </div>
                      {meal.assignedTo && (
                        <div className="text-sm text-[rgb(100,116,139)] mt-1">
                          Prepared by: {meal.assignedTo.name}
                        </div>
                      )}
                    </div>
                    <div className="w-8 h-8 bg-[rgb(245,158,11)] rounded-full flex items-center justify-center">
                      <Utensils size={16} className="text-[rgb(255,255,255)]" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Group Chat</h2>

            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-md">
              <div className="p-4 border-b border-[rgb(226,232,240)] max-h-96 overflow-y-auto">
                <div className="space-y-4">
                  {trip.chat.map((message) => (
                    <div key={message.id} className="flex gap-3">
                      <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium flex-shrink-0">
                        {message.user.name.charAt(0)}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-sm font-medium text-[rgb(15,23,42)]">{message.user.name}</span>
                          <span className="text-xs text-[rgb(100,116,139)]">
                            {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </span>
                        </div>
                        <div className="text-sm text-[rgb(15,23,42)]">{message.message}</div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="p-4">
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                    placeholder="Type a message..."
                    className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 text-[rgb(15,23,42)]"
                    aria-label="Type your message"
                  />
                  <button
                    onClick={handleSendMessage}
                    disabled={!newMessage.trim()}
                    className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed min-w-[44px] min-h-[44px] flex items-center justify-center shadow-md"
                    aria-label="Send message"
                  >
                    <Send size={16} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'rsvp' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">RSVP Status</h2>

            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
              <h3 className="font-medium text-[rgb(15,23,42)] mb-3">Your Response</h3>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {[
                  { status: 'attending', label: 'Attending', color: 'rgb(34,139,34)' },
                  { status: 'maybe', label: 'Maybe', color: 'rgb(245,158,11)' },
                  { status: 'not-attending', label: 'Not Attending', color: 'rgb(239,68,68)' }
                ].map(({ status, label, color }) => (
                  <button
                    key={status}
                    onClick={() => handleRSVP(status as any)}
                    className={`p-3 rounded-lg border-2 min-h-[44px] font-medium transition-colors ${
                      rsvpResponses.find(r => r.userId === '1')?.status === status
                        ? `border-[${color}] text-[rgb(255,255,255)]`
                        : 'border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:border-[rgb(100,116,139)]'
                    }`}
                    style={{
                      backgroundColor: rsvpResponses.find(r => r.userId === '1')?.status === status ? color : 'transparent'
                    }}
                    aria-label={`RSVP as ${label}`}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </div>

            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
              <h3 className="font-medium text-[rgb(15,23,42)] mb-3">Group Responses</h3>
              <div className="space-y-3">
                {trip.members.map((member) => (
                  <div key={member.id} className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <span className="text-[rgb(15,23,42)]">{member.name}</span>
                    </div>
                    <span className="text-sm px-2 py-1 rounded bg-[rgb(248,250,252)] text-[rgb(100,116,139)]">
                      Pending
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* New Task Modal */}
      {showNewTaskModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-[rgb(255,255,255)] rounded-lg p-6 w-full max-w-md shadow-lg">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">Add New Task</h3>
              <button
                onClick={() => setShowNewTaskModal(false)}
                className="text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] min-w-[44px] min-h-[44px] flex items-center justify-center"
                aria-label="Close modal"
              >
                <X size={20} />
              </button>
            </div>
            <div className="space-y-4">
              <input
                type="text"
                placeholder="Task title"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 text-[rgb(15,23,42)]"
                aria-label="Task title"
              />
              <select className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 text-[rgb(15,23,42)]">
                <option value="">Assign to...</option>
                {trip.members.map(member => (
                  <option key={member.id} value={member.id}>{member.name}</option>
                ))}
              </select>
              <input
                type="date"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 text-[rgb(15,23,42)]"
                aria-label="Due date"
              />
              <div className="flex gap-3">
                <button
                  onClick={() => setShowNewTaskModal(false)}
                  className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] min-h-[44px]"
                >
                  Cancel
                </button>
                <button
                  onClick={() => setShowNewTaskModal(false)}
                  className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(21,128,61)] min-h-[44px] shadow-md"
                >
                  Add Task
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TripPlannerApp;

