'use client';

import React, { useState, useEffect } from 'react';
import { Check, X, Clock, Users, Calendar, MapPin, MessageSquare } from 'lucide-react';

interface RSVPStatus {
  id: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  status: 'pending' | 'accepted' | 'declined' | 'maybe';
  respondedAt?: Date;
  notes?: string;
}

interface TripEvent {
  id: string;
  title: string;
  description: string;
  location: string;
  startDate: Date;
  endDate: Date;
  organizerId: string;
  maxParticipants?: number;
  rsvpDeadline?: Date;
}

interface RSVPComponentProps {
  event: TripEvent;
  currentUserId: string;
  rsvpList: RSVPStatus[];
  onRSVPUpdate: (eventId: string, status: 'accepted' | 'declined' | 'maybe', notes?: string) => Promise<void>;
  onSendReminder: (eventId: string, userIds: string[]) => Promise<void>;
  isOrganizer?: boolean;
}

const RSVPComponent: React.FC<RSVPComponentProps> = ({
  event,
  currentUserId,
  rsvpList,
  onRSVPUpdate,
  onSendReminder,
  isOrganizer = false
}) => {
  const [selectedStatus, setSelectedStatus] = useState<'accepted' | 'declined' | 'maybe' | null>(null);
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showNotes, setShowNotes] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState<string[]>([]);

  const currentUserRSVP = rsvpList.find(rsvp => rsvp.userId === currentUserId);
  const acceptedCount = rsvpList.filter(rsvp => rsvp.status === 'accepted').length;
  const pendingCount = rsvpList.filter(rsvp => rsvp.status === 'pending').length;
  const declinedCount = rsvpList.filter(rsvp => rsvp.status === 'declined').length;
  const maybeCount = rsvpList.filter(rsvp => rsvp.status === 'maybe').length;

  const isDeadlinePassed = event.rsvpDeadline ? new Date() > event.rsvpDeadline : false;
  const daysUntilDeadline = event.rsvpDeadline 
    ? Math.ceil((event.rsvpDeadline.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))
    : null;

  useEffect(() => {
    if (currentUserRSVP) {
      setSelectedStatus(currentUserRSVP.status === 'pending' ? null : currentUserRSVP.status);
      setNotes(currentUserRSVP.notes || '');
    }
  }, [currentUserRSVP]);

  const handleRSVPSubmit = async (status: 'accepted' | 'declined' | 'maybe') => {
    if (isDeadlinePassed) return;

    setIsSubmitting(true);
    try {
      await onRSVPUpdate(event.id, status, notes);
      setSelectedStatus(status);
      setShowNotes(false);
    } catch (error) {
      console.error('Failed to update RSVP:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSendReminder = async () => {
    if (selectedUsers.length === 0) return;

    try {
      await onSendReminder(event.id, selectedUsers);
      setSelectedUsers([]);
    } catch (error) {
      console.error('Failed to send reminder:', error);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'accepted': return 'rgb(34, 139, 34)';
      case 'declined': return 'rgb(239, 68, 68)';
      case 'maybe': return 'rgb(245, 158, 11)';
      default: return 'rgb(148, 163, 184)';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted': return <Check className="w-4 h-4" />;
      case 'declined': return <X className="w-4 h-4" />;
      case 'maybe': return <Clock className="w-4 h-4" />;
      default: return <Clock className="w-4 h-4" />;
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4 space-y-6 font-medium" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      {/* Event Header */}
      <div className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] p-6">
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">{event.title}</h1>
            <p className="text-[rgb(100,116,139)] mb-4">{event.description}</p>

            <div className="flex flex-col sm:flex-row gap-4 text-sm text-[rgb(100,116,139)]">
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4" />
                <span>
                  {event.startDate.toLocaleDateString()} - {event.endDate.toLocaleDateString()}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <MapPin className="w-4 h-4" />
                <span>{event.location}</span>
              </div>
              {event.maxParticipants && (
                <div className="flex items-center gap-2">
                  <Users className="w-4 h-4" />
                  <span>{acceptedCount}/{event.maxParticipants} spots</span>
                </div>
              )}
            </div>
          </div>

          {event.rsvpDeadline && (
            <div className="bg-[rgb(248,250,252)] rounded-lg p-4 text-center min-w-[140px]">
              <div className="text-sm text-[rgb(100,116,139)]">RSVP Deadline</div>
              <div className="font-semibold text-[rgb(15,23,42)]">
                {event.rsvpDeadline.toLocaleDateString()}
              </div>
              {daysUntilDeadline !== null && daysUntilDeadline > 0 && (
                <div className="text-xs text-[rgb(245,158,11)]">
                  {daysUntilDeadline} days left
                </div>
              )}
              {isDeadlinePassed && (
                <div className="text-xs text-[rgb(239,68,68)]">Deadline passed</div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* RSVP Actions */}
      {!isDeadlinePassed && (
        <div className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] p-6">
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Your Response</h2>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-4">
            <button
              onClick={() => handleRSVPSubmit('accepted')}
              disabled={isSubmitting}
              className={`flex items-center justify-center gap-2 p-4 rounded-lg border-2 transition-all min-h-[44px] ${
                selectedStatus === 'accepted'
                  ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)] text-white'
                  : 'border-[rgb(226,232,240)] bg-white text-[rgb(15,23,42)] hover:border-[rgb(34,139,34)]'
              } ${isSubmitting ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
              aria-label="Accept invitation"
            >
              <Check className="w-5 h-5" />
              <span className="font-medium">Accept</span>
            </button>

            <button
              onClick={() => handleRSVPSubmit('maybe')}
              disabled={isSubmitting}
              className={`flex items-center justify-center gap-2 p-4 rounded-lg border-2 transition-all min-h-[44px] ${
                selectedStatus === 'maybe'
                  ? 'border-[rgb(245,158,11)] bg-[rgb(245,158,11)] text-white'
                  : 'border-[rgb(226,232,240)] bg-white text-[rgb(15,23,42)] hover:border-[rgb(245,158,11)]'
              } ${isSubmitting ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
              aria-label="Mark as maybe"
            >
              <Clock className="w-5 h-5" />
              <span className="font-medium">Maybe</span>
            </button>

            <button
              onClick={() => handleRSVPSubmit('declined')}
              disabled={isSubmitting}
              className={`flex items-center justify-center gap-2 p-4 rounded-lg border-2 transition-all min-h-[44px] ${
                selectedStatus === 'declined'
                  ? 'border-[rgb(239,68,68)] bg-[rgb(239,68,68)] text-white'
                  : 'border-[rgb(226,232,240)] bg-white text-[rgb(15,23,42)] hover:border-[rgb(239,68,68)]'
              } ${isSubmitting ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
              aria-label="Decline invitation"
            >
              <X className="w-5 h-5" />
              <span className="font-medium">Decline</span>
            </button>
          </div>

          <button
            onClick={() => setShowNotes(!showNotes)}
            className="flex items-center gap-2 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] transition-colors"
            aria-label="Add notes to RSVP"
          >
            <MessageSquare className="w-4 h-4" />
            <span className="text-sm">Add a note (optional)</span>
          </button>

          {showNotes && (
            <div className="mt-4">
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Add any comments or questions..."
                className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg resize-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                rows={3}
                aria-label="RSVP notes"
              />
            </div>
          )}
        </div>
      )}

      {/* RSVP Summary */}
      <div className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] p-6">
        <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Response Summary</h2>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
          <div className="text-center p-4 bg-[rgb(248,250,252)] rounded-lg">
            <div className="text-2xl font-bold" style={{ color: 'rgb(34, 139, 34)' }}>
              {acceptedCount}
            </div>
            <div className="text-sm text-[rgb(100,116,139)]">Accepted</div>
          </div>
          <div className="text-center p-4 bg-[rgb(248,250,252)] rounded-lg">
            <div className="text-2xl font-bold" style={{ color: 'rgb(245, 158, 11)' }}>
              {maybeCount}
            </div>
            <div className="text-sm text-[rgb(100,116,139)]">Maybe</div>
          </div>
          <div className="text-center p-4 bg-[rgb(248,250,252)] rounded-lg">
            <div className="text-2xl font-bold" style={{ color: 'rgb(239, 68, 68)' }}>
              {declinedCount}
            </div>
            <div className="text-sm text-[rgb(100,116,139)]">Declined</div>
          </div>
          <div className="text-center p-4 bg-[rgb(248,250,252)] rounded-lg">
            <div className="text-2xl font-bold text-[rgb(148,163,184)]">
              {pendingCount}
            </div>
            <div className="text-sm text-[rgb(100,116,139)]">Pending</div>
          </div>
        </div>

        {/* Participant List */}
        <div className="space-y-3">
          <h3 className="font-semibold text-[rgb(15,23,42)]">Participants</h3>
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {rsvpList.map((rsvp) => (
              <div
                key={rsvp.id}
                className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg"
              >
                <div className="flex items-center gap-3">
                  {rsvp.userAvatar ? (
                    <img
                      src={rsvp.userAvatar}
                      alt={`${rsvp.userName} avatar`}
                      className="w-8 h-8 rounded-full"
                    />
                  ) : (
                    <div className="w-8 h-8 rounded-full bg-[rgb(226,232,240)] flex items-center justify-center">
                      <span className="text-sm font-medium text-[rgb(100,116,139)]">
                        {rsvp.userName.charAt(0).toUpperCase()}
                      </span>
                    </div>
                  )}
                  <div>
                    <div className="font-medium text-[rgb(15,23,42)]">{rsvp.userName}</div>
                    {rsvp.notes && (
                      <div className="text-sm text-[rgb(100,116,139)]">{rsvp.notes}</div>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <div
                    className="flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium text-white"
                    style={{ backgroundColor: getStatusColor(rsvp.status) }}
                  >
                    {getStatusIcon(rsvp.status)}
                    <span className="capitalize">{rsvp.status}</span>
                  </div>

                  {isOrganizer && rsvp.status === 'pending' && (
                    <input
                      type="checkbox"
                      checked={selectedUsers.includes(rsvp.userId)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedUsers([...selectedUsers, rsvp.userId]);
                        } else {
                          setSelectedUsers(selectedUsers.filter(id => id !== rsvp.userId));
                        }
                      }}
                      className="w-4 h-4 text-[rgb(34,139,34)] rounded focus:ring-2 focus:ring-[rgb(34,139,34)]"
                      aria-label={`Select ${rsvp.userName} for reminder`}
                    />
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Organizer Actions */}
        {isOrganizer && selectedUsers.length > 0 && (
          <div className="mt-4 pt-4 border-t border-[rgb(226,232,240)]">
            <button
              onClick={handleSendReminder}
              className="w-full sm:w-auto px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(22,101,22)] transition-colors min-h-[44px]"
              aria-label="Send reminder to selected users"
            >
              Send Reminder ({selectedUsers.length})
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default RSVPComponent;

'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, Users, ChefHat, Plus, Edit2, Trash2, MapPin } from 'lucide-react';

interface Meal {
  id: string;
  name: string;
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  date: string;
  time: string;
  assignedTo: string[];
  ingredients: string[];
  servings: number;
  notes?: string;
  location?: string;
}

interface MenuDisplayProps {
  tripId: string;
  meals?: Meal[];
  groupMembers?: { id: string; name: string; avatar?: string }[];
  onAddMeal?: (meal: Omit<Meal, 'id'>) => void;
  onEditMeal?: (id: string, meal: Partial<Meal>) => void;
  onDeleteMeal?: (id: string) => void;
  isLoading?: boolean;
  error?: string;
}

interface MealFormData {
  name: string;
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack';
  date: string;
  time: string;
  assignedTo: string[];
  ingredients: string[];
  servings: number;
  notes: string;
  location: string;
}

const MenuDisplay: React.FC<MenuDisplayProps> = ({
  tripId,
  meals = [],
  groupMembers = [],
  onAddMeal,
  onEditMeal,
  onDeleteMeal,
  isLoading = false,
  error
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingMeal, setEditingMeal] = useState<Meal | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [formData, setFormData] = useState<MealFormData>({
    name: '',
    type: 'breakfast',
    date: '',
    time: '',
    assignedTo: [],
    ingredients: [],
    servings: 4,
    notes: '',
    location: ''
  });
  const [newIngredient, setNewIngredient] = useState('');

  useEffect(() => {
    if (meals.length > 0) {
      const dates = meals.map(meal => meal.date).sort();
      setSelectedDate(dates[0]);
    }
  }, [meals]);

  const resetForm = () => {
    setFormData({
      name: '',
      type: 'breakfast',
      date: '',
      time: '',
      assignedTo: [],
      ingredients: [],
      servings: 4,
      notes: '',
      location: ''
    });
    setNewIngredient('');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingMeal) {
      onEditMeal?.(editingMeal.id, formData);
      setEditingMeal(null);
    } else {
      onAddMeal?.(formData);
      setShowAddForm(false);
    }

    resetForm();
  };

  const handleEdit = (meal: Meal) => {
    setFormData({
      name: meal.name,
      type: meal.type,
      date: meal.date,
      time: meal.time,
      assignedTo: meal.assignedTo,
      ingredients: meal.ingredients,
      servings: meal.servings,
      notes: meal.notes || '',
      location: meal.location || ''
    });
    setEditingMeal(meal);
    setShowAddForm(true);
  };

  const handleCancel = () => {
    setShowAddForm(false);
    setEditingMeal(null);
    resetForm();
  };

  const addIngredient = () => {
    if (newIngredient.trim()) {
      setFormData(prev => ({
        ...prev,
        ingredients: [...prev.ingredients, newIngredient.trim()]
      }));
      setNewIngredient('');
    }
  };

  const removeIngredient = (index: number) => {
    setFormData(prev => ({
      ...prev,
      ingredients: prev.ingredients.filter((_, i) => i !== index)
    }));
  };

  const toggleAssignment = (memberId: string) => {
    setFormData(prev => ({
      ...prev,
      assignedTo: prev.assignedTo.includes(memberId)
        ? prev.assignedTo.filter(id => id !== memberId)
        : [...prev.assignedTo, memberId]
    }));
  };

  const getMealsByDate = (date: string) => {
    return meals
      .filter(meal => meal.date === date)
      .sort((a, b) => {
        const timeOrder = { breakfast: 1, lunch: 2, dinner: 3, snack: 4 };
        return timeOrder[a.type] - timeOrder[b.type];
      });
  };

  const getUniqueDates = () => {
    return [...new Set(meals.map(meal => meal.date))].sort();
  };

  const getMealTypeIcon = (type: string) => {
    switch (type) {
      case 'breakfast': return '🌅';
      case 'lunch': return '☀️';
      case 'dinner': return '🌙';
      case 'snack': return '🍎';
      default: return '🍽️';
    }
  };

  const getAssignedMemberNames = (assignedIds: string[]) => {
    return assignedIds
      .map(id => groupMembers.find(member => member.id === id)?.name)
      .filter(Boolean)
      .join(', ');
  };

  if (isLoading) {
    return (
      <div className="p-4 space-y-4">
        <div className="h-8 bg-[rgb(241,245,249)] rounded animate-pulse"></div>
        <div className="space-y-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-24 bg-[rgb(241,245,249)] rounded animate-pulse"></div>
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4">
        <div className="bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg p-4">
          <p className="text-[rgb(239,68,68)] font-medium">Error loading menu</p>
          <p className="text-sm text-[rgb(127,29,29)] mt-1">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      {/* Header */}
      <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] z-10">
        <div className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <ChefHat className="w-6 h-6 text-[rgb(34,139,34)]" />
              <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Menu</h1>
            </div>
            <button
              onClick={() => setShowAddForm(true)}
              className="flex items-center gap-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg shadow-md hover:bg-[rgb(22,101,22)] transition-colors min-h-[44px]"
              aria-label="Add new meal"
            >
              <Plus className="w-4 h-4" />
              <span className="text-sm">Add Meal</span>
            </button>
          </div>
        </div>
      </div>

      {/* Date Filter */}
      {getUniqueDates().length > 0 && (
        <div className="p-4 border-b border-[rgb(226,232,240)]">
          <div className="flex gap-2 overflow-x-auto pb-2">
            {getUniqueDates().map(date => (
              <button
                key={date}
                onClick={() => setSelectedDate(date)}
                className={`flex-shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-colors min-h-[44px] ${
                  selectedDate === date
                    ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                    : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                }`}
                aria-label={`Filter meals for ${new Date(date).toLocaleDateString()}`}
              >
                {new Date(date).toLocaleDateString('en-US', { 
                  weekday: 'short', 
                  month: 'short', 
                  day: 'numeric' 
                })}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Meals List */}
      <div className="p-4 space-y-4">
        {selectedDate && getMealsByDate(selectedDate).length > 0 ? (
          getMealsByDate(selectedDate).map(meal => (
            <div
              key={meal.id}
              className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <span className="text-2xl" role="img" aria-label={meal.type}>
                    {getMealTypeIcon(meal.type)}
                  </span>
                  <div>
                    <h3 className="font-semibold text-[rgb(15,23,42)] text-lg">{meal.name}</h3>
                    <p className="text-sm text-[rgb(100,116,139)] capitalize">{meal.type}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleEdit(meal)}
                    className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)] rounded-lg transition-colors min-h-[44px] min-w-[44px]"
                    aria-label={`Edit ${meal.name}`}
                  >
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => onDeleteMeal?.(meal.id)}
                    className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(239,68,68)] hover:bg-[rgb(254,242,242)] rounded-lg transition-colors min-h-[44px] min-w-[44px]"
                    aria-label={`Delete ${meal.name}`}
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                  <Clock className="w-4 h-4" />
                  <span>{meal.time}</span>
                  <Users className="w-4 h-4 ml-4" />
                  <span>{meal.servings} servings</span>
                </div>

                {meal.location && (
                  <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                    <MapPin className="w-4 h-4" />
                    <span>{meal.location}</span>
                  </div>
                )}

                {meal.assignedTo.length > 0 && (
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-[rgb(15,23,42)]">Assigned to:</span>
                    <span className="text-sm text-[rgb(100,116,139)]">
                      {getAssignedMemberNames(meal.assignedTo)}
                    </span>
                  </div>
                )}

                {meal.ingredients.length > 0 && (
                  <div>
                    <span className="text-sm font-medium text-[rgb(15,23,42)] block mb-2">Ingredients:</span>
                    <div className="flex flex-wrap gap-2">
                      {meal.ingredients.map((ingredient, index) => (
                        <span
                          key={index}
                          className="bg-[rgb(248,250,252)] text-[rgb(15,23,42)] px-2 py-1 rounded text-sm"
                        >
                          {ingredient}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {meal.notes && (
                  <div>
                    <span className="text-sm font-medium text-[rgb(15,23,42)] block mb-1">Notes:</span>
                    <p className="text-sm text-[rgb(100,116,139)]">{meal.notes}</p>
                  </div>
                )}
              </div>
            </div>
          ))
        ) : meals.length === 0 ? (
          <div className="text-center py-12">
            <ChefHat className="w-16 h-16 text-[rgb(148,163,184)] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No meals planned yet</h3>
            <p className="text-[rgb(100,116,139)] mb-6">Start planning your trip meals by adding your first meal.</p>
            <button
              onClick={() => setShowAddForm(true)}
              className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-6 py-3 rounded-lg shadow-md hover:bg-[rgb(22,101,22)] transition-colors min-h-[44px]"
            >
              Add First Meal
            </button>
          </div>
        ) : (
          <div className="text-center py-8">
            <p className="text-[rgb(100,116,139)]">No meals planned for this date</p>
          </div>
        )}
      </div>

      {/* Add/Edit Meal Modal */}
      {showAddForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-[rgb(255,255,255)] rounded-t-xl sm:rounded-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] p-4">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">
                {editingMeal ? 'Edit Meal' : 'Add New Meal'}
              </h2>
            </div>

            <form onSubmit={handleSubmit} className="p-4 space-y-4">
              <div>
                <label htmlFor="meal-name" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Meal Name
                </label>
                <input
                  id="meal-name"
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                  placeholder="e.g., Campfire Breakfast"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label htmlFor="meal-type" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Type
                  </label>
                  <select
                    id="meal-type"
                    value={formData.type}
                    onChange={(e) => setFormData(prev => ({ ...prev, type: e.target.value as any }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                  >
                    <option value="breakfast">Breakfast</option>
                    <option value="lunch">Lunch</option>
                    <option value="dinner">Dinner</option>
                    <option value="snack">Snack</option>
                  </select>
                </div>

                <div>
                  <label htmlFor="servings" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Servings
                  </label>
                  <input
                    id="servings"
                    type="number"
                    min="1"
                    value={formData.servings}
                    onChange={(e) => setFormData(prev => ({ ...prev, servings: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label htmlFor="meal-date" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Date
                  </label>
                  <input
                    id="meal-date"
                    type="date"
                    value={formData.date}
                    onChange={(e) => setFormData(prev => ({ ...prev, date: e.target.value }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    required
                  />
                </div>

                <div>
                  <label htmlFor="meal-time" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Time
                  </label>
                  <input
                    id="meal-time"
                    type="time"
                    value={formData.time}
                    onChange={(e) => setFormData(prev => ({ ...prev, time: e.target.value }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    required
                  />
                </div>
              </div>

              <div>
                <label htmlFor="location" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Location (Optional)
                </label>
                <input
                  id="location"
                  type="text"
                  value={formData.location}
                  onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                  placeholder="e.g., Main campsite, Trail junction"
                />
              </div>

              {groupMembers.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Assign to Group Members
                  </label>
                  <div className="space-y-2">
                    {groupMembers.map(member => (
                      <label key={member.id} className="flex items-center gap-3 p-2 hover:bg-[rgb(248,250,252)] rounded-lg cursor-pointer min-h-[44px]">
                        <input
                          type="checkbox"
                          checked={formData.assignedTo.includes(member.id)}
                          onChange={() => toggleAssignment(member.id)}
                          className="w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded focus:ring-[rgb(34,139,34)]"
                        />
                        <span className="text-sm text-[rgb(15,23,42)]">{member.name}</span>
                      </label>
                    ))}
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Ingredients
                </label>
                <div className="flex gap-2 mb-2">
                  <input
                    type="text"
                    value={newIngredient}
                    onChange={(e) => setNewIngredient(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addIngredient())}
                    className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    placeholder="Add ingredient"
                  />
                  <button
                    type="button"
                    onClick={addIngredient}
                    className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg hover:bg-[rgb(22,101,22)] transition-colors min-h-[44px]"
                    aria-label="Add ingredient"
                  >
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                {formData.ingredients.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {formData.ingredients.map((ingredient, index) => (
                      <span
                        key={index}
                        className="bg-[rgb(248,250,252)] text-[rgb(15,23,42)] px-3 py-1 rounded-lg text-sm flex items-center gap-2"
                      >
                        {ingredient}
                        <button
                          type="button"
                          onClick={() => removeIngredient(index)}
                          className="text-[rgb(100,116,139)] hover:text-[rgb(239,68,68)] min-h-[24px] min-w-[24px]"
                          aria-label={`Remove ${ingredient}`}
                        >
                          ×
                        </button>
                      </span>
                    ))}
                  </div>
                )}
              </div>

              <div>
                <label htmlFor="notes" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Notes (Optional)
                </label>
                <textarea
                  id="notes"
                  value={formData.notes}
                  onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[80px] resize-none"
                  placeholder="Any special instructions or notes..."
                  rows={3}
                />
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={handleCancel}
                  className="flex-1 px-4 py-3 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors min-h-[44px]"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(22,101,22)] transition-colors min-h-[44px]"
                >
                  {editingMeal ? 'Update Meal' : 'Add Meal'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuDisplay;

'use client';

import React, { useState, useEffect } from 'react';
import { Check, Plus, X, User, Calendar, AlertCircle } from 'lucide-react';

interface TaskAssignee {
  id: string;
  name: string;
  avatar?: string;
}

interface Task {
  id: string;
  title: string;
  description?: string;
  assignee?: TaskAssignee;
  dueDate?: string;
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other';
  completed: boolean;
  priority: 'low' | 'medium' | 'high';
  createdAt: string;
}

interface TaskListProps {
  tripId: string;
  groupMembers: TaskAssignee[];
  onTaskUpdate?: (task: Task) => void;
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt'>) => void;
  onTaskDelete?: (taskId: string) => void;
}

const TaskList: React.FC<TaskListProps> = ({
  tripId,
  groupMembers,
  onTaskUpdate,
  onTaskCreate,
  onTaskDelete
}) => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [filter, setFilter] = useState<'all' | 'pending' | 'completed'>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    assigneeId: '',
    dueDate: '',
    category: 'other' as Task['category'],
    priority: 'medium' as Task['priority']
  });

  useEffect(() => {
    loadTasks();
  }, [tripId]);

  const loadTasks = async () => {
    try {
      setIsLoading(true);
      setError(null);
      // Simulated API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      const mockTasks: Task[] = [
        {
          id: '1',
          title: 'Bring firewood',
          description: 'Get enough for 2 nights',
          assignee: groupMembers[0],
          dueDate: '2024-01-15',
          category: 'equipment',
          completed: false,
          priority: 'high',
          createdAt: '2024-01-10T10:00:00Z'
        },
        {
          id: '2',
          title: 'Plan Saturday lunch',
          description: 'Sandwiches for 6 people',
          assignee: groupMembers[1],
          dueDate: '2024-01-14',
          category: 'food',
          completed: true,
          priority: 'medium',
          createdAt: '2024-01-10T11:00:00Z'
        }
      ];

      setTasks(mockTasks);
    } catch (err) {
      setError('Failed to load tasks. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleTaskToggle = async (taskId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    const updatedTask = { ...task, completed: !task.completed };

    // Optimistic update
    setTasks(prev => prev.map(t => t.id === taskId ? updatedTask : t));

    try {
      await new Promise(resolve => setTimeout(resolve, 500));
      onTaskUpdate?.(updatedTask);
    } catch (err) {
      // Revert on error
      setTasks(prev => prev.map(t => t.id === taskId ? task : t));
      setError('Failed to update task. Please try again.');
    }
  };

  const handleAddTask = async () => {
    if (!newTask.title.trim()) return;

    const assignee = groupMembers.find(m => m.id === newTask.assigneeId);
    const task: Omit<Task, 'id' | 'createdAt'> = {
      title: newTask.title,
      description: newTask.description,
      assignee,
      dueDate: newTask.dueDate || undefined,
      category: newTask.category,
      completed: false,
      priority: newTask.priority
    };

    const tempId = `temp-${Date.now()}`;
    const tempTask: Task = {
      ...task,
      id: tempId,
      createdAt: new Date().toISOString()
    };

    // Optimistic update
    setTasks(prev => [tempTask, ...prev]);
    setShowAddForm(false);
    setNewTask({
      title: '',
      description: '',
      assigneeId: '',
      dueDate: '',
      category: 'other',
      priority: 'medium'
    });

    try {
      await new Promise(resolve => setTimeout(resolve, 500));
      onTaskCreate?.(task);
    } catch (err) {
      // Remove temp task on error
      setTasks(prev => prev.filter(t => t.id !== tempId));
      setError('Failed to create task. Please try again.');
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    // Optimistic update
    setTasks(prev => prev.filter(t => t.id !== taskId));

    try {
      await new Promise(resolve => setTimeout(resolve, 500));
      onTaskDelete?.(taskId);
    } catch (err) {
      // Restore on error
      setTasks(prev => [...prev, task].sort((a, b) => 
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      ));
      setError('Failed to delete task. Please try again.');
    }
  };

  const filteredTasks = tasks.filter(task => {
    const statusMatch = filter === 'all' || 
      (filter === 'completed' && task.completed) ||
      (filter === 'pending' && !task.completed);

    const categoryMatch = categoryFilter === 'all' || task.category === categoryFilter;

    return statusMatch && categoryMatch;
  });

  const getPriorityColor = (priority: Task['priority']) => {
    switch (priority) {
      case 'high': return 'bg-[rgb(239,68,68)]';
      case 'medium': return 'bg-[rgb(245,158,11)]';
      case 'low': return 'bg-[rgb(34,139,34)]';
    }
  };

  const getCategoryIcon = (category: Task['category']) => {
    switch (category) {
      case 'food': return '🍽️';
      case 'equipment': return '🎒';
      case 'logistics': return '📋';
      case 'safety': return '🚨';
      default: return '📝';
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        {[...Array(3)].map((_, i) => (
          <div key={i} className="bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)] p-4">
            <div className="animate-pulse">
              <div className="h-4 bg-[rgb(241,245,249)] rounded w-3/4 mb-2"></div>
              <div className="h-3 bg-[rgb(241,245,249)] rounded w-1/2"></div>
            </div>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {error && (
        <div className="bg-[rgb(239,68,68)] bg-opacity-10 border border-[rgb(239,68,68)] rounded-lg p-4 flex items-center gap-3">
          <AlertCircle className="w-5 h-5 text-[rgb(239,68,68)] flex-shrink-0" />
          <p className="text-[rgb(239,68,68)] text-sm font-medium">{error}</p>
          <button
            onClick={() => setError(null)}
            className="ml-auto text-[rgb(239,68,68)] hover:text-[rgb(220,38,38)] transition-colors"
            aria-label="Dismiss error"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
        <button
          onClick={() => setShowAddForm(true)}
          className="w-full sm:w-auto bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-[rgb(22,101,22)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
          aria-label="Add new task"
        >
          <Plus className="w-4 h-4" />
          Add Task
        </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as typeof filter)}
          className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
          aria-label="Filter tasks by status"
        >
          <option value="all">All Tasks</option>
          <option value="pending">Pending</option>
          <option value="completed">Completed</option>
        </select>

        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
          aria-label="Filter tasks by category"
        >
          <option value="all">All Categories</option>
          <option value="food">Food</option>
          <option value="equipment">Equipment</option>
          <option value="logistics">Logistics</option>
          <option value="safety">Safety</option>
          <option value="other">Other</option>
        </select>
      </div>

      {showAddForm && (
        <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 space-y-4 shadow-md">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">Add New Task</h3>
            <button
              onClick={() => setShowAddForm(false)}
              className="text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] transition-colors p-1"
              aria-label="Cancel adding task"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="space-y-4">
            <div>
              <label htmlFor="task-title" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                Task Title *
              </label>
              <input
                id="task-title"
                type="text"
                value={newTask.title}
                onChange={(e) => setNewTask(prev => ({ ...prev, title: e.target.value }))}
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
                placeholder="Enter task title"
                required
              />
            </div>

            <div>
              <label htmlFor="task-description" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                Description
              </label>
              <textarea
                id="task-description"
                value={newTask.description}
                onChange={(e) => setNewTask(prev => ({ ...prev, description: e.target.value }))}
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 resize-none"
                rows={3}
                placeholder="Add details about the task"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="task-assignee" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Assign To
                </label>
                <select
                  id="task-assignee"
                  value={newTask.assigneeId}
                  onChange={(e) => setNewTask(prev => ({ ...prev, assigneeId: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
                >
                  <option value="">Unassigned</option>
                  {groupMembers.map(member => (
                    <option key={member.id} value={member.id}>{member.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="task-due-date" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Due Date
                </label>
                <input
                  id="task-due-date"
                  type="date"
                  value={newTask.dueDate}
                  onChange={(e) => setNewTask(prev => ({ ...prev, dueDate: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="task-category" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Category
                </label>
                <select
                  id="task-category"
                  value={newTask.category}
                  onChange={(e) => setNewTask(prev => ({ ...prev, category: e.target.value as Task['category'] }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
                >
                  <option value="food">Food</option>
                  <option value="equipment">Equipment</option>
                  <option value="logistics">Logistics</option>
                  <option value="safety">Safety</option>
                  <option value="other">Other</option>
                </select>
              </div>

              <div>
                <label htmlFor="task-priority" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Priority
                </label>
                <select
                  id="task-priority"
                  value={newTask.priority}
                  onChange={(e) => setNewTask(prev => ({ ...prev, priority: e.target.value as Task['priority'] }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg bg-[rgb(255,255,255)] text-[rgb(15,23,42)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
                >
                  <option value="low">Low</option>
                  <option value="medium">Medium</option>
                  <option value="high">High</option>
                </select>
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button
                onClick={handleAddTask}
                disabled={!newTask.title.trim()}
                className="flex-1 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-4 py-2 rounded-lg font-medium hover:bg-[rgb(22,101,22)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed min-h-[44px]"
              >
                Add Task
              </button>
              <button
                onClick={() => setShowAddForm(false)}
                className="flex-1 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] px-4 py-2 rounded-lg font-medium border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px]"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-3">
        {filteredTasks.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-6xl mb-4">📝</div>
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No tasks yet</h3>
            <p className="text-[rgb(100,116,139)] mb-4">
              {filter === 'all' 
                ? "Start by adding your first task to organize the trip"
                : `No ${filter} tasks found`
              }
            </p>
            {filter === 'all' && (
              <button
                onClick={() => setShowAddForm(true)}
                className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] px-6 py-2 rounded-lg font-medium hover:bg-[rgb(22,101,22)] transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              >
                Add First Task
              </button>
            )}
          </div>
        ) : (
          filteredTasks.map(task => (
            <div
              key={task.id}
              className={`bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-sm transition-all ${
                task.completed ? 'opacity-75' : ''
              }`}
            >
              <div className="flex items-start gap-3">
                <button
                  onClick={() => handleTaskToggle(task.id)}
                  className={`flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                    task.completed
                      ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                      : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                  }`}
                  aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
                >
                  {task.completed && <Check className="w-4 h-4" />}
                </button>

                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-lg">{getCategoryIcon(task.category)}</span>
                      <h3 className={`font-semibold text-[rgb(15,23,42)] ${
                        task.completed ? 'line-through' : ''
                      }`}>
                        {task.title}
                      </h3>
                      <div className={`w-2 h-2 rounded-full ${getPriorityColor(task.priority)}`} />
                    </div>
                    <button
                      onClick={() => handleDeleteTask(task.id)}
                      className="text-[rgb(100,116,139)] hover:text-[rgb(239,68,68)] transition-colors p-1 flex-shrink-0 focus:outline-none focus:ring-2 focus:ring-[rgb(239,68,68)] focus:ring-offset-2 rounded"
                      aria-label="Delete task"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>

                  {task.description && (
                    <p className={`text-sm text-[rgb(100,116,139)] mb-3 ${
                      task.completed ? 'line-through' : ''
                    }`}>
                      {task.description}
                    </p>
                  )}

                  <div className="flex flex-wrap items-center gap-4 text-sm text-[rgb(100,116,139)]">
                    {task.assignee && (
                      <div className="flex items-center gap-2">
                        <User className="w-4 h-4" />
                        <span>{task.assignee.name}</span>
                      </div>
                    )}

                    {task.dueDate && (
                      <div className="flex items-center gap-2">
                        <Calendar className="w-4 h-4" />
                        <span>{new Date(task.dueDate).toLocaleDateString()}</span>
                      </div>
                    )}

                    <div className="flex items-center gap-1">
                      <span className="capitalize text-xs px-2 py-1 bg-[rgb(241,245,249)] rounded-full">
                        {task.category}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TaskList;

'use client';

import React, { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, Clock, Users, ChefHat, Calendar } from 'lucide-react';

