  tripDates,
  groupMembers,
  onMealUpdate
}) => {
  const [meals, setMeals] = useState<Meal[]>([]);
  const [selectedDay, setSelectedDay] = useState<string>(tripDates[0] || '');
  const [isAddingMeal, setIsAddingMeal] = useState(false);
  const [editingMeal, setEditingMeal] = useState<Meal | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [newMeal, setNewMeal] = useState<Partial<Meal>>({
    name: '',
    day: selectedDay,
    time: '',
    type: 'breakfast',
    description: '',
    assignedTo: [],
    ingredients: [],
    servings: groupMembers.length,
    prepTime: 30,
    difficulty: 'easy',
    dietary: [],
    notes: ''
  });

  useEffect(() => {
    loadMeals();
  }, [tripId]);

  useEffect(() => {
    if (onMealUpdate) {
      onMealUpdate(meals);
    }
  }, [meals, onMealUpdate]);

  const loadMeals = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/trips/${tripId}/meals`);
      if (!response.ok) throw new Error('Failed to load meals');
      const data = await response.json();
      setMeals(data);
    } catch (err) {
      setError('Failed to load meal plan');
    } finally {
      setLoading(false);
    }
  };

  const saveMeal = async (meal: Partial<Meal>) => {
    try {
      const method = meal.id ? 'PUT' : 'POST';
      const url = meal.id 
        ? `/api/trips/${tripId}/meals/${meal.id}`
        : `/api/trips/${tripId}/meals`;

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(meal)
      });

      if (!response.ok) throw new Error('Failed to save meal');

      const savedMeal = await response.json();

      if (meal.id) {
        setMeals(prev => prev.map(m => m.id === meal.id ? savedMeal : m));
      } else {
        setMeals(prev => [...prev, savedMeal]);
      }

      resetForm();
    } catch (err) {
      setError('Failed to save meal');
    }
  };

  const deleteMeal = async (mealId: string) => {
    try {
      const response = await fetch(`/api/trips/${tripId}/meals/${mealId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete meal');

      setMeals(prev => prev.filter(m => m.id !== mealId));
    } catch (err) {
      setError('Failed to delete meal');
    }
  };

  const resetForm = () => {
    setNewMeal({
      name: '',
      day: selectedDay,
      time: '',
      type: 'breakfast',
      description: '',
      assignedTo: [],
      ingredients: [],
      servings: groupMembers.length,
      prepTime: 30,
      difficulty: 'easy',
      dietary: [],
      notes: ''
    });
    setIsAddingMeal(false);
    setEditingMeal(null);
  };

  const startEdit = (meal: Meal) => {
    setEditingMeal(meal);
    setNewMeal(meal);
    setIsAddingMeal(true);
  };

  const addIngredient = (ingredient: string) => {
    if (ingredient.trim()) {
      setNewMeal(prev => ({
        ...prev,
        ingredients: [...(prev.ingredients || []), ingredient.trim()]
      }));
    }
  };

  const removeIngredient = (index: number) => {
    setNewMeal(prev => ({
      ...prev,
      ingredients: prev.ingredients?.filter((_, i) => i !== index) || []
    }));
  };

  const toggleAssignment = (memberId: string) => {
    setNewMeal(prev => ({
      ...prev,
      assignedTo: prev.assignedTo?.includes(memberId)
        ? prev.assignedTo.filter(id => id !== memberId)
        : [...(prev.assignedTo || []), memberId]
    }));
  };

  const getMealsByDay = (day: string) => {
    return meals
      .filter(meal => meal.day === day)
      .sort((a, b) => {
        const timeOrder = { breakfast: 1, lunch: 2, dinner: 3, snack: 4 };
        return timeOrder[a.type] - timeOrder[b.type];
      });
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  const getMealTypeIcon = (type: string) => {
    switch (type) {
      case 'breakfast': return '🌅';
      case 'lunch': return '☀️';
      case 'dinner': return '🌙';
      case 'snack': return '🍎';
      default: return '🍽️';
    }
  };

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-[rgb(34,139,34)]';
      case 'medium': return 'bg-[rgb(245,158,11)]';
      case 'hard': return 'bg-[rgb(239,68,68)]';
      default: return 'bg-[rgb(226,232,240)]';
    }
  };

  if (loading) {
    return (
      <div className="p-4 space-y-4">
        <div className="h-8 bg-[rgb(241,245,249)] rounded animate-pulse"></div>
        <div className="space-y-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-24 bg-[rgb(241,245,249)] rounded animate-pulse"></div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] z-10">
        <div className="p-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <ChefHat className="w-6 h-6 text-[rgb(34,139,34)]" />
              <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Menu Planner</h1>
            </div>
            <button
              onClick={() => setIsAddingMeal(true)}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
              aria-label="Add new meal"
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">Add Meal</span>
            </button>
          </div>

          {/* Day Selector */}
          <div className="flex gap-2 overflow-x-auto pb-2">
            {tripDates.map(date => (
              <button
                key={date}
                onClick={() => setSelectedDay(date)}
                className={`flex-shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-colors min-h-[44px] ${
                  selectedDay === date
                    ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                    : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                }`}
                aria-label={`Select ${formatDate(date)}`}
              >
                {formatDate(date)}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="mx-4 mt-4 p-3 bg-[rgb(239,68,68)]/10 border border-[rgb(239,68,68)]/20 rounded-lg">
          <p className="text-[rgb(239,68,68)] text-sm">{error}</p>
          <button
            onClick={() => setError(null)}
            className="text-xs text-[rgb(239,68,68)] underline mt-1"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* Meals List */}
      <div className="p-4 space-y-4">
        {getMealsByDay(selectedDay).length === 0 ? (
          <div className="text-center py-12">
            <ChefHat className="w-12 h-12 text-[rgb(226,232,240)] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No meals planned</h3>
            <p className="text-[rgb(100,116,139)] mb-4">Start planning your meals for this day</p>
            <button
              onClick={() => setIsAddingMeal(true)}
              className="px-6 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
            >
              Add First Meal
            </button>
          </div>
        ) : (
          getMealsByDay(selectedDay).map(meal => (
            <div key={meal.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg shadow-md overflow-hidden">
              <div className="p-4">
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <span className="text-2xl">{getMealTypeIcon(meal.type)}</span>
                    <div>
                      <h3 className="font-semibold text-[rgb(15,23,42)]">{meal.name}</h3>
                      <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                        <Clock className="w-4 h-4" />
                        <span>{meal.time}</span>
                        <span className="capitalize">{meal.type}</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => startEdit(meal)}
                      className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)] rounded transition-colors min-h-[44px] min-w-[44px]"
                      aria-label={`Edit ${meal.name}`}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => deleteMeal(meal.id)}
                      className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(239,68,68)] hover:bg-[rgb(248,250,252)] rounded transition-colors min-h-[44px] min-w-[44px]"
                      aria-label={`Delete ${meal.name}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {meal.description && (
                  <p className="text-[rgb(100,116,139)] text-sm mb-3">{meal.description}</p>
                )}

                <div className="flex flex-wrap gap-2 mb-3">
                  <span className={`px-2 py-1 text-xs text-[rgb(255,255,255)] rounded ${getDifficultyColor(meal.difficulty)}`}>
                    {meal.difficulty}
                  </span>
                  <span className="px-2 py-1 text-xs bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded">
                    {meal.prepTime} min
                  </span>
                  <span className="px-2 py-1 text-xs bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded">
                    Serves {meal.servings}
                  </span>
                </div>

                {meal.assignedTo.length > 0 && (
                  <div className="flex items-center gap-2 mb-3">
                    <Users className="w-4 h-4 text-[rgb(100,116,139)]" />
                    <div className="flex flex-wrap gap-1">
                      {meal.assignedTo.map(memberId => {
                        const member = groupMembers.find(m => m.id === memberId);
                        return member ? (
                          <span key={memberId} className="px-2 py-1 text-xs bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] rounded">
                            {member.name}
                          </span>
                        ) : null;
                      })}
                    </div>
                  </div>
                )}

                {meal.ingredients.length > 0 && (
                  <div className="border-t border-[rgb(226,232,240)] pt-3">
                    <h4 className="text-sm font-medium text-[rgb(15,23,42)] mb-2">Ingredients:</h4>
                    <div className="flex flex-wrap gap-1">
                      {meal.ingredients.map((ingredient, index) => (
                        <span key={index} className="px-2 py-1 text-xs bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded">
                          {ingredient}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Add/Edit Meal Modal */}
      {isAddingMeal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-[rgb(255,255,255)] rounded-t-xl sm:rounded-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] p-4">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">
                {editingMeal ? 'Edit Meal' : 'Add New Meal'}
              </h2>
            </div>

            <div className="p-4 space-y-4">
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Meal Name *
                </label>
                <input
                  type="text"
                  value={newMeal.name || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                  placeholder="Enter meal name"
                  aria-label="Meal name"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Type *
                  </label>
                  <select
                    value={newMeal.type || 'breakfast'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, type: e.target.value as any }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    aria-label="Meal type"
                  >
                    <option value="breakfast">Breakfast</option>
                    <option value="lunch">Lunch</option>
                    <option value="dinner">Dinner</option>
                    <option value="snack">Snack</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Time *
                  </label>
                  <input
                    type="time"
                    value={newMeal.time || ''}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, time: e.target.value }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    aria-label="Meal time"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Description
                </label>
                <textarea
                  value={newMeal.description || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, description: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                  rows={3}
                  placeholder="Describe the meal..."
                  aria-label="Meal description"
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Servings
                  </label>
                  <input
                    type="number"
                    min="1"
                    value={newMeal.servings || groupMembers.length}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, servings: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    aria-label="Number of servings"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Prep Time (min)
                  </label>
                  <input
                    type="number"
                    min="5"
                    step="5"
                    value={newMeal.prepTime || 30}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, prepTime: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    aria-label="Preparation time in minutes"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Difficulty
                  </label>
                  <select
                    value={newMeal.difficulty || 'easy'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, difficulty: e.target.value as any }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                    aria-label="Difficulty level"
                  >
                    <option value="easy">Easy</option>
                    <option value="medium">Medium</option>
                    <option value="hard">Hard</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Assigned To
                </label>
                <div className="space-y-2">
                  {groupMembers.map(member => (
                    <label key={member.id} className="flex items-center gap-3 p-2 hover:bg-[rgb(248,250,252)] rounded cursor-pointer">
                      <input
                        type="checkbox"
                        checked={newMeal.assignedTo?.includes(member.id) || false}
                        onChange={() => toggleAssignment(member.id)}
                        className="w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded focus:ring-[rgb(34,139,34)]"
                        aria-label={`Assign to ${member.name}`}
                      />
                      <span className="text-sm text-[rgb(15,23,42)]">{member.name}</span>
                    </label>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Ingredients
                </label>
                <div className="space-y-2">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      placeholder="Add ingredient..."
                      className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent min-h-[44px]"
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          addIngredient(e.currentTarget.value);
                          e.currentTarget.value = '';
                        }
                      }}
                      aria-label="Add ingredient"
                    />
                    <button
                      onClick={(e) => {
                        const input = e.currentTarget.previousElementSibling as HTMLInputElement;
                        addIngredient(input.value);
                        input.value = '';
                      }}
                      className="px-4 py-2 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(241,245,249)] transition-colors min-h-[44px]"
                      aria-label="Add ingredient to list"
                    >
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                  {newMeal.ingredients && newMeal.ingredients.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {newMeal.ingredients.map((ingredient, index) => (
                        <span
                          key={index}
                          className="flex items-center gap-1 px-2 py-1 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded text-sm"
                        >
                          {ingredient}
                          <button
                            onClick={() => removeIngredient(index)}
                            className="text-[rgb(100,116,139)] hover:text-[rgb(239,68,68)] ml-1"
                            aria-label={`Remove ${ingredient}`}
                          >
                            ×
                          </button>
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Notes
                </label>
                <textarea
                  value={newMeal.notes || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, notes: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                  rows={2}
                  placeholder="Any special notes or instructions..."
                  aria-label="Meal notes"
                />
              </div>
            </div>

            <div className="sticky bottom-0 bg-[rgb(255,255,255)] border-t border-[rgb(226,232,240)] p-4 flex gap-3">
              <button
                onClick={resetForm}
                className="flex-1 px-4 py-3 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors min-h-[44px]"
                aria-label="Cancel meal creation"
              >
                Cancel
              </button>
              <button
                onClick={() => saveMeal(newMeal)}
                disabled={!newMeal.name || !newMeal.time}
                className="flex-1 px-4 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors min-h-[44px]"
                aria-label={editingMeal ? 'Update meal' : 'Save meal'}
              >
                {editingMeal ? 'Update' : 'Save'} Meal
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuPlanner;

