'use client'

import { Calendar, MapPin, Users, Clock, Thermometer, MessageSquare, CheckSquare, Utensils } from 'lucide-react'
import { useState } from 'react'

interface TripMember {
  id: string
  name: string
  email: string
  avatar?: string
  rsvpStatus: 'pending' | 'accepted' | 'declined'
}

interface TripTask {
  id: string
  title: string
  assignedTo?: string
  category: 'food' | 'equipment' | 'logistics' | 'safety'
  completed: boolean
  dueDate?: string
}

interface TripMeal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner' | 'snack'
  assignedTo?: string
}

interface WeatherData {
  day: string
  high: number
  low: number
  condition: string
  precipitation: number
}

interface ChatMessage {
  id: string
  sender: string
  message: string
  timestamp: string
}

interface TripLocation {
  id: string
  name: string
  coordinates: { lat: number; lng: number }
  description?: string
}

interface Trip {
  id: string
  title: string
  description: string
  startDate: string
  endDate: string
  location: TripLocation
  members: TripMember[]
  tasks: TripTask[]
  meals: TripMeal[]
  weather: WeatherData[]
  chat: ChatMessage[]
  createdBy: string
  status: 'planning' | 'confirmed' | 'in-progress' | 'completed' | 'cancelled'
}

interface TripModelProps {
  trip?: Trip
  onUpdate?: (trip: Trip) => void
  onDelete?: (tripId: string) => void
  onInviteMember?: (email: string) => void
  onAssignTask?: (taskId: string, memberId: string) => void
  onSendMessage?: (message: string) => void
}

const DEFAULT_TRIP: Trip = {
  id: '1',
  title: 'Moab Desert Adventure',
  description: 'Epic off-road adventure through the red rocks of Moab, Utah',
  startDate: '2024-03-15',
  endDate: '2024-03-17',
  location: {
    id: 'loc1',
    name: 'Moab, Utah',
    coordinates: { lat: 38.5733, lng: -109.5498 },
    description: 'Famous for its red rock formations and off-road trails'
  },
  members: [
    { id: '1', name: 'Alex Johnson', email: 'alex@example.com', rsvpStatus: 'accepted' },
    { id: '2', name: 'Sarah Chen', email: 'sarah@example.com', rsvpStatus: 'accepted' },
    { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', rsvpStatus: 'pending' },
    { id: '4', name: 'Emma Davis', email: 'emma@example.com', rsvpStatus: 'declined' }
  ],
  tasks: [
    { id: '1', title: 'Bring firewood', assignedTo: '1', category: 'equipment', completed: false, dueDate: '2024-03-14' },
    { id: '2', title: 'Saturday lunch prep', assignedTo: '2', category: 'food', completed: true, dueDate: '2024-03-16' },
    { id: '3', title: 'First aid kit', category: 'safety', completed: false, dueDate: '2024-03-15' },
    { id: '4', title: 'Trail permits', assignedTo: '1', category: 'logistics', completed: true, dueDate: '2024-03-10' }
  ],
  meals: [
    { id: '1', name: 'Campfire Breakfast', day: '2024-03-16', time: 'breakfast', assignedTo: '2' },
    { id: '2', name: 'Trail Mix Lunch', day: '2024-03-16', time: 'lunch', assignedTo: '2' },
    { id: '3', name: 'BBQ Dinner', day: '2024-03-16', time: 'dinner', assignedTo: '1' },
    { id: '4', name: 'Pancake Breakfast', day: '2024-03-17', time: 'breakfast', assignedTo: '3' }
  ],
  weather: [
    { day: '2024-03-15', high: 68, low: 42, condition: 'Sunny', precipitation: 0 },
    { day: '2024-03-16', high: 72, low: 45, condition: 'Partly Cloudy', precipitation: 10 },
    { day: '2024-03-17', high: 65, low: 38, condition: 'Clear', precipitation: 0 }
  ],
  chat: [
    { id: '1', sender: 'Alex Johnson', message: 'Looking forward to this trip!', timestamp: '2024-03-01T10:30:00Z' },
    { id: '2', sender: 'Sarah Chen', message: 'I can handle all the Saturday meals', timestamp: '2024-03-01T14:15:00Z' },
    { id: '3', sender: 'Mike Rodriguez', message: 'Still checking my schedule...', timestamp: '2024-03-02T09:00:00Z' }
  ],
  createdBy: '1',
  status: 'planning'
}

export function TripModel({
  trip = DEFAULT_TRIP,
  onUpdate = () => console.log('Trip updated'),
  onDelete = () => console.log('Trip deleted'),
  onInviteMember = () => console.log('Member invited'),
  onAssignTask = () => console.log('Task assigned'),
  onSendMessage = () => console.log('Message sent')
}: TripModelProps = {}) {
  const [activeTab, setActiveTab] = useState<'overview' | 'tasks' | 'meals' | 'chat'>('overview')
  const [newMessage, setNewMessage] = useState('')

  const getRsvpStatusColor = (status: string) => {
    switch (status) {
      case 'accepted': return 'bg-[rgb(34,139,34)] text-white'
      case 'declined': return 'bg-[rgb(220,38,38)] text-white'
      default: return 'bg-[rgb(245,158,11)] text-white'
    }
  }

  const getTaskCategoryIcon = (category: string) => {
    switch (category) {
      case 'food': return <Utensils className="w-4 h-4" />
      case 'equipment': return <CheckSquare className="w-4 h-4" />
      case 'logistics': return <Calendar className="w-4 h-4" />
      case 'safety': return <Users className="w-4 h-4" />
      default: return <CheckSquare className="w-4 h-4" />
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    })
  }

  const formatTime = (timestamp: string) => {
    return new Date(timestamp).toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit'
    })
  }

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      onSendMessage(newMessage)
      setNewMessage('')
    }
  }

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-lg overflow-hidden font-medium">
      {/* Header */}
      <div className="bg-[rgb(34,139,34)] text-white p-6">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-2xl font-bold mb-2">{trip.title}</h1>
            <p className="text-green-100 mb-4">{trip.description}</p>
            <div className="flex flex-wrap gap-4 text-sm">
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4" />
                <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
              </div>
              <div className="flex items-center gap-2">
                <MapPin className="w-4 h-4" />
                <span>{trip.location.name}</span>
              </div>
              <div className="flex items-center gap-2">
                <Users className="w-4 h-4" />
                <span>{trip.members.length} members</span>
              </div>
            </div>
          </div>
          <div className="flex gap-2">
            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
              trip.status === 'confirmed' ? 'bg-green-500' : 'bg-[rgb(245,158,11)]'
            }`}>
              {trip.status.charAt(0).toUpperCase() + trip.status.slice(1)}
            </span>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="border-b border-[rgb(226,232,240)]">
        <nav className="flex">
          {[
            { id: 'overview', label: 'Overview', icon: MapPin },
            { id: 'tasks', label: 'Tasks', icon: CheckSquare },
            { id: 'meals', label: 'Meals', icon: Utensils },
            { id: 'chat', label: 'Chat', icon: MessageSquare }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex items-center gap-2 px-6 py-4 text-sm font-medium border-b-2 transition-colors ${
                activeTab === id
                  ? 'border-[rgb(34,139,34)] text-[rgb(34,139,34)]'
                  : 'border-transparent text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
              }`}
              aria-label={`View ${label} tab`}
            >
              <Icon className="w-4 h-4" />
              {label}
            </button>
          ))}
        </nav>
      </div>

      {/* Tab Content */}
      <div className="p-6">
        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Weather Forecast */}
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Thermometer className="w-5 h-5" />
                Weather Forecast
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {trip.weather.map((day) => (
                  <div key={day.day} className="bg-[rgb(248,250,252)] rounded-lg p-4">
                    <div className="text-sm text-[rgb(100,116,139)] mb-1">
                      {formatDate(day.day)}
                    </div>
                    <div className="font-semibold text-lg">{day.condition}</div>
                    <div className="flex justify-between items-center mt-2">
                      <span className="text-sm">
                        {day.high}°/{day.low}°F
                      </span>
                      <span className="text-sm text-[rgb(100,116,139)]">
                        {day.precipitation}% rain
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Members & RSVP */}
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Users className="w-5 h-5" />
                Trip Members
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {trip.members.map((member) => (
                  <div key={member.id} className="flex items-center justify-between p-4 bg-[rgb(248,250,252)] rounded-lg">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                        {member.name.charAt(0)}
                      </div>
                      <div>
                        <div className="font-medium">{member.name}</div>
                        <div className="text-sm text-[rgb(100,116,139)]">{member.email}</div>
                      </div>
                    </div>
                    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getRsvpStatusColor(member.rsvpStatus)}`}>
                      {member.rsvpStatus}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'tasks' && (
          <div>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <CheckSquare className="w-5 h-5" />
              Trip Tasks
            </h3>
            <div className="space-y-3">
              {trip.tasks.map((task) => {
                const assignedMember = trip.members.find(m => m.id === task.assignedTo)
                return (
                  <div key={task.id} className="flex items-center gap-4 p-4 bg-[rgb(248,250,252)] rounded-lg">
                    <input
                      type="checkbox"
                      checked={task.completed}
                      onChange={() => {}}
                      className="w-5 h-5 text-[rgb(34,139,34)] rounded focus:ring-2 focus:ring-[rgb(34,139,34)]"
                      aria-label={`Mark ${task.title} as ${task.completed ? 'incomplete' : 'complete'}`}
                    />
                    <div className="flex-1">
                      <div className={`font-medium ${task.completed ? 'line-through text-[rgb(100,116,139)]' : ''}`}>
                        {task.title}
                      </div>
                      <div className="flex items-center gap-4 mt-1 text-sm text-[rgb(100,116,139)]">
                        <div className="flex items-center gap-1">
                          {getTaskCategoryIcon(task.category)}
                          <span className="capitalize">{task.category}</span>
                        </div>
                        {assignedMember && (
                          <span>Assigned to {assignedMember.name}</span>
                        )}
                        {task.dueDate && (
                          <div className="flex items-center gap-1">
                            <Clock className="w-3 h-3" />
                            <span>Due {formatDate(task.dueDate)}</span>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {activeTab === 'meals' && (
          <div>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Utensils className="w-5 h-5" />
              Meal Planning
            </h3>
            <div className="space-y-4">
              {Object.entries(
                trip.meals.reduce((acc, meal) => {
                  if (!acc[meal.day]) acc[meal.day] = []
                  acc[meal.day].push(meal)
                  return acc
                }, {} as Record<string, typeof trip.meals>)
              ).map(([day, meals]) => (
                <div key={day} className="bg-[rgb(248,250,252)] rounded-lg p-4">
                  <h4 className="font-semibold mb-3">{formatDate(day)}</h4>
                  <div className="space-y-2">
                    {meals.sort((a, b) => {
                      const timeOrder = { breakfast: 0, lunch: 1, dinner: 2, snack: 3 }
                      return timeOrder[a.time] - timeOrder[b.time]
                    }).map((meal) => {
                      const assignedMember = trip.members.find(m => m.id === meal.assignedTo)
                      return (
                        <div key={meal.id} className="flex items-center justify-between p-3 bg-white rounded border">
                          <div>
                            <div className="font-medium">{meal.name}</div>
                            <div className="text-sm text-[rgb(100,116,139)] capitalize">{meal.time}</div>
                          </div>
                          {assignedMember && (
                            <div className="text-sm text-[rgb(100,116,139)]">
                              by {assignedMember.name}
                            </div>
                          )}
                        </div>
                      )
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <MessageSquare className="w-5 h-5" />
              Group Chat
            </h3>
            <div className="space-y-4">
              <div className="bg-[rgb(248,250,252)] rounded-lg p-4 max-h-96 overflow-y-auto">
                <div className="space-y-3">
                  {trip.chat.map((message) => (
                    <div key={message.id} className="flex gap-3">
                      <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-semibold flex-shrink-0">
                        {message.sender.charAt(0)}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="font-medium text-sm">{message.sender}</span>
                          <span className="text-xs text-[rgb(100,116,139)]">
                            {formatTime(message.timestamp)}
                          </span>
                        </div>
                        <div className="text-sm">{message.message}</div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Type your message..."
                  className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                  aria-label="Type your message"
                />
                <button
                  onClick={handleSendMessage}
                  disabled={!newMessage.trim()}
                  className="px-6 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-green-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  aria-label="Send message"
                >
                  Send
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default function TripModelDemo() {
  return (
    <div className="min-h-screen bg-[rgb(241,245,249)] p-4">
      <TripModel />
    </div>
  )
}

