'use client'

import { useEffect } from 'react'

interface PWAManifestProps {
  appName?: string
  appDescription?: string
  themeColor?: string
  backgroundColor?: string
  startUrl?: string
  display?: 'standalone' | 'fullscreen' | 'minimal-ui' | 'browser'
  orientation?: 'portrait' | 'landscape' | 'any'
}

export function PWAManifest({
  appName = 'TrailPlan',
  appDescription = 'Plan your off-roading adventures with friends',
  themeColor = '#228B22',
  backgroundColor = '#FFFFFF',
  startUrl = '/',
  display = 'standalone',
  orientation = 'portrait'
}: PWAManifestProps = {}) {
  useEffect(() => {
    // Create manifest object
    const manifest = {
      name: appName,
      short_name: appName,
      description: appDescription,
      start_url: startUrl,
      display: display,
      orientation: orientation,
      theme_color: themeColor,
      background_color: backgroundColor,
      scope: '/',
      lang: 'en-US',
      categories: ['travel', 'outdoor', 'social'],
      icons: [
        {
          src: '/icons/icon-72x72.png',
          sizes: '72x72',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-96x96.png',
          sizes: '96x96',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-128x128.png',
          sizes: '128x128',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-144x144.png',
          sizes: '144x144',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-152x152.png',
          sizes: '152x152',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-192x192.png',
          sizes: '192x192',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-384x384.png',
          sizes: '384x384',
          type: 'image/png',
          purpose: 'maskable any'
        },
        {
          src: '/icons/icon-512x512.png',
          sizes: '512x512',
          type: 'image/png',
          purpose: 'maskable any'
        }
      ],
      shortcuts: [
        {
          name: 'New Trip',
          short_name: 'New Trip',
          description: 'Create a new off-road trip',
          url: '/trips/new',
          icons: [{ src: '/icons/shortcut-new-trip.png', sizes: '96x96' }]
        },
        {
          name: 'My Trips',
          short_name: 'My Trips',
          description: 'View your planned trips',
          url: '/trips',
          icons: [{ src: '/icons/shortcut-trips.png', sizes: '96x96' }]
        },
        {
          name: 'Group Chat',
          short_name: 'Chat',
          description: 'Open group chat',
          url: '/chat',
          icons: [{ src: '/icons/shortcut-chat.png', sizes: '96x96' }]
        }
      ],
      screenshots: [
        {
          src: '/screenshots/mobile-home.png',
          sizes: '390x844',
          type: 'image/png',
          form_factor: 'narrow',
          label: 'Home screen showing upcoming trips'
        },
        {
          src: '/screenshots/mobile-trip-detail.png',
          sizes: '390x844',
          type: 'image/png',
          form_factor: 'narrow',
          label: 'Trip detail with weather and tasks'
        },
        {
          src: '/screenshots/desktop-dashboard.png',
          sizes: '1280x720',
          type: 'image/png',
          form_factor: 'wide',
          label: 'Desktop dashboard view'
        }
      ]
    }

    // Remove existing manifest link if it exists
    const existingLink = document.querySelector('link[rel="manifest"]')
    if (existingLink) {
      existingLink.remove()
    }

    // Create manifest blob and URL
    const manifestBlob = new Blob([JSON.stringify(manifest, null, 2)], {
      type: 'application/json'
    })
    const manifestUrl = URL.createObjectURL(manifestBlob)

    // Create and append new manifest link
    const link = document.createElement('link')
    link.rel = 'manifest'
    link.href = manifestUrl
    document.head.appendChild(link)

    // Add meta tags for better PWA support
    const metaTags = [
      { name: 'theme-color', content: themeColor },
      { name: 'apple-mobile-web-app-capable', content: 'yes' },
      { name: 'apple-mobile-web-app-status-bar-style', content: 'default' },
      { name: 'apple-mobile-web-app-title', content: appName },
      { name: 'mobile-web-app-capable', content: 'yes' },
      { name: 'msapplication-TileColor', content: themeColor },
      { name: 'msapplication-tap-highlight', content: 'no' }
    ]

    metaTags.forEach(({ name, content }) => {
      let meta = document.querySelector(`meta[name="${name}"]`)
      if (!meta) {
        meta = document.createElement('meta')
        meta.setAttribute('name', name)
        document.head.appendChild(meta)
      }
      meta.setAttribute('content', content)
    })

    // Add apple touch icons
    const appleTouchIconSizes = ['57x57', '60x60', '72x72', '76x76', '114x114', '120x120', '144x144', '152x152', '180x180']

    appleTouchIconSizes.forEach(size => {
      let link = document.querySelector(`link[rel="apple-touch-icon"][sizes="${size}"]`)
      if (!link) {
        link = document.createElement('link')
        link.rel = 'apple-touch-icon'
        link.sizes = size
        link.href = `/icons/apple-touch-icon-${size}.png`
        document.head.appendChild(link)
      }
    })

    // Cleanup function
    return () => {
      URL.revokeObjectURL(manifestUrl)
    }
  }, [appName, appDescription, themeColor, backgroundColor, startUrl, display, orientation])

  // Register service worker
  useEffect(() => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('/sw.js')
        .then((registration) => {
          console.log('Service Worker registered successfully:', registration.scope)
        })
        .catch((error) => {
          console.log('Service Worker registration failed:', error)
        })
    }
  }, [])

  return null
}

