import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'

interface RSVPResponse {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  status: 'attending' | 'not-attending' | 'maybe' | 'pending'
  response?: string
  respondedAt?: Date
}

interface TripDetails {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  description: string
  organizer: string
}

interface RSVPModelProps {
  trip?: TripDetails
  currentUserId?: string
  responses?: RSVPResponse[]
  onRSVP?: (status: 'attending' | 'not-attending' | 'maybe', response?: string) => void
  onClose?: () => void
  isOpen?: boolean
}

const DEFAULT_TRIP: TripDetails = {
  id: '1',
  title: 'Moab Desert Adventure',
  location: 'Moab, Utah',
  startDate: new Date('2024-03-15'),
