'use client'

import { useState, useEffect } from 'react'
import { Wifi, WifiOff, Download, Upload, AlertCircle, CheckCircle, Clock } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Progress } from '@/components/ui/progress'

interface OfflineAction {
  id: string
  type: 'trip_update' | 'task_assignment' | 'rsvp' | 'chat_message'
  data: any
  timestamp: number
  status: 'pending' | 'syncing' | 'synced' | 'failed'
}

interface OfflineSupportProps {
  onSync?: (actions: OfflineAction[]) => Promise<void>
  onClearCache?: () => void
  syncInterval?: number
}

export function OfflineSupport({
  onSync = async () => console.log('Syncing offline actions'),
  onClearCache = () => console.log('Clearing cache'),
  syncInterval = 30000
}: OfflineSupportProps = {}) {
  const [isOnline, setIsOnline] = useState(true)
  const [pendingActions, setPendingActions] = useState<OfflineAction[]>([])
  const [syncProgress, setSyncProgress] = useState(0)
  const [isSyncing, setIsSyncing] = useState(false)
  const [cacheSize, setCacheSize] = useState(0)
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null)

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    setIsOnline(navigator.onLine)
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  // Load pending actions from localStorage
  useEffect(() => {
    const loadPendingActions = () => {
      try {
        const stored = localStorage.getItem('offline_actions')
        if (stored) {
          setPendingActions(JSON.parse(stored))
        }
      } catch (error) {
        console.error('Failed to load offline actions:', error)
      }
    }

    loadPendingActions()
  }, [])

  // Calculate cache size
  useEffect(() => {
    const calculateCacheSize = () => {
      let size = 0
      for (let key in localStorage) {
        if (localStorage.hasOwnProperty(key)) {
          size += localStorage[key].length
        }
      }
      setCacheSize(Math.round(size / 1024)) // Convert to KB
    }

    calculateCacheSize()
  }, [pendingActions])

  // Auto-sync when online
  useEffect(() => {
    if (isOnline && pendingActions.length > 0) {
      handleSync()
    }
  }, [isOnline])

  // Periodic sync
  useEffect(() => {
    if (!isOnline) return

    const interval = setInterval(() => {
      if (pendingActions.length > 0) {
        handleSync()
      }
    }, syncInterval)

    return () => clearInterval(interval)
  }, [isOnline, pendingActions.length, syncInterval])

  const handleSync = async () => {
    if (isSyncing || pendingActions.length === 0) return

    setIsSyncing(true)
    setSyncProgress(0)

    try {
      const actionsToSync = pendingActions.filter(action => action.status === 'pending')

      for (let i = 0; i < actionsToSync.length; i++) {
        const action = actionsToSync[i]

        // Update status to syncing
        setPendingActions(prev => 
          prev.map(a => a.id === action.id ? { ...a, status: 'syncing' } : a)
        )

        try {
          await onSync([action])

          // Mark as synced
          setPendingActions(prev => 
            prev.map(a => a.id === action.id ? { ...a, status: 'synced' } : a)
          )
        } catch (error) {
          // Mark as failed
          setPendingActions(prev => 
            prev.map(a => a.id === action.id ? { ...a, status: 'failed' } : a)
          )
        }

        setSyncProgress(((i + 1) / actionsToSync.length) * 100)
      }

      // Remove synced actions after a delay
      setTimeout(() => {
        setPendingActions(prev => prev.filter(action => action.status !== 'synced'))
        localStorage.setItem('offline_actions', JSON.stringify(
          pendingActions.filter(action => action.status !== 'synced')
        ))
      }, 2000)

      setLastSyncTime(new Date())
    } catch (error) {
      console.error('Sync failed:', error)
    } finally {
      setIsSyncing(false)
      setSyncProgress(0)
    }
  }

  const handleClearCache = () => {
    try {
      localStorage.removeItem('offline_actions')
      localStorage.removeItem('cached_trips')
      localStorage.removeItem('cached_weather')
      setPendingActions([])
      onClearCache()
    } catch (error) {
      console.error('Failed to clear cache:', error)
    }
  }

  const getStatusIcon = (status: OfflineAction['status']) => {
    switch (status) {
      case 'pending':
        return <Clock className="h-4 w-4 text-[rgb(245,158,11)]" />
      case 'syncing':
        return <Upload className="h-4 w-4 text-[rgb(34,139,34)] animate-pulse" />
      case 'synced':
        return <CheckCircle className="h-4 w-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="h-4 w-4 text-[rgb(220,38,38)]" />
      default:
        return null
    }
  }

  const getActionTypeLabel = (type: OfflineAction['type']) => {
    switch (type) {
      case 'trip_update':
        return 'Trip Update'
      case 'task_assignment':
        return 'Task Assignment'
      case 'rsvp':
        return 'RSVP'
      case 'chat_message':
        return 'Chat Message'
      default:
        return 'Unknown'
    }
  }

  return (
    <div className="space-y-4 p-4">
      {/* Connection Status */}
      <Card className="border-[rgb(226,232,240)]">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {isOnline ? (
                <Wifi className="h-5 w-5 text-[rgb(34,139,34)]" />
              ) : (
                <WifiOff className="h-5 w-5 text-[rgb(220,38,38)]" />
              )}
              <CardTitle className="text-lg font-medium text-[rgb(15,23,42)]">
                {isOnline ? 'Online' : 'Offline'}
              </CardTitle>
            </div>
            <Badge 
              variant={isOnline ? 'default' : 'destructive'}
              className={isOnline ? 'bg-[rgb(34,139,34)]' : 'bg-[rgb(220,38,38)]'}
            >
              {isOnline ? 'Connected' : 'Disconnected'}
