            <CardDescription className="text-[rgb(100,116,139)]">
              Actions waiting to sync when online
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {isSyncing && (
              <div className="space-y-2">
                <div className="flex items-center justify-between text-sm">
                  <span className="text-[rgb(100,116,139)]">Syncing...</span>
                  <span className="text-[rgb(100,116,139)]">{Math.round(syncProgress)}%</span>
                </div>
                <Progress 
                  value={syncProgress} 
                  className="h-2"
                />
              </div>
            )}

            <div className="space-y-2 max-h-48 overflow-y-auto">
              {pendingActions.map((action) => (
                <div 
                  key={action.id}
                  className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]"
                >
                  <div className="flex items-center gap-3">
                    {getStatusIcon(action.status)}
                    <div>
                      <div className="text-sm font-medium text-[rgb(15,23,42)]">
                        {getActionTypeLabel(action.type)}
                      </div>
                      <div className="text-xs text-[rgb(100,116,139)]">
                        {new Date(action.timestamp).toLocaleTimeString()}
                      </div>
                    </div>
                  </div>
                  <Badge 
                    variant="outline"
                    className={`text-xs ${
                      action.status === 'pending' ? 'border-[rgb(245,158,11)] text-[rgb(245,158,11)]' :
                      action.status === 'syncing' ? 'border-[rgb(34,139,34)] text-[rgb(34,139,34)]' :
                      action.status === 'synced' ? 'border-[rgb(34,139,34)] text-[rgb(34,139,34)]' :
                      'border-[rgb(220,38,38)] text-[rgb(220,38,38)]'
                    }`}
                  >
                    {action.status}
                  </Badge>
                </div>
              ))}
            </div>

            {isOnline && !isSyncing && (
              <Button 
                onClick={handleSync}
                className="w-full bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white"
                size="sm"
              >
                <Upload className="h-4 w-4 mr-2" />
                Sync Now
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      {/* Cache Management */}
      <Card className="border-[rgb(226,232,240)]">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg font-medium text-[rgb(15,23,42)]">
            Cache Management
          </CardTitle>
          <CardDescription className="text-[rgb(100,116,139)]">
            Manage offline data and storage
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-sm font-medium text-[rgb(15,23,42)]">Cache Size</div>
              <div className="text-xs text-[rgb(100,116,139)]">{cacheSize} KB used</div>
            </div>
            <Button 
              variant="outline"
              size="sm"
              onClick={handleClearCache}
              className="border-[rgb(226,232,240)] text-[rgb(100,116,139)] hover:bg-[rgb(248,250,252)]"
            >
              <Download className="h-4 w-4 mr-2" />
              Clear Cache
            </Button>
          </div>

          {lastSyncTime && (
            <div className="text-xs text-[rgb(100,116,139)]">
              Last sync: {lastSyncTime.toLocaleString()}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Offline Tips */}
      {!isOnline && (
        <Alert className="border-[rgb(245,158,11)] bg-[rgb(245,158,11)]/5">
          <AlertCircle className="h-4 w-4 text-[rgb(245,158,11)]" />
          <AlertDescription className="text-[rgb(15,23,42)]">
            <strong>Offline Mode:</strong> You can still view cached trips, add tasks, and send messages. 
            All changes will sync automatically when you're back online.
          </AlertDescription>
        </Alert>
      )}
    </div>
  )
}

