    name: string
    coordinates: {
      lat: number
      lng: number
    }
  }
}

interface WeatherAPIProps {
  location?: { lat: number; lng: number }
  onWeatherUpdate?: (weather: WeatherData) => void
  showAlerts?: boolean
  showForecast?: boolean
  refreshInterval?: number
}

const DEFAULT_WEATHER: WeatherData = {
