'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, MapPin, Plus, X, Check } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { toast } from '@/components/ui/use-toast'

interface CalendarEvent {
  id: string
  title: string
  description?: string
  startDate: string
  endDate: string
  location?: string
  attendees: string[]
  type: 'trip' | 'task' | 'meal' | 'meeting'
  status: 'pending' | 'confirmed' | 'cancelled'
  createdBy: string
  rsvpResponses: Record<string, 'yes' | 'no' | 'maybe'>
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  availability: Record<string, boolean>
}

interface CalendarServiceProps {
  events?: CalendarEvent[]
  members?: GroupMember[]
  onEventCreate?: (event: Omit<CalendarEvent, 'id'>) => void
  onEventUpdate?: (id: string, event: Partial<CalendarEvent>) => void
  onEventDelete?: (id: string) => void
  onRsvpUpdate?: (eventId: string, memberId: string, response: 'yes' | 'no' | 'maybe') => void
  currentUserId?: string
}

const DEFAULT_EVENTS: CalendarEvent[] = [
  {
    id: '1',
    title: 'Moab Off-Road Adventure',
    description: 'Epic weekend trip to Moab with the crew',
    startDate: '2024-03-15T09:00:00',
    endDate: '2024-03-17T17:00:00',
    location: 'Moab, Utah',
    attendees: ['user1', 'user2', 'user3'],
    type: 'trip',
    status: 'confirmed',
    createdBy: 'user1',
    rsvpResponses: {
      'user1': 'yes',
      'user2': 'yes',
      'user3': 'maybe'
    }
  },
  {
    id: '2',
    title: 'Saturday Lunch Prep',
    description: 'Prepare lunch for the group',
    startDate: '2024-03-16T11:00:00',
    endDate: '2024-03-16T12:00:00',
    attendees: ['user2'],
    type: 'task',
    status: 'pending',
    createdBy: 'user1',
    rsvpResponses: {
      'user2': 'yes'
    }
  }
]

const DEFAULT_MEMBERS: GroupMember[] = [
  {
    id: 'user1',
    name: 'Alex Johnson',
    email: 'alex@example.com',
    availability: {
      '2024-03-15': true,
      '2024-03-16': true,
      '2024-03-17': true
    }
  },
  {
    id: 'user2',
    name: 'Sarah Chen',
    email: 'sarah@example.com',
    availability: {
      '2024-03-15': true,
      '2024-03-16': true,
      '2024-03-17': false
    }
  },
  {
    id: 'user3',
    name: 'Mike Rodriguez',
    email: 'mike@example.com',
    availability: {
      '2024-03-15': false,
      '2024-03-16': true,
      '2024-03-17': true
    }
  }
]

export function CalendarService({
  events = DEFAULT_EVENTS,
  members = DEFAULT_MEMBERS,
  onEventCreate = () => console.log('Event created'),
  onEventUpdate = () => console.log('Event updated'),
  onEventDelete = () => console.log('Event deleted'),
  onRsvpUpdate = () => console.log('RSVP updated'),
  currentUserId = 'user1'
}: CalendarServiceProps = {}) {
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0])
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false)
  const [newEvent, setNewEvent] = useState<Partial<CalendarEvent>>({
    title: '',
    description: '',
    startDate: '',
    endDate: '',
    location: '',
    type: 'trip',
    attendees: []
  })
  const [availabilityConflicts, setAvailabilityConflicts] = useState<string[]>([])

  const eventTypes = [
    { value: 'trip', label: 'Trip', icon: MapPin },
    { value: 'task', label: 'Task', icon: Check },
    { value: 'meal', label: 'Meal', icon: Users },
    { value: 'meeting', label: 'Meeting', icon: Calendar }
  ]

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'trip': return 'bg-[rgb(34,139,34)]'
      case 'task': return 'bg-[rgb(245,158,11)]'
      case 'meal': return 'bg-[rgb(99,102,241)]'
      case 'meeting': return 'bg-[rgb(139,69,19)]'
      default: return 'bg-[rgb(107,114,128)]'
    }
  }

  const checkAvailability = (startDate: string, endDate: string, attendeeIds: string[]) => {
    const conflicts: string[] = []
    const start = new Date(startDate).toISOString().split('T')[0]
    const end = new Date(endDate).toISOString().split('T')[0]

    attendeeIds.forEach(memberId => {
      const member = members.find(m => m.id === memberId)
      if (member && (!member.availability[start] || !member.availability[end])) {
        conflicts.push(member.name)
      }
    })

    return conflicts
  }

  const handleCreateEvent = () => {
    if (!newEvent.title || !newEvent.startDate || !newEvent.endDate) {
      toast({
        title: 'Missing Information',
        description: 'Please fill in all required fields',
        variant: 'destructive'
      })
      return
    }

    const conflicts = checkAvailability(
      newEvent.startDate!,
      newEvent.endDate!,
      newEvent.attendees || []
    )

    if (conflicts.length > 0) {
      setAvailabilityConflicts(conflicts)
      return
    }

    const eventToCreate: Omit<CalendarEvent, 'id'> = {
      ...newEvent as CalendarEvent,
      createdBy: currentUserId,
      status: 'pending',
      rsvpResponses: {}
    }

    onEventCreate(eventToCreate)
    setIsCreateDialogOpen(false)
    setNewEvent({
      title: '',
      description: '',
      startDate: '',
      endDate: '',
      location: '',
      type: 'trip',
      attendees: []
    })
    setAvailabilityConflicts([])

    toast({
      title: 'Event Created',
      description: 'Your event has been created and invites will be sent'
    })
  }

  const handleRsvpResponse = (eventId: string, response: 'yes' | 'no' | 'maybe') => {
    onRsvpUpdate(eventId, currentUserId, response)
    toast({
      title: 'RSVP Updated',
      description: `You responded "${response}" to the event`
    })
  }

  const getEventsForDate = (date: string) => {
    return events.filter(event => {
      const eventStart = new Date(event.startDate).toISOString().split('T')[0]
      const eventEnd = new Date(event.endDate).toISOString().split('T')[0]
      return date >= eventStart && date <= eventEnd
    })
  }

  const generateCalendarDays = () => {
    const today = new Date()
    const currentMonth = today.getMonth()
    const currentYear = today.getFullYear()
    const firstDay = new Date(currentYear, currentMonth, 1)
    const lastDay = new Date(currentYear, currentMonth + 1, 0)
    const daysInMonth = lastDay.getDate()
    const startingDayOfWeek = firstDay.getDay()

    const days = []

    // Add empty cells for days before the first day of the month
    for (let i = 0; i < startingDayOfWeek; i++) {
      days.push(null)
    }

    // Add days of the month
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(currentYear, currentMonth, day)
      days.push(date)
    }

    return days
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit'
    })
  }

  return (
    <div className="w-full max-w-6xl mx-auto p-4 space-y-6 font-medium">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Trip Calendar</h1>
          <p className="text-[rgb(107,114,128)]">Plan and coordinate your off-road adventures</p>
        </div>

        <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button 
              className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white w-full sm:w-auto"
              aria-label="Create new event"
            >
              <Plus className="w-4 h-4 mr-2" />
              New Event
            </Button>
          </DialogTrigger>
          <DialogContent className="w-full max-w-md mx-auto">
            <DialogHeader>
              <DialogTitle>Create New Event</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="event-title">Event Title *</Label>
                <Input
                  id="event-title"
                  value={newEvent.title || ''}
                  onChange={(e) => setNewEvent({ ...newEvent, title: e.target.value })}
                  placeholder="Enter event title"
                  className="mt-1"
                />
              </div>

              <div>
                <Label htmlFor="event-type">Event Type</Label>
                <Select
                  value={newEvent.type}
                  onValueChange={(value) => setNewEvent({ ...newEvent, type: value as CalendarEvent['type'] })}
                >
                  <SelectTrigger className="mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {eventTypes.map(type => (
                      <SelectItem key={type.value} value={type.value}>
                        <div className="flex items-center gap-2">
                          <type.icon className="w-4 h-4" />
                          {type.label}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="start-date">Start Date *</Label>
                  <Input
                    id="start-date"
                    type="datetime-local"
                    value={newEvent.startDate || ''}
                    onChange={(e) => setNewEvent({ ...newEvent, startDate: e.target.value })}
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label htmlFor="end-date">End Date *</Label>
                  <Input
                    id="end-date"
                    type="datetime-local"
                    value={newEvent.endDate || ''}
                    onChange={(e) => setNewEvent({ ...newEvent, endDate: e.target.value })}
                    className="mt-1"
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="location">Location</Label>
                <Input
                  id="location"
                  value={newEvent.location || ''}
                  onChange={(e) => setNewEvent({ ...newEvent, location: e.target.value })}
                  placeholder="Event location"
                  className="mt-1"
                />
              </div>

              <div>
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={newEvent.description || ''}
                  onChange={(e) => setNewEvent({ ...newEvent, description: e.target.value })}
                  placeholder="Event description"
                  className="mt-1"
                  rows={3}
                />
              </div>

              <div>
                <Label>Attendees</Label>
                <div className="mt-2 space-y-2">
                  {members.map(member => (
                    <label key={member.id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={newEvent.attendees?.includes(member.id) || false}
                        onChange={(e) => {
                          const attendees = newEvent.attendees || []
                          if (e.target.checked) {
                            setNewEvent({ ...newEvent, attendees: [...attendees, member.id] })
                          } else {
                            setNewEvent({ ...newEvent, attendees: attendees.filter(id => id !== member.id) })
                          }
                        }}
                        className="rounded border-[rgb(226,232,240)]"
                      />
                      <span className="text-sm">{member.name}</span>
                    </label>
                  ))}
                </div>
              </div>

              {availabilityConflicts.length > 0 && (
                <div className="p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
                  <p className="text-sm text-[rgb(220,38,38)] font-medium">Availability Conflicts:</p>
                  <p className="text-sm text-[rgb(220,38,38)]">
                    {availabilityConflicts.join(', ')} may not be available during this time.
                  </p>
                </div>
              )}

              <div className="flex gap-2 pt-4">
                <Button
                  onClick={handleCreateEvent}
                  className="flex-1 bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white"
                >
                  Create Event
                </Button>
                <Button
                  variant="outline"
                  onClick={() => {
                    setIsCreateDialogOpen(false)
                    setAvailabilityConflicts([])
                  }}
                  className="flex-1"
                >
                  Cancel
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Calendar Grid */}
        <div className="lg:col-span-2">
          <Card className="shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Calendar className="w-5 h-5" />
                {new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-7 gap-1 mb-4">
                {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                  <div key={day} className="p-2 text-center text-sm font-medium text-[rgb(107,114,128)]">
                    {day}
                  </div>
                ))}
              </div>

              <div className="grid grid-cols-7 gap-1">
                {generateCalendarDays().map((date, index) => {
                  if (!date) {
                    return <div key={index} className="p-2 h-20"></div>
                  }

                  const dateString = date.toISOString().split('T')[0]
                  const dayEvents = getEventsForDate(dateString)
                  const isSelected = dateString === selectedDate
                  const isToday = dateString === new Date().toISOString().split('T')[0]

                  return (
                    <button
                      key={index}
                      onClick={() => setSelectedDate(dateString)}
                      className={`
                        p-2 h-20 border rounded-lg text-left hover:bg-[rgb(248,250,252)] transition-colors
                        ${isSelected ? 'bg-[rgb(34,139,34)] text-white' : ''}
                        ${isToday && !isSelected ? 'border-[rgb(34,139,34)] border-2' : 'border-[rgb(226,232,240)]'}
                      `}
                      aria-label={`Select ${date.toLocaleDateString()}`}
                    >
                      <div className="font-medium">{date.getDate()}</div>
                      <div className="space-y-1">
                        {dayEvents.slice(0, 2).map(event => (
                          <div
                            key={event.id}
                            className={`
                              w-full h-1 rounded-full
                              ${getEventTypeColor(event.type)}
                              ${isSelected ? 'opacity-80' : ''}
                            `}
                          />
                        ))}
                        {dayEvents.length > 2 && (
                          <div className={`text-xs ${isSelected ? 'text-white' : 'text-[rgb(107,114,128)]'}`}>
                            +{dayEvents.length - 2}
                          </div>
                        )}
                      </div>
                    </button>
                  )
                })}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Events List */}
        <div className="space-y-4">
          <Card className="shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Clock className="w-5 h-5" />
                Events for {new Date(selectedDate).toLocaleDateString()}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {getEventsForDate(selectedDate).length === 0 ? (
                  <div className="text-center py-8 text-[rgb(107,114,128)]">
                    <Calendar className="w-12 h-12 mx-auto mb-3 opacity-50" />
                    <p>No events scheduled</p>
                    <p className="text-sm">Create a new event to get started</p>
                  </div>
                ) : (
                  getEventsForDate(selectedDate).map(event => {
                    const userRsvp = event.rsvpResponses[currentUserId]
                    const attendeeCount = Object.keys(event.rsvpResponses).length
                    const confirmedCount = Object.values(event.rsvpResponses).filter(r => r === 'yes').length

                    return (
                      <Card key={event.id} className="border-l-4" style={{ borderLeftColor: getEventTypeColor(event.type).replace('bg-[', '').replace(']', '') }}>
                        <CardContent className="p-4">
                          <div className="flex justify-between items-start mb-2">
                            <h3 className="font-semibold text-[rgb(15,23,42)]">{event.title}</h3>
                            <Badge variant={event.status === 'confirmed' ? 'default' : 'secondary'}>
                              {event.status}
                            </Badge>
                          </div>

                          {event.description && (
                            <p className="text-sm text-[rgb(107,114,128)] mb-2">{event.description}</p>
                          )}

                          <div className="space-y-1 text-sm text-[rgb(107,114,128)]">
                            <div className="flex items-center gap-2">
                              <Clock className="w-4 h-4" />
                              {formatDate(event.startDate)} - {formatDate(event.endDate)}
                            </div>

                            {event.location && (
                              <div className="flex items-center gap-2">
                                <MapPin className="w-4 h-4" />
                                {event.location}
                              </div>
                            )}

                            <div className="flex items-center gap-2">
                              <Users className="w-4 h-4" />
                              {confirmedCount}/{attendeeCount} confirmed
                            </div>
                          </div>

                          {event.attendees.includes(currentUserId) && (
                            <div className="mt-3 pt-3 border-t border-[rgb(226,232,240)]">
                              <p className="text-sm font-medium mb-2">Your RSVP:</p>
                              <div className="flex gap-2">
                                {[
                                  { value: 'yes', label: 'Yes', color: 'bg-[rgb(34,139,34)]' },
                                  { value: 'maybe', label: 'Maybe', color: 'bg-[rgb(245,158,11)]' },
                                  { value: 'no', label: 'No', color: 'bg-[rgb(220,38,38)]' }
                                ].map(option => (
                                  <Button
                                    key={option.value}
                                    size="sm"
                                    variant={userRsvp === option.value ? 'default' : 'outline'}
                                    onClick={() => handleRsvpResponse(event.id, option.value as 'yes' | 'no' | 'maybe')}
                                    className={userRsvp === option.value ? `${option.color} text-white hover:${option.color}/90` : ''}
                                  >
                                    {option.label}
                                  </Button>
                                ))}
                              </div>
                            </div>
                          )}
                        </CardContent>
                      </Card>
                    )
                  })
                )}
              </div>
            </CardContent>
          </Card>

          {/* Group Availability */}
          <Card className="shadow-md">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Users className="w-5 h-5" />
                Group Availability
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {members.map(member => {
                  const isAvailable = member.availability[selectedDate]
                  return (
                    <div key={member.id} className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium">
                          {member.name.charAt(0)}
                        </div>
                        <span className="font-medium">{member.name}</span>
                      </div>
                      <Badge variant={isAvailable ? 'default' : 'secondary'}>
                        {isAvailable ? 'Available' : 'Busy'}
                      </Badge>
                    </div>
                  )
                })}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  )
}

export default function CalendarServiceDemo() {
  return <CalendarService />
}

