'use client'

import { useState, useEffect } from 'react'
import { Check, X, AlertCircle, Palette, Type, Spacing, Layers } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Alert, AlertDescription } from '@/components/ui/alert'

interface DesignToken {
  id: string
  name: string
  value: string
  category: 'color' | 'typography' | 'spacing' | 'shadow'
  description?: string
}

interface ComponentStatus {
  id: string
  name: string
  status: 'installed' | 'missing' | 'error'
  version?: string
}

interface ShadcnSetupProps {
  tokens?: DesignToken[]
  components?: ComponentStatus[]
  onInstallComponent?: (componentId: string) => void
  onValidateSetup?: () => void
}

export function ShadcnSetup({
  tokens = DEFAULT_TOKENS,
  components = DEFAULT_COMPONENTS,
  onInstallComponent = (id) => console.log('Installing component:', id),
  onValidateSetup = () => console.log('Validating setup')
}: ShadcnSetupProps = {}) {
  const [activeTab, setActiveTab] = useState('overview')
  const [setupStatus, setSetupStatus] = useState<'checking' | 'complete' | 'incomplete'>('checking')

  useEffect(() => {
    const timer = setTimeout(() => {
      const missingComponents = components.filter(c => c.status === 'missing')
      setSetupStatus(missingComponents.length === 0 ? 'complete' : 'incomplete')
    }, 1000)

    return () => clearTimeout(timer)
  }, [components])

  const getStatusIcon = (status: ComponentStatus['status']) => {
    switch (status) {
      case 'installed':
        return <Check className="h-4 w-4 text-[rgb(34,139,34)]" />
      case 'missing':
        return <X className="h-4 w-4 text-[rgb(220,38,38)]" />
      case 'error':
        return <AlertCircle className="h-4 w-4 text-[rgb(245,158,11)]" />
    }
  }

  const getStatusBadge = (status: ComponentStatus['status']) => {
    const variants = {
      installed: 'bg-[rgb(34,139,34)] text-white',
      missing: 'bg-[rgb(220,38,38)] text-white',
      error: 'bg-[rgb(245,158,11)] text-white'
    }

    return (
      <Badge className={variants[status]}>
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    )
  }

  const renderTokenPreview = (token: DesignToken) => {
    switch (token.category) {
      case 'color':
        return (
          <div 
            className="w-8 h-8 rounded border border-[rgb(226,232,240)] shadow-sm"
            style={{ backgroundColor: token.value }}
            aria-label={`Color preview for ${token.name}`}
          />
        )
      case 'typography':
        return (
          <div 
            className="text-[rgb(15,23,42)]"
            style={{ fontSize: token.value, fontWeight: 500 }}
          >
            Aa
          </div>
        )
      case 'spacing':
        return (
          <div 
            className="bg-[rgb(34,139,34)] rounded"
            style={{ width: token.value, height: '16px' }}
          />
        )
      case 'shadow':
        return (
          <div 
            className="w-8 h-8 bg-white rounded border border-[rgb(226,232,240)]"
            style={{ boxShadow: token.value }}
          />
        )
    }
  }

  const getCategoryIcon = (category: DesignToken['category']) => {
    switch (category) {
      case 'color':
        return <Palette className="h-4 w-4" />
      case 'typography':
        return <Type className="h-4 w-4" />
      case 'spacing':
        return <Spacing className="h-4 w-4" />
      case 'shadow':
        return <Layers className="h-4 w-4" />
    }
  }

