              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">Design Tokens</CardTitle>
                <CardDescription>Theme configuration</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="text-2xl font-bold text-[rgb(15,23,42)]">
                    {tokens.length}
                  </div>
                  <div className="text-sm text-[rgb(100,116,139)]">
                    Tokens configured
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardHeader>
              <CardTitle>Quick Actions</CardTitle>
              <CardDescription>Common setup tasks</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex flex-wrap gap-3">
                <Button 
                  onClick={onValidateSetup}
                  className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white"
                >
                  Validate Setup
                </Button>
                <Button variant="outline">
                  Export Config
                </Button>
                <Button variant="outline">
                  View Documentation
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="tokens" className="space-y-6">
          <div className="grid gap-6">
            {['color', 'typography', 'spacing', 'shadow'].map(category => {
              const categoryTokens = tokens.filter(t => t.category === category)

              return (
                <Card key={category}>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2 capitalize">
                      {getCategoryIcon(category as DesignToken['category'])}
                      {category} Tokens
                    </CardTitle>
                    <CardDescription>
                      {categoryTokens.length} tokens configured
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                      {categoryTokens.map(token => (
                        <div 
                          key={token.id}
                          className="flex items-center gap-3 p-3 rounded-lg border border-[rgb(226,232,240)] bg-[rgb(248,250,252)]"
                        >
                          {renderTokenPreview(token)}
                          <div className="flex-1 min-w-0">
                            <div className="font-medium text-sm text-[rgb(15,23,42)] truncate">
                              {token.name}
                            </div>
                            <div className="text-xs text-[rgb(100,116,139)] font-mono truncate">
                              {token.value}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )
            })}
          </div>
        </TabsContent>

        <TabsContent value="components" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Component Status</CardTitle>
              <CardDescription>
                Manage and install shadcn/ui components
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {components.map(component => (
                  <div 
                    key={component.id}
                    className="flex items-center justify-between p-4 rounded-lg border border-[rgb(226,232,240)] bg-[rgb(248,250,252)]"
                  >
                    <div className="flex items-center gap-3">
                      {getStatusIcon(component.status)}
                      <div>
                        <div className="font-medium text-[rgb(15,23,42)]">
                          {component.name}
                        </div>
                        {component.version && (
                          <div className="text-sm text-[rgb(100,116,139)]">
                            v{component.version}
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      {getStatusBadge(component.status)}
                      {component.status === 'missing' && (
                        <Button 
                          size="sm"
                          onClick={() => onInstallComponent(component.id)}
                          className="bg-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/90 text-white"
                        >
                          Install
                        </Button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}

