'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, Check, X, AlertCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { toast } from '@/components/ui/use-toast'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
}

interface AvailabilitySlot {
  id: string
  date: string
  startTime: string
  endTime: string
  available: GroupMember[]
  unavailable: GroupMember[]
  pending: GroupMember[]
}

interface AvailabilityCheckerProps {
  tripId?: string
  members?: GroupMember[]
  proposedDates?: string[]
  onAvailabilityUpdate?: (slotId: string, memberId: string, status: 'available' | 'unavailable') => void
  onDateConfirm?: (slotId: string) => void
}

export function AvailabilityChecker({
  tripId = 'demo-trip',
  members = DEFAULT_MEMBERS,
  proposedDates = DEFAULT_DATES,
  onAvailabilityUpdate = (slotId, memberId, status) => {
    console.log('Availability update:', { slotId, memberId, status })
    toast({
      title: 'Availability Updated',
      description: `Marked as ${status} for the selected date.`,
    })
  },
  onDateConfirm = (slotId) => {
    console.log('Date confirmed:', slotId)
    toast({
      title: 'Date Confirmed',
      description: 'Trip date has been set and invites will be sent.',
    })
  }
}: AvailabilityCheckerProps = {}) {
  const [availabilitySlots, setAvailabilitySlots] = useState<AvailabilitySlot[]>([])
  const [loading, setLoading] = useState(true)
  const [currentUserId] = useState('user-1') // Simulated current user

  useEffect(() => {
    // Simulate loading availability data
    const timer = setTimeout(() => {
      const slots = proposedDates.map((date, index) => ({
        id: `slot-${index}`,
        date,
        startTime: '09:00',
        endTime: '17:00',
        available: members.slice(0, Math.floor(Math.random() * members.length)),
        unavailable: members.slice(Math.floor(Math.random() * members.length)),
        pending: members.filter((_, i) => i === 0) // Current user pending by default
      }))
      setAvailabilitySlots(slots)
      setLoading(false)
    }, 1000)

    return () => clearTimeout(timer)
  }, [proposedDates, members])

  const handleAvailabilityResponse = (slotId: string, status: 'available' | 'unavailable') => {
    setAvailabilitySlots(prev => prev.map(slot => {
      if (slot.id === slotId) {
        const currentUser = members.find(m => m.id === currentUserId)
        if (!currentUser) return slot

        return {
          ...slot,
          available: status === 'available' 
            ? [...slot.available.filter(m => m.id !== currentUserId), currentUser]
            : slot.available.filter(m => m.id !== currentUserId),
          unavailable: status === 'unavailable'
            ? [...slot.unavailable.filter(m => m.id !== currentUserId), currentUser]
            : slot.unavailable.filter(m => m.id !== currentUserId),
          pending: slot.pending.filter(m => m.id !== currentUserId)
        }
      }
      return slot
    }))

    onAvailabilityUpdate(slotId, currentUserId, status)
  }

  const getAvailabilityPercentage = (slot: AvailabilitySlot) => {
    const total = members.length
    const available = slot.available.length
    return Math.round((available / total) * 100)
  }

  const getBestDate = () => {
    return availabilitySlots.reduce((best, current) => {
      const currentPercentage = getAvailabilityPercentage(current)
      const bestPercentage = getAvailabilityPercentage(best)
      return currentPercentage > bestPercentage ? current : best
    }, availabilitySlots[0])
  }

  if (loading) {
    return (
      <div className="w-full max-w-4xl mx-auto p-4 space-y-4">
        <Skeleton className="h-8 w-64" />
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map(i => (
            <Card key={i} className="shadow-md">
              <CardHeader>
                <Skeleton className="h-6 w-32" />
                <Skeleton className="h-4 w-24" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-20 w-full" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    )
  }

  const bestDate = getBestDate()

  return (
    <div className="w-full max-w-4xl mx-auto p-4 space-y-6">
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-bold text-[rgb(15,23,42)]">
          Check Group Availability
        </h2>
        <p className="text-[rgb(100,116,139)]">
          Help us find the best date for everyone to join the adventure
        </p>
      </div>

      {bestDate && (
        <Card className="border-[rgb(34,139,34)] bg-[rgb(248,250,252)] shadow-md">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-[rgb(34,139,34)]" />
              <CardTitle className="text-lg text-[rgb(15,23,42)]">
                Recommended Date
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent>
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div>
                <p className="font-medium text-[rgb(15,23,42)]">
                  {new Date(bestDate.date).toLocaleDateString('en-US', {
                    weekday: 'long',
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                  })}
                </p>
                <p className="text-sm text-[rgb(100,116,139)]">
                  {getAvailabilityPercentage(bestDate)}% of group available
                </p>
              </div>
              <Button
                onClick={() => onDateConfirm(bestDate.id)}
                className="bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white min-h-[44px] px-6"
              >
                Confirm This Date
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {availabilitySlots.map((slot) => {
          const percentage = getAvailabilityPercentage(slot)
          const isCurrentUserPending = slot.pending.some(m => m.id === currentUserId)
          const isCurrentUserAvailable = slot.available.some(m => m.id === currentUserId)
          const isCurrentUserUnavailable = slot.unavailable.some(m => m.id === currentUserId)

          return (
            <Card key={slot.id} className="shadow-md hover:shadow-lg transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Calendar className="h-4 w-4 text-[rgb(34,139,34)]" />
                    <CardTitle className="text-base font-medium text-[rgb(15,23,42)]">
                      {new Date(slot.date).toLocaleDateString('en-US', {
                        month: 'short',
                        day: 'numeric'
                      })}
                    </CardTitle>
                  </div>
                  <Badge 
                    variant={percentage >= 70 ? 'default' : percentage >= 50 ? 'secondary' : 'destructive'}
                    className={
                      percentage >= 70 
                        ? 'bg-[rgb(34,139,34)] text-white' 
                        : percentage >= 50 
                        ? 'bg-[rgb(245,158,11)] text-white'
                        : 'bg-[rgb(220,38,38)] text-white'
                    }
                  >
                    {percentage}%
                  </Badge>
                </div>
                <div className="flex items-center gap-1 text-sm text-[rgb(100,116,139)]">
                  <Clock className="h-3 w-3" />
                  <span>{slot.startTime} - {slot.endTime}</span>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                <div className="space-y-3">
                  {slot.available.length > 0 && (
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Check className="h-4 w-4 text-[rgb(34,139,34)]" />
                        <span className="text-sm font-medium text-[rgb(15,23,42)]">
                          Available ({slot.available.length})
                        </span>
                      </div>
                      <div className="flex flex-wrap gap-1">
                        {slot.available.map((member) => (
                          <Badge 
                            key={member.id} 
                            variant="outline"
                            className="text-xs border-[rgb(34,139,34)] text-[rgb(34,139,34)]"
                          >
                            {member.name}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  )}

                  {slot.unavailable.length > 0 && (
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <X className="h-4 w-4 text-[rgb(220,38,38)]" />
                        <span className="text-sm font-medium text-[rgb(15,23,42)]">
                          Unavailable ({slot.unavailable.length})
                        </span>
                      </div>
                      <div className="flex flex-wrap gap-1">
                        {slot.unavailable.map((member) => (
                          <Badge 
                            key={member.id} 
                            variant="outline"
                            className="text-xs border-[rgb(220,38,38)] text-[rgb(220,38,38)]"
                          >
                            {member.name}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  )}

                  {slot.pending.length > 0 && (
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Users className="h-4 w-4 text-[rgb(245,158,11)]" />
                        <span className="text-sm font-medium text-[rgb(15,23,42)]">
                          Pending ({slot.pending.length})
                        </span>
                      </div>
                      <div className="flex flex-wrap gap-1">
                        {slot.pending.map((member) => (
                          <Badge 
                            key={member.id} 
                            variant="outline"
                            className="text-xs border-[rgb(245,158,11)] text-[rgb(245,158,11)]"
                          >
                            {member.name}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {isCurrentUserPending && (
                  <div className="flex gap-2 pt-2 border-t border-[rgb(226,232,240)]">
                    <Button
                      size="sm"
                      onClick={() => handleAvailabilityResponse(slot.id, 'available')}
                      className="flex-1 bg-[rgb(34,139,34)] hover:bg-[rgb(22,101,22)] text-white min-h-[44px]"
                    >
                      <Check className="h-4 w-4 mr-1" />
                      Available
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleAvailabilityResponse(slot.id, 'unavailable')}
                      className="flex-1 border-[rgb(220,38,38)] text-[rgb(220,38,38)] hover:bg-[rgb(220,38,38)] hover:text-white min-h-[44px]"
                    >
                      <X className="h-4 w-4 mr-1" />
                      Unavailable
                    </Button>
                  </div>
                )}

                {(isCurrentUserAvailable || isCurrentUserUnavailable) && (
                  <div className="pt-2 border-t border-[rgb(226,232,240)]">
                    <p className="text-sm text-[rgb(100,116,139)] text-center">
                      {isCurrentUserAvailable ? 'You marked yourself as available' : 'You marked yourself as unavailable'}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          )
        })}
      </div>

      <div className="text-center text-sm text-[rgb(100,116,139)]">
        <p>
          Responses from {members.length} group members • 
          {availabilitySlots.reduce((total, slot) => total + slot.pending.length, 0)} pending responses
        </p>
      </div>
    </div>
  )
}

