                style={{ color: 'rgb(34, 139, 34)' }}
                aria-label={mode === 'login' ? 'Switch to registration' : 'Switch to login'}
              >
                {mode === 'login' ? 'Sign up' : 'Sign in'}
              </button>
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

