            </button>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Trip Dates */}
            <div className="bg-[rgb(248,250,252)] rounded-lg p-4">
              <h3 className="font-medium text-[rgb(15,23,42)] mb-3 flex items-center gap-2">
