        </div>
      </header>

      {/* Mobile Navigation Overlay */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 z-50 bg-black bg-opacity-50">
          <div className="bg-[rgb(255,255,255)] w-80 h-full shadow-lg">
            <div className="p-4 border-b border-[rgb(226,232,240)]">
              <div className="flex items-center gap-3">
                <Mountain className="w-8 h-8 text-[rgb(34,139,34)]" />
                <h2 className="text-xl font-bold text-[rgb(15,23,42)]">TrailPlan</h2>
              </div>
            </div>
            <nav className="p-4">
              <ul className="space-y-2">
                {navigationItems.map((item) => {
                  const Icon = item.icon
                  const isActive = currentPage === item.id
                  return (
                    <li key={item.id}>
                      <button
                        onClick={() => handleNavigation(item.id)}
                        className={`w-full flex items-center gap-3 p-3 rounded-lg transition-colors text-left ${
                          isActive
                            ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                            : 'text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]'
                        }`}
                        aria-label={`Navigate to ${item.label}`}
                      >
                        <Icon className="w-5 h-5" />
                        <span>{item.label}</span>
                      </button>
                    </li>
                  )
                })}
              </ul>
            </nav>
          </div>
        </div>
      )}

      <div className="lg:flex">
        {/* Desktop Sidebar */}
        <aside className="hidden lg:block w-64 bg-[rgb(248,250,252)] border-r border-[rgb(226,232,240)] min-h-screen">
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <div className="flex items-center gap-3">
              <Mountain className="w-8 h-8 text-[rgb(34,139,34)]" />
              <h1 className="text-xl font-bold text-[rgb(15,23,42)]">TrailPlan</h1>
            </div>
          </div>

          <nav className="p-4">
            <ul className="space-y-2">
              {navigationItems.map((item) => {
                const Icon = item.icon
                const isActive = currentPage === item.id
                return (
                  <li key={item.id}>
                    <button
                      onClick={() => handleNavigation(item.id)}
                      className={`w-full flex items-center gap-3 p-3 rounded-lg transition-colors text-left ${
                        isActive
                          ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                          : 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                      }`}
                      aria-label={`Navigate to ${item.label}`}
                    >
                      <Icon className="w-5 h-5" />
                      <span>{item.label}</span>
                    </button>
                  </li>
                )
              })}
            </ul>
          </nav>

          <div className="absolute bottom-4 left-4 right-4">
            <button
              onClick={() => handleNavigation('settings')}
