'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Mail, Lock, User, ArrowRight } from 'lucide-react'

interface SignInPageProps {
  onSignIn?: (email: string, password: string) => Promise<void>;
  onSignUp?: (name: string, email: string, password: string) => Promise<void>;
  onForgotPassword?: (email: string) => Promise<void>;
}

export function SignInPage({
  onSignIn = async () => console.log('Sign in'),
  onSignUp = async () => console.log('Sign up'),
  onForgotPassword = async () => console.log('Forgot password')
}: SignInPageProps = {}) {
  const [isSignUp, setIsSignUp] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  })

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setIsLoading(true)

    try {
      if (isSignUp) {
        await onSignUp(formData.name, formData.email, formData.password)
      } else {
        await onSignIn(formData.email, formData.password)
      }
    } catch (err) {
      setError(isSignUp ? 'Failed to create account' : 'Invalid credentials')
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = async () => {
    if (!formData.email) {
      setError('Please enter your email address')
      return
    }

    setError('')
    setIsLoading(true)

    try {
      await onForgotPassword(formData.email)
      setError('Password reset link sent to your email')
    } catch (err) {
      setError('Failed to send reset link')
    } finally {
      setIsLoading(false)
    }
  }

  const updateFormData = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (error) setError('')
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-[rgb(34,139,34)] to-[rgb(249,115,22)] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Logo and Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-white rounded-2xl shadow-lg mb-4">
            <Mountain className="w-8 h-8 text-[rgb(34,139,34)]" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-2">TrailPlan</h1>
          <p className="text-white/80 text-base">
            Plan your next off-road adventure
          </p>
        </div>

        {/* Sign In/Up Form */}
        <div className="bg-white rounded-2xl shadow-xl p-6 sm:p-8">
          <div className="mb-6">
            <h2 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">
              {isSignUp ? 'Create Account' : 'Welcome Back'}
            </h2>
            <p className="text-[rgb(100,116,139)] text-sm">
              {isSignUp 
                ? 'Join the adventure community' 
                : 'Sign in to your account'
              }
            </p>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
              <p className="text-[rgb(220,38,38)] text-sm font-medium">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {isSignUp && (
              <div>
                <label htmlFor="name" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Full Name
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                  <input
                    id="name"
                    type="text"
                    value={formData.name}
                    onChange={(e) => updateFormData('name', e.target.value)}
                    className="w-full pl-10 pr-4 py-3 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)]"
                    placeholder="Enter your full name"
                    required={isSignUp}
                    aria-label="Full name"
                  />
                </div>
              </div>
            )}

            <div>
              <label htmlFor="email" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => updateFormData('email', e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)]"
                  placeholder="Enter your email"
                  required
                  aria-label="Email address"
                />
              </div>
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Password
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => updateFormData('password', e.target.value)}
                  className="w-full pl-10 pr-12 py-3 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)]"
                  placeholder="Enter your password"
                  required
                  minLength={6}
                  aria-label="Password"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] rounded"
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            {!isSignUp && (
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={handleForgotPassword}
                  className="text-sm text-[rgb(34,139,34)] hover:text-[rgb(249,115,22)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] rounded px-1 py-1"
                  disabled={isLoading}
                >
                  Forgot password?
                </button>
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-[rgb(34,139,34)] text-white py-3 px-4 rounded-lg font-medium hover:bg-[rgb(22,101,22)] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[rgb(34,139,34)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
              aria-label={isSignUp ? 'Create account' : 'Sign in'}
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  {isSignUp ? 'Create Account' : 'Sign In'}
                  <ArrowRight className="w-5 h-5" />
                </>
              )}
            </button>
          </form>

          <div className="mt-6 text-center">
            <p className="text-[rgb(100,116,139)] text-sm">
              {isSignUp ? 'Already have an account?' : "Don't have an account?"}
              <button
                onClick={() => {
                  setIsSignUp(!isSignUp)
                  setError('')
                  setFormData({ name: '', email: '', password: '' })
                }}
                className="ml-1 text-[rgb(34,139,34)] hover:text-[rgb(249,115,22)] font-medium focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] rounded px-1"
              >
                {isSignUp ? 'Sign in' : 'Sign up'}
              </button>
            </p>
          </div>
        </div>

        {/* Features Preview */}
        <div className="mt-8 text-center">
          <div className="grid grid-cols-3 gap-4 text-white/80">
            <div className="text-center">
              <div className="w-8 h-8 bg-white/20 rounded-lg mx-auto mb-2 flex items-center justify-center">
                <Mountain className="w-4 h-4" />
              </div>
              <p className="text-xs font-medium">Plan Trips</p>
            </div>
            <div className="text-center">
              <div className="w-8 h-8 bg-white/20 rounded-lg mx-auto mb-2 flex items-center justify-center">
                <User className="w-4 h-4" />
              </div>
              <p className="text-xs font-medium">Manage Groups</p>
            </div>
            <div className="text-center">
              <div className="w-8 h-8 bg-white/20 rounded-lg mx-auto mb-2 flex items-center justify-center">
                <Mail className="w-4 h-4" />
              </div>
              <p className="text-xs font-medium">Stay Connected</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function SignInPageDemo() {
  return <SignInPage />
}

'use client'

import { useState } from 'react'
import { Eye, EyeOff, MapPin, Users, Calendar, MessageCircle } from 'lucide-react'

interface SignUpFormData {
  firstName: string
  lastName: string
  email: string
  password: string
  confirmPassword: string
  agreeToTerms: boolean
}

interface FormErrors {
  firstName?: string
  lastName?: string
  email?: string
  password?: string
  confirmPassword?: string
  agreeToTerms?: string
}

export function SignUpPage() {
  const [formData, setFormData] = useState<SignUpFormData>({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
    agreeToTerms: false
  })

  const [errors, setErrors] = useState<FormErrors>({})
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {}

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'First name is required'
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Last name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters'
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your password'
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    if (!formData.agreeToTerms) {
      newErrors.agreeToTerms = 'You must agree to the terms and conditions'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleInputChange = (field: keyof SignUpFormData, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field as keyof FormErrors]) {
      setErrors(prev => ({ ...prev, [field]: undefined }))
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsLoading(true)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000))
      console.log('Sign up successful:', formData)
      // Redirect to dashboard or login
    } catch (error) {
      console.error('Sign up failed:', error)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] flex flex-col">
      {/* Header */}
      <header className="px-4 py-6 border-b border-[#e2e8f0]">
        <div className="max-w-md mx-auto">
          <h1 className="text-2xl font-bold text-[#0f172a] flex items-center gap-2">
            <MapPin className="w-6 h-6 text-[#228b22]" />
            TrailPlan
          </h1>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-4 py-8">
        <div className="max-w-md mx-auto">
          {/* Hero Section */}
          <div className="text-center mb-8">
            <h2 className="text-3xl font-bold text-[#0f172a] mb-3">
              Join the Adventure
            </h2>
            <p className="text-[#64748b] text-lg mb-6">
              Plan epic off-road trips with your crew
            </p>

            {/* Feature Highlights */}
            <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="flex flex-col items-center p-4 bg-[#f8fafc] rounded-lg">
                <MapPin className="w-8 h-8 text-[#228b22] mb-2" />
                <span className="text-sm font-medium text-[#0f172a]">Route Planning</span>
              </div>
              <div className="flex flex-col items-center p-4 bg-[#f8fafc] rounded-lg">
                <Users className="w-8 h-8 text-[#228b22] mb-2" />
                <span className="text-sm font-medium text-[#0f172a]">Group Tasks</span>
              </div>
              <div className="flex flex-col items-center p-4 bg-[#f8fafc] rounded-lg">
                <Calendar className="w-8 h-8 text-[#228b22] mb-2" />
                <span className="text-sm font-medium text-[#0f172a]">Trip Scheduling</span>
              </div>
              <div className="flex flex-col items-center p-4 bg-[#f8fafc] rounded-lg">
                <MessageCircle className="w-8 h-8 text-[#228b22] mb-2" />
                <span className="text-sm font-medium text-[#0f172a]">Group Chat</span>
              </div>
            </div>
          </div>

          {/* Sign Up Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name Fields */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="firstName" className="block text-sm font-medium text-[#0f172a] mb-2">
                  First Name
                </label>
                <input
                  id="firstName"
                  type="text"
                  value={formData.firstName}
                  onChange={(e) => handleInputChange('firstName', e.target.value)}
                  className={`w-full px-3 py-3 border rounded-lg bg-white text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                    errors.firstName ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="John"
                  aria-describedby={errors.firstName ? 'firstName-error' : undefined}
                />
                {errors.firstName && (
                  <p id="firstName-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                    {errors.firstName}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="lastName" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Last Name
                </label>
                <input
                  id="lastName"
                  type="text"
                  value={formData.lastName}
                  onChange={(e) => handleInputChange('lastName', e.target.value)}
                  className={`w-full px-3 py-3 border rounded-lg bg-white text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                    errors.lastName ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="Doe"
                  aria-describedby={errors.lastName ? 'lastName-error' : undefined}
                />
                {errors.lastName && (
                  <p id="lastName-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                    {errors.lastName}
                  </p>
                )}
              </div>
            </div>

            {/* Email Field */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-[#0f172a] mb-2">
                Email Address
              </label>
              <input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => handleInputChange('email', e.target.value)}
                className={`w-full px-3 py-3 border rounded-lg bg-white text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                  errors.email ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                }`}
                placeholder="john@example.com"
                aria-describedby={errors.email ? 'email-error' : undefined}
              />
              {errors.email && (
                <p id="email-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.email}
                </p>
              )}
            </div>

            {/* Password Field */}
            <div>
              <label htmlFor="password" className="block text-sm font-medium text-[#0f172a] mb-2">
                Password
              </label>
              <div className="relative">
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => handleInputChange('password', e.target.value)}
                  className={`w-full px-3 py-3 pr-12 border rounded-lg bg-white text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                    errors.password ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="••••••••"
                  aria-describedby={errors.password ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#64748b] hover:text-[#0f172a] focus:outline-none focus:ring-2 focus:ring-[#228b22] rounded"
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
              {errors.password && (
                <p id="password-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.password}
                </p>
              )}
            </div>

            {/* Confirm Password Field */}
            <div>
              <label htmlFor="confirmPassword" className="block text-sm font-medium text-[#0f172a] mb-2">
                Confirm Password
              </label>
              <div className="relative">
                <input
                  id="confirmPassword"
                  type={showConfirmPassword ? 'text' : 'password'}
                  value={formData.confirmPassword}
                  onChange={(e) => handleInputChange('confirmPassword', e.target.value)}
                  className={`w-full px-3 py-3 pr-12 border rounded-lg bg-white text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                    errors.confirmPassword ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="••••••••"
                  aria-describedby={errors.confirmPassword ? 'confirmPassword-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#64748b] hover:text-[#0f172a] focus:outline-none focus:ring-2 focus:ring-[#228b22] rounded"
                  aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                >
                  {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
              {errors.confirmPassword && (
                <p id="confirmPassword-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.confirmPassword}
                </p>
              )}
            </div>

            {/* Terms Checkbox */}
            <div>
              <label className="flex items-start gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.agreeToTerms}
                  onChange={(e) => handleInputChange('agreeToTerms', e.target.checked)}
                  className="mt-1 w-4 h-4 text-[#228b22] border-[#e2e8f0] rounded focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2"
                  aria-describedby={errors.agreeToTerms ? 'terms-error' : undefined}
                />
                <span className="text-sm text-[#64748b]">
                  I agree to the{' '}
                  <a href="/terms" className="text-[#228b22] hover:underline focus:outline-none focus:ring-2 focus:ring-[#228b22] rounded">
                    Terms of Service
                  </a>{' '}
                  and{' '}
                  <a href="/privacy" className="text-[#228b22] hover:underline focus:outline-none focus:ring-2 focus:ring-[#228b22] rounded">
                    Privacy Policy
                  </a>
                </span>
              </label>
              {errors.agreeToTerms && (
                <p id="terms-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.agreeToTerms}
                </p>
              )}
