'use client'

import { useState, useEffect } from 'react'
import { User, Shield, LogOut, Settings, UserCheck, AlertCircle, CheckCircle } from 'lucide-react'

interface User {
  id: string
  email: string
  name: string
  role: 'admin' | 'member' | 'guest'
  avatar?: string
  lastActive: Date
  isOnline: boolean
}

interface AuthState {
  user: User | null
  isLoading: boolean
  error: string | null
}

interface AuthHelpersProps {
  onSignOut?: () => void
  onProfileUpdate?: (user: User) => void
  showUserMenu?: boolean
  compactMode?: boolean
}

export function AuthHelpers({
  onSignOut = () => console.log('Sign out'),
  onProfileUpdate = () => console.log('Profile updated'),
  showUserMenu = true,
  compactMode = false
}: AuthHelpersProps = {}) {
  const [authState, setAuthState] = useState<AuthState>({
    user: MOCK_USER,
    isLoading: false,
    error: null
  })
  const [showMenu, setShowMenu] = useState(false)
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false)

  const handleSignOut = async () => {
    setAuthState(prev => ({ ...prev, isLoading: true }))
    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      setAuthState({ user: null, isLoading: false, error: null })
      onSignOut()
    } catch (error) {
      setAuthState(prev => ({ 
        ...prev, 
        isLoading: false, 
        error: 'Failed to sign out. Please try again.' 
      }))
    }
  }

  const handleProfileUpdate = async (updates: Partial<User>) => {
    if (!authState.user) return

    setIsUpdatingProfile(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 1500)) // Simulate API call
      const updatedUser = { ...authState.user, ...updates }
      setAuthState(prev => ({ ...prev, user: updatedUser }))
      onProfileUpdate(updatedUser)
    } catch (error) {
      setAuthState(prev => ({ 
        ...prev, 
        error: 'Failed to update profile. Please try again.' 
      }))
    } finally {
      setIsUpdatingProfile(false)
    }
  }

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin': return 'bg-[rgb(220,38,38)] text-white'
      case 'member': return 'bg-[rgb(34,139,34)] text-white'
      case 'guest': return 'bg-[rgb(245,158,11)] text-white'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const formatLastActive = (date: Date) => {
    const now = new Date()
    const diff = now.getTime() - date.getTime()
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) return 'Just now'
    if (minutes < 60) return `${minutes}m ago`
    if (hours < 24) return `${hours}h ago`
    return `${days}d ago`
  }

  if (!authState.user) {
    return (
      <div className="p-4 bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)]">
        <div className="flex items-center gap-3 text-[rgb(15,23,42)]">
          <AlertCircle className="w-5 h-5 text-[rgb(245,158,11)]" />
          <span className="font-medium">Not authenticated</span>
        </div>
      </div>
    )
  }

  return (
    <div className="relative">
      {/* Error Display */}
      {authState.error && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
          <div className="flex items-center gap-2 text-red-700">
            <AlertCircle className="w-4 h-4" />
            <span className="text-sm font-medium">{authState.error}</span>
          </div>
          <button
            onClick={() => setAuthState(prev => ({ ...prev, error: null }))}
            className="mt-2 text-xs text-[rgb(255, 255, 255)] hover:text-red-800 underline"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* User Profile Card */}
      <div className={`bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)] shadow-md ${compactMode ? 'p-3' : 'p-4'}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            {/* Avatar */}
            <div className="relative">
              <div className={`${compactMode ? 'w-8 h-8' : 'w-12 h-12'} bg-[rgb(34,139,34)] rounded-full flex items-center justify-center`}>
                {authState.user.avatar ? (
                  <img 
                    src={authState.user.avatar} 
                    alt={authState.user.name}
                    className="w-full h-full rounded-full object-cover"
                  />
                ) : (
                  <User className={`${compactMode ? 'w-4 h-4' : 'w-6 h-6'} text-white`} />
                )}
              </div>
              {/* Online Status */}
              <div className={`absolute -bottom-1 -right-1 ${compactMode ? 'w-3 h-3' : 'w-4 h-4'} rounded-full border-2 border-white ${
                authState.user.isOnline ? 'bg-green-500' : 'bg-gray-400'
              }`} />
            </div>

            {/* User Info */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <h3 className={`font-semibold text-[rgb(15,23,42)] truncate ${compactMode ? 'text-sm' : 'text-base'}`}>
                  {authState.user.name}
                </h3>
                <span className={`px-2 py-1 text-xs font-medium rounded-full ${getRoleColor(authState.user.role)}`}>
                  {authState.user.role}
                </span>
              </div>
              {!compactMode && (
                <>
                  <p className="text-sm text-gray-600 truncate">{authState.user.email}</p>
                  <p className="text-xs text-gray-500">
                    {authState.user.isOnline ? 'Online' : `Last active ${formatLastActive(authState.user.lastActive)}`}
                  </p>
                </>
              )}
            </div>
          </div>

          {/* Menu Button */}
          {showUserMenu && (
            <button
              onClick={() => setShowMenu(!showMenu)}
              className="p-2 hover:bg-[rgb(241,245,249)] rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="User menu"
            >
              <Settings className="w-4 h-4 text-gray-600" />
            </button>
          )}
        </div>

        {/* User Menu */}
        {showMenu && showUserMenu && (
          <div className="mt-4 pt-4 border-t border-[rgb(226,232,240)]">
            <div className="space-y-2">
              <button
                onClick={() => {
                  handleProfileUpdate({ name: 'Updated Name' })
                  setShowMenu(false)
                }}
                disabled={isUpdatingProfile}
                className="w-full flex items-center gap-3 p-2 text-left hover:bg-[rgb(248,250,252)] rounded-lg transition-colors disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              >
                {isUpdatingProfile ? (
                  <div className="w-4 h-4 border-2 border-[rgb(34,139,34)] border-t-transparent rounded-full animate-spin" />
                ) : (
                  <UserCheck className="w-4 h-4 text-gray-600" />
                )}
                <span className="text-sm font-medium text-[rgb(15,23,42)]">
                  {isUpdatingProfile ? 'Updating...' : 'Update Profile'}
                </span>
              </button>

              <button
                onClick={() => {
                  setShowMenu(false)
                  // Navigate to settings
                }}
                className="w-full flex items-center gap-3 p-2 text-left hover:bg-[rgb(248,250,252)] rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              >
                <Shield className="w-4 h-4 text-gray-600" />
                <span className="text-sm font-medium text-[rgb(15,23,42)]">Privacy Settings</span>
              </button>

              <button
                onClick={handleSignOut}
                disabled={authState.isLoading}
                className="w-full flex items-center gap-3 p-2 text-left hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2"
              >
                {authState.isLoading ? (
                  <div className="w-4 h-4 border-2 border-red-500 border-t-transparent rounded-full animate-spin" />
                ) : (
                  <LogOut className="w-4 h-4 text-[rgb(255, 255, 255)]" />
                )}
                <span className="text-sm font-medium text-[rgb(255, 255, 255)]">
                  {authState.isLoading ? 'Signing out...' : 'Sign Out'}
                </span>
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Success Message */}
      {isUpdatingProfile && (
        <div className="mt-3 p-3 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center gap-2 text-green-700">
            <CheckCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Profile updated successfully!</span>
          </div>
        </div>
      )}
    </div>
  )
}

// Mock data
const MOCK_USER: User = {
  id: '1',
  email: 'trail.explorer@example.com',
  name: 'Alex Trail Explorer',
  role: 'admin',
  lastActive: new Date(Date.now() - 300000), // 5 minutes ago
  isOnline: true
}

// Demo component
export default function AuthHelpersDemo() {
  const [compactMode, setCompactMode] = useState(false)
  const [showUserMenu, setShowUserMenu] = useState(true)

  return (
    <div className="min-h-screen bg-[rgb(248,250,252)] p-4">
      <div className="max-w-md mx-auto space-y-6">
        <div className="bg-white p-4 rounded-lg border border-[rgb(226,232,240)]">
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Auth Helpers Demo</h2>

          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <input
                type="checkbox"
                id="compact"
                checked={compactMode}
                onChange={(e) => setCompactMode(e.target.checked)}
                className="w-4 h-4 text-[rgb(34,139,34)] border-gray-300 rounded focus:ring-[rgb(34,139,34)]"
              />
              <label htmlFor="compact" className="text-sm font-medium text-[rgb(15,23,42)]">
                Compact Mode
              </label>
            </div>

            <div className="flex items-center gap-3">
              <input
                type="checkbox"
                id="menu"
                checked={showUserMenu}
                onChange={(e) => setShowUserMenu(e.target.checked)}
                className="w-4 h-4 text-[rgb(34,139,34)] border-gray-300 rounded focus:ring-[rgb(34,139,34)]"
              />
              <label htmlFor="menu" className="text-sm font-medium text-[rgb(15,23,42)]">
                Show User Menu
              </label>
            </div>
          </div>
        </div>

        <AuthHelpers 
          compactMode={compactMode}
          showUserMenu={showUserMenu}
          onSignOut={() => alert('Signed out!')}
          onProfileUpdate={(user) => alert(`Profile updated for ${user.name}`)}
        />
      </div>
    </div>
  )
}

