        setConnectionStatus({
          status: 'error',
          message: 'Invalid configuration. Please check your credentials.'
        });
      }
    }, 2000);
  };

  const handleSave = () => {
    if (connectionStatus.status === 'connected') {
      onConfigSave(config);
      // Show success feedback
      setConnectionStatus({
        status: 'connected',
        message: 'Configuration saved successfully!'
      });
    } else {
      testConnection();
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const generateProjectRef = () => {
    if (config.url) {
      const match = config.url.match(/https:\/\/([^.]+)\.supabase\.co/);
      if (match) {
        setConfig(prev => ({ ...prev, projectRef: match[1] }));
      }
    }
  };

  useEffect(() => {
    generateProjectRef();
  }, [config.url]);

  return (
    <div className="min-h-screen bg-[#ffffff] p-4">
      <div className="max-w-2xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-[#228b22] rounded-lg">
              <Database className="w-6 h-6 text-[#ffffff]" />
            </div>
            <h1 className="text-2xl font-bold text-[#0f172a]">Supabase Configuration</h1>
          </div>
          <p className="text-[#64748b] font-medium">
            Configure your Supabase connection for the off-roading trip planner
          </p>
        </div>

        {/* Connection Status */}
        <div className="mb-6">
          <div className={`p-4 rounded-lg border-2 ${
            connectionStatus.status === 'connected' 
              ? 'bg-green-50 border-green-200' 
              : connectionStatus.status === 'error'
              ? 'bg-red-50 border-red-200'
              : connectionStatus.status === 'connecting'
              ? 'bg-blue-50 border-blue-200'
              : 'bg-[#f1f5f9] border-[#e2e8f0]'
          }`}>
            <div className="flex items-center gap-3">
              {connectionStatus.status === 'connected' && (
                <CheckCircle className="w-5 h-5 text-green-600" />
              )}
              {connectionStatus.status === 'error' && (
                <AlertCircle className="w-5 h-5 text-[rgb(255, 255, 255)]" />
              )}
              {connectionStatus.status === 'connecting' && (
                <div className="w-5 h-5 border-2 border-blue-600 border-t-transparent rounded-full animate-spin" />
              )}
              {connectionStatus.status === 'idle' && (
                <Settings className="w-5 h-5 text-[#64748b]" />
              )}
              <span className={`font-medium ${
                connectionStatus.status === 'connected' 
                  ? 'text-green-700'
                  : connectionStatus.status === 'error'
                  ? 'text-red-700'
                  : connectionStatus.status === 'connecting'
                  ? 'text-blue-700'
                  : 'text-[#64748b]'
              }`}>
                {connectionStatus.message}
              </span>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="mb-6">
          <div className="flex bg-[#f1f5f9] p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('basic')}
              className={`flex-1 py-2 px-4 rounded-md font-medium transition-colors ${
                activeTab === 'basic'
                  ? 'bg-[#ffffff] text-[#0f172a] shadow-sm'
                  : 'text-[#64748b] hover:text-[#0f172a]'
              }`}
            >
              Basic Configuration
            </button>
            <button
              onClick={() => setActiveTab('advanced')}
              className={`flex-1 py-2 px-4 rounded-md font-medium transition-colors ${
                activeTab === 'advanced'
                  ? 'bg-[#ffffff] text-[#0f172a] shadow-sm'
                  : 'text-[#64748b] hover:text-[#0f172a]'
              }`}
            >
              Advanced Settings
            </button>
          </div>
        </div>

        {/* Configuration Form */}
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-6 shadow-md">
          {activeTab === 'basic' && (
            <div className="space-y-6">
              {/* Project URL */}
              <div>
                <label className="block text-sm font-semibold text-[#0f172a] mb-2">
                  Project URL *
                </label>
                <input
                  type="url"
                  value={config.url}
                  onChange={(e) => setConfig(prev => ({ ...prev, url: e.target.value }))}
                  placeholder="https://your-project.supabase.co"
                  className="w-full px-3 py-3 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent font-medium text-[#0f172a]"
                  aria-label="Supabase project URL"
                />
                <p className="text-xs text-[#64748b] mt-1 font-medium">
                  Found in your Supabase project settings
                </p>
              </div>

              {/* Anonymous Key */}
              <div>
                <label className="block text-sm font-semibold text-[#0f172a] mb-2">
                  Anonymous Key *
                </label>
                <div className="relative">
                  <input
                    type={showKeys.anonKey ? 'text' : 'password'}
                    value={config.anonKey}
                    onChange={(e) => setConfig(prev => ({ ...prev, anonKey: e.target.value }))}
                    placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
                    className="w-full px-3 py-3 pr-20 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent font-medium text-[#0f172a]"
                    aria-label="Supabase anonymous key"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button
                      type="button"
                      onClick={() => setShowKeys(prev => ({ ...prev, anonKey: !prev.anonKey }))}
                      className="p-1.5 text-[#64748b] hover:text-[#0f172a] transition-colors"
                      aria-label={showKeys.anonKey ? 'Hide key' : 'Show key'}
                    >
                      {showKeys.anonKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                    <button
                      type="button"
                      onClick={() => copyToClipboard(config.anonKey)}
                      className="p-1.5 text-[#64748b] hover:text-[#0f172a] transition-colors"
                      aria-label="Copy key"
                    >
                      <Copy className="w-4 h-4" />
                    </button>
                  </div>
                </div>
                <p className="text-xs text-[#64748b] mt-1 font-medium">
                  Safe to use in client-side code
                </p>
              </div>

              {/* Project Reference */}
              <div>
                <label className="block text-sm font-semibold text-[#0f172a] mb-2">
                  Project Reference
                </label>
                <input
                  type="text"
                  value={config.projectRef}
                  onChange={(e) => setConfig(prev => ({ ...prev, projectRef: e.target.value }))}
                  placeholder="your-project-ref"
                  className="w-full px-3 py-3 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent font-medium text-[#0f172a]"
                  aria-label="Supabase project reference"
                />
                <p className="text-xs text-[#64748b] mt-1 font-medium">
                  Auto-generated from URL
                </p>
              </div>
            </div>
          )}

          {activeTab === 'advanced' && (
            <div className="space-y-6">
              {/* Service Key */}
              <div>
                <label className="block text-sm font-semibold text-[#0f172a] mb-2">
                  Service Role Key (Optional)
                </label>
                <div className="relative">
                  <input
                    type={showKeys.serviceKey ? 'text' : 'password'}
                    value={config.serviceKey}
