                    className="w-full px-3 py-3 pr-20 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent font-medium text-[#0f172a]"
                    aria-label="Supabase service role key"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button
                      type="button"
                      onClick={() => setShowKeys(prev => ({ ...prev, serviceKey: !prev.serviceKey }))}
