                      aria-label={showKeys.serviceKey ? 'Hide key' : 'Show key'}
                    >
                      {showKeys.serviceKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                    <button
                      type="button"
                      onClick={() => copyToClipboard(config.serviceKey || '')}
                      className="p-1.5 text-[#64748b] hover:text-[#0f172a] transition-colors"
                      aria-label="Copy key"
                    >
                      <Copy className="w-4 h-4" />
                    </button>
                  </div>
                </div>
                <p className="text-xs text-[rgb(255, 255, 255)] mt-1 font-medium">
                  ⚠️ Keep this secret! Only use server-side
                </p>
              </div>

              {/* Region */}
              <div>
                <label className="block text-sm font-semibold text-[#0f172a] mb-2">
                  Region
                </label>
                <select
                  value={config.region}
                  onChange={(e) => setConfig(prev => ({ ...prev, region: e.target.value }))}
                  className="w-full px-3 py-3 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent font-medium text-[#0f172a] bg-[#ffffff]"
                  aria-label="Select region"
                >
                  {regions.map(region => (
                    <option key={region.value} value={region.value}>
                      {region.label}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-[#64748b] mt-1 font-medium">
                  Choose the region closest to your users
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="mt-8 flex flex-col sm:flex-row gap-3">
          <button
            onClick={testConnection}
            disabled={connectionStatus.status === 'connecting'}
            className="flex-1 px-6 py-3 border border-[#e2e8f0] text-[#0f172a] rounded-lg hover:bg-[#f8fafc] transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Test connection"
          >
            {connectionStatus.status === 'connecting' ? 'Testing...' : 'Test Connection'}
          </button>
          <button
            onClick={handleSave}
            disabled={connectionStatus.status === 'connecting'}
            className="flex-1 px-6 py-3 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7a1e] transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
            aria-label="Save configuration"
          >
            Save Configuration
          </button>
        </div>

        {/* Help Text */}
        <div className="mt-6 p-4 bg-[#f8fafc] border border-[#e2e8f0] rounded-lg">
          <h3 className="font-semibold text-[#0f172a] mb-2">Need help?</h3>
          <ul className="text-sm text-[#64748b] space-y-1 font-medium">
            <li>• Find your credentials in your Supabase project dashboard</li>
            <li>• The anonymous key is safe for client-side use</li>
            <li>• Service role key should only be used server-side</li>
            <li>• Test your connection before saving</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

// Demo component for page.tsx
export default function SupabaseConfigDemo() {
  return (
    <SupabaseConfig
      onConfigSave={(config) => {
        console.log('Configuration saved:', config);
        alert('Configuration saved successfully!');
      }}
      initialConfig={{
        url: 'https://example-project.supabase.co',
        region: 'us-east-1'
      }}
    />
  );
}

