'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Mail, Lock, User } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignup?: (name: string, email: string, password: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignup = (name, email, password) => console.log('Signup:', { name, email, password }),
  onForgotPassword = (email) => console.log('Forgot password:', email)
}: LoginPageProps = {}) {
  const [isLogin, setIsLogin] = useState(true)
  const [showPassword, setShowPassword] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  })
  const [isLoading, setIsLoading] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.email) {
      newErrors.email = 'Email is required'
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 6) {
      newErrors.password = 'Password must be at least 6 characters'
    }

    if (!isLogin && !formData.name) {
      newErrors.name = 'Name is required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsLoading(true)

    try {
      if (isLogin) {
        await onLogin(formData.email, formData.password)
      } else {
        await onSignup(formData.name, formData.email, formData.password)
      }
    } catch (error) {
      console.error('Authentication error:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (!formData.email) {
      setErrors({ email: 'Please enter your email first' })
      return
    }
    onForgotPassword(formData.email)
  }

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: 'rgb(255, 255, 255)' }}>
      {/* Header */}
      <div className="flex items-center justify-center pt-8 pb-4">
        <div className="flex items-center gap-3">
          <div 
            className="p-3 rounded-xl shadow-md"
            style={{ backgroundColor: 'rgb(34, 139, 34)' }}
          >
            <Mountain className="w-8 h-8" style={{ color: 'rgb(255, 255, 255)' }} />
          </div>
          <div>
            <h1 className="text-2xl font-bold" style={{ color: 'rgb(15, 23, 42)' }}>
              TrailPlan
            </h1>
            <p className="text-sm" style={{ color: 'rgb(100, 116, 139)' }}>
              Plan epic off-road adventures
            </p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex items-center justify-center px-4 pb-8">
        <div className="w-full max-w-md">
          {/* Welcome Message */}
          <div className="text-center mb-8">
            <h2 className="text-3xl font-bold mb-2" style={{ color: 'rgb(15, 23, 42)' }}>
              {isLogin ? 'Welcome back!' : 'Join the adventure'}
            </h2>
            <p className="text-base" style={{ color: 'rgb(100, 116, 139)' }}>
              {isLogin 
                ? 'Sign in to plan your next off-road trip' 
                : 'Create an account to start planning trips'
              }
            </p>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name Field (Signup only) */}
            {!isLogin && (
              <div>
                <label 
                  htmlFor="name" 
                  className="block text-sm font-medium mb-2"
                  style={{ color: 'rgb(15, 23, 42)' }}
                >
                  Full Name
                </label>
                <div className="relative">
                  <User 
                    className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5"
                    style={{ color: 'rgb(100, 116, 139)' }}
                  />
                  <input
                    id="name"
                    type="text"
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    className="w-full pl-10 pr-4 py-3 rounded-lg border focus:outline-none focus:ring-2 focus:ring-offset-2 transition-colors"
                    style={{ 
                      borderColor: errors.name ? 'rgb(220, 38, 38)' : 'rgb(226, 232, 240)',
                      backgroundColor: 'rgb(255, 255, 255)',
                      color: 'rgb(15, 23, 42)',
                      focusRingColor: 'rgb(34, 139, 34)'
                    }}
                    placeholder="Enter your full name"
                    aria-label="Full Name"
                    aria-invalid={!!errors.name}
                    aria-describedby={errors.name ? 'name-error' : undefined}
                  />
                </div>
                {errors.name && (
                  <p id="name-error" className="mt-1 text-sm" style={{ color: 'rgb(220, 38, 38)' }}>
                    {errors.name}
                  </p>
                )}
              </div>
            )}

            {/* Email Field */}
            <div>
              <label 
                htmlFor="email" 
                className="block text-sm font-medium mb-2"
                style={{ color: 'rgb(15, 23, 42)' }}
              >
                Email Address
              </label>
              <div className="relative">
                <Mail 
                  className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5"
                  style={{ color: 'rgb(100, 116, 139)' }}
                />
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  className="w-full pl-10 pr-4 py-3 rounded-lg border focus:outline-none focus:ring-2 focus:ring-offset-2 transition-colors"
                  style={{ 
                    borderColor: errors.email ? 'rgb(220, 38, 38)' : 'rgb(226, 232, 240)',
                    backgroundColor: 'rgb(255, 255, 255)',
                    color: 'rgb(15, 23, 42)',
                    focusRingColor: 'rgb(34, 139, 34)'
                  }}
                  placeholder="Enter your email"
                  aria-label="Email Address"
                  aria-invalid={!!errors.email}
                  aria-describedby={errors.email ? 'email-error' : undefined}
                />
              </div>
              {errors.email && (
                <p id="email-error" className="mt-1 text-sm" style={{ color: 'rgb(220, 38, 38)' }}>
                  {errors.email}
                </p>
              )}
            </div>

            {/* Password Field */}
            <div>
              <label 
                htmlFor="password" 
                className="block text-sm font-medium mb-2"
                style={{ color: 'rgb(15, 23, 42)' }}
              >
                Password
              </label>
              <div className="relative">
                <Lock 
                  className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5"
                  style={{ color: 'rgb(100, 116, 139)' }}
                />
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => handleInputChange('password', e.target.value)}
                  className="w-full pl-10 pr-12 py-3 rounded-lg border focus:outline-none focus:ring-2 focus:ring-offset-2 transition-colors"
                  style={{ 
                    borderColor: errors.password ? 'rgb(220, 38, 38)' : 'rgb(226, 232, 240)',
                    backgroundColor: 'rgb(255, 255, 255)',
                    color: 'rgb(15, 23, 42)',
                    focusRingColor: 'rgb(34, 139, 34)'
                  }}
                  placeholder="Enter your password"
                  aria-label="Password"
                  aria-invalid={!!errors.password}
                  aria-describedby={errors.password ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 rounded focus:outline-none focus:ring-2 focus:ring-offset-2"
                  style={{ focusRingColor: 'rgb(34, 139, 34)' }}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? (
                    <EyeOff className="w-5 h-5" style={{ color: 'rgb(100, 116, 139)' }} />
                  ) : (
                    <Eye className="w-5 h-5" style={{ color: 'rgb(100, 116, 139)' }} />
                  )}
                </button>
              </div>
              {errors.password && (
                <p id="password-error" className="mt-1 text-sm" style={{ color: 'rgb(220, 38, 38)' }}>
                  {errors.password}
                </p>
              )}
            </div>

            {/* Forgot Password Link (Login only) */}
            {isLogin && (
              <div className="text-right">
                <button
                  type="button"
                  onClick={handleForgotPassword}
                  className="text-sm font-medium hover:underline focus:outline-none focus:underline"
                  style={{ color: 'rgb(34, 139, 34)' }}
                >
                  Forgot password?
                </button>
              </div>
            )}

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 px-4 rounded-lg font-semibold text-base transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed"
              style={{ 
                backgroundColor: isLoading ? 'rgb(100, 116, 139)' : 'rgb(34, 139, 34)',
                color: 'rgb(255, 255, 255)',
                focusRingColor: 'rgb(34, 139, 34)'
              }}
              aria-label={isLogin ? 'Sign in to your account' : 'Create new account'}
            >
              {isLoading ? 'Please wait...' : (isLogin ? 'Sign In' : 'Create Account')}
            </button>
          </form>

          {/* Toggle Form Type */}
          <div className="mt-8 text-center">
            <p className="text-sm" style={{ color: 'rgb(100, 116, 139)' }}>
              {isLogin ? "Don't have an account?" : 'Already have an account?'}
              <button
                onClick={() => {
                  setIsLogin(!isLogin)
                  setErrors({})
                  setFormData({ name: '', email: '', password: '' })
                }}
                className="ml-2 font-semibold hover:underline focus:outline-none focus:underline"
                style={{ color: 'rgb(34, 139, 34)' }}
              >
                {isLogin ? 'Sign up' : 'Sign in'}
              </button>
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function LoginPageDemo() {
  return <LoginPage />
}

code.api-route:
'use client'

import { useState, useEffect } from 'react'
import { Send, Calendar, Users, MapPin, Clock, Check, X, Mail } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  avatar?: string
  rsvpStatus: 'pending' | 'accepted' | 'declined'
  rsvpDate?: string
}

interface TripInvitation {
  id: string
  tripId: string
  tripName: string
  location: string
  startDate: string
  endDate: string
  organizer: string
  members: TripMember[]
  description: string
  invitationSent: boolean
  sentDate?: string
}

interface TripInvitationsProps {
  trips?: TripInvitation[]
  onSendInvitation?: (tripId: string) => void
  onResendInvitation?: (tripId: string, memberId: string) => void
  onRemoveMember?: (tripId: string, memberId: string) => void
}

export function TripInvitations({
  trips = DEFAULT_TRIPS,
  onSendInvitation = (tripId) => console.log('Sending invitation for trip:', tripId),
  onResendInvitation = (tripId, memberId) => console.log('Resending invitation:', { tripId, memberId }),
  onRemoveMember = (tripId, memberId) => console.log('Removing member:', { tripId, memberId })
}: TripInvitationsProps = {}) {
  const [selectedTrip, setSelectedTrip] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState<{ [key: string]: boolean }>({})

  const handleSendInvitation = async (tripId: string) => {
    setIsLoading(prev => ({ ...prev, [tripId]: true }))

    try {
      await new Promise(resolve => setTimeout(resolve, 1500)) // Simulate API call
      onSendInvitation(tripId)
    } finally {
      setIsLoading(prev => ({ ...prev, [tripId]: false }))
    }
  }

  const handleResendInvitation = async (tripId: string, memberId: string) => {
    setIsLoading(prev => ({ ...prev, [`${tripId}-${memberId}`]: true }))

    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onResendInvitation(tripId, memberId)
    } finally {
      setIsLoading(prev => ({ ...prev, [`${tripId}-${memberId}`]: false }))
    }
  }

  const getRsvpStatusColor = (status: string) => {
    switch (status) {
      case 'accepted':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'declined':
        return 'bg-[rgb(220,38,38)] text-white'
      default:
        return 'bg-[rgb(245,158,11)] text-white'
    }
  }

  const getRsvpStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted':
        return <Check className="w-3 h-3" />
      case 'declined':
        return <X className="w-3 h-3" />
      default:
        return <Clock className="w-3 h-3" />
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    })
  }

  const getPendingCount = (members: TripMember[]) => {
    return members.filter(member => member.rsvpStatus === 'pending').length
  }

  const getAcceptedCount = (members: TripMember[]) => {
    return members.filter(member => member.rsvpStatus === 'accepted').length
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 pb-20">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">
            Trip Invitations
          </h1>
          <p className="text-[rgb(15,23,42)] opacity-70">
            Manage and track invitations for your off-road adventures
          </p>
        </div>

        {/* Trip Cards */}
        <div className="space-y-4">
          {trips.map((trip) => (
            <div
              key={trip.id}
              className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] overflow-hidden"
            >
              {/* Trip Header */}
              <div className="p-4 border-b border-[rgb(226,232,240)]">
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-1">
                      {trip.tripName}
                    </h3>
                    <div className="flex items-center gap-4 text-sm text-[rgb(15,23,42)] opacity-70">
                      <div className="flex items-center gap-1">
                        <MapPin className="w-4 h-4" />
                        <span>{trip.location}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <Calendar className="w-4 h-4" />
                        <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
                      </div>
                    </div>
                  </div>

                  {!trip.invitationSent ? (
                    <button
                      onClick={() => handleSendInvitation(trip.id)}
                      disabled={isLoading[trip.id]}
                      className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 min-h-[44px]"
                      aria-label={`Send invitations for ${trip.tripName}`}
                    >
                      {isLoading[trip.id] ? (
                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      ) : (
                        <Send className="w-4 h-4" />
                      )}
                      <span className="hidden sm:inline">
                        {isLoading[trip.id] ? 'Sending...' : 'Send Invites'}
                      </span>
                    </button>
                  ) : (
                    <div className="text-sm text-[rgb(15,23,42)] opacity-70">
                      Sent {trip.sentDate && formatDate(trip.sentDate)}
                    </div>
                  )}
                </div>

                {/* Trip Stats */}
                <div className="flex items-center gap-4 text-sm">
                  <div className="flex items-center gap-1">
                    <Users className="w-4 h-4 text-[rgb(34,139,34)]" />
                    <span className="text-[rgb(15,23,42)]">
                      {getAcceptedCount(trip.members)}/{trip.members.length} confirmed
                    </span>
                  </div>
                  {getPendingCount(trip.members) > 0 && (
                    <div className="flex items-center gap-1">
                      <Clock className="w-4 h-4 text-[rgb(245,158,11)]" />
                      <span className="text-[rgb(15,23,42)]">
                        {getPendingCount(trip.members)} pending
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {/* Trip Description */}
              {trip.description && (
                <div className="p-4 bg-[rgb(248,250,252)] border-b border-[rgb(226,232,240)]">
                  <p className="text-sm text-[rgb(15,23,42)] opacity-80">
                    {trip.description}
                  </p>
                </div>
              )}

              {/* Members List */}
              <div className="p-4">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="font-semibold text-[rgb(15,23,42)]">
                    Invited Members ({trip.members.length})
                  </h4>
                  <button
                    onClick={() => setSelectedTrip(selectedTrip === trip.id ? null : trip.id)}
                    className="text-sm text-[rgb(34,139,34)] hover:underline"
                    aria-label={`${selectedTrip === trip.id ? 'Hide' : 'Show'} member details for ${trip.tripName}`}
                  >
                    {selectedTrip === trip.id ? 'Hide Details' : 'View Details'}
                  </button>
                </div>

                {selectedTrip === trip.id && (
                  <div className="space-y-3">
                    {trip.members.map((member) => (
                      <div
                        key={member.id}
                        className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg"
                      >
                        <div className="flex items-center gap-3 flex-1">
                          <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                            {member.name.charAt(0).toUpperCase()}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="font-medium text-[rgb(15,23,42)] truncate">
                              {member.name}
                            </div>
                            <div className="text-sm text-[rgb(15,23,42)] opacity-70 truncate">
                              {member.email}
                            </div>
                            {member.rsvpDate && (
                              <div className="text-xs text-[rgb(15,23,42)] opacity-50">
                                Responded {formatDate(member.rsvpDate)}
                              </div>
                            )}
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          <span
                            className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getRsvpStatusColor(member.rsvpStatus)}`}
                          >
                            {getRsvpStatusIcon(member.rsvpStatus)}
                            <span className="capitalize">{member.rsvpStatus}</span>
                          </span>

                          {trip.invitationSent && member.rsvpStatus === 'pending' && (
                            <button
                              onClick={() => handleResendInvitation(trip.id, member.id)}
                              disabled={isLoading[`${trip.id}-${member.id}`]}
                              className="p-2 text-[rgb(34,139,34)] hover:bg-[rgb(34,139,34)]/10 rounded-lg transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center"
                              aria-label={`Resend invitation to ${member.name}`}
                            >
                              {isLoading[`${trip.id}-${member.id}`] ? (
                                <div className="w-4 h-4 border-2 border-[rgb(34,139,34)] border-t-transparent rounded-full animate-spin" />
                              ) : (
                                <Mail className="w-4 h-4" />
                              )}
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {selectedTrip !== trip.id && (
                  <div className="flex items-center gap-2">
                    {trip.members.slice(0, 5).map((member) => (
                      <div
                        key={member.id}
                        className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium"
                        title={member.name}
                      >
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                    ))}
                    {trip.members.length > 5 && (
                      <div className="w-8 h-8 bg-[rgb(226,232,240)] rounded-full flex items-center justify-center text-[rgb(15,23,42)] text-sm font-medium">
                        +{trip.members.length - 5}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>

        {trips.length === 0 && (
          <div className="text-center py-12">
            <Send className="w-12 h-12 text-[rgb(226,232,240)] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">
              No Trip Invitations
            </h3>
            <p className="text-[rgb(15,23,42)] opacity-70 max-w-md mx-auto">
              Create your first off-road trip and start inviting your adventure crew!
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

const DEFAULT_TRIPS: TripInvitation[] = [
  {
    id: '1',
    tripId: 'trip-1',
    tripName: 'Moab Desert Adventure',
    location: 'Moab, Utah',
    startDate: '2024-03-15',
    endDate: '2024-03-17',
    organizer: 'John Smith',
    description: 'Epic 3-day off-road adventure through the red rocks of Moab. We\'ll tackle Hell\'s Revenge trail and camp under the stars.',
    invitationSent: true,
    sentDate: '2024-02-20',
    members: [
      {
