code.database-schema:
'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar } from 'lucide-react'

interface RsvpResponse {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  status: 'pending' | 'accepted' | 'declined' | 'maybe'
  respondedAt?: Date
  notes?: string
}

interface Trip {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  description?: string
}

interface RsvpModelProps {
  trip?: Trip
  responses?: RsvpResponse[]
  currentUserId?: string
  onRsvpUpdate?: (userId: string, status: RsvpResponse['status'], notes?: string) => void
  onSendReminder?: (userIds: string[]) => void
}

const DEFAULT_TRIP: Trip = {
  id: '1',
  title: 'Moab Desert Adventure',
  location: 'Moab, Utah',
  startDate: new Date('2024-03-15'),
  endDate: new Date('2024-03-17'),
  description: 'Epic off-road adventure through the red rocks of Moab'
}

const DEFAULT_RESPONSES: RsvpResponse[] = [
  {
    id: '1',
    userId: 'user1',
    userName: 'Sarah Johnson',
    userAvatar: 'SJ',
    status: 'accepted',
    respondedAt: new Date('2024-02-10'),
    notes: 'Can\'t wait! Bringing my Jeep Wrangler'
  },
  {
    id: '2',
    userId: 'user2',
    userName: 'Mike Chen',
    userAvatar: 'MC',
    status: 'maybe',
    respondedAt: new Date('2024-02-12'),
    notes: 'Need to check work schedule'
  },
  {
    id: '3',
    userId: 'user3',
    userName: 'Alex Rivera',
    userAvatar: 'AR',
    status: 'pending'
  },
  {
    id: '4',
    userId: 'user4',
    userName: 'Emma Davis',
    userAvatar: 'ED',
    status: 'declined',
    respondedAt: new Date('2024-02-11'),
    notes: 'Family commitment that weekend'
  }
]

export function RsvpModel({
  trip = DEFAULT_TRIP,
  responses = DEFAULT_RESPONSES,
  currentUserId = 'user3',
  onRsvpUpdate = (userId, status, notes) => console.log('RSVP updated:', { userId, status, notes }),
  onSendReminder = (userIds) => console.log('Reminder sent to:', userIds)
}: RsvpModelProps = {}) {
  const [localResponses, setLocalResponses] = useState<RsvpResponse[]>(responses)
  const [showRsvpForm, setShowRsvpForm] = useState(false)
  const [selectedStatus, setSelectedStatus] = useState<RsvpResponse['status']>('pending')
  const [notes, setNotes] = useState('')
  const [selectedUsers, setSelectedUsers] = useState<string[]>([])

  const currentUserResponse = localResponses.find(r => r.userId === currentUserId)
  const pendingUsers = localResponses.filter(r => r.status === 'pending')
  const acceptedCount = localResponses.filter(r => r.status === 'accepted').length
  const totalCount = localResponses.length

  useEffect(() => {
    setLocalResponses(responses)
  }, [responses])

  const handleRsvpSubmit = () => {
    const updatedResponses = localResponses.map(response => 
      response.userId === currentUserId
        ? {
            ...response,
            status: selectedStatus,
            respondedAt: new Date(),
            notes: notes.trim() || undefined
          }
        : response
    )

    setLocalResponses(updatedResponses)
    onRsvpUpdate(currentUserId, selectedStatus, notes.trim() || undefined)
    setShowRsvpForm(false)
    setNotes('')
  }

  const handleSendReminder = () => {
    if (selectedUsers.length > 0) {
      onSendReminder(selectedUsers)
      setSelectedUsers([])
    }
  }

  const getStatusColor = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'declined':
        return 'bg-[rgb(220,38,38)] text-white'
      case 'maybe':
        return 'bg-[rgb(245,158,11)] text-white'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getStatusIcon = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted':
        return <Check className="w-4 h-4" />
      case 'declined':
        return <X className="w-4 h-4" />
      case 'maybe':
        return <Clock className="w-4 h-4" />
      default:
        return <Clock className="w-4 h-4" />
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="bg-[rgb(34,139,34)] text-white p-6">
        <div className="flex items-center gap-3 mb-4">
          <MapPin className="w-6 h-6" />
          <div>
            <h1 className="text-xl font-semibold">{trip.title}</h1>
            <p className="text-sm opacity-90">{trip.location}</p>
          </div>
        </div>

        <div className="flex items-center gap-4 text-sm">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4" />
            <span>
              {trip.startDate.toLocaleDateString()} - {trip.endDate.toLocaleDateString()}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4" />
            <span>{acceptedCount}/{totalCount} confirmed</span>
          </div>
        </div>
      </div>

      {/* Current User RSVP Status */}
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Your RSVP</h2>
          {currentUserResponse?.status !== 'pending' && (
            <button
              onClick={() => setShowRsvpForm(true)}
              className="text-sm text-[rgb(34,139,34)] font-medium"
              aria-label="Change RSVP response"
            >
              Change
            </button>
          )}
        </div>

        {currentUserResponse?.status === 'pending' ? (
          <button
            onClick={() => setShowRsvpForm(true)}
            className="w-full py-3 px-4 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
            aria-label="Respond to trip invitation"
          >
            Respond to Invitation
          </button>
        ) : (
          <div className="flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-2 rounded-full text-sm font-medium ${getStatusColor(currentUserResponse.status)}`}>
              {getStatusIcon(currentUserResponse.status)}
              <span className="capitalize">{currentUserResponse.status}</span>
            </div>
            {currentUserResponse.notes && (
              <p className="text-sm text-[rgb(15,23,42)]/70 flex-1">
                "{currentUserResponse.notes}"
              </p>
            )}
          </div>
        )}
      </div>

      {/* RSVP Form Modal */}
      {showRsvpForm && (
        <div className="fixed inset-0 bg-black/50 flex items-end sm:items-center justify-center z-50">
          <div className="bg-white w-full sm:w-96 sm:rounded-lg p-6 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">
              Respond to Invitation
            </h3>

            <div className="space-y-3 mb-4">
              {(['accepted', 'maybe', 'declined'] as const).map((status) => (
                <button
                  key={status}
                  onClick={() => setSelectedStatus(status)}
                  className={`w-full flex items-center gap-3 p-3 rounded-lg border-2 transition-colors min-h-[44px] ${
                    selectedStatus === status
                      ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5'
                      : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
                  }`}
                  aria-label={`Select ${status} response`}
                >
                  <div className={`flex items-center justify-center w-8 h-8 rounded-full ${getStatusColor(status)}`}>
                    {getStatusIcon(status)}
                  </div>
                  <span className="font-medium text-[rgb(15,23,42)] capitalize">
                    {status === 'accepted' ? 'Yes, I\'ll be there!' : 
                     status === 'maybe' ? 'Maybe, not sure yet' : 
                     'Sorry, can\'t make it'}
                  </span>
                </button>
              ))}
            </div>

            <div className="mb-6">
              <label htmlFor="rsvp-notes" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Add a note (optional)
              </label>
              <textarea
                id="rsvp-notes"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Any additional comments..."
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                rows={3}
                aria-label="Additional comments for RSVP"
              />
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setShowRsvpForm(false)}
                className="flex-1 py-3 px-4 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg font-medium hover:bg-[rgb(248,250,252)] transition-colors min-h-[44px]"
                aria-label="Cancel RSVP form"
              >
                Cancel
              </button>
              <button
                onClick={handleRsvpSubmit}
                className="flex-1 py-3 px-4 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors min-h-[44px]"
                aria-label="Submit RSVP response"
              >
                Submit
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Response Summary */}
      <div className="p-6">
        <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">
          Group Responses ({acceptedCount}/{totalCount})
        </h2>

        <div className="space-y-3">
          {localResponses.map((response) => (
            <div
              key={response.id}
              className="flex items-center gap-3 p-4 bg-[rgb(248,250,252)] rounded-lg"
            >
              <div className="w-10 h-10 bg-[rgb(34,139,34)] text-white rounded-full flex items-center justify-center font-medium text-sm">
                {response.userAvatar || response.userName.split(' ').map(n => n[0]).join('')}
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-medium text-[rgb(15,23,42)]">
                    {response.userName}
                  </span>
                  <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(response.status)}`}>
                    {getStatusIcon(response.status)}
                    <span className="capitalize">{response.status}</span>
                  </div>
                </div>

                {response.notes && (
                  <p className="text-sm text-[rgb(15,23,42)]/70 truncate">
                    "{response.notes}"
                  </p>
                )}

                {response.respondedAt && (
                  <p className="text-xs text-[rgb(15,23,42)]/50 mt-1">
                    Responded {response.respondedAt.toLocaleDateString()}
                  </p>
                )}
              </div>

              {response.status === 'pending' && (
                <input
                  type="checkbox"
                  checked={selectedUsers.includes(response.userId)}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setSelectedUsers([...selectedUsers, response.userId])
                    } else {
                      setSelectedUsers(selectedUsers.filter(id => id !== response.userId))
                    }
                  }}
                  className="w-5 h-5 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded focus:ring-[rgb(34,139,34)]"
                  aria-label={`Select ${response.userName} for reminder`}
                />
              )}
            </div>
          ))}
        </div>

        {/* Send Reminder */}
        {pendingUsers.length > 0 && (
          <div className="mt-6 p-4 bg-[rgb(245,158,11)]/10 border border-[rgb(245,158,11)]/20 rounded-lg">
            <div className="flex items-center justify-between mb-3">
              <div>
                <h3 className="font-medium text-[rgb(15,23,42)]">
                  Pending Responses ({pendingUsers.length})
                </h3>
                <p className="text-sm text-[rgb(15,23,42)]/70">
                  Send reminders to get responses
                </p>
              </div>
            </div>

            {selectedUsers.length > 0 && (
              <button
                onClick={handleSendReminder}
                className="w-full py-3 px-4 bg-[rgb(245,158,11)] text-white rounded-lg font-medium hover:bg-[rgb(245,158,11)]/90 transition-colors min-h-[44px]"
                aria-label={`Send reminder to ${selectedUsers.length} selected users`}
              >
                Send Reminder to {selectedUsers.length} {selectedUsers.length === 1 ? 'Person' : 'People'}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

