'use client'

import { useState, useEffect } from 'react'
import { User, Mail, Phone, MapPin, Calendar, Settings, Edit3, Save, X } from 'lucide-react'

interface UserProfile {
  id: string
  email: string
  firstName: string
  lastName: string
  phone?: string
  location?: string
  bio?: string
  emergencyContact?: {
    name: string
    phone: string
    relationship: string
  }
  preferences: {
    notifications: boolean
    emailUpdates: boolean
    publicProfile: boolean
  }
  joinedAt: string
  lastActive: string
}

interface UserProfileModelProps {
  userId?: string
  onUpdate?: (profile: UserProfile) => void
  onDelete?: (userId: string) => void
  readonly?: boolean
}

export function UserProfileModel({
  userId = 'user-123',
  onUpdate = () => console.log('Profile updated'),
  onDelete = () => console.log('Profile deleted'),
  readonly = false
}: UserProfileModelProps = {}) {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE)
  const [isEditing, setIsEditing] = useState(false)
  const [editForm, setEditForm] = useState<Partial<UserProfile>>({})
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    loadProfile()
  }, [userId])

  const loadProfile = async () => {
    setLoading(true)
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500))
      setProfile(DEFAULT_PROFILE)
      setError(null)
    } catch (err) {
      setError('Failed to load profile')
    } finally {
      setLoading(false)
    }
  }

  const handleEdit = () => {
    setIsEditing(true)
    setEditForm(profile)
  }

  const handleSave = async () => {
    if (!editForm.firstName?.trim() || !editForm.lastName?.trim()) {
      setError('First name and last name are required')
      return
    }

    setLoading(true)
    try {
      const updatedProfile = { ...profile, ...editForm }
      await new Promise(resolve => setTimeout(resolve, 500))
      setProfile(updatedProfile)
      onUpdate(updatedProfile)
      setIsEditing(false)
      setError(null)
    } catch (err) {
      setError('Failed to update profile')
    } finally {
      setLoading(false)
    }
  }

  const handleCancel = () => {
    setIsEditing(false)
    setEditForm({})
    setError(null)
  }

  const updateEditForm = (field: string, value: any) => {
    setEditForm(prev => ({ ...prev, [field]: value }))
  }

  const updatePreference = (key: keyof UserProfile['preferences'], value: boolean) => {
    setEditForm(prev => ({
      ...prev,
      preferences: {
        ...profile.preferences,
        ...prev.preferences,
        [key]: value
      }
    }))
  }

  if (loading && !profile.id) {
    return (
      <div className="w-full max-w-2xl mx-auto p-4">
        <div className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] p-6">
          <div className="animate-pulse space-y-4">
            <div className="h-20 w-20 bg-[rgb(241,245,249)] rounded-full mx-auto"></div>
            <div className="h-4 bg-[rgb(241,245,249)] rounded w-3/4 mx-auto"></div>
            <div className="h-4 bg-[rgb(241,245,249)] rounded w-1/2 mx-auto"></div>
            <div className="space-y-2">
              <div className="h-4 bg-[rgb(241,245,249)] rounded"></div>
              <div className="h-4 bg-[rgb(241,245,249)] rounded w-5/6"></div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="w-full max-w-2xl mx-auto p-4 font-medium">
      <div className="bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] overflow-hidden">
        {/* Header */}
        <div className="bg-[rgb(34,139,34)] text-white p-6 relative">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center">
                <User className="w-8 h-8" />
              </div>
              <div>
                <h1 className="text-xl font-semibold">
                  {profile.firstName} {profile.lastName}
                </h1>
                <p className="text-white/80 text-sm">{profile.email}</p>
              </div>
            </div>
            {!readonly && (
              <div className="flex gap-2">
                {isEditing ? (
                  <>
                    <button
                      onClick={handleSave}
                      disabled={loading}
                      className="p-2 bg-white/20 rounded-lg hover:bg-white/30 transition-colors disabled:opacity-50"
                      aria-label="Save changes"
                    >
                      <Save className="w-5 h-5" />
                    </button>
                    <button
                      onClick={handleCancel}
                      className="p-2 bg-white/20 rounded-lg hover:bg-white/30 transition-colors"
                      aria-label="Cancel editing"
                    >
                      <X className="w-5 h-5" />
                    </button>
                  </>
                ) : (
                  <button
                    onClick={handleEdit}
                    className="p-2 bg-white/20 rounded-lg hover:bg-white/30 transition-colors"
                    aria-label="Edit profile"
                  >
                    <Edit3 className="w-5 h-5" />
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="p-4 bg-[rgb(220,38,38)]/10 border-l-4 border-[rgb(220,38,38)] text-[rgb(220,38,38)]">
            <p className="text-sm font-medium">{error}</p>
          </div>
        )}

        {/* Profile Content */}
        <div className="p-6 space-y-6">
          {/* Basic Information */}
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)] flex items-center gap-2">
              <User className="w-5 h-5" />
              Basic Information
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  First Name *
                </label>
                {isEditing ? (
                  <input
                    type="text"
                    value={editForm.firstName || ''}
                    onChange={(e) => updateEditForm('firstName', e.target.value)}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                    placeholder="Enter first name"
                  />
                ) : (
                  <p className="px-3 py-2 bg-[rgb(248,250,252)] rounded-lg text-[rgb(15,23,42)]">
                    {profile.firstName}
                  </p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Last Name *
                </label>
                {isEditing ? (
                  <input
                    type="text"
                    value={editForm.lastName || ''}
                    onChange={(e) => updateEditForm('lastName', e.target.value)}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                    placeholder="Enter last name"
                  />
                ) : (
                  <p className="px-3 py-2 bg-[rgb(248,250,252)] rounded-lg text-[rgb(15,23,42)]">
                    {profile.lastName}
                  </p>
                )}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1 flex items-center gap-2">
                <Phone className="w-4 h-4" />
                Phone Number
              </label>
              {isEditing ? (
                <input
                  type="tel"
                  value={editForm.phone || ''}
                  onChange={(e) => updateEditForm('phone', e.target.value)}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                  placeholder="Enter phone number"
                />
              ) : (
                <p className="px-3 py-2 bg-[rgb(248,250,252)] rounded-lg text-[rgb(15,23,42)]">
                  {profile.phone || 'Not provided'}
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1 flex items-center gap-2">
                <MapPin className="w-4 h-4" />
                Location
              </label>
              {isEditing ? (
                <input
                  type="text"
                  value={editForm.location || ''}
                  onChange={(e) => updateEditForm('location', e.target.value)}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                  placeholder="Enter your location"
                />
              ) : (
                <p className="px-3 py-2 bg-[rgb(248,250,252)] rounded-lg text-[rgb(15,23,42)]">
                  {profile.location || 'Not provided'}
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                Bio
              </label>
              {isEditing ? (
                <textarea
                  value={editForm.bio || ''}
                  onChange={(e) => updateEditForm('bio', e.target.value)}
                  rows={3}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                  placeholder="Tell us about yourself..."
                />
              ) : (
                <p className="px-3 py-2 bg-[rgb(248,250,252)] rounded-lg text-[rgb(15,23,42)] min-h-[80px]">
                  {profile.bio || 'No bio provided'}
                </p>
              )}
            </div>
          </div>

          {/* Emergency Contact */}
          <div className="space-y-4">
