                  onChange={(e) => updatePreference('notifications', e.target.checked)}
                  disabled={!isEditing}
                  className="w-5 h-5 text-[rgb(34,139,34)] rounded focus:ring-2 focus:ring-[rgb(34,139,34)] disabled:opacity-50"
                />
