'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, Users, MoreVertical, Reply, Trash2, Edit3 } from 'lucide-react'

interface GroupChatMessage {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  content: string
  timestamp: Date
  replyTo?: string
  edited?: boolean
  type: 'text' | 'system'
}

interface GroupChatParticipant {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  lastSeen?: Date
}

interface GroupChatProps {
  tripId?: string
  participants?: GroupChatParticipant[]
  messages?: GroupChatMessage[]
  currentUserId?: string
  onSendMessage?: (content: string, replyTo?: string) => void
  onEditMessage?: (messageId: string, content: string) => void
  onDeleteMessage?: (messageId: string) => void
}

export function GroupChatModel({
  tripId = 'trip-1',
  participants = DEFAULT_PARTICIPANTS,
  messages = DEFAULT_MESSAGES,
  currentUserId = 'user-1',
  onSendMessage = (content: string, replyTo?: string) => console.log('Send message:', content, replyTo),
  onEditMessage = (messageId: string, content: string) => console.log('Edit message:', messageId, content),
  onDeleteMessage = (messageId: string) => console.log('Delete message:', messageId)
}: GroupChatProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [replyingTo, setReplyingTo] = useState<string | null>(null)
  const [editingMessage, setEditingMessage] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')
  const [showParticipants, setShowParticipants] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    onSendMessage(newMessage, replyingTo || undefined)
    setNewMessage('')
    setReplyingTo(null)
    inputRef.current?.focus()
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleReply = (messageId: string) => {
    setReplyingTo(messageId)
    inputRef.current?.focus()
  }

  const handleEdit = (messageId: string, content: string) => {
    setEditingMessage(messageId)
    setEditContent(content)
  }

  const handleSaveEdit = () => {
    if (!editContent.trim() || !editingMessage) return

    onEditMessage(editingMessage, editContent)
    setEditingMessage(null)
    setEditContent('')
  }

  const handleCancelEdit = () => {
    setEditingMessage(null)
    setEditContent('')
  }

  const getReplyMessage = (replyId: string) => {
    return messages.find(msg => msg.id === replyId)
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const groupMessagesByDate = (messages: GroupChatMessage[]) => {
    const groups: { [key: string]: GroupChatMessage[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return groups
  }

  const messageGroups = groupMessagesByDate(messages)

  return (
    <div className="flex flex-col h-screen bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center">
              <Users className="w-5 h-5 text-[rgb(255,255,255)]" />
            </div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-[rgb(34,139,34)] rounded-full border-2 border-[rgb(255,255,255)]" />
          </div>
          <div>
            <h1 className="font-semibold text-[rgb(15,23,42)] text-lg">Trip Chat</h1>
            <p className="text-sm text-gray-600">{participants.length} members</p>
          </div>
        </div>

        <button
          onClick={() => setShowParticipants(!showParticipants)}
          className="p-2 hover:bg-[rgb(241,245,249)] rounded-lg transition-colors"
          aria-label="View participants"
        >
          <MoreVertical className="w-5 h-5 text-gray-600" />
        </button>
      </div>

      {/* Participants Panel */}
      {showParticipants && (
        <div className="p-4 bg-[rgb(248,250,252)] border-b border-[rgb(226,232,240)]">
          <h3 className="font-medium text-[rgb(15,23,42)] mb-3">Participants</h3>
          <div className="space-y-2">
            {participants.map(participant => (
              <div key={participant.id} className="flex items-center gap-3">
                <div className="relative">
                  <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center">
                    <span className="text-xs font-medium text-[rgb(255,255,255)]">
                      {participant.name.charAt(0).toUpperCase()}
                    </span>
                  </div>
                  {participant.isOnline && (
                    <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-[rgb(34,139,34)] rounded-full border border-[rgb(255,255,255)]" />
                  )}
                </div>
                <div className="flex-1">
                  <p className="text-sm font-medium text-[rgb(15,23,42)]">{participant.name}</p>
                  <p className="text-xs text-gray-500">
                    {participant.isOnline ? 'Online' : 'Offline'}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {Object.entries(messageGroups).map(([dateKey, dayMessages]) => (
          <div key={dateKey}>
            {/* Date Separator */}
            <div className="flex items-center justify-center my-4">
              <div className="px-3 py-1 bg-[rgb(241,245,249)] rounded-full">
                <span className="text-xs font-medium text-gray-600">
                  {formatDate(new Date(dateKey))}
                </span>
              </div>
            </div>

            {/* Messages for this date */}
            {dayMessages.map(message => {
              const isCurrentUser = message.userId === currentUserId
              const replyMessage = message.replyTo ? getReplyMessage(message.replyTo) : null
              const isEditing = editingMessage === message.id

              return (
                <div
                  key={message.id}
                  className={`flex ${isCurrentUser ? 'justify-end' : 'justify-start'} mb-3`}
                >
                  <div className={`max-w-[80%] ${isCurrentUser ? 'order-2' : 'order-1'}`}>
                    {/* Reply Context */}
                    {replyMessage && (
                      <div className="mb-1 px-3 py-2 bg-[rgb(241,245,249)] rounded-lg border-l-4 border-[rgb(34,139,34)]">
                        <p className="text-xs font-medium text-[rgb(34,139,34)]">
                          Replying to {replyMessage.userName}
                        </p>
                        <p className="text-xs text-gray-600 truncate">
                          {replyMessage.content}
                        </p>
                      </div>
                    )}

                    {/* Message Bubble */}
                    <div
                      className={`px-4 py-2 rounded-2xl ${
                        isCurrentUser
                          ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                          : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                      } shadow-sm`}
                    >
                      {!isCurrentUser && (
                        <p className="text-xs font-medium mb-1 opacity-80">
                          {message.userName}
                        </p>
                      )}

                      {isEditing ? (
                        <div className="space-y-2">
                          <textarea
                            value={editContent}
                            onChange={(e) => setEditContent(e.target.value)}
                            className="w-full p-2 text-sm bg-[rgb(255,255,255)] text-[rgb(15,23,42)] rounded border border-[rgb(226,232,240)] resize-none"
                            rows={2}
                            autoFocus
                          />
                          <div className="flex gap-2">
                            <button
                              onClick={handleSaveEdit}
                              className="px-3 py-1 text-xs bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded hover:bg-[rgb(34,139,34)]/90 transition-colors"
                            >
                              Save
                            </button>
                            <button
                              onClick={handleCancelEdit}
                              className="px-3 py-1 text-xs bg-[rgb(255, 255, 255)]0 text-[rgb(255,255,255)] rounded hover:bg-gray-600 transition-colors"
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      ) : (
                        <p className="text-sm leading-relaxed">{message.content}</p>
                      )}

                      {message.edited && !isEditing && (
                        <p className="text-xs opacity-60 mt-1">(edited)</p>
                      )}
                    </div>

                    {/* Message Actions */}
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-xs text-gray-500">
                        {formatTime(message.timestamp)}
                      </span>

                      {!isEditing && (
                        <div className="flex gap-1">
                          <button
                            onClick={() => handleReply(message.id)}
                            className="p-1 hover:bg-[rgb(241,245,249)] rounded transition-colors"
                            aria-label="Reply to message"
                          >
                            <Reply className="w-3 h-3 text-gray-500" />
                          </button>

                          {isCurrentUser && (
                            <>
                              <button
                                onClick={() => handleEdit(message.id, message.content)}
                                className="p-1 hover:bg-[rgb(241,245,249)] rounded transition-colors"
                                aria-label="Edit message"
                              >
                                <Edit3 className="w-3 h-3 text-gray-500" />
                              </button>
                              <button
                                onClick={() => onDeleteMessage(message.id)}
                                className="p-1 hover:bg-[rgb(241,245,249)] rounded transition-colors"
                                aria-label="Delete message"
                              >
                                <Trash2 className="w-3 h-3 text-gray-500" />
                              </button>
                            </>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Reply Context */}
      {replyingTo && (
        <div className="px-4 py-2 bg-[rgb(248,250,252)] border-t border-[rgb(226,232,240)]">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              <p className="text-xs font-medium text-[rgb(34,139,34)]">
                Replying to {getReplyMessage(replyingTo)?.userName}
              </p>
              <p className="text-xs text-gray-600 truncate">
                {getReplyMessage(replyingTo)?.content}
              </p>
            </div>
            <button
              onClick={() => setReplyingTo(null)}
              className="p-1 hover:bg-[rgb(241,245,249)] rounded transition-colors"
              aria-label="Cancel reply"
            >
              <span className="text-sm text-gray-500">×</span>
            </button>
          </div>
        </div>
      )}

      {/* Message Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
        <div className="flex items-end gap-3">
          <div className="flex-1">
            <textarea
              ref={inputRef}
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-2xl resize-none focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent text-sm"
              rows={1}
              style={{ minHeight: '44px' }}
            />
          </div>
          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="w-11 h-11 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full flex items-center justify-center hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

