  currentUserId = 'user-1',
  members = DEFAULT_MEMBERS,
  onInviteMember = (email: string) => console.log('Invite member:', email),
  onRemoveMember = (memberId: string) => console.log('Remove member:', memberId),
  onUpdateRole = (memberId: string, role: string) => console.log('Update role:', memberId, role),
  onUpdateRSVP = (memberId: string, status: string) => console.log('Update RSVP:', memberId, status),
  onAssignTask = (memberId: string, taskId: string) => console.log('Assign task:', memberId, taskId)
}: TripMemberModelProps = {}) {
  const [activeTab, setActiveTab] = useState<'members' | 'invites' | 'rsvp'>('members')
  const [inviteEmail, setInviteEmail] = useState('')
  const [showInviteForm, setShowInviteForm] = useState(false)
  const [selectedMember, setSelectedMember] = useState<TripMember | null>(null)

  const currentMember = members.find(m => m.userId === currentUserId)
  const isOrganizer = currentMember?.role === 'organizer'

  const acceptedMembers = members.filter(m => m.status === 'accepted')
  const pendingInvites = members.filter(m => m.status === 'invited' || m.status === 'pending')
  const rsvpResponses = members.filter(m => m.status === 'accepted')

  const handleInvite = () => {
    if (inviteEmail.trim()) {
      onInviteMember(inviteEmail.trim())
      setInviteEmail('')
      setShowInviteForm(false)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'accepted':
      case 'yes':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'declined':
      case 'no':
        return 'bg-[rgb(220,38,38)] text-white'
      case 'maybe':
        return 'bg-[rgb(245,158,11)] text-white'
      case 'pending':
      case 'invited':
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
      default:
        return 'bg-[rgb(226,232,240)] text-[rgb(15,23,42)]'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted':
      case 'yes':
        return <CheckCircle className="w-4 h-4" />
      case 'declined':
      case 'no':
        return <XCircle className="w-4 h-4" />
      case 'maybe':
        return <Clock className="w-4 h-4" />
      default:
        return <Clock className="w-4 h-4" />
    }
  }

  return (
    <div className="w-full max-w-4xl mx-auto bg-white rounded-lg shadow-md border border-[rgb(226,232,240)]">
      {/* Header */}
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Users className="w-6 h-6 text-[rgb(34,139,34)]" />
            <div>
              <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Members</h2>
              <p className="text-sm text-gray-600">{acceptedMembers.length} members joined</p>
            </div>
          </div>
          {isOrganizer && (
            <button
              onClick={() => setShowInviteForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors"
              aria-label="Invite new member"
            >
              <UserPlus className="w-4 h-4" />
              <span className="hidden sm:inline">Invite</span>
            </button>
          )}
        </div>
      </div>

      {/* Invite Form Modal */}
      {showInviteForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold mb-4">Invite Member</h3>
            <div className="space-y-4">
              <div>
                <label htmlFor="invite-email" className="block text-sm font-medium mb-2">
                  Email Address
                </label>
                <input
                  id="invite-email"
                  type="email"
                  value={inviteEmail}
                  onChange={(e) => setInviteEmail(e.target.value)}
                  placeholder="Enter email address"
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                />
              </div>
              <div className="flex gap-3">
                <button
                  onClick={handleInvite}
                  className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors"
                >
                  Send Invite
                </button>
                <button
                  onClick={() => setShowInviteForm(false)}
                  className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="border-b border-[rgb(226,232,240)]">
        <nav className="flex">
          {[
            { id: 'members', label: 'Members', count: acceptedMembers.length },
            { id: 'invites', label: 'Invites', count: pendingInvites.length },
            { id: 'rsvp', label: 'RSVP', count: rsvpResponses.length }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex-1 px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'border-[rgb(34,139,34)] text-[rgb(34,139,34)]'
                  : 'border-transparent text-gray-600 hover:text-[rgb(15,23,42)]'
              }`}
            >
              {tab.label} ({tab.count})
            </button>
          ))}
        </nav>
      </div>

      {/* Content */}
      <div className="p-6">
        {activeTab === 'members' && (
          <div className="space-y-4">
            {acceptedMembers.map((member) => (
              <div
                key={member.id}
                className="flex items-center justify-between p-4 border border-[rgb(226,232,240)] rounded-lg hover:shadow-sm transition-shadow"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                    {member.profile.name.charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h4 className="font-medium text-[rgb(15,23,42)]">{member.profile.name}</h4>
                      {member.role === 'organizer' && (
                        <Crown className="w-4 h-4 text-[rgb(245,158,11)]" />
                      )}
                    </div>
                    <p className="text-sm text-gray-600">{member.profile.email}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(member.rsvp.status)}`}>
                        {getStatusIcon(member.rsvp.status)}
                        {member.rsvp.status.charAt(0).toUpperCase() + member.rsvp.status.slice(1)}
                      </span>
                      {member.tasks.length > 0 && (
                        <span className="text-xs text-gray-500">
                          {member.tasks.length} task{member.tasks.length !== 1 ? 's' : ''}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setSelectedMember(member)}
                    className="p-2 text-gray-600 hover:text-[rgb(34,139,34)] transition-colors"
                    aria-label="View member details"
                  >
                    <MessageCircle className="w-4 h-4" />
                  </button>
                  {isOrganizer && member.userId !== currentUserId && (
                    <button
                      onClick={() => onRemoveMember(member.id)}
                      className="p-2 text-gray-600 hover:text-[rgb(220,38,38)] transition-colors"
                      aria-label="Remove member"
                    >
                      <UserMinus className="w-4 h-4" />
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'invites' && (
          <div className="space-y-4">
            {pendingInvites.length === 0 ? (
              <div className="text-center py-8">
                <Users className="w-12 h-12 text-gray-400 mx-auto mb-3" />
                <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-2">No Pending Invites</h3>
                <p className="text-gray-600">All invitations have been responded to.</p>
              </div>
            ) : (
              pendingInvites.map((member) => (
                <div
                  key={member.id}
                  className="flex items-center justify-between p-4 border border-[rgb(226,232,240)] rounded-lg"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center text-gray-600 font-semibold">
                      {member.profile.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <h4 className="font-medium text-[rgb(15,23,42)]">{member.profile.name}</h4>
                      <p className="text-sm text-gray-600">{member.profile.email}</p>
                      <p className="text-xs text-gray-500">
                        Invited {new Date(member.invitedAt).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  <span className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(member.status)}`}>
                    {getStatusIcon(member.status)}
                    {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                  </span>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'rsvp' && (
          <div className="space-y-4">
            {rsvpResponses.map((member) => (
              <div
                key={member.id}
                className="p-4 border border-[rgb(226,232,240)] rounded-lg"
              >
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                      {member.profile.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <h4 className="font-medium text-[rgb(15,23,42)]">{member.profile.name}</h4>
                      <p className="text-sm text-gray-600">{member.profile.email}</p>
                    </div>
                  </div>
                  <span className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(member.rsvp.status)}`}>
                    {getStatusIcon(member.rsvp.status)}
                    {member.rsvp.status.charAt(0).toUpperCase() + member.rsvp.status.slice(1)}
                  </span>
                </div>
                {member.rsvp.dietaryRestrictions && member.rsvp.dietaryRestrictions.length > 0 && (
                  <div className="text-sm">
                    <span className="font-medium text-[rgb(15,23,42)]">Dietary Restrictions: </span>
                    <span className="text-gray-600">{member.rsvp.dietaryRestrictions.join(', ')}</span>
                  </div>
                )}
                {member.rsvp.emergencyContact && (
                  <div className="text-sm mt-2">
                    <span className="font-medium text-[rgb(15,23,42)]">Emergency Contact: </span>
                    <span className="text-gray-600">
                      {member.rsvp.emergencyContact.name} ({member.rsvp.emergencyContact.relationship}) - {member.rsvp.emergencyContact.phone}
                    </span>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

