code.api-route:
'use client'

import { useState, useEffect } from 'react'
import { MapPin, Star, Search, Plus, Trash2, Navigation, Mountain, Trees, Compass } from 'lucide-react'

interface Location {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  description: string
  difficulty: 'Easy' | 'Moderate' | 'Difficult' | 'Expert'
  terrain: string[]
  isFavorite: boolean
  dateAdded: string
  notes?: string
  elevation?: number
  accessibility: string
}

interface LocationSavingProps {
  onLocationSave?: (location: Location) => void
  onLocationDelete?: (locationId: string) => void
  initialLocations?: Location[]
}

export function LocationSaving({
  onLocationSave = () => console.log('Location saved'),
  onLocationDelete = () => console.log('Location deleted'),
  initialLocations = DEFAULT_LOCATIONS
}: LocationSavingProps = {}) {
  const [locations, setLocations] = useState<Location[]>(initialLocations)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null)
  const [isAddingLocation, setIsAddingLocation] = useState(false)
  const [newLocation, setNewLocation] = useState<Partial<Location>>({
    name: '',
    description: '',
    difficulty: 'Easy',
    terrain: [],
    notes: ''
  })
  const [searchResults, setSearchResults] = useState<Location[]>([])
  const [isSearching, setIsSearching] = useState(false)

  useEffect(() => {
    if (searchQuery.trim()) {
      setIsSearching(true)
      const timer = setTimeout(() => {
        const filtered = MOCK_SEARCH_RESULTS.filter(location =>
          location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
          location.description.toLowerCase().includes(searchQuery.toLowerCase())
        )
        setSearchResults(filtered)
        setIsSearching(false)
      }, 300)
      return () => clearTimeout(timer)
    } else {
      setSearchResults([])
    }
  }, [searchQuery])

  const handleSaveLocation = (location: Location) => {
    const savedLocation = {
      ...location,
      id: Date.now().toString(),
      isFavorite: false,
      dateAdded: new Date().toISOString()
    }
    setLocations(prev => [...prev, savedLocation])
    onLocationSave(savedLocation)
  }

  const handleDeleteLocation = (locationId: string) => {
    setLocations(prev => prev.filter(loc => loc.id !== locationId))
    onLocationDelete(locationId)
  }

  const toggleFavorite = (locationId: string) => {
    setLocations(prev => prev.map(loc =>
      loc.id === locationId ? { ...loc, isFavorite: !loc.isFavorite } : loc
    ))
  }

  const handleAddNewLocation = () => {
    if (newLocation.name && newLocation.description) {
      const location: Location = {
        id: Date.now().toString(),
        name: newLocation.name,
        coordinates: { lat: 40.7128, lng: -74.0060 }, // Default coordinates
        description: newLocation.description,
        difficulty: newLocation.difficulty as Location['difficulty'],
        terrain: newLocation.terrain || [],
        isFavorite: false,
        dateAdded: new Date().toISOString(),
        notes: newLocation.notes,
        accessibility: 'Vehicle accessible'
      }
      handleSaveLocation(location)
      setNewLocation({ name: '', description: '', difficulty: 'Easy', terrain: [], notes: '' })
      setIsAddingLocation(false)
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-green-100 text-green-800'
      case 'Moderate': return 'bg-yellow-100 text-yellow-800'
      case 'Difficult': return 'bg-orange-100 text-orange-800'
      case 'Expert': return 'bg-red-100 text-red-800'
      default: return 'bg-[rgb(241, 245, 249)] text-gray-800'
    }
  }

  const getTerrainIcon = (terrain: string) => {
    switch (terrain.toLowerCase()) {
      case 'mountain': return <Mountain className="w-4 h-4" />
      case 'forest': return <Trees className="w-4 h-4" />
      case 'desert': return <Compass className="w-4 h-4" />
      default: return <MapPin className="w-4 h-4" />
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      {/* Header */}
      <div className="sticky top-0 bg-[#ffffff] border-b border-[#e2e8f0] z-10">
        <div className="p-4">
          <h1 className="text-2xl font-bold text-[#0f172a] mb-4">Location Saving</h1>

          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[#64748b] w-5 h-5" />
            <input
              type="text"
              placeholder="Search locations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent text-base"
              aria-label="Search locations"
            />
          </div>
        </div>
      </div>

      <div className="p-4 space-y-6">
        {/* Add Location Button */}
        <button
          onClick={() => setIsAddingLocation(true)}
          className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium shadow-md hover:bg-[#1e7b1e] transition-colors"
          aria-label="Add new location"
        >
          <Plus className="w-5 h-5" />
          Add New Location
        </button>

        {/* Search Results */}
        {searchQuery && (
          <div className="space-y-3">
            <h2 className="text-lg font-semibold text-[#0f172a]">Search Results</h2>
            {isSearching ? (
              <div className="space-y-3">
                {[1, 2, 3].map(i => (
                  <div key={i} className="bg-[#f1f5f9] rounded-lg p-4 animate-pulse">
                    <div className="h-4 bg-[#e2e8f0] rounded w-3/4 mb-2"></div>
                    <div className="h-3 bg-[#e2e8f0] rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : searchResults.length > 0 ? (
              <div className="space-y-3">
                {searchResults.map(location => (
                  <LocationCard
                    key={location.id}
                    location={location}
                    onSave={() => handleSaveLocation(location)}
                    onSelect={() => setSelectedLocation(location)}
                    showSaveButton={true}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-[#64748b]">
                <MapPin className="w-12 h-12 mx-auto mb-3 text-[#cbd5e1]" />
                <p>No locations found</p>
                <p className="text-sm">Try a different search term</p>
              </div>
            )}
          </div>
        )}

        {/* Saved Locations */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold text-[#0f172a]">Saved Locations</h2>
            <span className="text-sm text-[#64748b]">{locations.length} locations</span>
          </div>

          {locations.length > 0 ? (
            <div className="space-y-3">
              {locations.map(location => (
                <LocationCard
                  key={location.id}
                  location={location}
                  onDelete={() => handleDeleteLocation(location.id)}
                  onToggleFavorite={() => toggleFavorite(location.id)}
                  onSelect={() => setSelectedLocation(location)}
                  showSaveButton={false}
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-12 text-[#64748b]">
              <MapPin className="w-16 h-16 mx-auto mb-4 text-[#cbd5e1]" />
              <p className="text-lg mb-2">No saved locations yet</p>
              <p className="text-sm">Start by searching and saving your favorite off-road spots</p>
            </div>
          )}
        </div>
      </div>

      {/* Add Location Modal */}
      {isAddingLocation && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-[#ffffff] rounded-t-2xl sm:rounded-2xl w-full max-w-md max-h-[90vh] overflow-y-auto">
            <div className="p-6 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-semibold text-[#0f172a]">Add New Location</h3>
                <button
                  onClick={() => setIsAddingLocation(false)}
                  className="p-2 hover:bg-[#f1f5f9] rounded-lg transition-colors"
                  aria-label="Close modal"
                >
                  ×
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Location Name</label>
                  <input
                    type="text"
                    value={newLocation.name || ''}
                    onChange={(e) => setNewLocation(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-3 py-2 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22]"
                    placeholder="Enter location name"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Description</label>
                  <textarea
                    value={newLocation.description || ''}
                    onChange={(e) => setNewLocation(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full px-3 py-2 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] h-20 resize-none"
                    placeholder="Describe the location"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Difficulty</label>
                  <select
                    value={newLocation.difficulty || 'Easy'}
                    onChange={(e) => setNewLocation(prev => ({ ...prev, difficulty: e.target.value as Location['difficulty'] }))}
                    className="w-full px-3 py-2 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22]"
                  >
                    <option value="Easy">Easy</option>
                    <option value="Moderate">Moderate</option>
                    <option value="Difficult">Difficult</option>
                    <option value="Expert">Expert</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Notes (Optional)</label>
                  <textarea
                    value={newLocation.notes || ''}
                    onChange={(e) => setNewLocation(prev => ({ ...prev, notes: e.target.value }))}
                    className="w-full px-3 py-2 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] h-16 resize-none"
                    placeholder="Additional notes or tips"
                  />
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => setIsAddingLocation(false)}
                  className="flex-1 py-3 px-4 border border-[#e2e8f0] text-[#64748b] rounded-lg font-medium hover:bg-[#f8fafc] transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAddNewLocation}
                  disabled={!newLocation.name || !newLocation.description}
                  className="flex-1 py-3 px-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#1e7b1e] transition-colors"
                >
                  Save Location
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Location Detail Modal */}
      {selectedLocation && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-[#ffffff] rounded-t-2xl sm:rounded-2xl w-full max-w-md max-h-[90vh] overflow-y-auto">
            <LocationDetail
              location={selectedLocation}
              onClose={() => setSelectedLocation(null)}
            />
          </div>
        </div>
      )}
    </div>
  )
}

