          >
            Save
          </button>
        )}
      </div>
    </div>
  )
}

interface LocationDetailProps {
  location: Location
  onClose: () => void
}

function LocationDetail({ location, onClose }: LocationDetailProps) {
  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-semibold text-[#0f172a]">{location.name}</h2>
        <button
          onClick={onClose}
          className="p-2 hover:bg-[#f1f5f9] rounded-lg transition-colors"
          aria-label="Close details"
        >
          ×
        </button>
      </div>

      <div className="space-y-4">
        <div>
          <h3 className="font-medium text-[#0f172a] mb-2">Description</h3>
          <p className="text-[#64748b]">{location.description}</p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <h3 className="font-medium text-[#0f172a] mb-2">Difficulty</h3>
            <span className={`px-2 py-1 text-sm font-medium rounded-full ${getDifficultyColor(location.difficulty)}`}>
              {location.difficulty}
            </span>
          </div>
          <div>
            <h3 className="font-medium text-[#0f172a] mb-2">Accessibility</h3>
            <p className="text-sm text-[#64748b]">{location.accessibility}</p>
          </div>
        </div>

        {location.terrain.length > 0 && (
          <div>
            <h3 className="font-medium text-[#0f172a] mb-2">Terrain</h3>
            <div className="flex flex-wrap gap-2">
              {location.terrain.map((terrain, index) => (
                <div key={index} className="flex items-center gap-1 px-2 py-1 bg-[#f1f5f9] rounded-lg text-sm text-[#64748b]">
                  {getTerrainIcon(terrain)}
                  <span>{terrain}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <div>
          <h3 className="font-medium text-[#0f172a] mb-2">Coordinates</h3>
          <p className="text-sm text-[#64748b] font-mono">
            {location.coordinates.lat.toFixed(6)}, {location.coordinates.lng.toFixed(6)}
          </p>
        </div>

        {location.notes && (
          <div>
            <h3 className="font-medium text-[#0f172a] mb-2">Notes</h3>
            <p className="text-[#64748b]">{location.notes}</p>
          </div>
