        </div>
      </div>

      <button
        onClick={onClose}
        className="w-full mt-6 py-3 px-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium hover:bg-[#1e7b1e] transition-colors"
      >
        Close
      </button>
    </div>
  )
}

const getDifficultyColor = (difficulty: string) => {
  switch (difficulty) {
    case 'Easy': return 'bg-green-100 text-green-800'
