'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, MapPin, AlertCircle, CheckCircle, RefreshCw } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  location?: string
  description?: string
  status: 'confirmed' | 'tentative' | 'cancelled'
}

interface CalendarAvailability {
  date: string
  available: boolean
  conflicts: CalendarEvent[]
}

interface GoogleCalendarProps {
  tripTitle?: string
  proposedDates?: Date[]
  groupMembers?: string[]
  onDateSelected?: (date: Date) => void
  onInvitesSent?: (invites: string[]) => void
}

export function GoogleCalendar({
  tripTitle = "Off-Road Adventure",
  proposedDates = [
    new Date(2024, 2, 15),
    new Date(2024, 2, 22),
    new Date(2024, 2, 29)
  ],
  groupMembers = [
    "john@example.com",
    "sarah@example.com", 
    "mike@example.com",
    "lisa@example.com"
  ],
  onDateSelected = () => {},
  onInvitesSent = () => {}
}: GoogleCalendarProps = {}) {
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [availability, setAvailability] = useState<CalendarAvailability[]>([])
  const [selectedDate, setSelectedDate] = useState<Date | null>(null)
  const [invitesSent, setInvitesSent] = useState(false)

  // Mock calendar data
  const mockEvents: CalendarEvent[] = [
    {
      id: '1',
      title: 'Team Meeting',
      start: new Date(2024, 2, 15, 9, 0),
      end: new Date(2024, 2, 15, 10, 0),
      attendees: ['john@example.com'],
      status: 'confirmed'
    },
    {
      id: '2',
      title: 'Family Dinner',
      start: new Date(2024, 2, 22, 18, 0),
      end: new Date(2024, 2, 22, 20, 0),
      attendees: ['sarah@example.com'],
      status: 'confirmed'
    }
  ]

  useEffect(() => {
    if (isConnected) {
      checkAvailability()
    }
  }, [isConnected, proposedDates])

  const connectToGoogle = async () => {
    setIsLoading(true)
    // Simulate Google OAuth flow
    setTimeout(() => {
      setIsConnected(true)
      setIsLoading(false)
    }, 2000)
  }

  const checkAvailability = () => {
    const availabilityData = proposedDates.map(date => {
      const dateStr = date.toISOString().split('T')[0]
      const conflicts = mockEvents.filter(event => 
        event.start.toDateString() === date.toDateString()
      )

      return {
        date: dateStr,
        available: conflicts.length === 0,
        conflicts
      }
    })

    setAvailability(availabilityData)
  }

  const selectDate = (date: Date) => {
    setSelectedDate(date)
    onDateSelected(date)
  }

  const sendInvites = async () => {
    if (!selectedDate) return

    setIsLoading(true)
    // Simulate sending calendar invites
    setTimeout(() => {
      setInvitesSent(true)
      setIsLoading(false)
      onInvitesSent(groupMembers)
    }, 1500)
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  const getAvailabilityForDate = (date: Date) => {
    const dateStr = date.toISOString().split('T')[0]
    return availability.find(a => a.date === dateStr)
  }

  if (!isConnected) {
    return (
      <div className="p-6 bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] max-w-md mx-auto">
        <div className="text-center">
          <Calendar className="w-16 h-16 text-[rgb(34,139,34)] mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)] mb-2">
            Connect Google Calendar
          </h2>
          <p className="text-[rgb(100,116,139)] mb-6 text-sm">
            Check group availability and send calendar invites for your off-road trip
          </p>

          <button
            onClick={connectToGoogle}
            disabled={isLoading}
            className="w-full px-4 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(22,101,22)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            aria-label="Connect to Google Calendar"
          >
            {isLoading ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                Connecting...
              </>
            ) : (
              <>
                <Calendar className="w-4 h-4" />
                Connect Google Calendar
              </>
            )}
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 bg-white rounded-lg shadow-md border border-[rgb(226,232,240)] max-w-2xl mx-auto">
      <div className="flex items-center gap-3 mb-6">
        <Calendar className="w-6 h-6 text-[rgb(34,139,34)]" />
        <div>
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">
            Schedule Trip: {tripTitle}
          </h2>
          <p className="text-sm text-[rgb(100,116,139)]">
            Check availability and send invites
          </p>
        </div>
        <div className="ml-auto">
          <div className="flex items-center gap-2 px-3 py-1 bg-[rgb(34,139,34)] bg-opacity-10 rounded-full">
            <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
            <span className="text-xs font-medium text-[rgb(34,139,34)]">Connected</span>
          </div>
        </div>
      </div>

      {/* Proposed Dates */}
      <div className="mb-6">
        <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-4">
          Proposed Dates
        </h3>
        <div className="space-y-3">
          {proposedDates.map((date, index) => {
            const dateAvailability = getAvailabilityForDate(date)
            const isSelected = selectedDate?.toDateString() === date.toDateString()

            return (
              <div
                key={index}
                className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  isSelected 
                    ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)] bg-opacity-5' 
                    : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)] hover:border-opacity-50'
                }`}
                onClick={() => selectDate(date)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    selectDate(date)
                  }
                }}
                aria-label={`Select ${formatDate(date)} for trip`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Clock className="w-5 h-5 text-[rgb(100,116,139)]" />
                    <div>
                      <div className="font-medium text-[rgb(15,23,42)]">
                        {formatDate(date)}
                      </div>
                      {dateAvailability && (
                        <div className="text-sm text-[rgb(100,116,139)]">
                          {dateAvailability.available ? (
                            <span className="text-[rgb(34,139,34)]">All members available</span>
                          ) : (
                            <span className="text-[rgb(245,158,11)]">
                              {dateAvailability.conflicts.length} conflict(s)
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                  </div>

                  {dateAvailability && (
                    <div className="flex items-center">
                      {dateAvailability.available ? (
                        <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
                      ) : (
                        <AlertCircle className="w-5 h-5 text-[rgb(245,158,11)]" />
                      )}
                    </div>
                  )}
                </div>

                {/* Show conflicts if any */}
                {dateAvailability && !dateAvailability.available && (
                  <div className="mt-3 pt-3 border-t border-[rgb(226,232,240)]">
                    <div className="text-xs text-[rgb(100,116,139)] mb-2">Conflicts:</div>
                    {dateAvailability.conflicts.map(conflict => (
                      <div key={conflict.id} className="text-xs text-[rgb(220,38,38)] mb-1">
                        • {conflict.title} ({conflict.start.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})})
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </div>

      {/* Group Members */}
      <div className="mb-6">
        <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-3">
          Group Members ({groupMembers.length})
        </h3>
        <div className="flex items-center gap-2 mb-3">
          <Users className="w-4 h-4 text-[rgb(100,116,139)]" />
          <span className="text-sm text-[rgb(100,116,139)]">
            Calendar invites will be sent to:
          </span>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          {groupMembers.map((member, index) => (
            <div
              key={index}
              className="px-3 py-2 bg-[rgb(248,250,252)] rounded-md text-sm text-[rgb(15,23,42)]"
            >
              {member}
            </div>
          ))}
        </div>
      </div>

      {/* Send Invites */}
      <div className="pt-4 border-t border-[rgb(226,232,240)]">
        {invitesSent ? (
          <div className="flex items-center gap-3 p-4 bg-[rgb(34,139,34)] bg-opacity-10 rounded-lg">
            <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
            <div>
              <div className="font-medium text-[rgb(34,139,34)]">
                Invites Sent Successfully!
              </div>
              <div className="text-sm text-[rgb(34,139,34)] opacity-80">
                Calendar invites sent to {groupMembers.length} members for {selectedDate && formatDate(selectedDate)}
              </div>
            </div>
          </div>
        ) : (
          <button
            onClick={sendInvites}
            disabled={!selectedDate || isLoading}
            className="w-full px-4 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(22,101,22)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            aria-label="Send calendar invites to group members"
          >
            {isLoading ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                Sending Invites...
              </>
            ) : (
              <>
                <Calendar className="w-4 h-4" />
                Send Calendar Invites
                {selectedDate && ` for ${selectedDate.toLocaleDateString()}`}
              </>
            )}
          </button>
        )}

        {!selectedDate && (
          <p className="text-xs text-[rgb(100,116,139)] mt-2 text-center">
            Select a date above to send invites
          </p>
        )}
      </div>
    </div>
  )
}

export default function GoogleCalendarDemo() {
  return (
    <div className="min-h-screen bg-[rgb(248,250,252)] py-8 px-4">
      <GoogleCalendar />
    </div>
  )
}

