const DEFAULT_CAMPAIGNS: EmailCampaign[] = [
  {
    id: '1',
    templateId: '1',
    recipients: [
      { id: '1', name: 'John Smith', email: 'john@example.com', status: 'sent', sentAt: new Date() },
      { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', status: 'delivered' },
      { id: '3', name: 'Mike Wilson', email: 'mike@example.com', status: 'pending' }
    ],
    status: 'sent',
    sentAt: new Date(),
    tripId: 'trip1',
    tripName: 'Moab Desert Adventure'
  },
  {
    id: '2',
    templateId: '2',
    recipients: [
      { id: '4', name: 'Lisa Brown', email: 'lisa@example.com', status: 'scheduled' },
      { id: '5', name: 'Tom Davis', email: 'tom@example.com', status: 'scheduled' }
    ],
    status: 'scheduled',
    scheduledAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
    tripId: 'trip2',
    tripName: 'Rocky Mountain Trail'
  }
]

export function ResendService({
  onSendEmail = () => console.log('Email sent'),
  onScheduleEmail = () => console.log('Email scheduled'),
  campaigns = DEFAULT_CAMPAIGNS,
  templates = DEFAULT_TEMPLATES
}: ResendServiceProps = {}) {
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate | null>(null)
  const [recipients, setRecipients] = useState<string>('')
  const [subject, setSubject] = useState('')
  const [content, setContent] = useState('')
  const [scheduledDate, setScheduledDate] = useState('')
  const [scheduledTime, setScheduledTime] = useState('')
  const [activeTab, setActiveTab] = useState<'compose' | 'campaigns' | 'templates'>('compose')
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    if (selectedTemplate) {
      setSubject(selectedTemplate.subject)
      setContent(selectedTemplate.content)
    }
  }, [selectedTemplate])

  const handleSendNow = async () => {
    if (!subject || !content || !recipients) return

    setIsLoading(true)

    const recipientList = recipients.split(',').map((email, index) => ({
      id: `new-${index}`,
      name: email.trim().split('@')[0],
      email: email.trim(),
      status: 'pending' as const
    }))

    const newCampaign: EmailCampaign = {
      id: `campaign-${Date.now()}`,
      templateId: selectedTemplate?.id || 'custom',
      recipients: recipientList,
      status: 'sending',
      tripId: 'current-trip',
      tripName: 'Current Trip'
    }

    // Simulate sending delay
    setTimeout(() => {
      onSendEmail(newCampaign)
      setIsLoading(false)
      setSubject('')
      setContent('')
      setRecipients('')
      setSelectedTemplate(null)
    }, 2000)
  }

  const handleSchedule = () => {
    if (!subject || !content || !recipients || !scheduledDate || !scheduledTime) return

    const recipientList = recipients.split(',').map((email, index) => ({
      id: `scheduled-${index}`,
      name: email.trim().split('@')[0],
      email: email.trim(),
      status: 'scheduled' as const
    }))

    const scheduledAt = new Date(`${scheduledDate}T${scheduledTime}`)

    const newCampaign: EmailCampaign = {
      id: `campaign-${Date.now()}`,
      templateId: selectedTemplate?.id || 'custom',
      recipients: recipientList,
      status: 'scheduled',
      scheduledAt,
      tripId: 'current-trip',
      tripName: 'Current Trip'
    }

    onScheduleEmail(newCampaign, scheduledAt)
    setSubject('')
    setContent('')
    setRecipients('')
    setScheduledDate('')
    setScheduledTime('')
    setSelectedTemplate(null)
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
      case 'scheduled':
        return <Clock className="w-4 h-4 text-[rgb(245,158,11)]" />
      default:
        return <Clock className="w-4 h-4 text-[rgb(100,116,139)]" />
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'failed':
        return 'bg-[rgb(220,38,38)] text-white'
      case 'scheduled':
        return 'bg-[rgb(245,158,11)] text-white'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  return (
    <div className="w-full max-w-4xl mx-auto bg-white rounded-lg shadow-md border border-[rgb(226,232,240)]">
      {/* Header */}
      <div className="p-6 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center gap-3 mb-4">
          <div className="p-2 bg-[rgb(34,139,34)] rounded-lg">
            <Mail className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Email Service</h1>
            <p className="text-sm text-[rgb(100,116,139)]">Send trip invitations and updates</p>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex gap-1 bg-[rgb(248,250,252)] p-1 rounded-lg">
          {[
            { id: 'compose', label: 'Compose', icon: Send },
            { id: 'campaigns', label: 'Campaigns', icon: Users },
            { id: 'templates', label: 'Templates', icon: Mail }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === id
                  ? 'bg-white text-[rgb(34,139,34)] shadow-sm'
                  : 'text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
              }`}
            >
              <Icon className="w-4 h-4" />
              {label}
            </button>
          ))}
        </div>
      </div>

      <div className="p-6">
        {/* Compose Tab */}
        {activeTab === 'compose' && (
          <div className="space-y-6">
            {/* Template Selection */}
            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Email Template
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {templates.map((template) => (
                  <button
                    key={template.id}
                    onClick={() => setSelectedTemplate(template)}
                    className={`p-3 rounded-lg border text-left transition-colors ${
                      selectedTemplate?.id === template.id
                        ? 'border-[rgb(34,139,34)] bg-[rgb(248,250,252)]'
                        : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                    }`}
                  >
                    <div className="font-medium text-sm text-[rgb(15,23,42)]">{template.name}</div>
                    <div className="text-xs text-[rgb(100,116,139)] mt-1 capitalize">{template.type}</div>
                  </button>
                ))}
              </div>
            </div>

            {/* Recipients */}
            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Recipients
              </label>
              <textarea
                value={recipients}
                onChange={(e) => setRecipients(e.target.value)}
                placeholder="Enter email addresses separated by commas"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                rows={3}
              />
            </div>

            {/* Subject */}
            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Subject
              </label>
              <input
                type="text"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="Email subject"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
              />
            </div>

            {/* Content */}
            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Message
              </label>
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Email content"
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
                rows={6}
              />
            </div>

            {/* Schedule Options */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Schedule Date (Optional)
                </label>
                <input
                  type="date"
                  value={scheduledDate}
                  onChange={(e) => setScheduledDate(e.target.value)}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Schedule Time (Optional)
                </label>
                <input
                  type="time"
                  value={scheduledTime}
                  onChange={(e) => setScheduledTime(e.target.value)}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
                />
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-3">
              <button
                onClick={handleSendNow}
                disabled={!subject || !content || !recipients || isLoading}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(29,120,29)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isLoading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    Sending...
                  </>
                ) : (
                  <>
                    <Send className="w-4 h-4" />
                    Send Now
                  </>
                )}
              </button>
              {scheduledDate && scheduledTime && (
                <button
                  onClick={handleSchedule}
                  disabled={!subject || !content || !recipients}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-[rgb(245,158,11)] text-white rounded-lg font-medium hover:bg-[rgb(217,138,8)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  <Calendar className="w-4 h-4" />
                  Schedule
                </button>
              )}
            </div>
          </div>
        )}

        {/* Campaigns Tab */}
        {activeTab === 'campaigns' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Email Campaigns</h2>
              <div className="text-sm text-[rgb(100,116,139)]">
                {campaigns.length} campaigns
              </div>
            </div>

            <div className="space-y-3">
              {campaigns.map((campaign) => (
                <div key={campaign.id} className="p-4 border border-[rgb(226,232,240)] rounded-lg">
                  <div className="flex items-start justify-between mb-3">
                    <div>
                      <h3 className="font-medium text-[rgb(15,23,42)]">{campaign.tripName}</h3>
                      <p className="text-sm text-[rgb(100,116,139)]">
                        {campaign.recipients.length} recipients
                      </p>
                    </div>
                    <span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(campaign.status)}`}>
                      {campaign.status}
                    </span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-sm">
                    <div>
                      <span className="text-[rgb(100,116,139)]">Sent:</span>
                      <span className="ml-1 text-[rgb(15,23,42)]">
                        {campaign.sentAt ? campaign.sentAt.toLocaleDateString() : 'Not sent'}
                      </span>
                    </div>
                    <div>
                      <span className="text-[rgb(100,116,139)]">Scheduled:</span>
                      <span className="ml-1 text-[rgb(15,23,42)]">
                        {campaign.scheduledAt ? campaign.scheduledAt.toLocaleDateString() : 'Immediate'}
                      </span>
                    </div>
                    <div>
                      <span className="text-[rgb(100,116,139)]">Template:</span>
                      <span className="ml-1 text-[rgb(15,23,42)]">
                        {templates.find(t => t.id === campaign.templateId)?.name || 'Custom'}
                      </span>
                    </div>
                  </div>

                  {/* Recipients Status */}
                  <div className="mt-3 pt-3 border-t border-[rgb(226,232,240)]">
                    <div className="flex flex-wrap gap-2">
                      {campaign.recipients.slice(0, 5).map((recipient) => (
                        <div key={recipient.id} className="flex items-center gap-1 text-xs">
                          {getStatusIcon(recipient.status)}
                          <span className="text-[rgb(100,116,139)]">{recipient.name}</span>
                        </div>
                      ))}
                      {campaign.recipients.length > 5 && (
                        <span className="text-xs text-[rgb(100,116,139)]">
                          +{campaign.recipients.length - 5} more
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Templates Tab */}
        {activeTab === 'templates' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Email Templates</h2>
              <div className="text-sm text-[rgb(100,116,139)]">
                {templates.length} templates
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {templates.map((template) => (
                <div key={template.id} className="p-4 border border-[rgb(226,232,240)] rounded-lg">
                  <div className="flex items-start justify-between mb-3">
                    <div>
                      <h3 className="font-medium text-[rgb(15,23,42)]">{template.name}</h3>
                      <span className="inline-block px-2 py-1 text-xs font-medium rounded-full bg-[rgb(248,250,252)] text-[rgb(100,116,139)] capitalize mt-1">
                        {template.type}
                      </span>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div>
                      <span className="text-xs font-medium text-[rgb(100,116,139)]">Subject:</span>
                      <p className="text-sm text-[rgb(15,23,42)]">{template.subject}</p>
                    </div>
                    <div>
                      <span className="text-xs font-medium text-[rgb(100,116,139)]">Content:</span>
                      <p className="text-sm text-[rgb(15,23,42)] line-clamp-3">{template.content}</p>
                    </div>
                  </div>

                  <button
                    onClick={() => {
                      setSelectedTemplate(template)
                      setActiveTab('compose')
                    }}
                    className="w-full mt-3 px-3 py-2 bg-[rgb(248,250,252)] text-[rgb(34,139,34)] rounded-lg text-sm font-medium hover:bg-[rgb(241,245,249)] transition-colors"
                  >
                    Use Template
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default function ResendServiceDemo() {
  return (
    <div className="min-h-screen bg-[rgb(248,250,252)] p-4">
      <ResendService />
    </div>
  )
}

code.frontend:
'use client'

import { useState, useEffect } from 'react'
import { Code, Copy, Check, FileText, Zap, Shield, Smartphone } from 'lucide-react'

interface CodeExample {
  id: string
  title: string
  description: string
  code: string
  language: string
  category: 'component' | 'hook' | 'utility' | 'config'
}

interface TypeScriptGuideProps {
  examples?: CodeExample[]
  onCopyCode?: (code: string) => void
  showCategories?: boolean
}

export function TypeScriptGuide({
  examples = DEFAULT_EXAMPLES,
  onCopyCode = () => console.log('Code copied'),
  showCategories = true
}: TypeScriptGuideProps = {}) {
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [copiedId, setCopiedId] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState('')

  const categories = [
    { id: 'all', label: 'All Examples', icon: FileText },
    { id: 'component', label: 'Components', icon: Code },
    { id: 'hook', label: 'Hooks', icon: Zap },
    { id: 'utility', label: 'Utilities', icon: Shield },
    { id: 'config', label: 'Config', icon: Smartphone }
  ]

  const filteredExamples = examples.filter(example => {
    const matchesCategory = selectedCategory === 'all' || example.category === selectedCategory
    const matchesSearch = example.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         example.description.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesCategory && matchesSearch
  })

  const handleCopyCode = async (code: string, id: string) => {
    try {
      await navigator.clipboard.writeText(code)
      setCopiedId(id)
      onCopyCode(code)
      setTimeout(() => setCopiedId(null), 2000)
    } catch (error) {
      console.error('Failed to copy code:', error)
    }
  }

  const features = [
    {
      icon: Shield,
      title: 'Type Safety',
      description: 'Catch errors at compile time with strict TypeScript configuration'
    },
    {
      icon: Zap,
      title: 'Performance',
      description: 'Optimized code patterns for fast mobile experiences'
    },
    {
      icon: Smartphone,
      title: 'Mobile First',
      description: 'Touch-friendly interfaces designed for outdoor adventures'
    }
  ]

  return (
    <div className="min-h-screen" style={{ backgroundColor: 'rgb(255, 255, 255)', fontFamily: 'Inter, system-ui, sans-serif' }}>
      {/* Header */}
      <div className="sticky top-0 z-10 border-b" style={{ backgroundColor: 'rgb(255, 255, 255)', borderColor: 'rgb(226, 232, 240)' }}>
        <div className="px-4 py-4">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 rounded-lg" style={{ backgroundColor: 'rgb(34, 139, 34)' }}>
              <Code className="w-6 h-6" style={{ color: 'rgb(255, 255, 255)' }} />
            </div>
            <div>
              <h1 className="text-xl font-bold" style={{ color: 'rgb(15, 23, 42)' }}>
                TypeScript Guide
              </h1>
              <p className="text-sm" style={{ color: 'rgb(100, 116, 139)' }}>
                Production-ready patterns for off-road trip planning
              </p>
            </div>
          </div>

          {/* Search */}
          <div className="mb-4">
            <input
              type="text"
              placeholder="Search examples..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border focus:outline-none focus:ring-2 focus:ring-offset-2 text-base"
              style={{ 
                borderColor: 'rgb(226, 232, 240)',
                backgroundColor: 'rgb(255, 255, 255)',
                color: 'rgb(15, 23, 42)'
              }}
              aria-label="Search TypeScript examples"
            />
          </div>

          {/* Categories */}
          {showCategories && (
            <div className="flex gap-2 overflow-x-auto pb-2">
              {categories.map((category) => {
                const Icon = category.icon
                const isSelected = selectedCategory === category.id
                return (
                  <button
                    key={category.id}
                    onClick={() => setSelectedCategory(category.id)}
                    className="flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap transition-colors min-h-[44px]"
                    style={{
                      backgroundColor: isSelected ? 'rgb(34, 139, 34)' : 'rgb(248, 250, 252)',
                      color: isSelected ? 'rgb(255, 255, 255)' : 'rgb(15, 23, 42)'
                    }}
                    aria-label={`Filter by ${category.label}`}
                  >
                    <Icon className="w-4 h-4" />
                    <span className="text-sm font-medium">{category.label}</span>
                  </button>
                )
              })}
            </div>
          )}
        </div>
      </div>

      {/* Features Section */}
      <div className="px-4 py-6">
        <h2 className="text-lg font-bold mb-4" style={{ color: 'rgb(15, 23, 42)' }}>
          Why TypeScript for Adventure Planning?
        </h2>
        <div className="grid gap-4 mb-8">
          {features.map((feature, index) => {
            const Icon = feature.icon
            return (
              <div
                key={index}
                className="p-4 rounded-lg border"
                style={{ 
                  backgroundColor: 'rgb(248, 250, 252)',
                  borderColor: 'rgb(226, 232, 240)'
                }}
              >
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg" style={{ backgroundColor: 'rgb(245, 158, 11)' }}>
                    <Icon className="w-5 h-5" style={{ color: 'rgb(255, 255, 255)' }} />
                  </div>
                  <div className="flex-1">
                    <h3 className="font-semibold mb-1" style={{ color: 'rgb(15, 23, 42)' }}>
                      {feature.title}
                    </h3>
                    <p className="text-sm" style={{ color: 'rgb(100, 116, 139)' }}>
                      {feature.description}
                    </p>
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Examples */}
      <div className="px-4 pb-8">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold" style={{ color: 'rgb(15, 23, 42)' }}>
            Code Examples
          </h2>
          <span className="text-sm px-3 py-1 rounded-full" style={{ 
            backgroundColor: 'rgb(34, 139, 34)',
            color: 'rgb(255, 255, 255)'
          }}>
            {filteredExamples.length} examples
          </span>
        </div>

        {filteredExamples.length === 0 ? (
          <div className="text-center py-12">
            <Code className="w-12 h-12 mx-auto mb-4" style={{ color: 'rgb(156, 163, 175)' }} />
            <h3 className="font-semibold mb-2" style={{ color: 'rgb(15, 23, 42)' }}>
              No examples found
            </h3>
            <p className="text-sm" style={{ color: 'rgb(100, 116, 139)' }}>
              Try adjusting your search or category filter
            </p>
          </div>
        ) : (
          <div className="space-y-6">
            {filteredExamples.map((example) => (
              <div
                key={example.id}
                className="rounded-lg border shadow-md overflow-hidden"
                style={{ 
                  backgroundColor: 'rgb(255, 255, 255)',
                  borderColor: 'rgb(226, 232, 240)'
                }}
              >
                <div className="p-4 border-b" style={{ borderColor: 'rgb(226, 232, 240)' }}>
                  <div className="flex items-start justify-between gap-3 mb-2">
                    <div className="flex-1">
                      <h3 className="font-semibold" style={{ color: 'rgb(15, 23, 42)' }}>
                        {example.title}
                      </h3>
                      <p className="text-sm mt-1" style={{ color: 'rgb(100, 116, 139)' }}>
                        {example.description}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs px-2 py-1 rounded-full" style={{
                        backgroundColor: 'rgb(245, 158, 11)',
                        color: 'rgb(255, 255, 255)'
                      }}>
                        {example.language}
                      </span>
                      <button
                        onClick={() => handleCopyCode(example.code, example.id)}
                        className="p-2 rounded-lg transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center"
                        style={{ backgroundColor: 'rgb(248, 250, 252)' }}
                        aria-label="Copy code to clipboard"
                      >
                        {copiedId === example.id ? (
                          <Check className="w-4 h-4" style={{ color: 'rgb(34, 139, 34)' }} />
                        ) : (
                          <Copy className="w-4 h-4" style={{ color: 'rgb(100, 116, 139)' }} />
                        )}
                      </button>
                    </div>
                  </div>
                </div>

                <div className="p-4" style={{ backgroundColor: 'rgb(241, 245, 249)' }}>
                  <pre className="text-sm overflow-x-auto">
                    <code 
                      className="block whitespace-pre"
                      style={{ 
                        color: 'rgb(15, 23, 42)',
                        fontFamily: 'JetBrains Mono, monospace'
                      }}
                    >
                      {example.code}
                    </code>
                  </pre>
                </div>
              </div>
            ))}
