'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Mountain, Plus, X } from 'lucide-react'

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  tags: string[]
}

interface CreateTripFormProps {
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

const DIFFICULTY_OPTIONS = [
  { value: 'easy', label: 'Easy', color: 'bg-green-100 text-green-800' },
  { value: 'moderate', label: 'Moderate', color: 'bg-yellow-100 text-yellow-800' },
  { value: 'hard', label: 'Hard', color: 'bg-red-100 text-red-800' }
] as const

const POPULAR_TAGS = [
  'Camping', 'Rock Crawling', 'Scenic Views', 'Photography', 
  'Beginner Friendly', 'Advanced', 'Multi-Day', 'Day Trip'
]

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {},
  isLoading = false
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    ...initialData
  })

  const [errors, setErrors] = useState<Partial<Record<keyof TripFormData, string>>>({})
  const [customTag, setCustomTag] = useState('')

  const validateForm = (): boolean => {
    const newErrors: Partial<Record<keyof TripFormData, string>> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) > new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const updateField = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }))
    }
  }

  const addTag = (tag: string) => {
    if (tag && !formData.tags.includes(tag)) {
      updateField('tags', [...formData.tags, tag])
    }
  }

  const removeTag = (tagToRemove: string) => {
    updateField('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const addCustomTag = () => {
    if (customTag.trim()) {
      addTag(customTag.trim())
      setCustomTag('')
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-lg mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-[#228b22] rounded-lg">
              <Mountain className="w-6 h-6 text-[#ffffff]" />
            </div>
            <h1 className="text-2xl font-bold text-[#0f172a]">Create Trip</h1>
          </div>
          <p className="text-[#64748b] text-sm">Plan your next off-roading adventure</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Trip Name */}
          <div>
            <label htmlFor="name" className="block text-sm font-medium text-[#0f172a] mb-2">
              Trip Name *
            </label>
            <input
              id="name"
              type="text"
              value={formData.name}
              onChange={(e) => updateField('name', e.target.value)}
              placeholder="Enter trip name"
              className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                errors.name ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
              }`}
              aria-describedby={errors.name ? 'name-error' : undefined}
            />
            {errors.name && (
              <p id="name-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                {errors.name}
              </p>
            )}
          </div>

          {/* Location */}
          <div>
            <label htmlFor="location" className="block text-sm font-medium text-[#0f172a] mb-2">
              <MapPin className="w-4 h-4 inline mr-1" />
              Location *
            </label>
            <input
              id="location"
              type="text"
              value={formData.location}
              onChange={(e) => updateField('location', e.target.value)}
              placeholder="Enter trail or area name"
              className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                errors.location ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
              }`}
              aria-describedby={errors.location ? 'location-error' : undefined}
            />
            {errors.location && (
              <p id="location-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                {errors.location}
              </p>
            )}
          </div>

          {/* Dates */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="startDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                <Calendar className="w-4 h-4 inline mr-1" />
                Start Date *
              </label>
              <input
                id="startDate"
                type="date"
                value={formData.startDate}
                onChange={(e) => updateField('startDate', e.target.value)}
                min={new Date().toISOString().split('T')[0]}
                className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                  errors.startDate ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                }`}
                aria-describedby={errors.startDate ? 'startDate-error' : undefined}
              />
              {errors.startDate && (
                <p id="startDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.startDate}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="endDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                End Date *
              </label>
              <input
                id="endDate"
                type="date"
                value={formData.endDate}
                onChange={(e) => updateField('endDate', e.target.value)}
                min={formData.startDate || new Date().toISOString().split('T')[0]}
                className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                  errors.endDate ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                }`}
                aria-describedby={errors.endDate ? 'endDate-error' : undefined}
              />
              {errors.endDate && (
                <p id="endDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.endDate}
                </p>
              )}
            </div>
          </div>

          {/* Description */}
          <div>
            <label htmlFor="description" className="block text-sm font-medium text-[#0f172a] mb-2">
              Description
            </label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => updateField('description', e.target.value)}
              placeholder="Describe the trip, terrain, requirements..."
              rows={4}
              className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors resize-none"
            />
          </div>

          {/* Max Participants */}
          <div>
            <label htmlFor="maxParticipants" className="block text-sm font-medium text-[#0f172a] mb-2">
              <Users className="w-4 h-4 inline mr-1" />
              Max Participants
            </label>
            <input
              id="maxParticipants"
              type="number"
              value={formData.maxParticipants}
              onChange={(e) => updateField('maxParticipants', parseInt(e.target.value) || 0)}
              min="1"
              max="50"
              className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors ${
                errors.maxParticipants ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
              }`}
              aria-describedby={errors.maxParticipants ? 'maxParticipants-error' : undefined}
            />
            {errors.maxParticipants && (
              <p id="maxParticipants-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                {errors.maxParticipants}
              </p>
            )}
          </div>

          {/* Difficulty */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-3">
              Difficulty Level
            </label>
            <div className="grid grid-cols-3 gap-2">
              {DIFFICULTY_OPTIONS.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => updateField('difficulty', option.value)}
                  className={`px-4 py-3 rounded-lg border-2 transition-all text-sm font-medium ${
                    formData.difficulty === option.value
                      ? 'border-[#228b22] bg-[#228b22] text-[#ffffff]'
                      : 'border-[#e2e8f0] bg-[#ffffff] text-[#0f172a] hover:border-[#228b22]'
                  }`}
                  aria-pressed={formData.difficulty === option.value}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          {/* Tags */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-3">
              Tags
            </label>

            {/* Selected Tags */}
            {formData.tags.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-3">
                {formData.tags.map((tag) => (
                  <span
                    key={tag}
                    className="inline-flex items-center gap-1 px-3 py-1 bg-[#228b22] text-[#ffffff] text-sm rounded-full"
                  >
                    {tag}
                    <button
                      type="button"
                      onClick={() => removeTag(tag)}
                      className="hover:bg-white hover:bg-opacity-20 rounded-full p-0.5 transition-colors"
                      aria-label={`Remove ${tag} tag`}
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}
              </div>
            )}

            {/* Popular Tags */}
            <div className="grid grid-cols-2 gap-2 mb-3">
              {POPULAR_TAGS.map((tag) => (
                <button
                  key={tag}
                  type="button"
                  onClick={() => addTag(tag)}
                  disabled={formData.tags.includes(tag)}
                  className={`px-3 py-2 text-sm rounded-lg border transition-colors ${
                    formData.tags.includes(tag)
                      ? 'border-[#e2e8f0] bg-[#f1f5f9] text-[#64748b] cursor-not-allowed'
                      : 'border-[#e2e8f0] bg-[#ffffff] text-[#0f172a] hover:border-[#228b22] hover:bg-[#f8fafc]'
                  }`}
                >
                  {tag}
                </button>
              ))}
            </div>

            {/* Custom Tag Input */}
            <div className="flex gap-2">
              <input
                type="text"
                value={customTag}
                onChange={(e) => setCustomTag(e.target.value)}
                placeholder="Add custom tag"
                className="flex-1 px-3 py-2 border border-[#e2e8f0] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-colors text-sm"
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addCustomTag())}
              />
              <button
                type="button"
                onClick={addCustomTag}
                disabled={!customTag.trim()}
                className="px-3 py-2 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7e1e] disabled:bg-[#94a3b8] disabled:cursor-not-allowed transition-colors"
                aria-label="Add custom tag"
              >
                <Plus className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={isLoading}
            className="w-full py-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium hover:bg-[#1e7e1e] disabled:bg-[#94a3b8] disabled:cursor-not-allowed transition-colors shadow-md focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2"
            style={{ minHeight: '44px' }}
          >
            {isLoading ? (
              <div className="flex items-center justify-center gap-2">
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                Creating Trip...
              </div>
            ) : (
              'Create Trip'
            )}
          </button>
        </form>
      </div>
    </div>
  )
}

