'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, Calendar, MessageSquare, MapPin } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'organizer' | 'member'
}

interface RsvpResponse {
  id: string
  memberId: string
  status: 'pending' | 'accepted' | 'declined' | 'maybe'
  respondedAt?: Date
  notes?: string
}

interface Trip {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  description: string
  organizerId: string
}

interface RsvpManagementProps {
  trip?: Trip
  members?: TripMember[]
  responses?: RsvpResponse[]
  currentUserId?: string
  onRsvpUpdate?: (memberId: string, status: RsvpResponse['status'], notes?: string) => void
  onSendReminder?: (memberIds: string[]) => void
  onViewDetails?: (tripId: string) => void
}

const DEFAULT_TRIP: Trip = {
  id: '1',
  title: 'Moab Desert Adventure',
  location: 'Moab, Utah',
  startDate: new Date('2024-03-15'),
  endDate: new Date('2024-03-17'),
  description: 'Epic off-road adventure through the red rocks of Moab',
  organizerId: '1'
}

const DEFAULT_MEMBERS: TripMember[] = [
  { id: '1', name: 'Alex Chen', email: 'alex@example.com', role: 'organizer' },
  { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', role: 'member' },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', role: 'member' },
  { id: '4', name: 'Emma Wilson', email: 'emma@example.com', role: 'member' },
  { id: '5', name: 'David Kim', email: 'david@example.com', role: 'member' },
  { id: '6', name: 'Lisa Thompson', email: 'lisa@example.com', role: 'member' }
]

const DEFAULT_RESPONSES: RsvpResponse[] = [
  { id: '1', memberId: '1', status: 'accepted', respondedAt: new Date('2024-02-10') },
  { id: '2', memberId: '2', status: 'accepted', respondedAt: new Date('2024-02-12'), notes: 'Excited for this trip!' },
  { id: '3', memberId: '3', status: 'declined', respondedAt: new Date('2024-02-11'), notes: 'Family commitment that weekend' },
  { id: '4', memberId: '4', status: 'maybe', respondedAt: new Date('2024-02-13'), notes: 'Waiting on work schedule' },
  { id: '5', memberId: '5', status: 'pending' },
  { id: '6', memberId: '6', status: 'pending' }
]

export function RsvpManagement({
  trip = DEFAULT_TRIP,
  members = DEFAULT_MEMBERS,
  responses = DEFAULT_RESPONSES,
  currentUserId = '1',
  onRsvpUpdate = (memberId, status, notes) => console.log('RSVP updated:', { memberId, status, notes }),
  onSendReminder = (memberIds) => console.log('Sending reminders to:', memberIds),
  onViewDetails = (tripId) => console.log('Viewing trip details:', tripId)
}: RsvpManagementProps = {}) {
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [showNotes, setShowNotes] = useState<string | null>(null)
  const [rsvpNotes, setRsvpNotes] = useState('')
  const [filter, setFilter] = useState<'all' | 'pending' | 'accepted' | 'declined' | 'maybe'>('all')

  const getResponseForMember = (memberId: string) => {
    return responses.find(r => r.memberId === memberId)
  }

  const getStatusColor = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted': return 'bg-[rgb(34,139,34)] text-white'
      case 'declined': return 'bg-[rgb(220,38,38)] text-white'
      case 'maybe': return 'bg-[rgb(245,158,11)] text-white'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getStatusIcon = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted': return <Check className="w-4 h-4" />
      case 'declined': return <X className="w-4 h-4" />
      case 'maybe': return <Clock className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  const filteredMembers = members.filter(member => {
    if (filter === 'all') return true
    const response = getResponseForMember(member.id)
    const status = response?.status || 'pending'
    return status === filter
  })

  const stats = {
    total: members.length,
    accepted: responses.filter(r => r.status === 'accepted').length,
    declined: responses.filter(r => r.status === 'declined').length,
    maybe: responses.filter(r => r.status === 'maybe').length,
    pending: members.length - responses.filter(r => r.status !== 'pending').length
  }

  const handleRsvpUpdate = (status: RsvpResponse['status']) => {
    if (currentUserId) {
      onRsvpUpdate(currentUserId, status, rsvpNotes)
      setShowNotes(null)
      setRsvpNotes('')
    }
  }

  const handleSendReminders = () => {
    const pendingMembers = members
      .filter(member => {
        const response = getResponseForMember(member.id)
        return !response || response.status === 'pending'
      })
      .map(member => member.id)

    onSendReminder(pendingMembers)
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric',
      year: 'numeric'
    })
  }

  const currentUserResponse = getResponseForMember(currentUserId)
  const isOrganizer = members.find(m => m.id === currentUserId)?.role === 'organizer'

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="bg-[rgb(34,139,34)] text-white p-4">
        <div className="flex items-center gap-3 mb-3">
          <Calendar className="w-6 h-6" />
          <div>
            <h1 className="text-xl font-semibold">{trip.title}</h1>
            <div className="flex items-center gap-2 text-sm opacity-90">
              <MapPin className="w-4 h-4" />
              <span>{trip.location}</span>
            </div>
          </div>
        </div>

        <div className="text-sm opacity-90">
          {formatDate(trip.startDate)} - {formatDate(trip.endDate)}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="p-4">
        <div className="grid grid-cols-2 gap-3 mb-6">
          <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
            <div className="text-2xl font-semibold text-[rgb(34,139,34)]">{stats.accepted}</div>
            <div className="text-sm text-[rgb(15,23,42)]">Going</div>
          </div>
          <div className="bg-[rgb(248,250,252)] p-4 rounded-lg">
            <div className="text-2xl font-semibold text-[rgb(245,158,11)]">{stats.pending}</div>
            <div className="text-sm text-[rgb(15,23,42)]">Pending</div>
          </div>
        </div>

        {/* Current User RSVP */}
        {!isOrganizer && (
          <div className="bg-white border border-[rgb(226,232,240)] rounded-lg p-4 mb-6 shadow-md">
            <h3 className="font-semibold mb-3">Your RSVP</h3>
            {currentUserResponse?.status && currentUserResponse.status !== 'pending' ? (
              <div className="space-y-3">
                <div className={`inline-flex items-center gap-2 px-3 py-2 rounded-full text-sm ${getStatusColor(currentUserResponse.status)}`}>
                  {getStatusIcon(currentUserResponse.status)}
                  <span className="capitalize">{currentUserResponse.status}</span>
                </div>
                {currentUserResponse.notes && (
                  <p className="text-sm text-[rgb(15,23,42)] bg-[rgb(248,250,252)] p-3 rounded-lg">
                    "{currentUserResponse.notes}"
                  </p>
                )}
                <button
                  onClick={() => setShowNotes(currentUserId)}
                  className="text-[rgb(34,139,34)] text-sm font-medium"
                  aria-label="Update RSVP"
                >
                  Update Response
                </button>
              </div>
            ) : (
              <div className="space-y-3">
                <p className="text-sm text-[rgb(15,23,42)]">Please respond to this trip invitation</p>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleRsvpUpdate('accepted')}
                    className="flex-1 bg-[rgb(34,139,34)] text-white py-3 rounded-lg font-medium min-h-[44px] flex items-center justify-center gap-2"
                    aria-label="Accept invitation"
                  >
                    <Check className="w-4 h-4" />
                    Going
                  </button>
                  <button
                    onClick={() => setShowNotes(currentUserId)}
                    className="flex-1 bg-[rgb(245,158,11)] text-white py-3 rounded-lg font-medium min-h-[44px] flex items-center justify-center gap-2"
                    aria-label="Maybe attend"
                  >
                    <Clock className="w-4 h-4" />
                    Maybe
                  </button>
                  <button
                    onClick={() => handleRsvpUpdate('declined')}
                    className="flex-1 bg-[rgb(220,38,38)] text-white py-3 rounded-lg font-medium min-h-[44px] flex items-center justify-center gap-2"
                    aria-label="Decline invitation"
                  >
                    <X className="w-4 h-4" />
                    Can't Go
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Organizer Actions */}
        {isOrganizer && (
          <div className="bg-white border border-[rgb(226,232,240)] rounded-lg p-4 mb-6 shadow-md">
            <h3 className="font-semibold mb-3">Organizer Actions</h3>
            <div className="space-y-3">
              <button
                onClick={handleSendReminders}
                className="w-full bg-[rgb(34,139,34)] text-white py-3 rounded-lg font-medium min-h-[44px] flex items-center justify-center gap-2"
                aria-label="Send reminders to pending members"
              >
                <MessageSquare className="w-4 h-4" />
                Send Reminders ({stats.pending} pending)
              </button>
              <button
                onClick={() => onViewDetails(trip.id)}
                className="w-full border border-[rgb(226,232,240)] text-[rgb(15,23,42)] py-3 rounded-lg font-medium min-h-[44px]"
                aria-label="View trip details"
              >
                View Trip Details
              </button>
            </div>
          </div>
        )}

        {/* Filter Tabs */}
        <div className="flex gap-2 mb-4 overflow-x-auto">
          {[
            { key: 'all', label: 'All', count: stats.total },
            { key: 'accepted', label: 'Going', count: stats.accepted },
            { key: 'pending', label: 'Pending', count: stats.pending },
            { key: 'maybe', label: 'Maybe', count: stats.maybe },
            { key: 'declined', label: 'Declined', count: stats.declined }
          ].map(({ key, label, count }) => (
            <button
              key={key}
              onClick={() => setFilter(key as any)}
              className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap min-h-[44px] ${
                filter === key
                  ? 'bg-[rgb(34,139,34)] text-white'
                  : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
              }`}
              aria-label={`Filter by ${label}`}
            >
              {label} ({count})
            </button>
          ))}
        </div>

        {/* Members List */}
        <div className="space-y-3">
          {filteredMembers.map(member => {
            const response = getResponseForMember(member.id)
            const status = response?.status || 'pending'

            return (
              <div key={member.id} className="bg-white border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                      {member.name.charAt(0)}
                    </div>
                    <div>
                      <div className="font-medium text-[rgb(15,23,42)]">
                        {member.name}
                        {member.role === 'organizer' && (
                          <span className="ml-2 text-xs bg-[rgb(245,158,11)] text-white px-2 py-1 rounded-full">
                            Organizer
                          </span>
                        )}
                      </div>
                      <div className="text-sm text-gray-600">{member.email}</div>
                    </div>
                  </div>

                  <div className="text-right">
                    <div className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs ${getStatusColor(status)}`}>
                      {getStatusIcon(status)}
                      <span className="capitalize">{status}</span>
                    </div>
                    {response?.respondedAt && (
                      <div className="text-xs text-gray-500 mt-1">
                        {response.respondedAt.toLocaleDateString()}
                      </div>
                    )}
                  </div>
                </div>

                {response?.notes && (
                  <div className="mt-3 p-3 bg-[rgb(248,250,252)] rounded-lg">
                    <p className="text-sm text-[rgb(15,23,42)]">"{response.notes}"</p>
                  </div>
                )}
              </div>
            )
          })}
        </div>

        {filteredMembers.length === 0 && (
          <div className="text-center py-8">
            <Users className="w-12 h-12 text-gray-400 mx-auto mb-3" />
