'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, MapPin, Calendar, Users, Image, Paperclip, MoreVertical, Search } from 'lucide-react'

interface ChatMessage {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'image' | 'location' | 'task' | 'event'
  metadata?: {
    location?: { lat: number; lng: number; name: string }
    taskId?: string
    eventId?: string
    imageUrl?: string
  }
}

interface GroupMember {
  id: string
  name: string
  avatar: string
  isOnline: boolean
  lastSeen?: Date
}

interface GroupChatComponentProps {
  tripId?: string
  groupMembers?: GroupMember[]
  initialMessages?: ChatMessage[]
  onSendMessage?: (message: Omit<ChatMessage, 'id' | 'timestamp'>) => void
  onShareLocation?: () => void
  onCreateTask?: () => void
  onScheduleEvent?: () => void
}

export function GroupChatComponent({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  initialMessages = DEFAULT_MESSAGES,
  onSendMessage = (message) => console.log('Send message:', message),
  onShareLocation = () => console.log('Share location'),
  onCreateTask = () => console.log('Create task'),
  onScheduleEvent = () => console.log('Schedule event')
}: GroupChatComponentProps = {}) {
  const [messages, setMessages] = useState<ChatMessage[]>(initialMessages)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [showSearch, setShowSearch] = useState(false)
  const [showAttachments, setShowAttachments] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const currentUser = {
    id: 'current-user',
    name: 'You',
    avatar: '/api/placeholder/32/32'
  }

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Omit<ChatMessage, 'id' | 'timestamp'> = {
      userId: currentUser.id,
      userName: currentUser.name,
      userAvatar: currentUser.avatar,
      content: newMessage.trim(),
      type: 'text'
    }

    const fullMessage: ChatMessage = {
      ...message,
      id: `msg-${Date.now()}`,
      timestamp: new Date()
    }

    setMessages(prev => [...prev, fullMessage])
    onSendMessage(message)
    setNewMessage('')
    setShowAttachments(false)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleShareLocation = () => {
    const locationMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      userId: currentUser.id,
      userName: currentUser.name,
      userAvatar: currentUser.avatar,
      content: 'Shared current location',
      timestamp: new Date(),
      type: 'location',
      metadata: {
        location: { lat: 37.7749, lng: -122.4194, name: 'Moab, Utah' }
      }
    }
    setMessages(prev => [...prev, locationMessage])
    setShowAttachments(false)
    onShareLocation()
  }

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true 
    })
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    }
  }

  const filteredMessages = searchQuery
    ? messages.filter(msg => 
        msg.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
        msg.userName.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : messages

  const groupedMessages = filteredMessages.reduce((groups, message) => {
    const dateKey = message.timestamp.toDateString()
    if (!groups[dateKey]) {
      groups[dateKey] = []
    }
    groups[dateKey].push(message)
    return groups
  }, {} as Record<string, ChatMessage[]>)

  const renderMessage = (message: ChatMessage) => {
    const isCurrentUser = message.userId === currentUser.id
    const member = groupMembers.find(m => m.id === message.userId)

    return (
      <div
        key={message.id}
        className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}
      >
        {!isCurrentUser && (
          <img
            src={message.userAvatar}
            alt={message.userName}
            className="w-8 h-8 rounded-full flex-shrink-0"
          />
        )}

        <div className={`flex flex-col max-w-[75%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
          {!isCurrentUser && (
            <span className="text-xs font-medium text-[rgb(15,23,42)] mb-1">
              {message.userName}
            </span>
          )}

          <div
            className={`px-4 py-2 rounded-2xl ${
              isCurrentUser
                ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
            }`}
          >
            {message.type === 'location' && (
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="w-4 h-4" />
                <span className="text-sm font-medium">
                  {message.metadata?.location?.name}
                </span>
              </div>
            )}

            {message.type === 'task' && (
              <div className="flex items-center gap-2 mb-2">
                <Users className="w-4 h-4" />
                <span className="text-sm font-medium">Task Assignment</span>
              </div>
            )}

            {message.type === 'event' && (
              <div className="flex items-center gap-2 mb-2">
                <Calendar className="w-4 h-4" />
                <span className="text-sm font-medium">Event Scheduled</span>
              </div>
            )}

            <p className="text-sm leading-relaxed">{message.content}</p>
          </div>

          <span className="text-xs text-gray-500 mt-1">
            {formatTime(message.timestamp)}
          </span>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            {groupMembers.slice(0, 3).map((member) => (
              <div key={member.id} className="relative">
                <img
                  src={member.avatar}
                  alt={member.name}
                  className="w-8 h-8 rounded-full border-2 border-white"
                />
                {member.isOnline && (
                  <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-[rgb(34,139,34)] rounded-full border-2 border-white"></div>
                )}
              </div>
            ))}
          </div>
          <div>
            <h2 className="font-semibold text-[rgb(15,23,42)]">Trip Group</h2>
            <p className="text-xs text-gray-500">
              {groupMembers.filter(m => m.isOnline).length} online
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowSearch(!showSearch)}
            className="p-2 rounded-full hover:bg-[rgb(241,245,249)] transition-colors"
            aria-label="Search messages"
          >
            <Search className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>
          <button
            className="p-2 rounded-full hover:bg-[rgb(241,245,249)] transition-colors"
            aria-label="More options"
          >
            <MoreVertical className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>
        </div>
      </div>

      {/* Search Bar */}
      {showSearch && (
        <div className="p-4 border-b border-[rgb(226,232,240)]">
          <input
            type="text"
            placeholder="Search messages..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full px-4 py-2 border border-[rgb(226,232,240)] rounded-full focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent"
          />
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {Object.entries(groupedMessages).map(([dateKey, dayMessages]) => (
          <div key={dateKey}>
            <div className="flex justify-center mb-4">
              <span className="px-3 py-1 text-xs font-medium bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-full">
                {formatDate(new Date(dateKey))}
              </span>
            </div>
            <div className="space-y-4">
              {dayMessages.map(renderMessage)}
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-[rgb(241,245,249)] flex items-center justify-center">
              <div className="flex space-x-1">
                <div className="w-1 h-1 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-1 h-1 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                <div className="w-1 h-1 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              </div>
            </div>
            <span className="text-sm text-gray-500">Someone is typing...</span>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Attachment Menu */}
      {showAttachments && (
        <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
          <div className="grid grid-cols-3 gap-4">
            <button
              onClick={handleShareLocation}
              className="flex flex-col items-center gap-2 p-4 rounded-lg bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-colors"
            >
              <MapPin className="w-6 h-6 text-[rgb(34,139,34)]" />
              <span className="text-sm font-medium text-[rgb(15,23,42)]">Location</span>
            </button>

            <button
              onClick={onCreateTask}
              className="flex flex-col items-center gap-2 p-4 rounded-lg bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-colors"
            >
              <Users className="w-6 h-6 text-[rgb(245,158,11)]" />
              <span className="text-sm font-medium text-[rgb(15,23,42)]">Task</span>
            </button>

            <button
              onClick={onScheduleEvent}
              className="flex flex-col items-center gap-2 p-4 rounded-lg bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-colors"
            >
              <Calendar className="w-6 h-6 text-[rgb(34,139,34)]" />
              <span className="text-sm font-medium text-[rgb(15,23,42)]">Event</span>
            </button>
          </div>
        </div>
      )}

      {/* Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-end gap-3">
          <button
            onClick={() => setShowAttachments(!showAttachments)}
            className="p-2 rounded-full hover:bg-[rgb(241,245,249)] transition-colors flex-shrink-0"
            aria-label="Attach file"
          >
            <Paperclip className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              placeholder="Type a message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              className="w-full px-4 py-3 border border-[rgb(226,232,240)] rounded-full focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent resize-none"
              style={{ minHeight: '44px' }}
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex-shrink-0"
            style={{ minWidth: '44px', minHeight: '44px' }}
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

