'use client'

import { useState, useEffect } from 'react'
import { Plus, Edit3, Trash2, Clock, Users, ChefHat, Calendar } from 'lucide-react'

interface Meal {
  id: string
  name: string
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack'
  date: string
  time: string
  assignedTo: string[]
  ingredients: string[]
  servings: number
  notes?: string
  status: 'planned' | 'in-progress' | 'completed'
}

interface GroupMember {
  id: string
  name: string
  avatar?: string
}

interface MealPlanningComponentProps {
  tripId?: string
  groupMembers?: GroupMember[]
  existingMeals?: Meal[]
  onMealUpdate?: (meal: Meal) => void
  onMealDelete?: (mealId: string) => void
}

export function MealPlanningComponent({
  tripId = 'trip-1',
  groupMembers = DEFAULT_GROUP_MEMBERS,
  existingMeals = DEFAULT_MEALS,
  onMealUpdate = () => console.log('Meal updated'),
  onMealDelete = () => console.log('Meal deleted')
}: MealPlanningComponentProps = {}) {
  const [meals, setMeals] = useState<Meal[]>(existingMeals)
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0])
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingMeal, setEditingMeal] = useState<Meal | null>(null)
  const [newMeal, setNewMeal] = useState<Partial<Meal>>({
    name: '',
    type: 'breakfast',
    date: selectedDate,
    time: '08:00',
    assignedTo: [],
    ingredients: [],
    servings: 4,
    notes: '',
    status: 'planned'
  })

  const mealTypes = [
    { value: 'breakfast', label: 'Breakfast', icon: '🌅' },
    { value: 'lunch', label: 'Lunch', icon: '☀️' },
    { value: 'dinner', label: 'Dinner', icon: '🌙' },
    { value: 'snack', label: 'Snack', icon: '🥨' }
  ]

  const getUpcomingDates = () => {
    const dates = []
    for (let i = 0; i < 7; i++) {
      const date = new Date()
      date.setDate(date.getDate() + i)
      dates.push(date.toISOString().split('T')[0])
    }
    return dates
  }

  const getMealsForDate = (date: string) => {
    return meals.filter(meal => meal.date === date).sort((a, b) => a.time.localeCompare(b.time))
  }

  const handleAddMeal = () => {
    if (!newMeal.name || !newMeal.type) return

    const meal: Meal = {
      id: Date.now().toString(),
      name: newMeal.name,
      type: newMeal.type as Meal['type'],
      date: newMeal.date || selectedDate,
      time: newMeal.time || '08:00',
      assignedTo: newMeal.assignedTo || [],
      ingredients: newMeal.ingredients || [],
      servings: newMeal.servings || 4,
      notes: newMeal.notes || '',
      status: 'planned'
    }

    setMeals(prev => [...prev, meal])
    onMealUpdate(meal)
    setShowAddForm(false)
    setNewMeal({
      name: '',
      type: 'breakfast',
      date: selectedDate,
      time: '08:00',
      assignedTo: [],
      ingredients: [],
      servings: 4,
      notes: '',
      status: 'planned'
    })
  }

  const handleEditMeal = (meal: Meal) => {
    setEditingMeal(meal)
    setNewMeal(meal)
    setShowAddForm(true)
  }

  const handleUpdateMeal = () => {
    if (!editingMeal || !newMeal.name) return

    const updatedMeal: Meal = {
      ...editingMeal,
      ...newMeal
    } as Meal

    setMeals(prev => prev.map(meal => meal.id === editingMeal.id ? updatedMeal : meal))
    onMealUpdate(updatedMeal)
    setEditingMeal(null)
    setShowAddForm(false)
    setNewMeal({
      name: '',
      type: 'breakfast',
      date: selectedDate,
      time: '08:00',
      assignedTo: [],
      ingredients: [],
      servings: 4,
      notes: '',
      status: 'planned'
    })
  }

  const handleDeleteMeal = (mealId: string) => {
    setMeals(prev => prev.filter(meal => meal.id !== mealId))
    onMealDelete(mealId)
  }

  const toggleMemberAssignment = (memberId: string) => {
    setNewMeal(prev => ({
      ...prev,
      assignedTo: prev.assignedTo?.includes(memberId)
        ? prev.assignedTo.filter(id => id !== memberId)
        : [...(prev.assignedTo || []), memberId]
    }))
  }

  const addIngredient = (ingredient: string) => {
    if (ingredient.trim()) {
      setNewMeal(prev => ({
        ...prev,
        ingredients: [...(prev.ingredients || []), ingredient.trim()]
      }))
    }
  }

  const removeIngredient = (index: number) => {
    setNewMeal(prev => ({
      ...prev,
      ingredients: prev.ingredients?.filter((_, i) => i !== index) || []
    }))
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    })
  }

  const getMemberName = (memberId: string) => {
    return groupMembers.find(member => member.id === memberId)?.name || 'Unknown'
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] z-10">
        <div className="p-4">
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Meal Planning</h1>
            <button
              onClick={() => setShowAddForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors"
              aria-label="Add new meal"
            >
              <Plus size={20} />
              <span className="hidden sm:inline">Add Meal</span>
            </button>
          </div>

          {/* Date Selector */}
          <div className="flex gap-2 overflow-x-auto pb-2">
            {getUpcomingDates().map(date => (
              <button
                key={date}
                onClick={() => setSelectedDate(date)}
                className={`flex-shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  selectedDate === date
                    ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                    : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                }`}
              >
                {formatDate(date)}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Meals List */}
      <div className="p-4 space-y-4">
        {getMealsForDate(selectedDate).length === 0 ? (
          <div className="text-center py-12">
            <ChefHat size={48} className="mx-auto text-[rgb(226,232,240)] mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No meals planned</h3>
            <p className="text-[rgb(100,116,139)] mb-4">Start planning your meals for {formatDate(selectedDate)}</p>
            <button
              onClick={() => setShowAddForm(true)}
              className="px-6 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors"
            >
              Add First Meal
            </button>
          </div>
        ) : (
          getMealsForDate(selectedDate).map(meal => (
            <div key={meal.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-md">
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <span className="text-2xl">
                    {mealTypes.find(type => type.value === meal.type)?.icon}
                  </span>
                  <div>
                    <h3 className="font-semibold text-[rgb(15,23,42)]">{meal.name}</h3>
                    <div className="flex items-center gap-4 text-sm text-[rgb(100,116,139)]">
                      <div className="flex items-center gap-1">
                        <Clock size={14} />
                        {meal.time}
                      </div>
                      <div className="flex items-center gap-1">
                        <Users size={14} />
                        {meal.servings} servings
                      </div>
                    </div>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleEditMeal(meal)}
                    className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] hover:bg-[rgb(248,250,252)] rounded-lg transition-colors"
                    aria-label="Edit meal"
                  >
                    <Edit3 size={16} />
                  </button>
                  <button
                    onClick={() => handleDeleteMeal(meal.id)}
                    className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(220,38,38)] hover:bg-[rgb(254,242,242)] rounded-lg transition-colors"
                    aria-label="Delete meal"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              {meal.assignedTo.length > 0 && (
                <div className="mb-3">
                  <p className="text-sm text-[rgb(100,116,139)] mb-1">Assigned to:</p>
                  <div className="flex flex-wrap gap-2">
                    {meal.assignedTo.map(memberId => (
                      <span
                        key={memberId}
                        className="px-2 py-1 bg-[rgb(245,158,11)] text-[rgb(255,255,255)] text-xs rounded-full"
                      >
                        {getMemberName(memberId)}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {meal.ingredients.length > 0 && (
                <div className="mb-3">
                  <p className="text-sm text-[rgb(100,116,139)] mb-1">Ingredients:</p>
                  <div className="flex flex-wrap gap-1">
                    {meal.ingredients.map((ingredient, index) => (
                      <span
                        key={index}
                        className="px-2 py-1 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] text-xs rounded"
                      >
                        {ingredient}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {meal.notes && (
                <div className="text-sm text-[rgb(100,116,139)]">
                  <p className="font-medium mb-1">Notes:</p>
                  <p>{meal.notes}</p>
                </div>
              )}
            </div>
          ))
        )}
      </div>

      {/* Add/Edit Meal Modal */}
      {showAddForm && (
        <div className="fixed inset-0 bg-black/50 flex items-end sm:items-center justify-center z-50">
          <div className="bg-[rgb(255,255,255)] w-full sm:w-96 sm:rounded-lg max-h-[90vh] overflow-y-auto">
            <div className="p-4 border-b border-[rgb(226,232,240)]">
              <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">
                {editingMeal ? 'Edit Meal' : 'Add New Meal'}
              </h2>
            </div>

            <div className="p-4 space-y-4">
              {/* Meal Name */}
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Meal Name
                </label>
                <input
                  type="text"
                  value={newMeal.name || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] text-[rgb(15,23,42)]"
                  placeholder="Enter meal name"
                />
              </div>

              {/* Meal Type */}
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Meal Type
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {mealTypes.map(type => (
                    <button
                      key={type.value}
                      onClick={() => setNewMeal(prev => ({ ...prev, type: type.value as Meal['type'] }))}
                      className={`flex items-center gap-2 p-3 rounded-lg border transition-colors ${
                        newMeal.type === type.value
                          ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)]'
                          : 'border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]'
                      }`}
                    >
                      <span>{type.icon}</span>
                      <span className="text-sm font-medium">{type.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Date and Time */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Date
                  </label>
                  <input
                    type="date"
                    value={newMeal.date || selectedDate}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, date: e.target.value }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] text-[rgb(15,23,42)]"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                    Time
                  </label>
                  <input
                    type="time"
                    value={newMeal.time || '08:00'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, time: e.target.value }))}
                    className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] text-[rgb(15,23,42)]"
                  />
                </div>
              </div>

              {/* Servings */}
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Servings
                </label>
                <input
                  type="number"
                  min="1"
                  value={newMeal.servings || 4}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, servings: parseInt(e.target.value) }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] text-[rgb(15,23,42)]"
                />
              </div>

              {/* Assign Members */}
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Assign to Members
                </label>
                <div className="space-y-2">
                  {groupMembers.map(member => (
                    <button
                      key={member.id}
                      onClick={() => toggleMemberAssignment(member.id)}
                      className={`w-full flex items-center gap-3 p-3 rounded-lg border transition-colors ${
                        newMeal.assignedTo?.includes(member.id)
                          ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)]'
                          : 'border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]'
                      }`}
                    >
                      <div className="w-8 h-8 bg-[rgb(245,158,11)] rounded-full flex items-center justify-center text-[rgb(255,255,255)] text-sm font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <span>{member.name}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Notes */}
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Notes
                </label>
                <textarea
                  value={newMeal.notes || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, notes: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] text-[rgb(15,23,42)] resize-none"
                  rows={3}
                  placeholder="Add any notes or special instructions..."
                />
              </div>
            </div>

            {/* Actions */}
            <div className="p-4 border-t border-[rgb(226,232,240)] flex gap-3">
              <button
                onClick={() => {
                  setShowAddForm(false)
                  setEditingMeal(null)
                  setNewMeal({
                    name: '',
                    type: 'breakfast',
                    date: selectedDate,
                    time: '08:00',
                    assignedTo: [],
                    ingredients: [],
                    servings: 4,
                    notes: '',
                    status: 'planned'
                  })
                }}
                className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={editingMeal ? handleUpdateMeal : handleAddMeal}
                disabled={!newMeal.name}
                className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {editingMeal ? 'Update Meal' : 'Add Meal'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

