'use client'

import { useState, useEffect } from 'react'
import { Plus, Check, Clock, User, Calendar, MessageSquare, Trash2, Edit3 } from 'lucide-react'

interface Task {
  id: string
  title: string
  description: string
  assignedTo: string
  assignedToName: string
  dueDate: string
  category: 'meals' | 'equipment' | 'logistics' | 'safety' | 'other'
  status: 'pending' | 'in-progress' | 'completed'
  priority: 'low' | 'medium' | 'high'
  createdAt: string
}

interface Member {
  id: string
  name: string
  avatar: string
  role: 'organizer' | 'member'
}

interface TaskManagementProps {
  tripId?: string
  members?: Member[]
  initialTasks?: Task[]
  onTaskUpdate?: (task: Task) => void
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt'>) => void
  onTaskDelete?: (taskId: string) => void
}

const DEFAULT_MEMBERS: Member[] = [
  { id: '1', name: 'Alex Chen', avatar: 'AC', role: 'organizer' },
  { id: '2', name: 'Sarah Johnson', avatar: 'SJ', role: 'member' },
  { id: '3', name: 'Mike Rodriguez', avatar: 'MR', role: 'member' },
  { id: '4', name: 'Emma Davis', avatar: 'ED', role: 'member' }
]

const DEFAULT_TASKS: Task[] = [
  {
    id: '1',
    title: 'Saturday Lunch Prep',
    description: 'Prepare sandwiches and snacks for the group',
    assignedTo: '2',
    assignedToName: 'Sarah Johnson',
    dueDate: '2024-01-20T12:00:00Z',
    category: 'meals',
    status: 'pending',
    priority: 'high',
    createdAt: '2024-01-15T10:00:00Z'
  },
  {
    id: '2',
    title: 'Firewood Collection',
    description: 'Gather dry firewood for evening campfire',
    assignedTo: '3',
    assignedToName: 'Mike Rodriguez',
    dueDate: '2024-01-20T16:00:00Z',
    category: 'logistics',
    status: 'in-progress',
    priority: 'medium',
    createdAt: '2024-01-15T10:30:00Z'
  },
  {
    id: '3',
    title: 'First Aid Kit Check',
    description: 'Verify all medical supplies are stocked',
    assignedTo: '4',
    assignedToName: 'Emma Davis',
    dueDate: '2024-01-19T18:00:00Z',
    category: 'safety',
    status: 'completed',
    priority: 'high',
    createdAt: '2024-01-15T11:00:00Z'
  }
]

const CATEGORIES = [
  { value: 'meals', label: 'Meals', color: 'bg-orange-100 text-orange-800' },
  { value: 'equipment', label: 'Equipment', color: 'bg-blue-100 text-blue-800' },
  { value: 'logistics', label: 'Logistics', color: 'bg-purple-100 text-purple-800' },
  { value: 'safety', label: 'Safety', color: 'bg-red-100 text-red-800' },
  { value: 'other', label: 'Other', color: 'bg-[rgb(241, 245, 249)] text-gray-800' }
]

const PRIORITIES = [
  { value: 'low', label: 'Low', color: 'bg-green-100 text-green-800' },
  { value: 'medium', label: 'Medium', color: 'bg-yellow-100 text-yellow-800' },
  { value: 'high', label: 'High', color: 'bg-red-100 text-red-800' }
]

export function TaskManagement({
  tripId = 'trip-1',
  members = DEFAULT_MEMBERS,
  initialTasks = DEFAULT_TASKS,
  onTaskUpdate = () => {},
  onTaskCreate = () => {},
  onTaskDelete = () => {}
}: TaskManagementProps = {}) {
  const [tasks, setTasks] = useState<Task[]>(initialTasks)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingTask, setEditingTask] = useState<Task | null>(null)
  const [filter, setFilter] = useState<'all' | 'pending' | 'in-progress' | 'completed'>('all')
  const [categoryFilter, setCategoryFilter] = useState<string>('all')

  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    assignedTo: '',
    dueDate: '',
    category: 'other' as Task['category'],
    priority: 'medium' as Task['priority']
  })

  const filteredTasks = tasks.filter(task => {
    const statusMatch = filter === 'all' || task.status === filter
    const categoryMatch = categoryFilter === 'all' || task.category === categoryFilter
    return statusMatch && categoryMatch
  })

  const handleCreateTask = () => {
    if (!newTask.title.trim() || !newTask.assignedTo) return

    const assignedMember = members.find(m => m.id === newTask.assignedTo)
    if (!assignedMember) return

    const task: Task = {
      id: Date.now().toString(),
      ...newTask,
      assignedToName: assignedMember.name,
      status: 'pending',
      createdAt: new Date().toISOString()
    }

    setTasks(prev => [...prev, task])
    onTaskCreate(task)
    setNewTask({
      title: '',
      description: '',
      assignedTo: '',
      dueDate: '',
      category: 'other',
      priority: 'medium'
    })
    setShowCreateForm(false)
  }

  const handleUpdateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, ...updates } : task
    ))

    const updatedTask = tasks.find(t => t.id === taskId)
    if (updatedTask) {
      onTaskUpdate({ ...updatedTask, ...updates })
    }
  }

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(task => task.id !== taskId))
    onTaskDelete(taskId)
  }

  const getStatusIcon = (status: Task['status']) => {
    switch (status) {
      case 'completed':
        return <Check className="w-4 h-4 text-green-600" />
      case 'in-progress':
        return <Clock className="w-4 h-4 text-yellow-600" />
      default:
        return <Clock className="w-4 h-4 text-gray-400" />
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getTaskStats = () => {
    const total = tasks.length
    const completed = tasks.filter(t => t.status === 'completed').length
    const pending = tasks.filter(t => t.status === 'pending').length
    const inProgress = tasks.filter(t => t.status === 'in-progress').length

    return { total, completed, pending, inProgress }
  }

  const stats = getTaskStats()

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="bg-[rgb(34,139,34)] text-[rgb(255,255,255)] p-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-semibold">Task Management</h1>
            <p className="text-sm opacity-90">Organize your off-road adventure</p>
          </div>
          <button
            onClick={() => setShowCreateForm(true)}
            className="w-12 h-12 bg-[rgb(255,255,255)] bg-opacity-20 rounded-full flex items-center justify-center"
            aria-label="Create new task"
          >
            <Plus className="w-6 h-6" />
          </button>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-4 gap-2 mt-4">
          <div className="bg-[rgb(255,255,255)] bg-opacity-10 rounded-lg p-3 text-center">
            <div className="text-lg font-semibold">{stats.total}</div>
            <div className="text-xs opacity-80">Total</div>
          </div>
          <div className="bg-[rgb(255,255,255)] bg-opacity-10 rounded-lg p-3 text-center">
            <div className="text-lg font-semibold">{stats.pending}</div>
            <div className="text-xs opacity-80">Pending</div>
          </div>
          <div className="bg-[rgb(255,255,255)] bg-opacity-10 rounded-lg p-3 text-center">
            <div className="text-lg font-semibold">{stats.inProgress}</div>
            <div className="text-xs opacity-80">In Progress</div>
          </div>
          <div className="bg-[rgb(255,255,255)] bg-opacity-10 rounded-lg p-3 text-center">
            <div className="text-lg font-semibold">{stats.completed}</div>
            <div className="text-xs opacity-80">Done</div>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="p-4 border-b border-[rgb(226,232,240)]">
        <div className="flex gap-2 mb-3 overflow-x-auto">
          {['all', 'pending', 'in-progress', 'completed'].map(status => (
            <button
              key={status}
              onClick={() => setFilter(status as any)}
              className={`px-3 py-1 rounded-full text-sm whitespace-nowrap ${
                filter === status
                  ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                  : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
              }`}
            >
              {status.charAt(0).toUpperCase() + status.slice(1).replace('-', ' ')}
            </button>
          ))}
        </div>

        <div className="flex gap-2 overflow-x-auto">
          <button
            onClick={() => setCategoryFilter('all')}
            className={`px-3 py-1 rounded-full text-sm whitespace-nowrap ${
              categoryFilter === 'all'
                ? 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
            }`}
          >
            All Categories
          </button>
          {CATEGORIES.map(category => (
            <button
              key={category.value}
              onClick={() => setCategoryFilter(category.value)}
              className={`px-3 py-1 rounded-full text-sm whitespace-nowrap ${
                categoryFilter === category.value
                  ? 'bg-[rgb(245,158,11)] text-[rgb(255,255,255)]'
                  : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
              }`}
            >
              {category.label}
            </button>
          ))}
        </div>
      </div>

      {/* Task List */}
      <div className="p-4 space-y-3">
        {filteredTasks.length === 0 ? (
          <div className="text-center py-12">
            <Calendar className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No tasks found</h3>
            <p className="text-[rgb(100,116,139)] mb-4">
              {filter === 'all' ? 'Create your first task to get started' : `No ${filter.replace('-', ' ')} tasks`}
            </p>
            <button
              onClick={() => setShowCreateForm(true)}
              className="px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg"
            >
              Create Task
            </button>
          </div>
        ) : (
          filteredTasks.map(task => {
            const category = CATEGORIES.find(c => c.value === task.category)
            const priority = PRIORITIES.find(p => p.value === task.priority)
            const assignedMember = members.find(m => m.id === task.assignedTo)

            return (
              <div
                key={task.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 shadow-sm"
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      {getStatusIcon(task.status)}
                      <h3 className="font-semibold text-[rgb(15,23,42)]">{task.title}</h3>
                    </div>
                    {task.description && (
                      <p className="text-sm text-[rgb(100,116,139)] mb-2">{task.description}</p>
                    )}

                    <div className="flex flex-wrap gap-2 mb-2">
                      {category && (
                        <span className={`px-2 py-1 text-xs rounded-full ${category.color}`}>
                          {category.label}
                        </span>
                      )}
                      {priority && (
                        <span className={`px-2 py-1 text-xs rounded-full ${priority.color}`}>
                          {priority.label}
                        </span>
                      )}
                    </div>

                    <div className="flex items-center gap-4 text-sm text-[rgb(100,116,139)]">
                      {assignedMember && (
                        <div className="flex items-center gap-1">
                          <div className="w-6 h-6 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full flex items-center justify-center text-xs">
                            {assignedMember.avatar}
                          </div>
