'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Users, MapPin, Calendar } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignUp?: (email: string, password: string, name: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignUp = (email, password, name) => console.log('Sign up:', { email, password, name }),
  onForgotPassword = (email) => console.log('Forgot password:', email)
}: LoginPageProps = {}) {
  const [isSignUp, setIsSignUp] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  })
  const [isLoading, setIsLoading] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (isSignUp && !formData.name.trim()) {
      newErrors.name = 'Name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 6) {
      newErrors.password = 'Password must be at least 6 characters'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsLoading(true)

    try {
      if (isSignUp) {
        await onSignUp(formData.email, formData.password, formData.name)
      } else {
        await onLogin(formData.email, formData.password)
      }
    } catch (error) {
      console.error('Authentication error:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (!formData.email.trim()) {
      setErrors({ email: 'Please enter your email first' })
      return
    }
    onForgotPassword(formData.email)
  }

  const updateFormData = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Hero Section */}
      <div className="relative bg-gradient-to-br from-[#228B22] to-[#1e7e1e] text-white px-6 pt-12 pb-8">
        <div className="max-w-md mx-auto text-center">
          <div className="flex items-center justify-center gap-3 mb-6">
            <Mountain className="w-8 h-8" />
            <h1 className="text-2xl font-bold">TrailPlan</h1>
          </div>

          <h2 className="text-xl font-semibold mb-3">
            Plan Epic Off-Road Adventures
          </h2>

          <p className="text-white/90 text-sm leading-relaxed mb-8">
            Organize trips, assign tasks, track weather, and coordinate with your crew all in one place.
          </p>

          {/* Feature Icons */}
          <div className="flex justify-center gap-8 text-white/80">
            <div className="flex flex-col items-center gap-1">
              <MapPin className="w-5 h-5" />
              <span className="text-xs">Locations</span>
            </div>
            <div className="flex flex-col items-center gap-1">
              <Users className="w-5 h-5" />
              <span className="text-xs">Groups</span>
            </div>
            <div className="flex flex-col items-center gap-1">
              <Calendar className="w-5 h-5" />
              <span className="text-xs">Planning</span>
            </div>
          </div>
        </div>
      </div>

      {/* Login Form */}
      <div className="flex-1 px-6 py-8">
        <div className="max-w-md mx-auto">
          <div className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-md">
            <div className="text-center mb-6">
              <h3 className="text-xl font-semibold text-[#0f172a] mb-2">
                {isSignUp ? 'Create Account' : 'Welcome Back'}
              </h3>
              <p className="text-sm text-gray-600">
                {isSignUp 
                  ? 'Join the adventure community' 
                  : 'Sign in to plan your next trip'
                }
              </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              {isSignUp && (
                <div>
                  <label htmlFor="name" className="block text-sm font-medium text-[#0f172a] mb-2">
                    Full Name
                  </label>
                  <input
                    id="name"
                    type="text"
                    value={formData.name}
                    onChange={(e) => updateFormData('name', e.target.value)}
                    className={`w-full px-4 py-3 bg-white border rounded-lg text-[#0f172a] placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#228B22] focus:border-transparent transition-all duration-150 ${
                      errors.name ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                    }`}
                    placeholder="Enter your full name"
                    aria-describedby={errors.name ? 'name-error' : undefined}
                  />
                  {errors.name && (
                    <p id="name-error" className="mt-1 text-xs text-[#dc2626]" role="alert">
                      {errors.name}
                    </p>
                  )}
                </div>
              )}

              <div>
                <label htmlFor="email" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Email Address
                </label>
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => updateFormData('email', e.target.value)}
                  className={`w-full px-4 py-3 bg-white border rounded-lg text-[#0f172a] placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#228B22] focus:border-transparent transition-all duration-150 ${
                    errors.email ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="Enter your email"
                  aria-describedby={errors.email ? 'email-error' : undefined}
                />
                {errors.email && (
                  <p id="email-error" className="mt-1 text-xs text-[#dc2626]" role="alert">
                    {errors.email}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Password
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={formData.password}
                    onChange={(e) => updateFormData('password', e.target.value)}
                    className={`w-full px-4 py-3 pr-12 bg-white border rounded-lg text-[#0f172a] placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#228B22] focus:border-transparent transition-all duration-150 ${
                      errors.password ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                    }`}
                    placeholder="Enter your password"
                    aria-describedby={errors.password ? 'password-error' : undefined}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors duration-150 p-1"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
                {errors.password && (
                  <p id="password-error" className="mt-1 text-xs text-[#dc2626]" role="alert">
                    {errors.password}
                  </p>
                )}
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 bg-[#228B22] text-white rounded-lg font-medium hover:bg-[#1e7e1e] focus:outline-none focus:ring-2 focus:ring-[#228B22] focus:ring-offset-2 transition-all duration-150 shadow-md hover:shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label={isSignUp ? 'Create account' : 'Sign in'}
              >
                {isLoading ? (
                  <div className="flex items-center justify-center gap-2">
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    {isSignUp ? 'Creating Account...' : 'Signing In...'}
                  </div>
                ) : (
                  isSignUp ? 'Create Account' : 'Sign In'
                )}
              </button>
            </form>

            {!isSignUp && (
              <button
                onClick={handleForgotPassword}
                className="w-full mt-3 text-sm text-[#228B22] hover:text-[#1e7e1e] transition-colors duration-150 font-medium"
              >
                Forgot your password?
              </button>
            )}

            <div className="mt-6 pt-6 border-t border-[#e2e8f0] text-center">
              <p className="text-sm text-gray-600">
                {isSignUp ? 'Already have an account?' : "Don't have an account?"}
                <button
                  onClick={() => {
                    setIsSignUp(!isSignUp)
                    setErrors({})
                    setFormData({ name: '', email: '', password: '' })
                  }}
                  className="ml-1 text-[#228B22] hover:text-[#1e7e1e] font-medium transition-colors duration-150"
                >
                  {isSignUp ? 'Sign In' : 'Sign Up'}
                </button>
              </p>
            </div>
          </div>

          {/* Trust Indicators */}
          <div className="mt-6 text-center">
            <p className="text-xs text-gray-500 leading-relaxed">
              Join thousands of adventurers planning epic off-road trips.<br />
              Your data is secure and never shared.
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function LoginPageDemo() {
  return <LoginPage />
}

