'use client'

import { useState, useEffect } from 'react'
import { Database, CheckCircle, AlertCircle, Wifi, WifiOff } from 'lucide-react'

interface DatabaseConnection {
  id: string
  status: 'connected' | 'disconnected' | 'error'
  lastSync: Date
  endpoint: string
}

interface SupabaseClientSetupProps {
  onConnectionChange?: (status: 'connected' | 'disconnected' | 'error') => void
  autoConnect?: boolean
}

export function SupabaseClientSetup({
  onConnectionChange = () => {},
  autoConnect = true
}: SupabaseClientSetupProps = {}) {
  const [connection, setConnection] = useState<DatabaseConnection>({
    id: 'supabase-main',
    status: 'disconnected',
    lastSync: new Date(),
    endpoint: 'https://your-project.supabase.co'
  })
  const [isOnline, setIsOnline] = useState(true)
  const [retryCount, setRetryCount] = useState(0)
  const [isConnecting, setIsConnecting] = useState(false)

  // Simulate connection status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  // Auto-connect on mount
  useEffect(() => {
    if (autoConnect && isOnline) {
      handleConnect()
    }
  }, [autoConnect, isOnline])

  const handleConnect = async () => {
    if (!isOnline) return

    setIsConnecting(true)

    try {
      // Simulate connection attempt
      await new Promise(resolve => setTimeout(resolve, 1500))

      // Simulate occasional connection failures
      const shouldFail = Math.random() < 0.2 && retryCount < 2

      if (shouldFail) {
        throw new Error('Connection timeout')
      }

      const newConnection: DatabaseConnection = {
        ...connection,
        status: 'connected',
        lastSync: new Date()
      }

      setConnection(newConnection)
      onConnectionChange('connected')
      setRetryCount(0)
    } catch (error) {
      const newConnection: DatabaseConnection = {
        ...connection,
        status: 'error'
      }

      setConnection(newConnection)
      onConnectionChange('error')
      setRetryCount(prev => prev + 1)
    } finally {
      setIsConnecting(false)
    }
  }

  const handleDisconnect = () => {
    const newConnection: DatabaseConnection = {
      ...connection,
      status: 'disconnected'
    }

    setConnection(newConnection)
    onConnectionChange('disconnected')
  }

  const getStatusColor = () => {
    switch (connection.status) {
      case 'connected':
        return 'text-[rgb(34,139,34)]'
      case 'error':
        return 'text-[rgb(220,38,38)]'
      default:
        return 'text-[rgb(148,163,184)]'
    }
  }

  const getStatusIcon = () => {
    if (isConnecting) {
      return (
        <div className="w-5 h-5 border-2 border-[rgb(34,139,34)] border-t-transparent rounded-full animate-spin" />
      )
    }

    switch (connection.status) {
      case 'connected':
        return <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
      case 'error':
        return <AlertCircle className="w-5 h-5 text-[rgb(220,38,38)]" />
      default:
        return <Database className="w-5 h-5 text-[rgb(148,163,184)]" />
    }
  }

  const getStatusText = () => {
    if (isConnecting) return 'Connecting...'

    switch (connection.status) {
      case 'connected':
        return 'Connected'
      case 'error':
        return 'Connection Failed'
      default:
        return 'Disconnected'
    }
  }

  return (
    <div className="w-full max-w-md mx-auto p-6 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl shadow-md">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-[rgb(245,247,250)] rounded-lg">
            <Database className="w-6 h-6 text-[rgb(34,139,34)]" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">
              Database Connection
            </h3>
            <p className="text-sm text-[rgb(100,116,139)]">
              Supabase Client
            </p>
          </div>
        </div>

        {/* Network Status */}
        <div className="flex items-center gap-2">
          {isOnline ? (
            <Wifi className="w-4 h-4 text-[rgb(34,139,34)]" />
          ) : (
            <WifiOff className="w-4 h-4 text-[rgb(220,38,38)]" />
          )}
        </div>
      </div>

      {/* Connection Status */}
      <div className="mb-6 p-4 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
        <div className="flex items-center gap-3 mb-3">
          {getStatusIcon()}
          <span className={`font-medium ${getStatusColor()}`}>
            {getStatusText()}
          </span>
        </div>

        <div className="space-y-2 text-sm text-[rgb(100,116,139)]">
          <div className="flex justify-between">
            <span>Endpoint:</span>
            <span className="font-mono text-xs">{connection.endpoint}</span>
          </div>
          {connection.status === 'connected' && (
            <div className="flex justify-between">
              <span>Last Sync:</span>
              <span>{connection.lastSync.toLocaleTimeString()}</span>
            </div>
          )}
          {retryCount > 0 && (
            <div className="flex justify-between">
              <span>Retry Attempts:</span>
              <span>{retryCount}</span>
            </div>
          )}
        </div>
      </div>

      {/* Connection Actions */}
      <div className="space-y-3">
        {connection.status === 'disconnected' || connection.status === 'error' ? (
          <button
            onClick={handleConnect}
            disabled={isConnecting || !isOnline}
            className="w-full min-h-[44px] px-4 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium transition-all duration-200 hover:bg-[rgb(29,120,29)] disabled:bg-[rgb(148,163,184)] disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 active:scale-95"
            aria-label="Connect to database"
          >
            {isConnecting ? 'Connecting...' : 'Connect'}
          </button>
        ) : (
          <button
            onClick={handleDisconnect}
            className="w-full min-h-[44px] px-4 py-3 bg-[rgb(245,247,250)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)] rounded-lg font-medium transition-all duration-200 hover:bg-[rgb(241,245,249)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 active:scale-95"
            aria-label="Disconnect from database"
          >
            Disconnect
          </button>
        )}

        {!isOnline && (
          <div className="p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
            <p className="text-sm text-[rgb(220,38,38)] text-center">
              No internet connection. Please check your network.
            </p>
          </div>
        )}

        {connection.status === 'error' && retryCount >= 3 && (
          <div className="p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
            <p className="text-sm text-[rgb(220,38,38)] text-center">
              Multiple connection attempts failed. Please try again later.
            </p>
          </div>
        )}
      </div>

      {/* Connection Info */}
      <div className="mt-6 pt-4 border-t border-[rgb(226,232,240)]">
        <div className="grid grid-cols-2 gap-4 text-center">
          <div>
            <div className="text-2xl font-bold text-[rgb(34,139,34)]">
