code.layout:
'use client'

import { useState } from 'react'
import { 
  Map, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  Settings,
  Plus,
  Bell,
  Search,
  Menu,
  X
} from 'lucide-react'

interface AppLayoutProps {
  children?: React.ReactNode;
  activeTab?: string;
  onTabChange?: (tab: string) => void;
  showNotifications?: boolean;
  notificationCount?: number;
}

interface TabItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  href: string;
}

const TABS: TabItem[] = [
  { id: 'trips', label: 'Trips', icon: Map, href: '/trips' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'group', label: 'Group', icon: Users, href: '/group' },
  { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat' },
  { id: 'meals', label: 'Meals', icon: UtensilsCrossed, href: '/meals' }
];

export function AppLayout({
  children,
  activeTab = 'trips',
  onTabChange = () => {},
  showNotifications = true,
  notificationCount = 3
}: AppLayoutProps = {}) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const handleTabClick = (tabId: string) => {
    onTabChange(tabId);
    setIsMenuOpen(false);
  };

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] flex flex-col font-medium">
      {/* Header */}
      <header className="bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3 sticky top-0 z-50">
        <div className="flex items-center justify-between">
          {/* Logo */}
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-lg flex items-center justify-center">
              <Map className="w-5 h-5 text-[rgb(255,255,255)]" />
            </div>
            <h1 className="text-lg font-semibold text-[rgb(15,23,42)]">
              TrailPlan
            </h1>
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-2">
            {/* Search - Hidden on small screens */}
            <div className="hidden sm:flex items-center bg-[rgb(248,250,252)] rounded-lg px-3 py-2 border border-[rgb(226,232,240)]">
              <Search className="w-4 h-4 text-gray-400 mr-2" />
              <input
                type="text"
                placeholder="Search trips..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="bg-transparent text-sm text-[rgb(15,23,42)] placeholder-gray-400 outline-none w-32"
              />
            </div>

            {/* Notifications */}
            {showNotifications && (
              <button 
                className="relative p-2 rounded-lg hover:bg-[rgb(248,250,252)] transition-colors duration-150 touch-manipulation"
                style={{ minWidth: '44px', minHeight: '44px' }}
                aria-label={`Notifications (${notificationCount} unread)`}
              >
                <Bell className="w-5 h-5 text-[rgb(15,23,42)]" />
                {notificationCount > 0 && (
                  <span className="absolute -top-1 -right-1 w-5 h-5 bg-[rgb(220,38,38)] text-white text-xs rounded-full flex items-center justify-center font-medium">
                    {notificationCount > 9 ? '9+' : notificationCount}
                  </span>
                )}
              </button>
            )}

            {/* Menu Toggle - Mobile */}
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="sm:hidden p-2 rounded-lg hover:bg-[rgb(248,250,252)] transition-colors duration-150 touch-manipulation"
              style={{ minWidth: '44px', minHeight: '44px' }}
              aria-label="Toggle menu"
            >
              {isMenuOpen ? (
                <X className="w-5 h-5 text-[rgb(15,23,42)]" />
              ) : (
                <Menu className="w-5 h-5 text-[rgb(15,23,42)]" />
              )}
            </button>
          </div>
        </div>

        {/* Mobile Search - Expanded */}
        <div className="sm:hidden mt-3">
          <div className="flex items-center bg-[rgb(248,250,252)] rounded-lg px-3 py-2 border border-[rgb(226,232,240)]">
            <Search className="w-4 h-4 text-gray-400 mr-2" />
            <input
              type="text"
              placeholder="Search trips, locations, members..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent text-sm text-[rgb(15,23,42)] placeholder-gray-400 outline-none flex-1"
            />
          </div>
        </div>

        {/* Mobile Menu Overlay */}
        {isMenuOpen && (
          <div className="sm:hidden absolute top-full left-0 right-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] shadow-lg">
            <nav className="px-4 py-3">
              <div className="grid grid-cols-2 gap-2">
                {TABS.map((tab) => {
                  const Icon = tab.icon;
                  const isActive = activeTab === tab.id;

                  return (
                    <button
                      key={tab.id}
                      onClick={() => handleTabClick(tab.id)}
                      className={`flex items-center gap-3 p-3 rounded-lg transition-colors duration-150 touch-manipulation ${
                        isActive
                          ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                          : 'text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]'
                      }`}
                      style={{ minHeight: '44px' }}
                    >
                      <Icon className="w-5 h-5" />
                      <span className="font-medium text-sm">{tab.label}</span>
                    </button>
                  );
                })}
              </div>

              {/* Quick Actions */}
              <div className="mt-4 pt-4 border-t border-[rgb(226,232,240)]">
                <button className="w-full flex items-center gap-3 p-3 rounded-lg bg-[rgb(255,140,0)] text-[rgb(255,255,255)] hover:bg-[rgb(255,140,0)]/90 transition-colors duration-150 touch-manipulation">
                  <Plus className="w-5 h-5" />
                  <span className="font-medium text-sm">New Trip</span>
                </button>
              </div>
            </nav>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden">
        {children || (
          <div className="p-4 h-full flex items-center justify-center">
            <div className="text-center">
              <Map className="w-16 h-16 text-[rgb(34,139,34)] mx-auto mb-4" />
              <h2 className="text-xl font-semibold text-[rgb(15,23,42)] mb-2">
                Welcome to TrailPlan
              </h2>
              <p className="text-gray-600 mb-6 max-w-sm">
                Plan your next off-roading adventure with your crew. Organize locations, assign tasks, and coordinate everything in one place.
              </p>
              <button className="px-6 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium shadow-md touch-manipulation">
                Start Planning
              </button>
            </div>
          </div>
        )}
      </main>

      {/* Bottom Navigation - Mobile */}
      <nav className="sm:hidden bg-[rgb(255,255,255)] border-t border-[rgb(226,232,240)] px-2 py-2 safe-area-pb">
        <div className="flex justify-around">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;

            return (
              <button
                key={tab.id}
                onClick={() => handleTabClick(tab.id)}
                className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors duration-150 touch-manipulation ${
                  isActive
                    ? 'text-[rgb(34,139,34)]'
                    : 'text-gray-500 hover:text-[rgb(15,23,42)]'
                }`}
                style={{ minWidth: '44px', minHeight: '44px' }}
                aria-label={tab.label}
              >
                <Icon className="w-5 h-5" />
                <span className="text-xs font-medium">{tab.label}</span>
                {isActive && (
                  <div className="w-1 h-1 bg-[rgb(34,139,34)] rounded-full" />
                )}
              </button>
            );
          })}
        </div>
      </nav>

      {/* Desktop Sidebar - Hidden on mobile */}
      <aside className="hidden sm:block fixed left-0 top-16 bottom-0 w-64 bg-[rgb(255,255,255)] border-r border-[rgb(226,232,240)] overflow-y-auto">
        <div className="p-4">
          {/* Quick Actions */}
          <button className="w-full flex items-center gap-3 p-3 rounded-lg bg-[rgb(255,140,0)] text-[rgb(255,255,255)] hover:bg-[rgb(255,140,0)]/90 transition-colors duration-150 mb-6 font-medium">
            <Plus className="w-5 h-5" />
            New Trip
          </button>

          {/* Navigation */}
          <nav className="space-y-1">
            {TABS.map((tab) => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.id;

              return (
                <button
                  key={tab.id}
                  onClick={() => handleTabClick(tab.id)}
                  className={`w-full flex items-center gap-3 p-3 rounded-lg transition-colors duration-150 ${
                    isActive
                      ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]'
                      : 'text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)]'
                  }`}
                >
                  <Icon className="w-5 h-5" />
                  <span className="font-medium">{tab.label}</span>
                </button>
              );
            })}
          </nav>

          {/* Settings */}
          <div className="mt-8 pt-4 border-t border-[rgb(226,232,240)]">
            <button className="w-full flex items-center gap-3 p-3 rounded-lg text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] transition-colors duration-150">
              <Settings className="w-5 h-5" />
              <span className="font-medium">Settings</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Desktop Main Content Offset */}
      <style jsx>{`
        @media (min-width: 640px) {
          main {
            margin-left: 256px;
          }
        }
      `}</style>
    </div>
  );
}

// Demo component for page.tsx
export default function AppLayoutDemo() {
  const [activeTab, setActiveTab] = useState('trips');

  return (
    <AppLayout 
      activeTab={activeTab}
      onTabChange={setActiveTab}
      showNotifications={true}
      notificationCount={3}
    />
  );
}

