  interactive?: boolean;
}

interface ColorToken {
  name: string;
  value: string;
  description: string;
  usage: string[];
}

interface TypographyToken {
  name: string;
  size: string;
  weight: string;
  usage: string;
}

interface SpacingToken {
  name: string;
  value: string;
  pixels: string;
  usage: string;
}

export function DesignSystem({
