    { name: 'sm', value: '0.5rem', pixels: '8px', usage: 'Component padding, small gaps' },
    { name: 'md', value: '1rem', pixels: '16px', usage: 'Standard spacing, card padding' },
    { name: 'lg', value: '1.5rem', pixels: '24px', usage: 'Section spacing, large padding' },
    { name: 'xl', value: '2rem', pixels: '32px', usage: 'Page margins, major sections' },
    { name: '2xl', value: '3rem', pixels: '48px', usage: 'Hero sections, major spacing' }
  ]

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text)
  }

  const renderColorSection = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {colorTokens.map((token) => (
