            <span className="text-sm text-gray-600">Code Font</span>
          </div>
        </div>
      </div>

      <div className="grid gap-4">
        {typographyTokens.map((token) => (
          <div
            key={token.name}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 hover:shadow-md transition-shadow duration-200"
