                fontWeight: token.weight,
                fontFamily: 'Inter, system-ui, sans-serif'
              }}
            >
              The quick brown fox jumps over the lazy dog
            </p>
            <p className="text-sm text-gray-600">{token.usage}</p>
          </div>
        ))}
      </div>
    </div>
  )

  const renderSpacingSection = () => (
    <div className="space-y-6">
      <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6">
        <h3 className="font-semibold text-[rgb(15,23,42)] mb-4">Spacing Scale (8px base unit)</h3>
        <div className="space-y-4">
