'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageCircle, Plus, Search, Filter, ChevronRight, Star, Clock, Navigation } from 'lucide-react'

interface Trip {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  participants: number
  maxParticipants: number
  status: 'upcoming' | 'active' | 'completed'
  difficulty: 'easy' | 'moderate' | 'hard'
  distance: string
  duration: string
  imageUrl: string
  description: string
  organizer: string
  tags: string[]
  rsvpCount: number
  unreadMessages: number
  weatherCondition: 'sunny' | 'cloudy' | 'rainy' | 'snowy'
  isFavorite: boolean
}

interface TripListProps {
  trips?: Trip[]
  onTripSelect?: (trip: Trip) => void
  onCreateTrip?: () => void
  searchQuery?: string
  filterStatus?: string
}

export function TripList({
  trips = DEFAULT_TRIPS,
  onTripSelect = (trip) => console.log('Selected trip:', trip.title),
  onCreateTrip = () => console.log('Create new trip'),
  searchQuery = '',
  filterStatus = 'all'
}: TripListProps = {}) {
  const [filteredTrips, setFilteredTrips] = useState<Trip[]>(trips)
  const [searchTerm, setSearchTerm] = useState(searchQuery)
  const [activeFilter, setActiveFilter] = useState(filterStatus)
  const [isLoading, setIsLoading] = useState(false)
  const [favorites, setFavorites] = useState<Set<string>>(new Set())

  useEffect(() => {
    setIsLoading(true)
    const timer = setTimeout(() => {
      let filtered = trips

      // Apply search filter
      if (searchTerm) {
        filtered = filtered.filter(trip =>
          trip.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          trip.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
          trip.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
        )
      }

      // Apply status filter
      if (activeFilter !== 'all') {
        filtered = filtered.filter(trip => trip.status === activeFilter)
      }

      setFilteredTrips(filtered)
      setIsLoading(false)
    }, 300)

    return () => clearTimeout(timer)
  }, [searchTerm, activeFilter, trips])

  const toggleFavorite = (tripId: string) => {
    setFavorites(prev => {
      const newFavorites = new Set(prev)
      if (newFavorites.has(tripId)) {
        newFavorites.delete(tripId)
      } else {
        newFavorites.add(tripId)
      }
      return newFavorites
    })
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'upcoming': return 'bg-[rgb(34,139,34)] text-white'
      case 'active': return 'bg-[rgb(255,140,0)] text-white'
      case 'completed': return 'bg-[rgb(226,232,240)] text-[rgb(15,23,42)]'
      default: return 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-green-100 text-green-700 border-green-200'
      case 'moderate': return 'bg-yellow-100 text-yellow-700 border-yellow-200'
      case 'hard': return 'bg-red-100 text-red-700 border-red-200'
      default: return 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return '☀️'
      case 'cloudy': return '☁️'
      case 'rainy': return '🌧️'
      case 'snowy': return '❄️'
      default: return '☀️'
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric',
      year: date.getFullYear() !== new Date().getFullYear() ? 'numeric' : undefined
    })
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Off-Road Trips</h1>
          <button
            onClick={onCreateTrip}
            className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium text-sm shadow-md active:scale-95"
            aria-label="Create new trip"
          >
            <Plus className="w-4 h-4" />
            New Trip
          </button>
        </div>

        {/* Search and Filter */}
        <div className="space-y-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search trips, locations, or tags..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
              aria-label="Search trips"
            />
          </div>

          <div className="flex gap-2 overflow-x-auto pb-1">
            {['all', 'upcoming', 'active', 'completed'].map((filter) => (
              <button
                key={filter}
                onClick={() => setActiveFilter(filter)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors duration-150 ${
                  activeFilter === filter
                    ? 'bg-[rgb(34,139,34)] text-white'
                    : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(226,232,240)]'
                }`}
                aria-label={`Filter by ${filter} trips`}
              >
                {filter.charAt(0).toUpperCase() + filter.slice(1)}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Trip List */}
      <div className="px-4 py-4">
        {isLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-[rgb(248,250,252)] rounded-xl p-4 animate-pulse">
                <div className="flex gap-4">
                  <div className="w-20 h-20 bg-[rgb(226,232,240)] rounded-lg"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-[rgb(226,232,240)] rounded w-3/4"></div>
                    <div className="h-3 bg-[rgb(226,232,240)] rounded w-1/2"></div>
                    <div className="h-3 bg-[rgb(226,232,240)] rounded w-2/3"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : filteredTrips.length === 0 ? (
          <div className="text-center py-12">
            <Navigation className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No trips found</h3>
            <p className="text-gray-500 mb-6">
              {searchTerm ? 'Try adjusting your search terms' : 'Start planning your first off-road adventure!'}
            </p>
            <button
              onClick={onCreateTrip}
              className="px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium shadow-md active:scale-95"
            >
              Create Your First Trip
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredTrips.map((trip) => (
              <div
                key={trip.id}
                onClick={() => onTripSelect(trip)}
                className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 hover:border-[rgb(34,139,34)]/50 transition-all duration-200 shadow-sm hover:shadow-md cursor-pointer active:scale-[0.98]"
                role="button"
                tabIndex={0}
                aria-label={`View trip: ${trip.title}`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onTripSelect(trip)
                  }
                }}
              >
                <div className="flex gap-4">
                  {/* Trip Image */}
                  <div className="relative">
                    <div 
                      className="w-20 h-20 bg-gradient-to-br from-[rgb(34,139,34)] to-[rgb(255,140,0)] rounded-lg flex items-center justify-center text-white text-2xl font-bold"
                      style={{
                        backgroundImage: trip.imageUrl ? `url(${trip.imageUrl})` : undefined,
                        backgroundSize: 'cover',
                        backgroundPosition: 'center'
                      }}
                    >
                      {!trip.imageUrl && trip.title.charAt(0).toUpperCase()}
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation()
                        toggleFavorite(trip.id)
                      }}
                      className="absolute -top-1 -right-1 w-6 h-6 bg-white rounded-full shadow-md flex items-center justify-center hover:scale-110 transition-transform duration-150"
                      aria-label={favorites.has(trip.id) ? 'Remove from favorites' : 'Add to favorites'}
                    >
                      <Star 
                        className={`w-3 h-3 ${
                          favorites.has(trip.id) || trip.isFavorite
                            ? 'text-[rgb(255,140,0)] fill-current' 
                            : 'text-gray-400'
                        }`} 
                      />
                    </button>
                  </div>

                  {/* Trip Details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="font-semibold text-[rgb(15,23,42)] text-lg leading-tight truncate pr-2">
                        {trip.title}
                      </h3>
                      <ChevronRight className="w-5 h-5 text-gray-400 flex-shrink-0" />
                    </div>

                    <div className="flex items-center gap-2 mb-2">
                      <MapPin className="w-4 h-4 text-gray-500" />
                      <span className="text-sm text-gray-600 truncate">{trip.location}</span>
                      <span className="text-lg">{getWeatherIcon(trip.weatherCondition)}</span>
                    </div>

                    <div className="flex items-center gap-2 mb-3">
                      <Calendar className="w-4 h-4 text-gray-500" />
                      <span className="text-sm text-gray-600">
                        {formatDate(trip.startDate)} - {formatDate(trip.endDate)}
                      </span>
                    </div>

                    {/* Status and Difficulty Badges */}
                    <div className="flex items-center gap-2 mb-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(trip.status)}`}>
                        {trip.status.charAt(0).toUpperCase() + trip.status.slice(1)}
                      </span>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getDifficultyColor(trip.difficulty)}`}>
                        {trip.difficulty.charAt(0).toUpperCase() + trip.difficulty.slice(1)}
                      </span>
                    </div>

                    {/* Trip Stats */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4 text-sm text-gray-600">
                        <div className="flex items-center gap-1">
                          <Users className="w-4 h-4" />
                          <span>{trip.participants}/{trip.maxParticipants}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          <span>{trip.duration}</span>
                        </div>
                      </div>

                      {trip.unreadMessages > 0 && (
                        <div className="flex items-center gap-1">
                          <MessageCircle className="w-4 h-4 text-[rgb(255,140,0)]" />
                          <span className="bg-[rgb(255,140,0)] text-white text-xs font-medium px-2 py-1 rounded-full min-w-[20px] text-center">
                            {trip.unreadMessages}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

