const DEFAULT_RECIPIENTS: EmailRecipient[] = [
  { id: '1', name: 'Sarah Johnson', email: 'sarah@example.com', status: 'pending' },
  { id: '2', name: 'Mike Chen', email: 'mike@example.com', status: 'sent', sentAt: new Date() },
  { id: '3', name: 'Alex Rivera', email: 'alex@example.com', status: 'delivered', sentAt: new Date() },
  { id: '4', name: 'Emma Davis', email: 'emma@example.com', status: 'failed', sentAt: new Date() }
]

export function ResendEmailService({
  tripData = DEFAULT_TRIP_DATA,
  recipients = DEFAULT_RECIPIENTS,
  onEmailSent = () => console.log('Email sent'),
  onTemplateSelect = () => console.log('Template selected')
}: ResendEmailServiceProps = {}) {
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate>(DEFAULT_TEMPLATES[0])
  const [emailRecipients, setEmailRecipients] = useState<EmailRecipient[]>(recipients)
  const [isSending, setIsSending] = useState(false)
  const [sendingProgress, setSendingProgress] = useState(0)
  const [customSubject, setCustomSubject] = useState('')
  const [customContent, setCustomContent] = useState('')
  const [showPreview, setShowPreview] = useState(false)

  useEffect(() => {
    setCustomSubject(selectedTemplate.subject)
    setCustomContent(selectedTemplate.content)
  }, [selectedTemplate])

  const replaceTemplateVariables = (text: string): string => {
    return text
      .replace(/{{tripName}}/g, tripData.tripName)
      .replace(/{{location}}/g, tripData.location)
      .replace(/{{startDate}}/g, tripData.startDate.toLocaleDateString())
      .replace(/{{endDate}}/g, tripData.endDate.toLocaleDateString())
      .replace(/{{organizer}}/g, tripData.organizer)
  }

  const handleSendEmails = async () => {
    setIsSending(true)
    setSendingProgress(0)

    const pendingRecipients = emailRecipients.filter(r => r.status === 'pending')

    for (let i = 0; i < pendingRecipients.length; i++) {
      const recipient = pendingRecipients[i]

      // Simulate email sending delay
      await new Promise(resolve => setTimeout(resolve, 1000))

      // Simulate success/failure (90% success rate)
      const success = Math.random() > 0.1

      setEmailRecipients(prev => prev.map(r => 
        r.id === recipient.id 
          ? { ...r, status: success ? 'sent' : 'failed', sentAt: new Date() }
          : r
      ))

      onEmailSent(recipient.id, success)
      setSendingProgress(((i + 1) / pendingRecipients.length) * 100)
    }

    setIsSending(false)
    setSendingProgress(0)
  }

  const handleRetryFailed = async () => {
    const failedRecipients = emailRecipients.filter(r => r.status === 'failed')

    setEmailRecipients(prev => prev.map(r => 
      r.status === 'failed' ? { ...r, status: 'pending' } : r
    ))
  }

  const getStatusIcon = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'pending':
        return <Clock className="w-4 h-4 text-[rgb(255,140,0)]" />
      case 'sent':
        return <Send className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
    }
  }

  const getStatusColor = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'pending':
        return 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)] border-[rgb(255,140,0)]/20'
      case 'sent':
        return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'delivered':
        return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'failed':
        return 'bg-[rgb(220,38,38)]/10 text-[rgb(220,38,38)] border-[rgb(220,38,38)]/20'
    }
  }

  const pendingCount = emailRecipients.filter(r => r.status === 'pending').length
  const sentCount = emailRecipients.filter(r => r.status === 'sent' || r.status === 'delivered').length
  const failedCount = emailRecipients.filter(r => r.status === 'failed').length

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Header */}
        <div className="bg-[rgb(248,250,252)] rounded-xl p-6 border border-[rgb(226,232,240)]">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-[rgb(34,139,34)] rounded-lg">
              <Mail className="w-6 h-6 text-[rgb(255,255,255)]" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-[rgb(15,23,42)]">Email Service</h1>
              <p className="text-sm text-[rgb(15,23,42)]/60">Send trip invitations and updates</p>
            </div>
          </div>

          {/* Trip Info */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4 text-[rgb(34,139,34)]" />
              <span className="text-sm text-[rgb(15,23,42)]">{tripData.location}</span>
            </div>
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-[rgb(34,139,34)]" />
              <span className="text-sm text-[rgb(15,23,42)]">
                {tripData.startDate.toLocaleDateString()} - {tripData.endDate.toLocaleDateString()}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Users className="w-4 h-4 text-[rgb(34,139,34)]" />
              <span className="text-sm text-[rgb(15,23,42)]">{emailRecipients.length} recipients</span>
            </div>
          </div>
        </div>

        {/* Email Stats */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(255,140,0)]">{pendingCount}</div>
            <div className="text-sm text-[rgb(15,23,42)]/60">Pending</div>
          </div>
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(34,139,34)]">{sentCount}</div>
            <div className="text-sm text-[rgb(15,23,42)]/60">Sent</div>
          </div>
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(220,38,38)]">{failedCount}</div>
            <div className="text-sm text-[rgb(15,23,42)]/60">Failed</div>
          </div>
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(15,23,42)]">{emailRecipients.length}</div>
            <div className="text-sm text-[rgb(15,23,42)]/60">Total</div>
          </div>
        </div>

        {/* Template Selection */}
        <div className="bg-[rgb(248,250,252)] rounded-xl p-6 border border-[rgb(226,232,240)]">
          <h2 className="text-lg font-bold text-[rgb(15,23,42)] mb-4">Email Template</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
            {DEFAULT_TEMPLATES.map((template) => (
              <button
                key={template.id}
                onClick={() => {
                  setSelectedTemplate(template)
                  onTemplateSelect(template)
                }}
                className={`p-4 rounded-lg border text-left transition-all duration-200 ${
                  selectedTemplate.id === template.id
                    ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5'
                    : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(34,139,34)]/50'
                }`}
              >
                <div className="font-semibold text-[rgb(15,23,42)] mb-1">{template.name}</div>
                <div className="text-sm text-[rgb(15,23,42)]/60 capitalize">{template.type}</div>
              </button>
            ))}
          </div>

          {/* Custom Subject */}
          <div className="space-y-3">
            <label className="block text-sm font-semibold text-[rgb(15,23,42)]">Subject Line</label>
            <input
              type="text"
              value={customSubject}
              onChange={(e) => setCustomSubject(e.target.value)}
              className="w-full px-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)]/40 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200"
              placeholder="Enter email subject..."
            />
          </div>

          {/* Custom Content */}
          <div className="space-y-3 mt-4">
            <label className="block text-sm font-semibold text-[rgb(15,23,42)]">Email Content</label>
            <textarea
              value={customContent}
              onChange={(e) => setCustomContent(e.target.value)}
              rows={4}
              className="w-full px-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)]/40 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200 resize-none"
              placeholder="Enter email content..."
            />
          </div>

          {/* Preview Toggle */}
          <button
            onClick={() => setShowPreview(!showPreview)}
            className="mt-4 px-4 py-2 bg-[rgb(245,247,250)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(226,232,240)] transition-colors duration-200 text-sm font-medium"
          >
            {showPreview ? 'Hide Preview' : 'Show Preview'}
          </button>

          {/* Email Preview */}
          {showPreview && (
            <div className="mt-4 p-4 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg">
              <div className="text-sm font-semibold text-[rgb(15,23,42)] mb-2">Preview:</div>
              <div className="text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Subject: {replaceTemplateVariables(customSubject)}
              </div>
              <div className="text-sm text-[rgb(15,23,42)]/80 whitespace-pre-wrap">
                {replaceTemplateVariables(customContent)}
              </div>
            </div>
          )}
        </div>

        {/* Recipients List */}
        <div className="bg-[rgb(248,250,252)] rounded-xl p-6 border border-[rgb(226,232,240)]">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-[rgb(15,23,42)]">Recipients</h2>
            {failedCount > 0 && (
              <button
                onClick={handleRetryFailed}
                className="px-3 py-1.5 bg-[rgb(220,38,38)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(220,38,38)]/90 transition-colors duration-200 text-sm font-medium"
              >
                Retry Failed
              </button>
            )}
          </div>

          <div className="space-y-3">
            {emailRecipients.map((recipient) => (
              <div
                key={recipient.id}
                className="flex items-center justify-between p-4 bg-[rgb(255,255,255)] rounded-lg border border-[rgb(226,232,240)]"
              >
                <div className="flex items-center gap-3">
                  {getStatusIcon(recipient.status)}
                  <div>
                    <div className="font-medium text-[rgb(15,23,42)]">{recipient.name}</div>
                    <div className="text-sm text-[rgb(15,23,42)]/60">{recipient.email}</div>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  {recipient.sentAt && (
                    <div className="text-xs text-[rgb(15,23,42)]/60">
                      {recipient.sentAt.toLocaleTimeString()}
                    </div>
                  )}
                  <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(recipient.status)}`}>
                    {recipient.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Send Button */}
        <div className="sticky bottom-4">
          <button
            onClick={handleSendEmails}
            disabled={isSending || pendingCount === 0}
            className="w-full px-6 py-4 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-xl hover:bg-[rgb(34,139,34)]/90 transition-all duration-200 font-semibold text-lg shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
          >
            {isSending ? (
              <>
                <div className="w-5 h-5 border-2 border-[rgb(255,255,255)]/30 border-t-[rgb(255,255,255)] rounded-full animate-spin" />
                Sending... {Math.round(sendingProgress)}%
              </>
            ) : (
              <>
                <Send className="w-5 h-5" />
                Send to {pendingCount} Recipients
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

export default function ResendEmailServiceDemo() {
  return <ResendEmailService />
}

