                    className="w-full p-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                  />
                ) : (
                  <div className="p-3 bg-[#f8fafb] rounded-lg">
                    <span className="text-[#0f172a]">{profileData.emergencyContact.phone}</span>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0f172a] mb-2">Relationship</label>
                {isEditing ? (
                  <select
                    value={profileData.emergencyContact.relationship}
                    onChange={(e) => updateEmergencyContact('relationship', e.target.value)}
                    className="w-full p-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                  >
                    <option value="spouse">Spouse</option>
                    <option value="parent">Parent</option>
                    <option value="sibling">Sibling</option>
                    <option value="friend">Friend</option>
                    <option value="other">Other</option>
                  </select>
                ) : (
                  <div className="p-3 bg-[#f8fafb] rounded-lg">
                    <span className="text-[#0f172a] capitalize">{profileData.emergencyContact.relationship}</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'preferences' && (
          <div className="space-y-6">
            <div className="bg-[#ffffff] rounded-xl border border-[#e2e8f0] p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[#0f172a] mb-4">Notifications</h3>
              <div className="space-y-4">
                {[
                  { key: 'notifications', label: 'Push Notifications', icon: Bell },
                  { key: 'emailUpdates', label: 'Email Updates', icon: Mail },
                  { key: 'publicProfile', label: 'Public Profile', icon: Globe }
                ].map(({ key, label, icon: Icon }) => (
                  <div key={key} className="flex items-center justify-between p-3 bg-[#f8fafb] rounded-lg">
                    <div className="flex items-center gap-3">
                      <Icon size={16} className="text-[#64748b]" />
                      <span className="text-[#0f172a] font-medium">{label}</span>
                    </div>
                    <button
                      onClick={() => updatePreference(key, !profileData.preferences[key as keyof typeof profileData.preferences])}
                      className={`relative w-12 h-6 rounded-full transition-colors duration-200 ${
                        profileData.preferences[key as keyof typeof profileData.preferences]
                          ? 'bg-[#228b22]'
                          : 'bg-[#e2e8f0]'
                      }`}
                      aria-label={`Toggle ${label}`}
                    >
                      <div
                        className={`absolute top-0.5 w-5 h-5 bg-white rounded-full transition-transform duration-200 ${
                          profileData.preferences[key as keyof typeof profileData.preferences]
                            ? 'translate-x-6'
                            : 'translate-x-0.5'
                        }`}
                      />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-[#ffffff] rounded-xl border border-[#e2e8f0] p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[#0f172a] mb-4">Appearance</h3>
              <div className="flex items-center justify-between p-3 bg-[#f8fafb] rounded-lg">
                <div className="flex items-center gap-3">
                  {profileData.preferences.darkMode ? (
                    <Moon size={16} className="text-[#64748b]" />
                  ) : (
                    <Sun size={16} className="text-[#64748b]" />
                  )}
                  <span className="text-[#0f172a] font-medium">Dark Mode</span>
                </div>
                <button
                  onClick={() => updatePreference('darkMode', !profileData.preferences.darkMode)}
                  className={`relative w-12 h-6 rounded-full transition-colors duration-200 ${
                    profileData.preferences.darkMode ? 'bg-[#228b22]' : 'bg-[#e2e8f0]'
                  }`}
                  aria-label="Toggle dark mode"
                >
                  <div
                    className={`absolute top-0.5 w-5 h-5 bg-white rounded-full transition-transform duration-200 ${
                      profileData.preferences.darkMode ? 'translate-x-6' : 'translate-x-0.5'
                    }`}
                  />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Save Button */}
      {isEditing && (
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-[#ffffff] border-t border-[#e2e8f0] z-20">
          <button
            onClick={handleSave}
            disabled={isSaving}
            className="w-full flex items-center justify-center gap-2 p-4 bg-[#228b22] text-[#ffffff] rounded-xl font-semibold hover:bg-[#1e7a1e] transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
          >
            {isSaving ? (
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            ) : (
              <Save size={20} />
            )}
            {isSaving ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      )}
    </div>
  )
}

