code.database-schema:
'use client'

import { useState, useEffect } from 'react'
import { MapPin, Star, Compass, Mountain, TreePine, Waves, Calendar, Users, AlertTriangle } from 'lucide-react'

// TypeScript interfaces
interface Location {
  id: string
  name: string
  coordinates: {
    latitude: number
    longitude: number
  }
  address: string
  description: string
  terrain_type: 'mountain' | 'desert' | 'forest' | 'beach' | 'plains' | 'canyon'
  difficulty_level: 'beginner' | 'intermediate' | 'advanced' | 'expert'
  features: string[]
  amenities: string[]
  restrictions: string[]
  best_season: string[]
  weather_conditions: {
    temperature_range: {
      min: number
      max: number
    }
    precipitation_chance: number
    wind_speed: number
  }
  accessibility: {
    vehicle_requirements: string[]
    permits_required: boolean
    fees: number | null
  }
  safety_notes: string[]
  images: string[]
  rating: number
  review_count: number
  created_at: string
  updated_at: string
  created_by: string
  is_favorite: boolean
  last_visited: string | null
  visit_count: number
  tags: string[]
}

interface LocationSchemaProps {
  locations?: Location[]
  onLocationSelect?: (location: Location) => void
  onLocationSave?: (location: Location) => void
  onLocationDelete?: (locationId: string) => void
  showFavoritesOnly?: boolean
  filterByDifficulty?: string[]
  filterByTerrain?: string[]
}

const TERRAIN_ICONS = {
  mountain: Mountain,
  desert: Compass,
  forest: TreePine,
  beach: Waves,
  plains: MapPin,
  canyon: Mountain
}

const DIFFICULTY_COLORS = {
  beginner: 'bg-[#22c55e] text-white',
  intermediate: 'bg-[#f59e0b] text-white',
  advanced: 'bg-[#ef4444] text-white',
  expert: 'bg-[#7c2d12] text-white'
}

export function LocationSchema({
  locations = DEFAULT_LOCATIONS,
  onLocationSelect = () => console.log('Location selected'),
  onLocationSave = () => console.log('Location saved'),
  onLocationDelete = () => console.log('Location deleted'),
  showFavoritesOnly = false,
  filterByDifficulty = [],
  filterByTerrain = []
}: LocationSchemaProps = {}) {
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(locations)
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    let filtered = locations

    // Apply favorites filter
    if (showFavoritesOnly) {
      filtered = filtered.filter(location => location.is_favorite)
    }

    // Apply difficulty filter
    if (filterByDifficulty.length > 0) {
      filtered = filtered.filter(location => 
        filterByDifficulty.includes(location.difficulty_level)
      )
    }

    // Apply terrain filter
    if (filterByTerrain.length > 0) {
      filtered = filtered.filter(location => 
        filterByTerrain.includes(location.terrain_type)
      )
    }

    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter(location =>
        location.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        location.address.toLowerCase().includes(searchTerm.toLowerCase()) ||
        location.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
      )
    }

    setFilteredLocations(filtered)
  }, [locations, showFavoritesOnly, filterByDifficulty, filterByTerrain, searchTerm])

  const handleLocationClick = (location: Location) => {
    setSelectedLocation(location)
    onLocationSelect(location)
  }

  const handleSaveLocation = (location: Location) => {
    setIsLoading(true)
    setTimeout(() => {
      onLocationSave(location)
      setIsLoading(false)
    }, 500)
  }

  const toggleFavorite = (locationId: string) => {
    const updatedLocations = locations.map(location =>
      location.id === locationId
        ? { ...location, is_favorite: !location.is_favorite }
        : location
    )
    setFilteredLocations(updatedLocations)
  }

  const renderLocationCard = (location: Location) => {
    const TerrainIcon = TERRAIN_ICONS[location.terrain_type]

    return (
      <div
        key={location.id}
        className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-md hover:shadow-lg transition-all duration-200 cursor-pointer active:scale-95"
        onClick={() => handleLocationClick(location)}
        role="button"
        tabIndex={0}
        aria-label={`Select ${location.name} location`}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            handleLocationClick(location)
          }
        }}
      >
        {/* Header */}
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-[#f8fafc] rounded-lg">
              <TerrainIcon className="w-5 h-5 text-[#228b22]" />
            </div>
            <div>
              <h3 className="font-semibold text-[#0f172a] text-lg">{location.name}</h3>
              <p className="text-sm text-gray-600">{location.address}</p>
            </div>
          </div>
          <button
            onClick={(e) => {
              e.stopPropagation()
              toggleFavorite(location.id)
            }}
            className="p-2 hover:bg-[#f8fafc] rounded-lg transition-colors duration-150"
            aria-label={location.is_favorite ? 'Remove from favorites' : 'Add to favorites'}
          >
            <Star
              className={`w-5 h-5 ${
                location.is_favorite
                  ? 'text-[#ff8c00] fill-current'
                  : 'text-gray-400'
              }`}
            />
          </button>
        </div>

        {/* Difficulty and Rating */}
        <div className="flex items-center gap-3 mb-4">
          <span
            className={`px-3 py-1 rounded-full text-xs font-medium ${
              DIFFICULTY_COLORS[location.difficulty_level]
            }`}
          >
            {location.difficulty_level.charAt(0).toUpperCase() + location.difficulty_level.slice(1)}
          </span>
          <div className="flex items-center gap-1">
            <Star className="w-4 h-4 text-[#ff8c00] fill-current" />
            <span className="text-sm font-medium text-[#0f172a]">
              {location.rating.toFixed(1)}
            </span>
            <span className="text-sm text-gray-500">
              ({location.review_count})
            </span>
          </div>
        </div>

        {/* Description */}
        <p className="text-sm text-gray-600 mb-4 line-clamp-2">
          {location.description}
        </p>

        {/* Features */}
        <div className="flex flex-wrap gap-2 mb-4">
          {location.features.slice(0, 3).map((feature, index) => (
            <span
              key={index}
              className="px-2 py-1 bg-[#f8fafc] text-[#228b22] rounded text-xs font-medium border border-[#e2e8f0]"
            >
              {feature}
            </span>
          ))}
          {location.features.length > 3 && (
            <span className="px-2 py-1 bg-[#f8fafc] text-gray-500 rounded text-xs">
              +{location.features.length - 3} more
            </span>
          )}
        </div>

        {/* Weather Info */}
        <div className="flex items-center justify-between text-sm text-gray-600">
          <div className="flex items-center gap-2">
            <span>
              {location.weather_conditions.temperature_range.min}°-
              {location.weather_conditions.temperature_range.max}°F
            </span>
          </div>
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4" />
            <span>Last visited: {location.last_visited || 'Never'}</span>
          </div>
        </div>

        {/* Safety Warnings */}
        {location.safety_notes.length > 0 && (
          <div className="mt-3 p-3 bg-[#fef3cd] border border-[#fbbf24] rounded-lg">
            <div className="flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-[#f59e0b]" />
              <span className="text-sm font-medium text-[#92400e]">
                Safety Notes
              </span>
            </div>
            <p className="text-sm text-[#92400e] mt-1">
              {location.safety_notes[0]}
            </p>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-[#0f172a] mb-2">
            Off-Road Locations
          </h1>
          <p className="text-gray-600">
            Discover and save your favorite off-roading destinations
          </p>
        </div>

        {/* Search and Filters */}
        <div className="mb-6">
          <div className="relative">
            <MapPin className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search locations, features, or tags..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-white border border-[#e2e8f0] rounded-xl text-[#0f172a] placeholder-gray-400 focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
              aria-label="Search locations"
            />
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          <div className="bg-white border border-[#e2e8f0] rounded-xl p-4 text-center shadow-sm">
            <div className="text-2xl font-bold text-[#228b22]">
              {filteredLocations.length}
            </div>
            <div className="text-sm text-gray-600">Total Locations</div>
          </div>
          <div className="bg-white border border-[#e2e8f0] rounded-xl p-4 text-center shadow-sm">
            <div className="text-2xl font-bold text-[#ff8c00]">
              {filteredLocations.filter(l => l.is_favorite).length}
            </div>
            <div className="text-sm text-gray-600">Favorites</div>
          </div>
          <div className="bg-white border border-[#e2e8f0] rounded-xl p-4 text-center shadow-sm">
            <div className="text-2xl font-bold text-[#228b22]">
              {filteredLocations.filter(l => l.last_visited).length}
            </div>
            <div className="text-sm text-gray-600">Visited</div>
          </div>
          <div className="bg-white border border-[#e2e8f0] rounded-xl p-4 text-center shadow-sm">
            <div className="text-2xl font-bold text-[#0f172a]">
              {Math.round(filteredLocations.reduce((acc, l) => acc + l.rating, 0) / filteredLocations.length * 10) / 10 || 0}
            </div>
            <div className="text-sm text-gray-600">Avg Rating</div>
          </div>
        </div>

        {/* Location Grid */}
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(6)].map((_, index) => (
              <div
                key={index}
                className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-sm animate-pulse"
              >
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-10 h-10 bg-[#f8fafc] rounded-lg"></div>
                  <div className="flex-1">
                    <div className="h-5 bg-[#f8fafc] rounded mb-2"></div>
                    <div className="h-4 bg-[#f8fafc] rounded w-3/4"></div>
                  </div>
                </div>
                <div className="h-4 bg-[#f8fafc] rounded mb-4"></div>
                <div className="h-4 bg-[#f8fafc] rounded mb-4 w-1/2"></div>
                <div className="flex gap-2">
                  <div className="h-6 bg-[#f8fafc] rounded w-16"></div>
                  <div className="h-6 bg-[#f8fafc] rounded w-16"></div>
                </div>
              </div>
            ))}
          </div>
        ) : filteredLocations.length === 0 ? (
          <div className="text-center py-12">
            <MapPin className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-[#0f172a] mb-2">
              No locations found
            </h3>
            <p className="text-gray-600 mb-6">
              Try adjusting your search or filters to find locations
            </p>
            <button
              onClick={() => {
                setSearchTerm('')
                setFilteredLocations(locations)
              }}
              className="px-6 py-3 bg-[#228b22] text-white rounded-xl hover:bg-[#1e7b1e] transition-colors duration-150 font-medium shadow-md hover:shadow-lg active:scale-95"
            >
              Clear Filters
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredLocations.map(renderLocationCard)}
          </div>
        )}

        {/* Selected Location Details Modal */}
        {selectedLocation && (
          <div className="fixed inset-0 bg-black/50 flex items-end sm:items-center justify-center z-50 p-4">
            <div className="bg-white rounded-t-2xl sm:rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
              <div className="p-6">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-2xl font-bold text-[#0f172a]">
                    {selectedLocation.name}
                  </h2>
                  <button
                    onClick={() => setSelectedLocation(null)}
                    className="p-2 hover:bg-[#f8fafc] rounded-lg transition-colors duration-150"
                    aria-label="Close location details"
                  >
                    ✕
                  </button>
                </div>

                <div className="space-y-6">
                  {/* Basic Info */}
                  <div>
                    <h3 className="font-semibold text-[#0f172a] mb-3">Location Details</h3>
                    <div className="space-y-2 text-sm">
                      <p><strong>Address:</strong> {selectedLocation.address}</p>
                      <p><strong>Coordinates:</strong> {selectedLocation.coordinates.latitude}, {selectedLocation.coordinates.longitude}</p>
                      <p><strong>Terrain:</strong> {selectedLocation.terrain_type}</p>
                      <p><strong>Difficulty:</strong> {selectedLocation.difficulty_level}</p>
                    </div>
                  </div>

                  {/* Features */}
                  <div>
                    <h3 className="font-semibold text-[#0f172a] mb-3">Features</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedLocation.features.map((feature, index) => (
                        <span
                          key={index}
                          className="px-3 py-1 bg-[#f8fafc] text-[#228b22] rounded-full text-sm border border-[#e2e8f0]"
                        >
                          {feature}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Safety Notes */}
                  {selectedLocation.safety_notes.length > 0 && (
                    <div>
                      <h3 className="font-semibold text-[#0f172a] mb-3 flex items-center gap-2">
                        <AlertTriangle className="w-5 h-5 text-[#f59e0b]" />
                        Safety Information
                      </h3>
                      <ul className="space-y-2">
                        {selectedLocation.safety_notes.map((note, index) => (
                          <li key={index} className="text-sm text-[#92400e] bg-[#fef3cd] p-3 rounded-lg border border-[#fbbf24]">
                            {note}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {/* Actions */}
                  <div className="flex gap-3 pt-4">
                    <button
                      onClick={() => handleSaveLocation(selectedLocation)}
                      className="flex-1 px-6 py-3 bg-[#228b22] text-white rounded-xl hover:bg-[#1e7b1e] transition-colors duration-150 font-medium shadow-md hover:shadow-lg active:scale-95"
                    >
                      Save Location
                    </button>
                    <button
                      onClick={() => toggleFavorite(selectedLocation.id)}
                      className="px-6 py-3 bg-[#f8fafc] text-[#228b22] rounded-xl hover:bg-[#f1f5f9] transition-colors duration-150 font-medium border border-[#e2e8f0]"
                    >
                      {selectedLocation.is_favorite ? 'Remove Favorite' : 'Add Favorite'}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// Mock data for demo
