'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, ChefHat, Plus, Edit3, Trash2, Save, X } from 'lucide-react'

interface MealItem {
  id: string
  name: string
  description: string
  servings: number
  prepTime: number
  cookTime: number
  difficulty: 'Easy' | 'Medium' | 'Hard'
  ingredients: string[]
  instructions: string[]
  dietaryTags: string[]
  assignedTo?: string
  cost?: number
}

interface MealPlan {
  id: string
  tripId: string
  day: string
  mealType: 'Breakfast' | 'Lunch' | 'Dinner' | 'Snack'
  scheduledTime: string
  meal: MealItem
  servingCount: number
  notes?: string
}

interface MealMenuSchemaProps {
  tripId?: string
  initialMeals?: MealPlan[]
  groupMembers?: Array<{ id: string; name: string }>
  onMealUpdate?: (meals: MealPlan[]) => void
  readOnly?: boolean
}

export function MealMenuSchema({
  tripId = 'trip-1',
  initialMeals = DEFAULT_MEALS,
  groupMembers = DEFAULT_MEMBERS,
  onMealUpdate = () => console.log('Meal updated'),
  readOnly = false
}: MealMenuSchemaProps = {}) {
  const [meals, setMeals] = useState<MealPlan[]>(initialMeals)
  const [editingMeal, setEditingMeal] = useState<string | null>(null)
  const [showAddMeal, setShowAddMeal] = useState(false)
  const [selectedDay, setSelectedDay] = useState<string>('Day 1')
  const [newMeal, setNewMeal] = useState<Partial<MealPlan>>({
    day: 'Day 1',
    mealType: 'Breakfast',
    scheduledTime: '08:00',
    servingCount: 4
  })

  const days = ['Day 1', 'Day 2', 'Day 3']
  const mealTypes = ['Breakfast', 'Lunch', 'Dinner', 'Snack']

  useEffect(() => {
    onMealUpdate(meals)
  }, [meals, onMealUpdate])

  const addMeal = () => {
    if (!newMeal.meal?.name) return

    const meal: MealPlan = {
      id: `meal-${Date.now()}`,
      tripId,
      day: newMeal.day || 'Day 1',
      mealType: newMeal.mealType || 'Breakfast',
      scheduledTime: newMeal.scheduledTime || '08:00',
      meal: {
        id: `item-${Date.now()}`,
        name: newMeal.meal.name,
        description: newMeal.meal.description || '',
        servings: newMeal.servingCount || 4,
        prepTime: newMeal.meal.prepTime || 15,
        cookTime: newMeal.meal.cookTime || 30,
        difficulty: newMeal.meal.difficulty || 'Easy',
        ingredients: newMeal.meal.ingredients || [],
        instructions: newMeal.meal.instructions || [],
        dietaryTags: newMeal.meal.dietaryTags || [],
        assignedTo: newMeal.meal.assignedTo
      },
      servingCount: newMeal.servingCount || 4,
      notes: newMeal.notes
    }

    setMeals(prev => [...prev, meal])
    setNewMeal({
      day: 'Day 1',
      mealType: 'Breakfast',
      scheduledTime: '08:00',
      servingCount: 4
    })
    setShowAddMeal(false)
  }

  const updateMeal = (mealId: string, updates: Partial<MealPlan>) => {
    setMeals(prev => prev.map(meal => 
      meal.id === mealId ? { ...meal, ...updates } : meal
    ))
  }

  const deleteMeal = (mealId: string) => {
    setMeals(prev => prev.filter(meal => meal.id !== mealId))
  }

  const getMealsForDay = (day: string) => {
    return meals
      .filter(meal => meal.day === day)
      .sort((a, b) => {
        const timeA = new Date(`2000-01-01 ${a.scheduledTime}`)
        const timeB = new Date(`2000-01-01 ${b.scheduledTime}`)
        return timeA.getTime() - timeB.getTime()
      })
  }

  const getTotalCost = () => {
    return meals.reduce((total, meal) => total + (meal.meal.cost || 0), 0)
  }

  const getDietaryInfo = () => {
    const allTags = meals.flatMap(meal => meal.meal.dietaryTags)
    return [...new Set(allTags)]
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 bg-[#228b22] rounded-xl flex items-center justify-center">
              <ChefHat className="w-5 h-5 text-[#ffffff]" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[#0f172a]">Meal Menu</h1>
              <p className="text-sm text-[#64748b]">Plan your trip meals and assignments</p>
            </div>
          </div>

          {/* Summary Stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-4">
            <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-lg p-3">
              <div className="text-xs text-[#64748b] mb-1">Total Meals</div>
              <div className="text-lg font-bold text-[#0f172a]">{meals.length}</div>
            </div>
            <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-lg p-3">
              <div className="text-xs text-[#64748b] mb-1">Est. Cost</div>
              <div className="text-lg font-bold text-[#228b22]">${getTotalCost().toFixed(0)}</div>
            </div>
            <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-lg p-3">
              <div className="text-xs text-[#64748b] mb-1">Dietary Tags</div>
              <div className="text-lg font-bold text-[#0f172a]">{getDietaryInfo().length}</div>
            </div>
            <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-lg p-3">
              <div className="text-xs text-[#64748b] mb-1">Avg Servings</div>
              <div className="text-lg font-bold text-[#0f172a]">
                {Math.round(meals.reduce((sum, m) => sum + m.servingCount, 0) / meals.length || 0)}
              </div>
            </div>
          </div>
        </div>

        {/* Day Tabs */}
        <div className="flex gap-2 mb-6 overflow-x-auto">
          {days.map(day => (
            <button
              key={day}
              onClick={() => setSelectedDay(day)}
              className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-200 ${
                selectedDay === day
                  ? 'bg-[#228b22] text-[#ffffff] shadow-md'
                  : 'bg-[#f8fafc] text-[#64748b] hover:bg-[#e2e8f0]'
              }`}
            >
              {day}
              <span className="ml-2 text-xs opacity-75">
                ({getMealsForDay(day).length})
              </span>
            </button>
          ))}
        </div>

        {/* Meals for Selected Day */}
        <div className="space-y-4 mb-6">
          {getMealsForDay(selectedDay).map(meal => (
            <div
              key={meal.id}
              className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 shadow-sm hover:shadow-md transition-all duration-200"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className={`px-3 py-1 rounded-full text-xs font-medium ${
                    meal.mealType === 'Breakfast' ? 'bg-[#fef3c7] text-[#92400e]' :
                    meal.mealType === 'Lunch' ? 'bg-[#dbeafe] text-[#1e40af]' :
                    meal.mealType === 'Dinner' ? 'bg-[#fce7f3] text-[#be185d]' :
                    'bg-[#f3e8ff] text-[#7c3aed]'
                  }`}>
                    {meal.mealType}
                  </div>
                  <div className="flex items-center gap-1 text-xs text-[#64748b]">
                    <Clock className="w-3 h-3" />
                    {meal.scheduledTime}
                  </div>
                </div>
                {!readOnly && (
                  <div className="flex gap-2">
                    <button
                      onClick={() => setEditingMeal(meal.id)}
                      className="w-8 h-8 flex items-center justify-center text-[#64748b] hover:text-[#228b22] hover:bg-[#f8fafc] rounded-lg transition-all duration-200"
                      aria-label="Edit meal"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => deleteMeal(meal.id)}
                      className="w-8 h-8 flex items-center justify-center text-[#64748b] hover:text-[#dc2626] hover:bg-[#fef2f2] rounded-lg transition-all duration-200"
                      aria-label="Delete meal"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                )}
              </div>

              <div className="mb-3">
                <h3 className="text-lg font-bold text-[#0f172a] mb-1">{meal.meal.name}</h3>
                {meal.meal.description && (
                  <p className="text-sm text-[#64748b] mb-2">{meal.meal.description}</p>
                )}

                <div className="flex flex-wrap gap-2 mb-3">
                  <div className="flex items-center gap-1 text-xs text-[#64748b]">
                    <Users className="w-3 h-3" />
                    {meal.servingCount} servings
                  </div>
                  <div className="text-xs text-[#64748b]">
                    Prep: {meal.meal.prepTime}min
                  </div>
                  <div className="text-xs text-[#64748b]">
                    Cook: {meal.meal.cookTime}min
                  </div>
                  <div className={`px-2 py-0.5 rounded text-xs font-medium ${
                    meal.meal.difficulty === 'Easy' ? 'bg-[#dcfce7] text-[#166534]' :
                    meal.meal.difficulty === 'Medium' ? 'bg-[#fef3c7] text-[#92400e]' :
                    'bg-[#fecaca] text-[#991b1b]'
                  }`}>
                    {meal.meal.difficulty}
                  </div>
                </div>

                {meal.meal.dietaryTags.length > 0 && (
                  <div className="flex flex-wrap gap-1 mb-3">
                    {meal.meal.dietaryTags.map(tag => (
                      <span
                        key={tag}
                        className="px-2 py-0.5 bg-[#f1f5f9] text-[#475569] rounded text-xs"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                )}

                {meal.meal.assignedTo && (
                  <div className="text-sm text-[#64748b]">
                    Assigned to: <span className="font-medium text-[#228b22]">{meal.meal.assignedTo}</span>
                  </div>
                )}
              </div>

              {meal.meal.ingredients.length > 0 && (
                <div className="mb-3">
                  <h4 className="text-sm font-medium text-[#0f172a] mb-2">Ingredients</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-1">
                    {meal.meal.ingredients.map((ingredient, index) => (
                      <div key={index} className="text-sm text-[#64748b]">
                        • {ingredient}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {meal.notes && (
                <div className="mt-3 p-3 bg-[#f8fafc] rounded-lg">
                  <div className="text-xs text-[#64748b] mb-1">Notes</div>
                  <div className="text-sm text-[#0f172a]">{meal.notes}</div>
                </div>
              )}
            </div>
          ))}

          {getMealsForDay(selectedDay).length === 0 && (
            <div className="text-center py-12">
              <ChefHat className="w-12 h-12 text-[#cbd5e1] mx-auto mb-3" />
              <h3 className="text-lg font-medium text-[#0f172a] mb-2">No meals planned</h3>
              <p className="text-sm text-[#64748b] mb-4">Add your first meal for {selectedDay}</p>
              {!readOnly && (
                <button
                  onClick={() => setShowAddMeal(true)}
                  className="px-4 py-2 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7b1e] transition-all duration-200 font-medium text-sm shadow-md hover:shadow-lg active:scale-95"
                >
                  Add Meal
                </button>
              )}
            </div>
          )}
        </div>

        {/* Add Meal Button */}
        {!readOnly && getMealsForDay(selectedDay).length > 0 && (
          <button
            onClick={() => setShowAddMeal(true)}
            className="w-full flex items-center justify-center gap-2 py-3 border-2 border-dashed border-[#e2e8f0] text-[#64748b] hover:border-[#228b22] hover:text-[#228b22] rounded-xl transition-all duration-200"
          >
            <Plus className="w-5 h-5" />
            Add Meal to {selectedDay}
          </button>
        )}

        {/* Add Meal Modal */}
        {showAddMeal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-[#ffffff] rounded-xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-[#0f172a]">Add New Meal</h2>
                <button
                  onClick={() => setShowAddMeal(false)}
                  className="w-8 h-8 flex items-center justify-center text-[#64748b] hover:text-[#0f172a] hover:bg-[#f8fafc] rounded-lg transition-all duration-200"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-[#0f172a] mb-1">Day</label>
                    <select
                      value={newMeal.day}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, day: e.target.value }))}
                      className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                    >
                      {days.map(day => (
                        <option key={day} value={day}>{day}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#0f172a] mb-1">Meal Type</label>
                    <select
                      value={newMeal.mealType}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, mealType: e.target.value as any }))}
                      className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                    >
                      {mealTypes.map(type => (
                        <option key={type} value={type}>{type}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-[#0f172a] mb-1">Time</label>
                    <input
                      type="time"
                      value={newMeal.scheduledTime}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, scheduledTime: e.target.value }))}
                      className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#0f172a] mb-1">Servings</label>
                    <input
                      type="number"
                      min="1"
                      value={newMeal.servingCount}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, servingCount: parseInt(e.target.value) }))}
                      className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-1">Meal Name</label>
                  <input
                    type="text"
                    placeholder="e.g., Campfire Chili"
                    value={newMeal.meal?.name || ''}
                    onChange={(e) => setNewMeal(prev => ({ 
                      ...prev, 
                      meal: { ...prev.meal, name: e.target.value } as any
                    }))}
                    className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-1">Description</label>
                  <textarea
                    placeholder="Brief description of the meal..."
                    value={newMeal.meal?.description || ''}
                    onChange={(e) => setNewMeal(prev => ({ 
                      ...prev, 
                      meal: { ...prev.meal, description: e.target.value } as any
                    }))}
                    rows={2}
                    className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200 resize-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-1">Assigned To</label>
                  <select
                    value={newMeal.meal?.assignedTo || ''}
                    onChange={(e) => setNewMeal(prev => ({ 
                      ...prev, 
                      meal: { ...prev.meal, assignedTo: e.target.value } as any
                    }))}
                    className="w-full px-3 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                  >
                    <option value="">Select member...</option>
                    {groupMembers.map(member => (
                      <option key={member.id} value={member.name}>{member.name}</option>
                    ))}
                  </select>
                </div>

                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => setShowAddMeal(false)}
                    className="flex-1 px-4 py-2 bg-[#f8fafc] text-[#64748b] rounded-lg hover:bg-[#e2e8f0] transition-all duration-200 font-medium text-sm"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={addMeal}
                    disabled={!newMeal.meal?.name}
                    className="flex-1 px-4 py-2 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7b1e] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-medium text-sm shadow-md hover:shadow-lg active:scale-95"
                  >
                    Add Meal
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
