'use client'

import { useState, useEffect } from 'react'
import { Send, Mail, CheckCircle, AlertCircle, Clock, Users } from 'lucide-react'

interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
  sentAt?: Date
}

interface EmailCampaign {
  id: string
  templateId: string
  recipients: EmailRecipient[]
  scheduledFor?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed'
  createdAt: Date
}

interface ResendServiceProps {
  tripId?: string
  onEmailSent?: (campaignId: string) => void
  onError?: (error: string) => void
}

export function ResendService({
  tripId = 'trip-1',
  onEmailSent = () => console.log('Email sent'),
  onError = () => console.log('Email error')
}: ResendServiceProps = {}) {
  const [templates, setTemplates] = useState<EmailTemplate[]>(DEFAULT_TEMPLATES)
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>(DEFAULT_CAMPAIGNS)
  const [selectedTemplate, setSelectedTemplate] = useState<string>('')
  const [recipients, setRecipients] = useState<EmailRecipient[]>(DEFAULT_RECIPIENTS)
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'send' | 'templates' | 'history'>('send')

  const handleSendEmail = async () => {
    if (!selectedTemplate || recipients.length === 0) return

    setIsLoading(true)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000))

      const newCampaign: EmailCampaign = {
        id: `campaign-${Date.now()}`,
        templateId: selectedTemplate,
        recipients: recipients.map(r => ({ ...r, status: 'sent', sentAt: new Date() })),
        status: 'sent',
        createdAt: new Date()
      }

      setCampaigns(prev => [newCampaign, ...prev])
      onEmailSent(newCampaign.id)
      setSelectedTemplate('')
    } catch (error) {
      onError('Failed to send emails')
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusIcon = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
      default:
        return <Clock className="w-4 h-4 text-[rgb(255,140,0)]" />
    }
  }

  const getStatusColor = (status: EmailCampaign['status']) => {
    switch (status) {
      case 'sent':
        return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'sending':
        return 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)] border-[rgb(255,140,0)]/20'
      case 'failed':
        return 'bg-[rgb(220,38,38)]/10 text-[rgb(220,38,38)] border-[rgb(220,38,38)]/20'
      default:
        return 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 pb-20">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">Email Service</h1>
          <p className="text-[rgb(15,23,42)]/60">Send trip invitations and updates to your group</p>
        </div>

        {/* Tab Navigation */}
        <div className="flex bg-[rgb(248,250,252)] rounded-lg p-1 mb-6">
          {[
            { id: 'send', label: 'Send Email', icon: Send },
            { id: 'templates', label: 'Templates', icon: Mail },
            { id: 'history', label: 'History', icon: Clock }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 py-3 px-4 rounded-md text-sm font-medium transition-all duration-200 ${
                activeTab === id
                  ? 'bg-[rgb(255,255,255)] text-[rgb(34,139,34)] shadow-sm'
                  : 'text-[rgb(15,23,42)]/60 hover:text-[rgb(15,23,42)]'
              }`}
              aria-label={label}
            >
              <Icon className="w-4 h-4" />
              <span className="hidden sm:inline">{label}</span>
            </button>
          ))}
        </div>

        {/* Send Email Tab */}
        {activeTab === 'send' && (
          <div className="space-y-6">
            {/* Template Selection */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Select Template</h3>
              <div className="grid gap-3">
                {templates.map((template) => (
                  <button
                    key={template.id}
                    onClick={() => setSelectedTemplate(template.id)}
                    className={`p-4 rounded-lg border-2 text-left transition-all duration-200 ${
                      selectedTemplate === template.id
                        ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5'
                        : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
                    }`}
                    aria-label={`Select ${template.name} template`}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="font-medium text-[rgb(15,23,42)]">{template.name}</h4>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${
                        template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20' :
                        template.type === 'reminder' ? 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)] border-[rgb(255,140,0)]/20' :
                        'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
                      }`}>
                        {template.type}
                      </span>
                    </div>
                    <p className="text-sm text-[rgb(15,23,42)]/60">{template.subject}</p>
                  </button>
                ))}
              </div>
            </div>

            {/* Recipients */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">Recipients</h3>
                <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/60">
                  <Users className="w-4 h-4" />
                  {recipients.length} members
                </div>
              </div>
              <div className="space-y-3">
                {recipients.map((recipient) => (
                  <div
                    key={recipient.id}
                    className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg"
                  >
                    <div>
                      <p className="font-medium text-[rgb(15,23,42)]">{recipient.name}</p>
                      <p className="text-sm text-[rgb(15,23,42)]/60">{recipient.email}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      {getStatusIcon(recipient.status)}
                      <span className="text-sm text-[rgb(15,23,42)]/60 capitalize">
                        {recipient.status}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Send Button */}
            <button
              onClick={handleSendEmail}
              disabled={!selectedTemplate || recipients.length === 0 || isLoading}
              className="w-full py-4 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium text-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[rgb(34,139,34)]/90 transition-all duration-200 shadow-md hover:shadow-lg active:scale-95 flex items-center justify-center gap-2"
              aria-label="Send email to all recipients"
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  Send Email
                </>
              )}
            </button>
          </div>
        )}

        {/* Templates Tab */}
        {activeTab === 'templates' && (
          <div className="space-y-4">
            {templates.map((template) => (
              <div
                key={template.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm"
              >
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">{template.name}</h3>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium border ${
                    template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20' :
                    template.type === 'reminder' ? 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)] border-[rgb(255,140,0)]/20' :
                    'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
                  }`}>
                    {template.type}
                  </span>
                </div>
                <p className="text-[rgb(15,23,42)] font-medium mb-2">Subject: {template.subject}</p>
                <p className="text-[rgb(15,23,42)]/60 text-sm leading-relaxed">{template.content}</p>
              </div>
            ))}
          </div>
        )}

        {/* History Tab */}
        {activeTab === 'history' && (
          <div className="space-y-4">
            {campaigns.map((campaign) => (
              <div
                key={campaign.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm"
              >
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">
                    {templates.find(t => t.id === campaign.templateId)?.name || 'Unknown Template'}
                  </h3>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(campaign.status)}`}>
                    {campaign.status}
                  </span>
                </div>
                <div className="flex items-center justify-between text-sm text-[rgb(15,23,42)]/60">
                  <span>Sent to {campaign.recipients.length} recipients</span>
                  <span>{campaign.createdAt.toLocaleDateString()}</span>
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  {campaign.recipients.slice(0, 3).map((recipient) => (
                    <div
                      key={recipient.id}
                      className="flex items-center gap-1 px-2 py-1 bg-[rgb(248,250,252)] rounded text-xs"
                    >
                      {getStatusIcon(recipient.status)}
                      {recipient.name}
                    </div>
                  ))}
                  {campaign.recipients.length > 3 && (
                    <span className="px-2 py-1 bg-[rgb(248,250,252)] rounded text-xs text-[rgb(15,23,42)]/60">
                      +{campaign.recipients.length - 3} more
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

