'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, MapPin, AlertCircle, CheckCircle, RefreshCw } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  location?: string
  description?: string
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
}

interface TripEvent {
  id: string
  title: string
  date: Date
  assignedTo?: string
  type: 'meal' | 'task' | 'activity'
}

interface CalendarIntegrationProps {
  groupMembers?: GroupMember[]
  tripEvents?: TripEvent[]
  onEventCreate?: (event: CalendarEvent) => void
  onAvailabilityCheck?: (dates: Date[]) => Promise<{ [email: string]: boolean[] }>
  onInviteSend?: (event: CalendarEvent) => void
}

export function CalendarIntegration({
  groupMembers = DEFAULT_GROUP_MEMBERS,
  tripEvents = DEFAULT_TRIP_EVENTS,
  onEventCreate = (event) => console.log('Creating event:', event),
  onAvailabilityCheck = async () => ({}),
  onInviteSend = (event) => console.log('Sending invite:', event)
}: CalendarIntegrationProps = {}) {
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [selectedDates, setSelectedDates] = useState<Date[]>([])
  const [availability, setAvailability] = useState<{ [email: string]: boolean[] }>({})
  const [activeTab, setActiveTab] = useState<'schedule' | 'availability' | 'invites'>('schedule')
  const [error, setError] = useState<string | null>(null)

  const connectCalendar = async () => {
    setIsLoading(true)
    setError(null)

    try {
      // Simulate Google Calendar OAuth flow
      await new Promise(resolve => setTimeout(resolve, 2000))
      setIsConnected(true)
    } catch (err) {
      setError('Failed to connect to Google Calendar. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const checkAvailability = async () => {
    if (selectedDates.length === 0) return

    setIsLoading(true)
    try {
      const result = await onAvailabilityCheck(selectedDates)
      setAvailability(result)
    } catch (err) {
      setError('Failed to check availability')
    } finally {
      setIsLoading(false)
    }
  }

  const createTripEvent = async (tripEvent: TripEvent) => {
    const calendarEvent: CalendarEvent = {
      id: `trip-${tripEvent.id}`,
      title: `Off-Road Trip: ${tripEvent.title}`,
      start: tripEvent.date,
      end: new Date(tripEvent.date.getTime() + 2 * 60 * 60 * 1000), // 2 hours
      attendees: groupMembers.map(m => m.email),
      description: `Assigned to: ${groupMembers.find(m => m.id === tripEvent.assignedTo)?.name || 'Unassigned'}`
    }

    onEventCreate(calendarEvent)
    onInviteSend(calendarEvent)
  }

  const getAvailabilityColor = (email: string, dateIndex: number) => {
    const isAvailable = availability[email]?.[dateIndex]
    if (isAvailable === undefined) return 'bg-[rgb(248,250,252)]'
    return isAvailable ? 'bg-[rgb(34,139,34)]' : 'bg-[rgb(220,38,38)]'
  }

  if (!isConnected) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] p-4">
        <div className="max-w-md mx-auto pt-16">
          <div className="bg-[rgb(255,255,255)] rounded-xl border border-[rgb(226,232,240)] p-8 shadow-md">
            <div className="text-center space-y-6">
              <div className="w-16 h-16 bg-[rgb(245,247,250)] rounded-full flex items-center justify-center mx-auto">
                <Calendar className="w-8 h-8 text-[rgb(34,139,34)]" />
              </div>

              <div className="space-y-2">
                <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">
                  Connect Google Calendar
                </h2>
                <p className="text-sm text-[rgb(100,116,139)]">
                  Sync your calendar to check availability and send trip invites to your group
                </p>
              </div>

              {error && (
                <div className="flex items-center gap-2 p-3 bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg">
                  <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
                  <span className="text-sm text-[rgb(220,38,38)]">{error}</span>
                </div>
              )}

              <button
                onClick={connectCalendar}
                disabled={isLoading}
                className="w-full h-12 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium text-sm hover:bg-[rgb(22,101,52)] transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                aria-label="Connect to Google Calendar"
              >
                {isLoading ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    Connecting...
                  </>
                ) : (
                  <>
                    <Calendar className="w-4 h-4" />
                    Connect Calendar
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
            <h1 className="text-lg font-semibold text-[rgb(15,23,42)]">Calendar Connected</h1>
          </div>
          <button
            onClick={() => setIsConnected(false)}
            className="text-sm text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]"
            aria-label="Disconnect calendar"
          >
            Disconnect
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-[rgb(226,232,240)]">
        <div className="flex">
          {[
            { id: 'schedule', label: 'Schedule', icon: Calendar },
            { id: 'availability', label: 'Availability', icon: Clock },
            { id: 'invites', label: 'Invites', icon: Users }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 p-4 text-sm font-medium border-b-2 transition-colors duration-150 ${
                activeTab === id
                  ? 'border-[rgb(34,139,34)] text-[rgb(34,139,34)]'
                  : 'border-transparent text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)]'
              }`}
              aria-label={`Switch to ${label} tab`}
            >
              <Icon className="w-4 h-4" />
              {label}
            </button>
          ))}
        </div>
      </div>

      <div className="p-4 space-y-4">
        {activeTab === 'schedule' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Trip Events</h2>
            {tripEvents.map((event) => (
              <div
                key={event.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-4 space-y-3"
              >
                <div className="flex items-start justify-between">
                  <div className="space-y-1">
                    <h3 className="font-medium text-[rgb(15,23,42)]">{event.title}</h3>
                    <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                      <Clock className="w-4 h-4" />
                      {event.date.toLocaleDateString()} at {event.date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </div>
                    {event.assignedTo && (
                      <div className="flex items-center gap-2 text-sm text-[rgb(100,116,139)]">
                        <Users className="w-4 h-4" />
                        {groupMembers.find(m => m.id === event.assignedTo)?.name}
                      </div>
                    )}
                  </div>
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                    event.type === 'meal' ? 'bg-[rgb(255,247,237)] text-[rgb(255,140,0)]' :
                    event.type === 'task' ? 'bg-[rgb(240,253,244)] text-[rgb(34,139,34)]' :
                    'bg-[rgb(245,247,250)] text-[rgb(100,116,139)]'
                  }`}>
                    {event.type}
                  </span>
                </div>

                <button
                  onClick={() => createTripEvent(event)}
                  className="w-full h-10 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium text-sm hover:bg-[rgb(22,101,52)] transition-colors duration-150"
                  aria-label={`Create calendar event for ${event.title}`}
                >
                  Add to Calendar & Send Invites
                </button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'availability' && (
          <div className="space-y-4">
            <div className="space-y-3">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Check Group Availability</h2>
              <p className="text-sm text-[rgb(100,116,139)]">
                Select dates to check when your group members are available
              </p>
            </div>

            <div className="space-y-3">
              <label className="block text-sm font-medium text-[rgb(15,23,42)]">
                Trip Dates
              </label>
              <input
                type="date"
                className="w-full h-12 px-4 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]"
                onChange={(e) => {
                  const date = new Date(e.target.value)
                  if (!isNaN(date.getTime())) {
                    setSelectedDates([date])
                  }
                }}
                aria-label="Select trip date"
              />
            </div>

            {selectedDates.length > 0 && (
              <button
                onClick={checkAvailability}
                disabled={isLoading}
                className="w-full h-12 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg font-medium text-sm hover:bg-[rgb(22,101,52)] transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                aria-label="Check group availability"
              >
                {isLoading ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    Checking...
                  </>
                ) : (
                  'Check Availability'
                )}
              </button>
            )}

            {Object.keys(availability).length > 0 && (
              <div className="space-y-3">
                <h3 className="font-medium text-[rgb(15,23,42)]">Group Availability</h3>
                <div className="space-y-2">
                  {groupMembers.map((member, memberIndex) => (
                    <div key={member.id} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg">
                      <span className="text-sm font-medium text-[rgb(15,23,42)]">{member.name}</span>
                      <div className="flex gap-1">
                        {selectedDates.map((_, dateIndex) => (
                          <div
                            key={dateIndex}
                            className={`w-4 h-4 rounded-full ${getAvailabilityColor(member.email, dateIndex)}`}
                            title={availability[member.email]?.[dateIndex] ? 'Available' : 'Busy'}
                          />
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <div className="flex items-center gap-4 text-xs text-[rgb(100,116,139)]">
                  <div className="flex items-center gap-1">
                    <div className="w-3 h-3 bg-[rgb(34,139,34)] rounded-full" />
                    Available
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-3 h-3 bg-[rgb(220,38,38)] rounded-full" />
                    Busy
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'invites' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Sent Invitations</h2>
