'use client'

import { useState, useEffect } from 'react'
import { 
  MapPin, 
  Users, 
  Calendar, 
  MessageCircle, 
  CloudSun, 
  CheckCircle,
  Plus,
  Settings,
  Navigation,
  Tent,
  UtensilsCrossed,
  Clock
} from 'lucide-react'

interface TripLocation {
  id: string
  name: string
  coordinates: { lat: number; lng: number }
  difficulty: 'easy' | 'moderate' | 'hard'
  saved: boolean
}

interface GroupMember {
  id: string
  name: string
  avatar: string
  status: 'confirmed' | 'pending' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface WeatherData {
  date: string
  temp: { high: number; low: number }
  condition: string
  precipitation: number
}

interface TripPlannerProps {
  initialLocation?: TripLocation
  groupMembers?: GroupMember[]
  tasks?: Task[]
  weather?: WeatherData[]
}

export function TripPlanner({
  initialLocation,
  groupMembers = DEFAULT_MEMBERS,
  tasks = DEFAULT_TASKS,
  weather = DEFAULT_WEATHER
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('locations')
  const [selectedLocation, setSelectedLocation] = useState<TripLocation | null>(initialLocation || null)
  const [tripTasks, setTripTasks] = useState(tasks)
  const [showAddTask, setShowAddTask] = useState(false)
  const [newTaskTitle, setNewTaskTitle] = useState('')
  const [rsvpCount, setRsvpCount] = useState(0)

  useEffect(() => {
    const confirmed = groupMembers.filter(member => member.status === 'confirmed').length
    setRsvpCount(confirmed)
  }, [groupMembers])

  const toggleTaskComplete = (taskId: string) => {
    setTripTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const addNewTask = () => {
    if (!newTaskTitle.trim()) return

    const newTask: Task = {
      id: Date.now().toString(),
      title: newTaskTitle,
      assignedTo: groupMembers[0]?.name || 'Unassigned',
      category: 'logistics',
      completed: false,
      dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    }

    setTripTasks(prev => [...prev, newTask])
    setNewTaskTitle('')
    setShowAddTask(false)
  }

  const renderLocationsTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Locations</h2>
        <button 
          className="p-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(28,115,28)] transition-colors duration-150 shadow-md"
          aria-label="Add new location"
        >
          <Plus className="w-5 h-5" />
        </button>
      </div>

      {DEFAULT_LOCATIONS.map((location) => (
        <div 
          key={location.id}
          className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm hover:shadow-md transition-all duration-200 cursor-pointer"
          onClick={() => setSelectedLocation(location)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => e.key === 'Enter' && setSelectedLocation(location)}
        >
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="w-4 h-4 text-[rgb(34,139,34)]" />
                <h3 className="font-medium text-[rgb(15,23,42)]">{location.name}</h3>
              </div>
              <div className="flex items-center gap-4 text-sm text-gray-600">
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  location.difficulty === 'easy' ? 'bg-green-100 text-green-700' :
                  location.difficulty === 'moderate' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-red-100 text-red-700'
                }`}>
                  {location.difficulty}
                </span>
                <span>{location.coordinates.lat.toFixed(4)}, {location.coordinates.lng.toFixed(4)}</span>
              </div>
            </div>
            <button 
              className={`p-1.5 rounded-lg transition-colors duration-150 ${
                location.saved 
                  ? 'bg-[rgb(34,139,34)] text-white' 
                  : 'bg-[rgb(245,247,250)] text-gray-600 hover:bg-gray-200'
              }`}
              onClick={(e) => {
                e.stopPropagation()
                // Toggle save logic would go here
              }}
              aria-label={location.saved ? 'Remove from saved' : 'Save location'}
            >
              <CheckCircle className="w-4 h-4" />
            </button>
          </div>
        </div>
      ))}
    </div>
  )

  const renderTasksTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
        <button 
          className="p-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(28,115,28)] transition-colors duration-150 shadow-md"
          onClick={() => setShowAddTask(true)}
          aria-label="Add new task"
        >
          <Plus className="w-5 h-5" />
        </button>
      </div>

      {showAddTask && (
        <div className="bg-[rgb(245,247,250)] border border-[rgb(226,232,240)] rounded-xl p-4">
          <input
            type="text"
            placeholder="Enter task description..."
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            className="w-full px-3 py-2 bg-white border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150 mb-3"
            onKeyDown={(e) => e.key === 'Enter' && addNewTask()}
          />
          <div className="flex gap-2">
            <button
              onClick={addNewTask}
              className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(28,115,28)] transition-colors duration-150 font-medium text-sm"
            >
              Add Task
            </button>
            <button
              onClick={() => setShowAddTask(false)}
              className="px-4 py-2 bg-white text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(245,247,250)] transition-colors duration-150 font-medium text-sm border border-[rgb(226,232,240)]"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      <div className="space-y-3">
        {tripTasks.map((task) => (
          <div 
            key={task.id}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm"
          >
            <div className="flex items-start gap-3">
              <button
                onClick={() => toggleTaskComplete(task.id)}
                className={`mt-0.5 w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors duration-150 ${
                  task.completed 
                    ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)] text-white' 
                    : 'border-gray-300 hover:border-[rgb(34,139,34)]'
                }`}
                aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
              >
                {task.completed && <CheckCircle className="w-3 h-3" />}
              </button>
              <div className="flex-1">
                <h3 className={`font-medium ${task.completed ? 'line-through text-gray-500' : 'text-[rgb(15,23,42)]'}`}>
                  {task.title}
                </h3>
                <div className="flex items-center gap-4 mt-1 text-sm text-gray-600">
                  <span>Assigned to: {task.assignedTo}</span>
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                    task.category === 'food' ? 'bg-orange-100 text-orange-700' :
                    task.category === 'equipment' ? 'bg-blue-100 text-blue-700' :
                    'bg-purple-100 text-purple-700'
                  }`}>
                    {task.category}
                  </span>
                  <span>Due: {new Date(task.dueDate).toLocaleDateString()}</span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )

  const renderGroupTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Members</h2>
        <div className="text-sm text-gray-600">
          {rsvpCount}/{groupMembers.length} confirmed
        </div>
      </div>

      <div className="space-y-3">
        {groupMembers.map((member) => (
          <div 
            key={member.id}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-medium">
                {member.name.charAt(0)}
              </div>
              <div className="flex-1">
                <h3 className="font-medium text-[rgb(15,23,42)]">{member.name}</h3>
                <span className={`inline-block px-2 py-1 rounded-full text-xs font-medium ${
                  member.status === 'confirmed' ? 'bg-green-100 text-green-700' :
                  member.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-red-100 text-red-700'
                }`}>
                  {member.status}
                </span>
              </div>
              <button 
                className="p-2 bg-[rgb(245,247,250)] text-gray-600 rounded-lg hover:bg-gray-200 transition-colors duration-150"
