          </div>
        ))}
      </div>
    </div>
  )

  const renderWeatherTab = () => (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Weather Forecast</h2>

      <div className="space-y-3">
        {weather.map((day, index) => (
          <div 
            key={index}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <CloudSun className="w-6 h-6 text-[rgb(255,140,0)]" />
                <div>
                  <h3 className="font-medium text-[rgb(15,23,42)]">
                    {new Date(day.date).toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
                  </h3>
                  <p className="text-sm text-gray-600">{day.condition}</p>
                </div>
              </div>
              <div className="text-right">
                <div className="font-medium text-[rgb(15,23,42)]">
                  {day.temp.high}°/{day.temp.low}°
                </div>
                <div className="text-sm text-gray-600">
                  {day.precipitation}% rain
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )

  const tabs = [
    { id: 'locations', label: 'Locations', icon: MapPin },
    { id: 'tasks', label: 'Tasks', icon: CheckCircle },
    { id: 'group', label: 'Group', icon: Users },
    { id: 'weather', label: 'Weather', icon: CloudSun }
  ]

  return (
    <div className="min-h-screen bg-[rgb(248,250,252)]">
      {/* Header */}
      <div className="bg-white border-b border-[rgb(226,232,240)] px-4 py-4 sticky top-0 z-10">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-lg flex items-center justify-center">
              <Tent className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-lg font-semibold text-[rgb(15,23,42)]">Trip Planner</h1>
          </div>
          <button 
            className="p-2 bg-[rgb(245,247,250)] text-gray-600 rounded-lg hover:bg-gray-200 transition-colors duration-150"
            aria-label="Settings"
          >
            <Settings className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="px-4 py-6 pb-24">
        {activeTab === 'locations' && renderLocationsTab()}
        {activeTab === 'tasks' && renderTasksTab()}
        {activeTab === 'group' && renderGroupTab()}
        {activeTab === 'weather' && renderWeatherTab()}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-[rgb(226,232,240)] px-4 py-2">
        <div className="flex items-center justify-around">
          {tabs.map((tab) => {
            const Icon = tab.icon
            const isActive = activeTab === tab.id
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex flex-col items-center gap-1 py-2 px-3 rounded-lg transition-colors duration-150 min-w-0 ${
                  isActive 
                    ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)]' 
                    : 'text-gray-600 hover:text-[rgb(34,139,34)]'
                }`}
                aria-label={tab.label}
              >
                <Icon className="w-5 h-5" />
                <span className="text-xs font-medium">{tab.label}</span>
              </button>
            )
          })}
        </div>
      </div>
    </div>
  )
}

