  members = DEFAULT_MEMBERS,
  onLocationSave = () => console.log('Location saved'),
  onTaskAssign = () => console.log('Task assigned'),
  onRSVP = () => console.log('RSVP updated')
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('location')
