  return (
    <div className="space-y-3">
      <p className="text-sm text-[rgb(100,116,139)]">
        Signed in as: {user?.email}
      </p>
      <button
        onClick={signOut}
        className="px-4 py-2 bg-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(226,232,240)]/80 transition-colors font-medium text-sm"
