  avatar: string
  role: 'organizer' | 'member'
  rsvpStatus: 'pending' | 'accepted' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface TripPlannerProps {
  initialLocation?: TripLocation
  members?: GroupMember[]
  tasks?: Task[]
}

export function TripPlanner({
  initialLocation,
  members = DEFAULT_MEMBERS,
  tasks = DEFAULT_TASKS
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('locations')
  const [selectedLocation, setSelectedLocation] = useState<TripLocation | null>(initialLocation || null)
  const [tripMembers, setTripMembers] = useState(members)
  const [tripTasks, setTripTasks] = useState(tasks)
  const [showInviteModal, setShowInviteModal] = useState(false)

  const handleLocationSelect = (location: TripLocation) => {
    setSelectedLocation(location)
  }

  const handleTaskToggle = (taskId: string) => {
    setTripTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const handleRSVP = (memberId: string, status: 'accepted' | 'declined') => {
    setTripMembers(prev => prev.map(member =>
      member.id === memberId ? { ...member, rsvpStatus: status } : member
    ))
  }

  const renderLocationsTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trail Locations</h2>
        <button className="p-2 bg-[rgb(34,139,34)] text-white rounded-lg shadow-md hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95">
          <Plus className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-3">
        {SAMPLE_LOCATIONS.map((location) => (
          <div
            key={location.id}
            className={`p-4 bg-white border rounded-xl shadow-sm transition-all duration-200 cursor-pointer ${
              selectedLocation?.id === location.id 
                ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5' 
                : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
            }`}
            onClick={() => handleLocationSelect(location)}
          >
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <h3 className="font-medium text-[rgb(15,23,42)]">{location.name}</h3>
                <div className="flex items-center gap-2 mt-1">
                  <MapPin className="w-4 h-4 text-[rgb(34,139,34)]" />
                  <span className="text-sm text-gray-600">
                    {location.coordinates.lat.toFixed(4)}, {location.coordinates.lng.toFixed(4)}
                  </span>
                </div>
                <span className={`inline-block px-2 py-1 mt-2 text-xs font-medium rounded-full ${
                  location.difficulty === 'Easy' ? 'bg-green-100 text-green-700' :
                  location.difficulty === 'Moderate' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-red-100 text-red-700'
                }`}>
                  {location.difficulty}
                </span>
              </div>
              {location.saved && (
                <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  )

  const renderTasksTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
        <button className="p-2 bg-[rgb(34,139,34)] text-white rounded-lg shadow-md hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95">
          <Plus className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-3">
        {tripTasks.map((task) => {
          const assignedMember = tripMembers.find(m => m.id === task.assignedTo)
          return (
            <div
              key={task.id}
              className="p-4 bg-white border border-[rgb(226,232,240)] rounded-xl shadow-sm"
            >
              <div className="flex items-start gap-3">
                <button
                  onClick={() => handleTaskToggle(task.id)}
                  className={`mt-1 w-5 h-5 rounded border-2 flex items-center justify-center transition-colors duration-150 ${
                    task.completed 
                      ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)]' 
                      : 'border-gray-300 hover:border-[rgb(34,139,34)]'
                  }`}
                >
                  {task.completed && <CheckCircle className="w-3 h-3 text-white" />}
                </button>
                <div className="flex-1">
                  <h3 className={`font-medium ${task.completed ? 'line-through text-gray-500' : 'text-[rgb(15,23,42)]'}`}>
                    {task.title}
                  </h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-sm text-gray-600">Assigned to:</span>
                    <span className="text-sm font-medium text-[rgb(34,139,34)]">
                      {assignedMember?.name || 'Unassigned'}
                    </span>
                  </div>
                  <span className="text-xs text-gray-500 mt-1 block">Due: {task.dueDate}</span>
                </div>
                <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                  task.category === 'food' ? 'bg-orange-100 text-orange-700' :
                  task.category === 'equipment' ? 'bg-blue-100 text-blue-700' :
                  'bg-purple-100 text-purple-700'
                }`}>
                  {task.category}
                </span>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )

  const renderMembersTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Members</h2>
        <button 
          onClick={() => setShowInviteModal(true)}
          className="p-2 bg-[rgb(34,139,34)] text-white rounded-lg shadow-md hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95"
        >
          <Plus className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-3">
        {tripMembers.map((member) => (
          <div
            key={member.id}
            className="p-4 bg-white border border-[rgb(226,232,240)] rounded-xl shadow-sm"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-medium">
                {member.name.charAt(0)}
              </div>
              <div className="flex-1">
                <h3 className="font-medium text-[rgb(15,23,42)]">{member.name}</h3>
                <span className="text-sm text-gray-600 capitalize">{member.role}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                  member.rsvpStatus === 'accepted' ? 'bg-green-100 text-green-700' :
                  member.rsvpStatus === 'declined' ? 'bg-red-100 text-red-700' :
                  'bg-yellow-100 text-yellow-700'
                }`}>
                  {member.rsvpStatus}
                </span>
                {member.rsvpStatus === 'pending' && (
                  <div className="flex gap-1">
                    <button
                      onClick={() => handleRSVP(member.id, 'accepted')}
                      className="px-2 py-1 bg-green-500 text-white text-xs rounded hover:bg-green-600 transition-colors duration-150"
                    >
                      ✓
                    </button>
                    <button
                      onClick={() => handleRSVP(member.id, 'declined')}
                      className="px-2 py-1 bg-[rgb(220, 38, 38)] text-white text-xs rounded hover:bg-[rgb(220, 38, 38)] transition-colors duration-150"
                    >
                      ✗
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )

  const renderChatTab = () => (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Chat</h2>

      <div className="bg-white border border-[rgb(226,232,240)] rounded-xl shadow-sm h-96 flex flex-col">
        <div className="flex-1 p-4 space-y-3 overflow-y-auto">
          {SAMPLE_MESSAGES.map((message) => (
            <div key={message.id} className="flex gap-3">
              <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium">
                {message.sender.charAt(0)}
              </div>
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <span className="font-medium text-sm text-[rgb(15,23,42)]">{message.sender}</span>
                  <span className="text-xs text-gray-500">{message.time}</span>
                </div>
                <p className="text-sm text-gray-700 mt-1">{message.content}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-[rgb(226,232,240)]">
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Type a message..."
              className="flex-1 px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/50 focus:border-[rgb(34,139,34)]"
            />
            <button className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95">
              Send
            </button>
          </div>
        </div>
      </div>
    </div>
  )

  return (
    <div className="min-h-screen bg-[rgb(248,250,252)]">
      {/* Header */}
      <div className="bg-white border-b border-[rgb(226,232,240)] px-4 py-3">
        <div className="flex items-center justify-between">
          <h1 className="text-lg font-semibold text-[rgb(15,23,42)]">Off-Road Trip Planner</h1>
          <div className="flex items-center gap-2">
            <button className="p-2 text-gray-600 hover:text-[rgb(34,139,34)] transition-colors duration-150">
              <Bell className="w-5 h-5" />
            </button>
            <button className="p-2 text-gray-600 hover:text-[rgb(34,139,34)] transition-colors duration-150">
              <Settings className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="p-4 pb-20">
        {activeTab === 'locations' && renderLocationsTab()}
        {activeTab === 'tasks' && renderTasksTab()}
        {activeTab === 'members' && renderMembersTab()}
        {activeTab === 'chat' && renderChatTab()}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-[rgb(226,232,240)] px-4 py-2">
        <div className="flex items-center justify-around">
          {[
            { id: 'locations', icon: MapPin, label: 'Locations' },
            { id: 'tasks', icon: CheckCircle, label: 'Tasks' },
            { id: 'members', icon: Users, label: 'Members' },
            { id: 'chat', icon: MessageCircle, label: 'Chat' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors duration-150 ${
                activeTab === tab.id 
                  ? 'text-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10' 
                  : 'text-gray-600 hover:text-[rgb(34,139,34)]'
              }`}
            >
              <tab.icon className="w-5 h-5" />
              <span className="text-xs font-medium">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Invite Modal */}
      {showInviteModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-sm">
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Invite Members</h3>
            <input
              type="email"
              placeholder="Enter email address"
              className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg mb-4 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/50 focus:border-[rgb(34,139,34)]"
            />
            <div className="flex gap-2">
              <button
                onClick={() => setShowInviteModal(false)}
                className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] text-gray-700 rounded-lg hover:bg-[rgb(255, 255, 255)] transition-colors duration-150"
              >
                Cancel
              </button>
              <button
                onClick={() => setShowInviteModal(false)}
                className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95"
              >
                Send Invite
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

