'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, Paperclip, Smile, MoreVertical, MapPin, Calendar, Users } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'location' | 'task' | 'system'
  metadata?: {
    location?: { name: string; coordinates: [number, number] }
    task?: { name: string; assignee: string; dueDate: string }
  }
}

interface GroupMember {
  id: string
  name: string
  avatar: string
  status: 'online' | 'offline' | 'away'
}

interface GroupChatProps {
  tripId?: string
  groupMembers?: GroupMember[]
  currentUserId?: string
  onSendMessage?: (message: Omit<Message, 'id' | 'timestamp'>) => void
  onLocationShare?: () => void
  onTaskCreate?: () => void
}

export function GroupChat({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  currentUserId = 'user-1',
  onSendMessage = () => console.log('Message sent'),
  onLocationShare = () => console.log('Location shared'),
  onTaskCreate = () => console.log('Task created')
}: GroupChatProps = {}) {
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [showQuickActions, setShowQuickActions] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const currentUser = groupMembers.find(member => member.id === currentUserId)

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Omit<Message, 'id' | 'timestamp'> = {
      userId: currentUserId,
      userName: currentUser?.name || 'You',
      userAvatar: currentUser?.avatar || '/api/placeholder/32/32',
      content: newMessage.trim(),
      type: 'text'
    }

    const fullMessage: Message = {
      ...message,
      id: `msg-${Date.now()}`,
      timestamp: new Date()
    }

    setMessages(prev => [...prev, fullMessage])
    setNewMessage('')
    onSendMessage(message)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleLocationShare = () => {
    const locationMessage: Message = {
      id: `msg-${Date.now()}`,
      userId: currentUserId,
      userName: currentUser?.name || 'You',
      userAvatar: currentUser?.avatar || '/api/placeholder/32/32',
      content: 'Shared current location',
      timestamp: new Date(),
      type: 'location',
      metadata: {
        location: {
          name: 'Moab Desert Trail',
          coordinates: [38.5733, -109.5498]
        }
      }
    }

    setMessages(prev => [...prev, locationMessage])
    setShowQuickActions(false)
    onLocationShare()
  }

  const handleTaskShare = () => {
    const taskMessage: Message = {
      id: `msg-${Date.now()}`,
      userId: currentUserId,
      userName: currentUser?.name || 'You',
      userAvatar: currentUser?.avatar || '/api/placeholder/32/32',
      content: 'Created a new task',
      timestamp: new Date(),
      type: 'task',
      metadata: {
        task: {
          name: 'Bring firewood for Saturday night',
          assignee: 'Mike Johnson',
          dueDate: 'Saturday 6:00 PM'
        }
      }
    }

    setMessages(prev => [...prev, taskMessage])
    setShowQuickActions(false)
    onTaskCreate()
  }

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    })
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    }
  }

  const renderMessage = (message: Message, index: number) => {
    const isCurrentUser = message.userId === currentUserId
    const showAvatar = index === 0 || messages[index - 1].userId !== message.userId
    const showDate = index === 0 || formatDate(messages[index - 1].timestamp) !== formatDate(message.timestamp)

    return (
      <div key={message.id} className="space-y-2">
        {showDate && (
          <div className="flex justify-center py-2">
            <span className="px-3 py-1 text-xs font-medium text-[rgb(15,23,42)] bg-[rgb(248,250,252)] rounded-full border border-[rgb(226,232,240)]">
              {formatDate(message.timestamp)}
            </span>
          </div>
        )}

        <div className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : ''}`}>
          {showAvatar && !isCurrentUser && (
            <img
              src={message.userAvatar}
              alt={message.userName}
              className="w-8 h-8 rounded-full border-2 border-[rgb(226,232,240)] flex-shrink-0"
            />
          )}

          <div className={`flex flex-col max-w-[75%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
            {showAvatar && !isCurrentUser && (
              <span className="text-sm font-medium text-[rgb(15,23,42)] mb-1">
                {message.userName}
              </span>
            )}

            <div className={`rounded-2xl px-4 py-2 ${
              isCurrentUser 
                ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)]' 
                : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)]'
            }`}>
              {message.type === 'location' && message.metadata?.location && (
                <div className="flex items-center gap-2 mb-2">
                  <MapPin className="w-4 h-4" />
                  <span className="font-medium">{message.metadata.location.name}</span>
                </div>
              )}

              {message.type === 'task' && message.metadata?.task && (
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4" />
                    <span className="font-medium">Task Created</span>
                  </div>
                  <div className="text-sm opacity-90">
                    <div>{message.metadata.task.name}</div>
                    <div>Assigned to: {message.metadata.task.assignee}</div>
                    <div>Due: {message.metadata.task.dueDate}</div>
                  </div>
                </div>
              )}

              <p className="text-sm leading-relaxed">{message.content}</p>
            </div>

            <span className={`text-xs text-[rgb(15,23,42)] opacity-60 mt-1 ${isCurrentUser ? 'text-right' : ''}`}>
              {formatTime(message.timestamp)}
            </span>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen bg-[rgb(255,255,255)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            {groupMembers.slice(0, 3).map((member) => (
              <div key={member.id} className="relative">
                <img
                  src={member.avatar}
                  alt={member.name}
                  className="w-8 h-8 rounded-full border-2 border-[rgb(255,255,255)]"
                />
                <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-[rgb(255,255,255)] ${
                  member.status === 'online' ? 'bg-[rgb(34,139,34)]' : 
                  member.status === 'away' ? 'bg-[rgb(255,140,0)]' : 'bg-[rgb(226,232,240)]'
                }`} />
              </div>
            ))}
            {groupMembers.length > 3 && (
              <div className="w-8 h-8 rounded-full bg-[rgb(248,250,252)] border-2 border-[rgb(255,255,255)] flex items-center justify-center">
                <span className="text-xs font-medium text-[rgb(15,23,42)]">+{groupMembers.length - 3}</span>
              </div>
            )}
          </div>
          <div>
            <h2 className="font-semibold text-[rgb(15,23,42)]">Trip Group</h2>
            <p className="text-sm text-[rgb(15,23,42)] opacity-60">
              {groupMembers.filter(m => m.status === 'online').length} online
            </p>
          </div>
        </div>

        <button
          className="p-2 rounded-full hover:bg-[rgb(248,250,252)] transition-colors duration-150"
          aria-label="More options"
        >
          <MoreVertical className="w-5 h-5 text-[rgb(15,23,42)]" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => renderMessage(message, index))}
        {isTyping && (
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-[rgb(248,250,252)] flex items-center justify-center">
              <div className="flex gap-1">
                <div className="w-1 h-1 bg-[rgb(15,23,42)] opacity-60 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                <div className="w-1 h-1 bg-[rgb(15,23,42)] opacity-60 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                <div className="w-1 h-1 bg-[rgb(15,23,42)] opacity-60 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
              </div>
            </div>
            <span className="text-sm text-[rgb(15,23,42)] opacity-60">Someone is typing...</span>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Quick Actions */}
      {showQuickActions && (
        <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(248,250,252)]">
          <div className="flex gap-3">
            <button
              onClick={handleLocationShare}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(255,255,255)] text-[rgb(15,23,42)] rounded-xl border border-[rgb(226,232,240)] hover:bg-[rgb(245,247,250)] transition-colors duration-150 shadow-sm"
            >
              <MapPin className="w-4 h-4" />
              <span className="text-sm font-medium">Share Location</span>
            </button>
            <button
              onClick={handleTaskShare}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(255,255,255)] text-[rgb(15,23,42)] rounded-xl border border-[rgb(226,232,240)] hover:bg-[rgb(245,247,250)] transition-colors duration-150 shadow-sm"
            >
              <Users className="w-4 h-4" />
              <span className="text-sm font-medium">Create Task</span>
            </button>
          </div>
        </div>
      )}

      {/* Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-[rgb(255,255,255)]">
        <div className="flex items-end gap-3">
          <button
            onClick={() => setShowQuickActions(!showQuickActions)}
            className="p-3 rounded-full hover:bg-[rgb(248,250,252)] transition-colors duration-150 flex-shrink-0"
            aria-label="Quick actions"
          >
            <Paperclip className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-2xl text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)] placeholder-opacity-60 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-opacity-20 transition-all duration-150 resize-none"
              style={{ minHeight: '44px' }}
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full hover:bg-[rgb(34,139,34)] hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 flex-shrink-0 shadow-md active:scale-95"
            style={{ minWidth: '44px', minHeight: '44px' }}
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

