'use client'

import { useState, useEffect } from 'react'
import { Users, UserPlus, Crown, Settings, Search, MoreVertical, Check, X, Mail, Calendar, MessageCircle } from 'lucide-react'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'leader' | 'member'
  status: 'active' | 'invited' | 'declined'
  joinedAt: string
  skills: string[]
  availability: {
    startDate: string
    endDate: string
  }
}

interface GroupManagementPanelProps {
  tripId?: string
  members?: GroupMember[]
  onInviteMember?: (email: string) => void
  onRemoveMember?: (memberId: string) => void
  onUpdateRole?: (memberId: string, role: 'leader' | 'member') => void
  onSendReminder?: (memberId: string) => void
  maxMembers?: number
}

export function GroupManagementPanel({
  tripId = 'trip-1',
  members = DEFAULT_MEMBERS,
  onInviteMember = (email: string) => console.log('Invite member:', email),
  onRemoveMember = (memberId: string) => console.log('Remove member:', memberId),
  onUpdateRole = (memberId: string, role: 'leader' | 'member') => console.log('Update role:', memberId, role),
  onSendReminder = (memberId: string) => console.log('Send reminder:', memberId),
  maxMembers = 12
}: GroupManagementPanelProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [showInviteForm, setShowInviteForm] = useState(false)
  const [inviteEmail, setInviteEmail] = useState('')
  const [selectedMember, setSelectedMember] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const filteredMembers = members.filter(member =>
    member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    member.email.toLowerCase().includes(searchQuery.toLowerCase())
  )

  const activeMembers = members.filter(m => m.status === 'active')
  const pendingInvites = members.filter(m => m.status === 'invited')

  const handleInvite = async () => {
    if (!inviteEmail.trim()) return

    setIsLoading(true)
    try {
      await onInviteMember(inviteEmail)
      setInviteEmail('')
      setShowInviteForm(false)
    } catch (error) {
      console.error('Failed to invite member:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const getRoleColor = (role: string) => {
    return role === 'leader' ? 'text-[rgb(255,140,0)]' : 'text-[rgb(100,116,139)]'
  }

  const getStatusBadge = (status: string) => {
    const baseClasses = 'px-2 py-1 rounded-full text-xs font-medium'
    switch (status) {
      case 'active':
        return `${baseClasses} bg-[rgb(34,139,34)] bg-opacity-10 text-[rgb(34,139,34)]`
      case 'invited':
        return `${baseClasses} bg-[rgb(255,140,0)] bg-opacity-10 text-[rgb(255,140,0)]`
      case 'declined':
        return `${baseClasses} bg-[rgb(220,38,38)] bg-opacity-10 text-[rgb(220,38,38)]`
      default:
        return `${baseClasses} bg-[rgb(248,250,252)] text-[rgb(100,116,139)]`
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] z-10">
        <div className="px-4 py-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <Users className="w-6 h-6 text-[rgb(34,139,34)]" />
              <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Management</h1>
            </div>
            <button
              onClick={() => setShowInviteForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)] hover:bg-opacity-90 transition-all duration-150 shadow-md active:scale-95"
              aria-label="Invite new member"
            >
              <UserPlus className="w-4 h-4" />
              <span className="hidden sm:inline">Invite</span>
            </button>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-3 mb-4">
            <div className="bg-[rgb(248,250,252)] rounded-lg p-3 text-center">
              <div className="text-lg font-semibold text-[rgb(15,23,42)]">{activeMembers.length}</div>
              <div className="text-xs text-[rgb(100,116,139)]">Active</div>
            </div>
            <div className="bg-[rgb(248,250,252)] rounded-lg p-3 text-center">
              <div className="text-lg font-semibold text-[rgb(15,23,42)]">{pendingInvites.length}</div>
              <div className="text-xs text-[rgb(100,116,139)]">Pending</div>
            </div>
            <div className="bg-[rgb(248,250,252)] rounded-lg p-3 text-center">
              <div className="text-lg font-semibold text-[rgb(15,23,42)]">{maxMembers - members.length}</div>
              <div className="text-xs text-[rgb(100,116,139)]">Available</div>
            </div>
          </div>

          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(100,116,139)]" />
            <input
              type="text"
              placeholder="Search members..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)] focus:ring-opacity-50 transition-all duration-150"
              aria-label="Search group members"
            />
          </div>
        </div>
      </div>

      {/* Member List */}
      <div className="px-4 py-4 space-y-3">
        {filteredMembers.map((member) => (
          <div
            key={member.id}
            className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm hover:shadow-md transition-all duration-200"
          >
            <div className="flex items-start justify-between">
              <div className="flex items-start gap-3 flex-1">
                {/* Avatar */}
                <div className="w-12 h-12 bg-[rgb(34,139,34)] bg-opacity-10 rounded-full flex items-center justify-center flex-shrink-0">
                  {member.avatar ? (
                    <img src={member.avatar} alt={member.name} className="w-12 h-12 rounded-full object-cover" />
                  ) : (
                    <span className="text-[rgb(34,139,34)] font-semibold text-lg">
                      {member.name.charAt(0).toUpperCase()}
                    </span>
                  )}
                </div>

                {/* Member Info */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="font-semibold text-[rgb(15,23,42)] truncate">{member.name}</h3>
                    {member.role === 'leader' && (
                      <Crown className="w-4 h-4 text-[rgb(255,140,0)]" />
                    )}
                  </div>
                  <p className="text-sm text-[rgb(100,116,139)] mb-2 truncate">{member.email}</p>

                  <div className="flex items-center gap-2 mb-2">
                    <span className={getStatusBadge(member.status)}>
                      {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                    </span>
                    <span className={`text-xs ${getRoleColor(member.role)}`}>
                      {member.role.charAt(0).toUpperCase() + member.role.slice(1)}
                    </span>
                  </div>

                  {/* Skills */}
                  {member.skills.length > 0 && (
                    <div className="flex flex-wrap gap-1 mb-2">
                      {member.skills.slice(0, 3).map((skill, index) => (
                        <span
                          key={index}
                          className="px-2 py-1 bg-[rgb(245,247,250)] text-[rgb(100,116,139)] rounded text-xs"
                        >
                          {skill}
                        </span>
                      ))}
                      {member.skills.length > 3 && (
                        <span className="px-2 py-1 bg-[rgb(245,247,250)] text-[rgb(100,116,139)] rounded text-xs">
                          +{member.skills.length - 3}
                        </span>
                      )}
                    </div>
                  )}

                  {/* Availability */}
                  <div className="text-xs text-[rgb(100,116,139)]">
                    Available: {new Date(member.availability.startDate).toLocaleDateString()} - {new Date(member.availability.endDate).toLocaleDateString()}
                  </div>
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 ml-2">
                {member.status === 'invited' && (
                  <button
                    onClick={() => onSendReminder(member.id)}
                    className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(255,140,0)] hover:bg-[rgb(255,140,0)] hover:bg-opacity-10 rounded-lg transition-all duration-150"
                    aria-label="Send reminder"
                  >
                    <Mail className="w-4 h-4" />
                  </button>
                )}

                <button
                  onClick={() => setSelectedMember(selectedMember === member.id ? null : member.id)}
                  className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] rounded-lg transition-all duration-150"
                  aria-label="More options"
                >
                  <MoreVertical className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Expanded Actions */}
            {selectedMember === member.id && (
              <div className="mt-4 pt-4 border-t border-[rgb(226,232,240)]">
                <div className="grid grid-cols-2 gap-2">
                  <button
                    onClick={() => {
                      onUpdateRole(member.id, member.role === 'leader' ? 'member' : 'leader')
                      setSelectedMember(null)
                    }}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] rounded-lg transition-all duration-150"
                  >
                    <Crown className="w-4 h-4" />
                    {member.role === 'leader' ? 'Remove Leader' : 'Make Leader'}
                  </button>

                  <button
                    onClick={() => {
                      onRemoveMember(member.id)
                      setSelectedMember(null)
                    }}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-[rgb(220,38,38)] hover:bg-[rgb(220,38,38)] hover:bg-opacity-10 rounded-lg transition-all duration-150"
                  >
                    <X className="w-4 h-4" />
                    Remove
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}

        {filteredMembers.length === 0 && (
          <div className="text-center py-12">
            <Users className="w-12 h-12 text-[rgb(100,116,139)] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No members found</h3>
            <p className="text-[rgb(100,116,139)] mb-4">Try adjusting your search or invite new members</p>
            <button
              onClick={() => setShowInviteForm(true)}
              className="px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)] hover:bg-opacity-90 transition-all duration-150"
            >
              Invite Members
            </button>
          </div>
        )}
      </div>

      {/* Invite Form Modal */}
      {showInviteForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-end sm:items-center justify-center z-50 p-4">
          <div className="bg-[rgb(255,255,255)] rounded-t-2xl sm:rounded-2xl w-full max-w-md max-h-[90vh] overflow-hidden">
            <div className="p-6">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Invite Member</h2>
                <button
                  onClick={() => setShowInviteForm(false)}
                  className="p-2 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] rounded-lg transition-all duration-150"
                  aria-label="Close invite form"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label htmlFor="invite-email" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Email Address
                  </label>
                  <input
                    id="invite-email"
                    type="email"
                    placeholder="Enter email address"
                    value={inviteEmail}
                    onChange={(e) => setInviteEmail(e.target.value)}
                    className="w-full px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)] focus:ring-opacity-50 transition-all duration-150"
                    disabled={isLoading}
                  />
                </div>

                <div className="flex gap-3">
                  <button
                    onClick={() => setShowInviteForm(false)}
                    className="flex-1 px-4 py-2.5 bg-[rgb(248,250,252)] text-[rgb(100,116,139)] rounded-lg hover:bg-[rgb(226,232,240)] transition-all duration-150"
                    disabled={isLoading}
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleInvite}
                    disabled={!inviteEmail.trim() || isLoading}
                    className="flex-1 px-4 py-2.5 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(34,139,34)] hover:bg-opacity-90 transition-all duration-150 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                  >
                    {isLoading ? (
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    ) : (
                      <>
                        <Mail className="w-4 h-4" />
                        Send Invite
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Actions */}
      <div className="fixed bottom-0 left-0 right-0 bg-[rgb(255,255,255)] border-t border-[rgb(226,232,240)] p-4">
        <div className="grid grid-cols-3 gap-3">
          <button className="flex flex-col items-center gap-1 py-3 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors duration-150">
            <Calendar className="w-5 h-5" />
            <span className="text-xs">Schedule</span>
          </button>
          <button className="flex flex-col items-center gap-1 py-3 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors duration-150">
            <MessageCircle className="w-5 h-5" />
            <span className="text-xs">Chat</span>
          </button>
          <button className="flex flex-col items-center gap-1 py-3 text-[rgb(100,116,139)] hover:text-[rgb(34,139,34)] transition-colors duration-150">
            <Settings className="w-5 h-5" />
            <span className="text-xs">Settings</span>
          </button>
        </div>
      </div>
    </div>
  )
}

