export function LocationSelector({
  onLocationSelect = () => {},
  onLocationSave = () => {},
  savedLocations = [],
  currentLocation,
  className = ''
}: LocationSelectorProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('')
  const [showFilters, setShowFilters] = useState(false)
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [isLoading, setIsLoading] = useState(false)
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null)

  const debouncedSearch = useCallback(
    debounce((query: string) => {
      setIsLoading(true)
      // Simulate API call
      setTimeout(() => {
        const filtered = MOCK_LOCATIONS.filter(location =>
          location.name.toLowerCase().includes(query.toLowerCase()) ||
          location.description.toLowerCase().includes(query.toLowerCase()) ||
          location.terrain.some(t => t.toLowerCase().includes(query.toLowerCase()))
        )
        setLocations(filtered)
        setIsLoading(false)
      }, 300)
    }, 300),
    []
  )

  useEffect(() => {
    if (searchQuery) {
      debouncedSearch(searchQuery)
    } else {
      setLocations(MOCK_LOCATIONS)
    }
  }, [searchQuery, debouncedSearch])

  const filteredLocations = selectedDifficulty
    ? locations.filter(location => location.difficulty === selectedDifficulty)
    : locations

  const toggleFavorite = (locationId: string) => {
    setLocations(prev =>
      prev.map(location =>
        location.id === locationId
          ? { ...location, isFavorite: !location.isFavorite }
          : location
      )
    )
  }

  const handleLocationSelect = (location: Location) => {
    setSelectedLocation(location)
    onLocationSelect(location)
  }

  const handleLocationSave = (location: Location) => {
    onLocationSave(location)
    // Show success feedback
    console.log('Location saved:', location.name)
  }

  return (
    <div className={`min-h-screen bg-[rgb(255,255,255)] ${className}`}>
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3">
        <div className="flex items-center gap-3 mb-3">
          <div className="flex items-center gap-2">
            <MapPin className="w-6 h-6 text-[rgb(34,139,34)]" />
            <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Select Location</h1>
          </div>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="ml-auto p-2 rounded-lg bg-[rgb(248,250,252)] hover:bg-[rgb(245,247,250)] transition-colors duration-150"
            aria-label="Toggle filters"
          >
            <Filter className="w-5 h-5 text-[rgb(15,23,42)]" />
          </button>
        </div>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search locations, terrain, features..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
            style={{ minHeight: '44px' }}
          />
        </div>

        {/* Filters */}
        {showFilters && (
          <div className="mt-3 p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-[rgb(15,23,42)]">Difficulty Level</span>
              {selectedDifficulty && (
                <button
                  onClick={() => setSelectedDifficulty('')}
                  className="text-xs text-[rgb(34,139,34)] hover:underline"
                >
                  Clear
                </button>
              )}
            </div>
            <div className="flex flex-wrap gap-2">
              {['Easy', 'Moderate', 'Hard', 'Expert'].map((difficulty) => (
                <button
                  key={difficulty}
                  onClick={() => setSelectedDifficulty(selectedDifficulty === difficulty ? '' : difficulty)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all duration-150 ${
                    selectedDifficulty === difficulty
                      ? DIFFICULTY_COLORS[difficulty as keyof typeof DIFFICULTY_COLORS]
                      : 'bg-white border border-[rgb(226,232,240)] text-[rgb(15,23,42)] hover:border-[rgb(34,139,34)]'
                  }`}
                  style={{ minHeight: '32px' }}
                >
                  {difficulty}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="px-4 py-4">
        {isLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-[rgb(248,250,252)] rounded-xl p-4 animate-pulse">
                <div className="flex gap-4">
                  <div className="w-20 h-20 bg-[rgb(226,232,240)] rounded-lg"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-[rgb(226,232,240)] rounded w-3/4"></div>
                    <div className="h-3 bg-[rgb(226,232,240)] rounded w-1/2"></div>
                    <div className="h-3 bg-[rgb(226,232,240)] rounded w-2/3"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : filteredLocations.length === 0 ? (
          <div className="text-center py-12">
            <MapPin className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-[rgb(15,23,42)] mb-2">No locations found</h3>
            <p className="text-gray-500 mb-4">Try adjusting your search or filters</p>
            <button
              onClick={() => {
                setSearchQuery('')
                setSelectedDifficulty('')
              }}
              className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium"
            >
              Clear Filters
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredLocations.map((location) => (
              <LocationCard
                key={location.id}
                location={location}
                onSelect={() => handleLocationSelect(location)}
                onSave={() => handleLocationSave(location)}
                onToggleFavorite={() => toggleFavorite(location.id)}
                isSelected={selectedLocation?.id === location.id}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

interface LocationCardProps {
  location: Location
  onSelect: () => void
  onSave: () => void
  onToggleFavorite: () => void
  isSelected: boolean
}

function LocationCard({ location, onSelect, onSave, onToggleFavorite, isSelected }: LocationCardProps) {
  return (
    <div
      className={`bg-white border rounded-xl p-4 transition-all duration-200 cursor-pointer ${
        isSelected
          ? 'border-[rgb(34,139,34)] shadow-lg shadow-[rgb(34,139,34)]/10'
          : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50 shadow-sm hover:shadow-md'
      }`}
      onClick={onSelect}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onSelect()
        }
      }}
      aria-label={`Select ${location.name}`}
    >
      <div className="flex gap-4">
        {/* Location Image */}
        <div className="w-20 h-20 bg-[rgb(248,250,252)] rounded-lg overflow-hidden flex-shrink-0">
          <div className="w-full h-full bg-gradient-to-br from-[rgb(34,139,34)]/20 to-[rgb(255,140,0)]/20 flex items-center justify-center">
            <Mountain className="w-8 h-8 text-[rgb(34,139,34)]" />
          </div>
        </div>

        {/* Location Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between mb-2">
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-[rgb(15,23,42)] truncate">{location.name}</h3>
              <div className="flex items-center gap-2 mt-1">
                <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${DIFFICULTY_COLORS[location.difficulty]}`}>
                  {location.difficulty}
                </span>
                {location.distance && (
                  <span className="text-xs text-gray-500">{location.distance} mi</span>
                )}
              </div>
            </div>
            <button
              onClick={(e) => {
                e.stopPropagation()
                onToggleFavorite()
              }}
              className="p-1 hover:bg-[rgb(248,250,252)] rounded transition-colors duration-150"
              aria-label={location.isFavorite ? 'Remove from favorites' : 'Add to favorites'}
            >
              <Heart
                className={`w-5 h-5 ${
                  location.isFavorite
                    ? 'fill-[rgb(220,38,38)] text-[rgb(220,38,38)]'
                    : 'text-gray-400 hover:text-[rgb(220,38,38)]'
                }`}
              />
            </button>
          </div>

          <p className="text-sm text-gray-600 mb-3 line-clamp-2">{location.description}</p>

          {/* Terrain Tags */}
          <div className="flex flex-wrap gap-1 mb-3">
            {location.terrain.slice(0, 3).map((terrain) => {
              const IconComponent = TERRAIN_ICONS[terrain as keyof typeof TERRAIN_ICONS] || Mountain
              return (
                <div
                  key={terrain}
                  className="flex items-center gap-1 px-2 py-1 bg-[rgb(248,250,252)] rounded text-xs text-[rgb(15,23,42)]"
                >
                  <IconComponent className="w-3 h-3" />
                  <span>{terrain}</span>
                </div>
              )
            })}
            {location.terrain.length > 3 && (
              <span className="px-2 py-1 bg-[rgb(248,250,252)] rounded text-xs text-gray-500">
                +{location.terrain.length - 3} more
              </span>
            )}
          </div>

          {/* Rating and Actions */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1">
              <Star className="w-4 h-4 fill-[rgb(255,140,0)] text-[rgb(255,140,0)]" />
              <span className="text-sm font-medium text-[rgb(15,23,42)]">{location.rating}</span>
              <span className="text-sm text-gray-500">({location.reviewCount})</span>
            </div>
            <button
              onClick={(e) => {
                e.stopPropagation()
                onSave()
              }}
              className="px-3 py-1.5 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 text-sm font-medium"
              style={{ minHeight: '32px' }}
            >
              Save
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

// Utility function for debouncing
function debounce<T extends (...args: any[]) => any>(func: T, wait: number): T {
  let timeout: NodeJS.Timeout
  return ((...args: any[]) => {
    clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }) as T
}

