                className={`w-full px-4 py-3 bg-white border rounded-lg text-left flex items-center justify-between focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                  errors.location ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-expanded={showLocationDropdown}
                aria-haspopup="listbox"
              >
                <div className="flex items-center">
                  <MapPin className="h-5 w-5 text-gray-400 mr-3" />
                  <span className={formData.location ? 'text-[rgb(15,23,42)]' : 'text-gray-400'}>
                    {formData.location ? formData.location.name : 'Select location'}
                  </span>
                </div>
                <ChevronDown className="h-5 w-5 text-gray-400" />
              </button>

              {showLocationDropdown && (
                <div className="absolute z-10 w-full mt-1 bg-white border border-[rgb(226,232,240)] rounded-lg shadow-lg max-h-60 overflow-auto">
                  {MOCK_LOCATIONS.map((location) => (
                    <button
                      key={location.id}
                      type="button"
                      onClick={() => {
                        setFormData(prev => ({ ...prev, location }))
                        setShowLocationDropdown(false)
                      }}
                      className="w-full px-4 py-3 text-left hover:bg-[rgb(248,250,252)] focus:bg-[rgb(248,250,252)] focus:outline-none transition-colors duration-150"
                    >
                      <div className="font-medium text-[rgb(15,23,42)]">{location.name}</div>
                      {location.description && (
                        <div className="text-sm text-gray-600 mt-1">{location.description}</div>
                      )}
                    </button>
                  ))}
                </div>
              )}
            </div>
            {errors.location && (
              <p className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                {errors.location}
              </p>
            )}
          </div>

          {/* Members */}
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Trip Members *
            </label>

            {/* Selected Members */}
            {formData.members.length > 0 && (
              <div className="mb-3 flex flex-wrap gap-2">
                {formData.members.map((member) => (
                  <div
                    key={member.id}
                    className="flex items-center gap-2 px-3 py-2 bg-[rgb(245,247,250)] rounded-lg border border-[rgb(226,232,240)]"
                  >
                    <div className="w-6 h-6 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-xs font-medium">
                      {member.name.charAt(0)}
                    </div>
                    <span className="text-sm text-[rgb(15,23,42)]">{member.name}</span>
                    <button
                      type="button"
                      onClick={() => removeMember(member.id)}
                      className="p-1 hover:bg-gray-200 rounded-full transition-colors duration-150"
                      aria-label={`Remove ${member.name}`}
                    >
                      <X className="h-3 w-3 text-gray-500" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Add Member Dropdown */}
            <div className="relative">
              <button
                type="button"
                onClick={() => setShowMemberDropdown(!showMemberDropdown)}
                className={`w-full px-4 py-3 bg-white border rounded-lg text-left flex items-center justify-between focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                  errors.members ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-expanded={showMemberDropdown}
                aria-haspopup="listbox"
              >
                <div className="flex items-center">
                  <Plus className="h-5 w-5 text-gray-400 mr-3" />
                  <span className="text-gray-400">Add members</span>
                </div>
                <ChevronDown className="h-5 w-5 text-gray-400" />
              </button>

              {showMemberDropdown && (
                <div className="absolute z-10 w-full mt-1 bg-white border border-[rgb(226,232,240)] rounded-lg shadow-lg max-h-60 overflow-auto">
                  {availableMembers
                    .filter(member => !formData.members.find(m => m.id === member.id))
                    .map((member) => (
                      <button
                        key={member.id}
                        type="button"
                        onClick={() => addMember(member)}
                        className="w-full px-4 py-3 text-left hover:bg-[rgb(248,250,252)] focus:bg-[rgb(248,250,252)] focus:outline-none transition-colors duration-150 flex items-center gap-3"
                      >
                        <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-medium">
                          {member.name.charAt(0)}
                        </div>
                        <div>
                          <div className="font-medium text-[rgb(15,23,42)]">{member.name}</div>
                          <div className="text-sm text-gray-600">{member.email}</div>
                        </div>
                      </button>
                    ))}
                </div>
              )}
            </div>
            {errors.members && (
              <p className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                {errors.members}
              </p>
            )}
          </div>

          {/* Difficulty */}
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Difficulty Level
            </label>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              {DIFFICULTY_OPTIONS.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, difficulty: option.value as any }))}
                  className={`px-3 py-2 rounded-lg text-sm font-medium transition-all duration-150 ${
                    formData.difficulty === option.value
                      ? `${option.color} ring-2 ring-offset-2 ring-[rgb(34,139,34)]`
                      : 'bg-[rgb(248, 250, 252)] text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          {/* Vehicle Requirements */}
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Vehicle Requirements
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {VEHICLE_OPTIONS.map((requirement) => (
                <label
                  key={requirement}
                  className="flex items-center gap-3 p-3 bg-[rgb(248,250,252)] rounded-lg cursor-pointer hover:bg-[rgb(248, 250, 252)] transition-colors duration-150"
                >
                  <input
                    type="checkbox"
                    checked={formData.vehicleRequirements.includes(requirement)}
                    onChange={() => toggleVehicleRequirement(requirement)}
                    className="w-4 h-4 text-[rgb(34,139,34)] border-gray-300 rounded focus:ring-[rgb(34,139,34)] focus:ring-2"
                  />
                  <span className="text-sm text-[rgb(15,23,42)]">{requirement}</span>
                </label>
              ))}
            </div>
          </div>

          {/* Estimated Cost */}
          <div>
            <label htmlFor="estimated-cost" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Estimated Cost per Person
            </label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400">$</span>
              <input
                id="estimated-cost"
                type="number"
                min="0"
                step="0.01"
                value={formData.estimatedCost || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, estimatedCost: parseFloat(e.target.value) || 0 }))}
                placeholder="0.00"
                className="w-full pl-8 pr-4 py-3 bg-white border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200"
              />
            </div>
          </div>

          {/* Submit Button */}
          <div className="pt-4">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full px-6 py-4 bg-[rgb(34,139,34)] text-white rounded-lg font-medium text-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[rgb(34,139,34)] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 shadow-md hover:shadow-lg active:scale-95"
            >
              {isSubmitting ? (
                <div className="flex items-center justify-center gap-2">
                  <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  Creating Trip...
                </div>
              ) : (
                'Create Trip'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

