'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar, MessageCircle } from 'lucide-react'

interface RSVPResponse {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  status: 'attending' | 'not-attending' | 'maybe' | 'pending'
  responseDate?: Date
  note?: string
}

interface TripEvent {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  description: string
  organizer: string
  maxAttendees?: number
}

interface RSVPComponentProps {
  event?: TripEvent
  currentUserId?: string
  responses?: RSVPResponse[]
  onRSVP?: (status: RSVPResponse['status'], note?: string) => void
  onSendReminder?: () => void
  isOrganizer?: boolean
}

