export function RSVPComponent({
  event = DEFAULT_EVENT,
  currentUserId = 'user5',
  responses = DEFAULT_RESPONSES,
  onRSVP = (status, note) => console.log('RSVP:', status, note),
  onSendReminder = () => console.log('Sending reminder'),
  isOrganizer = false
}: RSVPComponentProps = {}) {
  const [selectedStatus, setSelectedStatus] = useState<RSVPResponse['status'] | null>(null)
  const [note, setNote] = useState('')
  const [showNoteInput, setShowNoteInput] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const currentUserResponse = responses.find(r => r.userId === currentUserId)
  const attendingCount = responses.filter(r => r.status === 'attending').length
  const notAttendingCount = responses.filter(r => r.status === 'not-attending').length
  const maybeCount = responses.filter(r => r.status === 'maybe').length
  const pendingCount = responses.filter(r => r.status === 'pending').length

  useEffect(() => {
    if (currentUserResponse) {
      setSelectedStatus(currentUserResponse.status)
      setNote(currentUserResponse.note || '')
    }
  }, [currentUserResponse])

  const handleStatusSelect = (status: RSVPResponse['status']) => {
    setSelectedStatus(status)
    if (status === 'not-attending' || status === 'maybe') {
      setShowNoteInput(true)
    } else {
      setShowNoteInput(false)
      setNote('')
    }
  }

  const handleSubmit = async () => {
    if (!selectedStatus) return

    setIsSubmitting(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      onRSVP(selectedStatus, note || undefined)
      setShowNoteInput(false)
    } finally {
      setIsSubmitting(false)
    }
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    })
  }

  const getStatusColor = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending': return 'text-[rgb(34,139,34)]'
      case 'not-attending': return 'text-[rgb(220,38,38)]'
      case 'maybe': return 'text-[rgb(255,140,0)]'
      default: return 'text-[rgb(148,163,184)]'
    }
  }

  const getStatusBg = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending': return 'bg-[rgb(34,139,34)]/10 border-[rgb(34,139,34)]/20'
      case 'not-attending': return 'bg-[rgb(220,38,38)]/10 border-[rgb(220,38,38)]/20'
      case 'maybe': return 'bg-[rgb(255,140,0)]/10 border-[rgb(255,140,0)]/20'
      default: return 'bg-[rgb(248,250,252)] border-[rgb(226,232,240)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-md mx-auto">
        {/* Header */}
        <div className="bg-gradient-to-r from-[rgb(34,139,34)] to-[rgb(46,125,50)] text-[rgb(255,255,255)] p-6 pb-8">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 bg-[rgb(255,255,255)]/20 rounded-lg flex items-center justify-center">
              <Calendar className="w-5 h-5" />
            </div>
            <div>
              <h1 className="text-xl font-semibold">{event.title}</h1>
              <p className="text-[rgb(255,255,255)]/80 text-sm">Trip RSVP</p>
            </div>
          </div>

          <div className="space-y-2 text-sm">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4" />
              <span>{event.location}</span>
            </div>
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4" />
              <span>{formatDate(event.startDate)} - {formatDate(event.endDate)}</span>
            </div>
          </div>
        </div>

        {/* Event Description */}
        <div className="p-6 border-b border-[rgb(226,232,240)]">
          <p className="text-[rgb(15,23,42)] text-sm leading-relaxed">
            {event.description}
          </p>
        </div>

        {/* RSVP Status Summary */}
        <div className="p-6 border-b border-[rgb(226,232,240)]">
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Response Summary</h2>
          <div className="grid grid-cols-2 gap-3">
            <div className="bg-[rgb(34,139,34)]/10 border border-[rgb(34,139,34)]/20 rounded-lg p-3">
              <div className="flex items-center gap-2">
                <Check className="w-4 h-4 text-[rgb(34,139,34)]" />
                <span className="text-sm font-medium text-[rgb(15,23,42)]">Going</span>
              </div>
              <p className="text-xl font-bold text-[rgb(34,139,34)] mt-1">{attendingCount}</p>
            </div>
            <div className="bg-[rgb(220,38,38)]/10 border border-[rgb(220,38,38)]/20 rounded-lg p-3">
              <div className="flex items-center gap-2">
                <X className="w-4 h-4 text-[rgb(220,38,38)]" />
                <span className="text-sm font-medium text-[rgb(15,23,42)]">Can't Go</span>
              </div>
              <p className="text-xl font-bold text-[rgb(220,38,38)] mt-1">{notAttendingCount}</p>
            </div>
            <div className="bg-[rgb(255,140,0)]/10 border border-[rgb(255,140,0)]/20 rounded-lg p-3">
              <div className="flex items-center gap-2">
                <Clock className="w-4 h-4 text-[rgb(255,140,0)]" />
                <span className="text-sm font-medium text-[rgb(15,23,42)]">Maybe</span>
              </div>
              <p className="text-xl font-bold text-[rgb(255,140,0)] mt-1">{maybeCount}</p>
            </div>
            <div className="bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg p-3">
              <div className="flex items-center gap-2">
                <Users className="w-4 h-4 text-[rgb(148,163,184)]" />
                <span className="text-sm font-medium text-[rgb(15,23,42)]">Pending</span>
              </div>
              <p className="text-xl font-bold text-[rgb(148,163,184)] mt-1">{pendingCount}</p>
            </div>
          </div>
        </div>

        {/* Your Response */}
        {!currentUserResponse?.status && (
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Your Response</h2>

            <div className="space-y-3 mb-4">
              <button
                onClick={() => handleStatusSelect('attending')}
                className={`w-full p-4 rounded-lg border-2 transition-all duration-200 ${
                  selectedStatus === 'attending'
                    ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10'
                    : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(34,139,34)]/50'
                }`}
                aria-label="RSVP as attending"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                    selectedStatus === 'attending'
                      ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]'
                      : 'border-[rgb(226,232,240)]'
                  }`}>
                    {selectedStatus === 'attending' && <Check className="w-3 h-3 text-[rgb(255,255,255)]" />}
                  </div>
                  <div className="text-left">
                    <p className="font-medium text-[rgb(15,23,42)]">I'll be there!</p>
                    <p className="text-sm text-[rgb(100,116,139)]">Count me in for this adventure</p>
                  </div>
                </div>
              </button>

              <button
                onClick={() => handleStatusSelect('maybe')}
                className={`w-full p-4 rounded-lg border-2 transition-all duration-200 ${
                  selectedStatus === 'maybe'
                    ? 'border-[rgb(255,140,0)] bg-[rgb(255,140,0)]/10'
                    : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(255,140,0)]/50'
                }`}
                aria-label="RSVP as maybe attending"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                    selectedStatus === 'maybe'
                      ? 'border-[rgb(255,140,0)] bg-[rgb(255,140,0)]'
                      : 'border-[rgb(226,232,240)]'
                  }`}>
                    {selectedStatus === 'maybe' && <Clock className="w-3 h-3 text-[rgb(255,255,255)]" />}
                  </div>
                  <div className="text-left">
                    <p className="font-medium text-[rgb(15,23,42)]">Maybe</p>
                    <p className="text-sm text-[rgb(100,116,139)]">Need to check my schedule</p>
                  </div>
                </div>
              </button>

              <button
                onClick={() => handleStatusSelect('not-attending')}
                className={`w-full p-4 rounded-lg border-2 transition-all duration-200 ${
                  selectedStatus === 'not-attending'
                    ? 'border-[rgb(220,38,38)] bg-[rgb(220,38,38)]/10'
                    : 'border-[rgb(226,232,240)] bg-[rgb(255,255,255)] hover:border-[rgb(220,38,38)]/50'
                }`}
                aria-label="RSVP as not attending"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                    selectedStatus === 'not-attending'
                      ? 'border-[rgb(220,38,38)] bg-[rgb(220,38,38)]'
                      : 'border-[rgb(226,232,240)]'
                  }`}>
                    {selectedStatus === 'not-attending' && <X className="w-3 h-3 text-[rgb(255,255,255)]" />}
                  </div>
                  <div className="text-left">
                    <p className="font-medium text-[rgb(15,23,42)]">Can't make it</p>
                    <p className="text-sm text-[rgb(100,116,139)]">Won't be able to attend</p>
                  </div>
                </div>
              </button>
            </div>

            {showNoteInput && (
              <div className="mb-4">
                <label htmlFor="rsvp-note" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Add a note (optional)
                </label>
                <textarea
                  id="rsvp-note"
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="Let the group know why or share any details..."
                  className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(148,163,184)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200"
                  rows={3}
                />
              </div>
            )}

            {selectedStatus && (
              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="w-full bg-[rgb(34,139,34)] text-[rgb(255,255,255)] py-3 px-4 rounded-lg font-medium hover:bg-[rgb(46,125,50)] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/50 focus:ring-offset-2"
              >
                {isSubmitting ? 'Submitting...' : 'Submit Response'}
              </button>
            )}
          </div>
        )}

        {/* Current User Response Display */}
        {currentUserResponse?.status && (
          <div className="p-6 border-b border-[rgb(226,232,240)]">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Your Response</h2>
            <div className={`p-4 rounded-lg border ${getStatusBg(currentUserResponse.status)}`}>
              <div className="flex items-center gap-3 mb-2">
                {currentUserResponse.status === 'attending' && <Check className="w-5 h-5 text-[rgb(34,139,34)]" />}
                {currentUserResponse.status === 'not-attending' && <X className="w-5 h-5 text-[rgb(220,38,38)]" />}
                {currentUserResponse.status === 'maybe' && <Clock className="w-5 h-5 text-[rgb(255,140,0)]" />}
                <span className={`font-medium ${getStatusColor(currentUserResponse.status)}`}>
                  {currentUserResponse.status === 'attending' && "You're going!"}
                  {currentUserResponse.status === 'not-attending' && "You can't make it"}
                  {currentUserResponse.status === 'maybe' && "You might attend"}
                </span>
              </div>
              {currentUserResponse.note && (
                <p className="text-sm text-[rgb(100,116,139)] italic">"{currentUserResponse.note}"</p>
              )}
              <button
                onClick={() => setSelectedStatus(null)}
                className="text-sm text-[rgb(34,139,34)] hover:text-[rgb(46,125,50)] mt-2 font-medium"
              >
                Change response
              </button>
            </div>
          </div>
        )}

        {/* Responses List */}
        <div className="p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">All Responses</h2>
            {isOrganizer && pendingCount > 0 && (
              <button
                onClick={onSendReminder}
                className="text-sm text-[rgb(34,139,34)] hover:text-[rgb(46,125,50)] font-medium flex items-center gap-1"
              >
                <MessageCircle className="w-4 h-4" />
                Send Reminder
              </button>
            )}
          </div>

          <div className="space-y-3">
            {responses.map((response) => (
              <div
                key={response.id}
                className="flex items-center gap-3 p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]"
              >
                <div className="w-10 h-10 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-full flex items-center justify-center font-medium text-sm">
                  {response.userAvatar}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <p className="font-medium text-[rgb(15,23,42)] truncate">{response.userName}</p>
                    <div className="flex items-center gap-1">
                      {response.status === 'attending' && <Check className="w-4 h-4 text-[rgb(34,139,34)]" />}
                      {response.status === 'not-attending' && <X className="w-4 h-4 text-[rgb(220,38,38)]" />}
                      {response.status === 'maybe' && <Clock className="w-4 h-4 text-[rgb(255,140,0)]" />}
                      {response.status === 'pending' && <Clock className="w-4 h-4 text-[rgb(148,163,184)]" />}
                      <span className={`text-xs font-medium ${getStatusColor(response.status)}`}>
                        {response.status === 'attending' && 'Going'}
                        {response.status === 'not-attending' && 'Not going'}
                        {response.status === 'maybe' && 'Maybe'}
                        {response.status === 'pending' && 'Pending'}
                      </span>
                    </div>
                  </div>
                  {response.note && (
                    <p className="text-xs text-[rgb(100,116,139)] italic truncate">"{response.note}"</p>
                  )}
                  {response.responseDate && (
                    <p className="text-xs text-[rgb(148,163,184)] mt-1">
                      {response.responseDate.toLocaleDateString()}
                    </p>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

