'use client'

import { useState, useEffect } from 'react'
import { CheckCircle2, Circle, User, Calendar, MessageSquare, Plus, X, Edit3, Trash2 } from 'lucide-react'

interface Task {
  id: string
  title: string
  description: string
  assignedTo: string[]
  dueDate: string
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other'
  completed: boolean
  priority: 'low' | 'medium' | 'high'
  createdAt: string
}

interface GroupMember {
  id: string
  name: string
  avatar?: string
  email: string
  role: 'organizer' | 'member'
}

interface TaskAssignmentToolProps {
  tripId?: string
  tasks?: Task[]
  members?: GroupMember[]
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt'>) => void
  onTaskUpdate?: (taskId: string, updates: Partial<Task>) => void
  onTaskDelete?: (taskId: string) => void
  currentUserId?: string
}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', email: 'alex@example.com', role: 'organizer' },
  { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', role: 'member' },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', role: 'member' },
  { id: '4', name: 'Emma Davis', email: 'emma@example.com', role: 'member' }
]

const DEFAULT_TASKS: Task[] = [
  {
    id: '1',
    title: 'Bring lunch for Saturday',
    description: 'Pack sandwiches and snacks for the group',
    assignedTo: ['1', '2'],
    dueDate: '2024-01-15',
    category: 'food',
    completed: false,
    priority: 'high',
    createdAt: '2024-01-10T10:00:00Z'
  },
  {
    id: '2',
    title: 'Collect firewood',
    description: 'Gather dry wood for evening campfire',
    assignedTo: ['3'],
    dueDate: '2024-01-15',
    category: 'logistics',
    completed: true,
    priority: 'medium',
    createdAt: '2024-01-10T11:00:00Z'
  },
  {
    id: '3',
    title: 'First aid kit check',
    description: 'Verify all medical supplies are stocked',
    assignedTo: ['4'],
    dueDate: '2024-01-14',
    category: 'safety',
    completed: false,
    priority: 'high',
    createdAt: '2024-01-10T12:00:00Z'
  }
]

const TASK_CATEGORIES = [
  { value: 'food', label: 'Food & Meals', color: 'bg-orange-100 text-orange-800' },
  { value: 'equipment', label: 'Equipment', color: 'bg-blue-100 text-blue-800' },
  { value: 'logistics', label: 'Logistics', color: 'bg-purple-100 text-purple-800' },
  { value: 'safety', label: 'Safety', color: 'bg-red-100 text-red-800' },
  { value: 'other', label: 'Other', color: 'bg-[rgb(248, 250, 252)] text-gray-800' }
]

const PRIORITY_COLORS = {
  low: 'border-l-gray-300',
  medium: 'border-l-yellow-400',
  high: 'border-l-red-400'
}

export function TaskAssignmentTool({
  tripId = 'trip-1',
  tasks = DEFAULT_TASKS,
  members = DEFAULT_MEMBERS,
  onTaskCreate = () => console.log('Task created'),
  onTaskUpdate = () => console.log('Task updated'),
  onTaskDelete = () => console.log('Task deleted'),
  currentUserId = '1'
}: TaskAssignmentToolProps = {}) {
  const [localTasks, setLocalTasks] = useState<Task[]>(tasks)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingTask, setEditingTask] = useState<string | null>(null)
  const [filter, setFilter] = useState<'all' | 'assigned' | 'completed' | 'pending'>('all')
  const [categoryFilter, setCategoryFilter] = useState<string>('all')

  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    assignedTo: [] as string[],
    dueDate: '',
    category: 'other' as Task['category'],
    priority: 'medium' as Task['priority']
  })

  useEffect(() => {
    setLocalTasks(tasks)
  }, [tasks])

  const handleCreateTask = () => {
    if (!newTask.title.trim()) return

    const task: Task = {
      id: Date.now().toString(),
      ...newTask,
      completed: false,
      createdAt: new Date().toISOString()
    }

    setLocalTasks(prev => [task, ...prev])
    onTaskCreate(newTask)
    setNewTask({
      title: '',
      description: '',
      assignedTo: [],
      dueDate: '',
      category: 'other',
      priority: 'medium'
    })
    setShowCreateForm(false)
  }

  const handleToggleComplete = (taskId: string) => {
    setLocalTasks(prev => prev.map(task => 
      task.id === taskId 
        ? { ...task, completed: !task.completed }
        : task
    ))
    const task = localTasks.find(t => t.id === taskId)
    if (task) {
      onTaskUpdate(taskId, { completed: !task.completed })
    }
  }

  const handleDeleteTask = (taskId: string) => {
    setLocalTasks(prev => prev.filter(task => task.id !== taskId))
    onTaskDelete(taskId)
  }

  const handleAssignMember = (taskId: string, memberId: string) => {
    setLocalTasks(prev => prev.map(task => {
      if (task.id === taskId) {
        const assignedTo = task.assignedTo.includes(memberId)
          ? task.assignedTo.filter(id => id !== memberId)
          : [...task.assignedTo, memberId]
        return { ...task, assignedTo }
      }
      return task
    }))
  }

  const filteredTasks = localTasks.filter(task => {
    if (filter === 'assigned' && !task.assignedTo.includes(currentUserId)) return false
    if (filter === 'completed' && !task.completed) return false
    if (filter === 'pending' && task.completed) return false
    if (categoryFilter !== 'all' && task.category !== categoryFilter) return false
    return true
  })

  const getMemberName = (memberId: string) => {
    return members.find(m => m.id === memberId)?.name || 'Unknown'
  }

  const getCategoryInfo = (category: string) => {
    return TASK_CATEGORIES.find(c => c.value === category) || TASK_CATEGORIES[4]
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[#0f172a] mb-2">Task Assignment</h1>
          <p className="text-[#64748b]">Organize and assign tasks for your off-road adventure</p>
        </div>

        {/* Filters */}
        <div className="mb-6 space-y-4">
          <div className="flex flex-wrap gap-2">
            {[
              { value: 'all', label: 'All Tasks' },
              { value: 'assigned', label: 'My Tasks' },
              { value: 'pending', label: 'Pending' },
              { value: 'completed', label: 'Completed' }
            ].map(option => (
              <button
                key={option.value}
                onClick={() => setFilter(option.value as any)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                  filter === option.value
                    ? 'bg-[#228b22] text-[#ffffff] shadow-md'
                    : 'bg-[#f8fafc] text-[#64748b] hover:bg-[#f1f5f9]'
                }`}
                aria-label={`Filter by ${option.label}`}
              >
                {option.label}
              </button>
            ))}
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setCategoryFilter('all')}
              className={`px-3 py-1 rounded-full text-xs font-medium transition-all duration-200 ${
                categoryFilter === 'all'
                  ? 'bg-[#228b22] text-[#ffffff]'
                  : 'bg-[#f8fafc] text-[#64748b] hover:bg-[#f1f5f9]'
              }`}
            >
              All Categories
            </button>
            {TASK_CATEGORIES.map(category => (
              <button
                key={category.value}
                onClick={() => setCategoryFilter(category.value)}
                className={`px-3 py-1 rounded-full text-xs font-medium transition-all duration-200 ${
                  categoryFilter === category.value
                    ? 'bg-[#228b22] text-[#ffffff]'
                    : `${category.color} hover:opacity-80`
                }`}
              >
                {category.label}
              </button>
            ))}
          </div>
        </div>

        {/* Create Task Button */}
        <button
          onClick={() => setShowCreateForm(true)}
          className="w-full mb-6 p-4 border-2 border-dashed border-[#e2e8f0] rounded-xl text-[#64748b] hover:border-[#228b22] hover:text-[#228b22] transition-all duration-200 flex items-center justify-center gap-2"
          aria-label="Create new task"
        >
          <Plus className="w-5 h-5" />
          <span>Add New Task</span>
        </button>

        {/* Create Task Form */}
        {showCreateForm && (
          <div className="mb-6 bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-[#0f172a]">Create New Task</h3>
              <button
                onClick={() => setShowCreateForm(false)}
                className="p-2 text-[#64748b] hover:text-[#0f172a] transition-colors duration-200"
                aria-label="Close create task form"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[#0f172a] mb-2">Task Title</label>
                <input
                  type="text"
                  value={newTask.title}
                  onChange={(e) => setNewTask(prev => ({ ...prev, title: e.target.value }))}
                  className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-200"
                  placeholder="Enter task title..."
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0f172a] mb-2">Description</label>
                <textarea
                  value={newTask.description}
                  onChange={(e) => setNewTask(prev => ({ ...prev, description: e.target.value }))}
                  className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-200 resize-none"
                  rows={3}
                  placeholder="Task description..."
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Category</label>
                  <select
                    value={newTask.category}
                    onChange={(e) => setNewTask(prev => ({ ...prev, category: e.target.value as Task['category'] }))}
                    className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-200"
                  >
                    {TASK_CATEGORIES.map(category => (
                      <option key={category.value} value={category.value}>
                        {category.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Priority</label>
                  <select
                    value={newTask.priority}
                    onChange={(e) => setNewTask(prev => ({ ...prev, priority: e.target.value as Task['priority'] }))}
                    className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-200"
                  >
                    <option value="low">Low</option>
                    <option value="medium">Medium</option>
                    <option value="high">High</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0f172a] mb-2">Due Date</label>
                  <input
                    type="date"
                    value={newTask.dueDate}
                    onChange={(e) => setNewTask(prev => ({ ...prev, dueDate: e.target.value }))}
                    className="w-full px-4 py-3 border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-200"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0f172a] mb-2">Assign Members</label>
                <div className="flex flex-wrap gap-2">
                  {members.map(member => (
                    <button
                      key={member.id}
                      onClick={() => {
                        const assignedTo = newTask.assignedTo.includes(member.id)
                          ? newTask.assignedTo.filter(id => id !== member.id)
                          : [...newTask.assignedTo, member.id]
                        setNewTask(prev => ({ ...prev, assignedTo }))
                      }}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-all duration-200 flex items-center gap-2 ${
                        newTask.assignedTo.includes(member.id)
                          ? 'bg-[#228b22] text-[#ffffff] shadow-md'
                          : 'bg-[#f8fafc] text-[#64748b] hover:bg-[#f1f5f9]'
                      }`}
                    >
                      <User className="w-4 h-4" />
                      {member.name}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={handleCreateTask}
                  disabled={!newTask.title.trim()}
                  className="flex-1 px-6 py-3 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7b1e] disabled:bg-[#94a3b8] disabled:cursor-not-allowed transition-all duration-200 font-medium shadow-md hover:shadow-lg active:scale-95"
                >
                  Create Task
                </button>
                <button
                  onClick={() => setShowCreateForm(false)}
                  className="px-6 py-3 bg-[#f8fafc] text-[#64748b] rounded-lg hover:bg-[#f1f5f9] transition-all duration-200 font-medium"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Tasks List */}
        <div className="space-y-4">
          {filteredTasks.length === 0 ? (
            <div className="text-center py-12">
              <Calendar className="w-12 h-12 text-[#94a3b8] mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-[#0f172a] mb-2">No tasks found</h3>
              <p className="text-[#64748b]">
                {filter === 'all' ? 'Create your first task to get started' : 'No tasks match your current filter'}
              </p>
            </div>
          ) : (
            filteredTasks.map(task => {
              const categoryInfo = getCategoryInfo(task.category)
              const isOverdue = new Date(task.dueDate) < new Date() && !task.completed

              return (
                <div
                  key={task.id}
                  className={`bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-md hover:shadow-lg transition-all duration-200 ${PRIORITY_COLORS[task.priority]} border-l-4`}
                >
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-start gap-3 flex-1">
                      <button
                        onClick={() => handleToggleComplete(task.id)}
                        className="mt-1 text-[#228b22] hover:text-[#1e7b1e] transition-colors duration-200"
                        aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
                      >
                        {task.completed ? (
                          <CheckCircle2 className="w-6 h-6" />
                        ) : (
                          <Circle className="w-6 h-6" />
                        )}
                      </button>

                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <h3 className={`text-lg font-semibold ${task.completed ? 'text-[#94a3b8] line-through' : 'text-[#0f172a]'}`}>
                            {task.title}
                          </h3>
                          <span className={`px-2 py-1 rounded-full text-xs font-medium ${categoryInfo.color}`}>
                            {categoryInfo.label}
                          </span>
                          {isOverdue && (
                            <span className="px-2 py-1 bg-red-100 text-red-800 rounded-full text-xs font-medium">
                              Overdue
                            </span>
                          )}
                        </div>

                        {task.description && (
                          <p className={`text-sm mb-3 ${task.completed ? 'text-[#94a3b8]' : 'text-[#64748b]'}`}>
                            {task.description}
                          </p>
                        )}

                        <div className="flex flex-wrap items-center gap-4 text-sm text-[#64748b]">
                          {task.dueDate && (
                            <div className="flex items-center gap-1">
                              <Calendar className="w-4 h-4" />
                              <span>{new Date(task.dueDate).toLocaleDateString()}</span>
                            </div>
                          )}

                          <div className="flex items-center gap-1">
                            <span className={`w-2 h-2 rounded-full ${
                              task.priority === 'high' ? 'bg-red-400' :
                              task.priority === 'medium' ? 'bg-yellow-400' : 'bg-gray-400'
                            }`} />
                            <span className="capitalize">{task.priority} priority</span>
                          </div>
                        </div>

                        {task.assignedTo.length > 0 && (
                          <div className="mt-3">
                            <div className="flex flex-wrap gap-2">
                              {task.assignedTo.map(memberId => (
                                <div
                                  key={memberId}
                                  className="flex items-center gap-2 px-3 py-1 bg-[#f8fafc] rounded-lg text-sm"
                                >
                                  <User className="w-4 h-4 text-[#64748b]" />
                                  <span className="text-[#0f172a]">{getMemberName(memberId)}</span>
                                  <button
                                    onClick={() => handleAssignMember(task.id, memberId)}
                                    className="text-[#94a3b8] hover:text-[#dc2626] transition-colors duration-200"
                                    aria-label={`Remove ${getMemberName(memberId)} from task`}
                                  >
                                    <X className="w-3 h-3" />
                                  </button>
                                </div>
                              ))}
                            </div>

                            <div className="mt-2">
                              <details className="group">
                                <summary className="text-sm text-[#228b22] cursor-pointer hover:text-[#1e7b1e] transition-colors duration-200">
                                  Assign more members
                                </summary>
                                <div className="mt-2 flex flex-wrap gap-2">
                                  {members
                                    .filter(member => !task.assignedTo.includes(member.id))
                                    .map(member => (
                                      <button
                                        key={member.id}
                                        onClick={() => handleAssignMember(task.id, member.id)}
                                        className="px-3 py-1 bg-[#f8fafc] text-[#64748b] rounded-lg text-sm hover:bg-[#228b22] hover:text-[#ffffff] transition-all duration-200 flex items-center gap-2"
                                      >
                                        <Plus className="w-3 h-3" />
                                        {member.name}
                                      </button>
                                    ))}
                                </div>
                              </details>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center gap-2 ml-4">
                      <button
                        onClick={() => setEditingTask(editingTask === task.id ? null : task.id)}
                        className="p-2 text-[#64748b] hover:text-[#228b22] transition-colors duration-200"
                        aria-label="Edit task"
                      >
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDeleteTask(task.id)}
                        className="p-2 text-[#64748b] hover:text-[#dc2626] transition-colors duration-200"
                        aria-label="Delete task"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                </div>
              )
            })
          )}
        </div>

        {/* Quick Stats */}
        <div className="mt-8 grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 text-center shadow-md">
            <div className="text-2xl font-bold text-[#228b22]">{localTasks.length}</div>
            <div className="text-sm text-[#64748b]">Total Tasks</div>
          </div>
          <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 text-center shadow-md">
            <div className="text-2xl font-bold text-[#ff8c00]">{localTasks.filter(t => !t.completed).length}</div>
            <div className="text-sm text-[#64748b]">Pending</div>
          </div>
          <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 text-center shadow-md">
            <div className="text-2xl font-bold text-[#228b22]">{localTasks.filter(t => t.completed).length}</div>
            <div className="text-sm text-[#64748b]">Completed</div>
          </div>
          <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 text-center shadow-md">
            <div className="text-2xl font-bold text-[#dc2626]">
              {localTasks.filter(t => new Date(t.dueDate) < new Date() && !t.completed).length}
            </div>
            <div className="text-sm text-[#64748b]">Overdue</div>
          </div>
        </div>
      </div>
    </div>
  )
}

