}

interface MealPlannerProps {
  tripId?: string
  groupMembers?: GroupMember[]
  existingMeals?: Meal[]
  onMealUpdate?: (meals: Meal[]) => void
  onAssignMember?: (mealId: string, memberId: string) => void
}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', dietary: ['vegetarian'] },
  { id: '2', name: 'Sarah Johnson', dietary: [] },
  { id: '3', name: 'Mike Rodriguez', dietary: ['gluten-free'] },
  { id: '4', name: 'Emma Davis', dietary: ['dairy-free'] }
]

const DEFAULT_MEALS: Meal[] = [
  {
    id: '1',
    name: 'Campfire Pancakes',
    type: 'breakfast',
    date: '2024-03-15',
    time: '08:00',
    assignedTo: ['1', '2'],
    ingredients: ['Pancake mix', 'Eggs', 'Milk', 'Butter', 'Syrup'],
    servings: 8,
    difficulty: 'easy',
    cookingTime: 30,
    notes: 'Prep batter the night before'
  },
  {
    id: '2',
    name: 'Trail Sandwiches',
    type: 'lunch',
    date: '2024-03-15',
    time: '12:30',
    assignedTo: ['3'],
    ingredients: ['Bread', 'Turkey', 'Cheese', 'Lettuce', 'Tomatoes'],
    servings: 8,
    difficulty: 'easy',
    cookingTime: 15
  },
  {
    id: '3',
    name: 'Dutch Oven Chili',
    type: 'dinner',
    date: '2024-03-15',
    time: '18:00',
    assignedTo: ['4'],
    ingredients: ['Ground beef', 'Beans', 'Tomatoes', 'Onions', 'Spices'],
    servings: 8,
    difficulty: 'medium',
    cookingTime: 90
  }
]

export function MealPlanner({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  existingMeals = DEFAULT_MEALS,
  onMealUpdate = () => {},
  onAssignMember = () => {}
}: MealPlannerProps = {}) {
  const [meals, setMeals] = useState<Meal[]>(existingMeals)
  const [selectedDate, setSelectedDate] = useState('2024-03-15')
  const [showAddMeal, setShowAddMeal] = useState(false)
  const [editingMeal, setEditingMeal] = useState<Meal | null>(null)
  const [activeTab, setActiveTab] = useState<'schedule' | 'shopping' | 'assignments'>('schedule')

  const [newMeal, setNewMeal] = useState<Partial<Meal>>({
    name: '',
    type: 'breakfast',
    date: selectedDate,
    time: '08:00',
    assignedTo: [],
    ingredients: [],
    servings: 4,
    difficulty: 'easy',
    cookingTime: 30
  })

  useEffect(() => {
    onMealUpdate(meals)
  }, [meals, onMealUpdate])

  const getMealsByDate = (date: string) => {
    return meals.filter(meal => meal.date === date).sort((a, b) => a.time.localeCompare(b.time))
  }

  const getMealTypeIcon = (type: string) => {
    switch (type) {
      case 'breakfast': return '🌅'
      case 'lunch': return '☀️'
      case 'dinner': return '🌙'
      case 'snack': return '🥨'
      default: return '🍽️'
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-[#22C55E] text-white'
      case 'medium': return 'bg-[#FF8C00] text-white'
      case 'hard': return 'bg-[#DC2626] text-white'
      default: return 'bg-[#6B7280] text-white'
    }
  }

  const addMeal = () => {
    if (!newMeal.name) return

    const meal: Meal = {
      id: Date.now().toString(),
      name: newMeal.name,
      type: newMeal.type || 'breakfast',
      date: newMeal.date || selectedDate,
      time: newMeal.time || '08:00',
      assignedTo: newMeal.assignedTo || [],
      ingredients: newMeal.ingredients || [],
      servings: newMeal.servings || 4,
      difficulty: newMeal.difficulty || 'easy',
      cookingTime: newMeal.cookingTime || 30,
      notes: newMeal.notes
    }

    setMeals(prev => [...prev, meal])
    setNewMeal({
      name: '',
      type: 'breakfast',
      date: selectedDate,
      time: '08:00',
      assignedTo: [],
      ingredients: [],
      servings: 4,
      difficulty: 'easy',
      cookingTime: 30
    })
    setShowAddMeal(false)
  }

  const deleteMeal = (mealId: string) => {
    setMeals(prev => prev.filter(meal => meal.id !== mealId))
  }

  const assignMemberToMeal = (mealId: string, memberId: string) => {
    setMeals(prev => prev.map(meal => {
      if (meal.id === mealId) {
        const isAssigned = meal.assignedTo.includes(memberId)
        return {
          ...meal,
          assignedTo: isAssigned 
            ? meal.assignedTo.filter(id => id !== memberId)
            : [...meal.assignedTo, memberId]
        }
      }
      return meal
    }))
    onAssignMember(mealId, memberId)
  }

  const getAllIngredients = () => {
    const ingredients = new Map<string, number>()
    meals.forEach(meal => {
      meal.ingredients.forEach(ingredient => {
        ingredients.set(ingredient, (ingredients.get(ingredient) || 0) + 1)
      })
    })
    return Array.from(ingredients.entries()).map(([name, count]) => ({ name, count }))
  }

  const getUnassignedMeals = () => {
    return meals.filter(meal => meal.assignedTo.length === 0)
  }

  const tripDates = ['2024-03-15', '2024-03-16', '2024-03-17']

  return (
    <div className="min-h-screen bg-[#FFFFFF] font-medium">
      {/* Header */}
      <div className="bg-[#228B22] text-white p-4 shadow-md">
        <div className="flex items-center gap-3">
          <ChefHat className="w-6 h-6" />
          <div>
            <h1 className="text-xl font-semibold">Meal Planner</h1>
            <p className="text-sm opacity-90">Plan meals for your off-road adventure</p>
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="bg-white border-b border-[#E2E8F0] px-4">
        <div className="flex space-x-6">
          {[
            { id: 'schedule', label: 'Schedule', icon: Calendar },
            { id: 'shopping', label: 'Shopping', icon: MapPin },
            { id: 'assignments', label: 'Tasks', icon: Users }
          ].map(tab => {
            const Icon = tab.icon
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 py-3 px-1 border-b-2 transition-colors ${
                  activeTab === tab.id
                    ? 'border-[#228B22] text-[#228B22]'
                    : 'border-transparent text-[#64748B] hover:text-[#0F172A]'
                }`}
                aria-label={`Switch to ${tab.label} tab`}
              >
                <Icon className="w-4 h-4" />
                <span className="text-sm font-medium">{tab.label}</span>
              </button>
            )
          })}
        </div>
      </div>

      <div className="p-4 pb-20">
        {/* Schedule Tab */}
        {activeTab === 'schedule' && (
          <div className="space-y-4">
            {/* Date Selector */}
            <div className="flex gap-2 overflow-x-auto pb-2">
              {tripDates.map(date => (
                <button
                  key={date}
                  onClick={() => setSelectedDate(date)}
                  className={`flex-shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                    selectedDate === date
                      ? 'bg-[#228B22] text-white'
                      : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#F1F5F9]'
                  }`}
                  aria-label={`Select date ${date}`}
                >
                  {new Date(date).toLocaleDateString('en-US', { 
                    weekday: 'short', 
                    month: 'short', 
                    day: 'numeric' 
                  })}
                </button>
              ))}
            </div>

            {/* Meals for Selected Date */}
            <div className="space-y-3">
              {getMealsByDate(selectedDate).map(meal => (
                <div key={meal.id} className="bg-white border border-[#E2E8F0] rounded-lg p-4 shadow-sm">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-lg">{getMealTypeIcon(meal.type)}</span>
                        <h3 className="font-semibold text-[#0F172A]">{meal.name}</h3>
                        <span className={`px-2 py-1 rounded-full text-xs ${getDifficultyColor(meal.difficulty)}`}>
                          {meal.difficulty}
                        </span>
                      </div>

                      <div className="flex items-center gap-4 text-sm text-[#64748B] mb-2">
                        <div className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          <span>{meal.time}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Users className="w-4 h-4" />
                          <span>{meal.servings} servings</span>
                        </div>
                        <span>{meal.cookingTime} min</span>
                      </div>

                      {/* Assigned Members */}
                      <div className="flex flex-wrap gap-2 mb-2">
                        {meal.assignedTo.map(memberId => {
                          const member = groupMembers.find(m => m.id === memberId)
                          return member ? (
                            <span key={memberId} className="px-2 py-1 bg-[#228B22] text-white rounded-full text-xs">
                              {member.name}
                            </span>
                          ) : null
                        })}
                        {meal.assignedTo.length === 0 && (
                          <span className="px-2 py-1 bg-[#DC2626] text-white rounded-full text-xs">
                            Unassigned
                          </span>
                        )}
                      </div>

                      {/* Ingredients Preview */}
                      <div className="text-xs text-[#64748B]">
                        {meal.ingredients.slice(0, 3).join(', ')}
                        {meal.ingredients.length > 3 && ` +${meal.ingredients.length - 3} more`}
                      </div>
                    </div>

                    <div className="flex gap-2">
                      <button
                        onClick={() => setEditingMeal(meal)}
                        className="p-2 text-[#64748B] hover:text-[#228B22] hover:bg-[#F8FAFC] rounded-lg transition-colors"
                        aria-label={`Edit ${meal.name}`}
                      >
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => deleteMeal(meal.id)}
                        className="p-2 text-[#64748B] hover:text-[#DC2626] hover:bg-[#FEF2F2] rounded-lg transition-colors"
                        aria-label={`Delete ${meal.name}`}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                </div>
              ))}

              {getMealsByDate(selectedDate).length === 0 && (
                <div className="text-center py-8 text-[#64748B]">
                  <ChefHat className="w-12 h-12 mx-auto mb-3 opacity-50" />
                  <p>No meals planned for this date</p>
                  <p className="text-sm">Add your first meal below</p>
                </div>
              )}
            </div>

            {/* Add Meal Button */}
            <button
              onClick={() => setShowAddMeal(true)}
              className="w-full flex items-center justify-center gap-2 py-3 bg-[#228B22] text-white rounded-lg hover:bg-[#1E7B1E] transition-colors shadow-md"
              aria-label="Add new meal"
            >
              <Plus className="w-5 h-5" />
              <span>Add Meal</span>
            </button>
          </div>
        )}

        {/* Shopping Tab */}
        {activeTab === 'shopping' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[#0F172A]">Shopping List</h2>
            <div className="space-y-2">
              {getAllIngredients().map(({ name, count }, index) => (
                <div key={index} className="flex items-center justify-between p-3 bg-white border border-[#E2E8F0] rounded-lg">
                  <span className="text-[#0F172A]">{name}</span>
                  <span className="px-2 py-1 bg-[#F8FAFC] text-[#64748B] rounded-full text-sm">
                    {count} meal{count > 1 ? 's' : ''}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Assignments Tab */}
        {activeTab === 'assignments' && (
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-[#0F172A]">Task Assignments</h2>

            {/* Unassigned Meals Alert */}
            {getUnassignedMeals().length > 0 && (
              <div className="p-3 bg-[#FEF2F2] border border-[#FECACA] rounded-lg">
                <p className="text-[#DC2626] text-sm font-medium">
                  {getUnassignedMeals().length} meal{getUnassignedMeals().length > 1 ? 's' : ''} need assignment
                </p>
              </div>
            )}

            {/* Meals by Member */}
            {groupMembers.map(member => {
              const memberMeals = meals.filter(meal => meal.assignedTo.includes(member.id))
              return (
                <div key={member.id} className="bg-white border border-[#E2E8F0] rounded-lg p-4">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-semibold text-[#0F172A]">{member.name}</h3>
                    <span className="px-2 py-1 bg-[#F8FAFC] text-[#64748B] rounded-full text-sm">
                      {memberMeals.length} task{memberMeals.length !== 1 ? 's' : ''}
                    </span>
                  </div>

                  {member.dietary && member.dietary.length > 0 && (
                    <div className="mb-3">
                      <div className="flex flex-wrap gap-1">
                        {member.dietary.map(diet => (
                          <span key={diet} className="px-2 py-1 bg-[#FF8C00] text-white rounded-full text-xs">
                            {diet}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  <div className="space-y-2">
                    {memberMeals.map(meal => (
                      <div key={meal.id} className="flex items-center justify-between p-2 bg-[#F8FAFC] rounded">
                        <div>
                          <span className="text-sm font-medium text-[#0F172A]">{meal.name}</span>
                          <span className="text-xs text-[#64748B] ml-2">
                            {new Date(meal.date).toLocaleDateString()} at {meal.time}
                          </span>
                        </div>
                        <button
                          onClick={() => assignMemberToMeal(meal.id, member.id)}
                          className="text-xs text-[#DC2626] hover:bg-[#FEF2F2] px-2 py-1 rounded"
                          aria-label={`Remove ${member.name} from ${meal.name}`}
                        >
                          Remove
                        </button>
                      </div>
                    ))}

                    {memberMeals.length === 0 && (
                      <p className="text-sm text-[#64748B]">No tasks assigned</p>
                    )}
                  </div>
                </div>
              )
            })}

            {/* Quick Assignment */}
            <div className="bg-white border border-[#E2E8F0] rounded-lg p-4">
              <h3 className="font-semibold text-[#0F172A] mb-3">Quick Assignment</h3>
              {getUnassignedMeals().map(meal => (
                <div key={meal.id} className="mb-3 last:mb-0">
                  <div className="text-sm font-medium text-[#0F172A] mb-2">{meal.name}</div>
                  <div className="flex flex-wrap gap-2">
                    {groupMembers.map(member => (
                      <button
                        key={member.id}
                        onClick={() => assignMemberToMeal(meal.id, member.id)}
                        className="px-3 py-1 bg-[#F8FAFC] text-[#64748B] hover:bg-[#228B22] hover:text-white rounded-full text-sm transition-colors"
                        aria-label={`Assign ${meal.name} to ${member.name}`}
                      >
                        {member.name}
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Add Meal Modal */}
      {showAddMeal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-end justify-center z-50">
          <div className="bg-white w-full max-w-md rounded-t-xl p-4 max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-[#0F172A]">Add New Meal</h2>
              <button
                onClick={() => setShowAddMeal(false)}
                className="p-2 text-[#64748B] hover:bg-[#F8FAFC] rounded-lg"
                aria-label="Close add meal dialog"
              >
                ×
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[#0F172A] mb-1">Meal Name</label>
                <input
                  type="text"
                  value={newMeal.name || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  placeholder="Enter meal name"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-[#0F172A] mb-1">Type</label>
                  <select
                    value={newMeal.type || 'breakfast'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, type: e.target.value as any }))}
                    className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  >
                    <option value="breakfast">Breakfast</option>
                    <option value="lunch">Lunch</option>
                    <option value="dinner">Dinner</option>
                    <option value="snack">Snack</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0F172A] mb-1">Time</label>
                  <input
                    type="time"
                    value={newMeal.time || '08:00'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, time: e.target.value }))}
                    className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-[#0F172A] mb-1">Servings</label>
                  <input
                    type="number"
                    value={newMeal.servings || 4}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, servings: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                    min="1"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#0F172A] mb-1">Difficulty</label>
                  <select
                    value={newMeal.difficulty || 'easy'}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, difficulty: e.target.value as any }))}
                    className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  >
                    <option value="easy">Easy</option>
                    <option value="medium">Medium</option>
                    <option value="hard">Hard</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0F172A] mb-1">Cooking Time (minutes)</label>
                <input
                  type="number"
                  value={newMeal.cookingTime || 30}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, cookingTime: parseInt(e.target.value) }))}
                  className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  min="5"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0F172A] mb-1">Ingredients</label>
                <textarea
                  value={newMeal.ingredients?.join(', ') || ''}
                  onChange={(e) => setNewMeal(prev => ({ 
                    ...prev, 
                    ingredients: e.target.value.split(',').map(i => i.trim()).filter(i => i) 
                  }))}
                  className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  placeholder="Enter ingredients separated by commas"
                  rows={3}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#0F172A] mb-1">Notes (optional)</label>
                <textarea
                  value={newMeal.notes || ''}
                  onChange={(e) => setNewMeal(prev => ({ ...prev, notes: e.target.value }))}
                  className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg focus:ring-2 focus:ring-[#228B22] focus:border-transparent"
                  placeholder="Any special instructions or notes"
                  rows={2}
                />
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => setShowAddMeal(false)}
                  className="flex-1 py-2 px-4 border border-[#E2E8F0] text-[#64748B] rounded-lg hover:bg-[#F8FAFC] transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={addMeal}
                  disabled={!newMeal.name}
                  className="flex-1 py-2 px-4 bg-[#228B22] text-white rounded-lg hover:bg-[#1E7B1E] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  Add Meal
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default function MealPlannerDemo() {
  return <MealPlanner />
}

