'use client'

import { useState, useEffect } from 'react'
import { 
  Map, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  Settings,
  Menu,
  X,
  Home,
  Plus
} from 'lucide-react'

interface AppLayoutProps {
  children?: React.ReactNode;
  currentPage?: string;
  onNavigate?: (page: string) => void;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  href: string;
  badge?: number;
}

const navigationItems: NavigationItem[] = [
  { id: 'trips', label: 'Trips', icon: Map, href: '/trips' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'group', label: 'Group', icon: Users, href: '/group' },
  { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat', badge: 3 },
  { id: 'meals', label: 'Meals', icon: UtensilsCrossed, href: '/meals' }
];

export function AppLayout({
  children,
  currentPage = 'trips',
  onNavigate = (page) => console.log('Navigate to:', page)
}: AppLayoutProps = {}) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isOnline, setIsOnline] = useState(true);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleNavigation = (item: NavigationItem) => {
    onNavigate(item.id);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="min-h-screen bg-white font-medium">
      {/* Offline Indicator */}
      {!isOnline && (
        <div className="bg-[rgb(220,38,38)] text-white px-4 py-2 text-center text-sm font-medium">
          You're offline. Some features may be limited.
        </div>
      )}

      {/* Header */}
      <header className="bg-white border-b border-[rgb(226,232,240)] sticky top-0 z-40">
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden p-2 -ml-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors duration-150"
              aria-label="Toggle menu"
            >
              {isMobileMenuOpen ? (
                <X className="w-5 h-5 text-[rgb(15,23,42)]" />
              ) : (
                <Menu className="w-5 h-5 text-[rgb(15,23,42)]" />
              )}
