'use client'

import { useState, useEffect } from 'react'
import { User, Shield, CheckCircle, AlertCircle, Settings, Key, Mail, Lock } from 'lucide-react'

interface AuthUser {
  id: string
  email: string
  name: string
  avatar?: string
  role: 'admin' | 'member'
  lastLogin: string
  isVerified: boolean
}

interface AuthConfig {
  providers: string[]
  requireEmailVerification: boolean
  sessionTimeout: number
  mfaEnabled: boolean
}

interface UserAuthSetupProps {
  onUserChange?: (user: AuthUser | null) => void
  onConfigUpdate?: (config: AuthConfig) => void
  initialUser?: AuthUser | null
  initialConfig?: AuthConfig
}

export function UserAuthSetup({
  onUserChange = () => {},
  onConfigUpdate = () => {},
  initialUser = null,
  initialConfig = DEFAULT_CONFIG
}: UserAuthSetupProps = {}) {
  const [currentUser, setCurrentUser] = useState<AuthUser | null>(initialUser)
  const [authConfig, setAuthConfig] = useState<AuthConfig>(initialConfig)
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'profile' | 'security' | 'settings'>('profile')
  const [showSuccess, setShowSuccess] = useState(false)

  const handleSignIn = async (email: string, password: string) => {
    setIsLoading(true)
    // Simulate authentication
    setTimeout(() => {
      const user: AuthUser = {
        id: '1',
        email,
        name: email.split('@')[0],
        role: 'admin',
        lastLogin: new Date().toISOString(),
        isVerified: true
      }
      setCurrentUser(user)
      onUserChange(user)
      setIsLoading(false)
      setShowSuccess(true)
      setTimeout(() => setShowSuccess(false), 3000)
    }, 1500)
  }

  const handleSignOut = () => {
    setCurrentUser(null)
    onUserChange(null)
  }

  const updateConfig = (updates: Partial<AuthConfig>) => {
    const newConfig = { ...authConfig, ...updates }
    setAuthConfig(newConfig)
    onConfigUpdate(newConfig)
  }

  if (!currentUser) {
    return <SignInForm onSignIn={handleSignIn} isLoading={isLoading} />
  }

  return (
    <div className="min-h-screen bg-[#ffffff]" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-[#228b22] rounded-xl flex items-center justify-center">
                <Shield className="w-6 h-6 text-[#ffffff]" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[#0f172a]">Authentication Setup</h1>
                <p className="text-[#64748b] text-sm">Manage your account security and preferences</p>
              </div>
            </div>
            <button
              onClick={handleSignOut}
              className="px-4 py-2 bg-[#dc2626] text-[#ffffff] rounded-lg hover:bg-[#b91c1c] transition-colors duration-150 font-medium text-sm"
            >
              Sign Out
            </button>
          </div>

          {showSuccess && (
            <div className="bg-[#228b22]/10 border border-[#228b22]/20 rounded-lg p-4 mb-6">
              <div className="flex items-center gap-2">
                <CheckCircle className="w-5 h-5 text-[#228b22]" />
                <span className="text-[#228b22] font-medium">Authentication successful!</span>
              </div>
            </div>
          )}
        </div>

        {/* Navigation Tabs */}
        <div className="flex gap-1 mb-8 bg-[#f1f5f9] p-1 rounded-lg">
          {[
            { id: 'profile', label: 'Profile', icon: User },
            { id: 'security', label: 'Security', icon: Lock },
            { id: 'settings', label: 'Settings', icon: Settings }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-md font-medium text-sm transition-all duration-150 ${
                activeTab === id
                  ? 'bg-[#ffffff] text-[#228b22] shadow-sm'
                  : 'text-[#64748b] hover:text-[#0f172a]'
              }`}
            >
              <Icon className="w-4 h-4" />
              {label}
            </button>
          ))}
        </div>

        {/* Content */}
        {activeTab === 'profile' && (
          <ProfileTab user={currentUser} />
        )}

        {activeTab === 'security' && (
          <SecurityTab config={authConfig} onConfigUpdate={updateConfig} />
        )}

        {activeTab === 'settings' && (
          <SettingsTab config={authConfig} onConfigUpdate={updateConfig} />
        )}
      </div>
    </div>
  )
}

function SignInForm({ onSignIn, isLoading }: { onSignIn: (email: string, password: string) => void, isLoading: boolean }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (email && password) {
      onSignIn(email, password)
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] flex items-center justify-center px-4" style={{ fontFamily: 'Inter, system-ui, sans-serif' }}>
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-[#228b22] rounded-2xl flex items-center justify-center mx-auto mb-4">
            <Shield className="w-8 h-8 text-[#ffffff]" />
          </div>
          <h1 className="text-3xl font-bold text-[#0f172a] mb-2">Welcome Back</h1>
          <p className="text-[#64748b]">Sign in to access your off-road trip planner</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-2">Email</label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[#64748b]" />
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-[#e2e8f0] rounded-lg focus:ring-2 focus:ring-[#228b22] focus:border-[#228b22] outline-none transition-all duration-150"
                placeholder="Enter your email"
                required
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-2">Password</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[#64748b]" />
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-[#e2e8f0] rounded-lg focus:ring-2 focus:ring-[#228b22] focus:border-[#228b22] outline-none transition-all duration-150"
                placeholder="Enter your password"
                required
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={isLoading || !email || !password}
            className="w-full py-3 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7e1e] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 font-medium flex items-center justify-center gap-2"
          >
            {isLoading ? (
              <>
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                Signing In...
              </>
            ) : (
              'Sign In'
            )}
          </button>
        </form>

        <div className="mt-8 text-center">
          <p className="text-sm text-[#64748b]">
            Demo credentials: any email and password
          </p>
        </div>
      </div>
    </div>
  )
}

function ProfileTab({ user }: { user: AuthUser }) {
  return (
    <div className="space-y-6">
      <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-sm">
        <h2 className="text-xl font-semibold text-[#0f172a] mb-6">Profile Information</h2>

        <div className="flex items-center gap-4 mb-6">
          <div className="w-16 h-16 bg-[#228b22] rounded-full flex items-center justify-center">
            <User className="w-8 h-8 text-[#ffffff]" />
          </div>
          <div>
            <h3 className="text-lg font-medium text-[#0f172a]">{user.name}</h3>
            <p className="text-[#64748b]">{user.email}</p>
            <div className="flex items-center gap-2 mt-1">
              <CheckCircle className="w-4 h-4 text-[#228b22]" />
              <span className="text-sm text-[#228b22]">Verified Account</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="p-4 bg-[#f8fafc] rounded-lg">
            <div className="text-sm text-[#64748b] mb-1">Role</div>
            <div className="font-medium text-[#0f172a] capitalize">{user.role}</div>
          </div>
          <div className="p-4 bg-[#f8fafc] rounded-lg">
            <div className="text-sm text-[#64748b] mb-1">Last Login</div>
            <div className="font-medium text-[#0f172a]">
              {new Date(user.lastLogin).toLocaleDateString()}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function SecurityTab({ config, onConfigUpdate }: { config: AuthConfig, onConfigUpdate: (updates: Partial<AuthConfig>) => void }) {
  return (
    <div className="space-y-6">
      <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-sm">
        <h2 className="text-xl font-semibold text-[#0f172a] mb-6">Security Settings</h2>

        <div className="space-y-4">
          <div className="flex items-center justify-between p-4 bg-[#f8fafc] rounded-lg">
            <div>
              <h3 className="font-medium text-[#0f172a]">Email Verification</h3>
              <p className="text-sm text-[#64748b]">Require email verification for new accounts</p>
            </div>
            <button
              onClick={() => onConfigUpdate({ requireEmailVerification: !config.requireEmailVerification })}
              className={`w-12 h-6 rounded-full transition-colors duration-150 ${
                config.requireEmailVerification ? 'bg-[#228b22]' : 'bg-[#e2e8f0]'
              }`}
            >
              <div className={`w-5 h-5 bg-white rounded-full transition-transform duration-150 ${
                config.requireEmailVerification ? 'translate-x-6' : 'translate-x-0.5'
