          </div>

          <div className="flex items-center justify-between p-4 bg-[#f8fafc] rounded-lg">
            <div>
              <h3 className="font-medium text-[#0f172a]">Multi-Factor Authentication</h3>
              <p className="text-sm text-[#64748b]">Add an extra layer of security</p>
            </div>
            <button
              onClick={() => onConfigUpdate({ mfaEnabled: !config.mfaEnabled })}
              className={`w-12 h-6 rounded-full transition-colors duration-150 ${
                config.mfaEnabled ? 'bg-[#228b22]' : 'bg-[#e2e8f0]'
              }`}
            >
              <div className={`w-5 h-5 bg-white rounded-full transition-transform duration-150 ${
