'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Users, MapPin, Calendar } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignUp?: (email: string, password: string, name: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignUp = (email, password, name) => console.log('Sign up:', { email, password, name }),
  onForgotPassword = (email) => console.log('Forgot password:', email)
}: LoginPageProps = {}) {
  const [isLogin, setIsLogin] = useState(true)
  const [showPassword, setShowPassword] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  })
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setIsLoading(true)

    try {
      if (isLogin) {
        await onLogin(formData.email, formData.password)
      } else {
        await onSignUp(formData.email, formData.password, formData.name)
      }
    } catch (err) {
      setError(isLogin ? 'Invalid email or password' : 'Failed to create account')
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (!formData.email) {
      setError('Please enter your email address first')
      return
    }
    onForgotPassword(formData.email)
    setError('')
  }

  const features = [
    {
      icon: MapPin,
      title: 'Location Planning',
      description: 'Save and organize your favorite off-road destinations'
    },
    {
      icon: Users,
      title: 'Group Management',
      description: 'Assign tasks and coordinate with your adventure crew'
    },
    {
      icon: Calendar,
      title: 'Trip Scheduling',
      description: 'Integrate calendars and send invites to your group'
    }
  ]

  return (
    <div className="min-h-screen bg-[#ffffff] flex flex-col">
      {/* Header */}
      <div className="bg-gradient-to-r from-[#228b22] to-[#32cd32] px-4 py-6 text-center">
        <div className="flex items-center justify-center gap-3 mb-2">
          <Mountain className="h-8 w-8 text-[#ffffff]" />
          <h1 className="text-2xl font-bold text-[#ffffff]">TrailPlan</h1>
        </div>
        <p className="text-[#ffffff]/90 text-sm font-medium">
          Plan epic off-road adventures with your crew
        </p>
      </div>

      {/* Features Preview */}
      <div className="px-4 py-6 bg-[#f8fafc]">
        <div className="grid grid-cols-1 gap-4 max-w-md mx-auto">
          {features.map((feature, index) => (
            <div key={index} className="flex items-center gap-3 p-3 bg-[#ffffff] rounded-lg shadow-sm border border-[#e2e8f0]">
              <div className="p-2 bg-[#228b22]/10 rounded-lg">
                <feature.icon className="h-5 w-5 text-[#228b22]" />
              </div>
              <div>
                <h3 className="font-semibold text-[#0f172a] text-sm">{feature.title}</h3>
                <p className="text-xs text-[#64748b] leading-relaxed">{feature.description}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Login Form */}
      <div className="flex-1 px-4 py-6">
        <div className="max-w-sm mx-auto">
          <div className="bg-[#ffffff] rounded-xl shadow-lg border border-[#e2e8f0] p-6">
            <div className="text-center mb-6">
              <h2 className="text-xl font-bold text-[#0f172a] mb-2">
                {isLogin ? 'Welcome Back' : 'Join TrailPlan'}
              </h2>
              <p className="text-sm text-[#64748b]">
                {isLogin ? 'Sign in to plan your next adventure' : 'Create your account to get started'}
              </p>
            </div>

            {error && (
              <div className="mb-4 p-3 bg-[#dc2626]/10 border border-[#dc2626]/20 rounded-lg">
                <p className="text-sm text-[#dc2626] font-medium">{error}</p>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
              {!isLogin && (
                <div>
                  <label htmlFor="name" className="block text-sm font-medium text-[#0f172a] mb-2">
                    Full Name
                  </label>
                  <input
                    id="name"
                    type="text"
                    required={!isLogin}
                    value={formData.name}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                    placeholder="Enter your full name"
                  />
                </div>
              )}

              <div>
                <label htmlFor="email" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Email Address
                </label>
                <input
                  id="email"
                  type="email"
                  required
                  value={formData.email}
                  onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                  className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                  placeholder="Enter your email"
                />
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Password
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    required
                    value={formData.password}
                    onChange={(e) => setFormData(prev => ({ ...prev, password: e.target.value }))}
                    className="w-full px-4 py-3 pr-12 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                    placeholder="Enter your password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#64748b] hover:text-[#0f172a] transition-colors duration-150"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? (
                      <EyeOff className="h-5 w-5" />
                    ) : (
                      <Eye className="h-5 w-5" />
                    )}
                  </button>
                </div>
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7a1e] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 font-semibold text-sm shadow-md hover:shadow-lg active:scale-95"
              >
                {isLoading ? 'Please wait...' : (isLogin ? 'Sign In' : 'Create Account')}
              </button>
            </form>

            {isLogin && (
              <button
                onClick={handleForgotPassword}
                className="w-full mt-3 text-sm text-[#228b22] hover:text-[#1e7a1e] font-medium transition-colors duration-150"
              >
                Forgot your password?
              </button>
            )}

            <div className="mt-6 pt-6 border-t border-[#e2e8f0] text-center">
              <p className="text-sm text-[#64748b]">
                {isLogin ? "Don't have an account?" : 'Already have an account?'}
              </p>
              <button
                onClick={() => {
                  setIsLogin(!isLogin)
                  setError('')
                  setFormData({ name: '', email: '', password: '' })
                }}
                className="mt-2 text-sm text-[#228b22] hover:text-[#1e7a1e] font-semibold transition-colors duration-150"
              >
                {isLogin ? 'Create Account' : 'Sign In'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="px-4 py-6 bg-[#f8fafc] border-t border-[#e2e8f0]">
        <div className="max-w-sm mx-auto text-center">
          <p className="text-xs text-[#64748b] leading-relaxed">
            By continuing, you agree to our Terms of Service and Privacy Policy
          </p>
        </div>
      </div>
    </div>
  )
}

export default function LoginPageDemo() {
  return <LoginPage />
}

code.data-model:
'use client'

import { useState } from 'react'
import { Database, Table, Key, Link, FileText, Users, Calendar, MapPin, MessageSquare, Utensils, Cloud } from 'lucide-react'

interface TableSchema {
  id: string
  name: string
  description: string
  fields: Field[]
  relationships: Relationship[]
}

interface Field {
  id: string
  name: string
  type: string
  required: boolean
  description: string
}

interface Relationship {
  id: string
  type: 'one-to-one' | 'one-to-many' | 'many-to-many'
  target: string
  description: string
}

interface DatabaseSchemaProps {
  tables?: TableSchema[]
  onTableSelect?: (tableId: string) => void
  showRelationships?: boolean
}

export function DatabaseSchema({
  tables = DEFAULT_TABLES,
  onTableSelect = () => console.log('Table selected'),
  showRelationships = true
}: DatabaseSchemaProps = {}) {
  const [selectedTable, setSelectedTable] = useState<string | null>(null)
  const [viewMode, setViewMode] = useState<'visual' | 'list'>('visual')

  const handleTableClick = (tableId: string) => {
    setSelectedTable(selectedTable === tableId ? null : tableId)
    onTableSelect(tableId)
  }

  const getTableIcon = (tableName: string) => {
    const iconMap: Record<string, any> = {
      'trips': MapPin,
      'users': Users,
      'tasks': FileText,
      'rsvps': Calendar,
      'messages': MessageSquare,
      'meals': Utensils,
      'weather': Cloud,
      'locations': MapPin,
      'invites': Calendar
    }

    const IconComponent = iconMap[tableName.toLowerCase()] || Table
    return <IconComponent className="w-5 h-5" />
  }

  const getFieldTypeColor = (type: string) => {
    const colorMap: Record<string, string> = {
      'string': 'bg-blue-100 text-blue-800',
      'number': 'bg-green-100 text-green-800',
      'boolean': 'bg-purple-100 text-purple-800',
      'date': 'bg-orange-100 text-orange-800',
      'array': 'bg-pink-100 text-pink-800',
      'object': 'bg-[rgb(241, 245, 249)] text-gray-800'
    }
    return colorMap[type] || 'bg-[rgb(241, 245, 249)] text-gray-800'
  }

  const getRelationshipColor = (type: string) => {
    const colorMap: Record<string, string> = {
      'one-to-one': 'border-blue-300 bg-blue-50',
      'one-to-many': 'border-green-300 bg-green-50',
      'many-to-many': 'border-purple-300 bg-purple-50'
    }
    return colorMap[type] || 'border-gray-300 bg-[rgb(255, 255, 255)]'
  }

  return (
    <div className="min-h-screen bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-[#228B22] rounded-lg">
              <Database className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-[#0F172A]">Database Schema</h1>
              <p className="text-gray-600 mt-1">Off-roading trip planning application data structure</p>
            </div>
          </div>

          {/* View Mode Toggle */}
          <div className="flex gap-2">
            <button
              onClick={() => setViewMode('visual')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition-all duration-150 ${
                viewMode === 'visual'
                  ? 'bg-[#228B22] text-white shadow-md'
                  : 'bg-[#F8FAFB] text-[#0F172A] border border-[#E2E8F0] hover:bg-[rgb(241, 245, 249)]'
              }`}
            >
              Visual View
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition-all duration-150 ${
                viewMode === 'list'
                  ? 'bg-[#228B22] text-white shadow-md'
                  : 'bg-[#F8FAFB] text-[#0F172A] border border-[#E2E8F0] hover:bg-[rgb(241, 245, 249)]'
              }`}
            >
              List View
            </button>
          </div>
        </div>

        {viewMode === 'visual' ? (
          /* Visual Schema View */
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {tables.map((table) => (
              <div
                key={table.id}
                className={`bg-white border rounded-xl p-6 transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md ${
                  selectedTable === table.id
                    ? 'border-[#228B22] ring-2 ring-[#228B22]/20'
                    : 'border-[#E2E8F0] hover:border-gray-300'
                }`}
                onClick={() => handleTableClick(table.id)}
              >
                {/* Table Header */}
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-[#F1F5F9] rounded-lg">
                    {getTableIcon(table.name)}
                  </div>
                  <div>
                    <h3 className="font-semibold text-[#0F172A]">{table.name}</h3>
                    <p className="text-sm text-gray-600">{table.description}</p>
                  </div>
                </div>

                {/* Fields */}
                <div className="space-y-2 mb-4">
                  <h4 className="text-sm font-medium text-gray-700 flex items-center gap-2">
                    <Key className="w-4 h-4" />
                    Fields ({table.fields.length})
                  </h4>
                  <div className="space-y-1 max-h-32 overflow-y-auto">
                    {table.fields.slice(0, 5).map((field) => (
                      <div key={field.id} className="flex items-center justify-between text-sm">
                        <span className="text-gray-700">{field.name}</span>
                        <span className={`px-2 py-1 rounded text-xs font-medium ${getFieldTypeColor(field.type)}`}>
                          {field.type}
                        </span>
                      </div>
