'use client'

import { useState } from 'react'
import { Eye, EyeOff, ArrowLeft, Shield, CheckCircle } from 'lucide-react'

interface PasswordResetProps {
  token?: string;
  onSuccess?: () => void;
  onBack?: () => void;
}

export function PasswordReset({
  token = '',
  onSuccess = () => console.log('Password reset successful'),
  onBack = () => console.log('Navigate back')
}: PasswordResetProps = {}) {
  const [step, setStep] = useState<'request' | 'reset' | 'success'>(token ? 'reset' : 'request')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  const validatePassword = (password: string): boolean => {
    return password.length >= 8 && /(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(password)
  }

  const handleRequestReset = async (e: React.FormEvent) => {
    e.preventDefault()
    setErrors({})

    if (!validateEmail(email)) {
      setErrors({ email: 'Please enter a valid email address' })
      return
    }

    setIsLoading(true)

    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500))

    setIsLoading(false)
    setStep('success')
  }

  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault()
    setErrors({})

    const newErrors: Record<string, string> = {}

    if (!validatePassword(password)) {
      newErrors.password = 'Password must be at least 8 characters with uppercase, lowercase, and number'
    }

    if (password !== confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors)
      return
    }

    setIsLoading(true)

    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500))

    setIsLoading(false)
    setStep('success')
    onSuccess()
  }

  if (step === 'success') {
    return (
      <div className="min-h-screen bg-[#ffffff] flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-8 shadow-md">
            <div className="text-center">
              <div className="w-16 h-16 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center mx-auto mb-6">
                <CheckCircle className="w-8 h-8 text-[#ffffff]" />
              </div>

              <h1 className="text-2xl font-semibold text-[#0f172a] mb-3">
                {token ? 'Password Updated!' : 'Check Your Email'}
              </h1>

              <p className="text-[#64748b] mb-8 leading-relaxed">
                {token 
                  ? 'Your password has been successfully updated. You can now sign in with your new password.'
                  : `We've sent a password reset link to ${email}. Click the link in the email to reset your password.`
                }
              </p>

              <button
                onClick={onBack}
                className="w-full h-12 bg-[rgb(34,139,34)] text-[#ffffff] rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 shadow-sm active:scale-95"
                aria-label={token ? 'Return to sign in' : 'Return to previous page'}
              >
                {token ? 'Return to Sign In' : 'Back to Sign In'}
              </button>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#ffffff] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-8 shadow-md">
          {/* Header */}
          <div className="flex items-center mb-8">
            <button
              onClick={onBack}
              className="p-2 -ml-2 text-[#64748b] hover:text-[#0f172a] transition-colors duration-150 rounded-lg hover:bg-[#f1f5f9]"
              aria-label="Go back"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="ml-3">
              <h1 className="text-2xl font-semibold text-[#0f172a]">
                {step === 'request' ? 'Reset Password' : 'Create New Password'}
              </h1>
              <p className="text-[#64748b] mt-1">
                {step === 'request' 
                  ? 'Enter your email to receive a reset link'
                  : 'Enter your new password below'
                }
              </p>
            </div>
          </div>

          {step === 'request' ? (
            <form onSubmit={handleRequestReset} className="space-y-6">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Email Address
                </label>
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className={`w-full h-12 px-4 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 focus:border-[rgb(34,139,34)] transition-colors duration-150 ${
                    errors.email ? 'border-[rgb(220,38,38)]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="Enter your email address"
                  required
                  aria-describedby={errors.email ? 'email-error' : undefined}
                />
                {errors.email && (
                  <p id="email-error" className="text-[rgb(220,38,38)] text-sm mt-2" role="alert">
                    {errors.email}
                  </p>
                )}
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full h-12 bg-[rgb(34,139,34)] text-[#ffffff] rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-150 shadow-sm active:scale-95 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[rgb(34,139,34)]"
                aria-label="Send reset email"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center gap-2">
                    <div className="w-4 h-4 border-2 border-[#ffffff]/30 border-t-[#ffffff] rounded-full animate-spin" />
                    Sending...
                  </div>
                ) : (
                  'Send Reset Email'
                )}
              </button>
            </form>
          ) : (
            <form onSubmit={handlePasswordReset} className="space-y-6">
              <div>
                <label htmlFor="password" className="block text-sm font-medium text-[#0f172a] mb-2">
                  New Password
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className={`w-full h-12 px-4 pr-12 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 focus:border-[rgb(34,139,34)] transition-colors duration-150 ${
                      errors.password ? 'border-[rgb(220,38,38)]' : 'border-[#e2e8f0]'
                    }`}
                    placeholder="Enter new password"
                    required
                    aria-describedby={errors.password ? 'password-error' : 'password-requirements'}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#64748b] hover:text-[#0f172a] transition-colors duration-150 rounded focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
                {errors.password && (
                  <p id="password-error" className="text-[rgb(220,38,38)] text-sm mt-2" role="alert">
                    {errors.password}
                  </p>
                )}
                <p id="password-requirements" className="text-[#64748b] text-sm mt-2">
                  Must be at least 8 characters with uppercase, lowercase, and number
                </p>
              </div>

              <div>
                <label htmlFor="confirmPassword" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Confirm Password
                </label>
                <div className="relative">
                  <input
                    id="confirmPassword"
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className={`w-full h-12 px-4 pr-12 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#94a3b8] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 focus:border-[rgb(34,139,34)] transition-colors duration-150 ${
                      errors.confirmPassword ? 'border-[rgb(220,38,38)]' : 'border-[#e2e8f0]'
                    }`}
                    placeholder="Confirm new password"
                    required
                    aria-describedby={errors.confirmPassword ? 'confirm-password-error' : undefined}
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#64748b] hover:text-[#0f172a] transition-colors duration-150 rounded focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20"
                    aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                  >
                    {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
                {errors.confirmPassword && (
                  <p id="confirm-password-error" className="text-[rgb(220,38,38)] text-sm mt-2" role="alert">
                    {errors.confirmPassword}
                  </p>
                )}
              </div>

              <div className="bg-[#f1f5f9] border border-[#e2e8f0] rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <Shield className="w-5 h-5 text-[rgb(34,139,34)] mt-0.5 flex-shrink-0" />
                  <div>
                    <h3 className="text-sm font-medium text-[#0f172a] mb-1">Security Tips</h3>
                    <ul className="text-sm text-[#64748b] space-y-1">
                      <li>• Use a unique password you haven't used before</li>
                      <li>• Consider using a password manager</li>
                      <li>• Don't share your password with anyone</li>
                    </ul>
                  </div>
                </div>
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full h-12 bg-[rgb(34,139,34)] text-[#ffffff] rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-150 shadow-sm active:scale-95 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[rgb(34,139,34)]"
                aria-label="Update password"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center gap-2">
                    <div className="w-4 h-4 border-2 border-[#ffffff]/30 border-t-[#ffffff] rounded-full animate-spin" />
                    Updating...
                  </div>
                ) : (
                  'Update Password'
                )}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  )
}

