'use client'

import { useState, useEffect } from 'react'
import { Plus, MapPin, Calendar, Users, Star, Filter, Search, ChevronRight } from 'lucide-react'

interface Trip {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  memberCount: number
  status: 'upcoming' | 'active' | 'completed'
  difficulty: 'easy' | 'moderate' | 'hard'
  imageUrl: string
  description: string
  isStarred: boolean
}

interface TripListPageProps {
  trips?: Trip[]
  onTripSelect?: (tripId: string) => void
  onCreateTrip?: () => void
}

export function TripListPage({
  trips = DEFAULT_TRIPS,
  onTripSelect = (id) => console.log('Trip selected:', id),
  onCreateTrip = () => console.log('Create trip')
}: TripListPageProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedFilter, setSelectedFilter] = useState<'all' | 'upcoming' | 'active' | 'completed'>('all')
  const [filteredTrips, setFilteredTrips] = useState(trips)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    setIsLoading(true)
    const timer = setTimeout(() => {
      let filtered = trips

      if (selectedFilter !== 'all') {
        filtered = filtered.filter(trip => trip.status === selectedFilter)
      }

      if (searchQuery.trim()) {
        filtered = filtered.filter(trip =>
          trip.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          trip.location.toLowerCase().includes(searchQuery.toLowerCase())
        )
      }

      setFilteredTrips(filtered)
      setIsLoading(false)
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery, selectedFilter, trips])

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-[rgb(34,139,34)] text-white'
      case 'moderate': return 'bg-[rgb(255,140,0)] text-white'
      case 'hard': return 'bg-[rgb(220,38,38)] text-white'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'upcoming': return 'bg-blue-100 text-blue-700 border-blue-200'
      case 'active': return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'completed': return 'bg-[rgb(241, 245, 249)] text-gray-600 border-[rgb(226, 232, 240)]'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-4">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">My Trips</h1>
          <button
            onClick={onCreateTrip}
            className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium shadow-md active:scale-95"
            aria-label="Create new trip"
          >
            <Plus className="w-4 h-4" />
            <span className="hidden sm:inline">New Trip</span>
          </button>
        </div>

        {/* Search */}
        <div className="relative mb-4">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search trips or locations..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
            aria-label="Search trips"
          />
        </div>

        {/* Filters */}
        <div className="flex gap-2 overflow-x-auto pb-2">
          {[
            { key: 'all', label: 'All' },
            { key: 'upcoming', label: 'Upcoming' },
            { key: 'active', label: 'Active' },
            { key: 'completed', label: 'Completed' }
          ].map((filter) => (
            <button
              key={filter.key}
              onClick={() => setSelectedFilter(filter.key as any)}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all duration-150 ${
                selectedFilter === filter.key
                  ? 'bg-[rgb(34,139,34)] text-white shadow-md'
                  : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] border border-[rgb(226,232,240)]'
              }`}
              aria-label={`Filter by ${filter.label}`}
            >
              {filter.label}
            </button>
          ))}
        </div>
      </div>

      {/* Trip List */}
      <div className="px-4 py-6">
        {isLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-[rgb(248,250,252)] rounded-xl p-4 animate-pulse">
                <div className="flex gap-4">
                  <div className="w-20 h-20 bg-gray-300 rounded-lg"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-gray-300 rounded w-3/4"></div>
                    <div className="h-3 bg-gray-300 rounded w-1/2"></div>
                    <div className="h-3 bg-gray-300 rounded w-1/3"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : filteredTrips.length === 0 ? (
          <div className="text-center py-12">
            <MapPin className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">
              {searchQuery ? 'No trips found' : 'No trips yet'}
            </h3>
            <p className="text-gray-500 mb-6 max-w-sm mx-auto">
              {searchQuery 
                ? 'Try adjusting your search or filters'
                : 'Start planning your first off-road adventure'
              }
            </p>
            {!searchQuery && (
              <button
                onClick={onCreateTrip}
                className="px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium shadow-md active:scale-95"
              >
                Plan Your First Trip
              </button>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {filteredTrips.map((trip) => (
              <div
                key={trip.id}
                onClick={() => onTripSelect(trip.id)}
                className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 hover:border-[rgb(34,139,34)]/50 transition-all duration-200 shadow-sm hover:shadow-md cursor-pointer active:scale-[0.98]"
                role="button"
                tabIndex={0}
                aria-label={`View trip: ${trip.title}`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onTripSelect(trip.id)
                  }
                }}
              >
                <div className="flex gap-4">
                  <div className="relative">
                    <img
                      src={trip.imageUrl}
                      alt={trip.title}
                      className="w-20 h-20 rounded-lg object-cover"
                    />
                    {trip.isStarred && (
                      <Star className="absolute -top-1 -right-1 w-4 h-4 text-[rgb(255,140,0)] fill-current" />
                    )}
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="font-semibold text-[rgb(15,23,42)] truncate pr-2">
                        {trip.title}
                      </h3>
                      <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
                    </div>

                    <div className="flex items-center gap-1 mb-2">
                      <MapPin className="w-3 h-3 text-gray-400" />
                      <span className="text-sm text-gray-600 truncate">{trip.location}</span>
                    </div>

                    <div className="flex items-center gap-1 mb-3">
                      <Calendar className="w-3 h-3 text-gray-400" />
                      <span className="text-sm text-gray-600">
                        {formatDate(trip.startDate)} - {formatDate(trip.endDate)}
                      </span>
                    </div>

                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(trip.status)}`}>
                          {trip.status.charAt(0).toUpperCase() + trip.status.slice(1)}
                        </span>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${getDifficultyColor(trip.difficulty)}`}>
                          {trip.difficulty.charAt(0).toUpperCase() + trip.difficulty.slice(1)}
                        </span>
                      </div>

                      <div className="flex items-center gap-1">
                        <Users className="w-3 h-3 text-gray-400" />
                        <span className="text-sm text-gray-600">{trip.memberCount}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

