code.middleware:
'use client'

import { useEffect, useState } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { Shield, AlertTriangle, Loader2 } from 'lucide-react'

interface User {
  id: string
  email: string
  name: string
  role: 'admin' | 'member' | 'guest'
  isVerified: boolean
}

interface AuthState {
  user: User | null
  isLoading: boolean
  isAuthenticated: boolean
  error: string | null
}

interface AuthMiddlewareProps {
  children?: React.ReactNode
  requireAuth?: boolean
  allowedRoles?: ('admin' | 'member' | 'guest')[]
  redirectTo?: string
  fallback?: React.ReactNode
}

// Mock authentication service
const mockAuthService = {
  getCurrentUser: async (): Promise<User | null> => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000))

    // Mock user data - in production this would come from your auth provider
    const mockUser: User = {
      id: '1',
      email: 'user@example.com',
      name: 'Trail Explorer',
      role: 'member',
      isVerified: true
    }

    // Simulate 70% authenticated state for demo
    return Math.random() > 0.3 ? mockUser : null
  },

  signOut: async (): Promise<void> => {
    await new Promise(resolve => setTimeout(resolve, 500))
    // Clear auth state
  }
}

export function AuthMiddleware({
  children,
  requireAuth = true,
  allowedRoles = ['admin', 'member', 'guest'],
  redirectTo = '/login',
  fallback
}: AuthMiddlewareProps = {}) {
  const [authState, setAuthState] = useState<AuthState>({
    user: null,
    isLoading: true,
    isAuthenticated: false,
    error: null
  })

  const router = useRouter()
  const pathname = usePathname()

  useEffect(() => {
    checkAuthStatus()
  }, [pathname])

  const checkAuthStatus = async () => {
    try {
      setAuthState(prev => ({ ...prev, isLoading: true, error: null }))

      const user = await mockAuthService.getCurrentUser()

      setAuthState({
        user,
        isLoading: false,
        isAuthenticated: !!user,
        error: null
      })

      // Handle authentication requirements
      if (requireAuth && !user) {
        router.push(redirectTo)
        return
      }

      // Handle role-based access
      if (user && !allowedRoles.includes(user.role)) {
        setAuthState(prev => ({
          ...prev,
          error: 'Insufficient permissions to access this area'
        }))
        return
      }

    } catch (error) {
      setAuthState({
        user: null,
        isLoading: false,
        isAuthenticated: false,
        error: 'Authentication failed. Please try again.'
      })
    }
  }

  const handleRetry = () => {
    checkAuthStatus()
  }

  const handleSignOut = async () => {
    try {
      await mockAuthService.signOut()
      setAuthState({
        user: null,
        isLoading: false,
        isAuthenticated: false,
        error: null
      })
      router.push('/login')
    } catch (error) {
      setAuthState(prev => ({
        ...prev,
        error: 'Sign out failed. Please try again.'
      }))
    }
  }

  // Loading state
  if (authState.isLoading) {
    if (fallback) {
      return <>{fallback}</>
    }

    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="text-center space-y-4">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-[#f8faf8] rounded-full">
            <Loader2 className="w-8 h-8 text-[#228b22] animate-spin" />
          </div>
          <div className="space-y-2">
            <h2 className="text-lg font-semibold text-[#0f172a]">
              Checking Authentication
            </h2>
            <p className="text-sm text-gray-600">
              Please wait while we verify your access...
            </p>
          </div>
        </div>
      </div>
    )
  }

  // Error state
  if (authState.error) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="max-w-md w-full text-center space-y-6">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-red-50 rounded-full">
            <AlertTriangle className="w-8 h-8 text-[#dc2626]" />
          </div>

          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-[#0f172a]">
              Access Denied
            </h2>
            <p className="text-sm text-gray-600">
              {authState.error}
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-3 justify-center">
            <button
              onClick={handleRetry}
              className="px-6 py-3 bg-[#228b22] text-white rounded-lg hover:bg-[#1e7b1e] transition-colors duration-150 font-medium text-sm shadow-md hover:shadow-lg active:scale-95 min-h-[44px]"
              aria-label="Retry authentication"
            >
              Try Again
            </button>

            {authState.user && (
              <button
                onClick={handleSignOut}
                className="px-6 py-3 bg-white text-[#0f172a] rounded-lg hover:bg-[#f8faf8] transition-colors duration-150 font-medium text-sm border border-[#e2e8f0] shadow-sm hover:shadow-md active:scale-95 min-h-[44px]"
                aria-label="Sign out"
              >
                Sign Out
              </button>
            )}
          </div>
        </div>
      </div>
    )
  }

  // Unauthorized access
  if (requireAuth && !authState.isAuthenticated) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="max-w-md w-full text-center space-y-6">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-[#f8faf8] rounded-full">
            <Shield className="w-8 h-8 text-[#228b22]" />
          </div>

          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-[#0f172a]">
              Authentication Required
            </h2>
            <p className="text-sm text-gray-600">
              Please sign in to access this area of the app.
            </p>
          </div>

          <button
            onClick={() => router.push(redirectTo)}
            className="w-full px-6 py-3 bg-[#228b22] text-white rounded-lg hover:bg-[#1e7b1e] transition-colors duration-150 font-medium text-sm shadow-md hover:shadow-lg active:scale-95 min-h-[44px]"
            aria-label="Go to sign in page"
          >
            Sign In
          </button>
        </div>
      </div>
    )
  }

  // Role-based access denied
  if (authState.user && !allowedRoles.includes(authState.user.role)) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="max-w-md w-full text-center space-y-6">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-orange-50 rounded-full">
            <Shield className="w-8 h-8 text-[#ff8c00]" />
          </div>

          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-[#0f172a]">
              Insufficient Permissions
            </h2>
            <p className="text-sm text-gray-600">
              Your account doesn't have permission to access this area.
            </p>
            <p className="text-xs text-gray-500">
              Current role: {authState.user.role}
            </p>
          </div>

          <div className="flex flex-col gap-3">
            <button
              onClick={() => router.back()}
              className="w-full px-6 py-3 bg-[#228b22] text-white rounded-lg hover:bg-[#1e7b1e] transition-colors duration-150 font-medium text-sm shadow-md hover:shadow-lg active:scale-95 min-h-[44px]"
              aria-label="Go back to previous page"
            >
              Go Back
            </button>

            <button
              onClick={handleSignOut}
              className="w-full px-6 py-3 bg-white text-[#0f172a] rounded-lg hover:bg-[#f8faf8] transition-colors duration-150 font-medium text-sm border border-[#e2e8f0] shadow-sm hover:shadow-md active:scale-95 min-h-[44px]"
              aria-label="Sign out and return to login"
            >
              Sign Out
            </button>
          </div>
        </div>
      </div>
    )
  }

  // Render children if authenticated and authorized
  return <>{children}</>
}

// Demo component showing different auth scenarios
export default function AuthMiddlewareDemo() {
  const [scenario, setScenario] = useState<'loading' | 'authenticated' | 'unauthorized' | 'insufficient'>('authenticated')

  const scenarios = [
    { key: 'loading', label: 'Loading State' },
    { key: 'authenticated', label: 'Authenticated User' },
    { key: 'unauthorized', label: 'Unauthorized Access' },
    { key: 'insufficient', label: 'Insufficient Permissions' }
  ]

  const renderScenario = () => {
    switch (scenario) {
      case 'loading':
        return (
          <AuthMiddleware requireAuth={true}>
            <div className="p-6 text-center">
              <h1 className="text-2xl font-bold text-[#0f172a]">Protected Content</h1>
              <p className="text-gray-600 mt-2">This content is only visible to authenticated users.</p>
            </div>
          </AuthMiddleware>
        )

      case 'unauthorized':
        return (
          <AuthMiddleware requireAuth={true} redirectTo="/login">
            <div className="p-6 text-center">
              <h1 className="text-2xl font-bold text-[#0f172a]">Protected Content</h1>
            </div>
          </AuthMiddleware>
        )

      case 'insufficient':
        return (
          <AuthMiddleware requireAuth={true} allowedRoles={['admin']}>
            <div className="p-6 text-center">
              <h1 className="text-2xl font-bold text-[#0f172a]">Admin Only Content</h1>
            </div>
          </AuthMiddleware>
        )

      default:
        return (
          <AuthMiddleware requireAuth={false}>
            <div className="min-h-screen bg-white p-6">
              <div className="max-w-4xl mx-auto space-y-6">
                <div className="text-center space-y-2">
                  <h1 className="text-3xl font-bold text-[#0f172a]">Off-Road Trip Planner</h1>
                  <p className="text-gray-600">Plan your next adventure with confidence</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  <div className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-md">
                    <h3 className="text-lg font-semibold text-[#0f172a] mb-2">Trip Planning</h3>
                    <p className="text-sm text-gray-600">Select locations and create detailed itineraries</p>
                  </div>

                  <div className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-md">
                    <h3 className="text-lg font-semibold text-[#0f172a] mb-2">Group Management</h3>
                    <p className="text-sm text-gray-600">Assign tasks and coordinate with your team</p>
                  </div>

                  <div className="bg-white border border-[#e2e8f0] rounded-xl p-6 shadow-md">
                    <h3 className="text-lg font-semibold text-[#0f172a] mb-2">Weather Integration</h3>
                    <p className="text-sm text-gray-600">Stay informed about conditions at your destination</p>
                  </div>
                </div>
              </div>
            </div>
          </AuthMiddleware>
        )
    }
  }

  return (
    <div className="min-h-screen bg-[#f8faf8]">
      {/* Demo Controls */}
      <div className="bg-white border-b border-[#e2e8f0] p-4">
        <div className="max-w-4xl mx-auto">
          <h2 className="text-lg font-semibold text-[#0f172a] mb-4">Auth Middleware Demo</h2>
          <div className="flex flex-wrap gap-2">
            {scenarios.map((item) => (
              <button
                key={item.key}
                onClick={() => setScenario(item.key as any)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors duration-150 min-h-[44px] ${
                  scenario === item.key
                    ? 'bg-[#228b22] text-white'
                    : 'bg-[#f1f5f9] text-[#0f172a] hover:bg-[#e2e8f0]'
                }`}
                aria-label={`Show ${item.label} scenario`}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Scenario Content */}
      {renderScenario()}
    </div>
  )
}

