'use client'

import { useState } from 'react'
import { Eye, EyeOff, User, Mail, Lock, MapPin, Calendar } from 'lucide-react'

interface RegistrationFormData {
  firstName: string
  lastName: string
  email: string
  password: string
  confirmPassword: string
  location: string
  birthDate: string
  agreeToTerms: boolean
  subscribeNewsletter: boolean
}

interface RegistrationPageProps {
  onRegister?: (data: RegistrationFormData) => void
  isLoading?: boolean
}

export function RegistrationPage({
  onRegister = () => console.log('Registration submitted'),
  isLoading = false
}: RegistrationPageProps = {}) {
  const [formData, setFormData] = useState<RegistrationFormData>({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
    location: '',
    birthDate: '',
    agreeToTerms: false,
    subscribeNewsletter: false
  })

  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [errors, setErrors] = useState<Partial<RegistrationFormData>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)

  const validateForm = (): boolean => {
    const newErrors: Partial<RegistrationFormData> = {}

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'First name is required'
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Last name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters'
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your password'
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.birthDate) {
      newErrors.birthDate = 'Birth date is required'
    }

    if (!formData.agreeToTerms) {
      newErrors.agreeToTerms = 'You must agree to the terms and conditions'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      onRegister(formData)
    } catch (error) {
      console.error('Registration failed:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleInputChange = (field: keyof RegistrationFormData, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }))
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      {/* Header */}
      <div className="bg-gradient-to-r from-[#228b22] to-[#32cd32] px-4 py-6 sm:px-6">
        <div className="max-w-md mx-auto">
          <h1 className="text-2xl font-bold text-[#ffffff] text-center">
            Join TrailPlan
          </h1>
          <p className="text-[#ffffff]/90 text-center mt-2">
            Start planning your next adventure
          </p>
        </div>
      </div>

      {/* Registration Form */}
      <div className="px-4 py-6 sm:px-6">
        <div className="max-w-md mx-auto">
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Name Fields */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label htmlFor="firstName" className="block text-sm font-medium text-[#0f172a] mb-2">
                  First Name
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                  <input
                    id="firstName"
                    type="text"
                    value={formData.firstName}
                    onChange={(e) => handleInputChange('firstName', e.target.value)}
                    className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                      errors.firstName ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                    }`}
                    placeholder="John"
                    aria-label="First Name"
                    aria-describedby={errors.firstName ? 'firstName-error' : undefined}
                  />
                </div>
                {errors.firstName && (
                  <p id="firstName-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                    {errors.firstName}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="lastName" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Last Name
                </label>
                <input
                  id="lastName"
                  type="text"
                  value={formData.lastName}
                  onChange={(e) => handleInputChange('lastName', e.target.value)}
                  className={`w-full px-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.lastName ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="Doe"
                  aria-label="Last Name"
                  aria-describedby={errors.lastName ? 'lastName-error' : undefined}
                />
                {errors.lastName && (
                  <p id="lastName-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                    {errors.lastName}
                  </p>
                )}
              </div>
            </div>

            {/* Email */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-[#0f172a] mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.email ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="john@example.com"
                  aria-label="Email Address"
                  aria-describedby={errors.email ? 'email-error' : undefined}
                />
              </div>
              {errors.email && (
                <p id="email-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                  {errors.email}
                </p>
              )}
            </div>

            {/* Password */}
            <div>
              <label htmlFor="password" className="block text-sm font-medium text-[#0f172a] mb-2">
                Password
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => handleInputChange('password', e.target.value)}
                  className={`w-full pl-10 pr-12 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.password ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="••••••••"
                  aria-label="Password"
                  aria-describedby={errors.password ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[#64748b] hover:text-[#0f172a] transition-colors duration-200"
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                </button>
              </div>
              {errors.password && (
                <p id="password-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                  {errors.password}
                </p>
              )}
            </div>

            {/* Confirm Password */}
            <div>
              <label htmlFor="confirmPassword" className="block text-sm font-medium text-[#0f172a] mb-2">
                Confirm Password
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="confirmPassword"
                  type={showConfirmPassword ? 'text' : 'password'}
                  value={formData.confirmPassword}
                  onChange={(e) => handleInputChange('confirmPassword', e.target.value)}
                  className={`w-full pl-10 pr-12 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.confirmPassword ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="••••••••"
                  aria-label="Confirm Password"
                  aria-describedby={errors.confirmPassword ? 'confirmPassword-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[#64748b] hover:text-[#0f172a] transition-colors duration-200"
                  aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                >
                  {showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                </button>
              </div>
              {errors.confirmPassword && (
                <p id="confirmPassword-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                  {errors.confirmPassword}
                </p>
              )}
            </div>

            {/* Location */}
            <div>
              <label htmlFor="location" className="block text-sm font-medium text-[#0f172a] mb-2">
                Location
              </label>
              <div className="relative">
                <MapPin className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="location"
                  type="text"
                  value={formData.location}
                  onChange={(e) => handleInputChange('location', e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.location ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  placeholder="City, State"
                  aria-label="Location"
                  aria-describedby={errors.location ? 'location-error' : undefined}
                />
              </div>
              {errors.location && (
                <p id="location-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            {/* Birth Date */}
            <div>
              <label htmlFor="birthDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                Birth Date
              </label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="birthDate"
                  type="date"
                  value={formData.birthDate}
                  onChange={(e) => handleInputChange('birthDate', e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.birthDate ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  aria-label="Birth Date"
                  aria-describedby={errors.birthDate ? 'birthDate-error' : undefined}
                />
              </div>
              {errors.birthDate && (
                <p id="birthDate-error" className="text-[#dc2626] text-sm mt-1" role="alert">
                  {errors.birthDate}
                </p>
              )}
            </div>

            {/* Checkboxes */}
            <div className="space-y-3">
