                />
                <label htmlFor="agreeToTerms" className="text-sm text-[#0f172a] leading-5">
                  I agree to the{' '}
                  <button
                    type="button"
                    className="text-[#228b22] hover:text-[#1e7e1e] underline focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 rounded"
                  >
                    Terms of Service
                  </button>{' '}
                  and{' '}
                  <button
                    type="button"
                    className="text-[#228b22] hover:text-[#1e7e1e] underline focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 rounded"
                  >
                    Privacy Policy
                  </button>
                </label>
              </div>
              {errors.agreeToTerms && (
                <p id="agreeToTerms-error" className="text-[#dc2626] text-sm" role="alert">
                  {errors.agreeToTerms}
                </p>
              )}

              <div className="flex items-start gap-3">
                <input
                  id="subscribeNewsletter"
                  type="checkbox"
                  checked={formData.subscribeNewsletter}
                  onChange={(e) => handleInputChange('subscribeNewsletter', e.target.checked)}
                  className="mt-1 h-4 w-4 text-[#228b22] border-[#e2e8f0] rounded focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2"
                />
                <label htmlFor="subscribeNewsletter" className="text-sm text-[#0f172a] leading-5">
                  Subscribe to our newsletter for trail updates and adventure tips
                </label>
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isSubmitting || isLoading}
              className="w-full py-3 px-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium text-base hover:bg-[#1e7e1e] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 shadow-md hover:shadow-lg active:scale-95"
              style={{ minHeight: '48px' }}
            >
              {isSubmitting || isLoading ? (
                <div className="flex items-center justify-center gap-2">
                  <div className="w-5 h-5 border-2 border-[#ffffff]/30 border-t-[#ffffff] rounded-full animate-spin"></div>
                  Creating Account...
                </div>
              ) : (
                'Create Account'
              )}
            </button>
          </form>

          {/* Sign In Link */}
          <div className="mt-6 text-center">
            <p className="text-sm text-[#64748b]">
              Already have an account?{' '}
              <button
                type="button"
                className="text-[#228b22] hover:text-[#1e7e1e] font-medium underline focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 rounded"
              >
                Sign In
              </button>
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

