'use client'

import { useState, useEffect } from 'react'
import { User, MapPin, Calendar, Users, Settings, Camera, Edit3, Save, X } from 'lucide-react'

interface UserProfileData {
  id: string
  name: string
  email: string
  avatar?: string
  bio: string
  location: string
  joinDate: string
  tripsCompleted: number
  favoriteTrails: string[]
  skills: string[]
  emergencyContact: {
    name: string
    phone: string
    relationship: string
  }
  preferences: {
    difficulty: 'beginner' | 'intermediate' | 'advanced'
    notifications: boolean
    publicProfile: boolean
  }
}

interface UserProfileProps {
  userId?: string
  onProfileUpdate?: (data: UserProfileData) => void
  isEditable?: boolean
}

export function UserProfile({
  userId = 'user-1',
  onProfileUpdate = () => console.log('Profile updated'),
  isEditable = true
}: UserProfileProps = {}) {
  const [profile, setProfile] = useState<UserProfileData>(DEFAULT_PROFILE)
  const [isEditing, setIsEditing] = useState(false)
  const [editedProfile, setEditedProfile] = useState<UserProfileData>(profile)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    // Simulate loading user data
    setIsLoading(true)
    setTimeout(() => {
      setProfile(DEFAULT_PROFILE)
      setEditedProfile(DEFAULT_PROFILE)
      setIsLoading(false)
    }, 1000)
  }, [userId])

  const handleSave = async () => {
    setIsLoading(true)
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))
      setProfile(editedProfile)
      onProfileUpdate(editedProfile)
      setIsEditing(false)
    } catch (error) {
      console.error('Failed to update profile:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleCancel = () => {
    setEditedProfile(profile)
    setIsEditing(false)
  }

  const updateField = (field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const updateNestedField = (parent: string, field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [parent]: {
        ...prev[parent as keyof UserProfileData],
        [field]: value
      }
    }))
  }

  if (isLoading) {
    return <ProfileSkeleton />
  }

  const currentProfile = isEditing ? editedProfile : profile

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      {/* Header */}
      <div className="bg-gradient-to-r from-[#228b22] to-[#32cd32] text-white p-4">
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-semibold">Profile</h1>
          {isEditable && (
            <div className="flex gap-2">
              {isEditing ? (
                <>
                  <button
                    onClick={handleCancel}
                    className="p-2 rounded-lg bg-white/20 hover:bg-white/30 transition-colors"
                    aria-label="Cancel editing"
                  >
                    <X className="w-5 h-5" />
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={isLoading}
                    className="p-2 rounded-lg bg-white/20 hover:bg-white/30 transition-colors disabled:opacity-50"
                    aria-label="Save changes"
                  >
                    <Save className="w-5 h-5" />
                  </button>
                </>
              ) : (
                <button
                  onClick={() => setIsEditing(true)}
                  className="p-2 rounded-lg bg-white/20 hover:bg-white/30 transition-colors"
                  aria-label="Edit profile"
                >
                  <Edit3 className="w-5 h-5" />
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="p-4 space-y-6">
        {/* Avatar and Basic Info */}
        <div className="bg-white rounded-xl border border-[#e2e8f0] p-6 shadow-md">
          <div className="flex flex-col items-center text-center space-y-4">
            <div className="relative">
              <div className="w-24 h-24 bg-[#f1f5f9] rounded-full flex items-center justify-center">
                {currentProfile.avatar ? (
                  <img
                    src={currentProfile.avatar}
                    alt={currentProfile.name}
                    className="w-24 h-24 rounded-full object-cover"
                  />
                ) : (
                  <User className="w-12 h-12 text-[#0f172a]" />
                )}
              </div>
              {isEditing && (
                <button
                  className="absolute -bottom-1 -right-1 p-2 bg-[#228b22] text-white rounded-full shadow-md hover:bg-[#1e7a1e] transition-colors"
                  aria-label="Change avatar"
                >
                  <Camera className="w-4 h-4" />
                </button>
              )}
            </div>

            {isEditing ? (
              <input
                type="text"
                value={editedProfile.name}
                onChange={(e) => updateField('name', e.target.value)}
                className="text-xl font-semibold text-[#0f172a] bg-[#f8fafc] border border-[#e2e8f0] rounded-lg px-3 py-2 text-center focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent"
                placeholder="Your name"
              />
            ) : (
              <h2 className="text-xl font-semibold text-[#0f172a]">{currentProfile.name}</h2>
            )}

            <p className="text-[#64748b] text-sm">{currentProfile.email}</p>

            <div className="flex items-center gap-2 text-[#64748b] text-sm">
              <Calendar className="w-4 h-4" />
              <span>Joined {currentProfile.joinDate}</span>
            </div>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-white rounded-xl border border-[#e2e8f0] p-4 text-center shadow-md">
