code.service-integration:
'use client'

import { useState, useEffect } from 'react'
import { Cloud, CloudRain, Sun, CloudSnow, Wind, Thermometer, Droplets, Eye, AlertTriangle, MapPin, Calendar, RefreshCw } from 'lucide-react'

interface WeatherData {
  id: string
  location: string
  coordinates: { lat: number; lng: number }
  current: {
    temperature: number
    condition: string
    humidity: number
    windSpeed: number
    visibility: number
    feelsLike: number
    uvIndex: number
  }
  forecast: Array<{
    date: string
    high: number
    low: number
    condition: string
    precipitation: number
    windSpeed: number
  }>
  alerts: Array<{
    id: string
    type: 'warning' | 'watch' | 'advisory'
    title: string
    description: string
    severity: 'minor' | 'moderate' | 'severe' | 'extreme'
    startTime: string
    endTime: string
  }>
  lastUpdated: string
}

interface WeatherIntegrationProps {
  tripId?: string
  locations?: Array<{ id: string; name: string; coordinates: { lat: number; lng: number } }>
  onLocationSelect?: (locationId: string) => void
  onWeatherAlert?: (alert: WeatherData['alerts'][0]) => void
}

const WEATHER_CONDITIONS = {
  sunny: { icon: Sun, color: 'text-yellow-500', bg: 'bg-yellow-50' },
  cloudy: { icon: Cloud, color: 'text-gray-500', bg: 'bg-[rgb(255, 255, 255)]' },
  rainy: { icon: CloudRain, color: 'text-[rgb(34, 139, 34)]', bg: 'bg-blue-50' },
  snowy: { icon: CloudSnow, color: 'text-blue-300', bg: 'bg-blue-50' },
  windy: { icon: Wind, color: 'text-gray-600', bg: 'bg-[rgb(255, 255, 255)]' }
}

const ALERT_COLORS = {
  minor: 'bg-yellow-50 border-yellow-200 text-yellow-800',
  moderate: 'bg-orange-50 border-orange-200 text-orange-800',
  severe: 'bg-red-50 border-red-200 text-red-800',
  extreme: 'bg-purple-50 border-purple-200 text-purple-800'
}

export function WeatherIntegration({
  tripId = 'trip-1',
  locations = DEFAULT_LOCATIONS,
  onLocationSelect = () => {},
  onWeatherAlert = () => {}
}: WeatherIntegrationProps = {}) {
  const [selectedLocation, setSelectedLocation] = useState(locations[0]?.id || '')
  const [weatherData, setWeatherData] = useState<WeatherData>(DEFAULT_WEATHER_DATA)
  const [isLoading, setIsLoading] = useState(false)
  const [lastRefresh, setLastRefresh] = useState(new Date())

  useEffect(() => {
    if (selectedLocation) {
      loadWeatherData(selectedLocation)
    }
  }, [selectedLocation])

  const loadWeatherData = async (locationId: string) => {
    setIsLoading(true)
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))
      const location = locations.find(l => l.id === locationId)
      if (location) {
        setWeatherData({
          ...DEFAULT_WEATHER_DATA,
          location: location.name,
          coordinates: location.coordinates
        })
      }
      setLastRefresh(new Date())
    } catch (error) {
      console.error('Failed to load weather data:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleLocationChange = (locationId: string) => {
    setSelectedLocation(locationId)
    onLocationSelect(locationId)
  }

  const handleRefresh = () => {
    if (selectedLocation) {
      loadWeatherData(selectedLocation)
    }
  }

  const getWeatherIcon = (condition: string) => {
    const conditionKey = condition.toLowerCase()
    if (conditionKey.includes('rain')) return WEATHER_CONDITIONS.rainy
    if (conditionKey.includes('snow')) return WEATHER_CONDITIONS.snowy
    if (conditionKey.includes('cloud')) return WEATHER_CONDITIONS.cloudy
    if (conditionKey.includes('wind')) return WEATHER_CONDITIONS.windy
    return WEATHER_CONDITIONS.sunny
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })
  }

  const formatTime = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-[#228b22] rounded-lg flex items-center justify-center">
              <Cloud className="w-5 h-5 text-[#ffffff]" />
            </div>
            <div>
              <h1 className="text-xl font-semibold text-[#0f172a]">Weather Forecast</h1>
              <p className="text-sm text-gray-600">Plan your adventure with confidence</p>
            </div>
          </div>
          <button
            onClick={handleRefresh}
            disabled={isLoading}
            className="w-10 h-10 bg-[#f8fafc] border border-[#e2e8f0] rounded-lg flex items-center justify-center hover:bg-[#f1f5f9] transition-colors duration-200 disabled:opacity-50"
            aria-label="Refresh weather data"
          >
            <RefreshCw className={`w-4 h-4 text-[#0f172a] ${isLoading ? 'animate-spin' : ''}`} />
          </button>
        </div>

        {/* Location Selector */}
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-4 shadow-md">
          <div className="flex items-center gap-2 mb-3">
            <MapPin className="w-4 h-4 text-[#228b22]" />
            <span className="text-sm font-medium text-[#0f172a]">Select Location</span>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
            {locations.map((location) => (
              <button
                key={location.id}
                onClick={() => handleLocationChange(location.id)}
                className={`p-3 rounded-lg text-left transition-all duration-200 ${
                  selectedLocation === location.id
                    ? 'bg-[#228b22] text-[#ffffff] shadow-md'
                    : 'bg-[#f8fafc] text-[#0f172a] hover:bg-[#f1f5f9] border border-[#e2e8f0]'
                }`}
              >
                <div className="font-medium text-sm">{location.name}</div>
                <div className={`text-xs ${
                  selectedLocation === location.id ? 'text-[#ffffff]/80' : 'text-gray-500'
                }`}>
                  {location.coordinates.lat.toFixed(2)}, {location.coordinates.lng.toFixed(2)}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Weather Alerts */}
        {weatherData.alerts.length > 0 && (
          <div className="space-y-3">
            <h2 className="text-lg font-semibold text-[#0f172a] flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-[#ff8c00]" />
              Weather Alerts
            </h2>
            {weatherData.alerts.map((alert) => (
              <div
                key={alert.id}
                className={`p-4 rounded-xl border-2 ${ALERT_COLORS[alert.severity]} shadow-md`}
                role="alert"
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-sm font-semibold uppercase tracking-wide">
                        {alert.type}
                      </span>
                      <span className="text-xs px-2 py-1 bg-white/50 rounded-full">
                        {alert.severity}
                      </span>
                    </div>
                    <h3 className="font-semibold mb-2">{alert.title}</h3>
                    <p className="text-sm mb-3">{alert.description}</p>
                    <div className="flex items-center gap-4 text-xs">
                      <span>Starts: {formatTime(alert.startTime)}</span>
                      <span>Ends: {formatTime(alert.endTime)}</span>
                    </div>
                  </div>
                  <button
                    onClick={() => onWeatherAlert(alert)}
                    className="px-3 py-1 bg-white/20 hover:bg-white/30 rounded-lg text-xs font-medium transition-colors duration-200"
                  >
                    Details
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Current Weather */}
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-md">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold text-[#0f172a]">Current Conditions</h2>
            <span className="text-xs text-gray-500">
              Updated {formatTime(weatherData.lastUpdated)}
            </span>
          </div>

          {isLoading ? (
            <div className="space-y-4">
              <div className="h-20 bg-[#f1f5f9] rounded-lg animate-pulse"></div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="h-16 bg-[#f1f5f9] rounded-lg animate-pulse"></div>
                ))}
              </div>
            </div>
          ) : (
            <>
              <div className="flex items-center gap-6 mb-6">
                <div className={`w-16 h-16 rounded-xl flex items-center justify-center ${getWeatherIcon(weatherData.current.condition).bg}`}>
                  {(() => {
                    const IconComponent = getWeatherIcon(weatherData.current.condition).icon
                    return <IconComponent className={`w-8 h-8 ${getWeatherIcon(weatherData.current.condition).color}`} />
                  })()}
                </div>
                <div>
                  <div className="text-3xl font-bold text-[#0f172a]">
                    {weatherData.current.temperature}°F
                  </div>
                  <div className="text-sm text-gray-600">
                    Feels like {weatherData.current.feelsLike}°F
                  </div>
                  <div className="text-sm font-medium text-[#0f172a] capitalize">
                    {weatherData.current.condition}
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <div className="bg-[#f8fafc] rounded-lg p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Droplets className="w-4 h-4 text-[rgb(34, 139, 34)]" />
                    <span className="text-xs text-gray-600">Humidity</span>
                  </div>
                  <div className="text-lg font-semibold text-[#0f172a]">
                    {weatherData.current.humidity}%
                  </div>
                </div>

                <div className="bg-[#f8fafc] rounded-lg p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Wind className="w-4 h-4 text-gray-500" />
                    <span className="text-xs text-gray-600">Wind</span>
                  </div>
                  <div className="text-lg font-semibold text-[#0f172a]">
                    {weatherData.current.windSpeed} mph
                  </div>
                </div>

                <div className="bg-[#f8fafc] rounded-lg p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Eye className="w-4 h-4 text-gray-500" />
                    <span className="text-xs text-gray-600">Visibility</span>
                  </div>
                  <div className="text-lg font-semibold text-[#0f172a]">
                    {weatherData.current.visibility} mi
                  </div>
                </div>

                <div className="bg-[#f8fafc] rounded-lg p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Sun className="w-4 h-4 text-yellow-500" />
                    <span className="text-xs text-gray-600">UV Index</span>
                  </div>
                  <div className="text-lg font-semibold text-[#0f172a]">
                    {weatherData.current.uvIndex}
                  </div>
                </div>
              </div>
            </>
          )}
        </div>

        {/* 7-Day Forecast */}
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6 shadow-md">
          <div className="flex items-center gap-2 mb-4">
            <Calendar className="w-5 h-5 text-[#228b22]" />
            <h2 className="text-lg font-semibold text-[#0f172a]">7-Day Forecast</h2>
          </div>

          {isLoading ? (
            <div className="space-y-3">
              {[...Array(7)].map((_, i) => (
                <div key={i} className="h-16 bg-[#f1f5f9] rounded-lg animate-pulse"></div>
              ))}
            </div>
          ) : (
            <div className="space-y-3">
              {weatherData.forecast.map((day, index) => (
                <div
                  key={day.date}
                  className="flex items-center justify-between p-4 bg-[#f8fafc] rounded-lg hover:bg-[#f1f5f9] transition-colors duration-200"
                >
                  <div className="flex items-center gap-4 flex-1">
                    <div className="w-12 text-sm font-medium text-[#0f172a] min-w-0">
                      {index === 0 ? 'Today' : formatDate(day.date)}
                    </div>
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${getWeatherIcon(day.condition).bg}`}>
                      {(() => {
                        const IconComponent = getWeatherIcon(day.condition).icon
                        return <IconComponent className={`w-4 h-4 ${getWeatherIcon(day.condition).color}`} />
                      })()}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium text-[#0f172a] capitalize truncate">
                        {day.condition}
                      </div>
                      <div className="text-xs text-gray-600">
                        {day.precipitation}% rain • {day.windSpeed} mph wind
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 text-sm font-medium">
                    <span className="text-[#0f172a]">{day.high}°</span>
                    <span className="text-gray-500">{day.low}°</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Trip Planning Tips */}
        <div className="bg-gradient-to-r from-[#228b22]/5 to-[#ff8c00]/5 border border-[#e2e8f0] rounded-xl p-6">
          <h3 className="text-lg font-semibold text-[#0f172a] mb-3">Planning Tips</h3>
