'use client'

import { useState, useEffect } from 'react'
import { Send, Mail, CheckCircle, AlertCircle, Clock, Users } from 'lucide-react'

interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
  sentAt?: Date
}

interface EmailCampaign {
  id: string
  name: string
  template: EmailTemplate
  recipients: EmailRecipient[]
  scheduledAt?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed'
  createdAt: Date
}

interface ResendServiceProps {
  tripId?: string
  onEmailSent?: (campaignId: string) => void
  onError?: (error: string) => void
}

export function ResendService({
  tripId = 'trip-1',
  onEmailSent = () => console.log('Email sent'),
  onError = () => console.log('Email error')
}: ResendServiceProps = {}) {
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>(DEFAULT_CAMPAIGNS)
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate>(EMAIL_TEMPLATES[0])
  const [recipients, setRecipients] = useState<EmailRecipient[]>(DEFAULT_RECIPIENTS)
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'compose' | 'campaigns' | 'templates'>('compose')

  const handleSendEmail = async () => {
    setIsLoading(true)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000))

      const newCampaign: EmailCampaign = {
        id: `campaign-${Date.now()}`,
        name: `${selectedTemplate.name} - ${new Date().toLocaleDateString()}`,
        template: selectedTemplate,
        recipients: recipients.map(r => ({ ...r, status: 'sent', sentAt: new Date() })),
        status: 'sent',
        createdAt: new Date()
      }

      setCampaigns(prev => [newCampaign, ...prev])
      onEmailSent(newCampaign.id)
    } catch (error) {
      onError('Failed to send emails')
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusIcon = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
      default:
        return <Clock className="w-4 h-4 text-[rgb(255,140,0)]" />
    }
  }

  const getStatusColor = (status: EmailCampaign['status']) => {
    switch (status) {
      case 'sent':
        return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'sending':
        return 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)] border-[rgb(255,140,0)]/20'
      case 'failed':
        return 'bg-[rgb(220,38,38)]/10 text-[rgb(220,38,38)] border-[rgb(220,38,38)]/20'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 sm:p-6">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">
            Email Communication
          </h1>
          <p className="text-[rgb(15,23,42)]/60">
            Send trip invitations, reminders, and updates to your group
          </p>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-1 mb-6 bg-[rgb(248,250,252)] p-1 rounded-lg">
          {[
            { id: 'compose', label: 'Compose', icon: Send },
            { id: 'campaigns', label: 'Campaigns', icon: Mail },
            { id: 'templates', label: 'Templates', icon: Users }
          ].map(tab => {
            const Icon = tab.icon
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 ${
                  activeTab === tab.id
                    ? 'bg-[rgb(255,255,255)] text-[rgb(34,139,34)] shadow-sm'
                    : 'text-[rgb(15,23,42)]/60 hover:text-[rgb(15,23,42)]'
                }`}
                aria-label={`Switch to ${tab.label} tab`}
              >
                <Icon className="w-4 h-4" />
                <span className="hidden sm:inline">{tab.label}</span>
              </button>
            )
          })}
        </div>

        {/* Compose Tab */}
        {activeTab === 'compose' && (
          <div className="space-y-6">
            {/* Template Selection */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">
                Select Email Template
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {EMAIL_TEMPLATES.map(template => (
                  <button
                    key={template.id}
                    onClick={() => setSelectedTemplate(template)}
                    className={`p-4 rounded-lg border-2 text-left transition-all duration-200 ${
                      selectedTemplate.id === template.id
                        ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5'
                        : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
                    }`}
                    aria-label={`Select ${template.name} template`}
                  >
                    <h4 className="font-semibold text-[rgb(15,23,42)] mb-1">
                      {template.name}
                    </h4>
                    <p className="text-sm text-[rgb(15,23,42)]/60 mb-2">
                      {template.subject}
                    </p>
                    <span className={`inline-block px-2 py-1 rounded text-xs font-medium ${
                      template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)]' :
                      template.type === 'reminder' ? 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)]' :
                      'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                    }`}>
                      {template.type}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {/* Recipients */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">
                Recipients ({recipients.length})
              </h3>
              <div className="space-y-3">
                {recipients.map(recipient => (
                  <div
                    key={recipient.id}
                    className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white text-sm font-semibold">
                        {recipient.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-medium text-[rgb(15,23,42)]">
                          {recipient.name}
                        </p>
                        <p className="text-sm text-[rgb(15,23,42)]/60">
                          {recipient.email}
                        </p>
                      </div>
                    </div>
                    {getStatusIcon(recipient.status)}
                  </div>
                ))}
              </div>
            </div>

            {/* Email Preview */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">
                Email Preview
              </h3>
              <div className="border border-[rgb(226,232,240)] rounded-lg p-4 bg-[rgb(248,250,252)]">
                <div className="mb-3">
                  <span className="text-sm font-medium text-[rgb(15,23,42)]/60">Subject:</span>
                  <p className="font-semibold text-[rgb(15,23,42)]">
                    {selectedTemplate.subject}
                  </p>
                </div>
                <div className="prose prose-sm max-w-none">
                  <div className="whitespace-pre-wrap text-[rgb(15,23,42)]">
                    {selectedTemplate.content}
                  </div>
                </div>
              </div>
            </div>

            {/* Send Button */}
            <button
              onClick={handleSendEmail}
              disabled={isLoading}
              className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-semibold shadow-md hover:shadow-lg active:scale-95"
              aria-label="Send emails to all recipients"
            >
              {isLoading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="w-4 h-4" />
                  Send to {recipients.length} Recipients
                </>
              )}
            </button>
          </div>
        )}

        {/* Campaigns Tab */}
        {activeTab === 'campaigns' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">
                Email Campaigns
              </h3>
              <span className="text-sm text-[rgb(15,23,42)]/60">
                {campaigns.length} campaigns
              </span>
            </div>

            {campaigns.map(campaign => (
              <div
                key={campaign.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm hover:shadow-md transition-shadow duration-200"
              >
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h4 className="font-semibold text-[rgb(15,23,42)] mb-1">
                      {campaign.name}
                    </h4>
                    <p className="text-sm text-[rgb(15,23,42)]/60">
                      {campaign.template.subject}
                    </p>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(campaign.status)}`}>
                    {campaign.status}
                  </span>
                </div>

                <div className="flex items-center gap-4 text-sm text-[rgb(15,23,42)]/60">
                  <span className="flex items-center gap-1">
                    <Users className="w-4 h-4" />
                    {campaign.recipients.length} recipients
                  </span>
                  <span>
                    {campaign.createdAt.toLocaleDateString()}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Templates Tab */}
        {activeTab === 'templates' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">
                Email Templates
              </h3>
              <span className="text-sm text-[rgb(15,23,42)]/60">
                {EMAIL_TEMPLATES.length} templates
              </span>
            </div>

            {EMAIL_TEMPLATES.map(template => (
              <div
                key={template.id}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-sm"
              >
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h4 className="font-semibold text-[rgb(15,23,42)] mb-1">
                      {template.name}
                    </h4>
                    <p className="text-sm text-[rgb(15,23,42)]/60 mb-2">
                      {template.subject}
                    </p>
                    <span className={`inline-block px-2 py-1 rounded text-xs font-medium ${
                      template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)]' :
                      template.type === 'reminder' ? 'bg-[rgb(255,140,0)]/10 text-[rgb(255,140,0)]' :
                      'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
                    }`}>
                      {template.type}
                    </span>
                  </div>
                </div>

                <div className="bg-[rgb(248,250,252)] rounded-lg p-4">
                  <p className="text-sm text-[rgb(15,23,42)] whitespace-pre-wrap line-clamp-3">
                    {template.content}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

