'use client'

import { useState, useEffect } from 'react'
import { MapPin, Users, Calendar, MessageCircle, Utensils, CheckCircle, Clock, Sun, Cloud, CloudRain, Snow, Thermometer } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  status: 'planning' | 'confirmed' | 'completed'
  memberCount: number
  weatherForecast: WeatherData[]
}

interface WeatherData {
  date: string
  temp: number
  condition: 'sunny' | 'cloudy' | 'rainy' | 'snowy'
  description: string
}

interface Task {
  id: string
  title: string
  assignee: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface Meal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner'
  assignee: string
}

interface Message {
  id: string
  sender: string
  content: string
  timestamp: string
}

interface Member {
  id: string
  name: string
  avatar: string
  rsvpStatus: 'pending' | 'accepted' | 'declined'
}

interface TripPlannerProps {
  initialTrip?: Trip
  onTripUpdate?: (trip: Trip) => void
}

export function TripPlanner({
  initialTrip = DEFAULT_TRIP,
  onTripUpdate = () => console.log('Trip updated')
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState<'overview' | 'tasks' | 'meals' | 'chat' | 'members'>('overview')
  const [trip, setTrip] = useState<Trip>(initialTrip)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [meals, setMeals] = useState<Meal[]>(DEFAULT_MEALS)
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [members, setMembers] = useState<Member[]>(DEFAULT_MEMBERS)
  const [newMessage, setNewMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const handleTaskToggle = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Message = {
      id: Date.now().toString(),
      sender: 'You',
      content: newMessage,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }

    setMessages(prev => [...prev, message])
    setNewMessage('')
  }

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return <Sun className="w-5 h-5 text-yellow-500" />
      case 'cloudy': return <Cloud className="w-5 h-5 text-gray-500" />
      case 'rainy': return <CloudRain className="w-5 h-5 text-[rgb(34, 139, 34)]" />
      case 'snowy': return <Snow className="w-5 h-5 text-blue-300" />
      default: return <Sun className="w-5 h-5 text-yellow-500" />
    }
  }

  const completedTasks = tasks.filter(task => task.completed).length
  const totalTasks = tasks.length
  const acceptedMembers = members.filter(member => member.rsvpStatus === 'accepted').length

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      {/* Header */}
      <div className="bg-[#228b22] text-[#ffffff] p-4 shadow-md">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-semibold">{trip.name}</h1>
            <div className="flex items-center gap-2 text-sm opacity-90 mt-1">
              <MapPin className="w-4 h-4" />
              <span>{trip.location}</span>
            </div>
          </div>
          <div className="text-right">
            <div className="text-sm opacity-90">
              {new Date(trip.startDate).toLocaleDateString()} - {new Date(trip.endDate).toLocaleDateString()}
            </div>
            <div className="flex items-center gap-1 text-sm mt-1">
              <Users className="w-4 h-4" />
              <span>{acceptedMembers} attending</span>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="pb-20">
        {activeTab === 'overview' && (
          <div className="p-4 space-y-4">
            {/* Trip Status */}
            <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-4 shadow-md">
              <h2 className="text-lg font-semibold text-[#0f172a] mb-3">Trip Status</h2>
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center">
                  <div className="text-2xl font-bold text-[#228b22]">{completedTasks}/{totalTasks}</div>
                  <div className="text-sm text-[#64748b]">Tasks Complete</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-[#228b22]">{acceptedMembers}</div>
                  <div className="text-sm text-[#64748b]">Members Confirmed</div>
                </div>
              </div>
            </div>

            {/* Weather Forecast */}
            <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-4 shadow-md">
              <h2 className="text-lg font-semibold text-[#0f172a] mb-3">Weather Forecast</h2>
              <div className="space-y-3">
                {trip.weatherForecast.map((weather, index) => (
                  <div key={index} className="flex items-center justify-between p-3 bg-[#f1f5f9] rounded-lg">
                    <div className="flex items-center gap-3">
                      {getWeatherIcon(weather.condition)}
                      <div>
                        <div className="font-medium text-[#0f172a]">
                          {new Date(weather.date).toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' })}
                        </div>
                        <div className="text-sm text-[#64748b]">{weather.description}</div>
                      </div>
                    </div>
                    <div className="flex items-center gap-1 text-[#0f172a] font-medium">
                      <Thermometer className="w-4 h-4" />
                      <span>{weather.temp}°F</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Quick Actions */}
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setActiveTab('tasks')}
                className="p-4 bg-[#ffffff] border border-[#e2e8f0] rounded-lg shadow-md text-left hover:bg-[#f1f5f9] transition-colors duration-200"
                aria-label="View tasks"
              >
                <CheckCircle className="w-6 h-6 text-[#228b22] mb-2" />
                <div className="font-medium text-[#0f172a]">Tasks</div>
                <div className="text-sm text-[#64748b]">{totalTasks - completedTasks} pending</div>
              </button>
              <button 
                onClick={() => setActiveTab('meals')}
                className="p-4 bg-[#ffffff] border border-[#e2e8f0] rounded-lg shadow-md text-left hover:bg-[#f1f5f9] transition-colors duration-200"
                aria-label="View meal plan"
              >
                <Utensils className="w-6 h-6 text-[#ff8c00] mb-2" />
                <div className="font-medium text-[#0f172a]">Meals</div>
                <div className="text-sm text-[#64748b]">{meals.length} planned</div>
              </button>
            </div>
          </div>
        )}

        {activeTab === 'tasks' && (
          <div className="p-4">
            <h2 className="text-lg font-semibold text-[#0f172a] mb-4">Trip Tasks</h2>
            <div className="space-y-3">
              {tasks.map((task) => (
                <div key={task.id} className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-4 shadow-md">
                  <div className="flex items-start gap-3">
                    <button
                      onClick={() => handleTaskToggle(task.id)}
                      className={`w-6 h-6 rounded-full border-2 flex items-center justify-center mt-0.5 transition-colors duration-200 ${
                        task.completed 
                          ? 'bg-[#228b22] border-[#228b22]' 
                          : 'border-[#e2e8f0] hover:border-[#228b22]'
                      }`}
                      aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
                    >
                      {task.completed && <CheckCircle className="w-4 h-4 text-[#ffffff]" />}
                    </button>
                    <div className="flex-1">
                      <div className={`font-medium ${task.completed ? 'line-through text-[#64748b]' : 'text-[#0f172a]'}`}>
                        {task.title}
                      </div>
                      <div className="flex items-center gap-4 mt-2 text-sm text-[#64748b]">
                        <span>Assigned to: {task.assignee}</span>
                        <div className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          <span>Due: {new Date(task.dueDate).toLocaleDateString()}</span>
                        </div>
                      </div>
                      <div className={`inline-block px-2 py-1 rounded-full text-xs mt-2 ${
                        task.category === 'food' ? 'bg-[#ff8c00]/20 text-[#ff8c00]' :
                        task.category === 'equipment' ? 'bg-[#228b22]/20 text-[#228b22]' :
                        'bg-[#64748b]/20 text-[#64748b]'
                      }`}>
                        {task.category}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'meals' && (
          <div className="p-4">
            <h2 className="text-lg font-semibold text-[#0f172a] mb-4">Meal Plan</h2>
            <div className="space-y-4">
              {['Saturday', 'Sunday'].map((day) => (
                <div key={day} className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-4 shadow-md">
                  <h3 className="font-semibold text-[#0f172a] mb-3">{day}</h3>
                  <div className="space-y-3">
                    {meals.filter(meal => meal.day === day).map((meal) => (
                      <div key={meal.id} className="flex items-center justify-between p-3 bg-[#f1f5f9] rounded-lg">
                        <div className="flex items-center gap-3">
                          <Utensils className="w-5 h-5 text-[#ff8c00]" />
                          <div>
                            <div className="font-medium text-[#0f172a] capitalize">{meal.time}</div>
                            <div className="text-sm text-[#64748b]">{meal.name}</div>
                          </div>
                        </div>
                        <div className="text-sm text-[#64748b]">
                          by {meal.assignee}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="flex flex-col h-[calc(100vh-140px)]">
            <div className="p-4 border-b border-[#e2e8f0]">
              <h2 className="text-lg font-semibold text-[#0f172a]">Group Chat</h2>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
              {messages.map((message) => (
                <div key={message.id} className={`flex ${message.sender === 'You' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-3 rounded-lg ${
                    message.sender === 'You' 
                      ? 'bg-[#228b22] text-[#ffffff]' 
                      : 'bg-[#f1f5f9] text-[#0f172a]'
                  }`}>
                    {message.sender !== 'You' && (
                      <div className="text-xs font-medium mb-1 opacity-70">{message.sender}</div>
                    )}
                    <div className="text-sm">{message.content}</div>
                    <div className="text-xs opacity-70 mt-1">{message.timestamp}</div>
                  </div>
                </div>
              ))}
            </div>
            <div className="p-4 border-t border-[#e2e8f0]">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Type a message..."
                  className="flex-1 px-4 py-2 border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:border-[#228b22] focus:outline-none focus:ring-1 focus:ring-[#228b22]/50 transition-all duration-200"
                  aria-label="Type a message"
                />
                <button
                  onClick={handleSendMessage}
                  disabled={!newMessage.trim()}
                  className="px-4 py-2 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7b1e] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-200 font-medium shadow-md hover:shadow-lg active:scale-95"
                  aria-label="Send message"
                >
                  Send
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'members' && (
          <div className="p-4">
            <h2 className="text-lg font-semibold text-[#0f172a] mb-4">Trip Members</h2>
            <div className="space-y-3">
              {members.map((member) => (
                <div key={member.id} className="bg-[#ffffff] border border-[#e2e8f0] rounded-lg p-4 shadow-md">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-[#228b22] rounded-full flex items-center justify-center text-[#ffffff] font-semibold">
                        {member.name.charAt(0)}
                      </div>
                      <div>
                        <div className="font-medium text-[#0f172a]">{member.name}</div>
                        <div className="text-sm text-[#64748b]">
                          {member.rsvpStatus === 'accepted' && 'Attending'}
                          {member.rsvpStatus === 'declined' && 'Not attending'}
                          {member.rsvpStatus === 'pending' && 'Pending response'}
                        </div>
                      </div>
                    </div>
                    <div className={`px-3 py-1 rounded-full text-xs font-medium ${
                      member.rsvpStatus === 'accepted' ? 'bg-[#228b22]/20 text-[#228b22]' :
                      member.rsvpStatus === 'declined' ? 'bg-[#dc2626]/20 text-[#dc2626]' :
                      'bg-[#ff8c00]/20 text-[#ff8c00]'
                    }`}>
                      {member.rsvpStatus}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-[#ffffff] border-t border-[#e2e8f0] shadow-lg">
        <div className="flex">
          {[
            { id: 'overview', icon: MapPin, label: 'Overview' },
            { id: 'tasks', icon: CheckCircle, label: 'Tasks' },
            { id: 'meals', icon: Utensils, label: 'Meals' },
            { id: 'chat', icon: MessageCircle, label: 'Chat' },
            { id: 'members', icon: Users, label: 'Members' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex-1 p-3 flex flex-col items-center gap-1 transition-colors duration-200 ${
                activeTab === tab.id 
                  ? 'text-[#228b22]' 
                  : 'text-[#64748b] hover:text-[#228b22]'
              }`}
              aria-label={`Navigate to ${tab.label}`}
            >
              <tab.icon className="w-5 h-5" />
              <span className="text-xs font-medium">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

