'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageCircle, Utensils, CheckCircle, Clock, AlertTriangle } from 'lucide-react'

interface TripLocation {
  id: string
  name: string
  coordinates: { lat: number; lng: number }
  difficulty: 'Easy' | 'Moderate' | 'Difficult'
  terrain: string
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar: string
  status: 'confirmed' | 'pending' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface Meal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner'
  assignedTo: string
}

interface WeatherData {
  day: string
  high: number
  low: number
  condition: string
  icon: string
}

interface OffRoadTripPlannerProps {
  tripId?: string
  initialLocation?: TripLocation
  members?: GroupMember[]
  onLocationSave?: (location: TripLocation) => void
  onTaskAssign?: (task: Task) => void
  onRsvpUpdate?: (memberId: string, status: string) => void
}

export function OffRoadTripPlanner({
  tripId = 'trip-001',
  initialLocation,
  members = DEFAULT_MEMBERS,
  onLocationSave = (location) => console.log('Location saved:', location),
  onTaskAssign = (task) => console.log('Task assigned:', task),
  onRsvpUpdate = (memberId, status) => console.log('RSVP updated:', memberId, status)
}: OffRoadTripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('location')
  const [selectedLocation, setSelectedLocation] = useState<TripLocation | null>(initialLocation || null)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [meals, setMeals] = useState<Meal[]>(DEFAULT_MEALS)
  const [weather, setWeather] = useState<WeatherData[]>(DEFAULT_WEATHER)
  const [chatMessages, setChatMessages] = useState(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [tripMembers, setTripMembers] = useState<GroupMember[]>(members)

  const handleLocationSelect = (location: TripLocation) => {
    setSelectedLocation(location)
    onLocationSave(location)
  }

  const handleTaskToggle = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const handleRsvpChange = (memberId: string, status: 'confirmed' | 'pending' | 'declined') => {
    setTripMembers(prev => prev.map(member =>
      member.id === memberId ? { ...member, status } : member
    ))
    onRsvpUpdate(memberId, status)
  }

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      const message = {
        id: Date.now().toString(),
        sender: 'You',
        message: newMessage,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        avatar: '/api/placeholder/32/32'
      }
      setChatMessages(prev => [...prev, message])
      setNewMessage('')
    }
  }

  const renderLocationTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg p-4 border border-[#e2e8f0ff]">
        <h3 className="font-semibold text-[#0f172aff] mb-3 flex items-center gap-2">
          <MapPin className="w-5 h-5 text-[#228b22ff]" />
          Select Trail Location
        </h3>
        <div className="space-y-3">
          {SAMPLE_LOCATIONS.map((location) => (
            <div
              key={location.id}
              onClick={() => handleLocationSelect(location)}
              className={`p-4 rounded-lg border-2 cursor-pointer transition-all duration-200 ${
                selectedLocation?.id === location.id
                  ? 'border-[#228b22ff] bg-[#228b22ff]/5'
                  : 'border-[#e2e8f0ff] hover:border-[#228b22ff]/50'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <h4 className="font-medium text-[#0f172aff]">{location.name}</h4>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  location.difficulty === 'Easy' ? 'bg-green-100 text-green-700' :
                  location.difficulty === 'Moderate' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-red-100 text-red-700'
                }`}>
                  {location.difficulty}
                </span>
              </div>
              <p className="text-sm text-gray-600">{location.terrain}</p>
              <p className="text-xs text-gray-500 mt-1">
                {location.coordinates.lat.toFixed(4)}, {location.coordinates.lng.toFixed(4)}
              </p>
            </div>
          ))}
        </div>
      </div>

      {selectedLocation && (
        <div className="bg-white rounded-lg p-4 border border-[#e2e8f0ff] shadow-md">
          <h4 className="font-semibold text-[#0f172aff] mb-2">Selected Location</h4>
          <p className="text-[#228b22ff] font-medium">{selectedLocation.name}</p>
          <p className="text-sm text-gray-600">{selectedLocation.terrain}</p>
        </div>
      )}
    </div>
  )

  const renderTasksTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg p-4 border border-[#e2e8f0ff]">
        <h3 className="font-semibold text-[#0f172aff] mb-3 flex items-center gap-2">
          <Users className="w-5 h-5 text-[#228b22ff]" />
          Task Assignments
        </h3>
        <div className="space-y-3">
          {tasks.map((task) => {
            const assignedMember = tripMembers.find(m => m.id === task.assignedTo)
            return (
              <div
                key={task.id}
                className="flex items-center justify-between p-3 bg-white rounded-lg border border-[#e2e8f0ff]"
              >
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => handleTaskToggle(task.id)}
                    className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                      task.completed
                        ? 'bg-[#228b22ff] border-[#228b22ff] text-white'
                        : 'border-[#e2e8f0ff] hover:border-[#228b22ff]'
                    }`}
                  >
                    {task.completed && <CheckCircle className="w-3 h-3" />}
                  </button>
                  <div>
                    <p className={`font-medium ${task.completed ? 'line-through text-gray-500' : 'text-[#0f172aff]'}`}>
                      {task.title}
                    </p>
                    <p className="text-xs text-gray-500">
                      Due: {task.dueDate} • {assignedMember?.name || 'Unassigned'}
                    </p>
                  </div>
                </div>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  task.category === 'food' ? 'bg-orange-100 text-orange-700' :
                  task.category === 'equipment' ? 'bg-blue-100 text-blue-700' :
                  'bg-purple-100 text-purple-700'
                }`}>
                  {task.category}
                </span>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )

  const renderMealsTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg p-4 border border-[#e2e8f0ff]">
        <h3 className="font-semibold text-[#0f172aff] mb-3 flex items-center gap-2">
          <Utensils className="w-5 h-5 text-[#228b22ff]" />
          Meal Schedule
        </h3>
        <div className="space-y-4">
          {['Saturday', 'Sunday'].map(day => (
            <div key={day} className="bg-white rounded-lg p-4 border border-[#e2e8f0ff]">
              <h4 className="font-semibold text-[#0f172aff] mb-3">{day}</h4>
              <div className="space-y-2">
                {meals.filter(meal => meal.day === day).map(meal => {
                  const assignedMember = tripMembers.find(m => m.id === meal.assignedTo)
                  return (
                    <div key={meal.id} className="flex justify-between items-center p-2 bg-[#f8fafcff] rounded">
                      <div>
                        <p className="font-medium text-[#0f172aff] capitalize">{meal.time}</p>
                        <p className="text-sm text-gray-600">{meal.name}</p>
                      </div>
                      <p className="text-sm text-[#228b22ff] font-medium">{assignedMember?.name}</p>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )

  const renderWeatherTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg p-4 border border-[#e2e8f0ff]">
        <h3 className="font-semibold text-[#0f172aff] mb-3 flex items-center gap-2">
          <Clock className="w-5 h-5 text-[#228b22ff]" />
          Weather Forecast
        </h3>
        <div className="grid grid-cols-2 gap-3">
          {weather.map((day, index) => (
            <div key={index} className="bg-white rounded-lg p-4 border border-[#e2e8f0ff] text-center">
              <p className="font-semibold text-[#0f172aff] mb-2">{day.day}</p>
              <div className="text-2xl mb-2">{day.icon}</div>
              <p className="text-sm text-gray-600 mb-2">{day.condition}</p>
              <div className="flex justify-center gap-2 text-sm">
                <span className="font-semibold text-[#0f172aff]">{day.high}°</span>
                <span className="text-gray-500">{day.low}°</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )

  const renderChatTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg border border-[#e2e8f0ff] h-96 flex flex-col">
        <div className="p-4 border-b border-[#e2e8f0ff]">
          <h3 className="font-semibold text-[#0f172aff] flex items-center gap-2">
            <MessageCircle className="w-5 h-5 text-[#228b22ff]" />
            Group Chat
          </h3>
        </div>
