                </div>
                <p className="text-sm text-gray-700">{msg.message}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="p-4 border-t border-[#e2e8f0ff]">
          <div className="flex gap-2">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="Type a message..."
              className="flex-1 px-3 py-2 border border-[#e2e8f0ff] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#228b22ff] focus:border-transparent"
