            <button
              onClick={handleSendMessage}
              className="px-4 py-2 bg-[#228b22ff] text-white rounded-lg hover:bg-[#228b22ff]/90 transition-colors duration-150 font-medium"
            >
              Send
            </button>
          </div>
        </div>
      </div>
    </div>
  )

  const renderRsvpTab = () => (
    <div className="space-y-4">
      <div className="bg-[#f8fafcff] rounded-lg p-4 border border-[#e2e8f0ff]">
        <h3 className="font-semibold text-[#0f172aff] mb-3 flex items-center gap-2">
          <Users className="w-5 h-5 text-[#228b22ff]" />
          Trip Members & RSVP
        </h3>
        <div className="space-y-3">
          {tripMembers.map((member) => (
            <div key={member.id} className="flex items-center justify-between p-3 bg-white rounded-lg border border-[#e2e8f0ff]">
              <div className="flex items-center gap-3">
                <img
                  src={member.avatar}
                  alt={member.name}
                  className="w-10 h-10 rounded-full"
                />
                <div>
                  <p className="font-medium text-[#0f172aff]">{member.name}</p>
                  <p className="text-sm text-gray-500">{member.email}</p>
                </div>
              </div>
              <div className="flex gap-2">
                {(['confirmed', 'pending', 'declined'] as const).map((status) => (
                  <button
                    key={status}
                    onClick={() => handleRsvpChange(member.id, status)}
                    className={`px-3 py-1 rounded-full text-xs font-medium transition-colors duration-150 ${
                      member.status === status
                        ? status === 'confirmed' ? 'bg-green-100 text-green-700' :
                          status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                          'bg-red-100 text-red-700'
                        : 'bg-[rgb(241, 245, 249)] text-gray-500 hover:bg-gray-200'
                    }`}
                  >
                    {status === 'confirmed' ? '✓' : status === 'pending' ? '?' : '✗'}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )

  const tabs = [
    { id: 'location', label: 'Location', icon: MapPin },
    { id: 'tasks', label: 'Tasks', icon: Users },
    { id: 'meals', label: 'Meals', icon: Utensils },
    { id: 'weather', label: 'Weather', icon: Clock },
    { id: 'chat', label: 'Chat', icon: MessageCircle },
    { id: 'rsvp', label: 'RSVP', icon: CheckCircle }
  ]

  return (
    <div className="min-h-screen bg-[#ffffffff] font-medium">
      <div className="max-w-md mx-auto bg-white">
        {/* Header */}
        <div className="bg-[#228b22ff] text-white p-4">
          <h1 className="text-xl font-bold">Off-Road Trip Planner</h1>
          <p className="text-sm opacity-90">Plan your adventure</p>
        </div>

        {/* Content */}
        <div className="p-4 pb-20">
          {activeTab === 'location' && renderLocationTab()}
          {activeTab === 'tasks' && renderTasksTab()}
          {activeTab === 'meals' && renderMealsTab()}
          {activeTab === 'weather' && renderWeatherTab()}
          {activeTab === 'chat' && renderChatTab()}
          {activeTab === 'rsvp' && renderRsvpTab()}
        </div>

        {/* Bottom Navigation */}
        <div className="fixed bottom-0 left-1/2 transform -translate-x-1/2 w-full max-w-md bg-white border-t border-[#e2e8f0ff]">
          <div className="grid grid-cols-6 gap-1 p-2">
            {tabs.map((tab) => {
              const Icon = tab.icon
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors duration-150 ${
                    activeTab === tab.id
                      ? 'bg-[#228b22ff] text-white'
                      : 'text-gray-600 hover:bg-[#f8fafcff]'
                  }`}
                >
                  <Icon className="w-5 h-5" />
                  <span className="text-xs font-medium">{tab.label}</span>
                </button>
              )
            })}
          </div>
        </div>
      </div>
    </div>
  )
}

