'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, Paperclip, Smile, MoreVertical, MapPin, Calendar, Users } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'location' | 'task' | 'system'
  metadata?: {
    location?: { name: string; coordinates: [number, number] }
    task?: { name: string; assignee: string; dueDate: string }
  }
}

interface GroupChatProps {
  tripId?: string
  messages?: Message[]
  currentUserId?: string
  onSendMessage?: (content: string, type: 'text' | 'location' | 'task') => void
  onLocationShare?: () => void
  onTaskCreate?: () => void
}

export function GroupChat({
  tripId = 'trip-1',
  messages = DEFAULT_MESSAGES,
  currentUserId = 'user-1',
  onSendMessage = (content, type) => console.log('Send message:', content, type),
  onLocationShare = () => console.log('Share location'),
  onTaskCreate = () => console.log('Create task')
}: GroupChatProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [showAttachments, setShowAttachments] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    onSendMessage(newMessage, 'text')
    setNewMessage('')
    setShowAttachments(false)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const renderMessage = (message: Message, index: number) => {
    const isCurrentUser = message.userId === currentUserId
    const showDate = index === 0 || 
      formatDate(message.timestamp) !== formatDate(messages[index - 1]?.timestamp)

    return (
      <div key={message.id} className="space-y-2">
        {showDate && (
          <div className="flex justify-center py-2">
            <span className="px-3 py-1 text-xs font-medium text-slate-600 bg-slate-100 rounded-full">
              {formatDate(message.timestamp)}
            </span>
          </div>
        )}

        <div className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}>
          {!isCurrentUser && (
            <div className="flex-shrink-0">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-green-400 to-green-600 flex items-center justify-center text-white text-sm font-medium">
                {message.userName.charAt(0)}
              </div>
            </div>
          )}

          <div className={`max-w-[75%] ${isCurrentUser ? 'items-end' : 'items-start'} flex flex-col gap-1`}>
            {!isCurrentUser && (
              <span className="text-xs font-medium text-slate-600 px-1">
                {message.userName}
              </span>
            )}

            <div className={`rounded-2xl px-4 py-2 ${
              isCurrentUser 
                ? 'bg-[rgb(34,139,34)] text-white' 
                : 'bg-slate-100 text-slate-900'
            } ${message.type !== 'text' ? 'border border-slate-200' : ''}`}>
              {message.type === 'text' && (
                <p className="text-sm leading-relaxed break-words">{message.content}</p>
              )}

              {message.type === 'location' && message.metadata?.location && (
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-[rgb(255,140,0)]" />
                  <div>
                    <p className="text-sm font-medium">{message.metadata.location.name}</p>
                    <p className="text-xs opacity-75">Shared location</p>
                  </div>
                </div>
              )}

              {message.type === 'task' && message.metadata?.task && (
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4 text-[rgb(255,140,0)]" />
                  <div>
                    <p className="text-sm font-medium">{message.metadata.task.name}</p>
                    <p className="text-xs opacity-75">
                      Assigned to {message.metadata.task.assignee} • Due {message.metadata.task.dueDate}
                    </p>
                  </div>
                </div>
              )}

              {message.type === 'system' && (
                <p className="text-xs text-center italic opacity-75">{message.content}</p>
              )}
            </div>

            <span className={`text-xs text-slate-500 px-1 ${isCurrentUser ? 'text-right' : 'text-left'}`}>
              {formatTime(message.timestamp)}
            </span>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen bg-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-slate-200 bg-white">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-gradient-to-br from-green-400 to-green-600 flex items-center justify-center">
            <Users className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="font-semibold text-slate-900">Trip Chat</h1>
            <p className="text-sm text-slate-600">5 members • 3 online</p>
          </div>
        </div>

        <button
          className="p-2 hover:bg-slate-100 rounded-lg transition-colors duration-150"
          aria-label="More options"
        >
          <MoreVertical className="w-5 h-5 text-slate-600" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => renderMessage(message, index))}

        {isTyping && (
          <div className="flex gap-3">
            <div className="w-8 h-8 rounded-full bg-slate-200 animate-pulse" />
            <div className="bg-slate-100 rounded-2xl px-4 py-2">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Attachment Menu */}
      {showAttachments && (
        <div className="p-4 border-t border-slate-200 bg-slate-50">
          <div className="flex gap-4 justify-center">
            <button
              onClick={() => {
                onLocationShare()
                setShowAttachments(false)
              }}
              className="flex flex-col items-center gap-2 p-3 bg-white rounded-xl shadow-sm hover:shadow-md transition-shadow duration-150"
              aria-label="Share location"
            >
              <div className="w-12 h-12 bg-[rgb(255,140,0)] rounded-full flex items-center justify-center">
                <MapPin className="w-6 h-6 text-white" />
              </div>
              <span className="text-xs font-medium text-slate-700">Location</span>
            </button>

            <button
              onClick={() => {
                onTaskCreate()
                setShowAttachments(false)
              }}
              className="flex flex-col items-center gap-2 p-3 bg-white rounded-xl shadow-sm hover:shadow-md transition-shadow duration-150"
              aria-label="Create task"
            >
              <div className="w-12 h-12 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center">
                <Calendar className="w-6 h-6 text-white" />
              </div>
              <span className="text-xs font-medium text-slate-700">Task</span>
            </button>
          </div>
        </div>
      )}

      {/* Input */}
      <div className="p-4 border-t border-slate-200 bg-white">
        <div className="flex items-end gap-3">
          <button
            onClick={() => setShowAttachments(!showAttachments)}
            className={`p-2 rounded-lg transition-colors duration-150 ${
              showAttachments 
                ? 'bg-[rgb(34,139,34)] text-white' 
                : 'hover:bg-slate-100 text-slate-600'
            }`}
            aria-label="Attachments"
          >
            <Paperclip className="w-5 h-5" />
          </button>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 placeholder-slate-500 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150 resize-none"
              aria-label="Message input"
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-white rounded-2xl hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 shadow-md hover:shadow-lg active:scale-95"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

