'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Camera, Plus, X } from 'lucide-react'

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  tags: string[]
  estimatedCost: string
}

interface CreateTripFormProps {
  onSubmit?: (data: TripFormData) => void
  onCancel?: () => void
  initialData?: Partial<TripFormData>
}

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  onCancel = () => console.log('Trip creation cancelled'),
  initialData = {}
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    estimatedCost: '',
    ...initialData
  })

  const [newTag, setNewTag] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1000)) // Simulate API call
      onSubmit(formData)
    } catch (error) {
      console.error('Error creating trip:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleInputChange = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const addTag = () => {
    if (newTag.trim() && !formData.tags.includes(newTag.trim())) {
      handleInputChange('tags', [...formData.tags, newTag.trim()])
      setNewTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    handleInputChange('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const difficultyOptions = [
    { value: 'easy', label: 'Easy', color: 'bg-[rgb(34,139,34)]' },
    { value: 'moderate', label: 'Moderate', color: 'bg-[rgb(255,140,0)]' },
    { value: 'hard', label: 'Hard', color: 'bg-[rgb(220,38,38)]' }
  ]

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-2xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">Create New Trip</h1>
          <p className="text-[rgb(100,116,139)] text-sm">Plan your next off-roading adventure</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Trip Name */}
          <div>
            <label htmlFor="trip-name" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Trip Name *
            </label>
            <input
              id="trip-name"
              type="text"
              value={formData.name}
              onChange={(e) => handleInputChange('name', e.target.value)}
              placeholder="Enter trip name"
              className={`w-full px-4 py-3 bg-[rgb(255,255,255)] border rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                errors.name ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
              }`}
              aria-describedby={errors.name ? 'name-error' : undefined}
            />
            {errors.name && (
              <p id="name-error" className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                {errors.name}
              </p>
            )}
          </div>

          {/* Location */}
          <div>
            <label htmlFor="location" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              <MapPin className="inline w-4 h-4 mr-1" />
              Location *
            </label>
            <input
              id="location"
              type="text"
              value={formData.location}
              onChange={(e) => handleInputChange('location', e.target.value)}
              placeholder="Enter destination"
              className={`w-full px-4 py-3 bg-[rgb(255,255,255)] border rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                errors.location ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
              }`}
              aria-describedby={errors.location ? 'location-error' : undefined}
            />
            {errors.location && (
              <p id="location-error" className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                {errors.location}
              </p>
            )}
          </div>

          {/* Dates */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label htmlFor="start-date" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                <Calendar className="inline w-4 h-4 mr-1" />
                Start Date *
              </label>
              <input
                id="start-date"
                type="date"
                value={formData.startDate}
                onChange={(e) => handleInputChange('startDate', e.target.value)}
                min={new Date().toISOString().split('T')[0]}
                className={`w-full px-4 py-3 bg-[rgb(255,255,255)] border rounded-lg text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                  errors.startDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-describedby={errors.startDate ? 'start-date-error' : undefined}
              />
              {errors.startDate && (
                <p id="start-date-error" className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                  {errors.startDate}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="end-date" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                <Calendar className="inline w-4 h-4 mr-1" />
                End Date *
              </label>
              <input
                id="end-date"
                type="date"
                value={formData.endDate}
                onChange={(e) => handleInputChange('endDate', e.target.value)}
                min={formData.startDate || new Date().toISOString().split('T')[0]}
                className={`w-full px-4 py-3 bg-[rgb(255,255,255)] border rounded-lg text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                  errors.endDate ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                }`}
                aria-describedby={errors.endDate ? 'end-date-error' : undefined}
              />
              {errors.endDate && (
                <p id="end-date-error" className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                  {errors.endDate}
                </p>
              )}
            </div>
          </div>

          {/* Description */}
          <div>
            <label htmlFor="description" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Description
            </label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => handleInputChange('description', e.target.value)}
              placeholder="Describe your trip..."
              rows={4}
              className="w-full px-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 resize-none"
            />
          </div>

          {/* Max Participants */}
          <div>
            <label htmlFor="max-participants" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              <Users className="inline w-4 h-4 mr-1" />
              Max Participants
            </label>
            <input
              id="max-participants"
              type="number"
              value={formData.maxParticipants}
              onChange={(e) => handleInputChange('maxParticipants', parseInt(e.target.value) || 0)}
              min="1"
              max="50"
              className={`w-full px-4 py-3 bg-[rgb(255,255,255)] border rounded-lg text-[rgb(15,23,42)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200 ${
                errors.maxParticipants ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
              }`}
              aria-describedby={errors.maxParticipants ? 'participants-error' : undefined}
            />
            {errors.maxParticipants && (
              <p id="participants-error" className="mt-1 text-sm text-[rgb(220,38,38)]" role="alert">
                {errors.maxParticipants}
              </p>
            )}
          </div>

          {/* Difficulty */}
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-3">
              Difficulty Level
            </label>
            <div className="grid grid-cols-3 gap-3">
              {difficultyOptions.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => handleInputChange('difficulty', option.value)}
                  className={`px-4 py-3 rounded-lg border-2 transition-all duration-200 font-medium text-sm ${
                    formData.difficulty === option.value
                      ? `${option.color} text-white border-transparent shadow-md`
                      : 'bg-[rgb(255,255,255)] text-[rgb(15,23,42)] border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                  }`}
                  aria-pressed={formData.difficulty === option.value}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          {/* Estimated Cost */}
          <div>
            <label htmlFor="estimated-cost" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Estimated Cost per Person
            </label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[rgb(100,116,139)]">$</span>
              <input
                id="estimated-cost"
                type="number"
                value={formData.estimatedCost}
                onChange={(e) => handleInputChange('estimatedCost', e.target.value)}
                placeholder="0"
                min="0"
                step="0.01"
                className="w-full pl-8 pr-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200"
              />
            </div>
          </div>

          {/* Tags */}
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Tags
            </label>
            <div className="flex flex-wrap gap-2 mb-3">
              {formData.tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-flex items-center gap-1 px-3 py-1 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-full text-sm border border-[rgb(226,232,240)]"
                >
                  {tag}
                  <button
                    type="button"
                    onClick={() => removeTag(tag)}
                    className="text-[rgb(100,116,139)] hover:text-[rgb(220,38,38)] transition-colors duration-200"
                    aria-label={`Remove ${tag} tag`}
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              ))}
            </div>
            <div className="flex gap-2">
              <input
                type="text"
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addTag())}
                placeholder="Add a tag..."
                className="flex-1 px-4 py-2 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent transition-all duration-200"
              />
              <button
                type="button"
                onClick={addTag}
                disabled={!newTag.trim()}
                className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(46,125,50)] disabled:bg-[rgb(148,163,184)] disabled:cursor-not-allowed transition-all duration-200 font-medium"
                aria-label="Add tag"
              >
                <Plus className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex flex-col sm:flex-row gap-3 pt-6">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 px-6 py-3 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-lg border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-all duration-200 font-medium"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex-1 px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(46,125,50)] disabled:bg-[rgb(148,163,184)] disabled:cursor-not-allowed transition-all duration-200 font-medium shadow-md hover:shadow-lg active:scale-95"
            >
              {isSubmitting ? (
                <span className="flex items-center justify-center gap-2">
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Creating Trip...
                </span>
              ) : (
                'Create Trip'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

