const DIFFICULTY_COLORS = {
  Easy: 'bg-[#22c55e] text-white',
  Moderate: 'bg-[#f59e0b] text-white',
  Difficult: 'bg-[#ef4444] text-white',
  Expert: 'bg-[#7c2d12] text-white'
}

export function LocationManagement({
  onLocationSelect = () => {},
  savedLocations = [],
  onSaveLocation = () => {},
  onRemoveLocation = () => {}
}: LocationManagementProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [activeTab, setActiveTab] = useState<'search' | 'saved'>('search')
  const [showFilters, setShowFilters] = useState(false)
  const [difficultyFilter, setDifficultyFilter] = useState<string[]>([])
  const [terrainFilter, setTerrainFilter] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)

  const allTerrains = Array.from(new Set(locations.flatMap(loc => loc.terrain)))

  useEffect(() => {
    const debounceTimer = setTimeout(() => {
      filterLocations()
    }, 300)

    return () => clearTimeout(debounceTimer)
  }, [searchQuery, difficultyFilter, terrainFilter, locations])

  const filterLocations = () => {
    setIsLoading(true)

    let filtered = locations.filter(location => {
      const matchesSearch = location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                           location.description.toLowerCase().includes(searchQuery.toLowerCase())

      const matchesDifficulty = difficultyFilter.length === 0 || 
                               difficultyFilter.includes(location.difficulty)

      const matchesTerrain = terrainFilter.length === 0 || 
                            terrainFilter.some(terrain => location.terrain.includes(terrain))

      return matchesSearch && matchesDifficulty && matchesTerrain
    })

    setTimeout(() => {
      setFilteredLocations(filtered)
      setIsLoading(false)
    }, 200)
  }

  const toggleFavorite = (locationId: string) => {
    setLocations(prev => prev.map(loc => 
      loc.id === locationId 
        ? { ...loc, isFavorite: !loc.isFavorite }
        : loc
    ))
  }

  const handleSaveLocation = (location: Location) => {
    onSaveLocation(location)
    toggleFavorite(location.id)
  }

  const clearFilters = () => {
    setDifficultyFilter([])
    setTerrainFilter([])
    setSearchQuery('')
  }

  const LocationCard = ({ location }: { location: Location }) => (
    <div 
      className="bg-white border border-[#e2e8f0] rounded-xl p-4 shadow-md hover:shadow-lg transition-all duration-200 active:scale-[0.98]"
      onClick={() => onLocationSelect(location)}
      role="button"
      tabIndex={0}
      aria-label={`Select ${location.name}`}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onLocationSelect(location)
        }
      }}
    >
      <div className="relative mb-3">
        <div className="w-full h-32 bg-[#f1f5f9] rounded-lg overflow-hidden">
          <div className="w-full h-full bg-gradient-to-br from-[#22c55e]/20 to-[#16a34a]/30 flex items-center justify-center">
            <MapPin className="w-8 h-8 text-[#22c55e]" />
          </div>
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation()
            handleSaveLocation(location)
          }}
          className="absolute top-2 right-2 p-2 bg-white/90 rounded-full shadow-md hover:bg-white transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-[#22c55e] focus:ring-offset-1"
          aria-label={location.isFavorite ? 'Remove from favorites' : 'Add to favorites'}
        >
          <Heart 
            className={`w-4 h-4 ${location.isFavorite ? 'fill-[#dc2626] text-[#dc2626]' : 'text-gray-400'}`} 
          />
        </button>
      </div>

      <div className="space-y-2">
        <div className="flex items-start justify-between gap-2">
          <h3 className="font-semibold text-[#0f172a] text-lg leading-tight">{location.name}</h3>
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${DIFFICULTY_COLORS[location.difficulty]}`}>
            {location.difficulty}
          </span>
        </div>

        <p className="text-[#64748b] text-sm leading-relaxed line-clamp-2">
          {location.description}
        </p>

        <div className="flex items-center gap-4 text-sm text-[#64748b]">
          <div className="flex items-center gap-1">
            <Star className="w-4 h-4 fill-[#f59e0b] text-[#f59e0b]" />
            <span className="font-medium">{location.rating}</span>
            <span>({location.reviewCount})</span>
          </div>
          <div className="flex items-center gap-1">
            <Navigation className="w-4 h-4" />
            <span>{location.distance} mi</span>
          </div>
        </div>

        <div className="flex flex-wrap gap-1">
          {location.terrain.slice(0, 3).map((terrain, index) => (
            <span 
              key={index}
              className="px-2 py-1 bg-[#f1f5f9] text-[#475569] rounded-md text-xs font-medium"
            >
              {terrain}
            </span>
          ))}
          {location.terrain.length > 3 && (
            <span className="px-2 py-1 bg-[#f1f5f9] text-[#475569] rounded-md text-xs font-medium">
              +{location.terrain.length - 3} more
            </span>
          )}
        </div>
      </div>
