  const FilterSection = () => (
    <div className="bg-white border border-[#e2e8f0] rounded-xl p-4 space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-[#0f172a]">Filters</h3>
        <button
          onClick={clearFilters}
          className="text-[#22c55e] text-sm font-medium hover:text-[#16a34a] transition-colors duration-150"
        >
          Clear All
        </button>
      </div>

      <div className="space-y-3">
        <div>
          <label className="block text-sm font-medium text-[#374151] mb-2">Difficulty</label>
          <div className="flex flex-wrap gap-2">
