                  <Icon className="w-5 h-5" />
                  {item.badge && (
                    <span className="absolute -top-1 -right-1 bg-[#f97316] text-white text-xs w-4 h-4 rounded-full flex items-center justify-center font-medium">
                      {item.badge}
                    </span>
                  )}
