            <Users className="w-5 h-5" />
            Group Availability for {formatDate(selectedDate)}
          </h3>

          {isCheckingAvailability ? (
            <div className="space-y-2">
              {[1, 2, 3].map(i => (
                <div key={i} className="h-12 bg-[rgb(248,250,252)] rounded-lg animate-pulse" />
