            <div className="flex items-center justify-center gap-6 text-sm text-[#64748b]">
              <div className="flex items-center gap-1">
                <MapPin size={16} />
                <span>{profile.location}</span>
              </div>
              <div className="flex items-center gap-1">
                <Calendar size={16} />
                <span>Since {profile.stats.memberSince}</span>
