        </div>

        {/* Tab Navigation */}
        <div className="bg-[#ffffff] border border-[#e2e8f0] rounded-xl shadow-md overflow-hidden">
          <div className="flex">
            {[
              { id: 'profile', label: 'Profile', icon: User },
