// TypeScript Interfaces
interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  status: 'planning' | 'confirmed' | 'active' | 'completed'
  memberCount: number
  imageUrl?: string
  difficulty: 'easy' | 'moderate' | 'hard'
  weather?: WeatherData
}

interface WeatherData {
  temperature: number
  condition: 'sunny' | 'rainy' | 'snowy' | 'cloudy'
  humidity: number
}

interface Task {
  id: string
  title: string
  assignedTo: string
  dueDate: string
  completed: boolean
  category: 'food' | 'equipment' | 'logistics' | 'safety'
}

interface Message {
  id: string
  sender: string
  content: string
  timestamp: string
  avatar?: string
}

interface Meal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner' | 'snack'
  assignedTo: string
  ingredients: string[]
}

interface Member {
  id: string
  name: string
  avatar?: string
  rsvpStatus: 'pending' | 'accepted' | 'declined'
  role: 'organizer' | 'member'
}

