'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, Star, Plus, Search, Filter, ChevronRight } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  participants: number
  maxParticipants: number
  difficulty: 'Easy' | 'Moderate' | 'Hard'
  status: 'Planning' | 'Confirmed' | 'Completed'
  imageUrl: string
  description: string
  organizer: string
  tags: string[]
}

interface TripListProps {
  trips?: Trip[]
  onTripSelect?: (trip: Trip) => void
  onCreateTrip?: () => void
  showFilters?: boolean
  searchPlaceholder?: string
}

const DEFAULT_TRIPS: Trip[] = [
  {
    id: '1',
    name: 'Moab Desert Adventure',
    location: 'Moab, Utah',
    startDate: '2024-03-15',
    endDate: '2024-03-17',
    participants: 6,
    maxParticipants: 8,
    difficulty: 'Moderate',
    status: 'Planning',
    imageUrl: '/api/placeholder/400/200',
    description: 'Epic red rock trails and stunning desert landscapes',
    organizer: 'Sarah Johnson',
    tags: ['Desert', 'Rock Crawling', 'Camping']
  },
  {
    id: '2',
    name: 'Colorado Mountain Trail',
    location: 'Silverton, Colorado',
    startDate: '2024-04-20',
    endDate: '2024-04-22',
    participants: 4,
    maxParticipants: 6,
    difficulty: 'Hard',
    status: 'Confirmed',
    imageUrl: '/api/placeholder/400/200',
    description: 'High altitude technical trails with breathtaking views',
    organizer: 'Mike Chen',
    tags: ['Mountains', 'Technical', 'Alpine']
  },
  {
    id: '3',
    name: 'Forest Creek Run',
    location: 'Olympic National Forest, WA',
    startDate: '2024-05-10',
    endDate: '2024-05-12',
    participants: 8,
    maxParticipants: 8,
    difficulty: 'Easy',
    status: 'Confirmed',
    imageUrl: '/api/placeholder/400/200',
    description: 'Family-friendly trails through lush Pacific Northwest forests',
    organizer: 'Alex Rivera',
    tags: ['Forest', 'Family', 'Scenic']
  }
]

export function TripList({
  trips = DEFAULT_TRIPS,
  onTripSelect = (trip) => console.log('Selected trip:', trip.name),
  onCreateTrip = () => console.log('Create new trip'),
  showFilters = true,
  searchPlaceholder = 'Search trips...'
}: TripListProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedFilter, setSelectedFilter] = useState<'all' | 'planning' | 'confirmed' | 'completed'>('all')
  const [filteredTrips, setFilteredTrips] = useState(trips)

  useEffect(() => {
    let filtered = trips

    // Apply search filter
    if (searchQuery) {
      filtered = filtered.filter(trip =>
        trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        trip.location.toLowerCase().includes(searchQuery.toLowerCase()) ||
        trip.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()))
      )
    }

    // Apply status filter
    if (selectedFilter !== 'all') {
      filtered = filtered.filter(trip =>
        trip.status.toLowerCase() === selectedFilter
      )
    }

    setFilteredTrips(filtered)
  }, [searchQuery, selectedFilter, trips])

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-[rgb(34,139,34)] text-white'
      case 'Moderate': return 'bg-[rgb(245,158,11)] text-white'
      case 'Hard': return 'bg-[rgb(220,38,38)] text-white'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Planning': return 'bg-[rgb(245,158,11)]/10 text-[rgb(245,158,11)] border-[rgb(245,158,11)]/20'
      case 'Confirmed': return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'Completed': return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    })
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] z-10">
        <div className="px-4 py-4">
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Off-Road Trips</h1>
            <button
              onClick={onCreateTrip}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 shadow-md active:scale-95"
              aria-label="Create new trip"
            >
              <Plus size={20} />
              <span className="hidden sm:inline">New Trip</span>
            </button>
          </div>

          {/* Search */}
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[rgb(15,23,42)]/40" size={20} />
            <input
              type="text"
              placeholder={searchPlaceholder}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)]/40 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
              aria-label="Search trips"
            />
          </div>

          {/* Filters */}
          {showFilters && (
            <div className="flex gap-2 overflow-x-auto pb-2">
              {[
                { key: 'all', label: 'All' },
                { key: 'planning', label: 'Planning' },
                { key: 'confirmed', label: 'Confirmed' },
                { key: 'completed', label: 'Completed' }
              ].map((filter) => (
                <button
                  key={filter.key}
                  onClick={() => setSelectedFilter(filter.key as any)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 ${
                    selectedFilter === filter.key
                      ? 'bg-[rgb(34,139,34)] text-white shadow-md'
                      : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)] border border-[rgb(226,232,240)]'
                  }`}
                  aria-label={`Filter by ${filter.label}`}
                >
                  {filter.label}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Trip List */}
      <div className="px-4 py-4">
        {filteredTrips.length === 0 ? (
          <div className="text-center py-12">
            <MapPin className="mx-auto mb-4 text-[rgb(15,23,42)]/20" size={48} />
            <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No trips found</h3>
            <p className="text-[rgb(15,23,42)]/60 mb-6">
              {searchQuery ? 'Try adjusting your search terms' : 'Start planning your first off-road adventure'}
            </p>
            <button
              onClick={onCreateTrip}
              className="px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 shadow-md active:scale-95"
            >
              Create Your First Trip
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredTrips.map((trip) => (
              <div
                key={trip.id}
                onClick={() => onTripSelect(trip)}
                className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-4 hover:border-[rgb(34,139,34)]/30 hover:shadow-md transition-all duration-200 cursor-pointer active:scale-[0.98]"
                role="button"
                tabIndex={0}
                aria-label={`View details for ${trip.name}`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onTripSelect(trip)
                  }
                }}
              >
                <div className="flex items-start gap-4">
                  {/* Trip Image */}
                  <div className="w-20 h-20 bg-[rgb(241,245,249)] rounded-lg flex-shrink-0 overflow-hidden">
                    <div className="w-full h-full bg-gradient-to-br from-[rgb(34,139,34)]/20 to-[rgb(245,158,11)]/20 flex items-center justify-center">
                      <MapPin className="text-[rgb(34,139,34)]" size={24} />
                    </div>
                  </div>

                  {/* Trip Details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="font-semibold text-[rgb(15,23,42)] truncate pr-2">{trip.name}</h3>
                      <ChevronRight className="text-[rgb(15,23,42)]/40 flex-shrink-0" size={20} />
                    </div>

                    <div className="flex items-center gap-2 mb-2 text-sm text-[rgb(15,23,42)]/60">
                      <MapPin size={14} />
                      <span className="truncate">{trip.location}</span>
                    </div>

                    <div className="flex items-center gap-2 mb-3 text-sm text-[rgb(15,23,42)]/60">
                      <Calendar size={14} />
                      <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
                    </div>

                    {/* Status and Difficulty Badges */}
                    <div className="flex items-center gap-2 mb-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(trip.status)}`}>
                        {trip.status}
                      </span>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getDifficultyColor(trip.difficulty)}`}>
                        {trip.difficulty}
                      </span>
                    </div>

                    {/* Participants */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/60">
                        <Users size={14} />
                        <span>{trip.participants}/{trip.maxParticipants} participants</span>
                      </div>
                      <div className="text-xs text-[rgb(15,23,42)]/40">
                        by {trip.organizer}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

export default function TripListDemo() {
  return <TripList />
}

'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Camera, Plus, X } from 'lucide-react'

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  tags: string[]
}

interface TripFormProps {
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

const DIFFICULTY_OPTIONS = [
  { value: 'easy', label: 'Easy', color: 'bg-green-100 text-green-800' },
  { value: 'moderate', label: 'Moderate', color: 'bg-yellow-100 text-yellow-800' },
  { value: 'hard', label: 'Hard', color: 'bg-red-100 text-red-800' }
] as const

const POPULAR_TAGS = [
  'Camping', 'Rock Crawling', 'Scenic Views', 'Photography', 
  'Beginner Friendly', 'Advanced Trails', 'Water Crossing', 'Desert'
]

export function TripForm({
  onSubmit = (data) => console.log('Trip submitted:', data),
  initialData = {},
  isLoading = false
}: TripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    ...initialData
  })

  const [errors, setErrors] = useState<Record<string, string>>({})
  const [customTag, setCustomTag] = useState('')

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const updateField = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const addTag = (tag: string) => {
    if (tag && !formData.tags.includes(tag)) {
      updateField('tags', [...formData.tags, tag])
    }
  }

  const removeTag = (tagToRemove: string) => {
    updateField('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const addCustomTag = () => {
    if (customTag.trim()) {
      addTag(customTag.trim())
      setCustomTag('')
    }
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-2xl mx-auto px-4 py-6">
        <div className="bg-[#ffffff] rounded-xl border border-[#e2e8f0] shadow-md p-6">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-10 h-10 bg-[#228b22] rounded-lg flex items-center justify-center">
              <MapPin className="w-5 h-5 text-[#ffffff]" />
            </div>
            <div>
              <h1 className="text-xl font-semibold text-[#0f172a]">Plan New Trip</h1>
              <p className="text-sm text-gray-600">Create an off-roading adventure</p>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Trip Name */}
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-[#0f172a] mb-2">
                Trip Name *
              </label>
              <input
                id="name"
                type="text"
                value={formData.name}
                onChange={(e) => updateField('name', e.target.value)}
                placeholder="e.g., Moab Desert Adventure"
                className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-gray-400 focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                aria-describedby={errors.name ? "name-error" : undefined}
              />
              {errors.name && (
                <p id="name-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.name}
                </p>
              )}
            </div>

            {/* Location */}
            <div>
              <label htmlFor="location" className="block text-sm font-medium text-[#0f172a] mb-2">
                Location *
              </label>
              <div className="relative">
                <MapPin className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  id="location"
                  type="text"
                  value={formData.location}
                  onChange={(e) => updateField('location', e.target.value)}
                  placeholder="e.g., Moab, Utah"
                  className="w-full pl-10 pr-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-gray-400 focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                  aria-describedby={errors.location ? "location-error" : undefined}
                />
              </div>
              {errors.location && (
                <p id="location-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            {/* Dates */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="startDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Start Date *
                </label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => updateField('startDate', e.target.value)}
                    min={new Date().toISOString().split('T')[0]}
                    className="w-full pl-10 pr-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                    aria-describedby={errors.startDate ? "startDate-error" : undefined}
                  />
                </div>
                {errors.startDate && (
                  <p id="startDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                    {errors.startDate}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="endDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                  End Date *
                </label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => updateField('endDate', e.target.value)}
                    min={formData.startDate || new Date().toISOString().split('T')[0]}
                    className="w-full pl-10 pr-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                    aria-describedby={errors.endDate ? "endDate-error" : undefined}
                  />
                </div>
                {errors.endDate && (
                  <p id="endDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                    {errors.endDate}
                  </p>
                )}
              </div>
            </div>

            {/* Difficulty & Participants */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="difficulty" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Difficulty Level
                </label>
                <select
                  id="difficulty"
                  value={formData.difficulty}
                  onChange={(e) => updateField('difficulty', e.target.value as TripFormData['difficulty'])}
                  className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                >
                  {DIFFICULTY_OPTIONS.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="maxParticipants" className="block text-sm font-medium text-[#0f172a] mb-2">
                  Max Participants
                </label>
                <div className="relative">
                  <Users className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input
                    id="maxParticipants"
                    type="number"
                    min="1"
                    max="50"
                    value={formData.maxParticipants}
                    onChange={(e) => updateField('maxParticipants', parseInt(e.target.value) || 1)}
                    className="w-full pl-10 pr-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                    aria-describedby={errors.maxParticipants ? "maxParticipants-error" : undefined}
                  />
                </div>
                {errors.maxParticipants && (
                  <p id="maxParticipants-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                    {errors.maxParticipants}
                  </p>
                )}
              </div>
            </div>

            {/* Description */}
            <div>
              <label htmlFor="description" className="block text-sm font-medium text-[#0f172a] mb-2">
                Description
              </label>
              <textarea
                id="description"
                rows={4}
                value={formData.description}
                onChange={(e) => updateField('description', e.target.value)}
                placeholder="Describe the trip, what to expect, what to bring..."
                className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-gray-400 focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150 resize-none"
              />
            </div>

            {/* Tags */}
            <div>
              <label className="block text-sm font-medium text-[#0f172a] mb-2">
                Tags
              </label>

              {/* Selected Tags */}
              {formData.tags.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {formData.tags.map(tag => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-3 py-1 bg-[#228b22]/10 text-[#228b22] rounded-full text-sm border border-[#228b22]/20"
                    >
                      {tag}
                      <button
                        type="button"
                        onClick={() => removeTag(tag)}
                        className="w-4 h-4 rounded-full hover:bg-[#228b22]/20 flex items-center justify-center transition-colors duration-150"
                        aria-label={`Remove ${tag} tag`}
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}

              {/* Popular Tags */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-3">
                {POPULAR_TAGS.map(tag => (
                  <button
                    key={tag}
                    type="button"
                    onClick={() => addTag(tag)}
                    disabled={formData.tags.includes(tag)}
                    className={`px-3 py-2 text-sm rounded-lg border transition-all duration-150 ${
                      formData.tags.includes(tag)
                        ? 'bg-[#f1f5f9] text-gray-400 border-[#e2e8f0] cursor-not-allowed'
                        : 'bg-[#ffffff] text-[#0f172a] border-[#e2e8f0] hover:border-[#228b22] hover:bg-[#228b22]/5'
                    }`}
                  >
                    {tag}
                  </button>
                ))}
              </div>

              {/* Custom Tag Input */}
              <div className="flex gap-2">
                <input
                  type="text"
                  value={customTag}
                  onChange={(e) => setCustomTag(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addCustomTag())}
                  placeholder="Add custom tag..."
                  className="flex-1 px-4 py-2 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-gray-400 focus:border-[#228b22] focus:outline-none focus:ring-2 focus:ring-[#228b22]/20 transition-all duration-150"
                />
                <button
                  type="button"
                  onClick={addCustomTag}
                  disabled={!customTag.trim()}
                  className="px-4 py-2 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7a1e] transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center min-w-[44px]"
                  aria-label="Add custom tag"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Submit Button */}
            <div className="pt-4">
              <button
                type="submit"
                disabled={isLoading}
                className="w-full px-6 py-4 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7a1e] transition-all duration-150 font-medium shadow-md hover:shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 min-h-[56px]"
              >
                {isLoading ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Creating Trip...
                  </>
                ) : (
                  <>
                    <Camera className="w-5 h-5" />
                    Create Trip
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  )
}

