'use client'

import { useState, useEffect } from 'react'
import { Database, CheckCircle, AlertCircle, Loader2, RefreshCw } from 'lucide-react'

interface SupabaseConfig {
  url: string
  anonKey: string
  status: 'connecting' | 'connected' | 'error' | 'disconnected'
}

interface SupabaseInitProps {
  onConnectionChange?: (status: string) => void
  autoRetry?: boolean
  retryInterval?: number
}

export function SupabaseInit({
  onConnectionChange = () => {},
  autoRetry = true,
  retryInterval = 5000
}: SupabaseInitProps = {}) {
  const [config, setConfig] = useState<SupabaseConfig>({
    url: process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://your-project.supabase.co',
    anonKey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'your-anon-key',
    status: 'connecting'
  })
  const [retryCount, setRetryCount] = useState(0)
  const [lastError, setLastError] = useState<string | null>(null)

  const testConnection = async () => {
    try {
      setConfig(prev => ({ ...prev, status: 'connecting' }))
      setLastError(null)

      // Simulate Supabase connection test
      const response = await fetch(`${config.url}/rest/v1/`, {
        headers: {
          'apikey': config.anonKey,
          'Authorization': `Bearer ${config.anonKey}`
        }
      })

      if (response.ok) {
        setConfig(prev => ({ ...prev, status: 'connected' }))
        setRetryCount(0)
        onConnectionChange('connected')
      } else {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Connection failed'
      setLastError(errorMessage)
      setConfig(prev => ({ ...prev, status: 'error' }))
      setRetryCount(prev => prev + 1)
      onConnectionChange('error')

      if (autoRetry && retryCount < 3) {
        setTimeout(testConnection, retryInterval)
      }
    }
  }

  const manualRetry = () => {
    setRetryCount(0)
    testConnection()
  }

  useEffect(() => {
    testConnection()
  }, [])

  const getStatusIcon = () => {
    switch (config.status) {
      case 'connecting':
        return <Loader2 className="w-5 h-5 animate-spin text-[rgb(245,158,11)]" />
      case 'connected':
        return <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
      case 'error':
        return <AlertCircle className="w-5 h-5 text-[rgb(220,38,38)]" />
      default:
        return <Database className="w-5 h-5 text-[rgb(148,163,184)]" />
    }
  }

  const getStatusText = () => {
    switch (config.status) {
      case 'connecting':
        return 'Connecting to database...'
      case 'connected':
        return 'Database connected successfully'
      case 'error':
        return `Connection failed${retryCount > 0 ? ` (Attempt ${retryCount}/3)` : ''}`
      default:
        return 'Database disconnected'
    }
  }

  const getStatusColor = () => {
    switch (config.status) {
      case 'connecting':
        return 'text-[rgb(245,158,11)]'
      case 'connected':
        return 'text-[rgb(34,139,34)]'
      case 'error':
        return 'text-[rgb(220,38,38)]'
      default:
        return 'text-[rgb(148,163,184)]'
    }
  }

  return (
    <div className="w-full max-w-md mx-auto p-4">
      <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg p-6 shadow-md">
        <div className="flex items-center gap-3 mb-4">
          <Database className="w-6 h-6 text-[rgb(34,139,34)]" />
          <h2 className="text-lg font-semibold text-[rgb(15,23,42)] font-medium">
            Database Connection
          </h2>
        </div>

        <div className="space-y-4">
          {/* Status Indicator */}
          <div className="flex items-center gap-3 p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
            {getStatusIcon()}
            <div className="flex-1">
              <p className={`text-sm font-medium ${getStatusColor()}`}>
                {getStatusText()}
              </p>
              {lastError && (
                <p className="text-xs text-[rgb(148,163,184)] mt-1">
                  {lastError}
                </p>
              )}
            </div>
          </div>

          {/* Connection Details */}
          <div className="space-y-3">
            <div>
              <label className="block text-xs font-medium text-[rgb(71,85,105)] mb-1">
                Supabase URL
              </label>
              <div className="p-2 bg-[rgb(241,245,249)] rounded border border-[rgb(226,232,240)]">
                <p className="text-sm text-[rgb(15,23,42)] font-mono break-all">
                  {config.url}
                </p>
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-[rgb(71,85,105)] mb-1">
                API Key Status
              </label>
              <div className="p-2 bg-[rgb(241,245,249)] rounded border border-[rgb(226,232,240)]">
                <p className="text-sm text-[rgb(15,23,42)] font-mono">
                  {config.anonKey.length > 20 ? '••••••••••••••••••••' + config.anonKey.slice(-8) : 'Not configured'}
                </p>
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-2 pt-2">
            <button
              onClick={manualRetry}
              disabled={config.status === 'connecting'}
              className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(29,120,29)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-150 font-medium text-sm shadow-sm hover:shadow-md active:scale-95"
              aria-label="Retry database connection"
            >
              <RefreshCw className="w-4 h-4" />
              Retry Connection
            </button>
          </div>

          {/* Auto-retry indicator */}
          {autoRetry && config.status === 'error' && retryCount < 3 && (
            <div className="text-center">
              <p className="text-xs text-[rgb(148,163,184)]">
                Auto-retry in {Math.ceil(retryInterval / 1000)}s...
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Environment Check */}
      <div className="mt-4 p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
        <h3 className="text-sm font-medium text-[rgb(15,23,42)] mb-2">
          Environment Check
        </h3>
        <div className="space-y-1">
          <div className="flex items-center justify-between text-xs">
            <span className="text-[rgb(71,85,105)]">SUPABASE_URL</span>
            <span className={process.env.NEXT_PUBLIC_SUPABASE_URL ? 'text-[rgb(34,139,34)]' : 'text-[rgb(220,38,38)]'}>
              {process.env.NEXT_PUBLIC_SUPABASE_URL ? 'Set' : 'Missing'}
            </span>
          </div>
          <div className="flex items-center justify-between text-xs">
            <span className="text-[rgb(71,85,105)]">SUPABASE_ANON_KEY</span>
            <span className={process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ? 'text-[rgb(34,139,34)]' : 'text-[rgb(220,38,38)]'}>
              {process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ? 'Set' : 'Missing'}
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}

// Demo component for page.tsx
export default function SupabaseInitDemo() {
  const [connectionStatus, setConnectionStatus] = useState<string>('disconnected')

  const handleConnectionChange = (status: string) => {
