'use client'

import { useState, useEffect } from 'react'
import { 
  Map, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  Settings,
  Menu,
  X,
  Home,
  Plus
} from 'lucide-react'

interface AppLayoutProps {
  children?: React.ReactNode
  currentPage?: string
  onNavigate?: (page: string) => void
}

interface NavigationItem {
  id: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  href: string
  badge?: number
}

const navigationItems: NavigationItem[] = [
  { id: 'dashboard', label: 'Dashboard', icon: Home, href: '/dashboard' },
  { id: 'locations', label: 'Locations', icon: Map, href: '/locations' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'group', label: 'Group', icon: Users, href: '/group', badge: 3 },
  { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat', badge: 2 },
  { id: 'meals', label: 'Meals', icon: UtensilsCrossed, href: '/meals' }
]

export function AppLayout({
  children,
  currentPage = 'dashboard',
  onNavigate = (page: string) => console.log('Navigate to:', page)
}: AppLayoutProps = {}) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isOnline, setIsOnline] = useState(true)

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const handleNavigation = (item: NavigationItem) => {
    onNavigate(item.id)
    setIsMobileMenuOpen(false)
  }

  return (
    <div className="min-h-screen bg-white font-medium">
      {/* Offline Indicator */}
      {!isOnline && (
        <div className="bg-[rgb(220,38,38)] text-white px-4 py-2 text-center text-sm font-medium">
          You're offline. Some features may be limited.
        </div>
      )}

      {/* Header */}
      <header className="bg-white border-b border-[rgb(226,232,240)] sticky top-0 z-40">
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden p-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="Toggle navigation menu"
            >
              {isMobileMenuOpen ? (
                <X className="w-6 h-6 text-[rgb(15,23,42)]" />
              ) : (
                <Menu className="w-6 h-6 text-[rgb(15,23,42)]" />
              )}
            </button>
            <h1 className="text-xl font-bold text-[rgb(15,23,42)]">
              Off-Road Planner
            </h1>
          </div>

          <div className="flex items-center gap-2">
            <button
              className="p-2 rounded-lg bg-[rgb(34,139,34)] text-white hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 shadow-md"
              aria-label="Create new trip"
            >
              <Plus className="w-5 h-5" />
            </button>
            <button
              className="p-2 rounded-lg hover:bg-[rgb(241,245,249)] transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
              aria-label="Settings"
            >
              <Settings className="w-5 h-5 text-[rgb(15,23,42)]" />
            </button>
          </div>
        </div>
      </header>

      <div className="flex">
        {/* Desktop Sidebar */}
        <aside className="hidden lg:flex lg:flex-col lg:w-64 lg:fixed lg:inset-y-0 lg:pt-16 bg-white border-r border-[rgb(226,232,240)]">
          <nav className="flex-1 px-4 py-6 space-y-2">
            {navigationItems.map((item) => {
              const Icon = item.icon
              const isActive = currentPage === item.id

              return (
                <button
                  key={item.id}
                  onClick={() => handleNavigation(item)}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-left transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                    isActive
                      ? 'bg-[rgb(34,139,34)] text-white shadow-md'
                      : 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                  }`}
                  aria-current={isActive ? 'page' : undefined}
                >
                  <Icon className="w-5 h-5 flex-shrink-0" />
                  <span className="font-medium">{item.label}</span>
                  {item.badge && (
                    <span className="ml-auto bg-[rgb(245,158,11)] text-white text-xs font-bold px-2 py-1 rounded-full min-w-[1.25rem] h-5 flex items-center justify-center">
                      {item.badge}
                    </span>
                  )}
                </button>
              )
            })}
          </nav>
        </aside>

        {/* Mobile Menu Overlay */}
        {isMobileMenuOpen && (
          <div className="lg:hidden fixed inset-0 z-50 bg-black/50" onClick={() => setIsMobileMenuOpen(false)}>
            <div className="fixed inset-y-0 left-0 w-64 bg-white shadow-lg" onClick={(e) => e.stopPropagation()}>
              <div className="p-4 border-b border-[rgb(226,232,240)]">
                <h2 className="text-lg font-bold text-[rgb(15,23,42)]">Navigation</h2>
              </div>
              <nav className="p-4 space-y-2">
                {navigationItems.map((item) => {
                  const Icon = item.icon
                  const isActive = currentPage === item.id

                  return (
                    <button
                      key={item.id}
                      onClick={() => handleNavigation(item)}
                      className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg text-left transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 ${
                        isActive
                          ? 'bg-[rgb(34,139,34)] text-white shadow-md'
                          : 'text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                      }`}
                      aria-current={isActive ? 'page' : undefined}
                    >
                      <Icon className="w-6 h-6 flex-shrink-0" />
                      <span className="font-medium text-base">{item.label}</span>
                      {item.badge && (
                        <span className="ml-auto bg-[rgb(245,158,11)] text-white text-xs font-bold px-2 py-1 rounded-full min-w-[1.25rem] h-5 flex items-center justify-center">
                          {item.badge}
                        </span>
                      )}
                    </button>
                  )
                })}
              </nav>
            </div>
          </div>
        )}

        {/* Main Content */}
        <main className="flex-1 lg:ml-64">
          <div className="min-h-screen bg-[rgb(248,250,252)]">
            {children || (
              <div className="p-4 sm:p-6 lg:p-8">
                <div className="max-w-7xl mx-auto">
                  <div className="bg-white rounded-xl border border-[rgb(226,232,240)] p-8 shadow-md">
                    <h2 className="text-2xl font-bold text-[rgb(15,23,42)] mb-4">
                      Welcome to Off-Road Planner
                    </h2>
                    <p className="text-[rgb(15,23,42)]/70 mb-6">
                      Plan your next off-roading adventure with your group. Manage locations, 
                      assign tasks, check weather, and coordinate meals all in one place.
                    </p>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                      {navigationItems.slice(1, 4).map((item) => {
                        const Icon = item.icon
                        return (
                          <button
                            key={item.id}
                            onClick={() => handleNavigation(item)}
                            className="p-4 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)] transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 text-left group"
                          >
                            <Icon className="w-8 h-8 text-[rgb(34,139,34)] mb-2 group-hover:scale-110 transition-transform duration-150" />
                            <h3 className="font-semibold text-[rgb(15,23,42)] mb-1">{item.label}</h3>
                            <p className="text-sm text-[rgb(15,23,42)]/60">
                              {item.id === 'locations' && 'Find and save off-road locations'}
                              {item.id === 'calendar' && 'Schedule your trips and events'}
                              {item.id === 'group' && 'Manage your adventure crew'}
                            </p>
                          </button>
                        )
                      })}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Mobile Bottom Navigation */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-[rgb(226,232,240)] z-30">
        <div className="grid grid-cols-4 gap-1 p-2">
          {navigationItems.slice(0, 4).map((item) => {
            const Icon = item.icon
            const isActive = currentPage === item.id

            return (
              <button
                key={item.id}
                onClick={() => handleNavigation(item)}
                className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 min-h-[44px] ${
                  isActive
                    ? 'text-[rgb(34,139,34)]'
                    : 'text-[rgb(15,23,42)]/60 hover:text-[rgb(15,23,42)]'
                }`}
                aria-current={isActive ? 'page' : undefined}
                aria-label={item.label}
              >
                <div className="relative">
                  <Icon className="w-5 h-5" />
                  {item.badge && (
                    <span className="absolute -top-1 -right-1 bg-[rgb(245,158,11)] text-white text-xs font-bold px-1.5 py-0.5 rounded-full min-w-[1rem] h-4 flex items-center justify-center text-[10px]">
                      {item.badge}
                    </span>
                  )}
                </div>
                <span className="text-xs font-medium">{item.label}</span>
              </button>
            )
          })}
        </div>
      </nav>

      {/* Bottom padding for mobile navigation */}
      <div className="lg:hidden h-20" />
    </div>
  )
}

// Demo component showing the layout with sample content
export default function AppLayoutDemo() {
  const [currentPage, setCurrentPage] = useState('dashboard')

  return (
    <AppLayout 
      currentPage={currentPage}
      onNavigate={setCurrentPage}
    />
  )
}

