'use client'

import { useState, useEffect } from 'react'
import { Database, Table, Key, FileText, Users, Calendar, MapPin, MessageSquare, Utensils, CheckSquare, Cloud } from 'lucide-react'

interface TableSchema {
  name: string
  description: string
  columns: Column[]
  relationships: string[]
}

interface Column {
  name: string
  type: string
  constraints: string[]
  description: string
}

interface DBSchemaProps {
  showDetails?: boolean
  onTableSelect?: (tableName: string) => void
}

export function DBSchema({
  showDetails = true,
  onTableSelect = () => console.log('Table selected')
}: DBSchemaProps = {}) {
  const [selectedTable, setSelectedTable] = useState<string | null>(null)
  const [expandedTables, setExpandedTables] = useState<Set<string>>(new Set())

  const handleTableClick = (tableName: string) => {
    setSelectedTable(selectedTable === tableName ? null : tableName)
    onTableSelect(tableName)
  }

  const toggleTableExpansion = (tableName: string) => {
    const newExpanded = new Set(expandedTables)
    if (newExpanded.has(tableName)) {
      newExpanded.delete(tableName)
    } else {
      newExpanded.add(tableName)
    }
    setExpandedTables(newExpanded)
  }

  const getTableIcon = (tableName: string) => {
    const iconMap: Record<string, any> = {
      users: Users,
      trips: MapPin,
      locations: MapPin,
      tasks: CheckSquare,
      messages: MessageSquare,
      meals: Utensils,
      invitations: Calendar,
      weather: Cloud,
      rsvps: CheckSquare
    }
    const IconComponent = iconMap[tableName] || Table
    return <IconComponent className="w-5 h-5" />
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-3 bg-[#228b22] rounded-xl">
              <Database className="w-6 h-6 text-[#ffffff]" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[#0f172a]">Database Schema</h1>
              <p className="text-[#64748b] text-sm">Off-roading trip planning database structure</p>
            </div>
          </div>
        </div>

        {/* Schema Overview */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
          <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-xl p-6">
            <div className="flex items-center gap-3 mb-3">
              <Table className="w-5 h-5 text-[#228b22]" />
              <h3 className="font-semibold text-[#0f172a]">Tables</h3>
            </div>
            <p className="text-2xl font-bold text-[#0f172a]">{SCHEMA_TABLES.length}</p>
            <p className="text-sm text-[#64748b]">Core entities</p>
          </div>

          <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-xl p-6">
            <div className="flex items-center gap-3 mb-3">
              <Key className="w-5 h-5 text-[#f59e0b]" />
              <h3 className="font-semibold text-[#0f172a]">Relationships</h3>
            </div>
            <p className="text-2xl font-bold text-[#0f172a]">12</p>
            <p className="text-sm text-[#64748b]">Foreign keys</p>
          </div>

          <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-xl p-6">
            <div className="flex items-center gap-3 mb-3">
              <FileText className="w-5 h-5 text-[#dc2626]" />
              <h3 className="font-semibold text-[#0f172a]">Indexes</h3>
            </div>
            <p className="text-2xl font-bold text-[#0f172a]">18</p>
            <p className="text-sm text-[#64748b]">Performance optimized</p>
          </div>
        </div>

        {/* Tables Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {SCHEMA_TABLES.map((table) => (
            <div
              key={table.name}
              className={`bg-[#ffffff] border rounded-xl p-6 transition-all duration-200 cursor-pointer hover:shadow-lg ${
                selectedTable === table.name
                  ? 'border-[#228b22] shadow-lg'
                  : 'border-[#e2e8f0] hover:border-[#228b22]/50'
              }`}
              onClick={() => handleTableClick(table.name)}
            >
              {/* Table Header */}
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-[#f1f5f9] rounded-lg">
                    {getTableIcon(table.name)}
                  </div>
                  <div>
                    <h3 className="font-semibold text-[#0f172a] capitalize">{table.name}</h3>
                    <p className="text-xs text-[#64748b]">{table.columns.length} columns</p>
                  </div>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    toggleTableExpansion(table.name)
                  }}
                  className="p-1 hover:bg-[#f1f5f9] rounded transition-colors duration-150"
                  aria-label={`${expandedTables.has(table.name) ? 'Collapse' : 'Expand'} ${table.name} table details`}
                >
                  <FileText className="w-4 h-4 text-[#64748b]" />
                </button>
              </div>

              {/* Table Description */}
              <p className="text-sm text-[#64748b] mb-4">{table.description}</p>

              {/* Column Count Badge */}
              <div className="flex items-center gap-2 mb-4">
                <span className="px-2 py-1 bg-[#228b22]/10 text-[#228b22] rounded-full text-xs font-medium">
                  {table.columns.length} columns
                </span>
                {table.relationships.length > 0 && (
                  <span className="px-2 py-1 bg-[#f59e0b]/10 text-[#f59e0b] rounded-full text-xs font-medium">
                    {table.relationships.length} relations
                  </span>
                )}
              </div>

              {/* Expanded Details */}
              {expandedTables.has(table.name) && showDetails && (
                <div className="border-t border-[#e2e8f0] pt-4 mt-4">
                  <h4 className="font-medium text-[#0f172a] mb-3">Columns</h4>
                  <div className="space-y-2">
                    {table.columns.slice(0, 5).map((column) => (
                      <div key={column.name} className="flex items-center justify-between text-sm">
                        <span className="text-[#0f172a] font-medium">{column.name}</span>
                        <span className="text-[#64748b] text-xs">{column.type}</span>
                      </div>
                    ))}
                    {table.columns.length > 5 && (
                      <p className="text-xs text-[#64748b] italic">
                        +{table.columns.length - 5} more columns
                      </p>
                    )}
                  </div>

                  {table.relationships.length > 0 && (
                    <div className="mt-4">
                      <h4 className="font-medium text-[#0f172a] mb-2">Relationships</h4>
                      <div className="space-y-1">
                        {table.relationships.map((rel, index) => (
                          <p key={index} className="text-xs text-[#64748b]">{rel}</p>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Selected Table Details */}
        {selectedTable && (
          <div className="mt-8 bg-[#ffffff] border border-[#e2e8f0] rounded-xl p-6">
            <h3 className="text-lg font-semibold text-[#0f172a] mb-4 capitalize">
              {selectedTable} Table Details
            </h3>
            {(() => {
              const table = SCHEMA_TABLES.find(t => t.name === selectedTable)
              if (!table) return null

              return (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div>
                    <h4 className="font-medium text-[#0f172a] mb-3">Columns</h4>
                    <div className="space-y-3">
                      {table.columns.map((column) => (
                        <div key={column.name} className="border border-[#e2e8f0] rounded-lg p-3">
                          <div className="flex items-center justify-between mb-2">
                            <span className="font-medium text-[#0f172a]">{column.name}</span>
                            <span className="px-2 py-1 bg-[#f1f5f9] text-[#64748b] rounded text-xs">
                              {column.type}
                            </span>
                          </div>
                          <p className="text-sm text-[#64748b] mb-2">{column.description}</p>
                          {column.constraints.length > 0 && (
                            <div className="flex flex-wrap gap-1">
                              {column.constraints.map((constraint, index) => (
                                <span
                                  key={index}
                                  className="px-2 py-1 bg-[#228b22]/10 text-[#228b22] rounded-full text-xs"
                                >
                                  {constraint}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div>
                    <h4 className="font-medium text-[#0f172a] mb-3">Relationships</h4>
                    <div className="space-y-2">
                      {table.relationships.map((rel, index) => (
                        <div key={index} className="border border-[#e2e8f0] rounded-lg p-3">
                          <p className="text-sm text-[#0f172a]">{rel}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )
            })()}
          </div>
        )}
      </div>
    </div>
  )
}

// Mock schema data
const SCHEMA_TABLES: TableSchema[] = [
  {
    name: 'users',
    description: 'User accounts and profiles for trip participants',
    columns: [
      { name: 'id', type: 'UUID', constraints: ['PRIMARY KEY'], description: 'Unique user identifier' },
      { name: 'email', type: 'VARCHAR(255)', constraints: ['UNIQUE', 'NOT NULL'], description: 'User email address' },
      { name: 'name', type: 'VARCHAR(100)', constraints: ['NOT NULL'], description: 'Full name' },
      { name: 'phone', type: 'VARCHAR(20)', constraints: [], description: 'Phone number for notifications' },
      { name: 'avatar_url', type: 'TEXT', constraints: [], description: 'Profile picture URL' },
      { name: 'created_at', type: 'TIMESTAMP', constraints: ['DEFAULT NOW()'], description: 'Account creation date' }
    ],
    relationships: [
      'One-to-many with trips (trip_organizer_id)',
      'Many-to-many with trips through trip_participants',
      'One-to-many with messages'
    ]
  },
  {
    name: 'trips',
