'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Users, MapPin, Calendar } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignUp?: (email: string, password: string, name: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignUp = (email, password, name) => console.log('Sign up:', { email, password, name }),
  onForgotPassword = (email) => console.log('Forgot password:', { email })
}: LoginPageProps = {}) {
  const [isSignUp, setIsSignUp] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [name, setName] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setIsLoading(true)

    try {
      if (isSignUp) {
        if (!name.trim()) {
          setError('Name is required')
          return
        }
        await onSignUp(email, password, name)
      } else {
        await onLogin(email, password)
      }
    } catch (err) {
      setError('Something went wrong. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (!email) {
      setError('Please enter your email address first')
      return
    }
    onForgotPassword(email)
    setError('')
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-[rgb(226,232,240)] px-4 py-6">
        <div className="flex items-center justify-center gap-3">
          <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-xl flex items-center justify-center">
            <Mountain className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">TrailPlan</h1>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col justify-center px-4 py-8">
        <div className="w-full max-w-md mx-auto">
          {/* Welcome Section */}
          <div className="text-center mb-8">
            <h2 className="text-3xl font-bold text-[rgb(15,23,42)] mb-2">
              {isSignUp ? 'Join the Adventure' : 'Welcome Back'}
            </h2>
            <p className="text-slate-600 text-base">
              {isSignUp 
                ? 'Create your account to start planning epic off-road adventures'
                : 'Sign in to continue planning your next off-road trip'
              }
            </p>
          </div>

          {/* Features Preview */}
          <div className="grid grid-cols-3 gap-4 mb-8">
            <div className="text-center">
              <div className="w-12 h-12 bg-[rgb(34,139,34)]/10 rounded-xl flex items-center justify-center mx-auto mb-2">
                <MapPin className="w-6 h-6 text-[rgb(34,139,34)]" />
              </div>
              <p className="text-xs text-slate-600 font-medium">Save Locations</p>
            </div>
            <div className="text-center">
              <div className="w-12 h-12 bg-[rgb(245,158,11)]/10 rounded-xl flex items-center justify-center mx-auto mb-2">
                <Users className="w-6 h-6 text-[rgb(245,158,11)]" />
              </div>
              <p className="text-xs text-slate-600 font-medium">Group Tasks</p>
            </div>
            <div className="text-center">
              <div className="w-12 h-12 bg-[rgb(34,139,34)]/10 rounded-xl flex items-center justify-center mx-auto mb-2">
                <Calendar className="w-6 h-6 text-[rgb(34,139,34)]" />
              </div>
              <p className="text-xs text-slate-600 font-medium">Trip Planning</p>
            </div>
          </div>

          {/* Login Form */}
          <div className="bg-white rounded-2xl p-6 shadow-lg border border-[rgb(226,232,240)]">
            <form onSubmit={handleSubmit} className="space-y-4">
              {isSignUp && (
                <div>
                  <label htmlFor="name" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                    Full Name
                  </label>
                  <input
                    id="name"
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full px-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-xl text-[rgb(15,23,42)] placeholder-slate-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200"
                    placeholder="Enter your full name"
                    required
                  />
                </div>
              )}

              <div>
                <label htmlFor="email" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Email Address
                </label>
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-xl text-[rgb(15,23,42)] placeholder-slate-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200"
                  placeholder="Enter your email"
                  required
                />
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Password
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full px-4 py-3 pr-12 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-xl text-[rgb(15,23,42)] placeholder-slate-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200"
                    placeholder="Enter your password"
                    required
                    minLength={6}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-slate-600 transition-colors duration-200"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? (
                      <EyeOff className="w-5 h-5" />
                    ) : (
                      <Eye className="w-5 h-5" />
                    )}
                  </button>
                </div>
              </div>

              {error && (
                <div className="p-3 bg-[rgb(220,38,38)]/10 border border-[rgb(220,38,38)]/20 rounded-lg">
                  <p className="text-sm text-[rgb(220,38,38)] font-medium">{error}</p>
                </div>
              )}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 bg-[rgb(34,139,34)] text-white rounded-xl font-semibold text-base hover:bg-[rgb(34,139,34)]/90 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/50 focus:ring-offset-2 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98] min-h-[48px] flex items-center justify-center"
              >
                {isLoading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  isSignUp ? 'Create Account' : 'Sign In'
                )}
              </button>
            </form>

            {!isSignUp && (
              <button
                onClick={handleForgotPassword}
                className="w-full mt-4 py-2 text-sm text-[rgb(34,139,34)] hover:text-[rgb(34,139,34)]/80 font-medium transition-colors duration-200"
              >
                Forgot your password?
              </button>
            )}
          </div>

          {/* Toggle Sign Up/Sign In */}
          <div className="text-center mt-6">
            <p className="text-slate-600 text-sm">
              {isSignUp ? 'Already have an account?' : "Don't have an account?"}
              <button
                onClick={() => {
                  setIsSignUp(!isSignUp)
                  setError('')
                  setEmail('')
                  setPassword('')
                  setName('')
                }}
                className="ml-2 text-[rgb(34,139,34)] hover:text-[rgb(34,139,34)]/80 font-semibold transition-colors duration-200"
              >
                {isSignUp ? 'Sign In' : 'Sign Up'}
              </button>
            </p>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="px-4 py-6 text-center">
        <p className="text-xs text-slate-500">
          By continuing, you agree to our Terms of Service and Privacy Policy
        </p>
      </div>
    </div>
  )
}

export default function LoginPageDemo() {
  return <LoginPage />
}

'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mail, Lock, User, Mountain, ArrowRight, CheckCircle } from 'lucide-react'

interface SignupFormData {
  firstName: string
  lastName: string
  email: string
  password: string
  confirmPassword: string
}

interface SignupPageProps {
  onSignup?: (data: SignupFormData) => Promise<void>
  onLoginRedirect?: () => void
}

export function SignupPage({
  onSignup = async (data) => {
    console.log('Signup attempt:', data)
    await new Promise(resolve => setTimeout(resolve, 1000))
  },
  onLoginRedirect = () => console.log('Redirect to login')
}: SignupPageProps = {}) {
  const [formData, setFormData] = useState<SignupFormData>({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: ''
  })
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [errors, setErrors] = useState<Partial<SignupFormData>>({})
  const [isSuccess, setIsSuccess] = useState(false)

  const validateForm = (): boolean => {
    const newErrors: Partial<SignupFormData> = {}

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'First name is required'
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Last name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters'
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your password'
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsLoading(true)
    try {
      await onSignup(formData)
      setIsSuccess(true)
    } catch (error) {
      console.error('Signup failed:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleInputChange = (field: keyof SignupFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }))
    }
  }

  if (isSuccess) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center mx-auto">
              <CheckCircle className="w-8 h-8 text-white" />
            </div>
            <div className="space-y-2">
              <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">
                Welcome to TrailPlan!
              </h1>
              <p className="text-[rgb(100,116,139)]">
                Your account has been created successfully. Check your email to verify your account.
              </p>
            </div>
            <button
              onClick={onLoginRedirect}
              className="w-full bg-[rgb(34,139,34)] text-white py-3 px-4 rounded-lg font-medium hover:bg-[rgb(29,120,29)] transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2"
            >
              Continue to Login
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-center py-6 px-4 border-b border-[rgb(226,232,240)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-lg flex items-center justify-center">
            <Mountain className="w-5 h-5 text-white" />
          </div>
          <span className="text-xl font-bold text-[rgb(15,23,42)]">TrailPlan</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-md space-y-6">
          {/* Title */}
          <div className="text-center space-y-2">
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">
              Join the Adventure
            </h1>
            <p className="text-[rgb(100,116,139)]">
              Create your account to start planning epic off-road trips
            </p>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Name Fields */}
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label htmlFor="firstName" className="block text-sm font-medium text-[rgb(15,23,42)]">
                  First Name
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(100,116,139)]" />
                  <input
                    id="firstName"
                    type="text"
                    value={formData.firstName}
                    onChange={(e) => handleInputChange('firstName', e.target.value)}
                    className={`w-full pl-10 pr-4 py-3 border rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(148,163,184)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors duration-200 ${
                      errors.firstName ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                    }`}
                    placeholder="John"
                    aria-describedby={errors.firstName ? 'firstName-error' : undefined}
                  />
                </div>
                {errors.firstName && (
                  <p id="firstName-error" className="text-xs text-[rgb(220,38,38)]" role="alert">
                    {errors.firstName}
                  </p>
                )}
              </div>

              <div className="space-y-1">
                <label htmlFor="lastName" className="block text-sm font-medium text-[rgb(15,23,42)]">
                  Last Name
                </label>
                <input
                  id="lastName"
                  type="text"
                  value={formData.lastName}
                  onChange={(e) => handleInputChange('lastName', e.target.value)}
                  className={`w-full px-4 py-3 border rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(148,163,184)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors duration-200 ${
                    errors.lastName ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                  }`}
                  placeholder="Doe"
                  aria-describedby={errors.lastName ? 'lastName-error' : undefined}
                />
                {errors.lastName && (
                  <p id="lastName-error" className="text-xs text-[rgb(220,38,38)]" role="alert">
                    {errors.lastName}
                  </p>
                )}
              </div>
            </div>

            {/* Email */}
            <div className="space-y-1">
              <label htmlFor="email" className="block text-sm font-medium text-[rgb(15,23,42)]">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(100,116,139)]" />
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 border rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(148,163,184)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-offset-2 transition-colors duration-200 ${
                    errors.email ? 'border-[rgb(220,38,38)]' : 'border-[rgb(226,232,240)]'
                  }`}
                  placeholder="john@example.com"
                  aria-describedby={errors.email ? 'email-error' : undefined}
                />
              </div>
              {errors.email && (
                <p id="email-error" className="text-xs text-[rgb(220,38,38)]" role="alert">
                  {errors.email}
                </p>
              )}
