'use client'

import { useState, useEffect } from 'react'
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs'
import { User, Session, AuthError } from '@supabase/supabase-js'
import { Eye, EyeOff, Mail, Lock, User as UserIcon, AlertCircle, CheckCircle } from 'lucide-react'

interface AuthState {
  user: User | null
  session: Session | null
  loading: boolean
  error: string | null
}

interface AuthFormData {
  email: string
  password: string
  confirmPassword?: string
  fullName?: string
}

interface AuthAPIProps {
  onAuthStateChange?: (user: User | null) => void
  redirectTo?: string
  mode?: 'signin' | 'signup' | 'reset'
}

export function AuthAPI({
  onAuthStateChange = () => {},
  redirectTo = '/dashboard',
  mode: initialMode = 'signin'
}: AuthAPIProps = {}) {
  const [authState, setAuthState] = useState<AuthState>({
    user: null,
    session: null,
    loading: true,
    error: null
  })

  const [mode, setMode] = useState<'signin' | 'signup' | 'reset'>(initialMode)
  const [formData, setFormData] = useState<AuthFormData>({
    email: '',
    password: '',
    confirmPassword: '',
    fullName: ''
  })
  const [showPassword, setShowPassword] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [successMessage, setSuccessMessage] = useState('')

  const supabase = createClientComponentClient()

  useEffect(() => {
    // Get initial session
    const getSession = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession()
        if (error) throw error

        setAuthState({
          user: session?.user || null,
          session,
          loading: false,
          error: null
        })

        if (session?.user) {
          onAuthStateChange(session.user)
        }
      } catch (error) {
        setAuthState(prev => ({
          ...prev,
          loading: false,
          error: error instanceof Error ? error.message : 'Failed to get session'
        }))
      }
    }

    getSession()

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        setAuthState({
          user: session?.user || null,
          session,
          loading: false,
          error: null
        })

        onAuthStateChange(session?.user || null)

        if (event === 'SIGNED_IN' && session?.user) {
          window.location.href = redirectTo
        }
      }
    )

    return () => subscription.unsubscribe()
  }, [supabase, onAuthStateChange, redirectTo])

  const validateForm = (): string | null => {
    if (!formData.email) return 'Email is required'
    if (!formData.email.includes('@')) return 'Please enter a valid email'

    if (mode !== 'reset') {
      if (!formData.password) return 'Password is required'
      if (formData.password.length < 6) return 'Password must be at least 6 characters'
    }

    if (mode === 'signup') {
      if (!formData.fullName) return 'Full name is required'
      if (formData.password !== formData.confirmPassword) return 'Passwords do not match'
    }

    return null
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const validationError = validateForm()
    if (validationError) {
      setAuthState(prev => ({ ...prev, error: validationError }))
      return
    }

    setIsSubmitting(true)
    setAuthState(prev => ({ ...prev, error: null }))
    setSuccessMessage('')

    try {
      if (mode === 'signin') {
        const { error } = await supabase.auth.signInWithPassword({
          email: formData.email,
          password: formData.password
        })
        if (error) throw error

      } else if (mode === 'signup') {
        const { error } = await supabase.auth.signUp({
          email: formData.email,
          password: formData.password,
          options: {
            data: {
              full_name: formData.fullName
            }
          }
        })
        if (error) throw error

        setSuccessMessage('Check your email for verification link!')

      } else if (mode === 'reset') {
        const { error } = await supabase.auth.resetPasswordForEmail(formData.email, {
          redirectTo: `${window.location.origin}/auth/reset-password`
        })
        if (error) throw error

        setSuccessMessage('Password reset email sent!')
      }

    } catch (error) {
      const authError = error as AuthError
      setAuthState(prev => ({
        ...prev,
        error: authError.message || 'Authentication failed'
      }))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleSignOut = async () => {
    try {
      const { error } = await supabase.auth.signOut()
      if (error) throw error
    } catch (error) {
      setAuthState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Sign out failed'
      }))
    }
  }

  const handleInputChange = (field: keyof AuthFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (authState.error) {
      setAuthState(prev => ({ ...prev, error: null }))
    }
  }

  if (authState.loading) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-[rgb(248,250,252)] rounded-xl p-8 space-y-6 animate-pulse">
            <div className="h-8 bg-[rgb(226,232,240)] rounded-lg"></div>
            <div className="space-y-4">
              <div className="h-12 bg-[rgb(226,232,240)] rounded-lg"></div>
              <div className="h-12 bg-[rgb(226,232,240)] rounded-lg"></div>
              <div className="h-12 bg-[rgb(226,232,240)] rounded-lg"></div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  if (authState.user) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-[rgb(248,250,252)] rounded-xl p-8 shadow-md">
          <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center mx-auto">
              <UserIcon className="w-8 h-8 text-[rgb(255,255,255)]" />
            </div>

            <div>
              <h2 className="text-xl font-semibold text-[rgb(15,23,42)] mb-2">
                Welcome back!
              </h2>
              <p className="text-[rgb(100,116,139)]">
                {authState.user.email}
              </p>
            </div>

            <button
              onClick={handleSignOut}
              className="w-full px-4 py-3 bg-[rgb(220,38,38)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(185,28,28)] transition-colors duration-150 font-medium shadow-sm active:scale-95"
              aria-label="Sign out of your account"
            >
              Sign Out
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="bg-[rgb(248,250,252)] rounded-xl p-8 shadow-md border border-[rgb(226,232,240)]">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center mx-auto mb-4">
              <UserIcon className="w-8 h-8 text-[rgb(255,255,255)]" />
            </div>
            <h1 className="text-2xl font-semibold text-[rgb(15,23,42)] mb-2">
              {mode === 'signin' && 'Welcome Back'}
              {mode === 'signup' && 'Join the Adventure'}
              {mode === 'reset' && 'Reset Password'}
            </h1>
            <p className="text-[rgb(100,116,139)]">
              {mode === 'signin' && 'Sign in to plan your next off-road adventure'}
              {mode === 'signup' && 'Create your account to start exploring'}
              {mode === 'reset' && 'Enter your email to reset your password'}
            </p>
          </div>

          {/* Success Message */}
          {successMessage && (
            <div className="mb-6 p-4 bg-[rgb(34,139,34)]/10 border border-[rgb(34,139,34)]/20 rounded-lg flex items-center gap-3">
              <CheckCircle className="w-5 h-5 text-[rgb(34,139,34)]" />
              <p className="text-[rgb(34,139,34)] text-sm font-medium">{successMessage}</p>
            </div>
          )}

          {/* Error Message */}
          {authState.error && (
            <div className="mb-6 p-4 bg-[rgb(220,38,38)]/10 border border-[rgb(220,38,38)]/20 rounded-lg flex items-center gap-3">
              <AlertCircle className="w-5 h-5 text-[rgb(220,38,38)]" />
              <p className="text-[rgb(220,38,38)] text-sm font-medium">{authState.error}</p>
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Full Name (Signup only) */}
            {mode === 'signup' && (
              <div>
                <label htmlFor="fullName" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Full Name
                </label>
                <div className="relative">
                  <UserIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                  <input
                    id="fullName"
                    type="text"
                    value={formData.fullName || ''}
                    onChange={(e) => handleInputChange('fullName', e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                    placeholder="Enter your full name"
                    required
                  />
                </div>
              </div>
            )}

            {/* Email */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                  placeholder="Enter your email"
                  required
                />
              </div>
            </div>

            {/* Password (not for reset) */}
            {mode !== 'reset' && (
              <div>
                <label htmlFor="password" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={formData.password}
                    onChange={(e) => handleInputChange('password', e.target.value)}
                    className="w-full pl-10 pr-12 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                    placeholder="Enter your password"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] transition-colors duration-150"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
              </div>
            )}

            {/* Confirm Password (Signup only) */}
            {mode === 'signup' && (
              <div>
                <label htmlFor="confirmPassword" className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Confirm Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[rgb(100,116,139)]" />
                  <input
                    id="confirmPassword"
                    type={showPassword ? 'text' : 'password'}
                    value={formData.confirmPassword || ''}
                    onChange={(e) => handleInputChange('confirmPassword', e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                    placeholder="Confirm your password"
                    required
                  />
                </div>
              </div>
            )}

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full px-4 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-lg hover:bg-[rgb(22,101,22)] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 font-medium shadow-sm active:scale-95 min-h-[48px] flex items-center justify-center"
              aria-label={`${mode === 'signin' ? 'Sign in' : mode === 'signup' ? 'Create account' : 'Send reset email'}`}
            >
              {isSubmitting ? (
                <div className="w-5 h-5 border-2 border-[rgb(255,255,255)]/30 border-t-[rgb(255,255,255)] rounded-full animate-spin"></div>
              ) : (
                <>
                  {mode === 'signin' && 'Sign In'}
                  {mode === 'signup' && 'Create Account'}
                  {mode === 'reset' && 'Send Reset Email'}
                </>
              )}
            </button>
          </form>

          {/* Mode Switching */}
          <div className="mt-6 text-center space-y-3">
            {mode === 'signin' && (
              <>
                <button
                  onClick={() => setMode('reset')}
                  className="text-[rgb(34,139,34)] hover:text-[rgb(22,101,22)] text-sm font-medium transition-colors duration-150"
                >
                  Forgot your password?
                </button>
                <p className="text-[rgb(100,116,139)] text-sm">
                  Don't have an account?{' '}
                  <button
                    onClick={() => setMode('signup')}
                    className="text-[rgb(34,139,34)] hover:text-[rgb(22,101,22)] font-medium transition-colors duration-150"
                  >
                    Sign up
                  </button>
                </p>
              </>
            )}

            {mode === 'signup' && (
              <p className="text-[rgb(100,116,139)] text-sm">
                Already have an account?{' '}
                <button
                  onClick={() => setMode('signin')}
                  className="text-[rgb(34,139,34)] hover:text-[rgb(22,101,22)] font-medium transition-colors duration-150"
                >
                  Sign in
                </button>
              </p>
            )}

            {mode === 'reset' && (
              <p className="text-[rgb(100,116,139)] text-sm">
                Remember your password?{' '}
                <button
                  onClick={() => setMode('signin')}
                  className="text-[rgb(34,139,34)] hover:text-[rgb(22,101,22)] font-medium transition-colors duration-150"
                >
                  Sign in
                </button>
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

