'use client'

import { useState, useEffect } from 'react'
import { Mail, Send, CheckCircle, AlertCircle, Clock, Users } from 'lucide-react'

interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
  sentAt?: Date
}

interface EmailCampaign {
  id: string
  templateId: string
  recipients: EmailRecipient[]
  scheduledFor?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'completed' | 'failed'
  createdAt: Date
}

interface ResendServiceProps {
  tripId?: string
  onEmailSent?: (campaignId: string) => void
  onError?: (error: string) => void
}

export function ResendService({
  tripId = 'trip-1',
  onEmailSent = () => console.log('Email sent'),
  onError = () => console.log('Error occurred')
}: ResendServiceProps = {}) {
  const [templates, setTemplates] = useState<EmailTemplate[]>(DEFAULT_TEMPLATES)
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>(DEFAULT_CAMPAIGNS)
  const [selectedTemplate, setSelectedTemplate] = useState<string>('')
  const [recipients, setRecipients] = useState<EmailRecipient[]>(DEFAULT_RECIPIENTS)
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'send' | 'templates' | 'history'>('send')

  const handleSendEmail = async () => {
    if (!selectedTemplate) {
      onError('Please select an email template')
      return
    }

    setIsLoading(true)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000))

      const newCampaign: EmailCampaign = {
        id: `campaign-${Date.now()}`,
        templateId: selectedTemplate,
        recipients: recipients.map(r => ({ ...r, status: 'sent', sentAt: new Date() })),
        status: 'completed',
        createdAt: new Date()
      }

      setCampaigns(prev => [newCampaign, ...prev])
      onEmailSent(newCampaign.id)
    } catch (error) {
      onError('Failed to send emails')
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusIcon = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-[rgb(34,139,34)]" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-[rgb(220,38,38)]" />
      default:
        return <Clock className="w-4 h-4 text-[rgb(245,158,11)]" />
    }
  }

  const getStatusColor = (status: EmailCampaign['status']) => {
    switch (status) {
      case 'completed':
        return 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20'
      case 'failed':
        return 'bg-[rgb(220,38,38)]/10 text-[rgb(220,38,38)] border-[rgb(220,38,38)]/20'
      case 'sending':
        return 'bg-[rgb(245,158,11)]/10 text-[rgb(245,158,11)] border-[rgb(245,158,11)]/20'
      default:
        return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 sm:p-6">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-[rgb(34,139,34)]/10 rounded-lg">
              <Mail className="w-6 h-6 text-[rgb(34,139,34)]" />
            </div>
            <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Email Service</h1>
          </div>
          <p className="text-[rgb(15,23,42)]/60">Send trip invitations and updates to your group</p>
        </div>

        {/* Navigation Tabs */}
        <div className="flex bg-[rgb(248,250,252)] rounded-lg p-1 mb-6">
          {[
            { id: 'send', label: 'Send Email', icon: Send },
            { id: 'templates', label: 'Templates', icon: Mail },
            { id: 'history', label: 'History', icon: Clock }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-md text-sm font-medium transition-all duration-200 ${
                activeTab === id
                  ? 'bg-[rgb(255,255,255)] text-[rgb(34,139,34)] shadow-sm'
                  : 'text-[rgb(15,23,42)]/60 hover:text-[rgb(15,23,42)]'
              }`}
              aria-label={`Switch to ${label} tab`}
            >
              <Icon className="w-4 h-4" />
              <span className="hidden sm:inline">{label}</span>
            </button>
          ))}
        </div>

        {/* Send Email Tab */}
        {activeTab === 'send' && (
          <div className="space-y-6">
            {/* Template Selection */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-6 shadow-sm">
              <h2 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Select Template</h2>
              <div className="grid gap-3">
                {templates.map((template) => (
                  <label
                    key={template.id}
                    className={`flex items-start gap-3 p-4 border rounded-lg cursor-pointer transition-all duration-200 ${
                      selectedTemplate === template.id
                        ? 'border-[rgb(34,139,34)] bg-[rgb(34,139,34)]/5'
                        : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
                    }`}
                  >
                    <input
                      type="radio"
                      name="template"
                      value={template.id}
                      checked={selectedTemplate === template.id}
                      onChange={(e) => setSelectedTemplate(e.target.value)}
                      className="mt-1 w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] focus:ring-[rgb(34,139,34)] focus:ring-offset-0"
                    />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-medium text-[rgb(15,23,42)]">{template.name}</h3>
                        <span className={`px-2 py-1 text-xs rounded-full border ${
                          template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20' :
                          template.type === 'reminder' ? 'bg-[rgb(245,158,11)]/10 text-[rgb(245,158,11)] border-[rgb(245,158,11)]/20' :
                          'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
                        }`}>
                          {template.type}
                        </span>
                      </div>
                      <p className="text-sm text-[rgb(15,23,42)]/60 mb-2">{template.subject}</p>
                      <p className="text-sm text-[rgb(15,23,42)]/40 line-clamp-2">{template.content}</p>
                    </div>
                  </label>
                ))}
              </div>
            </div>

            {/* Recipients */}
            <div className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-6 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Recipients</h2>
                <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]/60">
                  <Users className="w-4 h-4" />
                  {recipients.length} members
                </div>
              </div>
              <div className="space-y-3">
                {recipients.map((recipient) => (
                  <div key={recipient.id} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-[rgb(34,139,34)]/10 rounded-full flex items-center justify-center">
                        <span className="text-sm font-medium text-[rgb(34,139,34)]">
                          {recipient.name.charAt(0)}
                        </span>
                      </div>
                      <div>
                        <p className="font-medium text-[rgb(15,23,42)]">{recipient.name}</p>
                        <p className="text-sm text-[rgb(15,23,42)]/60">{recipient.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {getStatusIcon(recipient.status)}
                      <span className="text-sm text-[rgb(15,23,42)]/60 capitalize">{recipient.status}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Send Button */}
            <button
              onClick={handleSendEmail}
              disabled={!selectedTemplate || isLoading}
              className="w-full flex items-center justify-center gap-2 px-6 py-4 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-xl font-medium transition-all duration-200 hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg active:scale-95"
              aria-label="Send email to all recipients"
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  Send to {recipients.length} Recipients
                </>
              )}
            </button>
          </div>
        )}

        {/* Templates Tab */}
        {activeTab === 'templates' && (
          <div className="space-y-4">
            {templates.map((template) => (
              <div key={template.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-6 shadow-sm">
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">{template.name}</h3>
                    <p className="text-sm text-[rgb(15,23,42)]/60">{template.subject}</p>
                  </div>
                  <span className={`px-3 py-1 text-xs rounded-full border ${
                    template.type === 'invitation' ? 'bg-[rgb(34,139,34)]/10 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/20' :
                    template.type === 'reminder' ? 'bg-[rgb(245,158,11)]/10 text-[rgb(245,158,11)] border-[rgb(245,158,11)]/20' :
                    'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
                  }`}>
                    {template.type}
                  </span>
                </div>
                <div className="bg-[rgb(248,250,252)] rounded-lg p-4">
                  <p className="text-sm text-[rgb(15,23,42)]/80 whitespace-pre-wrap">{template.content}</p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* History Tab */}
        {activeTab === 'history' && (
          <div className="space-y-4">
            {campaigns.map((campaign) => {
              const template = templates.find(t => t.id === campaign.templateId)
              return (
                <div key={campaign.id} className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-6 shadow-sm">
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h3 className="text-lg font-semibold text-[rgb(15,23,42)]">{template?.name}</h3>
                      <p className="text-sm text-[rgb(15,23,42)]/60">
                        Sent {campaign.createdAt.toLocaleDateString()} at {campaign.createdAt.toLocaleTimeString()}
                      </p>
                    </div>
                    <span className={`px-3 py-1 text-xs rounded-full border ${getStatusColor(campaign.status)}`}>
                      {campaign.status}
                    </span>
                  </div>
                  <div className="flex items-center gap-4 text-sm text-[rgb(15,23,42)]/60">
                    <span>{campaign.recipients.length} recipients</span>
                    <span>•</span>
                    <span>{campaign.recipients.filter(r => r.status === 'delivered').length} delivered</span>
                    <span>•</span>
                    <span>{campaign.recipients.filter(r => r.status === 'failed').length} failed</span>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

// Mock data
