'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageSquare, Utensils, Cloud, CheckCircle, AlertCircle, Loader2 } from 'lucide-react'

// Types
interface Location {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  description?: string
  difficulty: 'easy' | 'moderate' | 'hard'
  terrain: string[]
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  status: 'invited' | 'confirmed' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics' | 'safety'
  dueDate: string
  completed: boolean
}

interface Trip {
  id: string
  name: string
  location: Location
  startDate: string
  endDate: string
  members: GroupMember[]
  tasks: Task[]
  meals: Meal[]
  weather?: WeatherData
  status: 'planning' | 'confirmed' | 'active' | 'completed'
}

interface Meal {
  id: string
  name: string
  date: string
  time: 'breakfast' | 'lunch' | 'dinner' | 'snack'
