'use client'

import { useState, useEffect } from 'react'
import { Cloud, CloudRain, Sun, CloudSnow, Zap, Wind, Thermometer, Droplets, Eye, Gauge, AlertTriangle } from 'lucide-react'

interface WeatherData {
  current: {
    temp: number
    feels_like: number
    humidity: number
    pressure: number
    visibility: number
    wind_speed: number
    wind_deg: number
    weather: Array<{
      id: number
      main: string
      description: string
      icon: string
    }>
  }
  daily: Array<{
    dt: number
    temp: {
      min: number
      max: number
    }
    weather: Array<{
      id: number
      main: string
      description: string
      icon: string
    }>
    pop: number
  }>
  alerts?: Array<{
    sender_name: string
    event: string
    description: string
    start: number
    end: number
  }>
}

interface WeatherServiceProps {
  location?: { lat: number; lon: number }
  apiKey?: string
  onWeatherUpdate?: (data: WeatherData) => void
}

export function WeatherService({
  location = { lat: 39.7392, lon: -104.9903 }, // Denver, CO default
  apiKey = 'demo_key',
  onWeatherUpdate = () => {}
}: WeatherServiceProps = {}) {
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)

  // Mock weather data for demo
  const mockWeatherData: WeatherData = {
