  const getWeatherIcon = (weatherMain: string, size: 'sm' | 'md' | 'lg' = 'md') => {
    const iconSize = size === 'sm' ? 16 : size === 'md' ? 24 : 32

    switch (weatherMain.toLowerCase()) {
