                  onChange={(e) => setNewEvent(prev => ({ ...prev, location: e.target.value }))}
                  className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg focus:ring-2 focus:ring-[rgb(34,139,34)] focus:border-transparent outline-none"
                  placeholder="Event location"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                  Invite Members
                </label>
                <div className="space-y-2 max-h-32 overflow-y-auto">
                  {groupMembers.map((member) => (
                    <label key={member.id} className="flex items-center gap-3 p-2 hover:bg-[rgb(248,250,252)] rounded-lg cursor-pointer">
                      <input
                        type="checkbox"
                        checked={newEvent.attendees.includes(member.id)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setNewEvent(prev => ({ ...prev, attendees: [...prev.attendees, member.id] }))
                          } else {
                            setNewEvent(prev => ({ ...prev, attendees: prev.attendees.filter(id => id !== member.id) }))
                          }
                        }}
                        className="w-4 h-4 text-[rgb(34,139,34)] border-[rgb(226,232,240)] rounded focus:ring-[rgb(34,139,34)]"
                      />
                      <span className="text-sm text-[rgb(15,23,42)]">{member.name}</span>
                    </label>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => setShowCreateModal(false)}
                  className="flex-1 px-4 py-2 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(248,250,252)] transition-colors duration-150 font-medium"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCreateEvent}
                  disabled={isLoading || !newEvent.title || !newEvent.start || !newEvent.end}
                  className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? 'Creating...' : 'Create Event'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

