'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, Users, MapPin, Calendar, Utensils, MessageCircle, CheckCircle2, AlertCircle, Wifi, WifiOff } from 'lucide-react'

interface Message {
  id: string
  content: string
  sender: {
    id: string
    name: string
    avatar?: string
  }
  timestamp: Date
  type: 'text' | 'location' | 'task' | 'meal' | 'system'
  metadata?: {
    location?: { lat: number; lng: number; name: string }
    task?: { id: string; title: string; assignee: string }
    meal?: { id: string; name: string; time: string }
  }
  status: 'sending' | 'sent' | 'delivered' | 'failed'
}

interface ChatUser {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  lastSeen?: Date
}

interface ChatAPIProps {
  tripId?: string
  currentUserId?: string
  initialMessages?: Message[]
  users?: ChatUser[]
  onSendMessage?: (message: Omit<Message, 'id' | 'timestamp' | 'status'>) => Promise<void>
  onTyping?: (isTyping: boolean) => void
  isOffline?: boolean
}

export function ChatAPI({
  tripId = 'trip-1',
  currentUserId = 'user-1',
  initialMessages = DEFAULT_MESSAGES,
  users = DEFAULT_USERS,
  onSendMessage = async () => {},
  onTyping = () => {},
  isOffline = false
}: ChatAPIProps = {}) {
  const [messages, setMessages] = useState<Message[]>(initialMessages)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [typingUsers, setTypingUsers] = useState<string[]>([])
  const [isConnected, setIsConnected] = useState(!isOffline)
  const [pendingMessages, setPendingMessages] = useState<Message[]>([])
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  // Simulate network status
  useEffect(() => {
    const interval = setInterval(() => {
      setIsConnected(prev => isOffline ? false : Math.random() > 0.1)
    }, 5000)
    return () => clearInterval(interval)
  }, [isOffline])

  // Handle typing indicator
  useEffect(() => {
    if (isTyping) {
      onTyping(true)
      const timeout = setTimeout(() => {
        setIsTyping(false)
        onTyping(false)
      }, 3000)
      return () => clearTimeout(timeout)
    }
  }, [isTyping, onTyping])

  // Retry failed messages when back online
  useEffect(() => {
    if (isConnected && pendingMessages.length > 0) {
      pendingMessages.forEach(msg => {
        handleSendMessage(msg.content, msg.type, msg.metadata)
      })
      setPendingMessages([])
    }
  }, [isConnected])

  const handleSendMessage = async (content: string, type: Message['type'] = 'text', metadata?: Message['metadata']) => {
    if (!content.trim()) return

    const tempId = `temp-${Date.now()}`
    const newMsg: Message = {
      id: tempId,
      content,
      sender: users.find(u => u.id === currentUserId) || users[0],
      timestamp: new Date(),
      type,
      metadata,
      status: isConnected ? 'sending' : 'failed'
    }

    setMessages(prev => [...prev, newMsg])
    setNewMessage('')

    if (!isConnected) {
      setPendingMessages(prev => [...prev, newMsg])
      return
    }

    try {
      await onSendMessage({
        content,
        sender: newMsg.sender,
        type,
        metadata
      })

      // Simulate message delivery
      setTimeout(() => {
        setMessages(prev => prev.map(msg => 
          msg.id === tempId 
            ? { ...msg, status: 'delivered', id: `msg-${Date.now()}` }
            : msg
        ))
      }, 1000)
    } catch (error) {
      setMessages(prev => prev.map(msg => 
        msg.id === tempId ? { ...msg, status: 'failed' } : msg
      ))
    }
  }

  const handleInputChange = (value: string) => {
    setNewMessage(value)
    if (value.trim() && !isTyping) {
      setIsTyping(true)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage(newMessage)
    }
  }

  const retryMessage = (messageId: string) => {
    const message = messages.find(m => m.id === messageId)
    if (message) {
      handleSendMessage(message.content, message.type, message.metadata)
      setMessages(prev => prev.filter(m => m.id !== messageId))
    }
  }

  const renderMessage = (message: Message) => {
    const isOwn = message.sender.id === currentUserId
    const isSystem = message.type === 'system'

    if (isSystem) {
      return (
        <div key={message.id} className="flex justify-center my-4">
          <div className="px-3 py-1 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-full text-sm font-medium">
            {message.content}
          </div>
        </div>
      )
    }

    return (
      <div key={message.id} className={`flex ${isOwn ? 'justify-end' : 'justify-start'} mb-4`}>
        <div className={`flex max-w-[80%] ${isOwn ? 'flex-row-reverse' : 'flex-row'} gap-2`}>
          {!isOwn && (
            <div className="w-8 h-8 rounded-full bg-[rgb(34,139,34)] flex items-center justify-center text-white text-sm font-medium flex-shrink-0">
              {message.sender.name.charAt(0)}
            </div>
          )}

          <div className={`flex flex-col ${isOwn ? 'items-end' : 'items-start'}`}>
            {!isOwn && (
              <span className="text-xs text-[rgb(15,23,42)] font-medium mb-1">
                {message.sender.name}
              </span>
            )}

            <div className={`px-4 py-2 rounded-2xl ${
              isOwn 
                ? 'bg-[rgb(34,139,34)] text-white' 
                : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
            } shadow-sm`}>
              {message.type === 'location' && message.metadata?.location && (
                <div className="flex items-center gap-2 mb-2">
                  <MapPin className="w-4 h-4" />
                  <span className="text-sm font-medium">{message.metadata.location.name}</span>
                </div>
              )}

              {message.type === 'task' && message.metadata?.task && (
                <div className="flex items-center gap-2 mb-2">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-sm font-medium">{message.metadata.task.title}</span>
                </div>
              )}

              {message.type === 'meal' && message.metadata?.meal && (
                <div className="flex items-center gap-2 mb-2">
                  <Utensils className="w-4 h-4" />
                  <span className="text-sm font-medium">{message.metadata.meal.name}</span>
                </div>
              )}

              <p className="text-sm leading-relaxed">{message.content}</p>
            </div>

            <div className="flex items-center gap-2 mt-1">
              <span className="text-xs text-gray-500">
                {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>

              {isOwn && (
                <div className="flex items-center">
                  {message.status === 'sending' && (
                    <div className="w-3 h-3 border border-gray-400 border-t-transparent rounded-full animate-spin" />
                  )}
                  {message.status === 'delivered' && (
                    <CheckCircle2 className="w-3 h-3 text-[rgb(34,139,34)]" />
                  )}
                  {message.status === 'failed' && (
                    <button
                      onClick={() => retryMessage(message.id)}
                      className="flex items-center gap-1 text-[rgb(220,38,38)] hover:text-red-700 transition-colors"
                      aria-label="Retry sending message"
                    >
                      <AlertCircle className="w-3 h-3" />
                      <span className="text-xs">Retry</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-white">
        <div className="flex items-center gap-3">
          <MessageCircle className="w-6 h-6 text-[rgb(34,139,34)]" />
          <div>
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">Trip Chat</h2>
            <div className="flex items-center gap-2">
              <Users className="w-4 h-4 text-gray-500" />
              <span className="text-sm text-gray-500">{users.length} members</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isConnected ? (
            <Wifi className="w-5 h-5 text-[rgb(34,139,34)]" />
          ) : (
            <WifiOff className="w-5 h-5 text-[rgb(220,38,38)]" />
          )}
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-2">
        {messages.map(renderMessage)}

        {typingUsers.length > 0 && (
          <div className="flex items-center gap-2 text-gray-500 text-sm">
            <div className="flex gap-1">
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
            </div>
            <span>{typingUsers.join(', ')} {typingUsers.length === 1 ? 'is' : 'are'} typing...</span>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-white">
        {!isConnected && (
          <div className="mb-3 p-2 bg-[rgb(220,38,38)]/10 border border-[rgb(220,38,38)]/20 rounded-lg">
            <p className="text-sm text-[rgb(220,38,38)] text-center">
              You're offline. Messages will be sent when connection is restored.
            </p>
          </div>
        )}

        <div className="flex items-end gap-2">
          <div className="flex-1">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => handleInputChange(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-2xl text-[rgb(15,23,42)] placeholder-gray-500 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
              disabled={false}
              aria-label="Type your message"
            />
          </div>

          <button
            onClick={() => handleSendMessage(newMessage)}
            disabled={!newMessage.trim()}
            className="w-12 h-12 bg-[rgb(34,139,34)] text-white rounded-full flex items-center justify-center hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 shadow-md hover:shadow-lg active:scale-95"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

