'use client'

import { useState, useEffect, useCallback } from 'react'
import { Search, MapPin, Star, Mountain, Compass, Wifi, WifiOff } from 'lucide-react'

interface Location {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  description: string
  difficulty: 'Easy' | 'Moderate' | 'Difficult' | 'Expert'
  terrain: string[]
  amenities: string[]
  rating: number
  reviewCount: number
  distance?: number
  isFavorite: boolean
  imageUrl: string
}

interface LocationAPIProps {
  onLocationSelect?: (location: Location) => void
  onLocationSave?: (location: Location) => void
  initialSearchQuery?: string
  userLocation?: { lat: number; lng: number }
}

export function LocationAPI({
  onLocationSelect = () => console.log('Location selected'),
  onLocationSave = () => console.log('Location saved'),
  initialSearchQuery = '',
  userLocation
}: LocationAPIProps = {}) {
  const [searchQuery, setSearchQuery] = useState(initialSearchQuery)
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(MOCK_LOCATIONS)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isOnline, setIsOnline] = useState(true)
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('All')
  const [showFavoritesOnly, setShowFavoritesOnly] = useState(false)

  // Monitor online status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  // Debounced search
  useEffect(() => {
    const timer = setTimeout(() => {
      handleSearch()
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery, selectedDifficulty, showFavoritesOnly])

  const handleSearch = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500))

      let filtered = locations.filter(location => {
        const matchesSearch = location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            location.description.toLowerCase().includes(searchQuery.toLowerCase())
        const matchesDifficulty = selectedDifficulty === 'All' || location.difficulty === selectedDifficulty
        const matchesFavorites = !showFavoritesOnly || location.isFavorite

        return matchesSearch && matchesDifficulty && matchesFavorites
      })

      // Calculate distances if user location is available
      if (userLocation) {
        filtered = filtered.map(location => ({
          ...location,
          distance: calculateDistance(userLocation, location.coordinates)
        })).sort((a, b) => (a.distance || 0) - (b.distance || 0))
      }

      setFilteredLocations(filtered)
    } catch (err) {
      setError('Failed to search locations. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }, [searchQuery, selectedDifficulty, showFavoritesOnly, locations, userLocation])

  const toggleFavorite = useCallback((locationId: string) => {
    setLocations(prev => prev.map(location => 
      location.id === locationId 
        ? { ...location, isFavorite: !location.isFavorite }
        : location
    ))
    setFilteredLocations(prev => prev.map(location => 
      location.id === locationId 
        ? { ...location, isFavorite: !location.isFavorite }
        : location
    ))
  }, [])

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-green-100 text-green-800 border-green-200'
      case 'Moderate': return 'bg-yellow-100 text-yellow-800 border-yellow-200'
      case 'Difficult': return 'bg-orange-100 text-orange-800 border-orange-200'
      case 'Expert': return 'bg-red-100 text-red-800 border-red-200'
      default: return 'bg-[rgb(241, 245, 249)] text-gray-800 border-[rgb(226, 232, 240)]'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-3">
        <div className="flex items-center justify-between mb-3">
          <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Find Locations</h1>
          <div className="flex items-center gap-2">
            {isOnline ? (
              <Wifi className="w-4 h-4 text-[rgb(34,139,34)]" />
            ) : (
              <WifiOff className="w-4 h-4 text-[rgb(220,38,38)]" />
            )}
          </div>
        </div>

        {/* Search Bar */}
        <div className="relative mb-3">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search locations..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
            style={{ minHeight: '44px' }}
          />
        </div>

        {/* Filters */}
        <div className="flex gap-2 overflow-x-auto pb-2">
          <button
            onClick={() => setShowFavoritesOnly(!showFavoritesOnly)}
            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 ${
              showFavoritesOnly
                ? 'bg-[rgb(34,139,34)] text-white'
                : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)]'
            }`}
            style={{ minHeight: '44px' }}
          >
            <Star className={`w-4 h-4 ${showFavoritesOnly ? 'fill-current' : ''}`} />
            Favorites
          </button>

          {['All', 'Easy', 'Moderate', 'Difficult', 'Expert'].map((difficulty) => (
            <button
              key={difficulty}
              onClick={() => setSelectedDifficulty(difficulty)}
              className={`px-3 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 ${
                selectedDifficulty === difficulty
                  ? 'bg-[rgb(34,139,34)] text-white'
                  : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)]'
              }`}
              style={{ minHeight: '44px' }}
            >
              {difficulty}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="px-4 py-4">
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-red-800 text-sm">{error}</p>
            <button
              onClick={handleSearch}
              className="mt-2 px-3 py-1 bg-red-100 text-red-800 rounded text-sm font-medium hover:bg-red-200 transition-colors duration-150"
            >
              Retry
            </button>
          </div>
        )}

        {isLoading ? (
