                      </div>
                      {location.distance && (
                        <div className="flex items-center gap-1">
                          <Compass className="w-3 h-3 text-gray-400" />
                          <span className="text-xs text-gray-600">{location.distance.toFixed(1)} mi</span>
                        </div>
                      )}
                    </div>

                    <div className="flex flex-wrap gap-1 mb-3">
                      {location.terrain.slice(0, 3).map((terrain) => (
                        <span
                          key={terrain}
                          className="px-2 py-1 bg-[rgb(241,245,249)] text-gray-600 rounded text-xs"
                        >
                          {terrain}
                        </span>
                      ))}
                      {location.terrain.length > 3 && (
                        <span className="px-2 py-1 bg-[rgb(241,245,249)] text-gray-600 rounded text-xs">
                          +{location.terrain.length - 3} more
                        </span>
                      )}
                    </div>

                    <div className="flex gap-2">
                      <button
                        onClick={() => onLocationSelect(location)}
                        className="flex-1 px-3 py-2 bg-[rgb(34,139,34)] text-white rounded-lg text-sm font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150"
                        style={{ minHeight: '44px' }}
                      >
                        <MapPin className="w-4 h-4 inline mr-1" />
