                      </button>
                      <button
                        onClick={() => onLocationSave(location)}
                        className="px-3 py-2 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] border border-[rgb(226,232,240)] rounded-lg text-sm font-medium hover:bg-[rgb(241, 245, 249)] transition-colors duration-150"
                        style={{ minHeight: '44px' }}
                      >
                        Save
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

// Helper function to calculate distance between two coordinates
function calculateDistance(
  point1: { lat: number; lng: number },
  point2: { lat: number; lng: number }
): number {
  const R = 3959 // Earth's radius in miles
  const dLat = (point2.lat - point1.lat) * Math.PI / 180
  const dLng = (point2.lng - point1.lng) * Math.PI / 180
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(point1.lat * Math.PI / 180) * Math.cos(point2.lat * Math.PI / 180) *
    Math.sin(dLng/2) * Math.sin(dLng/2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
  return R * c
}

