'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar, MessageSquare, Send } from 'lucide-react'

interface RSVPResponse {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  tripId: string
  status: 'pending' | 'accepted' | 'declined'
  response: string
  attendeeCount: number
  dietaryRestrictions?: string
  notes?: string
  respondedAt?: Date
  createdAt: Date
}

interface Trip {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  organizerId: string
  maxAttendees: number
  description: string
}

interface RSVPAPIProps {
  tripId?: string
  userId?: string
  onRSVPUpdate?: (rsvp: RSVPResponse) => void
  onRSVPSubmit?: (rsvpData: Partial<RSVPResponse>) => void
}

export function RSVPAPI({
  tripId = 'trip-1',
  userId = 'user-1',
  onRSVPUpdate = () => console.log('RSVP updated'),
  onRSVPSubmit = () => console.log('RSVP submitted')
}: RSVPAPIProps = {}) {
  const [trip, setTrip] = useState<Trip | null>(null)
  const [rsvps, setRSVPs] = useState<RSVPResponse[]>([])
  const [userRSVP, setUserRSVP] = useState<RSVPResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [showRSVPForm, setShowRSVPForm] = useState(false)
  const [formData, setFormData] = useState({
    status: 'pending' as 'pending' | 'accepted' | 'declined',
    attendeeCount: 1,
    dietaryRestrictions: '',
    notes: ''
  })

  useEffect(() => {
    loadTripData()
    loadRSVPs()
  }, [tripId])

  const loadTripData = async () => {
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 800))
      setTrip(MOCK_TRIP)
    } catch (error) {
      console.error('Failed to load trip:', error)
    }
  }

  const loadRSVPs = async () => {
    try {
      setLoading(true)
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 600))
      setRSVPs(MOCK_RSVPS)

      const existingRSVP = MOCK_RSVPS.find(rsvp => rsvp.userId === userId)
      setUserRSVP(existingRSVP || null)
    } catch (error) {
      console.error('Failed to load RSVPs:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleRSVPSubmit = async () => {
    if (!trip) return

    try {
      setSubmitting(true)

      const rsvpData: RSVPResponse = {
        id: userRSVP?.id || `rsvp-${Date.now()}`,
        userId,
        userName: 'Current User',
        tripId,
        status: formData.status,
        response: formData.status === 'accepted' ? 'Going' : formData.status === 'declined' ? 'Not Going' : 'Maybe',
        attendeeCount: formData.attendeeCount,
        dietaryRestrictions: formData.dietaryRestrictions,
        notes: formData.notes,
        respondedAt: new Date(),
        createdAt: userRSVP?.createdAt || new Date()
      }

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))

      if (userRSVP) {
        // Update existing RSVP
        setRSVPs(prev => prev.map(rsvp => 
          rsvp.id === userRSVP.id ? rsvpData : rsvp
        ))
      } else {
        // Add new RSVP
        setRSVPs(prev => [...prev, rsvpData])
      }

      setUserRSVP(rsvpData)
      setShowRSVPForm(false)
      onRSVPSubmit(rsvpData)
      onRSVPUpdate(rsvpData)
    } catch (error) {
      console.error('Failed to submit RSVP:', error)
    } finally {
      setSubmitting(false)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'accepted':
        return 'text-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10 border-[rgb(34,139,34)]/20'
      case 'declined':
        return 'text-[rgb(220,38,38)] bg-[rgb(220,38,38)]/10 border-[rgb(220,38,38)]/20'
      default:
        return 'text-[rgb(245,158,11)] bg-[rgb(245,158,11)]/10 border-[rgb(245,158,11)]/20'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted':
        return <Check className="w-3 h-3" />
      case 'declined':
        return <X className="w-3 h-3" />
      default:
        return <Clock className="w-3 h-3" />
    }
  }

  const acceptedCount = rsvps.filter(rsvp => rsvp.status === 'accepted').length
  const totalAttendees = rsvps
    .filter(rsvp => rsvp.status === 'accepted')
    .reduce((sum, rsvp) => sum + rsvp.attendeeCount, 0)

  if (loading) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] p-4">
        <div className="max-w-2xl mx-auto space-y-6">
          <div className="bg-[rgb(241,245,249)] rounded-xl h-48 animate-pulse" />
          <div className="space-y-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="bg-[rgb(241,245,249)] rounded-lg h-16 animate-pulse" />
            ))}
          </div>
        </div>
      </div>
    )
  }

  if (!trip) {
    return (
      <div className="min-h-screen bg-[rgb(255,255,255)] p-4 flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-16 h-16 bg-[rgb(241,245,249)] rounded-full mx-auto flex items-center justify-center">
            <MapPin className="w-8 h-8 text-[rgb(15,23,42)]" />
          </div>
          <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Not Found</h2>
          <p className="text-[rgb(15,23,42)]/60">The trip you're looking for doesn't exist.</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Trip Header */}
      <div className="bg-gradient-to-br from-[rgb(34,139,34)] to-[rgb(34,139,34)]/80 text-white p-6">
        <div className="max-w-2xl mx-auto">
          <h1 className="text-2xl font-bold mb-2">{trip.title}</h1>
          <div className="flex items-center gap-4 text-sm opacity-90">
            <div className="flex items-center gap-1">
              <MapPin className="w-4 h-4" />
              <span>{trip.location}</span>
            </div>
            <div className="flex items-center gap-1">
              <Calendar className="w-4 h-4" />
              <span>{trip.startDate.toLocaleDateString()}</span>
            </div>
          </div>
          <p className="mt-3 text-sm opacity-90">{trip.description}</p>
        </div>
      </div>

      <div className="max-w-2xl mx-auto p-4 space-y-6">
        {/* RSVP Summary */}
        <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold text-[rgb(15,23,42)]">RSVP Status</h2>
            <div className="flex items-center gap-1 text-sm text-[rgb(15,23,42)]/60">
              <Users className="w-4 h-4" />
              <span>{totalAttendees}/{trip.maxAttendees} attending</span>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4 mb-6">
            <div className="text-center">
              <div className="text-2xl font-bold text-[rgb(34,139,34)]">{acceptedCount}</div>
              <div className="text-xs text-[rgb(15,23,42)]/60">Going</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-[rgb(220,38,38)]">
                {rsvps.filter(r => r.status === 'declined').length}
              </div>
              <div className="text-xs text-[rgb(15,23,42)]/60">Not Going</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-[rgb(245,158,11)]">
                {rsvps.filter(r => r.status === 'pending').length}
              </div>
              <div className="text-xs text-[rgb(15,23,42)]/60">Pending</div>
            </div>
          </div>

          {/* User RSVP Action */}
          {!userRSVP ? (
            <button
              onClick={() => setShowRSVPForm(true)}
              className="w-full bg-[rgb(34,139,34)] text-white py-3 px-4 rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-200 shadow-md active:scale-95"
              aria-label="Respond to RSVP invitation"
            >
              Respond to Invitation
            </button>
          ) : (
            <div className="space-y-3">
              <div className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg border border-[rgb(226,232,240)]">
                <div className="flex items-center gap-2">
                  <div className={`px-2 py-1 rounded-full text-xs font-medium border flex items-center gap-1 ${getStatusColor(userRSVP.status)}`}>
                    {getStatusIcon(userRSVP.status)}
                    <span className="capitalize">{userRSVP.status}</span>
                  </div>
                  <span className="text-sm text-[rgb(15,23,42)]">Your Response</span>
                </div>
                <button
                  onClick={() => setShowRSVPForm(true)}
                  className="text-sm text-[rgb(34,139,34)] hover:text-[rgb(34,139,34)]/80 font-medium"
                  aria-label="Change RSVP response"
                >
                  Change
                </button>
              </div>
              {userRSVP.notes && (
                <div className="text-sm text-[rgb(15,23,42)]/60 bg-[rgb(248,250,252)] p-3 rounded-lg">
                  <strong>Your note:</strong> {userRSVP.notes}
                </div>
