            </div>
          )}
        </div>

        {/* RSVP List */}
        <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md">
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Responses</h3>
          <div className="space-y-3">
            {rsvps.map((rsvp) => (
