                    <textarea
                      value={formData.notes}
                      onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                      placeholder="Any additional information..."
                      rows={3}
                      className="w-full p-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)]/40 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-200 resize-none"
                      aria-label="Enter additional notes"
                    />
                  </div>
                </div>

                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => setShowRSVPForm(false)}
                    className="flex-1 py-3 px-4 border border-[rgb(226,232,240)] text-[rgb(15,23,42)] rounded-lg font-medium hover:bg-[rgb(248,250,252)] transition-colors duration-200"
                    aria-label="Cancel RSVP form"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleRSVPSubmit}
                    disabled={submitting}
                    className="flex-1 py-3 px-4 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-200 shadow-md disabled:opacity-50 disabled:cursor-not-allowed active:scale-95 flex items-center justify-center gap-2"
                    aria-label="Submit RSVP response"
                  >
                    {submitting ? (
                      <>
                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        <span>Submitting...</span>
                      </>
                    ) : (
                      <>
                        <Send className="w-4 h-4" />
                        <span>Submit RSVP</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

