'use client'

import { useState, useEffect } from 'react'
import { CheckCircle2, Circle, Users, Calendar, AlertCircle, Plus, Trash2, Edit3 } from 'lucide-react'

interface Task {
  id: string
  title: string
  description: string
  assignedTo: string[]
  dueDate: string
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'other'
  priority: 'low' | 'medium' | 'high'
  completed: boolean
  createdAt: string
  tripId: string
}

interface TaskAssignment {
  taskId: string
  userId: string
  assignedAt: string
}

interface User {
  id: string
  name: string
  email: string
  avatar?: string
}

interface TaskAPIProps {
  tripId?: string
  onTaskUpdate?: (task: Task) => void
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt'>) => void
  onTaskDelete?: (taskId: string) => void
}

export function TaskAPI({
  tripId = 'trip-1',
  onTaskUpdate = () => console.log('Task updated'),
  onTaskCreate = () => console.log('Task created'),
  onTaskDelete = () => console.log('Task deleted')
}: TaskAPIProps = {}) {
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [users, setUsers] = useState<User[]>(DEFAULT_USERS)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingTask, setEditingTask] = useState<Task | null>(null)
  const [filter, setFilter] = useState<'all' | 'pending' | 'completed'>('all')
  const [categoryFilter, setCategoryFilter] = useState<string>('all')

  // Simulate API calls
  const createTask = async (taskData: Omit<Task, 'id' | 'createdAt'>) => {
    setLoading(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 500)) // Simulate API delay

      const newTask: Task = {
        ...taskData,
        id: `task-${Date.now()}`,
        createdAt: new Date().toISOString()
      }

      setTasks(prev => [...prev, newTask])
      onTaskCreate(taskData)
      setShowCreateForm(false)
    } catch (err) {
      setError('Failed to create task')
    } finally {
      setLoading(false)
    }
  }

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setLoading(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 300))

      setTasks(prev => prev.map(task => 
        task.id === taskId ? { ...task, ...updates } : task
      ))

      const updatedTask = tasks.find(t => t.id === taskId)
      if (updatedTask) {
        onTaskUpdate({ ...updatedTask, ...updates })
      }
    } catch (err) {
      setError('Failed to update task')
    } finally {
      setLoading(false)
    }
  }

  const deleteTask = async (taskId: string) => {
    setLoading(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 300))

      setTasks(prev => prev.filter(task => task.id !== taskId))
      onTaskDelete(taskId)
    } catch (err) {
      setError('Failed to delete task')
    } finally {
      setLoading(false)
    }
  }

  const assignUserToTask = async (taskId: string, userId: string) => {
    const task = tasks.find(t => t.id === taskId)
    if (!task) return

    const isAssigned = task.assignedTo.includes(userId)
    const newAssignedTo = isAssigned 
      ? task.assignedTo.filter(id => id !== userId)
      : [...task.assignedTo, userId]

    await updateTask(taskId, { assignedTo: newAssignedTo })
  }

  const toggleTaskComplete = async (taskId: string) => {
    const task = tasks.find(t => t.id === taskId)
    if (!task) return

    await updateTask(taskId, { completed: !task.completed })
  }

  const filteredTasks = tasks.filter(task => {
    const statusMatch = filter === 'all' || 
      (filter === 'completed' && task.completed) ||
      (filter === 'pending' && !task.completed)

    const categoryMatch = categoryFilter === 'all' || task.category === categoryFilter

    return statusMatch && categoryMatch
  })

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'bg-[rgb(220,38,38)] text-white'
      case 'medium': return 'bg-[rgb(245,158,11)] text-white'
      case 'low': return 'bg-[rgb(34,139,34)] text-white'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)]'
    }
  }

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'food': return '🍽️'
      case 'equipment': return '🎒'
      case 'logistics': return '📋'
      case 'safety': return '🛡️'
      default: return '📝'
    }
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Header */}
        <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-[rgb(15,23,42)]">Trip Tasks</h1>
              <p className="text-[rgb(100,116,139)] mt-1">Manage and assign tasks for your off-road adventure</p>
            </div>
            <button
              onClick={() => setShowCreateForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(22,101,22)] transition-colors duration-150 shadow-md active:scale-95"
              aria-label="Create new task"
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">New Task</span>
            </button>
          </div>

          {/* Filters */}
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="flex gap-2">
              {['all', 'pending', 'completed'].map(status => (
                <button
                  key={status}
                  onClick={() => setFilter(status as any)}
                  className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors duration-150 ${
                    filter === status
                      ? 'bg-[rgb(34,139,34)] text-white'
                      : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)] hover:bg-[rgb(241,245,249)]'
                  }`}
                >
                  {status.charAt(0).toUpperCase() + status.slice(1)}
                </button>
              ))}
            </div>

            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="px-3 py-1.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-sm text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50"
            >
              <option value="all">All Categories</option>
              <option value="food">Food</option>
              <option value="equipment">Equipment</option>
              <option value="logistics">Logistics</option>
              <option value="safety">Safety</option>
              <option value="other">Other</option>
            </select>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-[rgb(254,242,242)] border border-[rgb(252,165,165)] rounded-lg p-4 flex items-center gap-3">
            <AlertCircle className="w-5 h-5 text-[rgb(220,38,38)]" />
            <span className="text-[rgb(220,38,38)]">{error}</span>
            <button
              onClick={() => setError(null)}
              className="ml-auto text-[rgb(220,38,38)] hover:text-[rgb(185,28,28)]"
            >
              ×
            </button>
          </div>
        )}

        {/* Task List */}
        <div className="space-y-4">
          {filteredTasks.length === 0 ? (
            <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-8 text-center">
              <div className="text-4xl mb-4">📝</div>
              <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-2">No tasks found</h3>
              <p className="text-[rgb(100,116,139)] mb-4">
                {filter === 'all' ? 'Create your first task to get started' : `No ${filter} tasks found`}
              </p>
              <button
                onClick={() => setShowCreateForm(true)}
                className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(22,101,22)] transition-colors duration-150"
              >
                Create Task
              </button>
            </div>
          ) : (
            filteredTasks.map(task => (
              <TaskCard
                key={task.id}
                task={task}
                users={users}
                onToggleComplete={() => toggleTaskComplete(task.id)}
                onAssignUser={(userId) => assignUserToTask(task.id, userId)}
                onEdit={() => setEditingTask(task)}
                onDelete={() => deleteTask(task.id)}
                getPriorityColor={getPriorityColor}
                getCategoryIcon={getCategoryIcon}
                loading={loading}
              />
            ))
          )}
        </div>

        {/* Create/Edit Task Form */}
        {(showCreateForm || editingTask) && (
          <TaskForm
            task={editingTask}
            users={users}
            onSubmit={editingTask ? 
              (data) => updateTask(editingTask.id, data) : 
              createTask
            }
            onCancel={() => {
              setShowCreateForm(false)
              setEditingTask(null)
            }}
            loading={loading}
          />
        )}
      </div>
    </div>
  )
}

interface TaskCardProps {
  task: Task
  users: User[]
  onToggleComplete: () => void
  onAssignUser: (userId: string) => void
  onEdit: () => void
  onDelete: () => void
  getPriorityColor: (priority: string) => string
  getCategoryIcon: (category: string) => string
  loading: boolean
}

function TaskCard({
  task,
  users,
  onToggleComplete,
  onAssignUser,
  onEdit,
  onDelete,
  getPriorityColor,
  getCategoryIcon,
  loading
}: TaskCardProps) {
  const [showAssignments, setShowAssignments] = useState(false)

  return (
    <div className={`bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md transition-all duration-200 ${
      task.completed ? 'opacity-75' : ''
    }`}>
      <div className="flex items-start gap-4">
        <button
          onClick={onToggleComplete}
          disabled={loading}
          className="mt-1 text-[rgb(34,139,34)] hover:text-[rgb(22,101,22)] transition-colors duration-150 disabled:opacity-50"
          aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
        >
          {task.completed ? (
            <CheckCircle2 className="w-5 h-5" />
          ) : (
            <Circle className="w-5 h-5" />
          )}
        </button>

        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-4 mb-3">
            <div className="flex-1">
              <h3 className={`font-semibold text-[rgb(15,23,42)] ${
                task.completed ? 'line-through' : ''
              }`}>
                {task.title}
              </h3>
              {task.description && (
                <p className="text-[rgb(100,116,139)] text-sm mt-1">{task.description}</p>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={onEdit}
                className="p-1.5 text-[rgb(100,116,139)] hover:text-[rgb(15,23,42)] hover:bg-[rgb(248,250,252)] rounded-lg transition-colors duration-150"
                aria-label="Edit task"
              >
                <Edit3 className="w-4 h-4" />
              </button>
              <button
                onClick={onDelete}
                className="p-1.5 text-[rgb(100,116,139)] hover:text-[rgb(220,38,38)] hover:bg-[rgb(254,242,242)] rounded-lg transition-colors duration-150"
                aria-label="Delete task"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-3 mb-4">
            <span className={`px-2 py-1 rounded-lg text-xs font-medium ${getPriorityColor(task.priority)}`}>
              {task.priority.toUpperCase()}
            </span>

            <span className="px-2 py-1 bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-lg text-xs font-medium flex items-center gap-1">
              <span>{getCategoryIcon(task.category)}</span>
              {task.category}
            </span>

            <div className="flex items-center gap-1 text-xs text-[rgb(100,116,139)]">
              <Calendar className="w-3 h-3" />
              {new Date(task.dueDate).toLocaleDateString()}
