          </div>

          <div className="flex items-center justify-between">
            <button
              onClick={() => setShowAssignments(!showAssignments)}
              className="flex items-center gap-2 px-3 py-1.5 bg-[rgb(248,250,252)] hover:bg-[rgb(241,245,249)] rounded-lg text-sm text-[rgb(15,23,42)] transition-colors duration-150"
            >
              <Users className="w-4 h-4" />
              <span>{task.assignedTo.length} assigned</span>
            </button>

            {task.assignedTo.length > 0 && (
              <div className="flex -space-x-2">
                {task.assignedTo.slice(0, 3).map(userId => {
                  const user = users.find(u => u.id === userId)
                  return user ? (
                    <div
                      key={userId}
                      className="w-8 h-8 bg-[rgb(34,139,34)] text-white rounded-full flex items-center justify-center text-xs font-medium border-2 border-white"
                      title={user.name}
                    >
                      {user.name.charAt(0).toUpperCase()}
                    </div>
                  ) : null
                })}
                {task.assignedTo.length > 3 && (
                  <div className="w-8 h-8 bg-[rgb(100,116,139)] text-white rounded-full flex items-center justify-center text-xs font-medium border-2 border-white">
                    +{task.assignedTo.length - 3}
                  </div>
                )}
              </div>
            )}
          </div>

          {showAssignments && (
            <div className="mt-4 pt-4 border-t border-[rgb(226,232,240)]">
              <h4 className="text-sm font-medium text-[rgb(15,23,42)] mb-3">Assign Members</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {users.map(user => (
                  <button
                    key={user.id}
                    onClick={() => onAssignUser(user.id)}
                    className={`flex items-center gap-3 p-3 rounded-lg border transition-all duration-150 ${
                      task.assignedTo.includes(user.id)
                        ? 'bg-[rgb(34,139,34)] text-white border-[rgb(34,139,34)]'
                        : 'bg-white text-[rgb(15,23,42)] border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                    }`}
                  >
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                      task.assignedTo.includes(user.id)
                        ? 'bg-white/20 text-white'
                        : 'bg-[rgb(34,139,34)] text-white'
                    }`}>
                      {user.name.charAt(0).toUpperCase()}
                    </div>
                    <span className="text-sm">{user.name}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

interface TaskFormProps {
  task?: Task | null
  users: User[]
  onSubmit: (data: any) => void
  onCancel: () => void
  loading: boolean
}

function TaskForm({ task, users, onSubmit, onCancel, loading }: TaskFormProps) {
  const [formData, setFormData] = useState({
    title: task?.title || '',
    description: task?.description || '',
    category: task?.category || 'other',
    priority: task?.priority || 'medium',
    dueDate: task?.dueDate ? task.dueDate.split('T')[0] : '',
    assignedTo: task?.assignedTo || []
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!formData.title.trim()) return

    onSubmit({
      ...formData,
      dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : new Date().toISOString(),
      completed: task?.completed || false,
      tripId: task?.tripId || 'trip-1'
    })
  }

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
        <h2 className="text-xl font-bold text-[rgb(15,23,42)] mb-6">
          {task ? 'Edit Task' : 'Create New Task'}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Task Title *
            </label>
            <input
              type="text"
              value={formData.title}
              onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
              className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50"
              placeholder="Enter task title"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Description
            </label>
            <textarea
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 resize-none"
              rows={3}
              placeholder="Enter task description"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Category
              </label>
              <select
                value={formData.category}
                onChange={(e) => setFormData(prev => ({ ...prev, category: e.target.value as any }))}
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50"
              >
                <option value="food">Food</option>
                <option value="equipment">Equipment</option>
                <option value="logistics">Logistics</option>
                <option value="safety">Safety</option>
                <option value="other">Other</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
                Priority
              </label>
              <select
                value={formData.priority}
                onChange={(e) => setFormData(prev => ({ ...prev, priority: e.target.value as any }))}
                className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50"
              >
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">
              Due Date
            </label>
            <input
              type="date"
              value={formData.dueDate}
              onChange={(e) => setFormData(prev => ({ ...prev, dueDate: e.target.value }))}
              className="w-full px-3 py-2 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50"
            />
          </div>

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 px-4 py-2 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-lg hover:bg-[rgb(241,245,249)] transition-colors duration-150 font-medium"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading || !formData.title.trim()}
              className="flex-1 px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg hover:bg-[rgb(22,101,22)] transition-colors duration-150 font-medium disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Saving...' : task ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

