'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageCircle, Utensils, CheckCircle, Clock, Sun, Cloud, CloudRain, Snow } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  status: 'planning' | 'confirmed' | 'completed'
  memberCount: number
  weatherForecast: WeatherData[]
}

interface WeatherData {
  date: string
  condition: 'sunny' | 'cloudy' | 'rainy' | 'snowy'
  high: number
  low: number
}

interface Task {
  id: string
  title: string
  assignee: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface Meal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner'
  preparedBy: string
}

interface TripPlannerProps {
  initialTrips?: Trip[]
  onCreateTrip?: (trip: Omit<Trip, 'id'>) => void
  onUpdateTrip?: (id: string, updates: Partial<Trip>) => void
}

export function TripPlanner({
  initialTrips = DEFAULT_TRIPS,
  onCreateTrip = (trip) => console.log('Create trip:', trip),
  onUpdateTrip = (id, updates) => console.log('Update trip:', id, updates)
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState<'trips' | 'tasks' | 'meals' | 'chat'>('trips')
  const [trips, setTrips] = useState<Trip[]>(initialTrips)
  const [selectedTrip, setSelectedTrip] = useState<Trip | null>(trips[0] || null)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [meals, setMeals] = useState<Meal[]>(DEFAULT_MEALS)
  const [showNewTripForm, setShowNewTripForm] = useState(false)
  const [newTripData, setNewTripData] = useState({
    name: '',
    location: '',
    startDate: '',
    endDate: ''
  })

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return <Sun className="w-4 h-4 text-yellow-500" />
      case 'cloudy': return <Cloud className="w-4 h-4 text-gray-500" />
      case 'rainy': return <CloudRain className="w-4 h-4 text-[rgb(34, 139, 34)]" />
      case 'snowy': return <Snow className="w-4 h-4 text-blue-300" />
      default: return <Sun className="w-4 h-4 text-yellow-500" />
    }
  }

  const handleCreateTrip = () => {
    if (newTripData.name && newTripData.location && newTripData.startDate && newTripData.endDate) {
      const newTrip: Trip = {
        id: Date.now().toString(),
        ...newTripData,
        status: 'planning',
        memberCount: 1,
        weatherForecast: DEFAULT_WEATHER
      }
      setTrips([...trips, newTrip])
      onCreateTrip(newTrip)
      setNewTripData({ name: '', location: '', startDate: '', endDate: '' })
      setShowNewTripForm(false)
      setSelectedTrip(newTrip)
    }
  }

  const toggleTaskComplete = (taskId: string) => {
    setTasks(tasks.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const renderTripsTab = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Your Trips</h2>
        <button
          onClick={() => setShowNewTripForm(true)}
          className="px-4 py-2 bg-[rgb(34,139,34)] text-white rounded-lg font-medium text-sm shadow-md hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95"
          aria-label="Create new trip"
        >
          New Trip
        </button>
      </div>

      {showNewTripForm && (
        <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md">
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Create New Trip</h3>
          <div className="space-y-4">
            <input
              type="text"
              placeholder="Trip name"
              value={newTripData.name}
              onChange={(e) => setNewTripData({ ...newTripData, name: e.target.value })}
              className="w-full px-4 py-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
              aria-label="Trip name"
            />
            <input
              type="text"
              placeholder="Location"
              value={newTripData.location}
              onChange={(e) => setNewTripData({ ...newTripData, location: e.target.value })}
              className="w-full px-4 py-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
              aria-label="Trip location"
            />
            <div className="grid grid-cols-2 gap-4">
              <input
                type="date"
                value={newTripData.startDate}
                onChange={(e) => setNewTripData({ ...newTripData, startDate: e.target.value })}
                className="px-4 py-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                aria-label="Start date"
              />
              <input
                type="date"
                value={newTripData.endDate}
                onChange={(e) => setNewTripData({ ...newTripData, endDate: e.target.value })}
                className="px-4 py-3 border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150"
                aria-label="End date"
              />
            </div>
            <div className="flex gap-3">
              <button
                onClick={handleCreateTrip}
                className="flex-1 px-4 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium shadow-md hover:bg-[rgb(29,120,29)] transition-colors duration-150 active:scale-95"
                aria-label="Create trip"
              >
                Create Trip
              </button>
              <button
                onClick={() => setShowNewTripForm(false)}
                className="px-4 py-3 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-lg font-medium border border-[rgb(226,232,240)] hover:bg-[rgb(241,245,249)] transition-colors duration-150"
                aria-label="Cancel"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-3">
        {trips.map((trip) => (
          <div
            key={trip.id}
            onClick={() => setSelectedTrip(trip)}
            className={`bg-white border rounded-xl p-4 shadow-md cursor-pointer transition-all duration-200 ${
              selectedTrip?.id === trip.id 
                ? 'border-[rgb(34,139,34)] ring-2 ring-[rgb(34,139,34)]/20' 
                : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/50'
            }`}
            role="button"
            tabIndex={0}
            aria-label={`Select trip ${trip.name}`}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                setSelectedTrip(trip)
              }
            }}
          >
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <h3 className="font-semibold text-[rgb(15,23,42)] mb-1">{trip.name}</h3>
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-2">
                  <MapPin className="w-4 h-4" />
                  <span>{trip.location}</span>
                </div>
                <div className="flex items-center gap-4 text-sm text-gray-600">
                  <div className="flex items-center gap-1">
                    <Calendar className="w-4 h-4" />
                    <span>{new Date(trip.startDate).toLocaleDateString()}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Users className="w-4 h-4" />
                    <span>{trip.memberCount} members</span>
                  </div>
                </div>
              </div>
              <div className={`px-3 py-1 rounded-full text-xs font-medium ${
                trip.status === 'planning' 
                  ? 'bg-[rgb(245,158,11)]/20 text-[rgb(245,158,11)]' 
                  : trip.status === 'confirmed'
                  ? 'bg-[rgb(34,139,34)]/20 text-[rgb(34,139,34)]'
                  : 'bg-[rgb(241,245,249)] text-gray-600'
              }`}>
                {trip.status}
              </div>
            </div>
          </div>
        ))}
      </div>

      {selectedTrip && (
        <div className="bg-white border border-[rgb(226,232,240)] rounded-xl p-6 shadow-md">
          <h3 className="text-lg font-semibold text-[rgb(15,23,42)] mb-4">Weather Forecast</h3>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {selectedTrip.weatherForecast.map((weather, index) => (
              <div key={index} className="text-center p-3 bg-[rgb(248,250,252)] rounded-lg">
                <div className="text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  {new Date(weather.date).toLocaleDateString('en-US', { weekday: 'short' })}
                </div>
                <div className="flex justify-center mb-2">
                  {getWeatherIcon(weather.condition)}
                </div>
                <div className="text-xs text-gray-600">
                  {weather.high}°/{weather.low}°
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )

  const renderTasksTab = () => (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Trip Tasks</h2>
      <div className="space-y-3">
        {tasks.map((task) => (
          <div
            key={task.id}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-md"
          >
            <div className="flex items-start gap-3">
              <button
                onClick={() => toggleTaskComplete(task.id)}
                className={`mt-1 w-5 h-5 rounded border-2 flex items-center justify-center transition-colors duration-150 ${
                  task.completed
                    ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)]'
                    : 'border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]'
                }`}
                aria-label={`Mark task ${task.title} as ${task.completed ? 'incomplete' : 'complete'}`}
              >
                {task.completed && <CheckCircle className="w-3 h-3 text-white" />}
              </button>
              <div className="flex-1">
                <h3 className={`font-medium ${task.completed ? 'text-gray-500 line-through' : 'text-[rgb(15,23,42)]'}`}>
