'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageCircle, Utensils, CheckSquare, Cloud, Plus, Search, Filter, Bell, Settings, Home, Map, User } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  participants: Participant[]
  tasks: Task[]
  meals: Meal[]
  weather?: WeatherData
  status: 'planning' | 'confirmed' | 'active' | 'completed'
}

interface Participant {
  id: string
  name: string
  email: string
  avatar?: string
  rsvpStatus: 'pending' | 'accepted' | 'declined'
  assignedTasks: string[]
}

interface Task {
  id: string
  title: string
  description: string
  assignedTo?: string
  dueDate: string
  completed: boolean
  category: 'food' | 'equipment' | 'logistics' | 'safety'
}

interface Meal {
  id: string
  name: string
  date: string
  time: string
  assignedTo?: string
  ingredients: string[]
  servings: number
}

interface WeatherData {
  temperature: number
  condition: string
  humidity: number
  windSpeed: number
  forecast: Array<{
    date: string
    high: number
    low: number
    condition: string
  }>
}

interface Message {
  id: string
  sender: string
  content: string
  timestamp: string
  type: 'text' | 'image' | 'location'
}

interface OffRoadTripPlannerProps {
  initialTrips?: Trip[]
  currentUser?: Participant
  onTripCreate?: (trip: Omit<Trip, 'id'>) => void
  onTaskAssign?: (taskId: string, userId: string) => void
  onRsvpUpdate?: (tripId: string, userId: string, status: 'accepted' | 'declined') => void
}

export function OffRoadTripPlanner({
  initialTrips = DEFAULT_TRIPS,
  currentUser = DEFAULT_USER,
  onTripCreate = () => console.log('Trip created'),
  onTaskAssign = () => console.log('Task assigned'),
  onRsvpUpdate = () => console.log('RSVP updated')
}: OffRoadTripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState<'trips' | 'map' | 'chat' | 'profile'>('trips')
  const [trips, setTrips] = useState<Trip[]>(initialTrips)
  const [selectedTrip, setSelectedTrip] = useState<Trip | null>(null)
  const [showCreateTrip, setShowCreateTrip] = useState(false)
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [filterStatus, setFilterStatus] = useState<string>('all')

  const filteredTrips = trips.filter(trip => {
    const matchesSearch = trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         trip.location.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesFilter = filterStatus === 'all' || trip.status === filterStatus
    return matchesSearch && matchesFilter
  })

  const handleCreateTrip = (tripData: Omit<Trip, 'id'>) => {
    const newTrip: Trip = {
      ...tripData,
      id: Date.now().toString()
    }
    setTrips(prev => [...prev, newTrip])
    onTripCreate(tripData)
    setShowCreateTrip(false)
  }

  const handleRsvp = (tripId: string, status: 'accepted' | 'declined') => {
    setTrips(prev => prev.map(trip => {
      if (trip.id === tripId) {
        return {
          ...trip,
          participants: trip.participants.map(p => 
            p.id === currentUser.id ? { ...p, rsvpStatus: status } : p
          )
        }
      }
      return trip
    }))
    onRsvpUpdate(tripId, currentUser.id, status)
  }

  const handleTaskToggle = (tripId: string, taskId: string) => {
    setTrips(prev => prev.map(trip => {
      if (trip.id === tripId) {
        return {
          ...trip,
          tasks: trip.tasks.map(task => 
            task.id === taskId ? { ...task, completed: !task.completed } : task
          )
        }
      }
      return trip
    }))
  }

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Message = {
      id: Date.now().toString(),
      sender: currentUser.name,
      content: newMessage,
      timestamp: new Date().toISOString(),
      type: 'text'
    }

    setMessages(prev => [...prev, message])
    setNewMessage('')
  }

  const renderTripsTab = () => (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="bg-white border-b border-[rgb(226,232,240)] p-4">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Off-Road Trips</h1>
          <button
            onClick={() => setShowCreateTrip(true)}
            className="w-10 h-10 bg-[rgb(34,139,34)] text-white rounded-full flex items-center justify-center shadow-md hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 active:scale-95"
            aria-label="Create new trip"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        {/* Search and Filter */}
        <div className="flex gap-2 mb-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search trips..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
            />
          </div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-3 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
          >
            <option value="all">All Status</option>
            <option value="planning">Planning</option>
            <option value="confirmed">Confirmed</option>
            <option value="active">Active</option>
            <option value="completed">Completed</option>
          </select>
        </div>
      </div>

      {/* Trip List */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {filteredTrips.map(trip => (
          <div
            key={trip.id}
            onClick={() => setSelectedTrip(trip)}
            className="bg-white border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm hover:shadow-md transition-all duration-200 cursor-pointer active:scale-[0.98]"
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex-1">
                <h3 className="font-semibold text-[rgb(15,23,42)] mb-1">{trip.name}</h3>
                <div className="flex items-center text-sm text-gray-600 mb-2">
                  <MapPin className="w-4 h-4 mr-1" />
                  {trip.location}
                </div>
                <div className="flex items-center text-sm text-gray-600">
                  <Calendar className="w-4 h-4 mr-1" />
                  {new Date(trip.startDate).toLocaleDateString()} - {new Date(trip.endDate).toLocaleDateString()}
                </div>
              </div>
              <div className="flex flex-col items-end gap-2">
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  trip.status === 'planning' ? 'bg-yellow-100 text-yellow-700 border border-yellow-200' :
                  trip.status === 'confirmed' ? 'bg-blue-100 text-blue-700 border border-blue-200' :
                  trip.status === 'active' ? 'bg-green-100 text-green-700 border border-green-200' :
                  'bg-[rgb(241, 245, 249)] text-gray-700 border border-[rgb(226, 232, 240)]'
                }`}>
                  {trip.status}
                </span>
                {trip.weather && (
                  <div className="flex items-center text-xs text-gray-500">
                    <Cloud className="w-3 h-3 mr-1" />
                    {trip.weather.temperature}°F
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center">
                <Users className="w-4 h-4 mr-1 text-gray-400" />
                <span className="text-sm text-gray-600">{trip.participants.length} participants</span>
              </div>
              <div className="flex items-center gap-2">
                {trip.participants.find(p => p.id === currentUser.id)?.rsvpStatus === 'pending' && (
                  <div className="flex gap-1">
                    <button
                      onClick={(e) => {
                        e.stopPropagation()
                        handleRsvp(trip.id, 'accepted')
                      }}
                      className="px-3 py-1 bg-[rgb(34,139,34)] text-white rounded-md text-xs font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150"
                    >
                      Accept
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation()
                        handleRsvp(trip.id, 'declined')
                      }}
                      className="px-3 py-1 bg-[rgb(220,38,38)] text-white rounded-md text-xs font-medium hover:bg-[rgb(220,38,38)]/90 transition-colors duration-150"
                    >
                      Decline
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {filteredTrips.length === 0 && (
          <div className="text-center py-12">
            <MapPin className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-[rgb(15, 23, 42)] mb-2">No trips found</h3>
            <p className="text-gray-500 mb-4">Start planning your next off-road adventure!</p>
            <button
              onClick={() => setShowCreateTrip(true)}
              className="px-6 py-3 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 shadow-md hover:shadow-lg active:scale-95"
            >
              Create Your First Trip
            </button>
          </div>
        )}
      </div>
    </div>
  )

  const renderTripDetails = () => {
    if (!selectedTrip) return null

    return (
      <div className="flex flex-col h-full">
        {/* Header */}
        <div className="bg-white border-b border-[rgb(226,232,240)] p-4">
          <div className="flex items-center justify-between mb-2">
            <button
              onClick={() => setSelectedTrip(null)}
              className="text-[rgb(34,139,34)] font-medium"
            >
              ← Back
            </button>
            <button className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-gray-600">
              <Settings className="w-5 h-5" />
            </button>
          </div>
          <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">{selectedTrip.name}</h1>
          <p className="text-gray-600">{selectedTrip.location}</p>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto">
          {/* Weather */}
          {selectedTrip.weather && (
            <div className="p-4 border-b border-[rgb(226,232,240)]">
              <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Weather Forecast</h3>
              <div className="bg-[rgb(248,250,252)] rounded-lg p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center">
                    <Cloud className="w-6 h-6 text-[rgb(34,139,34)] mr-2" />
                    <span className="font-medium">{selectedTrip.weather.condition}</span>
                  </div>
                  <span className="text-2xl font-bold">{selectedTrip.weather.temperature}°F</span>
                </div>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>Humidity: {selectedTrip.weather.humidity}%</div>
                  <div>Wind: {selectedTrip.weather.windSpeed} mph</div>
                </div>
              </div>
            </div>
          )}

          {/* Tasks */}
          <div className="p-4 border-b border-[rgb(226,232,240)]">
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Tasks & Assignments</h3>
            <div className="space-y-2">
              {selectedTrip.tasks.map(task => (
                <div key={task.id} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg">
                  <div className="flex items-center flex-1">
                    <button
                      onClick={() => handleTaskToggle(selectedTrip.id, task.id)}
                      className={`w-5 h-5 rounded border-2 mr-3 flex items-center justify-center transition-colors duration-150 ${
                        task.completed 
                          ? 'bg-[rgb(34,139,34)] border-[rgb(34,139,34)] text-white' 
                          : 'border-gray-300 hover:border-[rgb(34,139,34)]'
                      }`}
                    >
                      {task.completed && <CheckSquare className="w-3 h-3" />}
                    </button>
                    <div className="flex-1">
                      <div className={`font-medium ${task.completed ? 'line-through text-gray-500' : 'text-[rgb(15,23,42)]'}`}>
                        {task.title}
                      </div>
                      {task.assignedTo && (
                        <div className="text-sm text-gray-600">
                          Assigned to: {selectedTrip.participants.find(p => p.id === task.assignedTo)?.name}
                        </div>
                      )}
                    </div>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                    task.category === 'food' ? 'bg-orange-100 text-orange-700' :
                    task.category === 'equipment' ? 'bg-blue-100 text-blue-700' :
                    task.category === 'logistics' ? 'bg-purple-100 text-purple-700' :
                    'bg-red-100 text-red-700'
                  }`}>
                    {task.category}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Meals */}
          <div className="p-4 border-b border-[rgb(226,232,240)]">
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Meal Plan</h3>
            <div className="space-y-3">
              {selectedTrip.meals.map(meal => (
                <div key={meal.id} className="p-3 bg-[rgb(248,250,252)] rounded-lg">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center">
                      <Utensils className="w-4 h-4 text-[rgb(245,158,11)] mr-2" />
                      <span className="font-medium text-[rgb(15,23,42)]">{meal.name}</span>
                    </div>
                    <span className="text-sm text-gray-600">{meal.servings} servings</span>
                  </div>
                  <div className="text-sm text-gray-600 mb-1">
                    {new Date(meal.date).toLocaleDateString()} at {meal.time}
                  </div>
                  {meal.assignedTo && (
                    <div className="text-sm text-gray-600">
                      Prepared by: {selectedTrip.participants.find(p => p.id === meal.assignedTo)?.name}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Participants */}
          <div className="p-4">
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Participants</h3>
            <div className="space-y-2">
              {selectedTrip.participants.map(participant => (
                <div key={participant.id} className="flex items-center justify-between p-3 bg-[rgb(248,250,252)] rounded-lg">
                  <div className="flex items-center">
                    <div className="w-8 h-8 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-medium text-sm mr-3">
                      {participant.name.charAt(0)}
                    </div>
                    <div>
                      <div className="font-medium text-[rgb(15,23,42)]">{participant.name}</div>
                      <div className="text-sm text-gray-600">{participant.email}</div>
                    </div>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                    participant.rsvpStatus === 'accepted' ? 'bg-green-100 text-green-700' :
                    participant.rsvpStatus === 'declined' ? 'bg-red-100 text-red-700' :
                    'bg-yellow-100 text-yellow-700'
                  }`}>
                    {participant.rsvpStatus}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  }

  const renderChatTab = () => (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="bg-white border-b border-[rgb(226,232,240)] p-4">
        <h1 className="text-xl font-semibold text-[rgb(15,23,42)]">Group Chat</h1>
        <p className="text-sm text-gray-600">Stay connected with your adventure crew</p>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {messages.map(message => (
          <div
            key={message.id}
            className={`flex ${message.sender === currentUser.name ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[80%] p-3 rounded-lg ${
              message.sender === currentUser.name
                ? 'bg-[rgb(34,139,34)] text-white'
                : 'bg-[rgb(248,250,252)] text-[rgb(15,23,42)]'
            }`}>
              {message.sender !== currentUser.name && (
                <div className="text-xs font-medium mb-1 opacity-70">{message.sender}</div>
              )}
              <div className="text-sm">{message.content}</div>
              <div className={`text-xs mt-1 opacity-70`}>
                {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Message Input */}
      <div className="bg-white border-t border-[rgb(226,232,240)] p-4">
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="Type a message..."
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
            className="flex-1 px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
          />
          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="px-4 py-2.5 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg active:scale-95"
          >
            Send
          </button>
        </div>
      </div>
    </div>
  )

  const renderCreateTripModal = () => {
    if (!showCreateTrip) return null

    return (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
        <div className="bg-white rounded-xl max-w-md w-full max-h-[90vh] overflow-y-auto">
          <div className="p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-semibold text-[rgb(15,23,42)]">Create New Trip</h2>
              <button
                onClick={() => setShowCreateTrip(false)}
                className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-gray-600 rounded-full hover:bg-[rgb(241, 245, 249)]"
              >
                ×
              </button>
            </div>

            <form
              onSubmit={(e) => {
                e.preventDefault()
                const formData = new FormData(e.currentTarget)
                handleCreateTrip({
                  name: formData.get('name') as string,
                  location: formData.get('location') as string,
                  startDate: formData.get('startDate') as string,
                  endDate: formData.get('endDate') as string,
                  participants: [currentUser],
                  tasks: [],
                  meals: [],
                  status: 'planning'
                })
              }}
              className="space-y-4"
            >
              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">Trip Name</label>
                <input
                  name="name"
                  type="text"
                  required
                  placeholder="e.g., Moab Desert Adventure"
                  className="w-full px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">Location</label>
                <input
                  name="location"
                  type="text"
                  required
                  placeholder="e.g., Moab, Utah"
                  className="w-full px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-gray-400 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">Start Date</label>
                  <input
                    name="startDate"
                    type="date"
                    required
                    className="w-full px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[rgb(15,23,42)] mb-2">End Date</label>
                  <input
                    name="endDate"
                    type="date"
                    required
                    className="w-full px-4 py-2.5 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
                  />
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowCreateTrip(false)}
                  className="flex-1 px-4 py-2.5 bg-[rgb(248,250,252)] text-[rgb(15,23,42)] rounded-lg font-medium hover:bg-gray-200 transition-colors duration-150 border border-[rgb(226,232,240)]"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-2.5 bg-[rgb(34,139,34)] text-white rounded-lg font-medium hover:bg-[rgb(34,139,34)]/90 transition-colors duration-150 shadow-md hover:shadow-lg active:scale-95"
                >
                  Create Trip
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[rgb(241,245,249)] font-medium">
      {/* Main Content */}
      <div className="pb-16">
        {selectedTrip ? renderTripDetails() : 
         activeTab === 'trips' ? renderTripsTab() :
         activeTab === 'chat' ? renderChatTab() :
         activeTab === 'map' ? (
           <div className="flex items-center justify-center h-screen">
             <div className="text-center">
               <Map className="w-16 h-16 text-gray-300 mx-auto mb-4" />
               <h3 className="text-lg font-medium text-[rgb(15, 23, 42)] mb-2">Interactive Map</h3>
               <p className="text-gray-500">Explore off-road trails and save locations</p>
             </div>
           </div>
         ) : (
           <div className="flex items-center justify-center h-screen">
             <div className="text-center">
               <User className="w-16 h-16 text-gray-300 mx-auto mb-4" />
               <h3 className="text-lg font-medium text-[rgb(15, 23, 42)] mb-2">User Profile</h3>
               <p className="text-gray-500">Manage your account and preferences</p>
             </div>
           </div>
         )}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-[rgb(226,232,240)] px-4 py-2">
        <div className="flex items-center justify-around">
          {[
            { id: 'trips', icon: Home, label: 'Trips' },
            { id: 'map', icon: Map, label: 'Map' },
            { id: 'chat', icon: MessageCircle, label: 'Chat' },
            { id: 'profile', icon: User, label: 'Profile' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => {
                setActiveTab(tab.id as any)
                setSelectedTrip(null)
              }}
              className={`flex flex-col items-center py-2 px-3 rounded-lg transition-colors duration-150 min-h-[44px] min-w-[44px] ${
                activeTab === tab.id
                  ? 'text-[rgb(34,139,34)] bg-[rgb(34,139,34)]/10'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
              aria-label={tab.label}
            >
              <tab.icon className="w-5 h-5 mb-1" />
              <span className="text-xs font-medium">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Modals */}
      {renderCreateTripModal()}
    </div>
  )
}

