'use client'

import { useState, useEffect } from 'react'
import { MapPin, Users, Calendar, MessageCircle, CheckCircle, Settings, Plus, Search, Filter } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  memberCount: number
  status: 'planning' | 'confirmed' | 'completed'
  image: string
}

interface TripPlannerProps {
  trips?: Trip[]
  onCreateTrip?: () => void
  onViewTrip?: (tripId: string) => void
}

export function TripPlanner({
  trips = DEFAULT_TRIPS,
  onCreateTrip = () => console.log('Create trip'),
  onViewTrip = (tripId: string) => console.log('View trip:', tripId)
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState<'trips' | 'locations' | 'chat' | 'profile'>('trips')
  const [searchQuery, setSearchQuery] = useState('')
  const [filterStatus, setFilterStatus] = useState<'all' | 'planning' | 'confirmed' | 'completed'>('all')

  const filteredTrips = trips.filter(trip => {
    const matchesSearch = trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         trip.location.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesFilter = filterStatus === 'all' || trip.status === filterStatus
    return matchesSearch && matchesFilter
  })

  const getStatusColor = (status: Trip['status']) => {
    switch (status) {
      case 'planning': return 'bg-[rgb(245,158,11)]/20 text-[rgb(245,158,11)] border-[rgb(245,158,11)]/30'
      case 'confirmed': return 'bg-[rgb(34,139,34)]/20 text-[rgb(34,139,34)] border-[rgb(34,139,34)]/30'
      case 'completed': return 'bg-[rgb(226,232,240)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
      default: return 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] border-[rgb(226,232,240)]'
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric' 
    })
  }

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      {/* Header */}
      <div className="bg-[rgb(255,255,255)] border-b border-[rgb(226,232,240)] px-4 py-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[rgb(15,23,42)]">Trail Planner</h1>
            <p className="text-sm text-[rgb(15,23,42)]/60">Plan your next adventure</p>
          </div>
          <button
            onClick={onCreateTrip}
            className="w-11 h-11 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-xl flex items-center justify-center shadow-md hover:bg-[rgb(34,139,34)]/90 transition-all duration-150 active:scale-95"
            aria-label="Create new trip"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Search and Filter */}
      {activeTab === 'trips' && (
        <div className="px-4 py-4 bg-[rgb(248,250,252)] border-b border-[rgb(226,232,240)]">
          <div className="flex gap-3">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(15,23,42)]/40" />
              <input
                type="text"
                placeholder="Search trips or locations..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-3 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)]/40 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-1 focus:ring-[rgb(34,139,34)]/50 transition-all duration-150"
              />
            </div>
            <button
              className="w-12 h-12 bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl flex items-center justify-center hover:border-[rgb(34,139,34)]/50 transition-all duration-150"
              aria-label="Filter trips"
            >
              <Filter className="w-4 h-4 text-[rgb(15,23,42)]/60" />
            </button>
          </div>

          {/* Status Filter Pills */}
          <div className="flex gap-2 mt-3 overflow-x-auto pb-1">
            {(['all', 'planning', 'confirmed', 'completed'] as const).map((status) => (
              <button
                key={status}
                onClick={() => setFilterStatus(status)}
                className={`px-4 py-2 rounded-full text-xs font-medium whitespace-nowrap transition-all duration-150 ${
                  filterStatus === status
                    ? 'bg-[rgb(34,139,34)] text-[rgb(255,255,255)] shadow-md'
                    : 'bg-[rgb(255,255,255)] text-[rgb(15,23,42)]/60 border border-[rgb(226,232,240)] hover:border-[rgb(34,139,34)]/30'
                }`}
              >
                {status.charAt(0).toUpperCase() + status.slice(1)}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Main Content */}
      <div className="flex-1 pb-20">
        {activeTab === 'trips' && (
          <div className="px-4 py-4">
            <div className="space-y-4">
              {filteredTrips.map((trip) => (
                <div
                  key={trip.id}
                  onClick={() => onViewTrip(trip.id)}
                  className="bg-[rgb(255,255,255)] border border-[rgb(226,232,240)] rounded-xl p-4 shadow-sm hover:shadow-md hover:border-[rgb(34,139,34)]/30 transition-all duration-200 cursor-pointer active:scale-[0.98]"
                >
                  <div className="flex items-start gap-4">
                    <div className="w-16 h-16 bg-gradient-to-br from-[rgb(34,139,34)]/20 to-[rgb(245,158,11)]/20 rounded-xl flex items-center justify-center flex-shrink-0">
                      <MapPin className="w-6 h-6 text-[rgb(34,139,34)]" />
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div>
                          <h3 className="font-semibold text-[rgb(15,23,42)] truncate">{trip.name}</h3>
                          <p className="text-sm text-[rgb(15,23,42)]/60 truncate">{trip.location}</p>
                        </div>
                        <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(trip.status)}`}>
                          {trip.status}
                        </span>
                      </div>

                      <div className="flex items-center gap-4 mt-3">
                        <div className="flex items-center gap-1">
                          <Calendar className="w-4 h-4 text-[rgb(15,23,42)]/40" />
                          <span className="text-xs text-[rgb(15,23,42)]/60">
                            {formatDate(trip.startDate)} - {formatDate(trip.endDate)}
                          </span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Users className="w-4 h-4 text-[rgb(15,23,42)]/40" />
                          <span className="text-xs text-[rgb(15,23,42)]/60">
                            {trip.memberCount} members
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ))}

              {filteredTrips.length === 0 && (
                <div className="text-center py-12">
                  <MapPin className="w-12 h-12 text-[rgb(15,23,42)]/20 mx-auto mb-4" />
                  <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">No trips found</h3>
                  <p className="text-sm text-[rgb(15,23,42)]/60 mb-6">
                    {searchQuery ? 'Try adjusting your search terms' : 'Create your first off-road adventure'}
                  </p>
                  <button
                    onClick={onCreateTrip}
                    className="px-6 py-3 bg-[rgb(34,139,34)] text-[rgb(255,255,255)] rounded-xl font-medium shadow-md hover:bg-[rgb(34,139,34)]/90 transition-all duration-150 active:scale-95"
                  >
                    Plan New Trip
                  </button>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'locations' && (
          <div className="px-4 py-8 text-center">
            <MapPin className="w-12 h-12 text-[rgb(15,23,42)]/20 mx-auto mb-4" />
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">Saved Locations</h3>
            <p className="text-sm text-[rgb(15,23,42)]/60">Your favorite off-road destinations</p>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="px-4 py-8 text-center">
            <MessageCircle className="w-12 h-12 text-[rgb(15,23,42)]/20 mx-auto mb-4" />
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">Group Chat</h3>
            <p className="text-sm text-[rgb(15,23,42)]/60">Coordinate with your adventure crew</p>
          </div>
        )}

        {activeTab === 'profile' && (
          <div className="px-4 py-8 text-center">
            <Settings className="w-12 h-12 text-[rgb(15,23,42)]/20 mx-auto mb-4" />
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-2">Profile & Settings</h3>
            <p className="text-sm text-[rgb(15,23,42)]/60">Manage your account and preferences</p>
          </div>
        )}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-[rgb(255,255,255)] border-t border-[rgb(226,232,240)] px-4 py-2">
        <div className="flex items-center justify-around">
          {[
            { id: 'trips', icon: MapPin, label: 'Trips' },
            { id: 'locations', icon: CheckCircle, label: 'Locations' },
            { id: 'chat', icon: MessageCircle, label: 'Chat' },
            { id: 'profile', icon: Settings, label: 'Profile' }
          ].map(({ id, icon: Icon, label }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex flex-col items-center gap-1 py-2 px-3 rounded-lg transition-all duration-150 min-w-[44px] ${
                activeTab === id
                  ? 'text-[rgb(34,139,34)]'
                  : 'text-[rgb(15,23,42)]/40 hover:text-[rgb(15,23,42)]/60'
              }`}
              aria-label={label}
            >
              <Icon className="w-5 h-5" />
              <span className="text-xs font-medium">{label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

const DEFAULT_TRIPS: Trip[] = [
  {
    id: '1',
