'use client'

import { useState } from 'react'
import { Send, UserPlus, Calendar, MapPin, Clock, Check, X, Mail, Phone } from 'lucide-react'

interface Member {
  id: string
  name: string
  email: string
  phone?: string
  avatar?: string
  status: 'pending' | 'accepted' | 'declined'
  invitedAt: Date
  respondedAt?: Date
}

interface Trip {
  id: string
  name: string
  location: string
  startDate: Date
  endDate: Date
  description: string
}

interface MemberInvitationProps {
  trip?: Trip
  members?: Member[]
  onInviteMember?: (email: string, phone?: string) => void
  onResendInvite?: (memberId: string) => void
  onRemoveMember?: (memberId: string) => void
}

export function MemberInvitation({
  trip = DEFAULT_TRIP,
  members = DEFAULT_MEMBERS,
  onInviteMember = () => console.log('Invite member'),
  onResendInvite = () => console.log('Resend invite'),
  onRemoveMember = () => console.log('Remove member')
}: MemberInvitationProps = {}) {
  const [email, setEmail] = useState('')
  const [phone, setPhone] = useState('')
  const [isInviting, setIsInviting] = useState(false)
  const [showInviteForm, setShowInviteForm] = useState(false)

  const handleInvite = async () => {
    if (!email.trim()) return

    setIsInviting(true)
    try {
      await onInviteMember(email.trim(), phone.trim() || undefined)
      setEmail('')
      setPhone('')
      setShowInviteForm(false)
    } catch (error) {
      console.error('Failed to invite member:', error)
    } finally {
      setIsInviting(false)
    }
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    })
  }

  const getStatusColor = (status: Member['status']) => {
    switch (status) {
      case 'accepted':
        return 'bg-[rgb(34,139,34)] text-white'
      case 'declined':
        return 'bg-[rgb(220,38,38)] text-white'
      default:
        return 'bg-[rgb(245,158,11)] text-white'
    }
  }

  const getStatusIcon = (status: Member['status']) => {
    switch (status) {
      case 'accepted':
        return <Check className="w-3 h-3" />
      case 'declined':
        return <X className="w-3 h-3" />
      default:
        return <Clock className="w-3 h-3" />
    }
  }

  const pendingCount = members.filter(m => m.status === 'pending').length
  const acceptedCount = members.filter(m => m.status === 'accepted').length

  return (
    <div className="min-h-screen bg-[rgb(255,255,255)] font-medium">
      <div className="max-w-md mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-[rgb(15,23,42)] mb-2">
            Trip Invitations
          </h1>
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)]">
            <div className="flex items-center gap-2 mb-2">
              <MapPin className="w-4 h-4 text-[rgb(34,139,34)]" />
              <span className="font-semibold text-[rgb(15,23,42)]">{trip.name}</span>
            </div>
            <div className="flex items-center gap-2 text-sm text-[rgb(15,23,42)]">
              <Calendar className="w-4 h-4" />
              <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
            </div>
            <p className="text-sm text-[rgb(15,23,42)] mt-2 opacity-75">
              {trip.description}
            </p>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 gap-3 mb-6">
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 text-center border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(34,139,34)]">{acceptedCount}</div>
            <div className="text-sm text-[rgb(15,23,42)] opacity-75">Confirmed</div>
          </div>
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 text-center border border-[rgb(226,232,240)]">
            <div className="text-2xl font-bold text-[rgb(245,158,11)]">{pendingCount}</div>
            <div className="text-sm text-[rgb(15,23,42)] opacity-75">Pending</div>
          </div>
        </div>

        {/* Invite Button */}
        {!showInviteForm && (
          <button
            onClick={() => setShowInviteForm(true)}
            className="w-full bg-[rgb(34,139,34)] text-white rounded-lg p-4 flex items-center justify-center gap-2 font-semibold shadow-md hover:shadow-lg active:scale-95 transition-all duration-150 mb-6"
            aria-label="Invite new member"
          >
            <UserPlus className="w-5 h-5" />
            Invite Member
          </button>
        )}

        {/* Invite Form */}
        {showInviteForm && (
          <div className="bg-[rgb(248,250,252)] rounded-lg p-4 border border-[rgb(226,232,240)] mb-6">
            <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">Invite New Member</h3>

            <div className="space-y-3">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Email Address *
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(15,23,42)] opacity-50" />
                  <input
                    id="email"
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="member@example.com"
                    className="w-full pl-10 pr-4 py-3 bg-white border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)] placeholder-opacity-50 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-opacity-20 transition-all duration-150"
                    required
                  />
                </div>
              </div>

              <div>
                <label htmlFor="phone" className="block text-sm font-medium text-[rgb(15,23,42)] mb-1">
                  Phone Number (Optional)
                </label>
                <div className="relative">
                  <Phone className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[rgb(15,23,42)] opacity-50" />
                  <input
                    id="phone"
                    type="tel"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder="(555) 123-4567"
                    className="w-full pl-10 pr-4 py-3 bg-white border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] placeholder-[rgb(15,23,42)] placeholder-opacity-50 focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)] focus:ring-opacity-20 transition-all duration-150"
                  />
                </div>
              </div>

              <div className="flex gap-2 pt-2">
                <button
                  onClick={handleInvite}
                  disabled={!email.trim() || isInviting}
                  className="flex-1 bg-[rgb(34,139,34)] text-white rounded-lg py-3 px-4 flex items-center justify-center gap-2 font-semibold disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg active:scale-95 transition-all duration-150"
                  aria-label="Send invitation"
                >
                  {isInviting ? (
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  ) : (
                    <Send className="w-4 h-4" />
                  )}
                  {isInviting ? 'Sending...' : 'Send Invite'}
                </button>
                <button
                  onClick={() => {
                    setShowInviteForm(false)
                    setEmail('')
                    setPhone('')
                  }}
                  className="px-4 py-3 bg-white border border-[rgb(226,232,240)] rounded-lg text-[rgb(15,23,42)] font-semibold hover:bg-[rgb(248,250,252)] active:scale-95 transition-all duration-150"
                  aria-label="Cancel invitation"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Members List */}
        <div className="space-y-3">
          <h3 className="font-semibold text-[rgb(15,23,42)] mb-3">
            Invited Members ({members.length})
          </h3>

          {members.length === 0 ? (
            <div className="text-center py-8 text-[rgb(15,23,42)] opacity-75">
              <UserPlus className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>No members invited yet</p>
              <p className="text-sm">Start by inviting your adventure crew!</p>
            </div>
          ) : (
            members.map((member) => (
              <div
                key={member.id}
                className="bg-white rounded-lg p-4 border border-[rgb(226,232,240)] shadow-sm"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="w-10 h-10 bg-[rgb(34,139,34)] rounded-full flex items-center justify-center text-white font-semibold">
                      {member.name.charAt(0).toUpperCase()}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-[rgb(15,23,42)] truncate">
                        {member.name}
                      </div>
                      <div className="text-sm text-[rgb(15,23,42)] opacity-75 truncate">
                        {member.email}
                      </div>
                      {member.phone && (
                        <div className="text-sm text-[rgb(15,23,42)] opacity-75">
                          {member.phone}
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className={`px-2 py-1 rounded-full text-xs font-semibold flex items-center gap-1 ${getStatusColor(member.status)}`}>
                      {getStatusIcon(member.status)}
                      {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                    </span>
                  </div>
                </div>

                <div className="mt-3 flex items-center justify-between text-xs text-[rgb(15,23,42)] opacity-75">
                  <span>
                    Invited {formatDate(member.invitedAt)}
                  </span>
                  {member.status === 'pending' && (
                    <button
                      onClick={() => onResendInvite(member.id)}
                      className="text-[rgb(34,139,34)] hover:underline font-medium"
                      aria-label={`Resend invitation to ${member.name}`}
                    >
                      Resend
                    </button>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

