'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, CheckCircle, AlertCircle, RefreshCw, Plus, X } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  source: 'google' | 'outlook' | 'apple'
  conflicted?: boolean
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  calendarsConnected: string[]
}

interface CalendarSyncProps {
  tripId?: string
  tripDates?: { start: Date; end: Date }
  groupMembers?: GroupMember[]
  onScheduleConflict?: (conflicts: CalendarEvent[]) => void
  onInvitesSent?: (memberIds: string[]) => void
}

export function CalendarSync({
  tripId = 'trip-1',
  tripDates = {
    start: new Date('2024-03-15'),
    end: new Date('2024-03-17')
  },
  groupMembers = DEFAULT_GROUP_MEMBERS,
  onScheduleConflict = () => console.log('Schedule conflict detected'),
  onInvitesSent = () => console.log('Invites sent')
}: CalendarSyncProps = {}) {
  const [connectedCalendars, setConnectedCalendars] = useState<string[]>(['google'])
  const [isLoading, setIsLoading] = useState(false)
  const [conflicts, setConflicts] = useState<CalendarEvent[]>([])
  const [selectedMembers, setSelectedMembers] = useState<string[]>(groupMembers.map(m => m.id))
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [invitesSent, setInvitesSent] = useState(false)

  const handleConnectCalendar = async (provider: string) => {
    setIsLoading(true)
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500))
    setConnectedCalendars(prev => [...prev, provider])
    setIsLoading(false)
  }

  const handleCheckConflicts = async () => {
    setIsLoading(true)
    // Simulate conflict checking
    await new Promise(resolve => setTimeout(resolve, 2000))

    const mockConflicts: CalendarEvent[] = [
      {
        id: '1',
        title: 'Work Meeting',
        start: new Date('2024-03-15T14:00:00'),
        end: new Date('2024-03-15T15:00:00'),
        attendees: ['john@example.com'],
        source: 'google',
        conflicted: true
      }
    ]

    setConflicts(mockConflicts)
    onScheduleConflict(mockConflicts)
    setIsLoading(false)
  }

  const handleSendInvites = async () => {
    setIsLoading(true)
    // Simulate sending invites
    await new Promise(resolve => setTimeout(resolve, 1500))
    setInvitesSent(true)
    setShowInviteModal(false)
    onInvitesSent(selectedMembers)
    setIsLoading(false)
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    })
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-md mx-auto p-4 space-y-6">
        {/* Header */}
        <div className="text-center space-y-2">
          <div className="w-12 h-12 bg-[#228b22] rounded-xl flex items-center justify-center mx-auto">
            <Calendar className="w-6 h-6 text-[#ffffff]" />
          </div>
          <h1 className="text-2xl font-bold text-[#0f172a]">Calendar Sync</h1>
          <p className="text-sm text-gray-600">
            Connect calendars and check availability for your trip
          </p>
        </div>

        {/* Trip Dates */}
        <div className="bg-[#f8fafc] rounded-xl p-4 border border-[#e2e8f0]">
          <div className="flex items-center gap-3 mb-3">
            <Clock className="w-5 h-5 text-[#228b22]" />
            <h2 className="font-semibold text-[#0f172a]">Trip Dates</h2>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm text-gray-600">
              {formatDate(tripDates.start)} - {formatDate(tripDates.end)}
            </span>
            <span className="px-2 py-1 bg-[#228b22] text-[#ffffff] rounded-full text-xs">
              3 days
            </span>
          </div>
        </div>

        {/* Connected Calendars */}
        <div className="space-y-4">
          <h2 className="font-semibold text-[#0f172a] flex items-center gap-2">
            <Calendar className="w-5 h-5" />
            Connected Calendars
          </h2>

          <div className="space-y-3">
            {['google', 'outlook', 'apple'].map((provider) => (
              <div
                key={provider}
                className="flex items-center justify-between p-4 bg-white border border-[#e2e8f0] rounded-xl"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                    provider === 'google' ? 'bg-red-100' :
                    provider === 'outlook' ? 'bg-blue-100' : 'bg-[rgb(241, 245, 249)]'
                  }`}>
                    <Calendar className={`w-4 h-4 ${
                      provider === 'google' ? 'text-[rgb(255, 255, 255)]' :
                      provider === 'outlook' ? 'text-[rgb(34, 139, 34)]' : 'text-gray-600'
                    }`} />
                  </div>
                  <span className="font-medium text-[#0f172a] capitalize">
                    {provider} Calendar
                  </span>
                </div>

                {connectedCalendars.includes(provider) ? (
                  <CheckCircle className="w-5 h-5 text-[#228b22]" />
                ) : (
                  <button
                    onClick={() => handleConnectCalendar(provider)}
                    disabled={isLoading}
                    className="px-3 py-1.5 bg-[#228b22] text-[#ffffff] rounded-lg text-sm font-medium hover:bg-[#1e7b1e] transition-colors disabled:opacity-50"
                    style={{ minHeight: '44px', minWidth: '44px' }}
                  >
                    Connect
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Check Conflicts */}
        <div className="space-y-4">
          <button
            onClick={handleCheckConflicts}
            disabled={isLoading || connectedCalendars.length === 0}
            className="w-full p-4 bg-[#f59e0b] text-[#ffffff] rounded-xl font-semibold flex items-center justify-center gap-2 hover:bg-[#d97706] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            style={{ minHeight: '44px' }}
          >
            {isLoading ? (
              <RefreshCw className="w-5 h-5 animate-spin" />
            ) : (
              <AlertCircle className="w-5 h-5" />
            )}
            Check Schedule Conflicts
          </button>

          {conflicts.length > 0 && (
            <div className="bg-red-50 border border-red-200 rounded-xl p-4">
              <h3 className="font-semibold text-red-800 mb-2 flex items-center gap-2">
                <AlertCircle className="w-4 h-4" />
                Conflicts Found
              </h3>
              <div className="space-y-2">
                {conflicts.map((conflict) => (
                  <div key={conflict.id} className="text-sm text-red-700">
                    <div className="font-medium">{conflict.title}</div>
                    <div className="text-xs">
                      {conflict.start.toLocaleTimeString()} - {conflict.end.toLocaleTimeString()}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Group Members */}
        <div className="space-y-4">
          <h2 className="font-semibold text-[#0f172a] flex items-center gap-2">
            <Users className="w-5 h-5" />
            Group Members ({groupMembers.length})
          </h2>

          <div className="space-y-2">
            {groupMembers.map((member) => (
              <div
                key={member.id}
                className="flex items-center justify-between p-3 bg-white border border-[#e2e8f0] rounded-lg"
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 bg-[#228b22] rounded-full flex items-center justify-center">
                    <span className="text-[#ffffff] text-sm font-semibold">
                      {member.name.charAt(0)}
                    </span>
                  </div>
                  <div>
                    <div className="font-medium text-[#0f172a] text-sm">{member.name}</div>
                    <div className="text-xs text-gray-500">{member.email}</div>
                  </div>
                </div>

                <div className="flex items-center gap-1">
                  {member.calendarsConnected.map((cal) => (
                    <div
                      key={cal}
                      className="w-2 h-2 bg-[#228b22] rounded-full"
                      title={`${cal} connected`}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Send Invites */}
        <div className="space-y-4">
          <button
            onClick={() => setShowInviteModal(true)}
            disabled={isLoading || invitesSent}
            className="w-full p-4 bg-[#228b22] text-[#ffffff] rounded-xl font-semibold flex items-center justify-center gap-2 hover:bg-[#1e7b1e] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            style={{ minHeight: '44px' }}
          >
            {invitesSent ? (
              <CheckCircle className="w-5 h-5" />
            ) : (
              <Plus className="w-5 h-5" />
            )}
            {invitesSent ? 'Invites Sent' : 'Send Calendar Invites'}
          </button>

          {invitesSent && (
            <div className="bg-green-50 border border-green-200 rounded-xl p-4">
              <div className="flex items-center gap-2 text-green-800">
                <CheckCircle className="w-4 h-4" />
                <span className="font-medium text-sm">
                  Calendar invites sent to {selectedMembers.length} members
                </span>
              </div>
            </div>
          )}
        </div>

        {/* Invite Modal */}
        {showInviteModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl p-6 w-full max-w-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-semibold text-[#0f172a]">Send Invites</h3>
                <button
                  onClick={() => setShowInviteModal(false)}
                  className="p-1 hover:bg-[rgb(241, 245, 249)] rounded"
                  style={{ minHeight: '44px', minWidth: '44px' }}
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-3 mb-6">
                {groupMembers.map((member) => (
                  <label
                    key={member.id}
                    className="flex items-center gap-3 p-2 hover:bg-[rgb(255, 255, 255)] rounded cursor-pointer"
                  >
                    <input
                      type="checkbox"
                      checked={selectedMembers.includes(member.id)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedMembers(prev => [...prev, member.id])
                        } else {
                          setSelectedMembers(prev => prev.filter(id => id !== member.id))
                        }
                      }}
                      className="w-4 h-4 text-[#228b22] rounded"
                    />
                    <span className="text-sm font-medium">{member.name}</span>
                  </label>
                ))}
              </div>

              <button
                onClick={handleSendInvites}
                disabled={isLoading || selectedMembers.length === 0}
                className="w-full p-3 bg-[#228b22] text-[#ffffff] rounded-lg font-semibold hover:bg-[#1e7b1e] transition-colors disabled:opacity-50"
                style={{ minHeight: '44px' }}
              >
                {isLoading ? (
                  <RefreshCw className="w-5 h-5 animate-spin mx-auto" />
                ) : (
                  `Send to ${selectedMembers.length} members`
                )}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

