'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, MoreVertical, Users, MapPin, Calendar, Utensils } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'system' | 'location' | 'task' | 'meal'
  metadata?: {
    location?: string
    taskName?: string
    assignee?: string
    mealType?: string
    date?: string
  }
}

interface GroupChatProps {
  tripId?: string
  messages?: Message[]
  currentUserId?: string
  onSendMessage?: (content: string, type?: string) => void
  onMessageAction?: (messageId: string, action: string) => void
}

export function GroupChat({
  tripId = 'trip-1',
  messages = DEFAULT_MESSAGES,
  currentUserId = 'user-1',
  onSendMessage = (content: string) => console.log('Send message:', content),
  onMessageAction = (messageId: string, action: string) => console.log('Message action:', messageId, action)
}: GroupChatProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [chatMessages, setChatMessages] = useState<Message[]>(messages)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [chatMessages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Message = {
      id: `msg-${Date.now()}`,
      userId: currentUserId,
      userName: 'You',
      userAvatar: '/api/placeholder/32/32',
      content: newMessage.trim(),
      timestamp: new Date(),
      type: 'text'
    }

    setChatMessages(prev => [...prev, message])
    onSendMessage(newMessage.trim())
    setNewMessage('')

    // Simulate typing indicator
    setIsTyping(true)
    setTimeout(() => setIsTyping(false), 2000)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const renderMessage = (message: Message, index: number) => {
    const isCurrentUser = message.userId === currentUserId
    const showDate = index === 0 || 
      formatDate(message.timestamp) !== formatDate(chatMessages[index - 1]?.timestamp)

    return (
      <div key={message.id} className="space-y-2">
        {showDate && (
          <div className="flex justify-center py-2">
            <span className="px-3 py-1 text-xs font-medium text-[rgb(100,116,139)] bg-[rgb(241,245,249)] rounded-full">
              {formatDate(message.timestamp)}
            </span>
          </div>
        )}

        {message.type === 'system' ? (
          <div className="flex justify-center py-1">
            <div className="px-4 py-2 bg-[rgb(245,158,11)]/10 text-[rgb(245,158,11)] rounded-lg text-sm font-medium max-w-xs text-center">
              {message.content}
            </div>
          </div>
        ) : (
          <div className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : ''}`}>
            {!isCurrentUser && (
              <img
                src={message.userAvatar}
                alt={message.userName}
                className="w-8 h-8 rounded-full flex-shrink-0 mt-1"
              />
            )}

            <div className={`flex flex-col max-w-[80%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
              {!isCurrentUser && (
                <span className="text-xs font-medium text-[rgb(100,116,139)] mb-1">
                  {message.userName}
                </span>
              )}

              <div className={`relative group ${isCurrentUser ? 'ml-auto' : ''}`}>
                <div
                  className={`px-4 py-2 rounded-2xl ${
                    isCurrentUser
                      ? 'bg-[rgb(34,139,34)] text-white rounded-br-md'
                      : 'bg-[rgb(241,245,249)] text-[rgb(15,23,42)] rounded-bl-md'
                  } ${message.type !== 'text' ? 'border-l-4 border-[rgb(245,158,11)]' : ''}`}
                >
                  {message.type === 'location' && (
                    <div className="flex items-center gap-2 mb-1">
                      <MapPin className="w-4 h-4" />
                      <span className="text-sm font-medium">Location Shared</span>
                    </div>
                  )}

                  {message.type === 'task' && (
                    <div className="flex items-center gap-2 mb-1">
                      <Users className="w-4 h-4" />
                      <span className="text-sm font-medium">Task Assignment</span>
                    </div>
                  )}

                  {message.type === 'meal' && (
                    <div className="flex items-center gap-2 mb-1">
                      <Utensils className="w-4 h-4" />
                      <span className="text-sm font-medium">Meal Planning</span>
                    </div>
                  )}

                  <p className="text-sm leading-relaxed whitespace-pre-wrap">
                    {message.content}
                  </p>

                  {message.metadata && (
                    <div className="mt-2 text-xs opacity-75">
                      {message.metadata.location && (
                        <div>📍 {message.metadata.location}</div>
                      )}
                      {message.metadata.taskName && (
                        <div>✅ {message.metadata.taskName} → {message.metadata.assignee}</div>
                      )}
                      {message.metadata.mealType && (
                        <div>🍽️ {message.metadata.mealType} - {message.metadata.date}</div>
                      )}
                    </div>
                  )}
                </div>

                <div className={`flex items-center gap-1 mt-1 ${isCurrentUser ? 'justify-end' : 'justify-start'}`}>
                  <span className="text-xs text-[rgb(100,116,139)]">
                    {formatTime(message.timestamp)}
                  </span>

                  <button
                    onClick={() => onMessageAction(message.id, 'menu')}
                    className="opacity-0 group-hover:opacity-100 p-1 hover:bg-[rgb(241,245,249)] rounded transition-all duration-150"
                    aria-label="Message options"
                  >
                    <MoreVertical className="w-3 h-3 text-[rgb(100,116,139)]" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[rgb(226,232,240)] bg-white">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            <img
              src="/api/placeholder/32/32"
              alt="Member"
              className="w-8 h-8 rounded-full border-2 border-white"
            />
            <img
              src="/api/placeholder/32/32"
              alt="Member"
              className="w-8 h-8 rounded-full border-2 border-white"
            />
            <img
              src="/api/placeholder/32/32"
              alt="Member"
              className="w-8 h-8 rounded-full border-2 border-white"
            />
            <div className="w-8 h-8 rounded-full border-2 border-white bg-[rgb(34,139,34)] flex items-center justify-center">
              <span className="text-xs font-medium text-white">+2</span>
            </div>
          </div>
          <div>
            <h2 className="font-semibold text-[rgb(15,23,42)]">Trip Chat</h2>
            <p className="text-sm text-[rgb(100,116,139)]">6 members</p>
          </div>
        </div>

        <button
          onClick={() => onMessageAction('', 'info')}
          className="p-2 hover:bg-[rgb(241,245,249)] rounded-lg transition-colors duration-150"
          aria-label="Chat info"
        >
          <MoreVertical className="w-5 h-5 text-[rgb(100,116,139)]" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {chatMessages.map((message, index) => renderMessage(message, index))}

        {isTyping && (
          <div className="flex gap-3">
            <img
              src="/api/placeholder/32/32"
              alt="Typing"
              className="w-8 h-8 rounded-full flex-shrink-0 mt-1"
            />
            <div className="bg-[rgb(241,245,249)] rounded-2xl rounded-bl-md px-4 py-3">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                <div className="w-2 h-2 bg-[rgb(100,116,139)] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-[rgb(226,232,240)] bg-white">
        <div className="flex items-end gap-3">
          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 pr-12 bg-[rgb(248,250,252)] border border-[rgb(226,232,240)] rounded-2xl text-[rgb(15,23,42)] placeholder-[rgb(100,116,139)] focus:border-[rgb(34,139,34)] focus:outline-none focus:ring-2 focus:ring-[rgb(34,139,34)]/20 transition-all duration-150 resize-none"
              style={{ minHeight: '44px' }}
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-[rgb(34,139,34)] text-white rounded-2xl hover:bg-[rgb(34,139,34)]/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 shadow-md hover:shadow-lg active:scale-95"
            style={{ minWidth: '44px', minHeight: '44px' }}
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

