export function LocationManagement({
  locations = MOCK_LOCATIONS,
  onLocationSelect = () => {},
  onLocationSave = () => {},
  onLocationRemove = () => {},
  showFavoritesOnly = false
}: LocationManagementProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('All')
  const [showFilters, setShowFilters] = useState(false)
  const [filteredLocations, setFilteredLocations] = useState<Location[]>(locations)
  const [viewMode, setViewMode] = useState<'all' | 'favorites'>('all')
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    setIsLoading(true)
    const timer = setTimeout(() => {
      let filtered = locations

      if (viewMode === 'favorites') {
        filtered = filtered.filter(location => location.isFavorite)
      }

      if (searchQuery) {
        filtered = filtered.filter(location =>
          location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
          location.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
          location.terrain.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
        )
      }

      if (selectedDifficulty !== 'All') {
        filtered = filtered.filter(location => location.difficulty === selectedDifficulty)
      }

      setFilteredLocations(filtered)
      setIsLoading(false)
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery, selectedDifficulty, locations, viewMode])

  const handleToggleFavorite = (locationId: string) => {
    const location = locations.find(l => l.id === locationId)
    if (location) {
      const updatedLocation = { ...location, isFavorite: !location.isFavorite }
      onLocationSave(updatedLocation)
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-[#22c55e] text-white'
      case 'Moderate': return 'bg-[#f59e0b] text-white'
      case 'Difficult': return 'bg-[#ef4444] text-white'
      case 'Expert': return 'bg-[#7c3aed] text-white'
      default: return 'bg-[#6b7280] text-white'
    }
  }

  const LoadingSkeleton = () => (
    <div className="space-y-4">
      {[1, 2, 3].map(i => (
        <div key={i} className="bg-white rounded-xl border border-[#e2e8f0] p-4 animate-pulse">
          <div className="flex gap-4">
            <div className="w-20 h-20 bg-[#f1f5f9] rounded-lg"></div>
            <div className="flex-1 space-y-2">
              <div className="h-4 bg-[#f1f5f9] rounded w-3/4"></div>
              <div className="h-3 bg-[#f1f5f9] rounded w-1/2"></div>
              <div className="h-3 bg-[#f1f5f9] rounded w-2/3"></div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      {/* Header */}
      <div className="bg-[#228b22] text-white p-4 pb-6">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-xl font-semibold">Trail Locations</h1>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="p-2 rounded-lg bg-white/10 hover:bg-white/20 transition-colors"
            aria-label="Toggle filters"
          >
            <Filter className="w-5 h-5" />
          </button>
        </div>

        {/* Search Bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search trails, terrain, features..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 bg-white text-[#0f172a] rounded-lg border border-[#e2e8f0] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent"
          />
        </div>
      </div>

      {/* View Toggle */}
      <div className="px-4 py-3 bg-[#f8fafc] border-b border-[#e2e8f0]">
        <div className="flex gap-2">
          <button
            onClick={() => setViewMode('all')}
            className={`flex-1 py-2 px-4 rounded-lg font-medium transition-colors ${
              viewMode === 'all'
