      {/* Content */}
      <div className="px-4 py-4">
        {isLoading ? (
          <LoadingSkeleton />
        ) : filteredLocations.length === 0 ? (
          <div className="text-center py-12">
            <Mountain className="w-16 h-16 text-[#94a3b8] mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-[#0f172a] mb-2">
              {viewMode === 'favorites' ? 'No Favorite Locations' : 'No Locations Found'}
            </h3>
            <p className="text-[#64748b] mb-4">
              {viewMode === 'favorites' 
                ? 'Start exploring and save your favorite trails!'
                : 'Try adjusting your search or filters to find trails.'}
