            <button
              onClick={() => {
                setSearchQuery('')
                setSelectedDifficulty('All')
                setViewMode('all')
              }}
              className="px-4 py-2 bg-[#228b22] text-white rounded-lg hover:bg-[#1e7b1e] transition-colors"
            >
              <Plus className="w-4 h-4 inline mr-2" />
              Explore All Trails
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredLocations.map(location => (
              <div
                key={location.id}
                className="bg-white rounded-xl border border-[#e2e8f0] p-4 shadow-sm hover:shadow-md transition-all duration-200"
              >
                <div className="flex gap-4">
                  {/* Location Image */}
                  <div className="w-20 h-20 bg-[#f1f5f9] rounded-lg flex items-center justify-center flex-shrink-0">
                    <Mountain className="w-8 h-8 text-[#64748b]" />
