                    </div>

                    <p className="text-sm text-[#64748b] mb-3 line-clamp-2">
                      {location.description}
                    </p>

                    {/* Badges */}
                    <div className="flex flex-wrap gap-2 mb-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getDifficultyColor(location.difficulty)}`}>
                        {location.difficulty}
                      </span>
                      <span className="px-2 py-1 bg-[#f1f5f9] text-[#64748b] rounded-full text-xs font-medium">
                        <Navigation className="w-3 h-3 inline mr-1" />
                        {location.distance} mi
                      </span>
                      <span className="px-2 py-1 bg-[#f1f5f9] text-[#64748b] rounded-full text-xs font-medium">
                        <Star className="w-3 h-3 inline mr-1 fill-[#f59e0b] text-[#f59e0b]" />
                        {location.rating}
                      </span>
                    </div>

                    {/* Terrain Tags */}
                    <div className="flex flex-wrap gap-1 mb-3">
                      {location.terrain.slice(0, 3).map(terrain => (
                        <span
                          key={terrain}
                          className="px-2 py-1 bg-[#228b22]/10 text-[#228b22] rounded text-xs font-medium"
                        >
                          {terrain}
                        </span>
                      ))}
                      {location.terrain.length > 3 && (
                        <span className="px-2 py-1 bg-[#f1f5f9] text-[#64748b] rounded text-xs font-medium">
                          +{location.terrain.length - 3} more
                        </span>
                      )}
                    </div>

                    {/* Action Buttons */}
                    <div className="flex gap-2">
                      <button
                        onClick={() => onLocationSelect(location)}
                        className="flex-1 py-2 px-3 bg-[#228b22] text-white rounded-lg hover:bg-[#1e7b1e] transition-colors text-sm font-medium"
                      >
                        <MapPin className="w-4 h-4 inline mr-1" />
                        Select Location
                      </button>
                      <button
                        onClick={() => onLocationSave(location)}
                        className="py-2 px-3 bg-[#f8fafc] text-[#0f172a] border border-[#e2e8f0] rounded-lg hover:bg-[#f1f5f9] transition-colors text-sm font-medium"
