        )}
      </div>

      {/* Floating Action Button */}
      <div className="fixed bottom-6 right-4">
        <button
          onClick={() => {
            // Handle add new location
            console.log('Add new location')
          }}
          className="w-14 h-14 bg-[#228b22] text-white rounded-full shadow-lg hover:bg-[#1e7b1e] transition-all duration-200 hover:shadow-xl active:scale-95 flex items-center justify-center"
          aria-label="Add new location"
        >
          <Plus className="w-6 h-6" />
        </button>
      </div>
    </div>
