'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Plus, X, ChevronDown } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  role?: string
}

interface TripLocation {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  description?: string
}

interface CreateTripFormProps {
  onSubmit?: (tripData: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

interface TripFormData {
  name: string
  description: string
  startDate: string
  endDate: string
  location: TripLocation | null
  members: TripMember[]
  estimatedCost: number
  difficulty: 'easy' | 'moderate' | 'hard' | 'expert'
  vehicleRequirements: string[]
}

const DIFFICULTY_OPTIONS = [
  { value: 'easy', label: 'Easy', description: 'Suitable for beginners' },
  { value: 'moderate', label: 'Moderate', description: 'Some experience required' },
  { value: 'hard', label: 'Hard', description: 'Experienced drivers only' },
  { value: 'expert', label: 'Expert', description: 'Advanced skills required' }
] as const

const VEHICLE_OPTIONS = [
  '4WD Required',
  'High Clearance',
  'Winch Recommended',
  'Rock Sliders',
  'Skid Plates',
  'All-Terrain Tires'
]

const SAMPLE_LOCATIONS: TripLocation[] = [
  {
    id: '1',
