]

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {},
  isLoading = false
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    description: '',
    startDate: '',
    endDate: '',
    location: null,
    members: [],
    estimatedCost: 0,
    difficulty: 'moderate',
    vehicleRequirements: [],
    ...initialData
  })

  const [showLocationDropdown, setShowLocationDropdown] = useState(false)
  const [newMemberEmail, setNewMemberEmail] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && formData.startDate > formData.endDate) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (!formData.location) {
      newErrors.location = 'Location is required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const addMember = () => {
    if (newMemberEmail.trim() && !formData.members.find(m => m.email === newMemberEmail)) {
      const newMember: TripMember = {
        id: Date.now().toString(),
        name: newMemberEmail.split('@')[0],
        email: newMemberEmail.trim()
      }
      setFormData(prev => ({
        ...prev,
        members: [...prev.members, newMember]
      }))
      setNewMemberEmail('')
    }
  }

  const removeMember = (memberId: string) => {
    setFormData(prev => ({
      ...prev,
      members: prev.members.filter(m => m.id !== memberId)
    }))
  }

  const toggleVehicleRequirement = (requirement: string) => {
    setFormData(prev => ({
      ...prev,
      vehicleRequirements: prev.vehicleRequirements.includes(requirement)
        ? prev.vehicleRequirements.filter(r => r !== requirement)
        : [...prev.vehicleRequirements, requirement]
    }))
  }

  return (
    <div className="min-h-screen bg-[#ffffff] font-medium">
      <div className="max-w-2xl mx-auto px-4 py-6">
        <div className="mb-8">
          <h1 className="text-2xl font-bold text-[#0f172a] mb-2">Create New Trip</h1>
          <p className="text-[#64748b] text-sm">Plan your next off-road adventure</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Trip Name */}
          <div>
            <label htmlFor="tripName" className="block text-sm font-medium text-[#0f172a] mb-2">
              Trip Name *
            </label>
            <input
              id="tripName"
              type="text"
              value={formData.name}
              onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
              className={`w-full px-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                errors.name ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
              }`}
              placeholder="Enter trip name"
              aria-describedby={errors.name ? 'tripName-error' : undefined}
            />
            {errors.name && (
              <p id="tripName-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                {errors.name}
              </p>
            )}
          </div>

          {/* Description */}
          <div>
            <label htmlFor="description" className="block text-sm font-medium text-[#0f172a] mb-2">
              Description
            </label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={3}
              className="w-full px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 resize-none"
              placeholder="Describe your trip..."
            />
          </div>

          {/* Dates */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label htmlFor="startDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                Start Date *
              </label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="startDate"
                  type="date"
                  value={formData.startDate}
                  onChange={(e) => setFormData(prev => ({ ...prev, startDate: e.target.value }))}
                  className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.startDate ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  aria-describedby={errors.startDate ? 'startDate-error' : undefined}
                />
              </div>
              {errors.startDate && (
                <p id="startDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.startDate}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="endDate" className="block text-sm font-medium text-[#0f172a] mb-2">
                End Date *
              </label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#64748b]" />
                <input
                  id="endDate"
                  type="date"
                  value={formData.endDate}
                  onChange={(e) => setFormData(prev => ({ ...prev, endDate: e.target.value }))}
                  className={`w-full pl-10 pr-4 py-3 bg-[#ffffff] border rounded-lg text-[#0f172a] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                    errors.endDate ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                  }`}
                  aria-describedby={errors.endDate ? 'endDate-error' : undefined}
                />
              </div>
              {errors.endDate && (
                <p id="endDate-error" className="mt-1 text-sm text-[#dc2626]" role="alert">
                  {errors.endDate}
                </p>
              )}
            </div>
          </div>

          {/* Location */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-2">
              Location *
            </label>
            <div className="relative">
              <button
                type="button"
                onClick={() => setShowLocationDropdown(!showLocationDropdown)}
                className={`w-full px-4 py-3 bg-[#ffffff] border rounded-lg text-left flex items-center justify-between focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200 ${
                  errors.location ? 'border-[#dc2626]' : 'border-[#e2e8f0]'
                }`}
                aria-expanded={showLocationDropdown}
                aria-haspopup="listbox"
              >
                <div className="flex items-center">
                  <MapPin className="h-5 w-5 text-[#64748b] mr-3" />
                  <span className={formData.location ? 'text-[#0f172a]' : 'text-[#64748b]'}>
                    {formData.location ? formData.location.name : 'Select a location'}
                  </span>
                </div>
                <ChevronDown className={`h-5 w-5 text-[#64748b] transition-transform duration-200 ${
                  showLocationDropdown ? 'rotate-180' : ''
                }`} />
              </button>

              {showLocationDropdown && (
                <div className="absolute z-10 w-full mt-1 bg-[#ffffff] border border-[#e2e8f0] rounded-lg shadow-lg max-h-60 overflow-auto">
                  {SAMPLE_LOCATIONS.map((location) => (
                    <button
                      key={location.id}
                      type="button"
                      onClick={() => {
                        setFormData(prev => ({ ...prev, location }))
                        setShowLocationDropdown(false)
                      }}
                      className="w-full px-4 py-3 text-left hover:bg-[#f1f5f9] focus:bg-[#f1f5f9] focus:outline-none transition-colors duration-150"
                    >
                      <div className="font-medium text-[#0f172a]">{location.name}</div>
                      {location.description && (
                        <div className="text-sm text-[#64748b] mt-1">{location.description}</div>
                      )}
                    </button>
                  ))}
                </div>
              )}
            </div>
            {errors.location && (
              <p className="mt-1 text-sm text-[#dc2626]" role="alert">
                {errors.location}
              </p>
            )}
          </div>

          {/* Difficulty */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-3">
              Difficulty Level
            </label>
            <div className="grid grid-cols-2 gap-3">
              {DIFFICULTY_OPTIONS.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, difficulty: option.value }))}
                  className={`p-3 rounded-lg border-2 text-left transition-all duration-200 ${
                    formData.difficulty === option.value
                      ? 'border-[#228b22] bg-[#228b22]/5'
                      : 'border-[#e2e8f0] hover:border-[#228b22]/50'
                  }`}
                >
                  <div className={`font-medium ${
                    formData.difficulty === option.value ? 'text-[#228b22]' : 'text-[#0f172a]'
                  }`}>
                    {option.label}
                  </div>
                  <div className="text-xs text-[#64748b] mt-1">{option.description}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Vehicle Requirements */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-3">
              Vehicle Requirements
            </label>
            <div className="grid grid-cols-2 gap-2">
              {VEHICLE_OPTIONS.map((requirement) => (
                <button
                  key={requirement}
                  type="button"
                  onClick={() => toggleVehicleRequirement(requirement)}
                  className={`px-3 py-2 rounded-lg text-sm border transition-all duration-200 ${
                    formData.vehicleRequirements.includes(requirement)
                      ? 'border-[#228b22] bg-[#228b22] text-[#ffffff]'
                      : 'border-[#e2e8f0] text-[#64748b] hover:border-[#228b22]/50'
                  }`}
                >
                  {requirement}
                </button>
              ))}
            </div>
          </div>

          {/* Estimated Cost */}
          <div>
            <label htmlFor="estimatedCost" className="block text-sm font-medium text-[#0f172a] mb-2">
              Estimated Cost per Person
            </label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[#64748b]">$</span>
              <input
                id="estimatedCost"
                type="number"
                min="0"
                step="0.01"
                value={formData.estimatedCost || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, estimatedCost: parseFloat(e.target.value) || 0 }))}
                className="w-full pl-8 pr-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200"
                placeholder="0.00"
              />
            </div>
          </div>

          {/* Members */}
          <div>
            <label className="block text-sm font-medium text-[#0f172a] mb-3">
              Trip Members
            </label>

            <div className="flex gap-2 mb-3">
              <input
                type="email"
                value={newMemberEmail}
                onChange={(e) => setNewMemberEmail(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addMember())}
                className="flex-1 px-4 py-3 bg-[#ffffff] border border-[#e2e8f0] rounded-lg text-[#0f172a] placeholder-[#64748b] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:border-transparent transition-all duration-200"
                placeholder="Enter email address"
              />
              <button
                type="button"
                onClick={addMember}
                className="px-4 py-3 bg-[#228b22] text-[#ffffff] rounded-lg hover:bg-[#1e7a1e] transition-colors duration-200 min-w-[44px] min-h-[44px] flex items-center justify-center"
                aria-label="Add member"
              >
                <Plus className="h-5 w-5" />
              </button>
            </div>

            {formData.members.length > 0 && (
              <div className="space-y-2">
                {formData.members.map((member) => (
                  <div key={member.id} className="flex items-center justify-between p-3 bg-[#f8fafc] rounded-lg border border-[#e2e8f0]">
                    <div className="flex items-center">
                      <Users className="h-4 w-4 text-[#64748b] mr-3" />
                      <div>
                        <div className="font-medium text-[#0f172a]">{member.name}</div>
                        <div className="text-sm text-[#64748b]">{member.email}</div>
                      </div>
                    </div>
                    <button
                      type="button"
                      onClick={() => removeMember(member.id)}
                      className="p-1 text-[#64748b] hover:text-[#dc2626] transition-colors duration-200 min-w-[44px] min-h-[44px] flex items-center justify-center"
                      aria-label={`Remove ${member.name}`}
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Submit Button */}
          <div className="pt-6">
            <button
              type="submit"
              disabled={isLoading}
              className="w-full px-6 py-4 bg-[#228b22] text-[#ffffff] rounded-lg font-medium hover:bg-[#1e7a1e] focus:outline-none focus:ring-2 focus:ring-[#228b22] focus:ring-offset-2 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed min-h-[44px] flex items-center justify-center"
            >
              {isLoading ? (
                <div className="flex items-center">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-[#ffffff] mr-2"></div>
                  Creating Trip...
                </div>
