        setSession(prev => ({ ...prev, isLoading: false }))
      }
    }

    checkAuth()
  }, [handleAuthChange])

  const handleSignOut = async () => {
    try {
      setError(null)
      // Mock sign out - replace with actual auth service
      const newSession: AuthSession = {
        user: null,
        token: null,
        expiresAt: null,
        isLoading: false
      }

