  // Simulate checking calendar availability
  const checkGroupAvailability = async (startDate: string, endDate: string) => {
    setIsCheckingAvailability(true)
    setError(null)

    try {
      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 2000))

      const mockAvailability: Record<string, CalendarEvent[]> = {}

      groupMembers.forEach(member => {
        mockAvailability[member.id] = [
          {
            id: `${member.id}-1`,
            title: 'Work Meeting',
            start: startDate + 'T09:00:00',
            end: startDate + 'T10:00:00',
            attendees: [member.email]
          },
          {
            id: `${member.id}-2`,
            title: 'Family Dinner',
            start: startDate + 'T18:00:00',
            end: startDate + 'T20:00:00',
            attendees: [member.email]
          }
        ]
      })

      setAvailabilityData(mockAvailability)
    } catch (err) {
      setError('Failed to check availability. Please try again.')
    } finally {
      setIsCheckingAvailability(false)
    }
  }

  // Create trip schedule
  const createTripSchedule = async () => {
    if (!selectedDates.start || !selectedDates.end) return

    setIsLoading(true)
    setError(null)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1500))

      const newSchedule: TripSchedule = {
        id: tripId,
        tripName: 'Desert Adventure Trip',
        startDate: selectedDates.start,
        endDate: selectedDates.end,
        location: 'Moab, Utah',
        events: [
          {
            id: 'event-1',
            title: 'Arrival & Setup Camp',
            start: selectedDates.start + 'T15:00:00',
            end: selectedDates.start + 'T17:00:00',
            attendees: groupMembers.map(m => m.email),
            location: 'Base Camp',
            description: 'Set up tents and prepare for adventure'
          },
          {
            id: 'event-2',
            title: 'Morning Trail Ride',
            start: selectedDates.start + 'T08:00:00',
            end: selectedDates.start + 'T12:00:00',
            attendees: groupMembers.map(m => m.email),
            location: 'Hell\'s Revenge Trail',
            description: 'Epic off-road adventure through red rock country'
          },
          {
            id: 'event-3',
            title: 'Group Dinner',
            start: selectedDates.start + 'T18:00:00',
            end: selectedDates.start + 'T20:00:00',
            attendees: groupMembers.map(m => m.email),
            location: 'Base Camp',
            description: 'BBQ and campfire stories'
          }
        ]
      }

      setSchedule(newSchedule)
      onScheduleUpdate(newSchedule)
    } catch (err) {
      setError('Failed to create schedule. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  // Send calendar invites
