    }
  }

  const handleCancel = () => {
    setEditedProfile(profile)
    setIsEditing(false)
    setError(null)
  }

  const updateField = (field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const updateNestedField = (parent: string, field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [parent]: {
        ...prev[parent as keyof UserProfile],
        [field]: value
      }
    }))
  }

  if (isLoading && !profile.id) {
    return <ProfileSkeleton />
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-amber-50 dark:from-gray-900 dark:to-gray-800 font-sans">
      {/* Header */}
      <div className="bg-gradient-to-r from-orange-600 to-amber-600 dark:from-orange-700 dark:to-amber-700 text-white">
        <div className="max-w-4xl mx-auto px-4 py-8">
          <div className="flex flex-col sm:flex-row items-center gap-6">
            <div className="relative">
              <div className="w-24 h-24 sm:w-32 sm:h-32 rounded-full bg-white/20 flex items-center justify-center overflow-hidden ring-4 ring-white/20 transition-all duration-300 hover:ring-white/40">
                {profile.avatar ? (
                  <img 
                    src={profile.avatar} 
                    alt={`${profile.name}'s profile picture`} 
                    className="w-full h-full object-cover" 
                  />
                ) : (
                  <User className="w-12 h-12 sm:w-16 sm:h-16 text-white/80" />
                )}
              </div>
              {isEditing && (
                <button 
                  className="absolute bottom-0 right-0 w-8 h-8 bg-white text-orange-600 rounded-full flex items-center justify-center shadow-lg hover:bg-gray-50 hover:scale-110 active:scale-95 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-white/50"
                  aria-label="Change profile picture"
                >
                  <Camera className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="flex-1 text-center sm:text-left">
              {isEditing ? (
                <input
                  type="text"
                  value={editedProfile.name}
                  onChange={(e) => updateField('name', e.target.value)}
                  className="text-2xl sm:text-3xl font-bold bg-white/20 text-white placeholder-white/70 rounded-lg px-4 py-2 w-full max-w-md border-none outline-none focus:bg-white/30 focus:ring-2 focus:ring-white/50 transition-all duration-200"
                  placeholder="Your name"
                  aria-label="Edit your name"
                />
              ) : (
                <h1 className="text-2xl sm:text-3xl font-bold">{profile.name}</h1>
              )}

              <div className="flex flex-wrap items-center justify-center sm:justify-start gap-4 mt-2 text-white/90">
                <div className="flex items-center gap-1">
                  <MapPin className="w-4 h-4" />
                  <span className="text-sm">{profile.location}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Calendar className="w-4 h-4" />
                  <span className="text-sm">Joined {profile.joinDate}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Mountain className="w-4 h-4" />
                  <span className="text-sm">{profile.tripsCompleted} trips</span>
                </div>
              </div>
            </div>

            <div className="flex gap-2">
              {isEditing ? (
                <>
                  <button
                    onClick={handleSave}
                    disabled={isLoading}
                    className="px-4 py-2 bg-white text-orange-600 rounded-lg hover:bg-gray-50 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-white/50"
                    aria-label="Save profile changes"
                  >
                    <Save className="w-4 h-4" />
                    {isLoading ? 'Saving...' : 'Save'}
                  </button>
                  <button
                    onClick={handleCancel}
                    className="px-4 py-2 bg-white/20 text-white rounded-lg hover:bg-white/30 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm border border-white/30 flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-white/50"
                    aria-label="Cancel editing"
                  >
                    <X className="w-4 h-4" />
                    Cancel
                  </button>
                </>
              ) : (
                <button
                  onClick={() => setIsEditing(true)}
                  className="px-4 py-2 bg-white/20 text-white rounded-lg hover:bg-white/30 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm border border-white/30 flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-white/50"
                  aria-label="Edit profile"
                >
                  <Edit3 className="w-4 h-4" />
                  Edit Profile
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Error State */}
        {error && (
          <div className="mb-6 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400" />
              <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
            </div>
          </div>
        )}

        {/* Experience Badge */}
        <div className="mb-6">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 rounded-full text-sm font-medium border border-orange-200 dark:border-orange-700 hover:bg-orange-200 dark:hover:bg-orange-900/50 transition-colors duration-200">
            <Compass className="w-4 h-4" />
            {profile.experience.charAt(0).toUpperCase() + profile.experience.slice(1)} Off-Roader
          </div>
        </div>

        {/* Tabs */}
        <div className="flex flex-wrap gap-1 mb-6 bg-white dark:bg-gray-800 rounded-lg p-1 shadow-sm border border-gray-200 dark:border-gray-700">
          {[
            { id: 'personal', label: 'Personal Info', icon: User },
            { id: 'vehicle', label: 'Vehicle', icon: Tent },
            { id: 'preferences', label: 'Preferences', icon: Settings }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-md text-sm font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-orange-500/50 ${
                activeTab === id
                  ? 'bg-orange-600 text-white shadow-md'
                  : 'text-gray-600 dark:text-gray-300 hover:text-orange-600 dark:hover:text-orange-400 hover:bg-gray-100 dark:hover:bg-gray-700'
              }`}
              aria-label={`Switch to ${label} tab`}
            >
              <Icon className="w-4 h-4" />
              <span className="hidden sm:inline">{label}</span>
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 p-6 hover:shadow-xl transition-shadow duration-300">
          {activeTab === 'personal' && (
            <PersonalInfoTab
              profile={isEditing ? editedProfile : profile}
              isEditing={isEditing}
              onUpdate={updateField}
              onUpdateNested={updateNestedField}
            />
          )}

          {activeTab === 'vehicle' && (
            <VehicleInfoTab
