            />
          )}

          {activeTab === 'preferences' && (
            <PreferencesTab
              profile={isEditing ? editedProfile : profile}
              isEditing={isEditing}
              onUpdate={updateNestedField}
            />
          )}
        </div>
      </div>
    </div>
  )
}

