function PreferencesTab({ profile, isEditing, onUpdate }: any) {
  const difficultyOptions = ['Easy', 'Moderate', 'Difficult', 'Expert']
  const terrainOptions = ['Desert', 'Mountain', 'Forest', 'Beach', 'Rock Crawling', 'Mud']

  const togglePreference = (type: 'difficulty' | 'terrain', value: string) => {
    if (!isEditing) return

    const current = profile.preferences[type]
    const updated = current.includes(value)
      ? current.filter((item: string) => item !== value)
      : [...current, value]

    onUpdate('preferences', type, updated)
  }

  return (
    <div className="space-y-6">
      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">Preferred Difficulty</label>
        <div className="flex flex-wrap gap-2">
          {difficultyOptions.map((difficulty) => (
            <button
              key={difficulty}
              onClick={() => togglePreference('difficulty', difficulty)}
              disabled={!isEditing}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-orange-500/50 ${
                profile.preferences.difficulty.includes(difficulty)
                  ? 'bg-orange-600 text-white hover:bg-orange-700'
                  : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
              } ${!isEditing ? 'cursor-default' : 'hover:scale-[1.02] active:scale-[0.98]'}`}
              aria-label={`${profile.preferences.difficulty.includes(difficulty) ? 'Remove' : 'Add'} ${difficulty} difficulty preference`}
            >
              {difficulty}
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">Preferred Terrain</label>
        <div className="flex flex-wrap gap-2">
          {terrainOptions.map((terrain) => (
            <button
              key={terrain}
              onClick={() => togglePreference('terrain', terrain)}
              disabled={!isEditing}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-orange-500/50 ${
                profile.preferences.terrain.includes(terrain)
                  ? 'bg-orange-600 text-white hover:bg-orange-700'
                  : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
              } ${!isEditing ? 'cursor-default' : 'hover:scale-[1.02] active:scale-[0.98]'}`}
              aria-label={`${profile.preferences.terrain.includes(terrain) ? 'Remove' : 'Add'} ${terrain} terrain preference`}
            >
              {terrain}
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Preferred Group Size</label>
        {isEditing ? (
          <input
            type="text"
            value={profile.preferences.groupSize}
            onChange={(e) => onUpdate('preferences', 'groupSize', e.target.value)}
            className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white rounded-lg focus:border-orange-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all duration-200"
            placeholder="e.g., 4-8 people"
            aria-label="Edit preferred group size"
          />
        ) : (
          <p className="text-gray-900 dark:text-white">{profile.preferences.groupSize}</p>
        )}
      </div>
    </div>
  )
}

