  const getTableIcon = useCallback((tableName: string) => {
    const icons = {
      trips: MapPin,
      users: Users,
      trip_participants: Users,
      tasks: CheckSquare,
      task_assignments: Link,
      meals: Utensils,
      chat_messages: MessageSquare,
      saved_locations: MapPin
    }
    return icons[tableName as keyof typeof icons] || Table
  }, [])

  const generateSQL = useCallback((table: TableSchema) => {
    const fields = table.fields.map(field => {
      const nullable = field.required ? 'NOT NULL' : 'NULL'
      const primaryKey = field.name === 'id' ? ' PRIMARY KEY' : ''
      return `  ${field.name} ${field.type}${primaryKey} ${nullable}`
    }).join(',\n')

    return `CREATE TABLE ${table.name} (
${fields}
);

-- Indexes for ${table.name}
${table.fields
  .filter(f => f.name.includes('_id') || f.name === 'email')
  .map(f => `CREATE INDEX idx_${table.name}_${f.name} ON ${table.name}(${f.name});`)
  .join('\n')}

-- Comments for ${table.name}
COMMENT ON TABLE ${table.name} IS '${table.description}';
${table.fields
  .map(f => `COMMENT ON COLUMN ${table.name}.${f.name} IS '${f.description}';`)
  .join('\n')}`
  }, [])

  const handleCopySQL = useCallback(async (table: TableSchema) => {
    try {
      await navigator.clipboard.writeText(generateSQL(table))
      setCopiedTable(table.name)
      setTimeout(() => setCopiedTable(null), 2000)
    } catch (error) {
      console.error('Failed to copy SQL:', error)
    }
  }, [generateSQL])

  const selectedTableData = useMemo(() => 
    schema.find(t => t.name === selectedTable), 
    [schema, selectedTable]
  )

  const schemaStats = useMemo(() => ({
    totalTables: schema.length,
    totalFields: schema.reduce((sum, table) => sum + table.fields.length, 0),
    totalRelationships: schema.reduce((sum, table) => sum + table.relationships.length, 0),
    connectedTables: schema.filter(table => table.fields.some(f => f.name.includes('_id'))).length
