                    <div className="p-6 bg-orange-50 dark:bg-orange-900/20 rounded-xl border border-orange-200 dark:border-orange-800 hover:scale-105 transition-transform duration-200">
                      <div className="text-3xl font-bold text-orange-700 dark:text-orange-300 mb-1">
                        {schemaStats.connectedTables}
                      </div>
                      <div className="text-sm text-orange-600 dark:text-orange-400 font-medium">Connected Tables</div>
                    </div>
                  </div>
                </div>
              </div>
            ) : (
