              <div className="space-y-8">
                {schema.map((table) => (
                  <div 
                    key={table.name} 
                    className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-lg shadow-orange-500/5 p-8 hover:shadow-xl transition-all duration-300"
                  >
                    <div className="flex items-center justify-between mb-6">
