                        onClick={() => handleCopySQL(table)}
                        className="flex items-center gap-2 px-4 py-2 bg-orange-500 hover:bg-orange-600 text-white rounded-lg transition-all duration-200 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-orange-500/50 text-sm font-semibold shadow-md"
                        aria-label={`Copy SQL for ${table.name} table`}
