  start: Date
  end: Date
  attendees: string[]
  location?: string
  description?: string
}

interface CalendarAvailability {
  date: string
  available: boolean
  conflicts: CalendarEvent[]
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
}

interface CalendarIntegrationProps {
  groupMembers?: GroupMember[]
  tripDates?: { start: Date; end: Date }
  onAvailabilityCheck?: (availability: CalendarAvailability[]) => void
  onEventCreate?: (event: Partial<CalendarEvent>) => void
}

export function CalendarIntegration({
  groupMembers = DEFAULT_GROUP_MEMBERS,
  tripDates = { start: new Date(), end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) },
  onAvailabilityCheck = () => console.log('Availability checked'),
  onEventCreate = () => console.log('Event created')
}: CalendarIntegrationProps = {}) {
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [availability, setAvailability] = useState<CalendarAvailability[]>([])
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [eventTitle, setEventTitle] = useState('')
  const [eventLocation, setEventLocation] = useState('')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    // Simulate checking calendar connection status
    const checkConnection = async () => {
      setIsLoading(true)
      setError(null)
      try {
        await new Promise(resolve => setTimeout(resolve, 1000))
        setIsConnected(Math.random() > 0.3) // 70% chance of being connected
      } catch (err) {
        setError('Failed to check calendar connection')
      } finally {
        setIsLoading(false)
      }
    }
    checkConnection()
  }, [])

  const handleConnectCalendar = async () => {
    setIsLoading(true)
    setError(null)
    try {
      // Simulate OAuth flow
      await new Promise(resolve => setTimeout(resolve, 2000))
      setIsConnected(true)
    } catch (err) {
      setError('Failed to connect calendar. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCheckAvailability = async () => {
    if (!isConnected) return

    setIsLoading(true)
    setError(null)
    try {
      // Simulate API call to check availability
      await new Promise(resolve => setTimeout(resolve, 1500))

      const mockAvailability: CalendarAvailability[] = []
      const currentDate = new Date(tripDates.start)

      while (currentDate <= tripDates.end) {
        const hasConflict = Math.random() > 0.7
        mockAvailability.push({
          date: currentDate.toISOString().split('T')[0],
          available: !hasConflict,
          conflicts: hasConflict ? [{
            id: `conflict-${currentDate.getTime()}`,
            title: 'Work Meeting',
            start: new Date(currentDate.getTime() + 9 * 60 * 60 * 1000),
            end: new Date(currentDate.getTime() + 10 * 60 * 60 * 1000),
            attendees: ['user@example.com']
          }] : []
        })
        currentDate.setDate(currentDate.getDate() + 1)
      }

      setAvailability(mockAvailability)
      onAvailabilityCheck(mockAvailability)
    } catch (err) {
      setError('Failed to check availability. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCreateEvent = async () => {
    if (!eventTitle || selectedMembers.length === 0) return

    setIsLoading(true)
    setError(null)
    try {
      const event: Partial<CalendarEvent> = {
        title: eventTitle,
        start: tripDates.start,
        end: tripDates.end,
        attendees: selectedMembers,
        location: eventLocation,
        description: `Off-roading trip: ${eventTitle}`
      }

      await new Promise(resolve => setTimeout(resolve, 1000))
      onEventCreate(event)
      setEventTitle('')
      setEventLocation('')
      setSelectedMembers([])
    } catch (err) {
      setError('Failed to create event. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

