            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="Type a message..."
              className="flex-1 px-4 py-2 border border-border rounded-lg bg-background text-foreground placeholder:text-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200"
              disabled={isLoading}
            />
            <button
              onClick={handleSendMessage}
              disabled={!newMessage.trim() || isLoading}
              className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              aria-label="Send message"
            >
              <Send className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  )

  return (
    <div className="min-h-screen bg-background dark:bg-background transition-colors duration-300">
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Navigation */}
        <div className="bg-surface dark:bg-surface rounded-xl shadow-md border border-border mb-6 overflow-x-auto">
          <div className="flex">
            {[
              { id: 'overview', label: 'Overview', icon: Calendar },
              { id: 'locations', label: 'Locations', icon: MapPin },
              { id: 'members', label: 'Members', icon: Users },
              { id: 'tasks', label: 'Tasks', icon: CheckSquare },
              { id: 'meals', label: 'Meals', icon: Utensils },
              { id: 'chat', label: 'Chat', icon: MessageCircle }
            ].map((tab) => {
              const Icon = tab.icon
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center gap-2 px-4 py-3 font-medium text-sm whitespace-nowrap transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-inset ${
                    activeTab === tab.id
                      ? 'text-primary border-b-2 border-primary bg-primary/5'
                      : 'text-mutedForeground hover:text-foreground hover:bg-muted/50'
                  }`}
                  aria-label={`Switch to ${tab.label} tab`}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                </button>
              )
            })}
          </div>
        </div>

        {/* Content */}
        <div>
          {activeTab === 'overview' && renderOverview()}
          {activeTab === 'locations' && renderLocations()}
          {activeTab === 'members' && renderMembers()}
          {activeTab === 'tasks' && renderTasks()}
          {activeTab === 'meals' && renderMeals()}
          {activeTab === 'chat' && renderChat()}
        </div>
      </div>
    </div>
  )
}

