'use client'

import { useState, useEffect } from 'react'
import { 
  MapPin, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  CheckSquare,
  Plus,
  Search,
  Mountain,
  Compass,
  Cloud,
  Sun,
  CloudRain,
  Star,
  Navigation,
  Settings,
  Bell,
  X,
  Loader2
} from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  participants: number
  status: 'planning' | 'confirmed' | 'completed'
  weather: 'sunny' | 'cloudy' | 'rainy'
  difficulty: 'easy' | 'moderate' | 'hard'
  image: string
}

interface Task {
  id: string
  title: string
  assignee: string
  category: 'food' | 'gear' | 'logistics'
  completed: boolean
  dueDate: string
}

interface Message {
  id: string
  sender: string
  content: string
  timestamp: string
  avatar: string
}

interface OffRoadTripPlannerProps {
  initialTrips?: Trip[]
  currentUser?: string
}

export function OffRoadTripPlanner({
  initialTrips = DEFAULT_TRIPS,
  currentUser = 'You'
}: OffRoadTripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('trips')
  const [trips, setTrips] = useState<Trip[]>(initialTrips)
  const [selectedTrip, setSelectedTrip] = useState<Trip | null>(null)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [showNewTripModal, setShowNewTripModal] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const filteredTrips = trips.filter(trip =>
    trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    trip.location.toLowerCase().includes(searchQuery.toLowerCase())
  )

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Message = {
      id: Date.now().toString(),
      sender: currentUser,
      content: newMessage,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: '/api/placeholder/32/32'
    }

    setMessages(prev => [...prev, message])
    setNewMessage('')
  }

  const toggleTask = (taskId: string) => {
    setTasks(prev => prev.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const getWeatherIcon = (weather: string) => {
    switch (weather) {
      case 'sunny': return <Sun className="w-4 h-4 text-accent" />
      case 'cloudy': return <Cloud className="w-4 h-4 text-mutedForeground" />
      case 'rainy': return <CloudRain className="w-4 h-4 text-blue-500" />
      default: return <Sun className="w-4 h-4 text-accent" />
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-green-100 dark:bg-green-900/20 text-green-700 dark:text-green-300 border-green-200 dark:border-green-800'
      case 'moderate': return 'bg-accent/20 text-accentForeground border-accent/30'
      case 'hard': return 'bg-destructive/20 text-destructive border-destructive/30'
      default: return 'bg-muted text-mutedForeground border-border'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-green-100 dark:bg-green-900/20 text-green-700 dark:text-green-300 border-green-200 dark:border-green-800'
      case 'planning': return 'bg-accent/20 text-accentForeground border-accent/30'
      case 'completed': return 'bg-muted text-mutedForeground border-border'
      default: return 'bg-muted text-mutedForeground border-border'
    }
  }

  return (
    <div className="min-h-screen bg-background font-sans transition-colors duration-200">
