          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center shadow-md">
                <Mountain className="w-5 h-5 text-primaryForeground" />
              </div>
              <h1 className="text-xl font-bold text-foreground">TrailPlan</h1>
            </div>

            <div className="flex items-center gap-2">
              <button 
                className="p-2 text-mutedForeground hover:text-primary transition-colors duration-200 rounded-lg hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus-visible:ring-2"
                aria-label="Notifications"
              >
                <Bell className="w-5 h-5" />
              </button>
              <button 
                className="p-2 text-mutedForeground hover:text-primary transition-colors duration-200 rounded-lg hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus-visible:ring-2"
