                <Settings className="w-5 h-5" />
              </button>
              <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center shadow-md">
                <span className="text-primaryForeground text-sm font-medium">JD</span>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Navigation */}
      <nav className="bg-surface border-b border-border sticky top-16 z-40 backdrop-blur-md bg-surface/95">
