                  activeTab === id
                    ? 'border-primary text-primary'
                    : 'border-transparent text-mutedForeground hover:text-foreground hover:border-border'
                }`}
                aria-label={`Switch to ${label} tab`}
              >
                <Icon className="w-4 h-4" />
                {label}
