                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-surface border border-border rounded-xl text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 transition-all duration-200"
                  aria-label="Search trips"
                />
              </div>
              <button
                onClick={() => setShowNewTripModal(true)}
                disabled={isLoading}
                className="px-6 py-3 bg-primary text-primaryForeground rounded-xl hover:bg-primary/90 focus:bg-primary/90 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-medium flex items-center gap-2 shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                aria-label="Create new trip"
