                      <div key={meal.time} className="border border-border rounded-lg p-4 hover:border-ring transition-colors duration-200">
                        <div className="flex items-center justify-between mb-2">
                          <h4 className="font-medium text-foreground">{meal.time}</h4>
                          <span className="text-sm text-mutedForeground">{meal.chef}</span>
                        </div>
                        <p className="text-mutedForeground">{meal.dish}</p>
                        <div className="flex items-center gap-2 mt-2">
                          <Star className="w-4 h-4 text-accent fill-current" />
                          <span className="text-sm text-mutedForeground">{meal.rating}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="bg-surface rounded-xl border border-border h-[600px] flex flex-col shadow-sm">
            <div className="p-6 border-b border-border">
              <h2 className="text-xl font-semibold text-foreground">Group Chat</h2>
              <p className="text-sm text-mutedForeground">Moab Adventure Trip</p>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4">
              {messages.map((message) => (
                <div
                  key={message.id}
                  className={`flex gap-3 ${message.sender === currentUser ? 'flex-row-reverse' : ''}`}
                >
                  <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0">
                    <span className="text-primaryForeground text-xs font-medium">
                      {message.sender.split(' ').map(n => n[0]).join('')}
                    </span>
                  </div>
                  <div className={`max-w-xs lg:max-w-md ${message.sender === currentUser ? 'text-right' : ''}`}>
                    <div className={`rounded-2xl px-4 py-2 transition-all duration-200 ${
                      message.sender === currentUser
                        ? 'bg-primary text-primaryForeground'
                        : 'bg-muted text-foreground'
                    }`}>
                      <p>{message.content}</p>
                    </div>
                    <p className="text-xs text-mutedForeground mt-1">
                      {message.sender} • {message.timestamp}
                    </p>
                  </div>
                </div>
              ))}
            </div>

            <div className="p-6 border-t border-border">
              <div className="flex gap-3">
                <input
                  type="text"
                  placeholder="Type a message..."
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                  className="flex-1 px-4 py-2 bg-muted border border-border rounded-xl text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 transition-all duration-200"
                  aria-label="Type your message"
                />
                <button
                  onClick={handleSendMessage}
                  disabled={!newMessage.trim()}
                  className="px-6 py-2 bg-primary text-primaryForeground rounded-xl hover:bg-primary/90 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  aria-label="Send message"
                >
                  Send
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'calendar' && (
          <div className="bg-surface rounded-xl border border-border p-6 shadow-sm">
            <h2 className="text-2xl font-bold text-foreground mb-6">Trip Calendar</h2>

            <div className="grid grid-cols-7 gap-1 mb-4">
              {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => (
                <div key={day} className="p-2 text-center text-sm font-medium text-mutedForeground">
                  {day}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-7 gap-1">
              {Array.from({ length: 35 }, (_, i) => {
                const day = i - 5
                const isCurrentMonth = day > 0 && day <= 31
                const isSelected = day >= 15 && day <= 18

                return (
                  <button
                    key={i}
                    className={`aspect-square p-2 text-center text-sm border border-border rounded transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring ${
                      isCurrentMonth
                        ? isSelected
                          ? 'bg-primary text-primaryForeground font-medium shadow-md'
                          : 'text-foreground hover:bg-muted hover:border-ring'
                        : 'text-mutedForeground cursor-not-allowed'
                    }`}
                    disabled={!isCurrentMonth}
                    aria-label={isCurrentMonth ? `Day ${day}` : 'Not in current month'}
                  >
                    {isCurrentMonth ? day : ''}
                  </button>
                )
              })}
            </div>

            <div className="mt-6 p-4 bg-primary/10 rounded-lg border border-primary/20">
              <h3 className="font-medium text-primary mb-2">Upcoming Trip</h3>
              <p className="text-foreground">Moab Adventure - March 15-18, 2024</p>
              <p className="text-sm text-mutedForeground">4 days • 8 participants</p>
            </div>
          </div>
        )}
      </main>
    </div>
  )
}

