Here's the polished React component with all improvements applied:

'use client'

import { useState, useEffect } from 'react'
import { 
  MapPin, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  CheckSquare,
  Plus,
  Search,
  Filter,
  Star,
  Navigation,
  Compass,
  Mountain,
  Trees,
  Sun,
  Cloud,
  CloudRain,
  Wind,
  Thermometer,
  Loader2,
  AlertCircle,
  X
} from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  participants: number
  status: 'planning' | 'confirmed' | 'completed'
  difficulty: 'easy' | 'moderate' | 'hard'
  terrain: 'desert' | 'forest' | 'mountain' | 'coastal'
  weather: {
    temp: number
    condition: 'sunny' | 'cloudy' | 'rainy' | 'windy'
    humidity: number
  }
}

interface Task {
  id: string
  title: string
  assignee: string
  category: 'food' | 'equipment' | 'logistics' | 'safety'
  completed: boolean
  dueDate: string
}

interface Message {
  id: string
  sender: string
  content: string
  timestamp: string
  type: 'text' | 'location' | 'image'
}

interface OffRoadPlannerProps {
  initialTrips?: Trip[]
  currentUser?: string
  onTripCreate?: (trip: Omit<Trip, 'id'>) => void
  onTaskAssign?: (task: Omit<Task, 'id'>) => void
  onMessageSend?: (message: Omit<Message, 'id' | 'timestamp'>) => void
}

export function OffRoadPlanner({
  initialTrips = DEFAULT_TRIPS,
  currentUser = 'John Doe',
  onTripCreate = () => console.log('Trip created'),
  onTaskAssign = () => console.log('Task assigned'),
  onMessageSend = () => console.log('Message sent')
}: OffRoadPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState<'trips' | 'tasks' | 'chat' | 'menu'>('trips')
  const [trips, setTrips] = useState<Trip[]>(initialTrips)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [searchQuery, setSearchQuery] = useState('')
  const [showNewTripModal, setShowNewTripModal] = useState(false)
  const [newMessage, setNewMessage] = useState('')
  const [selectedTrip, setSelectedTrip] = useState<Trip | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newTrip, setNewTrip] = useState({
    name: '',
    location: '',
    startDate: '',
    endDate: ''
  })

  const filteredTrips = trips.filter(trip =>
    trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    trip.location.toLowerCase().includes(searchQuery.toLowerCase())
  )

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return <Sun className="w-4 h-4 text-amber-500 dark:text-amber-400" />
      case 'cloudy': return <Cloud className="w-4 h-4 text-gray-500 dark:text-gray-400" />
      case 'rainy': return <CloudRain className="w-4 h-4 text-blue-500 dark:text-blue-400" />
      case 'windy': return <Wind className="w-4 h-4 text-gray-600 dark:text-gray-300" />
      default: return <Sun className="w-4 h-4 text-amber-500 dark:text-amber-400" />
    }
  }

  const getTerrainIcon = (terrain: string) => {
    switch (terrain) {
      case 'mountain': return <Mountain className="w-4 h-4 text-gray-700 dark:text-gray-300" />
      case 'forest': return <Trees className="w-4 h-4 text-green-600 dark:text-green-400" />
      case 'desert': return <Sun className="w-4 h-4 text-orange-500 dark:text-orange-400" />
      default: return <Compass className="w-4 h-4 text-primary dark:text-primary" />
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300 border-green-200 dark:border-green-700'
      case 'moderate': return 'bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-700'
      case 'hard': return 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-300 border-red-200 dark:border-red-700'
      default: return 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground border-border dark:border-border'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300'
      case 'planning': return 'bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-300'
      case 'completed': return 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-300'
      default: return 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground'
    }
  }

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      const message: Message = {
        id: Date.now().toString(),
        sender: currentUser,
        content: newMessage,
        timestamp: new Date().toISOString(),
        type: 'text'
      }
      setMessages([...messages, message])
      onMessageSend(message)
      setNewMessage('')
    }
  }

  const toggleTaskComplete = (taskId: string) => {
    setTasks(tasks.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const handleCreateTrip = async () => {
    if (!newTrip.name || !newTrip.location || !newTrip.startDate || !newTrip.endDate) {
      setError('Please fill in all required fields')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const trip: Trip = {
        id: Date.now().toString(),
        name: newTrip.name,
        location: newTrip.location,
        startDate: newTrip.startDate,
        endDate: newTrip.endDate,
        participants: 1,
        status: 'planning',
        difficulty: 'moderate',
        terrain: 'forest',
        weather: { temp: 75, condition: 'sunny', humidity: 45 }
      }

      setTrips([...trips, trip])
      onTripCreate(trip)
      setShowNewTripModal(false)
      setNewTrip({ name: '', location: '', startDate: '', endDate: '' })
    } catch (err) {
      setError('Failed to create trip. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const LoadingSkeleton = () => (
    <div className="space-y-6 animate-pulse">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="bg-white dark:bg-surface border border-border dark:border-border rounded-xl p-6">
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 bg-gray-200 dark:bg-gray-700 rounded"></div>
              <div className="h-5 bg-gray-200 dark:bg-gray-700 rounded w-32"></div>
            </div>
            <div className="h-6 bg-gray-200 dark:bg-gray-700 rounded w-16"></div>
          </div>
          <div className="space-y-3">
            <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2"></div>
            <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-2/3"></div>
          </div>
        </div>
      ))}
    </div>
  )

  const EmptyState = ({ icon: Icon, title, description }: { icon: any, title: string, description: string }) => (
    <div className="text-center py-12">
      <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
        <Icon className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
      </div>
      <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">{title}</h3>
      <p className="text-mutedForeground dark:text-mutedForeground text-sm">{description}</p>
    </div>
  )

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans transition-colors duration-200">
      {/* Header */}
      <div className="bg-surface dark:bg-surface border-b border-border dark:border-border sticky top-0 z-50 backdrop-blur-md bg-opacity-95 dark:bg-opacity-95">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center shadow-sm">
                <Navigation className="w-5 h-5 text-primaryForeground" />
              </div>
              <h1 className="text-xl font-bold text-foreground dark:text-foreground">TrailPlan</h1>
            </div>
            <button
              onClick={() => setShowNewTripModal(true)}
              className="px-4 py-2 bg-primary hover:bg-primary/90 active:bg-primary/80 text-primaryForeground rounded-lg transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label="Create new trip"
            >
              <Plus className="w-4 h-4" />
              New Trip
            </button>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="bg-surface dark:bg-surface border-b border-border dark:border-border">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex space-x-8 overflow-x-auto">
            {[
              { id: 'trips', label: 'Trips', icon: MapPin },
              { id: 'tasks', label: 'Tasks', icon: CheckSquare },
              { id: 'chat', label: 'Chat', icon: MessageCircle },
              { id: 'menu', label: 'Menu', icon: UtensilsCrossed }
            ].map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                onClick={() => setActiveTab(id as any)}
                className={`flex items-center gap-2 py-4 px-2 border-b-2 font-medium text-sm transition-all duration-150 hover:scale-[1.02] ${
                  activeTab === id
                    ? 'border-primary text-primary'
                    : 'border-transparent text-mutedForeground hover:text-foreground hover:border-border'
                }`}
                aria-label={`Switch to ${label} tab`}
              >
                <Icon className="w-4 h-4" />
                {label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Trips Tab */}
        {activeTab === 'trips' && (
          <div className="space-y-6">
            {/* Search and Filter */}
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-mutedForeground w-4 h-4" />
                <input
                  type="text"
                  placeholder="Search trips or locations..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  aria-label="Search trips"
                />
              </div>
              <button 
                className="px-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl hover:bg-muted dark:hover:bg-muted transition-all duration-150 flex items-center gap-2 text-foreground dark:text-foreground hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50"
                aria-label="Filter trips"
              >
                <Filter className="w-4 h-4" />
                Filter
              </button>
            </div>

            {/* Trip Cards */}
            {isLoading ? (
              <LoadingSkeleton />
            ) : filteredTrips.length === 0 ? (
              <EmptyState 
                icon={MapPin} 
                title="No trips found" 
                description="Create your first adventure or adjust your search filters"
              />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredTrips.map((trip) => (
                  <div
                    key={trip.id}
                    onClick={() => setSelectedTrip(trip)}
                    className="bg-surface dark:bg-surface border border-border dark:border-border rounded-xl p-6 hover:border-ring hover:shadow-xl hover:-translate-y-1 transition-all duration-300 cursor-pointer group focus:outline-none focus:ring-2 focus:ring-ring/50"
                    role="button"
                    tabIndex={0}
                    aria-label={`View details for ${trip.name}`}
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center gap-2">
                        {getTerrainIcon(trip.terrain)}
                        <h3 className="font-semibold text-foreground dark:text-foreground group-hover:text-primary transition-colors">
                          {trip.name}
                        </h3>
                      </div>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getDifficultyColor(trip.difficulty)}`}>
                        {trip.difficulty}
                      </span>
                    </div>

                    <div className="space-y-3">
                      <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground">
                        <MapPin className="w-4 h-4" />
                        <span className="text-sm">{trip.location}</span>
                      </div>

                      <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground">
                        <Calendar className="w-4 h-4" />
                        <span className="text-sm">
                          {new Date(trip.startDate).toLocaleDateString()} - {new Date(trip.endDate).toLocaleDateString()}
                        </span>
                      </div>

                      <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground">
                        <Users className="w-4 h-4" />
                        <span className="text-sm">{trip.participants} participants</span>
                      </div>

                      <div className="flex items-center justify-between pt-2">
                        <div className="flex items-center gap-2">
                          {getWeatherIcon(trip.weather.condition)}
                          <span className="text-sm text-mutedForeground dark:text-mutedForeground">{trip.weather.temp}°F</span>
                        </div>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(trip.status)}`}>
                          {trip.status}
