Looking at this React component, I'll polish it to follow the design system and modern best practices. Here's the improved version:

'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Mountain, Plus, X } from 'lucide-react'

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard' | 'expert'
  tags: string[]
}

interface CreateTripFormProps {
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {},
  isLoading = false
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    ...initialData
  })

  const [newTag, setNewTag] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const difficultyOptions = [
    { 
      value: 'easy', 
      label: 'Easy', 
      color: 'bg-green-500 dark:bg-green-400', 
      description: 'Beginner friendly' 
    },
    { 
      value: 'moderate', 
      label: 'Moderate', 
      color: 'bg-accent dark:bg-accent', 
      description: 'Some experience needed' 
    },
    { 
      value: 'hard', 
      label: 'Hard', 
      color: 'bg-secondary dark:bg-secondary', 
      description: 'Experienced drivers' 
    },
    { 
      value: 'expert', 
      label: 'Expert', 
      color: 'bg-destructive dark:bg-destructive', 
      description: 'Expert level only' 
    }
  ]

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const handleInputChange = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const addTag = () => {
    if (newTag.trim() && !formData.tags.includes(newTag.trim())) {
      handleInputChange('tags', [...formData.tags, newTag.trim()])
      setNewTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    handleInputChange('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      addTag()
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-2xl mx-auto px-4 sm:px-6 py-8">
        <div className="bg-surface/85 dark:bg-surface/85 backdrop-blur-md border border-border dark:border-border rounded-2xl shadow-lg hover:shadow-xl transition-all duration-300">
          <div className="p-6 sm:p-8">
            {/* Header */}
            <div className="flex items-center gap-3 mb-8">
              <div className="p-3 bg-gradient-to-br from-primary to-secondary rounded-xl shadow-sm">
                <Mountain className="w-6 h-6 text-primaryForeground" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-foreground dark:text-foreground">
                  Create Off-Road Trip
                </h1>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">
                  Plan your next adventure
                </p>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Trip Name */}
              <div>
                <label htmlFor="name" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Trip Name *
                </label>
                <input
                  id="name"
                  type="text"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder="e.g., Moab Desert Adventure"
                  className={`w-full px-4 py-3 bg-muted/50 dark:bg-muted/50 border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50 ${
                    errors.name 
                      ? 'border-destructive dark:border-destructive' 
                      : 'border-border dark:border-border focus:border-ring dark:focus:border-ring'
                  }`}
                  aria-describedby={errors.name ? 'name-error' : undefined}
                />
                {errors.name && (
                  <p id="name-error" className="mt-2 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.name}
                  </p>
                )}
              </div>

              {/* Location */}
              <div>
                <label htmlFor="location" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  <MapPin className="w-4 h-4 inline mr-1" />
                  Location *
                </label>
                <input
                  id="location"
                  type="text"
                  value={formData.location}
                  onChange={(e) => handleInputChange('location', e.target.value)}
