                  />
                  <button
                    type="button"
                    onClick={addTag}
                    className="px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-xl hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 shadow-sm hover:shadow-md"
                    aria-label="Add tag"
                  >
                    <Plus className="w-5 h-5" />
                  </button>
                </div>
                {formData.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {formData.tags.map((tag, index) => (
                      <span
                        key={index}
                        className="inline-flex items-center gap-1 px-3 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-full text-sm border border-border dark:border-border hover:bg-muted/80 dark:hover:bg-muted/80 transition-colors duration-200"
                      >
                        {tag}
                        <button
                          type="button"
                          onClick={() => removeTag(tag)}
                          className="text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive transition-colors duration-200 focus:outline-none focus:ring-1 focus:ring-ring/50 dark:focus:ring-ring/50 rounded"
                          aria-label={`Remove ${tag} tag`}
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}
              </div>

              {/* Description */}
              <div>
                <label htmlFor="description" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Description
                </label>
                <textarea
                  id="description"
                  rows={4}
                  value={formData.description}
                  onChange={(e) => handleInputChange('description', e.target.value)}
                  placeholder="Describe your trip, what to expect, what to bring..."
                  className="w-full px-4 py-3 bg-muted/50 dark:bg-muted/50 border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 focus:border-ring dark:focus:border-ring transition-all duration-200 resize-none hover:border-ring/50 dark:hover:border-ring/50"
                />
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-4 bg-gradient-to-r from-primary to-secondary text-primaryForeground font-medium rounded-xl hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center gap-2">
                    <div className="w-5 h-5 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                    Creating Trip...
                  </div>
                ) : (
                  'Create Trip'
                )}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  )
}

