'use client'

import { useState, useEffect } from 'react'
import { Send, Calendar, MapPin, Users, Clock, Check, X, Mail, MessageSquare } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  avatar?: string
  status: 'pending' | 'accepted' | 'declined'
  rsvpDate?: string
}

interface TripDetails {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  description: string
  organizer: string
}

interface TripInviteSystemProps {
  tripDetails?: TripDetails
  members?: TripMember[]
  onInviteSent?: (emails: string[]) => void
  onRsvpUpdate?: (memberId: string, status: 'accepted' | 'declined') => void
  onRemindMembers?: (memberIds: string[]) => void
}

export function TripInviteSystem({
  tripDetails = DEFAULT_TRIP,
  members = DEFAULT_MEMBERS,
  onInviteSent = () => console.log('Invites sent'),
  onRsvpUpdate = () => console.log('RSVP updated'),
  onRemindMembers = () => console.log('Reminders sent')
}: TripInviteSystemProps = {}) {
  const [inviteEmails, setInviteEmails] = useState('')
  const [isInviting, setIsInviting] = useState(false)
  const [showInviteForm, setShowInviteForm] = useState(false)
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [inviteMessage, setInviteMessage] = useState(DEFAULT_INVITE_MESSAGE)
  const [error, setError] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const pendingMembers = members.filter(m => m.status === 'pending')
  const acceptedMembers = members.filter(m => m.status === 'accepted')
  const declinedMembers = members.filter(m => m.status === 'declined')

  const handleSendInvites = async () => {
    if (!inviteEmails.trim()) {
      setError('Please enter at least one email address')
      return
    }

    setIsInviting(true)
    setError('')
    const emails = inviteEmails.split(',').map(email => email.trim()).filter(Boolean)

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1500))

      onInviteSent(emails)
      setInviteEmails('')
      setShowInviteForm(false)
    } catch (err) {
      setError('Failed to send invites. Please try again.')
    } finally {
      setIsInviting(false)
    }
  }

  const handleRsvp = async (memberId: string, status: 'accepted' | 'declined') => {
    setIsLoading(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 500))
      onRsvpUpdate(memberId, status)
    } catch (err) {
      setError('Failed to update RSVP. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleSendReminders = async () => {
    if (selectedMembers.length === 0) return

    setIsLoading(true)
    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onRemindMembers(selectedMembers)
      setSelectedMembers([])
    } catch (err) {
      setError('Failed to send reminders. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-muted dark:from-background dark:to-muted p-4 font-sans">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Error State */}
        {error && (
          <div className="rounded-lg bg-destructive/10 dark:bg-destructive/20 border border-destructive/20 dark:border-destructive/30 p-4 transition-all duration-300">
            <p className="text-sm text-destructive dark:text-destructive font-medium">{error}</p>
          </div>
        )}

        {/* Trip Overview Card */}
        <div className="bg-surface dark:bg-surface rounded-xl p-6 shadow-md hover:shadow-lg dark:shadow-xl transition-all duration-300 border border-border dark:border-border hover:-translate-y-0.5">
          <div className="flex items-start justify-between mb-4">
            <div className="flex-1">
              <h1 className="text-2xl font-bold text-foreground dark:text-foreground mb-2">{tripDetails.title}</h1>
              <div className="flex flex-wrap gap-4 text-sm text-mutedForeground dark:text-mutedForeground">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-primary dark:text-primary" />
                  <span>{tripDetails.location}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4 text-primary dark:text-primary" />
                  <span>{new Date(tripDetails.startDate).toLocaleDateString()} - {new Date(tripDetails.endDate).toLocaleDateString()}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Users className="w-4 h-4 text-primary dark:text-primary" />
                  <span>{members.length} invited</span>
                </div>
              </div>
            </div>
            <button
              onClick={() => setShowInviteForm(!showInviteForm)}
              className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background flex items-center gap-2"
              aria-label="Invite new members"
            >
              <Send className="w-4 h-4" />
              Invite
            </button>
          </div>

          {/* Invite Form */}
          {showInviteForm && (
            <div className="border-t border-border dark:border-border pt-4 space-y-4 animate-in slide-in-from-top-2 duration-300">
              <div>
                <label htmlFor="invite-emails" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Email addresses (comma separated)
                </label>
                <input
                  id="invite-emails"
                  type="text"
                  value={inviteEmails}
                  onChange={(e) => {
                    setInviteEmails(e.target.value)
                    setError('')
                  }}
                  placeholder="john@example.com, jane@example.com"
                  className="w-full px-4 py-2.5 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                />
              </div>

              <div>
                <label htmlFor="invite-message" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
