                >
                  {isInviting ? (
                    <>
                      <div className="w-4 h-4 border-2 border-primaryForeground dark:border-primaryForeground border-t-transparent rounded-full animate-spin" />
                      Sending...
                    </>
                  ) : (
                    <>
                      <Mail className="w-4 h-4" />
                      Send Invites
                    </>
                  )}
                </button>
                <button
                  onClick={() => setShowInviteForm(false)}
                  className="px-4 py-2 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-lg hover:bg-muted/80 dark:hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm min-h-[44px] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                >
                  Cancel
                </button>
              </div>
            </div>
          )}
        </div>

        {/* RSVP Status Overview */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="bg-surface dark:bg-surface rounded-xl p-4 shadow-md hover:shadow-lg dark:shadow-xl border border-border dark:border-border hover:-translate-y-0.5 transition-all duration-300">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-mutedForeground dark:text-mutedForeground">Accepted</p>
                <p className="text-2xl font-bold text-green-600 dark:text-green-400">{acceptedMembers.length}</p>
              </div>
              <div className="w-12 h-12 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center">
                <Check className="w-6 h-6 text-green-600 dark:text-green-400" />
              </div>
            </div>
          </div>

          <div className="bg-surface dark:bg-surface rounded-xl p-4 shadow-md hover:shadow-lg dark:shadow-xl border border-border dark:border-border hover:-translate-y-0.5 transition-all duration-300">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-mutedForeground dark:text-mutedForeground">Pending</p>
