              <div className="w-12 h-12 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center">
                <X className="w-6 h-6 text-destructive dark:text-destructive" />
              </div>
            </div>
          </div>
        </div>

        {/* Member List */}
        <div className="bg-surface dark:bg-surface rounded-xl p-6 shadow-md hover:shadow-lg dark:shadow-xl border border-border dark:border-border hover:-translate-y-0.5 transition-all duration-300">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-foreground dark:text-foreground">Trip Members</h2>
            {pendingMembers.length > 0 && (
              <button
                onClick={handleSendReminders}
                disabled={selectedMembers.length === 0 || isLoading}
                className="px-4 py-2 bg-secondary dark:bg-secondary text-secondaryForeground dark:text-secondaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] disabled:bg-mutedForeground/30 dark:disabled:bg-mutedForeground/30 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background flex items-center gap-2 min-h-[44px]"
              >
                {isLoading ? (
