                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-3">
              {members.map((member) => (
                <div
                  key={member.id}
                  className="flex items-center justify-between p-4 bg-muted/50 dark:bg-muted/50 rounded-xl border border-border/50 dark:border-border/50 hover:border-primary/30 dark:hover:border-primary/30 hover:bg-muted/70 dark:hover:bg-muted/70 transition-all duration-200"
                >
                  <div className="flex items-center gap-3 flex-1">
                    {member.status === 'pending' && (
                      <input
                        type="checkbox"
                        checked={selectedMembers.includes(member.id)}
                        onChange={() => toggleMemberSelection(member.id)}
                        className="w-4 h-4 text-primary dark:text-primary border-border dark:border-border rounded focus:ring-ring dark:focus:ring-ring focus:ring-2 transition-all duration-150"
                        aria-label={`Select ${member.name} for reminder`}
                      />
                    )}

                    <div className="w-10 h-10 bg-gradient-to-br from-primary to-accent dark:from-primary dark:to-accent rounded-full flex items-center justify-center text-primaryForeground dark:text-primaryForeground font-medium text-sm">
                      {member.avatar ? (
                        <img 
                          src={member.avatar} 
                          alt={`${member.name}'s avatar`} 
                          className="w-full h-full rounded-full object-cover" 
                        />
                      ) : (
                        member.name.charAt(0).toUpperCase()
                      )}
                    </div>

                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-foreground dark:text-foreground truncate">{member.name}</p>
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground truncate">{member.email}</p>
                      {member.rsvpDate && (
                        <p className="text-xs text-mutedForeground/70 dark:text-mutedForeground/70">
                          Responded {new Date(member.rsvpDate).toLocaleDateString()}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {member.status === 'pending' && (
                      <>
                        <button
                          onClick={() => handleRsvp(member.id, 'accepted')}
                          disabled={isLoading}
                          className="p-2 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-lg hover:bg-green-200 dark:hover:bg-green-900/50 hover:scale-[1.05] active:scale-[0.95] transition-all duration-150 min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-green-500/50 dark:focus:ring-green-400/50"
                          aria-label={`Mark ${member.name} as accepted`}
                        >
                          <Check className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => handleRsvp(member.id, 'declined')}
                          disabled={isLoading}
                          className="p-2 bg-red-100 dark:bg-red-900/30 text-destructive dark:text-destructive rounded-lg hover:bg-red-200 dark:hover:bg-red-900/50 hover:scale-[1.05] active:scale-[0.95] transition-all duration-150 min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-destructive/50 dark:focus:ring-destructive/50"
                          aria-label={`Mark ${member.name} as declined`}
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </>
                    )}

                    {member.status !== 'pending' && (
                      <div className={`px-3 py-1 rounded-full text-xs font-medium border transition-all duration-150 ${
                        member.status === 'accepted' 
                          ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 border-green-200 dark:border-green-800'
                          : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 border-red-200 dark:border-red-800'
                      }`}>
                        {member.status === 'accepted' ? 'Going' : 'Can\'t make it'}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Empty State */}
          {members.length === 0 && !isLoading && (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
              </div>
              <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No members invited yet</h3>
              <p className="text-mutedForeground dark:text-mutedForeground text-sm">Click "Invite" to add people to your trip</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

