'use client'

import { useState, useEffect, useRef } from 'react'
import { Users, UserPlus, Crown, MapPin, Calendar, MessageSquare, Settings, Search, Filter, MoreVertical, UserMinus, Shield } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'organizer' | 'member'
  status: 'confirmed' | 'pending' | 'declined'
  joinedAt: string
  skills: string[]
  emergencyContact?: {
    name: string
    phone: string
  }
}

interface TripMemberManagementProps {
  tripId?: string
  members?: TripMember[]
  currentUserId?: string
  onInviteMember?: (email: string) => void
  onRemoveMember?: (memberId: string) => void
  onUpdateRole?: (memberId: string, role: 'organizer' | 'member') => void
  onUpdateStatus?: (memberId: string, status: TripMember['status']) => void
}

export function TripMemberManagement({
  tripId = 'trip-1',
  members = DEFAULT_MEMBERS,
  currentUserId = 'user-1',
  onInviteMember = (email: string) => console.log('Invite member:', email),
  onRemoveMember = (memberId: string) => console.log('Remove member:', memberId),
  onUpdateRole = (memberId: string, role: string) => console.log('Update role:', memberId, role),
  onUpdateStatus = (memberId: string, status: string) => console.log('Update status:', memberId, status)
}: TripMemberManagementProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [filterStatus, setFilterStatus] = useState<'all' | 'confirmed' | 'pending' | 'declined'>('all')
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [inviteEmail, setInviteEmail] = useState('')
  const [selectedMember, setSelectedMember] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isInitialLoading, setIsInitialLoading] = useState(true)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // Simulate initial loading
  useEffect(() => {
    const timer = setTimeout(() => setIsInitialLoading(false), 800)
    return () => clearTimeout(timer)
  }, [])

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setSelectedMember(null)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const filteredMembers = members.filter(member => {
    const matchesSearch = member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         member.email.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesFilter = filterStatus === 'all' || member.status === filterStatus
    return matchesSearch && matchesFilter
  })

  const handleInvite = async () => {
    if (!inviteEmail.trim()) return

    setIsLoading(true)
    setError(null)

    try {
      // Email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
      if (!emailRegex.test(inviteEmail)) {
        throw new Error('Please enter a valid email address')
      }

      await onInviteMember(inviteEmail)
      setInviteEmail('')
      setShowInviteModal(false)
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to invite member')
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusColor = (status: TripMember['status']) => {
    switch (status) {
      case 'confirmed': return 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 border-green-200 dark:border-green-800'
      case 'pending': return 'bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300 border-amber-200 dark:border-amber-800'
      case 'declined': return 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 border-red-200 dark:border-red-800'
      default: return 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground border-border dark:border-border'
    }
  }

  const currentUser = members.find(m => m.id === currentUserId)
  const isOrganizer = currentUser?.role === 'organizer'

  // Loading skeleton component
  const LoadingSkeleton = () => (
    <div className="space-y-3 animate-pulse">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-muted dark:bg-muted rounded-full"></div>
            <div className="flex-1 space-y-2">
              <div className="h-4 bg-muted dark:bg-muted rounded w-1/3"></div>
              <div className="h-3 bg-muted dark:bg-muted rounded w-1/2"></div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-background font-sans">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="bg-surface dark:bg-surface rounded-2xl shadow-lg border border-border dark:border-border p-6 mb-6">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 bg-muted dark:bg-muted rounded-xl animate-pulse"></div>
              <div className="space-y-2">
                <div className="h-6 bg-muted dark:bg-muted rounded w-32 animate-pulse"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-48 animate-pulse"></div>
              </div>
            </div>
            <div className="flex gap-3">
              <div className="flex-1 h-10 bg-muted dark:bg-muted rounded-xl animate-pulse"></div>
              <div className="w-32 h-10 bg-muted dark:bg-muted rounded-xl animate-pulse"></div>
            </div>
          </div>
          <LoadingSkeleton />
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header */}
        <div className="bg-surface dark:bg-surface rounded-2xl shadow-lg border border-border dark:border-border p-6 mb-6 hover:shadow-xl transition-all duration-300">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-gradient-to-br from-primary to-secondary rounded-xl shadow-md">
                <Users className="w-6 h-6 text-primaryForeground" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-foreground dark:text-foreground">Trip Members</h1>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">Manage your adventure crew</p>
              </div>
            </div>
            {isOrganizer && (
              <button
                onClick={() => setShowInviteModal(true)}
                className="flex items-center gap-2 px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-xl hover:bg-primary/90 dark:hover:bg-primary/90 transition-all duration-200 font-medium shadow-md hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                aria-label="Invite new member to the trip"
              >
                <UserPlus className="w-4 h-4" />
                <span className="hidden sm:inline">Invite</span>
              </button>
            )}
          </div>

          {/* Search and Filter */}
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
              <input
                type="text"
                placeholder="Search members..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-background dark:bg-background border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                aria-label="Search trip members"
              />
            </div>
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as any)}
                className="pl-10 pr-8 py-2.5 bg-background dark:bg-background border border-border dark:border-border rounded-xl text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 appearance-none cursor-pointer"
                aria-label="Filter members by status"
              >
                <option value="all">All Status</option>
                <option value="confirmed">Confirmed</option>
                <option value="pending">Pending</option>
                <option value="declined">Declined</option>
              </select>
            </div>
          </div>
        </div>

        {/* Members List */}
        <div className="space-y-3">
          {filteredMembers.map((member) => (
            <div
              key={member.id}
              className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border hover:border-ring/50 dark:hover:border-ring/50 transition-all duration-200 shadow-sm hover:shadow-md hover:-translate-y-0.5"
            >
              <div className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="relative">
                      <div className="w-12 h-12 bg-gradient-to-br from-primary to-secondary rounded-full flex items-center justify-center text-primaryForeground font-bold text-lg shadow-md">
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                      {member.role === 'organizer' && (
                        <div className="absolute -top-1 -right-1 w-5 h-5 bg-accent dark:bg-accent rounded-full flex items-center justify-center shadow-sm">
                          <Crown className="w-3 h-3 text-accentForeground dark:text-accentForeground" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-semibold text-foreground dark:text-foreground truncate">{member.name}</h3>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(member.status)}`}>
                          {member.status}
