                      </div>
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground truncate">{member.email}</p>
                      {member.skills.length > 0 && (
                        <div className="flex flex-wrap gap-1 mt-2">
                          {member.skills.slice(0, 3).map((skill, index) => (
                            <span
                              key={index}
                              className="px-2 py-1 bg-primary/10 dark:bg-primary/20 text-primary dark:text-primary rounded-md text-xs font-medium"
                            >
                              {skill}
                            </span>
                          ))}
                          {member.skills.length > 3 && (
                            <span className="px-2 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-md text-xs">
                              +{member.skills.length - 3}
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                  </div>

                  {isOrganizer && member.id !== currentUserId && (
                    <div className="relative" ref={dropdownRef}>
                      <button
                        onClick={() => setSelectedMember(selectedMember === member.id ? null : member.id)}
                        className="p-2 hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                        aria-label={`Options for ${member.name}`}
                      >
                        <MoreVertical className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
                      </button>

                      {selectedMember === member.id && (
                        <div className="absolute right-0 top-full mt-1 w-48 bg-surface dark:bg-surface border border-border dark:border-border rounded-lg shadow-lg z-10 animate-in slide-in-from-top-2 duration-200">
                          <div className="py-1">
                            <button
                              onClick={() => {
                                onUpdateRole(member.id, member.role === 'organizer' ? 'member' : 'organizer')
                                setSelectedMember(null)
                              }}
                              className="w-full px-4 py-2 text-left text-sm text-foreground dark:text-foreground hover:bg-muted dark:hover:bg-muted flex items-center gap-2 transition-colors duration-150"
                              aria-label={`${member.role === 'organizer' ? 'Remove admin role from' : 'Make admin'} ${member.name}`}
                            >
                              <Shield className="w-4 h-4" />
                              {member.role === 'organizer' ? 'Remove Admin' : 'Make Admin'}
                            </button>
                            <button
                              onClick={() => {
                                onRemoveMember(member.id)
                                setSelectedMember(null)
                              }}
                              className="w-full px-4 py-2 text-left text-sm text-destructive dark:text-destructive hover:bg-destructive/10 dark:hover:bg-destructive/10 flex items-center gap-2 transition-colors duration-150"
                              aria-label={`Remove ${member.name} from trip`}
                            >
                              <UserMinus className="w-4 h-4" />
                              Remove Member
                            </button>
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Empty State */}
        {filteredMembers.length === 0 && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-8 text-center">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-2">No members found</h3>
            <p className="text-mutedForeground dark:text-mutedForeground mb-4">
              {searchQuery || filterStatus !== 'all' 
                ? 'Try adjusting your search or filter criteria'
                : 'Start building your adventure crew by inviting members'
              }
            </p>
            {isOrganizer && !searchQuery && filterStatus === 'all' && (
              <button
                onClick={() => setShowInviteModal(true)}
                className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:bg-primary/90 dark:hover:bg-primary/90 transition-all duration-150 font-medium hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                aria-label="Invite first member to the trip"
              >
                Invite First Member
              </button>
            )}
          </div>
        )}

        {/* Invite Modal */}
        {showInviteModal && (
          <div className="fixed inset-0 bg-black/50 dark:bg-black/70 flex items-center justify-center p-4 z-50 animate-in fade-in duration-200">
            <div className="bg-surface dark:bg-surface rounded-2xl shadow-xl max-w-md w-full p-6 animate-in slide-in-from-bottom-4 duration-300">
              <div className="flex items-center gap-3 mb-4">
