export function RSVPFeature({
  tripId = 'trip-1',
  currentUserId = 'user-current',
  tripDetails = DEFAULT_TRIP,
  responses = DEFAULT_RESPONSES,
  onRSVP = (status, note) => console.log('RSVP:', status, note),
  onSendReminder = (userIds) => console.log('Send reminder to:', userIds),
  isLoading = false,
  error
}: RSVPFeatureProps = {}) {
  const [userResponse, setUserResponse] = useState<RSVPResponse['status']>('pending')
  const [responseNote, setResponseNote] = useState('')
  const [showNoteInput, setShowNoteInput] = useState(false)
  const [selectedUsers, setSelectedUsers] = useState<string[]>([])
  const [showReminders, setShowReminders] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const attendingCount = responses.filter(r => r.status === 'attending').length
  const maybeCount = responses.filter(r => r.status === 'maybe').length
  const notAttendingCount = responses.filter(r => r.status === 'not-attending').length
  const pendingCount = responses.filter(r => r.status === 'pending').length

  const currentUserResponse = responses.find(r => r.userId === currentUserId)

  useEffect(() => {
    if (currentUserResponse) {
      setUserResponse(currentUserResponse.status)
      setResponseNote(currentUserResponse.note || '')
    }
  }, [currentUserResponse])

  const handleRSVP = (status: RSVPResponse['status']) => {
    if (status === 'maybe' || status === 'not-attending') {
      setShowNoteInput(true)
    } else {
      setShowNoteInput(false)
      setResponseNote('')
    }
    setUserResponse(status)
  }

  const submitRSVP = async () => {
    setIsSubmitting(true)
    try {
      await onRSVP(userResponse, responseNote)
      setShowNoteInput(false)
    } finally {
      setIsSubmitting(false)
    }
  }

  const getStatusColor = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending':
        return 'text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800'
      case 'maybe':
        return 'text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800'
      case 'not-attending':
        return 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800'
      default:
        return 'text-gray-600 dark:text-gray-400 bg-muted dark:bg-muted border-border dark:border-border'
    }
  }

  const getStatusIcon = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'attending':
        return <Check className="w-4 h-4" />
      case 'maybe':
        return <Clock className="w-4 h-4" />
      case 'not-attending':
        return <X className="w-4 h-4" />
      default:
        return <Clock className="w-4 h-4" />
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  const pendingUsers = responses.filter(r => r.status === 'pending')

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-background">
        <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
          {/* Loading skeleton */}
          <div className="animate-pulse space-y-6">
            <div className="bg-surface dark:bg-surface rounded-2xl p-6 border border-border dark:border-border">
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 bg-muted dark:bg-muted rounded-xl"></div>
                <div className="flex-1 space-y-3">
                  <div className="h-8 bg-muted dark:bg-muted rounded w-3/4"></div>
                  <div className="h-4 bg-muted dark:bg-muted rounded w-1/2"></div>
                  <div className="h-4 bg-muted dark:bg-muted rounded w-2/3"></div>
                </div>
              </div>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="bg-surface dark:bg-surface rounded-xl p-4 border border-border dark:border-border">
                  <div className="h-8 bg-muted dark:bg-muted rounded mb-2"></div>
                  <div className="h-4 bg-muted dark:bg-muted rounded"></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        {/* Error State */}
        {error && (
          <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4">
            <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
          </div>
        )}

        {/* Trip Header */}
