              <MapPin className="w-6 h-6 text-primaryForeground" />
            </div>
            <div className="flex-1">
              <h1 className="text-2xl font-bold text-foreground dark:text-foreground mb-2">{tripDetails.title}</h1>
              <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 text-mutedForeground dark:text-mutedForeground">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4" />
                  <span className="font-medium">{tripDetails.location}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" />
                  <span>{formatDate(tripDetails.startDate)} - {formatDate(tripDetails.endDate)}</span>
                </div>
              </div>
              <p className="text-foreground dark:text-foreground mt-3 leading-relaxed">{tripDetails.description}</p>
              <p className="text-sm text-mutedForeground dark:text-mutedForeground mt-2">Organized by {tripDetails.organizer}</p>
            </div>
          </div>
        </div>

        {/* RSVP Stats */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-emerald-200 dark:border-emerald-800 hover:shadow-md hover:-translate-y-1 transition-all duration-300">
            <div className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{attendingCount}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Attending</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-amber-200 dark:border-amber-800 hover:shadow-md hover:-translate-y-1 transition-all duration-300">
            <div className="text-2xl font-bold text-amber-600 dark:text-amber-400">{maybeCount}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Maybe</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-red-200 dark:border-red-800 hover:shadow-md hover:-translate-y-1 transition-all duration-300">
            <div className="text-2xl font-bold text-red-600 dark:text-red-400">{notAttendingCount}</div>
