            <div className="text-2xl font-bold text-mutedForeground dark:text-mutedForeground">{pendingCount}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Pending</div>
          </div>
        </div>

        {/* User RSVP Section */}
        <div className="bg-surface dark:bg-surface rounded-2xl p-6 shadow-md hover:shadow-lg transition-all duration-300 border border-border dark:border-border">
