              onClick={() => handleRSVP('attending')}
              className={`p-4 rounded-xl border-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                userResponse === 'attending'
                  ? 'border-emerald-500 dark:border-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300'
                  : 'border-border dark:border-border hover:border-emerald-300 dark:hover:border-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/10'
              }`}
              aria-label="RSVP as attending"
            >
              <Check className="w-6 h-6 mx-auto mb-2" />
              <div className="font-medium">I'll be there!</div>
            </button>

            <button
              onClick={() => handleRSVP('maybe')}
              className={`p-4 rounded-xl border-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                userResponse === 'maybe'
                  ? 'border-amber-500 dark:border-amber-400 bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300'
                  : 'border-border dark:border-border hover:border-amber-300 dark:hover:border-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/10'
              }`}
              aria-label="RSVP as maybe"
            >
              <Clock className="w-6 h-6 mx-auto mb-2" />
              <div className="font-medium">Maybe</div>
            </button>

            <button
              onClick={() => handleRSVP('not-attending')}
              className={`p-4 rounded-xl border-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                userResponse === 'not-attending'
                  ? 'border-red-500 dark:border-red-400 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300'
                  : 'border-border dark:border-border hover:border-red-300 dark:hover:border-red-600 hover:bg-red-50 dark:hover:bg-red-900/10'
              }`}
              aria-label="RSVP as not attending"
            >
              <X className="w-6 h-6 mx-auto mb-2" />
              <div className="font-medium">Can't make it</div>
