                aria-label="Toggle reminder options"
              >
                <MessageCircle className="w-4 h-4" />
                <span className="text-sm font-medium">Send Reminders</span>
              </button>
            )}
          </div>

          {showReminders && pendingUsers.length > 0 && (
            <div className="mb-6 p-4 bg-primary/5 dark:bg-primary/10 rounded-xl border border-primary/20 dark:border-primary/30">
              <h3 className="font-medium text-foreground dark:text-foreground mb-3">Send reminder to:</h3>
              <div className="space-y-2 mb-4">
                {pendingUsers.map((user) => (
                  <label key={user.id} className="flex items-center gap-3 cursor-pointer hover:bg-primary/5 dark:hover:bg-primary/5 p-2 rounded-lg transition-colors duration-200">
                    <input
                      type="checkbox"
                      checked={selectedUsers.includes(user.userId)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedUsers([...selectedUsers, user.userId])
