                          setSelectedUsers(selectedUsers.filter(id => id !== user.userId))
                        }
                      }}
                      className="w-4 h-4 text-primary border-border dark:border-border rounded focus:ring-ring focus:ring-2"
                    />
                    <span className="text-foreground dark:text-foreground">{user.userName}</span>
