                        {response.userName.split(' ').map(n => n[0]).join('')}
                      </span>
                    </div>
                    <div>
                      <div className="font-medium text-foreground dark:text-foreground">{response.userName}</div>
                      {response.note && (
                        <div className="text-sm text-mutedForeground dark:text-mutedForeground mt-1">{response.note}</div>
                      )}
                      {response.responseDate && (
                        <div className="text-xs text-mutedForeground dark:text-mutedForeground mt-1">
