'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, Plus, Edit3, Trash2, ChefHat, MapPin, AlertCircle } from 'lucide-react'

interface Meal {
  id: string
  name: string
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack'
  date: string
  time: string
  assignedTo: string[]
  ingredients: string[]
  servings: number
  notes?: string
  location?: string
}

interface GroupMember {
  id: string
  name: string
  avatar?: string
  dietary?: string[]
}

interface MealPlannerViewProps {
  tripId?: string
  meals?: Meal[]
  groupMembers?: GroupMember[]
  onMealAdd?: (meal: Omit<Meal, 'id'>) => void
  onMealUpdate?: (id: string, meal: Partial<Meal>) => void
  onMealDelete?: (id: string) => void
}

const DEFAULT_MEALS: Meal[] = [
  {
    id: '1',
    name: 'Trail Mix Pancakes',
    type: 'breakfast',
    date: '2024-03-15',
    time: '08:00',
    assignedTo: ['1', '2'],
    ingredients: ['Pancake mix', 'Trail mix', 'Maple syrup', 'Coffee'],
    servings: 8,
    notes: 'Make extra for late risers',
    location: 'Base camp'
  },
  {
    id: '2',
    name: 'Campfire Chili',
    type: 'lunch',
    date: '2024-03-15',
    time: '12:30',
    assignedTo: ['3'],
    ingredients: ['Ground beef', 'Beans', 'Tomatoes', 'Spices', 'Bread'],
    servings: 8,
    location: 'Trail junction'
  },
  {
    id: '3',
    name: 'Grilled Fish & Vegetables',
    type: 'dinner',
    date: '2024-03-15',
    time: '18:00',
    assignedTo: ['1', '4'],
    ingredients: ['Fresh fish', 'Bell peppers', 'Zucchini', 'Seasoning'],
    servings: 8,
    location: 'Lakeside camp'
  }
]

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', dietary: ['pescatarian'] },
  { id: '2', name: 'Sarah Johnson', dietary: [] },
  { id: '3', name: 'Mike Rodriguez', dietary: ['gluten-free'] },
  { id: '4', name: 'Emma Davis', dietary: ['vegetarian'] }
]

export function MealPlannerView({
  tripId = 'trip-1',
  meals = DEFAULT_MEALS,
  groupMembers = DEFAULT_MEMBERS,
  onMealAdd = () => console.log('Add meal'),
  onMealUpdate = () => console.log('Update meal'),
  onMealDelete = () => console.log('Delete meal')
}: MealPlannerViewProps = {}) {
  const [selectedDate, setSelectedDate] = useState('2024-03-15')
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingMeal, setEditingMeal] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newMeal, setNewMeal] = useState<Partial<Meal>>({
    name: '',
    type: 'breakfast',
    date: selectedDate,
    time: '08:00',
    assignedTo: [],
    ingredients: [],
    servings: 4,
    notes: '',
    location: ''
  })

  const mealTypes = [
    { value: 'breakfast', label: 'Breakfast', icon: '🌅' },
    { value: 'lunch', label: 'Lunch', icon: '☀️' },
    { value: 'dinner', label: 'Dinner', icon: '🌙' },
    { value: 'snack', label: 'Snack', icon: '🥜' }
  ]

  const filteredMeals = meals.filter(meal => meal.date === selectedDate)
  const sortedMeals = filteredMeals.sort((a, b) => a.time.localeCompare(b.time))

  const getMemberName = (id: string) => {
    return groupMembers.find(member => member.id === id)?.name || 'Unknown'
  }

  const handleAddMeal = async () => {
    if (!newMeal.name || !newMeal.type) {
      setError('Please fill in all required fields')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      await onMealAdd({
        ...newMeal,
        assignedTo: newMeal.assignedTo || [],
        ingredients: newMeal.ingredients || [],
        servings: newMeal.servings || 4
      } as Omit<Meal, 'id'>)

      setNewMeal({
        name: '',
        type: 'breakfast',
        date: selectedDate,
        time: '08:00',
        assignedTo: [],
        ingredients: [],
        servings: 4,
        notes: '',
        location: ''
      })
      setShowAddForm(false)
    } catch (err) {
      setError('Failed to add meal. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleDeleteMeal = async (id: string) => {
    if (confirm('Are you sure you want to delete this meal?')) {
      setIsLoading(true)
      try {
        await onMealDelete(id)
      } catch (err) {
        setError('Failed to delete meal. Please try again.')
      } finally {
        setIsLoading(false)
      }
    }
  }

  const getMealTypeColor = (type: string) => {
    switch (type) {
      case 'breakfast': return 'bg-orange-100 dark:bg-orange-900/30 text-orange-800 dark:text-orange-200 border-orange-200 dark:border-orange-700'
      case 'lunch': return 'bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-200 border-amber-200 dark:border-amber-700'
      case 'dinner': return 'bg-orange-200 dark:bg-orange-800/30 text-orange-900 dark:text-orange-100 border-orange-300 dark:border-orange-600'
      case 'snack': return 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 border-yellow-200 dark:border-yellow-700'
      default: return 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground border-border dark:border-border'
    }
  }

  // Update newMeal date when selectedDate changes
  useEffect(() => {
    setNewMeal(prev => ({ ...prev, date: selectedDate }))
  }, [selectedDate])

  return (
    <div className="min-h-screen bg-gradient-to-br from-background via-muted to-background dark:from-background dark:via-muted dark:to-background font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2 flex items-center gap-3">
            <div className="p-2 bg-gradient-to-br from-primary to-secondary rounded-xl shadow-md">
              <ChefHat className="w-6 h-6 text-primaryForeground" />
            </div>
            Meal Planner
          </h1>
          <p className="text-mutedForeground dark:text-mutedForeground text-lg">Plan and organize meals for your off-road adventure</p>
        </div>

        {/* Error State */}
        {error && (
          <div className="mb-6 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 animate-in slide-in-from-top-2 duration-300">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400" />
              <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
            </div>
          </div>
        )}

        {/* Date Selector */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-8 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center gap-3 mb-4">
            <Calendar className="w-5 h-5 text-primary dark:text-primary" />
            <span className="font-semibold text-foreground dark:text-foreground">Select Date</span>
          </div>
          <div className="flex gap-2 overflow-x-auto pb-2">
            {['2024-03-15', '2024-03-16', '2024-03-17'].map(date => (
              <button
                key={date}
                onClick={() => setSelectedDate(date)}
                disabled={isLoading}
                className={`px-4 py-3 rounded-lg whitespace-nowrap transition-all duration-200 font-medium focus:outline-none focus:ring-2 focus:ring-ring/50 disabled:opacity-50 disabled:cursor-not-allowed ${
                  selectedDate === date
                    ? 'bg-gradient-to-r from-primary to-secondary text-primaryForeground shadow-md hover:shadow-lg active:scale-95'
                    : 'bg-muted dark:bg-muted text-foreground dark:text-foreground hover:bg-muted/80 dark:hover:bg-muted/80 hover:scale-[1.02] active:scale-98'
                }`}
                aria-label={`Select date ${date}`}
              >
                {new Date(date).toLocaleDateString('en-US', { 
                  weekday: 'short', 
                  month: 'short', 
                  day: 'numeric' 
                })}
              </button>
            ))}
          </div>
        </div>

        {/* Add Meal Button */}
        <div className="mb-8">
          <button
            onClick={() => setShowAddForm(true)}
            disabled={isLoading}
            className="w-full sm:w-auto px-6 py-3 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg transition-all duration-200 font-semibold flex items-center justify-center gap-2 shadow-md hover:scale-[1.02] active:scale-98 focus:outline-none focus:ring-2 focus:ring-ring/50 disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Add new meal"
          >
            <Plus className="w-5 h-5" />
            Add Meal
          </button>
        </div>

        {/* Add Meal Form */}
        {showAddForm && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-8 shadow-lg animate-in slide-in-from-top-4 duration-300">
            <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-6">Add New Meal</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Meal Name *
                </label>
                <input
                  type="text"
                  value={newMeal.name || ''}
                  onChange={(e) => setNewMeal({ ...newMeal, name: e.target.value })}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  placeholder="Enter meal name"
                  disabled={isLoading}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Meal Type *
                </label>
                <select
                  value={newMeal.type || 'breakfast'}
                  onChange={(e) => setNewMeal({ ...newMeal, type: e.target.value as Meal['type'] })}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  disabled={isLoading}
                >
                  {mealTypes.map(type => (
                    <option key={type.value} value={type.value}>
                      {type.icon} {type.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Time
                </label>
                <input
                  type="time"
                  value={newMeal.time || '08:00'}
                  onChange={(e) => setNewMeal({ ...newMeal, time: e.target.value })}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  disabled={isLoading}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Servings
                </label>
                <input
                  type="number"
                  min="1"
                  value={newMeal.servings || 4}
                  onChange={(e) => setNewMeal({ ...newMeal, servings: parseInt(e.target.value) })}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  disabled={isLoading}
                />
              </div>
              <div className="sm:col-span-2">
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Location
                </label>
                <input
                  type="text"
                  value={newMeal.location || ''}
                  onChange={(e) => setNewMeal({ ...newMeal, location: e.target.value })}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  placeholder="Where will this meal be served?"
                  disabled={isLoading}
                />
              </div>
              <div className="sm:col-span-2">
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Notes
                </label>
                <textarea
                  value={newMeal.notes || ''}
                  onChange={(e) => setNewMeal({ ...newMeal, notes: e.target.value })}
                  rows={3}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 resize-none"
                  placeholder="Any special notes or instructions..."
                  disabled={isLoading}
                />
              </div>
            </div>
            <div className="flex gap-3 mt-8">
              <button
                onClick={handleAddMeal}
                disabled={isLoading || !newMeal.name || !newMeal.type}
                className="px-6 py-3 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg transition-all duration-200 font-semibold shadow-md hover:scale-[1.02] active:scale-98 focus:outline-none focus:ring-2 focus:ring-ring/50 disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Add meal to plan"
              >
                {isLoading ? 'Adding...' : 'Add Meal'}
              </button>
              <button
                onClick={() => {
                  setShowAddForm(false)
                  setError(null)
                }}
                disabled={isLoading}
                className="px-6 py-3 bg-muted dark:bg-muted text-foreground dark:text-foreground rounded-lg hover:bg-muted/80 dark:hover:bg-muted/80 transition-all duration-200 font-medium hover:scale-[1.02] active:scale-98 focus:outline-none focus:ring-2 focus:ring-ring/50 disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Cancel adding meal"
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {/* Loading Skeleton */}
        {isLoading && (
          <div className="space-y-4 animate-pulse mb-8">
            {[1, 2, 3].map(i => (
              <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6">
                <div className="h-6 bg-muted dark:bg-muted rounded w-3/4 mb-4"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-1/2 mb-2"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-2/3"></div>
              </div>
            ))}
          </div>
        )}

        {/* Meals List */}
        <div className="space-y-6">
          {!isLoading && sortedMeals.length === 0 ? (
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-12 text-center shadow-sm">
              <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <ChefHat className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
              </div>
              <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-2">No meals planned</h3>
              <p className="text-mutedForeground dark:text-mutedForeground mb-6">Add your first meal to get started with planning</p>
              <button
                onClick={() => setShowAddForm(true)}
                className="px-6 py-3 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg transition-all duration-200 font-semibold shadow-md hover:scale-[1.02] active:scale-98 focus:outline-none focus:ring-2 focus:ring-ring/50"
                aria-label="Add your first meal"
              >
                Add First Meal
              </button>
            </div>
          ) : (
            !isLoading && sortedMeals.map(meal => (
              <div key={meal.id} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-3">
                      <h3 className="text-xl font-semibold text-foreground dark:text-foreground">{meal.name}</h3>
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold border ${getMealTypeColor(meal.type)}`}>
                        {mealTypes.find(t => t.value === meal.type)?.icon} {meal.type}
                      </span>
                    </div>
                    <div className="flex items-center gap-6 text-sm text-mutedForeground dark:text-mutedForeground mb-4">
                      <div className="flex items-center gap-2">
                        <Clock className="w-4 h-4" />
                        {meal.time}
                      </div>
                      <div className="flex items-center gap-2">
                        <Users className="w-4 h-4" />
                        {meal.servings} servings
                      </div>
                      {meal.location && (
                        <div className="flex items-center gap-2">
                          <MapPin className="w-4 h-4" />
                          {meal.location}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => setEditingMeal(meal.id)}
                      className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-primary dark:hover:text-primary hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-200 hover:scale-110 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
                      aria-label={`Edit ${meal.name}`}
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeleteMeal(meal.id)}
                      className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all duration-200 hover:scale-110 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
                      aria-label={`Delete ${meal.name}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {/* Assigned Members */}
                {meal.assignedTo.length > 0 && (
                  <div className="mb-4">
                    <span className="text-sm font-semibold text-foreground dark:text-foreground mb-2 block">Assigned to:</span>
                    <div className="flex flex-wrap gap-2">
                      {meal.assignedTo.map(memberId => (
                        <span
                          key={memberId}
                          className="px-3 py-1 bg-primary/10 dark:bg-primary/20 text-primary dark:text-primary rounded-full text-sm font-medium border border-primary/20 dark:border-primary/30"
                        >
                          {getMemberName(memberId)}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* Ingredients */}
                {meal.ingredients.length > 0 && (
                  <div className="mb-4">
                    <span className="text-sm font-semibold text-foreground dark:text-foreground mb-2 block">Ingredients:</span>
                    <div className="flex flex-wrap gap-2">
                      {meal.ingredients.map((ingredient, index) => (
                        <span
                          key={index}
                          className="px-3 py-1 bg-muted dark:bg-muted text-foreground dark:text-foreground rounded-lg text-sm border border-border dark:border-border"
                        >
                          {ingredient}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* Notes */}
                {meal.notes && (
                  <div className="p-4 bg-accent/10 dark:bg-accent/20 border border-accent/20 dark:border-accent/30 rounded-lg">
                    <span className="text-sm font-semibold text-accentForeground dark:text-accent block mb-1">Notes:</span>
                    <p className="text-sm text-accentForeground dark:text-accent/90">{meal.notes}</p>
                  </div>
                )}
              </div>
            ))
          )}
        </div>

        {/* Summary */}
        {!isLoading && (
          <div className="mt-12 bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm">
            <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-6">Daily Summary</h3>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
              {mealTypes.map(type => {
                const count = filteredMeals.filter(meal => meal.type === type.value).length
                return (
                  <div key={type.value} className="text-center p-4 bg-muted/50 dark:bg-muted/50 rounded-lg hover:bg-muted dark:hover:bg-muted transition-colors duration-200">
                    <div className="text-3xl mb-2">{type.icon}</div>
                    <div className="text-2xl font-bold text-foreground dark:text-foreground">{count}</div>
                    <div className="text-sm text-mutedForeground dark:text-mutedForeground font-medium">{type.label}</div>
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default function MealPlannerViewDemo() {
  return <MealPlannerView />
