'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, Users, MapPin, Calendar, Utensils, CheckCircle2, Clock, Paperclip, Image, Smile, AlertCircle } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'location' | 'task' | 'meal' | 'rsvp'
  metadata?: {
    location?: { name: string; coordinates: [number, number] }
    task?: { name: string; assignee: string; dueDate: Date }
    meal?: { name: string; date: Date; time: string }
    rsvp?: { event: string; status: 'yes' | 'no' | 'maybe' }
  }
}

interface GroupMember {
  id: string
  name: string
  avatar: string
  status: 'online' | 'offline' | 'away'
}

interface GroupChatFeatureProps {
  tripId?: string
  groupMembers?: GroupMember[]
  currentUserId?: string
  onSendMessage?: (message: Omit<Message, 'id' | 'timestamp'>) => void
  onLocationShare?: (location: { name: string; coordinates: [number, number] }) => void
  onTaskAssign?: (task: { name: string; assignee: string; dueDate: Date }) => void
}

export function GroupChatFeature({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  currentUserId = 'user-1',
  onSendMessage = () => console.log('Message sent'),
  onLocationShare = () => console.log('Location shared'),
  onTaskAssign = () => console.log('Task assigned')
}: GroupChatFeatureProps = {}) {
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [showQuickActions, setShowQuickActions] = useState(false)
  const [activeMembers, setActiveMembers] = useState(groupMembers.filter(m => m.status === 'online'))
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const currentUser = groupMembers.find(m => m.id === currentUserId) || groupMembers[0]

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  useEffect(() => {
    // Simulate typing indicator
    if (newMessage.length > 0) {
      setIsTyping(true)
      const timer = setTimeout(() => setIsTyping(false), 1000)
      return () => clearTimeout(timer)
    }
  }, [newMessage])

  const handleSendMessage = async () => {
    if (!newMessage.trim()) return

    setIsLoading(true)
    setError(null)

    try {
      const message: Omit<Message, 'id' | 'timestamp'> = {
        userId: currentUserId,
        userName: currentUser.name,
        userAvatar: currentUser.avatar,
        content: newMessage,
        type: 'text'
      }

      const fullMessage: Message = {
        ...message,
        id: `msg-${Date.now()}`,
        timestamp: new Date()
      }

      setMessages(prev => [...prev, fullMessage])
      setNewMessage('')
      onSendMessage(message)
      inputRef.current?.focus()
    } catch (err) {
      setError('Failed to send message. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleQuickAction = async (action: string) => {
    setIsLoading(true)
    setError(null)

    try {
      let message: Omit<Message, 'id' | 'timestamp'>

      switch (action) {
        case 'location':
          message = {
            userId: currentUserId,
            userName: currentUser.name,
            userAvatar: currentUser.avatar,
            content: 'Shared a location',
            type: 'location',
            metadata: {
              location: { name: 'Moab Trail Head', coordinates: [-109.5925, 38.5816] }
            }
          }
          onLocationShare(message.metadata!.location!)
          break
        case 'task':
          message = {
            userId: currentUserId,
            userName: currentUser.name,
            userAvatar: currentUser.avatar,
            content: 'Assigned a task',
            type: 'task',
            metadata: {
              task: { name: 'Bring firewood', assignee: 'Mike Johnson', dueDate: new Date(Date.now() + 86400000) }
            }
          }
          onTaskAssign(message.metadata!.task!)
          break
        case 'meal':
          message = {
            userId: currentUserId,
            userName: currentUser.name,
            userAvatar: currentUser.avatar,
            content: 'Planned a meal',
            type: 'meal',
            metadata: {
              meal: { name: 'BBQ Dinner', date: new Date(Date.now() + 86400000), time: '6:00 PM' }
            }
          }
          break
        default:
          return
      }

      const fullMessage: Message = {
        ...message,
        id: `msg-${Date.now()}`,
        timestamp: new Date()
      }

      setMessages(prev => [...prev, fullMessage])
      setShowQuickActions(false)
      onSendMessage(message)
    } catch (err) {
      setError('Failed to perform action. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true 
    })
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    }
  }

  const renderMessage = (message: Message) => {
    const isCurrentUser = message.userId === currentUserId
    const messageDate = formatDate(message.timestamp)
    const messageTime = formatTime(message.timestamp)

    return (
      <div key={message.id} className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : ''} mb-4 group`}>
        {!isCurrentUser && (
          <div className="flex-shrink-0">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-[#F97316] to-[#EA580C] flex items-center justify-center text-white text-sm font-medium shadow-sm">
              {message.userName.charAt(0)}
            </div>
          </div>
        )}

        <div className={`flex-1 max-w-xs sm:max-w-sm ${isCurrentUser ? 'text-right' : ''}`}>
          {!isCurrentUser && (
            <div className="text-xs text-[#6B7280] dark:text-[#A3A3A3] mb-1 font-medium">{message.userName}</div>
          )}

          <div className={`rounded-2xl px-4 py-3 transition-all duration-200 hover:shadow-md ${
            isCurrentUser 
              ? 'bg-gradient-to-r from-[#EA580C] to-[#F97316] text-[#FFFFFF] shadow-sm' 
              : 'bg-[#F9FAFB] dark:bg-[#262626] text-[#111827] dark:text-[#FAFAFA] border border-[#E5E7EB] dark:border-[#404040]'
          }`}>
            {message.type === 'text' && (
              <p className="text-sm leading-relaxed">{message.content}</p>
            )}

            {message.type === 'location' && message.metadata?.location && (
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4" />
                  <span className="text-sm font-medium">Location Shared</span>
                </div>
                <div className="bg-black/10 dark:bg-white/10 rounded-lg p-3">
                  <p className="text-sm font-medium">{message.metadata.location.name}</p>
                  <p className="text-xs opacity-75">
                    {message.metadata.location.coordinates[1].toFixed(4)}, {message.metadata.location.coordinates[0].toFixed(4)}
                  </p>
                </div>
              </div>
            )}

            {message.type === 'task' && message.metadata?.task && (
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-sm font-medium">Task Assigned</span>
                </div>
                <div className="bg-black/10 dark:bg-white/10 rounded-lg p-3">
                  <p className="text-sm font-medium">{message.metadata.task.name}</p>
                  <p className="text-xs opacity-75">Assigned to: {message.metadata.task.assignee}</p>
                  <p className="text-xs opacity-75">Due: {message.metadata.task.dueDate.toLocaleDateString()}</p>
                </div>
              </div>
            )}

            {message.type === 'meal' && message.metadata?.meal && (
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Utensils className="w-4 h-4" />
                  <span className="text-sm font-medium">Meal Planned</span>
                </div>
                <div className="bg-black/10 dark:bg-white/10 rounded-lg p-3">
                  <p className="text-sm font-medium">{message.metadata.meal.name}</p>
                  <p className="text-xs opacity-75">
                    {message.metadata.meal.date.toLocaleDateString()} at {message.metadata.meal.time}
                  </p>
                </div>
              </div>
            )}
          </div>

          <div className="text-xs text-[#6B7280] dark:text-[#A3A3A3] mt-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
            {messageDate} {messageTime}
          </div>
        </div>
      </div>
    )
  }

  const renderLoadingSkeleton = () => (
    <div className="space-y-4 animate-pulse p-4">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="flex gap-3">
          <div className="w-8 h-8 bg-[#E5E7EB] dark:bg-[#404040] rounded-full"></div>
          <div className="flex-1 space-y-2">
            <div className="h-4 bg-[#E5E7EB] dark:bg-[#404040] rounded w-3/4"></div>
            <div className="h-4 bg-[#E5E7EB] dark:bg-[#404040] rounded w-1/2"></div>
          </div>
        </div>
      ))}
    </div>
  )

  const renderEmptyState = () => (
    <div className="text-center py-12">
      <div className="w-16 h-16 bg-[#F9FAFB] dark:bg-[#262626] rounded-full mx-auto mb-4 flex items-center justify-center border border-[#E5E7EB] dark:border-[#404040]">
        <Users className="w-8 h-8 text-[#6B7280] dark:text-[#A3A3A3]" />
      </div>
      <h3 className="text-lg font-medium text-[#111827] dark:text-[#FAFAFA] mb-2">No messages yet</h3>
      <p className="text-[#6B7280] dark:text-[#A3A3A3] text-sm">Start the conversation with your travel group</p>
    </div>
  )

  return (
    <div className="flex flex-col h-screen max-h-[600px] bg-[#FFFFFF] dark:bg-[#1A1A1A] rounded-xl border border-[#E5E7EB] dark:border-[#404040] shadow-lg overflow-hidden font-sans transition-colors duration-200">
      {/* Header */}
      <div className="bg-gradient-to-r from-[#EA580C] to-[#F97316] text-[#FFFFFF] p-4">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold">Trip Chat</h2>
            <p className="text-sm opacity-90">Moab Adventure 2024</p>
          </div>
          <div className="flex items-center gap-2">
            <Users className="w-5 h-5" />
            <span className="text-sm font-medium">{activeMembers.length}</span>
          </div>
        </div>

        {/* Active Members */}
        <div className="flex gap-2 mt-3 overflow-x-auto pb-1 scrollbar-hide">
          {activeMembers.map(member => (
            <div key={member.id} className="flex-shrink-0 flex items-center gap-2 bg-white/20 rounded-full px-3 py-1 hover:bg-white/30 transition-colors duration-150">
              <div className="w-6 h-6 rounded-full bg-white/30 flex items-center justify-center text-xs font-medium">
                {member.name.charAt(0)}
              </div>
              <span className="text-xs font-medium whitespace-nowrap">{member.name.split(' ')[0]}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Error State */}
      {error && (
        <div className="mx-4 mt-4 rounded-lg bg-[#FEF2F2] dark:bg-[#7F1D1D]/20 border border-[#FECACA] dark:border-[#7F1D1D] p-3">
