            <AlertCircle className="w-4 h-4 text-[#EF4444] dark:text-[#F87171]" />
            <p className="text-sm text-[#EF4444] dark:text-[#F87171]">{error}</p>
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-1 scrollbar-thin scrollbar-thumb-[#E5E7EB] dark:scrollbar-thumb-[#404040] scrollbar-track-transparent">
        {isLoading && messages.length === 0 ? renderLoadingSkeleton() : 
         messages.length === 0 ? renderEmptyState() :
         messages.map(renderMessage)}

        {isTyping && (
          <div className="flex items-center gap-2 text-[#6B7280] dark:text-[#A3A3A3] text-sm">
