            </div>
            <span>Someone is typing...</span>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Quick Actions */}
      {showQuickActions && (
        <div className="border-t border-[#E5E7EB] dark:border-[#404040] p-3 bg-[#FEFEFE] dark:bg-[#0F0F0F]">
          <div className="grid grid-cols-3 gap-2">
            <button
              onClick={() => handleQuickAction('location')}
              disabled={isLoading}
              className="flex flex-col items-center gap-1 p-3 bg-[#EFF6FF] dark:bg-[#1E3A8A]/20 text-[#2563EB] dark:text-[#60A5FA] rounded-lg hover:bg-[#DBEAFE] dark:hover:bg-[#1E3A8A]/30 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50"
              aria-label="Share location"
            >
              <MapPin className="w-5 h-5" />
              <span className="text-xs font-medium">Location</span>
            </button>
            <button
              onClick={() => handleQuickAction('task')}
              disabled={isLoading}
              className="flex flex-col items-center gap-1 p-3 bg-[#F0FDF4] dark:bg-[#14532D]/20 text-[#16A34A] dark:text-[#4ADE80] rounded-lg hover:bg-[#DCFCE7] dark:hover:bg-[#14532D]/30 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50"
              aria-label="Assign task"
            >
              <CheckCircle2 className="w-5 h-5" />
              <span className="text-xs font-medium">Task</span>
            </button>
            <button
              onClick={() => handleQuickAction('meal')}
              disabled={isLoading}
              className="flex flex-col items-center gap-1 p-3 bg-[#FAF5FF] dark:bg-[#581C87]/20 text-[#9333EA] dark:text-[#C084FC] rounded-lg hover:bg-[#F3E8FF] dark:hover:bg-[#581C87]/30 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50"
              aria-label="Plan meal"
            >
              <Utensils className="w-5 h-5" />
              <span className="text-xs font-medium">Meal</span>
            </button>
          </div>
        </div>
      )}

      {/* Input */}
      <div className="border-t border-[#E5E7EB] dark:border-[#404040] p-4 bg-[#FEFEFE] dark:bg-[#0F0F0F]">
        <div className="flex items-center gap-3">
          <button
            onClick={() => setShowQuickActions(!showQuickActions)}
            disabled={isLoading}
            className="flex-shrink-0 w-10 h-10 bg-[#F9FAFB] dark:bg-[#262626] text-[#6B7280] dark:text-[#A3A3A3] rounded-full flex items-center justify-center hover:bg-[#F3F4F6] dark:hover:bg-[#404040] hover:text-[#EA580C] dark:hover:text-[#FB923C] transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50"
            aria-label="Quick actions"
          >
            <Paperclip className="w-5 h-5" />
          </button>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
              placeholder="Type a message..."
              disabled={isLoading}
              className="w-full px-4 py-2.5 bg-[#F9FAFB] dark:bg-[#262626] border border-[#E5E7EB] dark:border-[#404040] rounded-full text-[#111827] dark:text-[#FAFAFA] placeholder-[#6B7280] dark:placeholder-[#A3A3A3] focus:border-[#EA580C] dark:focus:border-[#FB923C] focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50 dark:focus:ring-[#FB923C]/50 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Type your message"
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim() || isLoading}
            className="flex-shrink-0 w-10 h-10 bg-gradient-to-r from-[#EA580C] to-[#F97316] text-[#FFFFFF] rounded-full flex items-center justify-center hover:from-[#DC2626] hover:to-[#EA580C] disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-150 shadow-md hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#EA580C]/50"
            aria-label="Send message"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

