  equipment: 'bg-blue-50 text-blue-800 border-blue-200 dark:bg-blue-900/20 dark:text-blue-200 dark:border-blue-800',
  logistics: 'bg-green-50 text-green-800 border-green-200 dark:bg-green-900/20 dark:text-green-200 dark:border-green-800',
  safety: 'bg-red-50 text-red-800 border-red-200 dark:bg-red-900/20 dark:text-red-200 dark:border-red-800'
}

const PRIORITY_COLORS = {
  low: 'bg-gray-50 text-gray-600 dark:bg-gray-800 dark:text-gray-400',
  medium: 'bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-300',
  high: 'bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-300'
}

const PRIORITY_BORDER_COLORS = {
  low: 'border-gray-300 dark:border-gray-600',
  medium: 'border-amber-500 dark:border-amber-400',
  high: 'border-red-500 dark:border-red-400'
}

export function AssignTaskComponent({
  tripId = 'trip-1',
  tasks = DEFAULT_TASKS,
  members = DEFAULT_MEMBERS,
  onTaskCreate = (task) => console.log('Create task:', task),
  onTaskUpdate = (id, updates) => console.log('Update task:', id, updates),
  onTaskDelete = (id) => console.log('Delete task:', id),
  isLoading = false
}: AssignTaskComponentProps = {}) {
  const [localTasks, setLocalTasks] = useState<Task[]>(tasks)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [error, setError] = useState<string>('')
  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    assignedTo: [] as string[],
    dueDate: '',
    category: 'logistics' as Task['category'],
    priority: 'medium' as Task['priority']
  })

  useEffect(() => {
    setLocalTasks(tasks)
  }, [tasks])

  const handleTaskToggle = (taskId: string) => {
    try {
      const task = localTasks.find(t => t.id === taskId)
      if (task) {
        const updatedTask = { ...task, completed: !task.completed }
        setLocalTasks(prev => prev.map(t => t.id === taskId ? updatedTask : t))
        onTaskUpdate(taskId, { completed: !task.completed })
        setError('')
      }
    } catch (err) {
      setError('Failed to update task. Please try again.')
    }
  }

  const handleCreateTask = () => {
    if (!newTask.title.trim()) {
      setError('Task title is required')
      return
    }

    try {
      const task: Omit<Task, 'id'> = {
        ...newTask,
        completed: false
      }

      const taskWithId = {
        ...task,
        id: Date.now().toString()
      }

      setLocalTasks(prev => [...prev, taskWithId])
      onTaskCreate(task)
      setNewTask({
        title: '',
        description: '',
        assignedTo: [],
        dueDate: '',
        category: 'logistics',
        priority: 'medium'
      })
      setShowCreateForm(false)
      setError('')
    } catch (err) {
      setError('Failed to create task. Please try again.')
    }
  }

  const handleDeleteTask = (taskId: string) => {
    try {
      setLocalTasks(prev => prev.filter(t => t.id !== taskId))
      onTaskDelete(taskId)
      setError('')
    } catch (err) {
      setError('Failed to delete task. Please try again.')
    }
  }

  const handleAssignMember = (taskId: string, memberId: string) => {
    try {
      const task = localTasks.find(t => t.id === taskId)
      if (task) {
        const isAssigned = task.assignedTo.includes(memberId)
        const updatedAssignedTo = isAssigned
          ? task.assignedTo.filter(id => id !== memberId)
          : [...task.assignedTo, memberId]

        setLocalTasks(prev => prev.map(t => 
          t.id === taskId ? { ...t, assignedTo: updatedAssignedTo } : t
        ))
        onTaskUpdate(taskId, { assignedTo: updatedAssignedTo })
        setError('')
      }
    } catch (err) {
      setError('Failed to assign member. Please try again.')
    }
  }

  const filteredTasks = selectedCategory === 'all' 
    ? localTasks 
    : localTasks.filter(task => task.category === selectedCategory)

  const completedTasks = localTasks.filter(task => task.completed).length
  const totalTasks = localTasks.length
  const progressPercentage = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getMemberById = (id: string) => members.find(m => m.id === id)

  // Loading skeleton component
  const TaskSkeleton = () => (
    <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700 animate-pulse">
      <div className="flex items-start gap-3 mb-4">
        <div className="w-5 h-5 bg-gray-200 dark:bg-gray-700 rounded-full mt-1"></div>
        <div className="flex-1 space-y-2">
          <div className="h-5 bg-gray-200 dark:bg-gray-700 rounded w-3/4"></div>
          <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2"></div>
        </div>
      </div>
      <div className="flex gap-2 mb-3">
        <div className="h-6 bg-gray-200 dark:bg-gray-700 rounded w-16"></div>
        <div className="h-6 bg-gray-200 dark:bg-gray-700 rounded w-20"></div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div className="h-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
        <div className="h-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
      </div>
    </div>
  )

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-amber-50 dark:from-gray-900 dark:to-gray-800 font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        {/* Error State */}
        {error && (
          <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 flex items-center gap-3">
            <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400 flex-shrink-0" />
            <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
            <button
              onClick={() => setError('')}
              className="ml-auto text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-200 transition-colors duration-150"
              aria-label="Dismiss error"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        )}

        {/* Header */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700 hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg">
                <Users className="w-6 h-6 text-orange-600 dark:text-orange-400" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Task Assignment</h1>
                <p className="text-gray-600 dark:text-gray-400">Organize responsibilities for your off-road adventure</p>
              </div>
            </div>
            <button
              onClick={() => setShowCreateForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-orange-600 dark:bg-orange-500 text-white rounded-lg hover:bg-orange-700 dark:hover:bg-orange-600 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800"
              aria-label="Create new task"
              disabled={isLoading}
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">New Task</span>
            </button>
          </div>

          {/* Progress Bar */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600 dark:text-gray-400">Progress</span>
              <span className="text-gray-900 dark:text-white font-semibold">{completedTasks}/{totalTasks} tasks completed</span>
            </div>
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
              <div 
                className="bg-gradient-to-r from-orange-600 to-orange-500 h-2 rounded-full transition-all duration-500 ease-out"
                style={{ width: `${progressPercentage}%` }}
              />
            </div>
          </div>
        </div>

        {/* Category Filter */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-200 dark:border-gray-700">
          <div className="flex gap-2 overflow-x-auto pb-2">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800 ${
