                className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800 capitalize ${
                  selectedCategory === category
                    ? 'bg-orange-600 dark:bg-orange-500 text-white shadow-sm'
                    : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                }`}
              >
                {category}
              </button>
            ))}
          </div>
        </div>

        {/* Create Task Form */}
        {showCreateForm && (
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-md border-2 border-orange-200 dark:border-orange-700 hover:shadow-lg transition-all duration-300">
