  avatar: string
  role: 'organizer' | 'member'
  rsvpStatus: 'pending' | 'accepted' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface TripPlannerProps {
  initialLocation?: TripLocation
  groupMembers?: GroupMember[]
  tasks?: Task[]
}

export function TripPlanner({
  initialLocation,
  groupMembers = DEFAULT_MEMBERS,
  tasks = DEFAULT_TASKS
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('locations')
  const [selectedLocation, setSelectedLocation] = useState<TripLocation | null>(initialLocation || null)
  const [members, setMembers] = useState(groupMembers)
  const [tripTasks, setTripTasks] = useState(tasks)
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newMessage, setNewMessage] = useState('')
  const [inviteEmail, setInviteEmail] = useState('')

  const handleLocationSelect = (location: TripLocation) => {
    setSelectedLocation(location)
  }

  const handleTaskToggle = (taskId: string) => {
    setTripTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const handleRSVP = (memberId: string, status: 'accepted' | 'declined') => {
    setMembers(prev => prev.map(member =>
      member.id === memberId ? { ...member, rsvpStatus: status } : member
    ))
  }

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      // In a real app, this would send the message to the backend
      setNewMessage('')
    }
  }

  const handleSendInvite = () => {
    if (inviteEmail.trim()) {
      setIsLoading(true)
      // Simulate API call
      setTimeout(() => {
        setIsLoading(false)
        setInviteEmail('')
        setShowInviteModal(false)
      }, 1000)
    }
  }

  const TabButton = ({ id, label, icon: Icon, isActive }: { 
    id: string
    label: string
    icon: any
    isActive: boolean 
  }) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`flex flex-col items-center gap-1 px-3 py-2 rounded-lg transition-all duration-200 min-h-[44px] focus:outline-none focus:ring-2 focus:ring-primary/50 ${
        isActive 
          ? 'bg-primary text-primaryForeground shadow-md' 
          : 'text-mutedForeground hover:bg-muted hover:text-foreground active:scale-95'
      }`}
      aria-label={label}
      aria-pressed={isActive}
    >
      <Icon size={20} />
      <span className="text-xs font-medium">{label}</span>
    </button>
  )

  const LoadingSkeleton = () => (
    <div className="space-y-4 animate-pulse">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="bg-surface rounded-xl border border-border p-4">
          <div className="flex items-center justify-between">
            <div className="space-y-2 flex-1">
              <div className="h-4 bg-muted rounded w-3/4"></div>
              <div className="h-3 bg-muted rounded w-1/2"></div>
            </div>
            <div className="h-6 bg-muted rounded-full w-16"></div>
          </div>
        </div>
      ))}
    </div>
  )

  const EmptyState = ({ icon: Icon, title, description }: { icon: any, title: string, description: string }) => (
    <div className="text-center py-12">
      <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
        <Icon className="w-8 h-8 text-mutedForeground" />
      </div>
      <h3 className="text-lg font-medium text-foreground mb-2">{title}</h3>
      <p className="text-mutedForeground text-sm">{description}</p>
    </div>
  )

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-muted dark:from-background dark:to-surface font-sans">
      {/* Header */}
      <div className="bg-surface border-b border-border px-4 py-3 shadow-sm backdrop-blur-md bg-surface/95">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center shadow-md">
              <Mountain className="w-5 h-5 text-primaryForeground" />
            </div>
            <div>
              <h1 className="font-bold text-lg text-foreground">Off-Road Planner</h1>
              <p className="text-xs text-mutedForeground">Plan your next adventure</p>
            </div>
          </div>
          <button 
            className="p-2 text-mutedForeground hover:bg-muted hover:text-foreground rounded-lg transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring active:scale-95"
            aria-label="Settings"
          >
            <Settings size={20} />
          </button>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="bg-surface/95 backdrop-blur-md border-b border-border px-4 py-2 sticky top-0 z-10">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide">
          <TabButton id="locations" label="Locations" icon={MapPin} isActive={activeTab === 'locations'} />
          <TabButton id="group" label="Group" icon={Users} isActive={activeTab === 'group'} />
          <TabButton id="tasks" label="Tasks" icon={CheckCircle} isActive={activeTab === 'tasks'} />
          <TabButton id="schedule" label="Schedule" icon={Calendar} isActive={activeTab === 'schedule'} />
          <TabButton id="chat" label="Chat" icon={MessageCircle} isActive={activeTab === 'chat'} />
        </div>
      </div>

      {/* Error State */}
      {error && (
        <div className="mx-4 mt-4">
          <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-4">
            <p className="text-sm text-destructive">{error}</p>
          </div>
        </div>
      )}

      {/* Content */}
      <div className="p-4 pb-20">
        {activeTab === 'locations' && (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold text-foreground">Trail Locations</h2>
              <button className="px-4 py-2 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-sm shadow-md focus:outline-none focus:ring-2 focus:ring-ring flex items-center gap-2">
                <Plus size={16} />
                Add Location
              </button>
            </div>

            {selectedLocation && (
              <div className="bg-surface rounded-xl border border-border p-6 shadow-lg hover:shadow-xl transition-all duration-300">
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h3 className="font-bold text-xl text-foreground">{selectedLocation.name}</h3>
                    <p className="text-mutedForeground">{selectedLocation.terrain}</p>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                    selectedLocation.difficulty === 'Easy' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                    selectedLocation.difficulty === 'Moderate' ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                    'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                  }`}>
                    {selectedLocation.difficulty}
                  </span>
                </div>
                <div className="bg-muted rounded-lg h-32 flex items-center justify-center mb-4 border border-border">
                  <Compass className="w-8 h-8 text-mutedForeground" />
                  <span className="ml-2 text-mutedForeground">Map View</span>
                </div>
                <button className="w-full px-4 py-3 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-md focus:outline-none focus:ring-2 focus:ring-ring">
                  Set as Trip Destination
                </button>
              </div>
            )}

            {isLoading ? (
              <LoadingSkeleton />
            ) : SAMPLE_LOCATIONS.length === 0 ? (
              <EmptyState 
                icon={MapPin} 
                title="No locations yet" 
                description="Get started by adding your first trail location"
              />
            ) : (
              <div className="grid gap-3">
                {SAMPLE_LOCATIONS.map((location) => (
                  <div 
                    key={location.id}
                    className="bg-surface rounded-xl border border-border p-4 hover:border-primary/30 hover:shadow-lg hover:-translate-y-1 transition-all duration-300 cursor-pointer active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring"
                    onClick={() => handleLocationSelect(location)}
                    role="button"
                    tabIndex={0}
                    onKeyDown={(e) => e.key === 'Enter' && handleLocationSelect(location)}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <h3 className="font-semibold text-foreground">{location.name}</h3>
                        <p className="text-sm text-mutedForeground">{location.terrain}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          location.difficulty === 'Easy' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                          location.difficulty === 'Moderate' ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                          'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                        }`}>
                          {location.difficulty}
                        </span>
                        <MapPin className="w-4 h-4 text-mutedForeground" />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'group' && (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold text-foreground">Group Members</h2>
              <button 
                onClick={() => setShowInviteModal(true)}
                className="px-4 py-2 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-sm shadow-md focus:outline-none focus:ring-2 focus:ring-ring flex items-center gap-2"
              >
                <Plus size={16} />
                Invite
              </button>
            </div>

            {members.length === 0 ? (
              <EmptyState 
                icon={Users} 
                title="No members yet" 
                description="Invite friends to join your adventure"
              />
            ) : (
              <div className="grid gap-3">
                {members.map((member) => (
                  <div key={member.id} className="bg-surface rounded-xl border border-border p-4 shadow-sm hover:shadow-md transition-all duration-200">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-full flex items-center justify-center shadow-md">
                          <span className="text-primaryForeground font-medium text-sm">
                            {member.name.split(' ').map(n => n[0]).join('')}
                          </span>
                        </div>
                        <div>
                          <h3 className="font-semibold text-foreground">{member.name}</h3>
                          <p className="text-sm text-mutedForeground">{member.email}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          member.rsvpStatus === 'accepted' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                          member.rsvpStatus === 'declined' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
                          'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
                        }`}>
                          {member.rsvpStatus}
                        </span>
                        {member.role === 'organizer' && (
                          <span className="px-2 py-1 bg-accent/20 text-accentForeground rounded-full text-xs font-medium">
                            Organizer
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'tasks' && (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold text-foreground">Trip Tasks</h2>
              <button className="px-4 py-2 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-sm shadow-md focus:outline-none focus:ring-2 focus:ring-ring flex items-center gap-2">
                <Plus size={16} />
                Add Task
              </button>
            </div>

            {tripTasks.length === 0 ? (
              <EmptyState 
                icon={CheckCircle} 
                title="No tasks yet" 
                description="Create tasks to organize your trip planning"
              />
            ) : (
              <div className="grid gap-3">
                {tripTasks.map((task) => (
                  <div key={task.id} className="bg-surface rounded-xl border border-border p-4 shadow-sm hover:shadow-md transition-all duration-200">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <button
                          onClick={() => handleTaskToggle(task.id)}
                          className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring ${
                            task.completed 
                              ? 'bg-green-500 border-green-500 hover:bg-green-600' 
                              : 'border-border hover:border-primary'
                          }`}
                          aria-label={`Mark ${task.title} as ${task.completed ? 'incomplete' : 'complete'}`}
                        >
                          {task.completed && <CheckCircle className="w-3 h-3 text-white" />}
                        </button>
                        <div>
                          <h3 className={`font-semibold transition-all duration-200 ${task.completed ? 'text-mutedForeground line-through' : 'text-foreground'}`}>
                            {task.title}
                          </h3>
                          <p className="text-sm text-mutedForeground">
                            Assigned to: {members.find(m => m.id === task.assignedTo)?.name || 'Unassigned'}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          task.category === 'food' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
                          task.category === 'equipment' ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400' :
                          'bg-muted text-mutedForeground'
                        }`}>
                          {task.category}
                        </span>
                        <p className="text-xs text-mutedForeground mt-1">{task.dueDate}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'schedule' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-foreground">Trip Schedule</h2>

            <div className="bg-surface rounded-xl border border-border p-6 shadow-sm hover:shadow-md transition-all duration-200">
              <h3 className="font-semibold text-foreground mb-4">Weather Forecast</h3>
              <div className="grid grid-cols-3 gap-4">
                {['Fri', 'Sat', 'Sun'].map((day, index) => (
                  <div key={day} className="text-center">
                    <p className="font-medium text-foreground">{day}</p>
                    <div className="w-8 h-8 bg-gradient-to-br from-accent to-yellow-400 rounded-full mx-auto my-2 shadow-sm"></div>
                    <p className="text-sm text-mutedForeground">{75 + index * 3}°F</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-surface rounded-xl border border-border p-6 shadow-sm hover:shadow-md transition-all duration-200">
              <h3 className="font-semibold text-foreground mb-4">Meal Schedule</h3>
              <div className="space-y-3">
                {MEAL_SCHEDULE.map((meal, index) => (
                  <div key={index} className="flex justify-between items-center py-2 border-b border-border last:border-b-0">
