                      <p className="font-medium text-foreground">{meal.time}</p>
                      <p className="text-sm text-mutedForeground">{meal.meal}</p>
                    </div>
                    <span className="text-sm text-primary font-medium">{meal.day}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-foreground">Group Chat</h2>

            <div className="bg-surface rounded-xl border border-border shadow-sm">
              <div className="p-4 border-b border-border">
                <h3 className="font-semibold text-foreground">Trip Planning Chat</h3>
                <p className="text-sm text-mutedForeground">{members.length} members</p>
              </div>

              <div className="h-64 p-4 space-y-3 overflow-y-auto">
                {CHAT_MESSAGES.map((message, index) => (
                  <div key={index} className="flex gap-3">
                    <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-full flex items-center justify-center flex-shrink-0 shadow-sm">
                      <span className="text-primaryForeground font-medium text-xs">
                        {message.sender.split(' ').map(n => n[0]).join('')}
                      </span>
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium text-sm text-foreground">{message.sender}</span>
                        <span className="text-xs text-mutedForeground">{message.time}</span>
                      </div>
                      <p className="text-sm text-foreground">{message.text}</p>
                    </div>
                  </div>
                ))}
              </div>

              <div className="p-4 border-t border-border">
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Type a message..."
                    className="flex-1 px-3 py-2 border border-border rounded-lg text-sm bg-background text-foreground placeholder:text-mutedForeground focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring transition-all duration-200"
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  />
                  <button 
                    onClick={handleSendMessage}
                    disabled={!newMessage.trim()}
                    className="px-4 py-2 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-sm shadow-md focus:outline-none focus:ring-2 focus:ring-ring disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center gap-2"
                  >
                    <Send size={16} />
                    Send
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Invite Modal */}
      {showInviteModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50 animate-in fade-in duration-200">
          <div className="bg-surface rounded-xl p-6 w-full max-w-md shadow-xl border border-border animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-foreground">Invite Members</h3>
              <button
                onClick={() => setShowInviteModal(false)}
                className="p-1 text-mutedForeground hover:text-foreground rounded-lg transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring"
                aria-label="Close modal"
              >
                <X size={20} />
              </button>
            </div>
            <div className="space-y-4">
              <input
                type="email"
                value={inviteEmail}
                onChange={(e) => setInviteEmail(e.target.value)}
                placeholder="Enter email address"
                className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background text-foreground placeholder:text-mutedForeground focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring transition-all duration-200"
                onKeyDown={(e) => e.key === 'Enter' && handleSendInvite()}
              />
              <div className="flex gap-3">
                <button
                  onClick={() => setShowInviteModal(false)}
                  className="flex-1 px-4 py-2 border border-border text-foreground rounded-lg hover:bg-muted transition-all duration-200 font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSendInvite}
                  disabled={!inviteEmail.trim() || isLoading}
                  className="flex-1 px-4 py-2 bg-gradient-to-r from-primary to-secondary text-primaryForeground rounded-lg hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-sm shadow-md focus:outline-none focus:ring-2 focus:ring-ring disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Sending...
                    </>
                  ) : (
                    'Send Invite'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Navigation Spacer */}
      <div className="h-16"></div>
    </div>
  )
}

