'use client'

import { createClient } from '@supabase/supabase-js'
import { useState, useEffect } from 'react'
import { Database, Shield, AlertCircle, CheckCircle } from 'lucide-react'

interface SupabaseConfig {
  url?: string
  anonKey?: string
  options?: {
    auth?: {
      autoRefreshToken?: boolean
      persistSession?: boolean
      detectSessionInUrl?: boolean
    }
    realtime?: {
      params?: {
        eventsPerSecond?: number
      }
    }
  }
}

interface ConnectionStatus {
  status: 'connecting' | 'connected' | 'error' | 'disconnected'
  message: string
  lastChecked: Date
}

interface SupabaseClientProps {
  config?: SupabaseConfig
  onStatusChange?: (status: ConnectionStatus) => void
  showStatus?: boolean
  autoConnect?: boolean
}

export function SupabaseClient({
  config = DEFAULT_CONFIG,
  onStatusChange = () => {},
  showStatus = true,
  autoConnect = true
}: SupabaseClientProps = {}) {
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>({
    status: 'disconnected',
    message: 'Not connected',
    lastChecked: new Date()
  })
  const [client, setClient] = useState<any>(null)
  const [isInitializing, setIsInitializing] = useState(false)

  const updateStatus = (status: ConnectionStatus['status'], message: string) => {
    const newStatus = {
      status,
      message,
      lastChecked: new Date()
    }
    setConnectionStatus(newStatus)
    onStatusChange(newStatus)
  }

  const initializeClient = async () => {
    if (!config.url || !config.anonKey) {
      updateStatus('error', 'Missing Supabase URL or anonymous key')
      return
    }

    setIsInitializing(true)
    updateStatus('connecting', 'Initializing Supabase client...')

    try {
      const supabaseClient = createClient(config.url, config.anonKey, {
        auth: {
          autoRefreshToken: config.options?.auth?.autoRefreshToken ?? true,
          persistSession: config.options?.auth?.persistSession ?? true,
          detectSessionInUrl: config.options?.auth?.detectSessionInUrl ?? true
        },
        realtime: {
          params: {
            eventsPerSecond: config.options?.realtime?.params?.eventsPerSecond ?? 10
          }
        }
      })

      const { error } = await supabaseClient.from('_test_connection').select('*').limit(1)

      if (error && !error.message.includes('relation "_test_connection" does not exist')) {
        throw error
      }

      setClient(supabaseClient)
      updateStatus('connected', 'Successfully connected to Supabase')
    } catch (error: any) {
      console.error('Supabase connection error:', error)
      updateStatus('error', error.message || 'Failed to connect to Supabase')
    } finally {
      setIsInitializing(false)
    }
  }

  const testConnection = async () => {
    if (!client) {
      updateStatus('error', 'Client not initialized')
      return
    }

    updateStatus('connecting', 'Testing connection...')

    try {
      const { data, error } = await client.from('_health_check').select('*').limit(1)

      if (error && !error.message.includes('relation "_health_check" does not exist')) {
        throw error
      }

      updateStatus('connected', 'Connection test successful')
    } catch (error: any) {
      updateStatus('error', `Connection test failed: ${error.message}`)
    }
  }

  const disconnect = () => {
    if (client) {
      setClient(null)
      updateStatus('disconnected', 'Disconnected from Supabase')
    }
  }

  useEffect(() => {
    if (autoConnect) {
      initializeClient()
    }
  }, [autoConnect, config.url, config.anonKey])

  const getStatusIcon = () => {
    switch (connectionStatus.status) {
      case 'connected':
        return <CheckCircle className="w-5 h-5 text-accent dark:text-accent" />
      case 'connecting':
        return <Database className="w-5 h-5 text-primary dark:text-primary animate-pulse" />
      case 'error':
        return <AlertCircle className="w-5 h-5 text-destructive dark:text-destructive" />
      default:
        return <Shield className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
    }
  }

  const getStatusColor = () => {
    switch (connectionStatus.status) {
      case 'connected':
        return 'border-accent/20 bg-accent/5 dark:border-accent/30 dark:bg-accent/10'
      case 'connecting':
        return 'border-primary/20 bg-primary/5 dark:border-primary/30 dark:bg-primary/10'
      case 'error':
        return 'border-destructive/20 bg-destructive/5 dark:border-destructive/30 dark:bg-destructive/10'
      default:
        return 'border-border bg-muted/50 dark:border-border dark:bg-muted/50'
    }
  }

  return (
    <div className="w-full max-w-2xl mx-auto p-6 space-y-6 font-sans">
      <div className="text-center space-y-2">
        <div className="flex items-center justify-center gap-3">
          <Database className="w-8 h-8 text-accent dark:text-accent" />
          <h2 className="text-2xl font-semibold text-foreground dark:text-foreground">Supabase Client</h2>
        </div>
        <p className="text-mutedForeground dark:text-mutedForeground text-base leading-normal">
          Manage your Supabase database connection for the off-roading trip planner
        </p>
      </div>

      {showStatus && (
        <div className={`p-4 rounded-lg border-2 ${getStatusColor()} transition-all duration-300 hover:shadow-md`}>
          <div className="flex items-center gap-3">
            {getStatusIcon()}
            <div className="flex-1">
              <div className="flex items-center justify-between">
                <span className="font-medium text-foreground dark:text-foreground capitalize">
                  {connectionStatus.status}
                </span>
                <span className="text-sm text-mutedForeground dark:text-mutedForeground">
                  {connectionStatus.lastChecked.toLocaleTimeString()}
                </span>
              </div>
              <p className="text-sm text-mutedForeground dark:text-mutedForeground mt-1">
                {connectionStatus.message}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-surface dark:bg-surface border border-border dark:border-border rounded-lg p-6 space-y-4 shadow-sm hover:shadow-md transition-all duration-300">
        <h3 className="text-lg font-semibold text-foreground dark:text-foreground flex items-center gap-2">
          <Shield className="w-5 h-5" />
          Configuration
        </h3>

        <div className="grid gap-4">
          <div>
            <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
              Supabase URL
            </label>
            <div className="px-3 py-2 bg-muted dark:bg-muted border border-border dark:border-border rounded-md text-sm text-mutedForeground dark:text-mutedForeground font-mono">
              {config.url ? `${config.url.substring(0, 30)}...` : 'Not configured'}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
              Anonymous Key
            </label>
            <div className="px-3 py-2 bg-muted dark:bg-muted border border-border dark:border-border rounded-md text-sm text-mutedForeground dark:text-mutedForeground font-mono">
              {config.anonKey ? `${config.anonKey.substring(0, 20)}...` : 'Not configured'}
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        <button
          onClick={initializeClient}
          disabled={isInitializing || connectionStatus.status === 'connecting'}
          aria-label={isInitializing ? 'Connecting to Supabase' : client ? 'Reconnect to Supabase' : 'Connect to Supabase'}
          className="flex-1 px-6 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted disabled:text-mutedForeground disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md min-h-[44px] flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background"
        >
          {isInitializing ? (
            <>
              <Database className="w-4 h-4 animate-spin" />
              Connecting...
            </>
          ) : (
            <>
              <Database className="w-4 h-4" />
              {client ? 'Reconnect' : 'Connect'}
            </>
          )}
        </button>

        {client && (
          <>
            <button
              onClick={testConnection}
              disabled={connectionStatus.status === 'connecting'}
              aria-label="Test Supabase connection"
              className="flex-1 px-6 py-3 bg-surface dark:bg-surface text-accent dark:text-accent border-2 border-accent dark:border-accent rounded-lg hover:bg-accent/5 dark:hover:bg-accent/10 hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted disabled:text-mutedForeground disabled:border-border disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium text-sm min-h-[44px] flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background"
            >
              <CheckCircle className="w-4 h-4" />
              Test Connection
            </button>

            <button
              onClick={disconnect}
              aria-label="Disconnect from Supabase"
              className="flex-1 px-6 py-3 bg-surface dark:bg-surface text-destructive dark:text-destructive border-2 border-destructive dark:border-destructive rounded-lg hover:bg-destructive/5 dark:hover:bg-destructive/10 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm min-h-[44px] flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background"
            >
              <AlertCircle className="w-4 h-4" />
              Disconnect
            </button>
          </>
        )}
      </div>

      {client && (
        <div className="bg-accent/5 dark:bg-accent/10 border border-accent/20 dark:border-accent/30 rounded-lg p-4 hover:shadow-md transition-all duration-300">
          <div className="flex items-center gap-2 text-accent dark:text-accent">
            <CheckCircle className="w-5 h-5" />
            <span className="font-medium">Client Ready</span>
          </div>
          <p className="text-sm text-foreground dark:text-foreground mt-1 leading-relaxed">
            Supabase client is initialized and ready for database operations.
            You can now perform queries, authentication, and real-time subscriptions.
          </p>
        </div>
      )}
    </div>
  )
}

const DEFAULT_CONFIG: SupabaseConfig = {
  url: process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://your-project.supabase.co',
  anonKey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'your-anon-key',
  options: {
    auth: {
      autoRefreshToken: true,
      persistSession: true,
      detectSessionInUrl: true
    },
    realtime: {
      params: {
        eventsPerSecond: 10
      }
    }
  }
}

export default function SupabaseClientDemo() {
  const [status, setStatus] = useState<ConnectionStatus | null>(null)

  return (
    <div className="min-h-screen bg-background dark:bg-background py-8 font-sans">
      <div className="max-w-4xl mx-auto px-4">
        <SupabaseClient
          onStatusChange={setStatus}
          showStatus={true}
          autoConnect={false}
        />

        {status && (
          <div className="mt-8 p-4 bg-surface dark:bg-surface border border-border dark:border-border rounded-lg shadow-sm hover:shadow-md transition-all duration-300">
            <h4 className="font-medium text-foreground dark:text-foreground mb-2">Status Updates</h4>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground space-y-1">
              <p><span className="font-medium">Status:</span> {status.status}</p>
              <p><span className="font-medium">Message:</span> {status.message}</p>
              <p><span className="font-medium">Last Checked:</span> {status.lastChecked.toLocaleString()}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

