                  <h1 className="text-xl font-bold text-foreground dark:text-foreground">TrailPlan</h1>
                  <p className="text-xs text-mutedForeground dark:text-mutedForeground -mt-1">Off-Road Adventures</p>
                </div>
              </div>
            </div>

