                      : 'text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground hover:bg-muted dark:hover:bg-muted'
                  }`}
                  style={{ minHeight: '44px' }}
                  aria-label={item.label}
                >
                  <Icon className="h-5 w-5 flex-shrink-0" />
                  <span className="font-medium">{item.label}</span>
                  {item.badge && (
                    <span className="ml-auto h-5 w-5 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground text-xs rounded-full flex items-center justify-center font-bold">
                      {item.badge}
                    </span>
                  )}
