'use client';

import React, { useState } from 'react';
import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { cookies } from 'next/headers'

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

interface AuthRequest {
  email: string
  password: string
  action: 'sign_up' | 'sign_in' | 'sign_out' | 'reset_password'
  firstName?: string
  lastName?: string
  phone?: string
}

interface AuthResponse {
  success: boolean
  message: string
  user?: {
    id: string
    email: string
    firstName?: string
    lastName?: string
    phone?: string
  }
  session?: {
    access_token: string
    refresh_token: string
    expires_at: number
  }
  error?: string
}

export async function POST(request: NextRequest): Promise<NextResponse<AuthResponse>> {
  try {
    const body: AuthRequest = await request.json()
    const { email, password, action, firstName, lastName, phone } = body

    if (!email || !action) {
      return NextResponse.json({
        success: false,
        message: 'Email and action are required',
        error: 'MISSING_FIELDS'
      }, { status: 400 })
    }

    switch (action) {
      case 'sign_up': {
        if (!password || !firstName || !lastName) {
          return NextResponse.json({
            success: false,
            message: 'Password, first name, and last name are required for sign up',
            error: 'MISSING_FIELDS'
          }, { status: 400 })
        }

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              first_name: firstName,
              last_name: lastName,
              phone: phone || null
            }
          }
        })

        if (authError) {
          return NextResponse.json({
            success: false,
            message: authError.message,
            error: authError.code || 'SIGNUP_ERROR'
          }, { status: 400 })
        }

        if (!authData.user) {
          return NextResponse.json({
            success: false,
            message: 'Failed to create user account',
            error: 'USER_CREATION_FAILED'
          }, { status: 500 })
        }

        const { error: profileError } = await supabase
          .from('profiles')
          .insert({
            id: authData.user.id,
            email: authData.user.email,
            first_name: firstName,
            last_name: lastName,
            phone: phone || null,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          })

        if (profileError) {
          console.error('Profile creation error:', profileError)
        }

        return NextResponse.json({
          success: true,
          message: 'Account created successfully. Please check your email to verify your account.',
          user: {
            id: authData.user.id,
            email: authData.user.email!,
            firstName,
            lastName,
            phone: phone || undefined
          }
        })
      }

      case 'sign_in': {
        if (!password) {
          return NextResponse.json({
            success: false,
            message: 'Password is required for sign in',
            error: 'MISSING_PASSWORD'
          }, { status: 400 })
        }

        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
          email,
          password
        })

        if (authError) {
          return NextResponse.json({
            success: false,
            message: authError.message,
            error: authError.code || 'SIGNIN_ERROR'
          }, { status: 401 })
        }

        if (!authData.user || !authData.session) {
          return NextResponse.json({
            success: false,
            message: 'Invalid credentials',
            error: 'INVALID_CREDENTIALS'
          }, { status: 401 })
        }

        const { data: profile } = await supabase
          .from('profiles')
          .select('first_name, last_name, phone')
          .eq('id', authData.user.id)
          .single()

        const cookieStore = cookies()
        cookieStore.set('sb-access-token', authData.session.access_token, {
          httpOnly: true,
          secure: process.env.NODE_ENV === 'production',
          sameSite: 'lax',
          maxAge: authData.session.expires_in
        })
        cookieStore.set('sb-refresh-token', authData.session.refresh_token, {
          httpOnly: true,
          secure: process.env.NODE_ENV === 'production',
          sameSite: 'lax',
          maxAge: 60 * 60 * 24 * 30
        })

        return NextResponse.json({
          success: true,
          message: 'Signed in successfully',
          user: {
            id: authData.user.id,
            email: authData.user.email!,
            firstName: profile?.first_name,
            lastName: profile?.last_name,
            phone: profile?.phone
          },
          session: {
            access_token: authData.session.access_token,
            refresh_token: authData.session.refresh_token,
            expires_at: authData.session.expires_at!
          }
        })
      }

      case 'sign_out': {
        const { error: signOutError } = await supabase.auth.signOut()

        if (signOutError) {
          return NextResponse.json({
            success: false,
            message: signOutError.message,
            error: signOutError.code || 'SIGNOUT_ERROR'
          }, { status: 400 })
        }

        const cookieStore = cookies()
        cookieStore.delete('sb-access-token')
        cookieStore.delete('sb-refresh-token')

        return NextResponse.json({
          success: true,
          message: 'Signed out successfully'
        })
      }

      case 'reset_password': {
        const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: `${process.env.NEXT_PUBLIC_SITE_URL}/auth/reset-password`
        })

        if (resetError) {
          return NextResponse.json({
            success: false,
            message: resetError.message,
            error: resetError.code || 'RESET_ERROR'
          }, { status: 400 })
        }

        return NextResponse.json({
          success: true,
          message: 'Password reset email sent. Please check your inbox.'
        })
      }

      default:
        return NextResponse.json({
          success: false,
          message: 'Invalid action',
          error: 'INVALID_ACTION'
        }, { status: 400 })
    }
  } catch (error) {
    console.error('Auth API error:', error)
    return NextResponse.json({
      success: false,
      message: 'Internal server error',
      error: 'INTERNAL_ERROR'
    }, { status: 500 })
  }
}

export async function GET(request: NextRequest): Promise<NextResponse<AuthResponse>> {
  try {
    const cookieStore = cookies()
    const accessToken = cookieStore.get('sb-access-token')?.value
    const refreshToken = cookieStore.get('sb-refresh-token')?.value

    if (!accessToken || !refreshToken) {
      return NextResponse.json({
        success: false,
        message: 'No active session',
        error: 'NO_SESSION'
      }, { status: 401 })
    }

    const { data: { user }, error: userError } = await supabase.auth.getUser(accessToken)

    if (userError || !user) {
      const { data: refreshData, error: refreshError } = await supabase.auth.refreshSession({
        refresh_token: refreshToken
      })

      if (refreshError || !refreshData.session) {
        cookieStore.delete('sb-access-token')
        cookieStore.delete('sb-refresh-token')

        return NextResponse.json({
          success: false,
          message: 'Session expired',
          error: 'SESSION_EXPIRED'
        }, { status: 401 })
      }

      cookieStore.set('sb-access-token', refreshData.session.access_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: refreshData.session.expires_in
      })
      cookieStore.set('sb-refresh-token', refreshData.session.refresh_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 60 * 60 * 24 * 30
      })

      const { data: profile } = await supabase
        .from('profiles')
        .select('first_name, last_name, phone')
        .eq('id', refreshData.user.id)
        .single()

      return NextResponse.json({
        success: true,
        message: 'Session refreshed',
        user: {
          id: refreshData.user.id,
          email: refreshData.user.email!,
          firstName: profile?.first_name,
          lastName: profile?.last_name,
          phone: profile?.phone
        },
        session: {
          access_token: refreshData.session.access_token,
          refresh_token: refreshData.session.refresh_token,
          expires_at: refreshData.session.expires_at!
        }
      })
    }

    const { data: profile } = await supabase
      .from('profiles')
      .select('first_name, last_name, phone')
      .eq('id', user.id)
      .single()

    return NextResponse.json({
      success: true,
      message: 'Session valid',
      user: {
        id: user.id,
        email: user.email!,
        firstName: profile?.first_name,
        lastName: profile?.last_name,
        phone: profile?.phone
      }
    })
  } catch (error) {
    console.error('Auth session check error:', error)
    return NextResponse.json({
      success: false,
      message: 'Internal server error',
      error: 'INTERNAL_ERROR'
    }, { status: 500 })
  }
}

