'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mail, Lock, Mountain, Users, Calendar, MapPin } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignup?: (email: string, password: string, name: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignup = (email, password, name) => console.log('Signup:', { email, password, name }),
  onForgotPassword = (email) => console.log('Forgot password:', email)
}: LoginPageProps = {}) {
  const [isLogin, setIsLogin] = useState(true)
  const [showPassword, setShowPassword] = useState(false)
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    name: ''
  })
  const [isLoading, setIsLoading] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateEmail = (email: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.email) {
      newErrors.email = 'Email is required'
    } else if (!validateEmail(formData.email)) {
      newErrors.email = 'Please enter a valid email'
    }

    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else if (formData.password.length < 6) {
      newErrors.password = 'Password must be at least 6 characters'
    }

    if (!isLogin && !formData.name) {
      newErrors.name = 'Name is required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsLoading(true)

    try {
      if (isLogin) {
        await onLogin(formData.email, formData.password)
      } else {
        await onSignup(formData.email, formData.password, formData.name)
      }
    } catch (error) {
      console.error('Authentication error:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (!formData.email) {
      setErrors({ email: 'Please enter your email first' })
      return
    }
    onForgotPassword(formData.email)
  }

  const features = [
    {
      icon: MapPin,
      title: 'Location Planning',
      description: 'Discover and save amazing off-road destinations'
    },
    {
      icon: Users,
      title: 'Group Management',
      description: 'Assign tasks and coordinate with your adventure crew'
    },
    {
      icon: Calendar,
      title: 'Smart Scheduling',
      description: 'Weather integration and shared calendar sync'
    }
  ]

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-r from-primary/20 to-accent/20" />
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8 pb-16">
          <div className="text-center mb-12">
            <div className="flex items-center justify-center gap-3 mb-6">
              <div className="p-3 bg-primary rounded-xl shadow-lg hover:scale-105 transition-transform duration-200">
                <Mountain className="w-8 h-8 text-primaryForeground" />
              </div>
              <h1 className="text-3xl font-bold text-foreground dark:text-foreground">TrailPlan</h1>
            </div>
            <p className="text-xl text-mutedForeground dark:text-mutedForeground max-w-2xl mx-auto leading-relaxed">
              Plan epic off-road adventures with your crew. Coordinate locations, tasks, and schedules all in one place.
            </p>
          </div>

          <div className="grid md:grid-cols-3 gap-6 mb-16">
            {features.map((feature, index) => (
              <div
                key={index}
                className="bg-surface/80 dark:bg-surface/80 backdrop-blur-sm border border-border dark:border-border rounded-xl p-6 text-center hover:border-primary/50 dark:hover:border-primary/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300 group"
              >
                <div className="w-12 h-12 bg-primary/20 dark:bg-primary/20 rounded-lg flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform duration-200">
                  <feature.icon className="w-6 h-6 text-primary dark:text-primary" />
                </div>
                <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-2">{feature.title}</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm leading-normal">{feature.description}</p>
              </div>
            ))}
          </div>

          <div className="max-w-md mx-auto">
            <div className="bg-surface/80 dark:bg-surface/80 backdrop-blur-sm border border-border dark:border-border rounded-2xl p-8 shadow-xl hover:shadow-2xl transition-shadow duration-300">
              <div className="text-center mb-8">
                <h2 className="text-2xl font-bold text-foreground dark:text-foreground mb-2">
                  {isLogin ? 'Welcome Back' : 'Join TrailPlan'}
                </h2>
                <p className="text-mutedForeground dark:text-mutedForeground">
                  {isLogin ? 'Sign in to your adventure hub' : 'Start planning your next adventure'}
                </p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6">
                {!isLogin && (
                  <div>
                    <label htmlFor="name" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                      Full Name
                    </label>
                    <input
                      id="name"
                      type="text"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full px-4 py-3 bg-muted/50 dark:bg-muted/50 border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 dark:focus:ring-ring/20 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                      placeholder="Enter your full name"
                      aria-describedby={errors.name ? 'name-error' : undefined}
                    />
                    {errors.name && (
                      <p id="name-error" className="text-destructive dark:text-destructive text-sm mt-1" role="alert">
                        {errors.name}
                      </p>
                    )}
                  </div>
                )}

                <div>
                  <label htmlFor="email" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Email Address
                  </label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
                    <input
                      id="email"
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full pl-12 pr-4 py-3 bg-muted/50 dark:bg-muted/50 border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 dark:focus:ring-ring/20 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                      placeholder="Enter your email"
                      aria-describedby={errors.email ? 'email-error' : undefined}
                    />
                  </div>
                  {errors.email && (
                    <p id="email-error" className="text-destructive dark:text-destructive text-sm mt-1" role="alert">
                      {errors.email}
                    </p>
                  )}
                </div>

                <div>
                  <label htmlFor="password" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Password
                  </label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
                    <input
                      id="password"
                      type={showPassword ? 'text' : 'password'}
                      value={formData.password}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      className="w-full pl-12 pr-12 py-3 bg-muted/50 dark:bg-muted/50 border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 dark:focus:ring-ring/20 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                      placeholder="Enter your password"
                      aria-describedby={errors.password ? 'password-error' : undefined}
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground transition-colors duration-200 p-1 rounded focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
