'use client'

import { useState, useEffect, useCallback } from 'react'
import { Bell, X, Check, AlertTriangle, Info, Calendar, Users, MapPin, MessageSquare } from 'lucide-react'

interface Notification {
  id: string
  type: 'trip_invite' | 'task_assignment' | 'weather_alert' | 'message' | 'rsvp_reminder' | 'schedule_update'
  title: string
  message: string
  timestamp: Date
  read: boolean
  actionRequired?: boolean
  tripId?: string
  userId?: string
  priority: 'low' | 'medium' | 'high'
}

interface NotificationServiceProps {
  userId?: string
  onNotificationClick?: (notification: Notification) => void
  maxNotifications?: number
  autoMarkAsRead?: boolean
}

export function NotificationService({
  userId = 'user-123',
  onNotificationClick = () => {},
  maxNotifications = 50,
  autoMarkAsRead = true
}: NotificationServiceProps = {}) {
  const [notifications, setNotifications] = useState<Notification[]>(DEFAULT_NOTIFICATIONS)
  const [isOpen, setIsOpen] = useState(false)
  const [unreadCount, setUnreadCount] = useState(0)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    const count = notifications.filter(n => !n.read).length
    setUnreadCount(count)
  }, [notifications])

  useEffect(() => {
    const interval = setInterval(() => {
      if (Math.random() > 0.8) {
        addNotification(generateRandomNotification())
      }
    }, 10000)

    return () => clearInterval(interval)
  }, [])

  const addNotification = useCallback((notification: Notification) => {
    setNotifications(prev => {
      const updated = [notification, ...prev].slice(0, maxNotifications)
      return updated
    })
  }, [maxNotifications])

  const markAsRead = useCallback((notificationId: string) => {
    setNotifications(prev =>
      prev.map(n =>
        n.id === notificationId ? { ...n, read: true } : n
      )
    )
  }, [])

  const markAllAsRead = useCallback(() => {
    setNotifications(prev =>
      prev.map(n => ({ ...n, read: true }))
    )
  }, [])

  const removeNotification = useCallback((notificationId: string) => {
    setNotifications(prev =>
      prev.filter(n => n.id !== notificationId)
    )
  }, [])

  const handleNotificationClick = useCallback((notification: Notification) => {
    if (autoMarkAsRead && !notification.read) {
      markAsRead(notification.id)
    }
    onNotificationClick(notification)
  }, [autoMarkAsRead, markAsRead, onNotificationClick])

  const getNotificationIcon = (type: Notification['type']) => {
    switch (type) {
      case 'trip_invite':
        return <MapPin className="w-5 h-5 text-orange-500 dark:text-orange-400" />
      case 'task_assignment':
        return <Check className="w-5 h-5 text-emerald-500 dark:text-emerald-400" />
      case 'weather_alert':
        return <AlertTriangle className="w-5 h-5 text-orange-500 dark:text-orange-400" />
      case 'message':
        return <MessageSquare className="w-5 h-5 text-stone-500 dark:text-stone-400" />
      case 'rsvp_reminder':
        return <Calendar className="w-5 h-5 text-red-500 dark:text-red-400" />
      case 'schedule_update':
        return <Info className="w-5 h-5 text-emerald-500 dark:text-emerald-400" />
      default:
        return <Bell className="w-5 h-5 text-stone-500 dark:text-stone-400" />
    }
  }

  const getPriorityColor = (priority: Notification['priority']) => {
    switch (priority) {
      case 'high':
        return 'border-l-red-500 dark:border-l-red-400 bg-red-50 dark:bg-red-900/20'
      case 'medium':
        return 'border-l-orange-500 dark:border-l-orange-400 bg-orange-50 dark:bg-orange-900/20'
      case 'low':
        return 'border-l-emerald-500 dark:border-l-emerald-400 bg-emerald-50 dark:bg-emerald-900/20'
      default:
        return 'border-l-stone-500 dark:border-l-stone-400 bg-stone-50 dark:bg-stone-900/20'
    }
  }

  const formatTimestamp = (timestamp: Date) => {
    const now = new Date()
    const diff = now.getTime() - timestamp.getTime()
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) return 'Just now'
    if (minutes < 60) return `${minutes}m ago`
    if (hours < 24) return `${hours}h ago`
    if (days < 7) return `${days}d ago`
    return timestamp.toLocaleDateString()
  }

  return (
    <div className="relative font-sans">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 text-stone-600 dark:text-stone-400 hover:text-orange-500 dark:hover:text-orange-400 hover:bg-stone-100 dark:hover:bg-stone-800 rounded-lg transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-orange-500 dark:focus:ring-orange-400 focus:ring-offset-2 dark:focus:ring-offset-stone-900 hover:scale-105 active:scale-95"
        aria-label={`Notifications ${unreadCount > 0 ? `(${unreadCount} unread)` : ''}`}
      >
        <Bell className="w-6 h-6" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 bg-orange-500 dark:bg-orange-400 text-white dark:text-stone-900 text-xs rounded-full h-5 w-5 flex items-center justify-center font-medium animate-pulse">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {isOpen && (
        <>
          <div
            className="fixed inset-0 z-40 bg-black/60 md:hidden"
            onClick={() => setIsOpen(false)}
          />

          <div className="absolute right-0 top-full mt-2 w-80 md:w-96 bg-white dark:bg-stone-900 rounded-xl shadow-xl border border-stone-200 dark:border-stone-700 z-50 max-h-96 overflow-hidden backdrop-blur-sm">
            <div className="flex items-center justify-between p-4 border-b border-stone-200 dark:border-stone-700">
              <h3 className="text-lg font-semibold text-stone-900 dark:text-stone-100">Notifications</h3>
              <div className="flex items-center gap-2">
                {unreadCount > 0 && (
                  <button
                    onClick={markAllAsRead}
                    className="text-sm text-orange-600 dark:text-orange-400 hover:text-orange-700 dark:hover:text-orange-300 font-medium transition-colors duration-200 hover:underline"
                  >
                    Mark all read
                  </button>
                )}
                <button
                  onClick={() => setIsOpen(false)}
                  className="p-1 text-stone-400 dark:text-stone-500 hover:text-stone-600 dark:hover:text-stone-300 rounded transition-all duration-200 hover:bg-stone-100 dark:hover:bg-stone-800"
                  aria-label="Close notifications"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>

            <div className="max-h-80 overflow-y-auto">
              {isLoading ? (
                <div className="p-4 space-y-4">
                  {[...Array(3)].map((_, i) => (
                    <div key={i} className="animate-pulse">
                      <div className="flex items-start gap-3">
                        <div className="w-5 h-5 bg-stone-200 dark:bg-stone-700 rounded"></div>
                        <div className="flex-1 space-y-2">
                          <div className="h-4 bg-stone-200 dark:bg-stone-700 rounded w-3/4"></div>
                          <div className="h-3 bg-stone-200 dark:bg-stone-700 rounded w-1/2"></div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : notifications.length === 0 ? (
                <div className="p-8 text-center">
                  <div className="w-16 h-16 bg-stone-100 dark:bg-stone-800 rounded-full mx-auto mb-4 flex items-center justify-center">
                    <Bell className="w-8 h-8 text-stone-400 dark:text-stone-500" />
                  </div>
                  <h3 className="text-lg font-medium text-stone-900 dark:text-stone-100 mb-2">No notifications yet</h3>
                  <p className="text-stone-500 dark:text-stone-400 text-sm">You're all caught up! New notifications will appear here.</p>
                </div>
              ) : (
                <div className="divide-y divide-stone-100 dark:divide-stone-800">
                  {notifications.map((notification) => (
                    <div
                      key={notification.id}
                      className={`p-4 hover:bg-stone-50 dark:hover:bg-stone-800 cursor-pointer transition-all duration-200 border-l-4 ${getPriorityColor(notification.priority)} ${
                        !notification.read ? 'bg-orange-50 dark:bg-orange-900/20' : ''
                      } hover:-translate-y-0.5 hover:shadow-md`}
                      onClick={() => handleNotificationClick(notification)}
                    >
                      <div className="flex items-start gap-3">
                        <div className="flex-shrink-0 mt-0.5">
                          {getNotificationIcon(notification.type)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between">
                            <h4 className={`text-sm font-medium text-stone-900 dark:text-stone-100 ${
                              !notification.read ? 'font-semibold' : ''
                            }`}>
                              {notification.title}
                            </h4>
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                removeNotification(notification.id)
                              }}
                              className="ml-2 p-1 text-stone-400 dark:text-stone-500 hover:text-stone-600 dark:hover:text-stone-300 rounded transition-all duration-200 hover:bg-stone-100 dark:hover:bg-stone-700"
                              aria-label="Remove notification"
                            >
                              <X className="w-4 h-4" />
                            </button>
                          </div>
                          <p className="text-sm text-stone-600 dark:text-stone-400 mt-1 line-clamp-2">
                            {notification.message}
                          </p>
                          <div className="flex items-center justify-between mt-2">
                            <span className="text-xs text-stone-500 dark:text-stone-500">
                              {formatTimestamp(notification.timestamp)}
                            </span>
                            {notification.actionRequired && (
                              <span className="px-2 py-1 bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 text-xs rounded-full font-medium">
                                Action Required
                              </span>
                            )}
                          </div>
                        </div>
                        {!notification.read && (
                          <div className="w-2 h-2 bg-orange-500 dark:bg-orange-400 rounded-full flex-shrink-0 mt-2" />
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  )
}

const DEFAULT_NOTIFICATIONS: Notification[] = [
  {
    id: '1',
