'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, Users, MapPin, Calendar, Clock, Trash2, Edit3, MessageCircle } from 'lucide-react'

interface GroupChatMessage {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  message: string
  timestamp: Date
  type: 'text' | 'system' | 'location' | 'task'
  metadata?: {
    taskId?: string
    locationId?: string
    eventId?: string
  }
}

interface GroupChatUser {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  lastSeen?: Date
}

interface GroupChatProps {
  tripId?: string
  currentUserId?: string
  users?: GroupChatUser[]
  messages?: GroupChatMessage[]
  onSendMessage?: (message: string) => void
  onDeleteMessage?: (messageId: string) => void
  onEditMessage?: (messageId: string, newMessage: string) => void
  className?: string
  isLoading?: boolean
}

export function GroupChatSchema({
  tripId = 'trip-1',
  currentUserId = 'user-1',
  users = DEFAULT_USERS,
  messages = DEFAULT_MESSAGES,
  onSendMessage = (message: string) => console.log('Send message:', message),
  onDeleteMessage = (messageId: string) => console.log('Delete message:', messageId),
  onEditMessage = (messageId: string, newMessage: string) => console.log('Edit message:', messageId, newMessage),
  className = '',
  isLoading = false
}: GroupChatProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null)
  const [editingText, setEditingText] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = async () => {
    if (newMessage.trim()) {
      try {
        setError(null)
        await onSendMessage(newMessage.trim())
        setNewMessage('')
        setIsTyping(false)
      } catch (err) {
        setError('Failed to send message. Please try again.')
      }
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleEditMessage = (messageId: string) => {
    const message = messages.find(m => m.id === messageId)
    if (message) {
      setEditingMessageId(messageId)
      setEditingText(message.message)
    }
  }

  const handleSaveEdit = async () => {
    if (editingMessageId && editingText.trim()) {
      try {
        setError(null)
        await onEditMessage(editingMessageId, editingText.trim())
        setEditingMessageId(null)
        setEditingText('')
      } catch (err) {
        setError('Failed to edit message. Please try again.')
      }
    }
  }

  const handleCancelEdit = () => {
    setEditingMessageId(null)
    setEditingText('')
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const getMessageIcon = (type: string) => {
    switch (type) {
      case 'location':
        return <MapPin className="w-4 h-4 text-primary dark:text-primary" />
      case 'task':
        return <Calendar className="w-4 h-4 text-accent dark:text-accent" />
      default:
        return null
    }
  }

  const onlineUsers = users.filter(user => user.isOnline)

  if (isLoading) {
    return (
      <div className={`flex flex-col h-full bg-surface dark:bg-surface ${className}`}>
        <div className="flex items-center justify-between p-4 border-b border-border dark:border-border bg-surface dark:bg-surface">
          <div className="flex items-center gap-3">
            <div className="h-6 bg-muted dark:bg-muted rounded w-24 animate-pulse"></div>
            <div className="h-4 bg-muted dark:bg-muted rounded w-16 animate-pulse"></div>
          </div>
          <div className="flex -space-x-2">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="w-8 h-8 bg-muted dark:bg-muted rounded-full animate-pulse"></div>
            ))}
          </div>
        </div>
        <div className="flex-1 p-4 space-y-4">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="flex gap-3">
              <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full animate-pulse"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 bg-muted dark:bg-muted rounded w-1/4 animate-pulse"></div>
                <div className="h-10 bg-muted dark:bg-muted rounded-2xl w-3/4 animate-pulse"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className={`flex flex-col h-full bg-surface dark:bg-surface shadow-lg ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-border dark:border-border bg-surface dark:bg-surface">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Users className="w-5 h-5 text-secondary dark:text-secondary" />
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground">Trip Chat</h2>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-2 h-2 bg-accent dark:bg-accent rounded-full"></div>
            <span className="text-sm text-mutedForeground dark:text-mutedForeground">{onlineUsers.length} online</span>
          </div>
        </div>

        {/* Online Users */}
        <div className="flex -space-x-2">
          {onlineUsers.slice(0, 4).map((user) => (
            <div
              key={user.id}
              className="relative w-8 h-8 rounded-full bg-gradient-to-br from-primary to-primary/80 dark:from-primary dark:to-primary/80 border-2 border-surface dark:border-surface flex items-center justify-center transition-transform duration-200 hover:scale-110 hover:z-10"
              title={user.name}
            >
              <span className="text-xs font-medium text-primaryForeground dark:text-primaryForeground">
                {user.name.charAt(0).toUpperCase()}
              </span>
              <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-accent dark:bg-accent border-2 border-surface dark:border-surface rounded-full"></div>
            </div>
          ))}
          {onlineUsers.length > 4 && (
            <div className="w-8 h-8 rounded-full bg-muted dark:bg-muted border-2 border-surface dark:border-surface flex items-center justify-center transition-transform duration-200 hover:scale-110">
              <span className="text-xs font-medium text-mutedForeground dark:text-mutedForeground">
                +{onlineUsers.length - 4}
              </span>
            </div>
          )}
        </div>
      </div>

      {/* Error State */}
      {error && (
        <div className="mx-4 mt-4 rounded-lg bg-destructive/10 dark:bg-destructive/20 border border-destructive/20 dark:border-destructive/30 p-3">
          <p className="text-sm text-destructive dark:text-destructive">{error}</p>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <MessageCircle className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No messages yet</h3>
            <p className="text-mutedForeground dark:text-mutedForeground text-sm">Start the conversation with your travel companions</p>
          </div>
        ) : (
          messages.map((message, index) => {
            const prevMessage = messages[index - 1]
            const showDate = !prevMessage || 
              formatDate(message.timestamp) !== formatDate(prevMessage.timestamp)
            const isCurrentUser = message.userId === currentUserId
            const user = users.find(u => u.id === message.userId)

            return (
              <div key={message.id}>
                {/* Date Separator */}
                {showDate && (
                  <div className="flex items-center justify-center my-4">
                    <div className="px-3 py-1 bg-muted dark:bg-muted rounded-full">
                      <span className="text-xs font-medium text-mutedForeground dark:text-mutedForeground">
                        {formatDate(message.timestamp)}
                      </span>
                    </div>
                  </div>
                )}

                {/* System Messages */}
                {message.type === 'system' && (
                  <div className="flex justify-center">
                    <div className="px-3 py-2 bg-muted dark:bg-muted rounded-lg max-w-xs">
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground text-center">{message.message}</p>
                    </div>
                  </div>
                )}

                {/* Regular Messages */}
                {message.type !== 'system' && (
                  <div className={`flex gap-3 group ${isCurrentUser ? 'flex-row-reverse' : ''}`}>
                    {/* Avatar */}
                    {!isCurrentUser && (
                      <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-primary/80 dark:from-primary dark:to-primary/80 flex items-center justify-center flex-shrink-0">
                        <span className="text-xs font-medium text-primaryForeground dark:text-primaryForeground">
                          {user?.name.charAt(0).toUpperCase()}
                        </span>
                      </div>
                    )}

                    <div className={`flex flex-col max-w-xs lg:max-w-md ${isCurrentUser ? 'items-end' : 'items-start'}`}>
                      {/* User Name & Time */}
                      {!isCurrentUser && (
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-sm font-medium text-foreground dark:text-foreground">{user?.name}</span>
                          <span className="text-xs text-mutedForeground dark:text-mutedForeground">{formatTime(message.timestamp)}</span>
                        </div>
                      )}

                      {/* Message Bubble */}
                      <div
                        className={`relative px-4 py-2 rounded-2xl transition-all duration-200 ${
                          isCurrentUser
                            ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground'
                            : 'bg-muted dark:bg-muted text-foreground dark:text-foreground'
                        } ${message.type !== 'text' ? 'border border-border dark:border-border' : ''}`}
                      >
                        {/* Message Content */}
                        {editingMessageId === message.id ? (
                          <div className="space-y-2">
                            <input
                              type="text"
                              value={editingText}
                              onChange={(e) => setEditingText(e.target.value)}
                              className="w-full px-2 py-1 text-sm bg-surface dark:bg-surface border border-border dark:border-border rounded text-foreground dark:text-foreground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20 dark:focus:ring-primary/20 transition-all duration-200"
                              onKeyPress={(e) => {
                                if (e.key === 'Enter') handleSaveEdit()
                                if (e.key === 'Escape') handleCancelEdit()
                              }}
                              autoFocus
                            />
                            <div className="flex gap-2">
                              <button
                                onClick={handleSaveEdit}
                                className="px-2 py-1 text-xs bg-accent dark:bg-accent text-accentForeground dark:text-accentForeground rounded hover:bg-accent/90 dark:hover:bg-accent/90 transition-all duration-150 hover:scale-105 active:scale-95"
                              >
                                Save
                              </button>
                              <button
                                onClick={handleCancelEdit}
                                className="px-2 py-1 text-xs bg-secondary dark:bg-secondary text-secondaryForeground dark:text-secondaryForeground rounded hover:bg-secondary/90 dark:hover:bg-secondary/90 transition-all duration-150 hover:scale-105 active:scale-95"
                              >
                                Cancel
                              </button>
                            </div>
                          </div>
                        ) : (
                          <div className="flex items-start gap-2">
                            {getMessageIcon(message.type)}
                            <p className="text-sm leading-relaxed">{message.message}</p>
                          </div>
                        )}

                        {/* Message Actions */}
                        {isCurrentUser && editingMessageId !== message.id && (
                          <div className="absolute -left-12 top-1/2 transform -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                            <div className="flex gap-1">
                              <button
                                onClick={() => handleEditMessage(message.id)}
                                className="p-1 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground rounded transition-all duration-150 hover:scale-110 active:scale-95"
                                aria-label="Edit message"
                              >
                                <Edit3 className="w-3 h-3" />
                              </button>
                              <button
                                onClick={() => onDeleteMessage(message.id)}
                                className="p-1 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive rounded transition-all duration-150 hover:scale-110 active:scale-95"
                                aria-label="Delete message"
                              >
                                <Trash2 className="w-3 h-3" />
                              </button>
                            </div>
                          </div>
                        )}
                      </div>

                      {/* Current User Time */}
                      {isCurrentUser && (
                        <span className="text-xs text-mutedForeground dark:text-mutedForeground mt-1">{formatTime(message.timestamp)}</span>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Typing Indicator */}
      {isTyping && (
        <div className="px-4 py-2">
          <div className="flex items-center gap-2 text-sm text-mutedForeground dark:text-mutedForeground">
            <div className="flex gap-1">
              <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce"></div>
              <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
              <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
            </div>
            <span>Someone is typing...</span>
          </div>
        </div>
      )}

      {/* Message Input */}
      <div className="p-4 border-t border-border dark:border-border bg-surface dark:bg-surface">
        <div className="flex items-end gap-3">
          <div className="flex-1">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => {
                setNewMessage(e.target.value)
