  location?: string
  description?: string
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  isAvailable: boolean
}

interface CalendarAPIIntegrationProps {
  tripId?: string
  groupMembers?: GroupMember[]
  onEventCreate?: (event: Omit<CalendarEvent, 'id'>) => void
  onAvailabilityCheck?: (members: string[]) => Promise<GroupMember[]>
  onInviteSend?: (eventId: string, members: string[]) => Promise<void>
}

export function CalendarAPIIntegration({
  tripId = 'trip-123',
  groupMembers = DEFAULT_GROUP_MEMBERS,
  onEventCreate = (event) => console.log('Event created:', event),
  onAvailabilityCheck = async (members) => {
    await new Promise(resolve => setTimeout(resolve, 1000))
    return DEFAULT_GROUP_MEMBERS.map(member => ({
      ...member,
      isAvailable: Math.random() > 0.3
    }))
  },
  onInviteSend = async (eventId, members) => {
    await new Promise(resolve => setTimeout(resolve, 500))
    console.log('Invites sent for event:', eventId, 'to:', members)
  }
}: CalendarAPIIntegrationProps = {}) {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date())
  const [selectedTime, setSelectedTime] = useState<string>('10:00')
  const [eventTitle, setEventTitle] = useState<string>('')
  const [eventLocation, setEventLocation] = useState<string>('')
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [availability, setAvailability] = useState<GroupMember[]>([])
  const [isCheckingAvailability, setIsCheckingAvailability] = useState(false)
  const [isSendingInvites, setIsSendingInvites] = useState(false)
  const [lastChecked, setLastChecked] = useState<Date | null>(null)
  const [events, setEvents] = useState<CalendarEvent[]>(DEFAULT_EVENTS)
  const [error, setError] = useState<string>('')

  const checkAvailability = async () => {
    if (selectedMembers.length === 0) return

    setIsCheckingAvailability(true)
    setError('')
    try {
      const result = await onAvailabilityCheck(selectedMembers)
      setAvailability(result)
      setLastChecked(new Date())
    } catch (error) {
      setError('Failed to check availability. Please try again.')
      console.error('Failed to check availability:', error)
    } finally {
      setIsCheckingAvailability(false)
    }
  }

  const createEvent = async () => {
    if (!eventTitle.trim() || selectedMembers.length === 0) return

    const eventDateTime = new Date(selectedDate)
    const [hours, minutes] = selectedTime.split(':').map(Number)
    eventDateTime.setHours(hours, minutes)

    const newEvent: Omit<CalendarEvent, 'id'> = {
      title: eventTitle,
      start: eventDateTime,
      end: new Date(eventDateTime.getTime() + 2 * 60 * 60 * 1000),
      attendees: selectedMembers,
      location: eventLocation || undefined,
      description: `Off-roading trip event for ${tripId}`
    }

    setError('')
    try {
      await onEventCreate(newEvent)

      const eventWithId: CalendarEvent = {
        ...newEvent,
        id: `event-${Date.now()}`
      }
      setEvents(prev => [...prev, eventWithId])

      setIsSendingInvites(true)
      await onInviteSend(eventWithId.id, selectedMembers)

      setEventTitle('')
      setEventLocation('')
      setSelectedMembers([])
      setAvailability([])
    } catch (error) {
      setError('Failed to create event. Please try again.')
      console.error('Failed to create event:', error)
    } finally {
      setIsSendingInvites(false)
    }
  }

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    })
  }

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true 
    })
  }

  useEffect(() => {
    if (selectedMembers.length > 0) {
      checkAvailability()
    } else {
      setAvailability([])
    }
  }, [selectedDate, selectedTime])

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
