                  placeholder="e.g., Moab Trail Head"
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-border/80 dark:hover:border-border/80"
                  aria-label="Event location"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-3">
