export function TripSchema({
  onSchemaUpdate = () => console.log('Schema updated')
}: TripSchemaProps = {}) {
  const [schema, setSchema] = useState<DatabaseSchema>(DEFAULT_SCHEMA);
  const [selectedTable, setSelectedTable] = useState<string>('trips');
  const [viewMode, setViewMode] = useState<'overview' | 'detailed'>('overview');

  const getTableIcon = (tableName: string) => {
    const icons: Record<string, any> = {
      trips: MapPin,
      users: Users,
      trip_participants: Users,
      locations: MapPin,
      tasks: CheckSquare,
      meals: Utensils,
      messages: MessageSquare,
      rsvps: Calendar
    };
    return icons[tableName] || Table;
  };

  const getTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      uuid: 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800',
      text: 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800',
      timestamp: 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-300 dark:border-purple-800',
      integer: 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800',
      decimal: 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800',
      boolean: 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800',
      enum: 'bg-yellow-50 text-yellow-700 border-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:border-yellow-800',
      jsonb: 'bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-900/20 dark:text-indigo-300 dark:border-indigo-800',
      'text[]': 'bg-teal-50 text-teal-700 border-teal-200 dark:bg-teal-900/20 dark:text-teal-300 dark:border-teal-800'
    };
    return colors[type] || 'bg-stone-50 text-stone-700 border-stone-200 dark:bg-stone-900/20 dark:text-stone-300 dark:border-stone-800';
  };

  const selectedTableData = schema.tables.find(t => t.name === selectedTable);

