  const [activeTab, setActiveTab] = useState<'overview' | 'tasks' | 'meals' | 'weather' | 'chat'>('overview')
  const [trip, setTrip] = useState(initialData)
  const [newMessage, setNewMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const handleRSVP = (status: 'accepted' | 'declined') => {
    setIsLoading(true)
    setTimeout(() => {
      setTrip(prev => ({
        ...prev,
        members: prev.members.map(member => 
          member.id === 'current-user' 
            ? { ...member, rsvpStatus: status }
            : member
        )
      }))
      setIsLoading(false)
    }, 500)
