              {trip.weather.map((day, idx) => (
                <div key={idx} className="p-4 bg-muted/50 dark:bg-muted/50 rounded-lg text-center hover:bg-muted dark:hover:bg-muted transition-all duration-150 hover:scale-105">
                  <div className="text-sm font-medium mb-2">{day.day}</div>
                  <div className="text-3xl mb-2">{getWeatherIcon(day.condition)}</div>
                  <div className="text-sm text-mutedForeground dark:text-mutedForeground mb-3">{day.condition}</div>
                  <div className="flex justify-center gap-2 text-sm mb-3">
                    <span className="font-medium">{day.high}°</span>
                    <span className="text-mutedForeground dark:text-mutedForeground">{day.low}°</span>
                  </div>
                  <div className="space-y-1 text-xs text-mutedForeground dark:text-mutedForeground">
                    <div className="flex items-center justify-center gap-1">
                      <Droplets className="w-3 h-3" />
                      <span>{day.precipitation}%</span>
                    </div>
                    <div className="flex items-center justify-center gap-1">
                      <Wind className="w-3 h-3" />
                      <span>{day.wind} mph</span>
                    </div>
