'use client'

import { useState, useEffect } from 'react'
import { Send, Mail, CheckCircle, AlertCircle, Clock, Users, Inbox } from 'lucide-react'

interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
  sentAt?: Date
}

interface EmailCampaign {
  id: string
  templateId: string
  recipients: EmailRecipient[]
  scheduledFor?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed'
  createdAt: Date
}

interface ResendServiceProps {
  tripId?: string
  onEmailSent?: (campaignId: string) => void
  onError?: (error: string) => void
}

export function ResendService({
  tripId = 'trip-1',
  onEmailSent = () => console.log('Email sent'),
  onError = () => console.log('Email error')
}: ResendServiceProps = {}) {
  const [templates, setTemplates] = useState<EmailTemplate[]>(DEFAULT_TEMPLATES)
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>(DEFAULT_CAMPAIGNS)
  const [selectedTemplate, setSelectedTemplate] = useState<string>('')
  const [recipients, setRecipients] = useState<EmailRecipient[]>(DEFAULT_RECIPIENTS)
  const [selectedRecipients, setSelectedRecipients] = useState<string[]>(DEFAULT_RECIPIENTS.map(r => r.id))
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'send' | 'templates' | 'history'>('send')
  const [error, setError] = useState<string>('')

  const sendEmail = async (templateId: string, recipientIds: string[]) => {
    setIsLoading(true)
    setError('')

    try {
      await new Promise(resolve => setTimeout(resolve, 2000))

      const template = templates.find(t => t.id === templateId)
      const selectedRecipientsData = recipients.filter(r => recipientIds.includes(r.id))

      const newCampaign: EmailCampaign = {
        id: `campaign-${Date.now()}`,
        templateId,
        recipients: selectedRecipientsData.map(r => ({
          ...r,
          status: 'sent',
          sentAt: new Date()
        })),
        status: 'sent',
        createdAt: new Date()
      }

      setCampaigns(prev => [newCampaign, ...prev])
      onEmailSent(newCampaign.id)
      setSelectedTemplate('')
    } catch (error) {
      const errorMessage = 'Failed to send emails. Please try again.'
      setError(errorMessage)
      onError(errorMessage)
    } finally {
      setIsLoading(false)
    }
  }

  const toggleRecipient = (recipientId: string) => {
    setSelectedRecipients(prev => 
      prev.includes(recipientId) 
        ? prev.filter(id => id !== recipientId)
        : [...prev, recipientId]
    )
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-accent dark:text-accent" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
      case 'pending':
        return <Clock className="w-4 h-4 text-primary dark:text-primary" />
      default:
        return <Clock className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20'
      case 'failed':
        return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/10 dark:text-destructive dark:border-destructive/20'
      case 'pending':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      default:
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'invitation':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      case 'reminder':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      case 'update':
        return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20'
      case 'cancellation':
        return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/10 dark:text-destructive dark:border-destructive/20'
      default:
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-foreground dark:text-foreground mb-2">Email Service</h1>
          <p className="text-lg text-mutedForeground dark:text-mutedForeground">Send trip invitations and updates to your group</p>
        </div>

        <div className="flex space-x-1 mb-8 bg-muted dark:bg-muted p-1 rounded-xl">
          {[
            { id: 'send', label: 'Send Email', icon: Send },
            { id: 'templates', label: 'Templates', icon: Mail },
            { id: 'history', label: 'History', icon: Clock }
          ].map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveTab(id as any)}
              aria-label={`Switch to ${label} tab`}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-lg font-medium transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background ${
                activeTab === id
                  ? 'bg-primary text-primaryForeground shadow-md dark:bg-primary dark:text-primaryForeground'
                  : 'text-mutedForeground hover:text-foreground hover:bg-surface dark:text-mutedForeground dark:hover:text-foreground dark:hover:bg-surface'
              }`}
            >
              <Icon className="w-4 h-4" />
              <span className="hidden sm:inline">{label}</span>
            </button>
          ))}
        </div>

        {error && (
          <div className="mb-6 rounded-lg bg-destructive/10 border border-destructive/20 p-4 dark:bg-destructive/10 dark:border-destructive/20">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
              <p className="text-sm text-destructive dark:text-destructive">{error}</p>
            </div>
          </div>
        )}

        {activeTab === 'send' && (
          <div className="space-y-6">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:shadow-lg transition-all duration-300">
              <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-4">Select Template</h3>
              <div className="grid gap-3">
                {templates.map((template) => (
                  <label
                    key={template.id}
                    className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all duration-200 hover:-translate-y-1 hover:shadow-md ${
                      selectedTemplate === template.id
                        ? 'border-primary bg-primary/5 dark:border-primary dark:bg-primary/5'
                        : 'border-border hover:border-primary/50 bg-background dark:border-border dark:hover:border-primary/50 dark:bg-background'
                    }`}
                  >
                    <input
                      type="radio"
                      name="template"
                      value={template.id}
                      checked={selectedTemplate === template.id}
                      onChange={(e) => setSelectedTemplate(e.target.value)}
                      className="mt-1 text-primary focus:ring-primary focus:ring-offset-background dark:focus:ring-offset-background"
                    />
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <h4 className="font-medium text-foreground dark:text-foreground">{template.name}</h4>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getTypeColor(template.type)}`}>
                          {template.type}
                        </span>
                      </div>
                      <p className="text-sm text-foreground dark:text-foreground mb-2">{template.subject}</p>
                      <p className="text-xs text-mutedForeground dark:text-mutedForeground line-clamp-2">{template.content}</p>
                    </div>
                  </label>
                ))}
              </div>
            </div>

            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:shadow-lg transition-all duration-300">
              <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-4">Recipients</h3>
              <div className="space-y-3">
                {recipients.map((recipient) => (
                  <div
                    key={recipient.id}
                    className="flex items-center gap-3 p-3 bg-muted dark:bg-muted rounded-lg hover:bg-muted/80 dark:hover:bg-muted/80 transition-all duration-200"
                  >
                    <input
                      type="checkbox"
                      checked={selectedRecipients.includes(recipient.id)}
                      onChange={() => toggleRecipient(recipient.id)}
                      className="text-primary focus:ring-primary focus:ring-offset-background dark:focus:ring-offset-background rounded"
                    />
                    <div className="flex-1">
                      <p className="font-medium text-foreground dark:text-foreground">{recipient.name}</p>
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground">{recipient.email}</p>
                    </div>
                    {getStatusIcon(recipient.status)}
                  </div>
                ))}
              </div>
            </div>

            <button
              onClick={() => selectedTemplate && sendEmail(selectedTemplate, selectedRecipients)}
              disabled={!selectedTemplate || selectedRecipients.length === 0 || isLoading}
              aria-label={`Send email to ${selectedRecipients.length} recipients`}
              className="w-full flex items-center justify-center gap-2 px-6 py-4 bg-primary text-primaryForeground rounded-xl hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-medium shadow-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:bg-primary dark:text-primaryForeground dark:hover:bg-primary/90"
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  Send to {selectedRecipients.length} Recipients
                </>
              )}
            </button>
          </div>
        )}

        {activeTab === 'templates' && (
          <div className="space-y-4">
            {templates.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <Mail className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                </div>
                <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No templates yet</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">Get started by creating your first email template</p>
              </div>
            ) : (
              templates.map((template) => (
                <div
                  key={template.id}
                  className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:border-primary/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300"
                >
                  <div className="flex items-start justify-between mb-3">
                    <div>
                      <h3 className="text-lg font-semibold text-foreground dark:text-foreground">{template.name}</h3>
                      <p className="text-foreground dark:text-foreground">{template.subject}</p>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getTypeColor(template.type)}`}>
                      {template.type}
                    </span>
                  </div>
                  <p className="text-mutedForeground dark:text-mutedForeground text-sm leading-relaxed">{template.content}</p>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-4">
            {campaigns.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <Inbox className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                </div>
                <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No campaigns yet</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">Your email campaign history will appear here</p>
              </div>
            ) : (
              campaigns.map((campaign) => {
                const template = templates.find(t => t.id === campaign.templateId)
                const successCount = campaign.recipients.filter(r => r.status === 'sent').length

                return (
                  <div
                    key={campaign.id}
                    className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:border-primary/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300"
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <h3 className="text-lg font-semibold text-foreground dark:text-foreground">{template?.name}</h3>
                        <p className="text-foreground dark:text-foreground text-sm">{template?.subject}</p>
                        <p className="text-mutedForeground dark:text-mutedForeground text-xs mt-1">
                          {campaign.createdAt.toLocaleDateString()} at {campaign.createdAt.toLocaleTimeString()}
                        </p>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(campaign.status)}`}>
                        {campaign.status}
                      </span>
                    </div>

                    <div className="flex items-center gap-4 text-sm">
                      <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground">
                        <Users className="w-4 h-4" />
                        {campaign.recipients.length} recipients
                      </div>
                      <div className="flex items-center gap-2 text-accent dark:text-accent">
                        <CheckCircle className="w-4 h-4" />
                        {successCount} sent
                      </div>
                    </div>
                  </div>
                )
              })
            )}
          </div>
        )}
      </div>
    </div>
  )
}

