'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, MapPin, AlertCircle, CheckCircle, RefreshCw, Plus, X } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  location?: string
  description?: string
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
}

interface TripEvent {
  id: string
  title: string
  date: Date
  assignedTo?: string
  type: 'meal' | 'task' | 'activity'
  description?: string
}

interface CalendarIntegrationProps {
  groupMembers?: GroupMember[]
  tripEvents?: TripEvent[]
  onEventCreate?: (event: CalendarEvent) => void
  onAvailabilityCheck?: (dates: Date[]) => Promise<{ [email: string]: boolean[] }>
  onInviteSend?: (event: CalendarEvent) => void
}

export function CalendarIntegration({
  groupMembers = DEFAULT_GROUP_MEMBERS,
  tripEvents = DEFAULT_TRIP_EVENTS,
  onEventCreate = () => console.log('Event created'),
  onAvailabilityCheck = mockAvailabilityCheck,
  onInviteSend = () => console.log('Invite sent')
}: CalendarIntegrationProps = {}) {
  const [selectedDates, setSelectedDates] = useState<Date[]>([])
  const [availability, setAvailability] = useState<{ [email: string]: boolean[] }>({})
  const [isCheckingAvailability, setIsCheckingAvailability] = useState(false)
  const [isCreatingEvent, setIsCreatingEvent] = useState(false)
  const [eventTitle, setEventTitle] = useState('')
  const [eventDescription, setEventDescription] = useState('')
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const checkGroupAvailability = async (dates: Date[]) => {
    if (dates.length === 0) return

    setIsCheckingAvailability(true)
    setError(null)
    try {
      const result = await onAvailabilityCheck(dates)
      setAvailability(result)
    } catch (error) {
      console.error('Failed to check availability:', error)
      setError('Failed to check group availability. Please try again.')
    } finally {
      setIsCheckingAvailability(false)
    }
  }

  const handleDateSelect = (date: Date) => {
    const dateString = date.toDateString()
    const isSelected = selectedDates.some(d => d.toDateString() === dateString)

    if (isSelected) {
      setSelectedDates(prev => prev.filter(d => d.toDateString() !== dateString))
    } else {
      const newDates = [...selectedDates, date]
      setSelectedDates(newDates)
      checkGroupAvailability(newDates)
    }
  }

  const handleCreateEvent = async () => {
    if (!eventTitle || selectedDates.length === 0) return

    setIsCreatingEvent(true)
    setError(null)
    try {
      const event: CalendarEvent = {
        id: Date.now().toString(),
        title: eventTitle,
        start: selectedDates[0],
        end: selectedDates[selectedDates.length - 1],
        attendees: selectedMembers,
        description: eventDescription
      }

      await onEventCreate(event)
      await onInviteSend(event)

      setEventTitle('')
      setEventDescription('')
      setSelectedMembers([])
      setSelectedDates([])
      setShowCreateForm(false)
    } catch (error) {
      console.error('Failed to create event:', error)
      setError('Failed to create event. Please try again.')
    } finally {
      setIsCreatingEvent(false)
    }
  }

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  const getAvailabilityStatus = (memberEmail: string, dateIndex: number) => {
    return availability[memberEmail]?.[dateIndex] ?? null
  }

  const generateCalendarDays = () => {
    const today = new Date()
    const days = []

    for (let i = 0; i < 30; i++) {
      const date = new Date(today)
      date.setDate(today.getDate() + i)
      days.push(date)
    }

    return days
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background transition-colors duration-300">
      <div className="max-w-4xl mx-auto p-6 space-y-6 font-sans">
        {error && (
          <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-4 transition-all duration-200">
            <div className="flex items-center gap-3">
              <AlertCircle className="w-5 h-5 text-destructive flex-shrink-0" />
              <p className="text-sm text-destructive">{error}</p>
              <button
                onClick={() => setError(null)}
                className="ml-auto text-destructive hover:text-destructive/80 transition-colors duration-150"
                aria-label="Dismiss error"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        <div className="bg-surface border border-border rounded-xl p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-primary/10 rounded-lg">
              <Calendar className="w-6 h-6 text-primary" />
            </div>
            <div>
              <h1 className="text-xl font-semibold text-foreground">Trip Calendar & Scheduling</h1>
              <p className="text-mutedForeground text-sm mt-1">
                Check group availability and schedule your adventure
              </p>
            </div>
          </div>
        </div>

        <div className="bg-surface border border-border rounded-xl p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-lg font-medium text-foreground">Select Dates</h2>
            {selectedDates.length > 0 && (
              <button
                onClick={() => setShowCreateForm(true)}
                className="inline-flex items-center gap-2 px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                aria-label="Create new event"
              >
                <Plus className="w-4 h-4" />
                Create Event
              </button>
            )}
          </div>

          <div className="grid grid-cols-7 gap-2 mb-4">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
              <div key={day} className="text-center text-xs font-medium text-mutedForeground py-2">
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-2">
            {generateCalendarDays().map((date, index) => {
              const isSelected = selectedDates.some(d => d.toDateString() === date.toDateString())
              const isToday = date.toDateString() === new Date().toDateString()

              return (
                <button
                  key={index}
                  onClick={() => handleDateSelect(date)}
                  className={`
                    aspect-square p-2 rounded-lg text-sm font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2
                    ${isSelected 
                      ? 'bg-primary text-primaryForeground shadow-md hover:bg-primary/90 hover:scale-[1.05]' 
                      : 'bg-muted text-mutedForeground hover:bg-muted/80 hover:text-foreground hover:scale-[1.02]'
                    }
                    ${isToday ? 'ring-2 ring-accent ring-offset-2' : ''}
                  `}
                  aria-label={`Select ${date.toLocaleDateString()}`}
                >
                  {date.getDate()}
                </button>
              )
            })}
          </div>
        </div>

        {selectedDates.length > 0 && (
          <div className="bg-surface border border-border rounded-xl p-6 shadow-sm hover:shadow-md transition-all duration-300">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-accent/10 rounded-lg">
                <Users className="w-5 h-5 text-accent" />
              </div>
              <h3 className="text-lg font-medium text-foreground">Group Availability</h3>
              {isCheckingAvailability && (
                <RefreshCw className="w-4 h-4 text-accent animate-spin" />
              )}
            </div>

            {isCheckingAvailability ? (
              <div className="space-y-3 animate-pulse">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-muted rounded-full"></div>
                      <div className="h-4 bg-muted rounded w-24"></div>
                    </div>
                    <div className="flex gap-2">
                      {selectedDates.map((_, dateIndex) => (
                        <div key={dateIndex} className="w-6 h-6 bg-muted rounded-full"></div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-3">
                {groupMembers.map(member => (
                  <div key={member.id} className="flex items-center justify-between p-4 bg-muted/30 rounded-lg hover:bg-muted/50 transition-colors duration-200">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center text-primaryForeground text-sm font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <span className="text-foreground font-medium">{member.name}</span>
                    </div>

                    <div className="flex gap-2">
                      {selectedDates.map((_, dateIndex) => {
                        const status = getAvailabilityStatus(member.email, dateIndex)
                        return (
                          <div
                            key={dateIndex}
                            className={`w-6 h-6 rounded-full flex items-center justify-center transition-all duration-200 ${
                              status === true 
                                ? 'bg-accent' 
                                : status === false 
                                  ? 'bg-destructive' 
                                  : 'bg-muted'
                            }`}
                            title={
                              status === true ? 'Available' : 
                              status === false ? 'Unavailable' : 
                              'Checking...'
                            }
                          >
                            {status === true && <CheckCircle className="w-3 h-3 text-accentForeground" />}
                            {status === false && <AlertCircle className="w-3 h-3 text-destructiveForeground" />}
                            {status === null && <Clock className="w-3 h-3 text-mutedForeground" />}
                          </div>
                        )
                      })}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        <div className="bg-surface border border-border rounded-xl p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h3 className="text-lg font-medium text-foreground mb-6">Scheduled Events</h3>

          {tripEvents.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Calendar className="w-8 h-8 text-mutedForeground" />
              </div>
              <h4 className="text-lg font-medium text-foreground mb-2">No events scheduled</h4>
              <p className="text-mutedForeground text-sm">Create your first event to get started</p>
            </div>
          ) : (
            <div className="space-y-3">
              {tripEvents.map(event => (
                <div key={event.id} className="flex items-center justify-between p-4 bg-muted/30 rounded-lg hover:bg-muted/50 hover:-translate-y-0.5 transition-all duration-200">
                  <div className="flex items-center gap-4">
                    <div className={`w-3 h-3 rounded-full ${
                      event.type === 'meal' ? 'bg-primary' :
                      event.type === 'task' ? 'bg-secondary' : 'bg-accent'
                    }`} />
                    <div>
                      <h4 className="text-foreground font-medium">{event.title}</h4>
                      <p className="text-mutedForeground text-sm">
                        {event.date.toLocaleDateString()} at {event.date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </p>
                      {event.description && (
                        <p className="text-mutedForeground text-xs mt-1">{event.description}</p>
                      )}
                    </div>
                  </div>

                  {event.assignedTo && (
                    <div className="px-3 py-1 bg-accent/20 text-accent rounded-full text-xs font-medium border border-accent/30">
                      {groupMembers.find(m => m.id === event.assignedTo)?.name || 'Unknown'}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {showCreateForm && (
          <div className="fixed inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 z-50 transition-all duration-300">
            <div className="bg-surface rounded-xl border border-border p-6 w-full max-w-md shadow-xl animate-in fade-in-0 zoom-in-95 duration-300">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-medium text-foreground">Create Calendar Event</h3>
                <button
                  onClick={() => setShowCreateForm(false)}
                  className="p-1 text-mutedForeground hover:text-foreground transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring rounded"
                  aria-label="Close dialog"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Event Title *
                  </label>
                  <input
                    type="text"
                    value={eventTitle}
                    onChange={(e) => setEventTitle(e.target.value)}
                    className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    placeholder="Enter event title"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Description
                  </label>
                  <textarea
                    value={eventDescription}
                    onChange={(e) => setEventDescription(e.target.value)}
                    className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 resize-none"
                    rows={3}
                    placeholder="Event description (optional)"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground mb-3">
                    Invite Members
                  </label>
                  <div className="space-y-2">
                    {groupMembers.map(member => (
                      <label key={member.id} className="flex items-center gap-3 cursor-pointer p-2 rounded-lg hover:bg-muted/30 transition-colors duration-150">
                        <input
                          type="checkbox"
                          checked={selectedMembers.includes(member.id)}
                          onChange={() => toggleMemberSelection(member.id)}
                          className="w-4 h-4 text-primary bg-background border-border rounded focus:ring-ring focus:ring-2 transition-colors duration-150"
                        />
                        <div className="w-6 h-6 bg-primary rounded-full flex items-center justify-center text-primaryForeground text-xs font-medium">
                          {member.name.charAt(0)}
                        </div>
                        <span className="text-foreground">{member.name}</span>
                      </label>
                    ))}
                  </div>
                </div>

                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => setShowCreateForm(false)}
                    className="flex-1 px-4 py-2 bg-muted text-mutedForeground rounded-lg hover:bg-muted/80 hover:text-foreground transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleCreateEvent}
                    disabled={!eventTitle || selectedDates.length === 0 || isCreatingEvent}
                    className="flex-1 px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  >
                    {isCreatingEvent ? (
                      <span className="flex items-center gap-2">
                        <RefreshCw className="w-4 h-4 animate-spin" />
                        Creating...
                      </span>
                    ) : (
                      'Create & Send Invites'
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

