  groupMembers = DEFAULT_MEMBERS,
  onDateSelect = (date) => console.log('Date selected:', date),
  onInviteSend = (members) => console.log('Invites sent to:', members)
}: TripCalendarIntegrationProps = {}) {
  const [selectedDate, setSelectedDate] = useState<string>('')
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>(DEFAULT_EVENTS)
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle')

  useEffect(() => {
    const syncCalendars = async () => {
      setSyncStatus('syncing')
      await new Promise(resolve => setTimeout(resolve, 2000))
      setSyncStatus('success')
      setTimeout(() => setSyncStatus('idle'), 3000)
    }

    syncCalendars()
  }, [])

  const handleDateSelect = (date: string) => {
    setSelectedDate(date)
    onDateSelect(date)
  }

  const handleSendInvites = async () => {
    setIsLoading(true)
    await new Promise(resolve => setTimeout(resolve, 1500))
    onInviteSend(selectedMembers)
    setShowInviteModal(false)
    setIsLoading(false)
    setSyncStatus('success')
  }

  const getDateAvailability = (date: string) => {
    const conflicts = calendarEvents.filter(event => 
      event.date === date && event.type === 'conflict'
    ).length
    const total = groupMembers.length
    return {
      available: total - conflicts,
      total,
      percentage: ((total - conflicts) / total) * 100
    }
  }

  const getMemberStatus = (memberId: string, date: string) => {
    const conflict = calendarEvents.find(event => 
      event.date === date && 
      event.type === 'conflict' && 
      event.attendees?.includes(memberId)
    )
    return conflict ? 'busy' : 'available'
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
