                <div className="flex items-center gap-2 text-primary dark:text-primary">
                  <div className="w-4 h-4 border-2 border-primary dark:border-primary border-t-transparent rounded-full animate-spin"></div>
                  <span className="text-sm">Syncing...</span>
                </div>
