            aria-label="Send calendar invites to group members"
          >
            <Plus className="w-4 h-4" />
            Send Calendar Invites
          </button>
        </div>

        {/* Proposed Dates */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
          <h2 className="text-xl font-semibold text-foreground dark:text-foreground mb-6 flex items-center gap-2">
            <Calendar className="w-5 h-5 text-accent dark:text-accent" />
