              return (
                <button
                  key={date}
                  onClick={() => handleDateSelect(date)}
                  className={`p-4 rounded-lg border transition-all duration-200 text-left hover:-translate-y-1 hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                    isSelected
                      ? 'border-accent dark:border-accent bg-accent/10 dark:bg-accent/10'
                      : 'border-border dark:border-border hover:border-mutedForeground dark:hover:border-mutedForeground bg-muted/50 dark:bg-muted/50'
                  }`}
                  aria-label={`Select date ${new Date(date).toLocaleDateString()} with ${availability.available} of ${availability.total} members available`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <span className="font-medium text-foreground dark:text-foreground">
                      {new Date(date).toLocaleDateString('en-US', {
                        weekday: 'short',
                        month: 'short',
                        day: 'numeric'
                      })}
                    </span>
                    <div className={`w-3 h-3 rounded-full ${
                      availability.percentage >= 80 ? 'bg-accent dark:bg-accent' :
                      availability.percentage >= 50 ? 'bg-primary dark:bg-primary' : 'bg-destructive dark:bg-destructive'
                    }`}></div>
                  </div>

                  <div className="text-sm text-mutedForeground dark:text-mutedForeground mb-3">
                    {availability.available}/{availability.total} available
                  </div>

                  <div className="w-full bg-muted dark:bg-muted rounded-full h-2">
                    <div
                      className={`h-2 rounded-full transition-all duration-300 ${
                        availability.percentage >= 80 ? 'bg-accent dark:bg-accent' :
                        availability.percentage >= 50 ? 'bg-primary dark:bg-primary' : 'bg-destructive dark:bg-destructive'
                      }`}
                      style={{ width: `${availability.percentage}%` }}
                    ></div>
                  </div>
                </button>
              )
            })}
          </div>
        </div>

        {/* Group Availability */}
        {selectedDate && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-6 flex items-center gap-2">
              <Users className="w-5 h-5 text-accent dark:text-accent" />
              Group Availability for {new Date(selectedDate).toLocaleDateString()}
            </h3>

            <div className="space-y-3">
              {groupMembers.map((member) => {
                const status = getMemberStatus(member.id, selectedDate)

                return (
                  <div key={member.id} className="flex items-center justify-between p-4 bg-muted/50 dark:bg-muted/50 rounded-lg hover:bg-muted dark:hover:bg-muted transition-all duration-200">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-primary dark:bg-primary rounded-full flex items-center justify-center text-primaryForeground dark:text-primaryForeground font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-medium text-foreground dark:text-foreground">{member.name}</p>
                        <p className="text-sm text-mutedForeground dark:text-mutedForeground">{member.email}</p>
                      </div>
                    </div>

                    <div className={`px-3 py-1 rounded-full text-xs font-medium ${
                      status === 'available'
                        ? 'bg-accent/20 dark:bg-accent/20 text-accent dark:text-accent border border-accent/30 dark:border-accent/30'
                        : 'bg-destructive/20 dark:bg-destructive/20 text-destructive dark:text-destructive border border-destructive/30 dark:border-destructive/30'
                    }`}>
                      {status === 'available' ? 'Available' : 'Busy'}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Calendar Events */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
          <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-6 flex items-center gap-2">
            <Clock className="w-5 h-5 text-accent dark:text-accent" />
            Upcoming Events
          </h3>

          {calendarEvents.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Calendar className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
              </div>
              <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No events yet</h3>
              <p className="text-mutedForeground dark:text-mutedForeground text-sm">Calendar events will appear here once synced</p>
            </div>
          ) : (
            <div className="space-y-3">
              {calendarEvents.slice(0, 5).map((event) => (
                <div key={event.id} className="flex items-center gap-3 p-4 bg-muted/50 dark:bg-muted/50 rounded-lg hover:bg-muted dark:hover:bg-muted transition-all duration-200">
                  <div className={`w-3 h-3 rounded-full ${
                    event.type === 'trip' ? 'bg-accent dark:bg-accent' :
                    event.type === 'conflict' ? 'bg-destructive dark:bg-destructive' : 'bg-primary dark:bg-primary'
                  }`}></div>

                  <div className="flex-1">
                    <p className="font-medium text-foreground dark:text-foreground">{event.title}</p>
                    <div className="flex items-center gap-4 text-sm text-mutedForeground dark:text-mutedForeground">
                      <span>{new Date(event.date).toLocaleDateString()}</span>
                      <span>{event.time}</span>
                      {event.location && (
                        <span className="flex items-center gap-1">
                          <MapPin className="w-3 h-3" />
                          {event.location}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Invite Modal */}
        {showInviteModal && (
          <div className="fixed inset-0 bg-black/60 dark:bg-black/80 flex items-center justify-center p-4 z-50 backdrop-blur-sm">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 w-full max-w-md shadow-xl">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-semibold text-foreground dark:text-foreground">Send Calendar Invites</h3>
                <button
                  onClick={() => setShowInviteModal(false)}
                  className="text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground transition-colors p-1 rounded-md hover:bg-muted dark:hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring"
                  aria-label="Close modal"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-3 mb-6">
                {groupMembers.map((member) => (
                  <label key={member.id} className="flex items-center gap-3 p-3 bg-muted/50 dark:bg-muted/50 rounded-lg cursor-pointer hover:bg-muted dark:hover:bg-muted transition-all duration-200">
                    <input
                      type="checkbox"
                      checked={selectedMembers.includes(member.id)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedMembers([...selectedMembers, member.id])
                        } else {
                          setSelectedMembers(selectedMembers.filter(id => id !== member.id))
                        }
                      }}
                      className="w-4 h-4 text-primary dark:text-primary bg-surface dark:bg-surface border-border dark:border-border rounded focus:ring-ring dark:focus:ring-ring focus:ring-2"
                    />
                    <div className="w-8 h-8 bg-primary dark:bg-primary rounded-full flex items-center justify-center text-primaryForeground dark:text-primaryForeground font-medium text-sm">
                      {member.name.charAt(0)}
                    </div>
                    <span className="text-foreground dark:text-foreground">{member.name}</span>
                  </label>
                ))}
              </div>

              <div className="flex gap-3">
                <button
                  onClick={() => setShowInviteModal(false)}
                  className="flex-1 px-4 py-3 bg-muted dark:bg-muted text-foreground dark:text-foreground rounded-lg hover:bg-mutedForeground/10 dark:hover:bg-mutedForeground/10 transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSendInvites}
                  disabled={selectedMembers.length === 0 || isLoading}
                  className="flex-1 px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background flex items-center justify-center gap-2"
                  aria-label={`Send invites to ${selectedMembers.length} selected members`}
                >
                  {isLoading ? (
                    <>
                      <div className="w-4 h-4 border-2 border-primaryForeground dark:border-primaryForeground border-t-transparent rounded-full animate-spin"></div>
                      Sending...
                    </>
                  ) : (
                    `Send Invites (${selectedMembers.length})`
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

