'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, Paperclip, Smile, MoreVertical, MapPin, Calendar, Users } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'image' | 'location' | 'task'
  metadata?: {
    taskTitle?: string
    location?: string
    eventDate?: string
  }
}

interface GroupMember {
  id: string
  name: string
  avatar: string
  status: 'online' | 'offline' | 'away'
}

interface GroupChatProps {
  tripId?: string
  groupMembers?: GroupMember[]
  currentUserId?: string
  onSendMessage?: (message: string) => void
  onAttachFile?: () => void
  onShareLocation?: () => void
}

export function GroupChat({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  currentUserId = 'user-1',
  onSendMessage = () => console.log('Message sent'),
  onAttachFile = () => console.log('File attached'),
  onShareLocation = () => console.log('Location shared')
}: GroupChatProps = {}) {
  const [messages, setMessages] = useState<Message[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Message = {
      id: Date.now().toString(),
      userId: currentUserId,
      userName: 'You',
      userAvatar: '/api/placeholder/32/32',
      content: newMessage,
      timestamp: new Date(),
      type: 'text'
    }

    setMessages(prev => [...prev, message])
    setNewMessage('')
    onSendMessage(newMessage)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true 
    })
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return date.toLocaleDateString('en-US', { 
        month: 'short', 
        day: 'numeric' 
      })
    }
  }

  const renderMessage = (message: Message) => {
    const isCurrentUser = message.userId === currentUserId

    return (
      <div
        key={message.id}
        className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}
      >
        {!isCurrentUser && (
          <img
            src={message.userAvatar}
            alt={`${message.userName} avatar`}
            className="w-8 h-8 rounded-full flex-shrink-0 ring-2 ring-border dark:ring-border transition-all duration-200"
          />
        )}

        <div className={`flex flex-col max-w-[75%] ${isCurrentUser ? 'items-end' : 'items-start'}`}>
          {!isCurrentUser && (
            <span className="text-xs font-medium text-mutedForeground dark:text-mutedForeground mb-1">
              {message.userName}
            </span>
          )}

          <div
            className={`px-4 py-3 rounded-2xl transition-all duration-200 hover:scale-[1.02] ${
              isCurrentUser
                ? 'bg-primary text-primaryForeground dark:bg-primary dark:text-primaryForeground shadow-sm'
                : 'bg-muted text-foreground dark:bg-muted dark:text-foreground shadow-sm'
            }`}
          >
            {message.type === 'text' && (
              <p className="text-sm leading-relaxed font-sans">{message.content}</p>
            )}

            {message.type === 'task' && (
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Users className="w-4 h-4" />
                  <span className="text-sm font-medium">Task Assignment</span>
                </div>
                <p className="text-sm">{message.content}</p>
                <div className="text-xs opacity-75">
                  Task: {message.metadata?.taskTitle}
                </div>
              </div>
            )}

            {message.type === 'location' && (
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4" />
                  <span className="text-sm font-medium">Location Shared</span>
                </div>
                <p className="text-sm">{message.content}</p>
                <div className="text-xs opacity-75">
                  {message.metadata?.location}
                </div>
              </div>
            )}
          </div>

          <span className="text-xs text-mutedForeground dark:text-mutedForeground mt-1">
            {formatTime(message.timestamp)}
          </span>
        </div>
      </div>
    )
  }

  const groupMessagesByDate = (messages: Message[]) => {
    const groups: { [key: string]: Message[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return groups
  }

  const messageGroups = groupMessagesByDate(messages)

  if (isLoading) {
    return (
      <div className="flex flex-col h-screen bg-background dark:bg-background font-sans">
        <div className="flex items-center justify-between p-4 border-b border-border dark:border-border bg-surface dark:bg-surface">
          <div className="flex items-center gap-3">
            <div className="flex -space-x-2">
              {[1, 2, 3].map((i) => (
                <div key={i} className="w-8 h-8 bg-muted dark:bg-muted rounded-full animate-pulse" />
              ))}
            </div>
            <div className="space-y-2">
              <div className="h-4 bg-muted dark:bg-muted rounded w-24 animate-pulse" />
              <div className="h-3 bg-muted dark:bg-muted rounded w-16 animate-pulse" />
            </div>
          </div>
        </div>
        <div className="flex-1 p-4 space-y-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="flex gap-3 animate-pulse">
              <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full" />
              <div className="space-y-2">
                <div className="h-3 bg-muted dark:bg-muted rounded w-16" />
                <div className="h-12 bg-muted dark:bg-muted rounded-2xl w-48" />
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen bg-background dark:bg-background font-sans">
      <div className="flex items-center justify-between p-4 border-b border-border dark:border-border bg-surface dark:bg-surface shadow-sm">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            {groupMembers.slice(0, 3).map((member, index) => (
              <div key={member.id} className="relative">
                <img
                  src={member.avatar}
                  alt={`${member.name} avatar`}
                  className="w-8 h-8 rounded-full border-2 border-surface dark:border-surface ring-1 ring-border dark:ring-border transition-all duration-200 hover:scale-110"
                />
                {index === 0 && (
                  <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-surface dark:border-surface ${
                    member.status === 'online' ? 'bg-accent dark:bg-accent' :
                    member.status === 'away' ? 'bg-yellow-500' : 'bg-secondary dark:bg-secondary'
                  }`} />
                )}
              </div>
            ))}
          </div>
          <div>
            <h2 className="font-semibold text-foreground dark:text-foreground">Trip Chat</h2>
            <p className="text-sm text-mutedForeground dark:text-mutedForeground">
              {groupMembers.filter(m => m.status === 'online').length} online
            </p>
          </div>
        </div>

        <button
          className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
          aria-label="Chat options"
        >
          <MoreVertical className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {Object.keys(messageGroups).length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No messages yet</h3>
            <p className="text-mutedForeground dark:text-mutedForeground text-sm">Start the conversation with your travel group</p>
          </div>
        ) : (
          Object.entries(messageGroups).map(([dateKey, dayMessages]) => (
            <div key={dateKey}>
              <div className="flex justify-center mb-4">
                <span className="px-3 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground text-xs rounded-full font-medium">
                  {formatDate(new Date(dateKey))}
                </span>
              </div>

              <div className="space-y-4">
                {dayMessages.map(renderMessage)}
              </div>
            </div>
          ))
        )}

        {isTyping && (
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full animate-pulse" />
            <div className="bg-muted dark:bg-muted rounded-2xl px-4 py-3">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 border-t border-border dark:border-border bg-surface dark:bg-surface">
        <div className="flex items-end gap-3">
          <div className="flex gap-2">
            <button
              onClick={onAttachFile}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface active:scale-95"
              aria-label="Attach file"
            >
              <Paperclip className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>

            <button
              onClick={onShareLocation}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface active:scale-95"
              aria-label="Share location"
            >
              <MapPin className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>
          </div>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-muted dark:bg-muted rounded-2xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:bg-background dark:focus:bg-background transition-all duration-200 border border-transparent focus:border-ring dark:focus:border-ring font-sans"
            />

            <button
              className="absolute right-2 top-1/2 -translate-y-1/2 p-1 hover:bg-background dark:hover:bg-background rounded-full transition-all duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring active:scale-95"
              aria-label="Add emoji"
            >
              <Smile className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-full hover:scale-110 disabled:bg-muted dark:disabled:bg-muted disabled:text-mutedForeground dark:disabled:text-mutedForeground disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface active:scale-95 shadow-md hover:shadow-lg"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

