'use client'

import { useState, useEffect, useMemo } from 'react'
import { Search, MapPin, Star, Bookmark, BookmarkCheck, Filter, Mountain, Compass, Gauge, AlertCircle } from 'lucide-react'

interface Location {
  id: string
  name: string
  state: string
  coordinates: {
    lat: number
    lng: number
  }
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced' | 'Expert'
  terrain: string[]
  rating: number
  reviewCount: number
  distance: number
  description: string
  features: string[]
  isSaved: boolean
}

interface LocationSelectorProps {
  onLocationSelect?: (location: Location) => void
  onLocationSave?: (location: Location) => void
  savedLocations?: Location[]
  currentLocation?: { lat: number; lng: number }
}

const DIFFICULTY_COLORS = {
  'Beginner': 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/20 dark:text-accent dark:border-accent/30',
  'Intermediate': 'bg-yellow-500/10 text-yellow-600 border-yellow-500/20 dark:bg-yellow-500/20 dark:text-yellow-400 dark:border-yellow-500/30',
  'Advanced': 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/20 dark:text-primary dark:border-primary/30',
  'Expert': 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
}

const TERRAIN_ICONS = {
  'Rocky': '🪨',
  'Sandy': '🏖️',
  'Muddy': '🟫',
  'Forest': '🌲',
  'Desert': '🏜️',
  'Mountain': '⛰️'
}

export function LocationSelector({
  onLocationSelect = () => {},
  onLocationSave = () => {},
  savedLocations = [],
  currentLocation
}: LocationSelectorProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('')
  const [selectedTerrain, setSelectedTerrain] = useState<string>('')
  const [showFilters, setShowFilters] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string>('')
  const [locations, setLocations] = useState<Location[]>(MOCK_LOCATIONS)

  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery) {
        setIsLoading(true)
        setError('')
        setTimeout(() => {
          setIsLoading(false)
        }, 300)
      }
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery])

  const filteredLocations = useMemo(() => {
    return locations.filter(location => {
      const matchesSearch = location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                           location.state.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesDifficulty = !selectedDifficulty || location.difficulty === selectedDifficulty
      const matchesTerrain = !selectedTerrain || location.terrain.includes(selectedTerrain)

      return matchesSearch && matchesDifficulty && matchesTerrain
    })
  }, [searchQuery, selectedDifficulty, selectedTerrain, locations])

  const handleSaveLocation = (location: Location) => {
    const updatedLocation = { ...location, isSaved: !location.isSaved }
    setLocations(prev => prev.map(loc => 
      loc.id === location.id ? updatedLocation : loc
    ))
    onLocationSave(updatedLocation)
  }

  const clearFilters = () => {
    setSelectedDifficulty('')
    setSelectedTerrain('')
    setShowFilters(false)
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background transition-colors duration-200">
      <div className="max-w-4xl mx-auto px-4 py-6 font-sans">
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2">Find Your Adventure</h1>
          <p className="text-mutedForeground dark:text-mutedForeground">Discover amazing off-road locations for your next trip</p>
        </div>

        <div className="relative mb-4">
          <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-mutedForeground dark:text-mutedForeground w-5 h-5" />
          <input
            type="text"
            placeholder="Search locations, trails, or destinations..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-12 pr-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
            aria-label="Search locations"
          />
        </div>

        {error && (
          <div className="rounded-lg bg-destructive/10 dark:bg-destructive/20 border border-destructive/20 dark:border-destructive/30 p-4 mb-4">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
              <p className="text-sm text-destructive dark:text-destructive">{error}</p>
            </div>
          </div>
        )}

        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="flex items-center gap-2 px-4 py-2 bg-surface dark:bg-surface text-foreground dark:text-foreground rounded-lg border border-border dark:border-border hover:border-ring/50 dark:hover:border-ring/50 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
            aria-expanded={showFilters}
            aria-controls="filter-panel"
            aria-label="Toggle filters"
          >
            <Filter className="w-4 h-4" />
            Filters
            {(selectedDifficulty || selectedTerrain) && (
              <span className="w-2 h-2 bg-primary dark:bg-primary rounded-full"></span>
            )}
          </button>

          {(selectedDifficulty || selectedTerrain) && (
            <button
              onClick={clearFilters}
              className="text-primary dark:text-primary hover:text-primary/80 dark:hover:text-primary/80 text-sm transition-colors duration-150 focus:outline-none focus:underline"
            >
              Clear all
            </button>
          )}
        </div>

        {showFilters && (
          <div id="filter-panel" className="bg-surface dark:bg-surface rounded-lg border border-border dark:border-border p-4 mb-6 shadow-sm dark:shadow-lg">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-foreground dark:text-foreground font-medium mb-2">Difficulty Level</label>
                <select
                  value={selectedDifficulty}
                  onChange={(e) => setSelectedDifficulty(e.target.value)}
                  className="w-full px-3 py-2 bg-muted dark:bg-muted border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  aria-label="Select difficulty level"
                >
                  <option value="">All Difficulties</option>
                  <option value="Beginner">Beginner</option>
                  <option value="Intermediate">Intermediate</option>
                  <option value="Advanced">Advanced</option>
                  <option value="Expert">Expert</option>
                </select>
              </div>

              <div>
                <label className="block text-foreground dark:text-foreground font-medium mb-2">Terrain Type</label>
                <select
                  value={selectedTerrain}
                  onChange={(e) => setSelectedTerrain(e.target.value)}
                  className="w-full px-3 py-2 bg-muted dark:bg-muted border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  aria-label="Select terrain type"
                >
                  <option value="">All Terrain</option>
                  <option value="Rocky">Rocky</option>
                  <option value="Sandy">Sandy</option>
                  <option value="Muddy">Muddy</option>
                  <option value="Forest">Forest</option>
                  <option value="Desert">Desert</option>
                  <option value="Mountain">Mountain</option>
                </select>
              </div>
            </div>
          </div>
        )}

        {isLoading && (
          <div className="space-y-4 mb-6">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-surface dark:bg-surface rounded-lg p-6 animate-pulse border border-border dark:border-border">
                <div className="flex justify-between items-start mb-4">
                  <div className="space-y-2">
                    <div className="h-5 bg-muted dark:bg-muted rounded w-48"></div>
                    <div className="h-4 bg-muted dark:bg-muted rounded w-32"></div>
                  </div>
                  <div className="h-8 w-8 bg-muted dark:bg-muted rounded"></div>
                </div>
                <div className="space-y-2">
                  <div className="h-4 bg-muted dark:bg-muted rounded w-full"></div>
                  <div className="h-4 bg-muted dark:bg-muted rounded w-3/4"></div>
                </div>
              </div>
            ))}
          </div>
        )}

        {!isLoading && (
          <div className="space-y-4">
            {filteredLocations.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <Mountain className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                </div>
                <h3 className="text-xl font-bold text-foreground dark:text-foreground mb-2">No locations found</h3>
                <p className="text-mutedForeground dark:text-mutedForeground mb-4">Try adjusting your search or filters</p>
                <button
                  onClick={clearFilters}
                  className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:bg-primary/90 dark:hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                >
                  Clear Filters
                </button>
              </div>
            ) : (
              filteredLocations.map((location) => (
                <LocationCard
                  key={location.id}
                  location={location}
                  onSelect={() => onLocationSelect(location)}
                  onSave={() => handleSaveLocation(location)}
                />
              ))
            )}
          </div>
        )}
      </div>
    </div>
  )
}

