'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar, MessageSquare, AlertCircle } from 'lucide-react'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
}

interface TripDetails {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  description: string
}

interface RSVPResponse {
  memberId: string
  status: 'pending' | 'accepted' | 'declined'
  respondedAt?: string
  notes?: string
}

interface RSVPComponentProps {
  tripDetails?: TripDetails
  groupMembers?: GroupMember[]
  currentUserId?: string
  onRSVPUpdate?: (memberId: string, status: 'accepted' | 'declined', notes?: string) => void
  onSendReminder?: (memberIds: string[]) => void
}

const DEFAULT_TRIP: TripDetails = {
