}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Johnson', email: 'alex@example.com' },
  { id: '2', name: 'Sarah Chen', email: 'sarah@example.com' },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com' },
  { id: '4', name: 'Emma Davis', email: 'emma@example.com' },
  { id: '5', name: 'Chris Wilson', email: 'chris@example.com' }
]

export function RSVPComponent({
  tripDetails = DEFAULT_TRIP,
  groupMembers = DEFAULT_MEMBERS,
  currentUserId = '1',
  onRSVPUpdate = (memberId, status, notes) => console.log('RSVP updated:', { memberId, status, notes }),
  onSendReminder = (memberIds) => console.log('Sending reminders to:', memberIds)
}: RSVPComponentProps = {}) {
  const [rsvpResponses, setRsvpResponses] = useState<Record<string, RSVPResponse>>({})
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [showNoteModal, setShowNoteModal] = useState(false)
  const [currentMemberNote, setCurrentMemberNote] = useState('')
  const [noteModalMemberId, setNoteModalMemberId] = useState<string | null>(null)
  const [filter, setFilter] = useState<'all' | 'pending' | 'accepted' | 'declined'>('all')
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const timer = setTimeout(() => {
      const initialResponses: Record<string, RSVPResponse> = {}
      groupMembers.forEach(member => {
        initialResponses[member.id] = {
          memberId: member.id,
          status: Math.random() > 0.7 ? (Math.random() > 0.5 ? 'accepted' : 'declined') : 'pending',
          respondedAt: Math.random() > 0.7 ? new Date().toISOString() : undefined
        }
      })
      setRsvpResponses(initialResponses)
      setIsLoading(false)
    }, 1000)

    return () => clearTimeout(timer)
  }, [groupMembers])

  const handleRSVPResponse = (memberId: string, status: 'accepted' | 'declined') => {
    if (memberId !== currentUserId) return

    setRsvpResponses(prev => ({
      ...prev,
      [memberId]: {
        ...prev[memberId],
        status,
        respondedAt: new Date().toISOString()
      }
    }))
    onRSVPUpdate(memberId, status)
  }

  const handleAddNote = (memberId: string) => {
    setNoteModalMemberId(memberId)
    setCurrentMemberNote(rsvpResponses[memberId]?.notes || '')
    setShowNoteModal(true)
  }

  const saveNote = () => {
    if (!noteModalMemberId) return

    setRsvpResponses(prev => ({
      ...prev,
      [noteModalMemberId]: {
        ...prev[noteModalMemberId],
        notes: currentMemberNote
      }
    }))
    setShowNoteModal(false)
    setNoteModalMemberId(null)
    setCurrentMemberNote('')
  }

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  const sendReminders = () => {
    const pendingMembers = selectedMembers.length > 0 
      ? selectedMembers 
      : groupMembers
          .filter(member => rsvpResponses[member.id]?.status === 'pending')
          .map(member => member.id)

    onSendReminder(pendingMembers)
    setSelectedMembers([])
  }

  const filteredMembers = groupMembers.filter(member => {
    const response = rsvpResponses[member.id]
    if (filter === 'all') return true
    return response?.status === filter
  })

  const stats = {
    total: groupMembers.length,
    accepted: Object.values(rsvpResponses).filter(r => r.status === 'accepted').length,
    declined: Object.values(rsvpResponses).filter(r => r.status === 'declined').length,
    pending: Object.values(rsvpResponses).filter(r => r.status === 'pending').length
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'accepted': return 'bg-accent/20 text-accent border-accent/30 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      case 'declined': return 'bg-destructive/20 text-destructive border-destructive/30 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      default: return 'bg-primary/20 text-primary border-primary/30 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted': return <Check className="w-4 h-4" />
      case 'declined': return <X className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  const LoadingSkeleton = () => (
    <div className="space-y-3 animate-pulse">
      {[...Array(5)].map((_, i) => (
        <div key={i} className="bg-surface dark:bg-surface rounded-lg border border-border dark:border-border p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-5 h-5 bg-muted dark:bg-muted rounded"></div>
              <div className="w-10 h-10 bg-muted dark:bg-muted rounded-full"></div>
              <div className="space-y-2">
                <div className="h-4 bg-muted dark:bg-muted rounded w-32"></div>
                <div className="h-3 bg-muted dark:bg-muted rounded w-48"></div>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="h-6 bg-muted dark:bg-muted rounded w-20"></div>
              <div className="h-6 bg-muted dark:bg-muted rounded w-16"></div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
