        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
          <div className="bg-surface dark:bg-surface rounded-lg border border-border dark:border-border p-4 text-center hover:shadow-md transition-all duration-200">
            <div className="text-2xl font-bold text-foreground dark:text-foreground">{stats.total}</div>
            <div className="text-mutedForeground dark:text-mutedForeground text-sm">Total Invited</div>
