          <div className="bg-surface dark:bg-surface rounded-lg border border-accent/30 dark:border-accent/30 p-4 text-center hover:shadow-md transition-all duration-200">
            <div className="text-2xl font-bold text-accent dark:text-accent">{stats.accepted}</div>
            <div className="text-mutedForeground dark:text-mutedForeground text-sm">Accepted</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-lg border border-destructive/30 dark:border-destructive/30 p-4 text-center hover:shadow-md transition-all duration-200">
            <div className="text-2xl font-bold text-destructive dark:text-destructive">{stats.declined}</div>
            <div className="text-mutedForeground dark:text-mutedForeground text-sm">Declined</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-lg border border-primary/30 dark:border-primary/30 p-4 text-center hover:shadow-md transition-all duration-200">
            <div className="text-2xl font-bold text-primary dark:text-primary">{stats.pending}</div>
            <div className="text-mutedForeground dark:text-mutedForeground text-sm">Pending</div>
          </div>
        </div>

        {rsvpResponses[currentUserId]?.status === 'pending' && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-primary/50 dark:border-primary/50 p-6 mb-6 shadow-lg hover:shadow-xl transition-all duration-300">
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Your Response Required</h3>
            <div className="flex gap-3">
              <button
                onClick={() => handleRSVPResponse(currentUserId, 'accepted')}
