                aria-label={`Clear ${selectedMembers.length} selected members`}
              >
                Clear ({selectedMembers.length})
              </button>
            )}
            <button
              onClick={sendReminders}
              className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 text-sm font-medium shadow-md hover:shadow-lg flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-primary/50 dark:focus:ring-primary/50"
              aria-label="Send reminders to selected members"
            >
              <MessageSquare className="w-4 h-4" />
              Send Reminders
            </button>
          </div>
        </div>

        {isLoading ? (
          <LoadingSkeleton />
        ) : filteredMembers.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <AlertCircle className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No members found</h3>
            <p className="text-mutedForeground dark:text-mutedForeground text-sm">Try adjusting your filter to see more results</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filteredMembers.map(member => {
              const response = rsvpResponses[member.id]
              const isSelected = selectedMembers.includes(member.id)
              const isCurrentUser = member.id === currentUserId

              return (
                <div
                  key={member.id}
                  className={`bg-surface dark:bg-surface rounded-lg border p-4 transition-all duration-200 shadow-sm hover:shadow-md hover:-translate-y-0.5 ${
                    isSelected 
                      ? 'border-accent/50 dark:border-accent/50 bg-accent/5 dark:bg-accent/5' 
                      : 'border-border dark:border-border hover:border-ring/30 dark:hover:border-ring/30'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <button
                        onClick={() => toggleMemberSelection(member.id)}
                        className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all duration-150 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 ${
                          isSelected
                            ? 'bg-accent dark:bg-accent border-accent dark:border-accent'
                            : 'border-border dark:border-border hover:border-ring dark:hover:border-ring'
                        }`}
                        aria-label={`${isSelected ? 'Deselect' : 'Select'} ${member.name}`}
                      >
                        {isSelected && <Check className="w-3 h-3 text-accentForeground dark:text-accentForeground" />}
                      </button>

                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-br from-accent to-accent/80 dark:from-accent dark:to-accent/80 rounded-full flex items-center justify-center text-accentForeground dark:text-accentForeground font-semibold">
                          {member.name.split(' ').map(n => n[0]).join('')}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="text-foreground dark:text-foreground font-medium">
                              {member.name}
                              {isCurrentUser && <span className="text-accent dark:text-accent text-sm">(You)</span>}
                            </span>
                          </div>
                          <div className="text-mutedForeground dark:text-mutedForeground text-sm">{member.email}</div>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-3">
                      <div className={`px-3 py-1 rounded-full text-xs font-medium border flex items-center gap-2 ${getStatusColor(response?.status || 'pending')}`}>
                        {getStatusIcon(response?.status || 'pending')}
                        <span className="capitalize">{response?.status || 'pending'}</span>
                      </div>

                      <button
                        onClick={() => handleAddNote(member.id)}
                        className="px-3 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-lg hover:bg-secondary dark:hover:bg-secondary hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 text-xs font-medium focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                        aria-label={`${response?.notes ? 'Edit' : 'Add'} note for ${member.name}`}
                      >
                        {response?.notes ? 'Edit Note' : 'Add Note'}
                      </button>
                    </div>
                  </div>

                  {response?.notes && (
                    <div className="mt-3 p-3 bg-muted/50 dark:bg-muted/50 rounded-lg">
                      <div className="text-mutedForeground dark:text-mutedForeground text-sm">{response.notes}</div>
                    </div>
                  )}

                  {response?.respondedAt && (
                    <div className="mt-2 text-mutedForeground/70 dark:text-mutedForeground/70 text-xs">
                      Responded {new Date(response.respondedAt).toLocaleDateString()}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}

        {showNoteModal && (
          <div className="fixed inset-0 bg-background/80 dark:bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 w-full max-w-md shadow-xl">
              <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Add Note</h3>
              <textarea
                value={currentMemberNote}
                onChange={(e) => setCurrentMemberNote(e.target.value)}
                placeholder="Add a note about dietary restrictions, special requests, etc..."
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-150 resize-none"
                rows={4}
                aria-label="Note content"
              />
              <div className="flex gap-3 mt-4">
                <button
                  onClick={() => setShowNoteModal(false)}
                  className="flex-1 px-4 py-2 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-lg hover:bg-secondary dark:hover:bg-secondary hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                  aria-label="Cancel note editing"
                >
                  Cancel
                </button>
                <button
                  onClick={saveNote}
                  className="flex-1 px-4 py-2 bg-accent dark:bg-accent text-accentForeground dark:text-accentForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-accent/50 dark:focus:ring-accent/50"
                  aria-label="Save note"
                >
                  Save Note
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

