'use client'

import { useState, useEffect } from 'react'
import { Users, UserPlus, Crown, Calendar, MessageCircle, CheckCircle, X, Mail, Phone, MapPin, Clock } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  phone?: string
  avatar?: string
  role: 'organizer' | 'member'
  status: 'confirmed' | 'pending' | 'declined'
  joinedAt: Date
  lastActive?: Date
  skills?: string[]
  emergencyContact?: {
    name: string
    phone: string
    relationship: string
  }
}

interface TripMembersPanelProps {
  tripId?: string
  members?: TripMember[]
  onInviteMember?: (email: string) => void
  onRemoveMember?: (memberId: string) => void
  onUpdateMemberRole?: (memberId: string, role: 'organizer' | 'member') => void
  maxMembers?: number
  isOrganizer?: boolean
  isLoading?: boolean
}

export function TripMembersPanel({
  tripId = 'trip-1',
  members = DEFAULT_MEMBERS,
  onInviteMember = (email: string) => console.log('Invite member:', email),
  onRemoveMember = (memberId: string) => console.log('Remove member:', memberId),
  onUpdateMemberRole = (memberId: string, role: string) => console.log('Update role:', memberId, role),
  maxMembers = 12,
  isOrganizer = true,
  isLoading = false
}: TripMembersPanelProps = {}) {
  const [showInviteForm, setShowInviteForm] = useState(false)
  const [inviteEmail, setInviteEmail] = useState('')
  const [selectedMember, setSelectedMember] = useState<TripMember | null>(null)
  const [filter, setFilter] = useState<'all' | 'confirmed' | 'pending' | 'declined'>('all')
  const [error, setError] = useState<string | null>(null)

  const filteredMembers = members.filter(member => {
    if (filter === 'all') return true
    return member.status === filter
  })

  const confirmedCount = members.filter(m => m.status === 'confirmed').length
  const pendingCount = members.filter(m => m.status === 'pending').length

  const handleInvite = async () => {
    if (inviteEmail.trim()) {
      try {
        setError(null)
        await onInviteMember(inviteEmail.trim())
        setInviteEmail('')
        setShowInviteForm(false)
      } catch (err) {
        setError('Failed to send invitation. Please try again.')
      }
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-accent/20 text-accent border-accent/30 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      case 'pending': return 'bg-primary/20 text-primary border-primary/30 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'declined': return 'bg-destructive/20 text-destructive border-destructive/30 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      default: return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'confirmed': return <CheckCircle className="w-3 h-3" />
      case 'pending': return <Clock className="w-3 h-3" />
      case 'declined': return <X className="w-3 h-3" />
      default: return null
    }
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-background font-sans">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-md">
            <div className="space-y-4 animate-pulse">
              <div className="h-6 bg-muted dark:bg-muted rounded w-1/3"></div>
              <div className="h-4 bg-muted dark:bg-muted rounded w-1/2"></div>
              <div className="h-2 bg-muted dark:bg-muted rounded w-full"></div>
              <div className="flex gap-2">
                <div className="h-8 bg-muted dark:bg-muted rounded w-20"></div>
                <div className="h-8 bg-muted dark:bg-muted rounded w-24"></div>
                <div className="h-8 bg-muted dark:bg-muted rounded w-20"></div>
              </div>
            </div>
          </div>
          <div className="space-y-3">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4 animate-pulse">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-muted dark:bg-muted rounded-full"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-muted dark:bg-muted rounded w-1/4"></div>
                    <div className="h-3 bg-muted dark:bg-muted rounded w-1/3"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {error && (
          <div className="rounded-lg bg-destructive/10 dark:bg-destructive/10 border border-destructive/20 dark:border-destructive/20 p-4 mb-6">
            <p className="text-sm text-destructive dark:text-destructive">{error}</p>
          </div>
        )}

        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-md hover:shadow-lg transition-all duration-300">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-accent/20 dark:bg-accent/20 rounded-lg">
                <Users className="w-6 h-6 text-accent dark:text-accent" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-foreground dark:text-foreground">Trip Members</h1>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">
                  {confirmedCount} confirmed • {pendingCount} pending • {maxMembers - members.length} spots left
                </p>
              </div>
            </div>
            {isOrganizer && members.length < maxMembers && (
              <button
                onClick={() => setShowInviteForm(true)}
                className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background flex items-center gap-2"
                aria-label="Invite new member"
              >
                <UserPlus className="w-4 h-4" />
                <span className="hidden sm:inline">Invite</span>
              </button>
            )}
          </div>

          <div className="w-full bg-muted dark:bg-muted rounded-full h-2 mb-4">
            <div 
              className="bg-accent dark:bg-accent h-2 rounded-full transition-all duration-300"
              style={{ width: `${(members.length / maxMembers) * 100}%` }}
            />
          </div>

          <div className="flex gap-2 overflow-x-auto">
            {[
              { key: 'all', label: 'All', count: members.length },
              { key: 'confirmed', label: 'Confirmed', count: confirmedCount },
              { key: 'pending', label: 'Pending', count: pendingCount }
            ].map(tab => (
              <button
                key={tab.key}
                onClick={() => setFilter(tab.key as any)}
                className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                  filter === tab.key
                    ? 'bg-accent/20 dark:bg-accent/20 text-accent dark:text-accent border border-accent/30 dark:border-accent/30'
                    : 'text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground hover:bg-muted/50 dark:hover:bg-muted/50'
                }`}
                aria-label={`Filter by ${tab.label}`}
              >
                {tab.label} ({tab.count})
              </button>
            ))}
          </div>
        </div>

        {showInviteForm && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-md hover:shadow-lg transition-all duration-300">
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Invite New Member</h3>
            <div className="flex gap-3">
              <input
                type="email"
                value={inviteEmail}
                onChange={(e) => setInviteEmail(e.target.value)}
                placeholder="Enter email address"
                className="flex-1 px-4 py-2.5 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                onKeyDown={(e) => e.key === 'Enter' && handleInvite()}
                aria-label="Email address to invite"
              />
              <button
                onClick={handleInvite}
                disabled={!inviteEmail.trim()}
                className="px-6 py-2.5 bg-accent dark:bg-accent text-accentForeground dark:text-accentForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted dark:disabled:bg-muted disabled:text-mutedForeground dark:disabled:text-mutedForeground disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                aria-label="Send invitation"
              >
                Send
              </button>
              <button
                onClick={() => setShowInviteForm(false)}
                className="px-4 py-2.5 bg-secondary dark:bg-secondary text-secondaryForeground dark:text-secondaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
