        <div className="space-y-3">
          {filteredMembers.length === 0 ? (
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-8 text-center shadow-md">
              <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
