                key={member.id}
                className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4 hover:border-accent/50 dark:hover:border-accent/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4 flex-1 min-w-0">
                    <div className="relative">
                      {member.avatar ? (
                        <img
                          src={member.avatar}
                          alt={member.name}
                          className="w-12 h-12 rounded-full object-cover border-2 border-border dark:border-border"
                        />
                      ) : (
                        <div className="w-12 h-12 bg-gradient-to-br from-accent to-accent/80 dark:from-accent dark:to-accent/80 rounded-full flex items-center justify-center text-accentForeground dark:text-accentForeground font-semibold text-lg">
                          {member.name.charAt(0).toUpperCase()}
                        </div>
                      )}
                      {member.role === 'organizer' && (
                        <div className="absolute -top-1 -right-1 p-1 bg-primary dark:bg-primary rounded-full">
                          <Crown className="w-3 h-3 text-primaryForeground dark:text-primaryForeground" />
                        </div>
                      )}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-semibold text-foreground dark:text-foreground truncate">{member.name}</h3>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border flex items-center gap-1 ${getStatusColor(member.status)}`}>
