                      </div>
                      {member.skills && member.skills.length > 0 && (
                        <div className="flex gap-1 mt-2 flex-wrap">
                          {member.skills.slice(0, 3).map((skill, index) => (
                            <span
                              key={index}
                              className="px-2 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded text-xs"
                            >
                              {skill}
                            </span>
                          ))}
                          {member.skills.length > 3 && (
                            <span className="px-2 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded text-xs">
                              +{member.skills.length - 3} more
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2 ml-4">
                    <button
                      onClick={() => setSelectedMember(member)}
                      className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-accent dark:hover:text-accent hover:bg-muted/50 dark:hover:bg-muted/50 rounded-lg transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                      aria-label={`View ${member.name} details`}
                    >
                      <MessageCircle className="w-4 h-4" />
                    </button>
                    {isOrganizer && member.role !== 'organizer' && (
                      <button
                        onClick={() => onRemoveMember(member.id)}
                        className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive hover:bg-muted/50 dark:hover:bg-muted/50 rounded-lg transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                        aria-label={`Remove ${member.name}`}
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {selectedMember && (
          <div className="fixed inset-0 bg-background/60 dark:bg-background/60 backdrop-blur-sm flex items-center justify-center p-4 z-50">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 max-w-md w-full shadow-xl">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-foreground dark:text-foreground">Member Details</h3>
                <button
                  onClick={() => setSelectedMember(null)}
                  className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground hover:bg-muted/50 dark:hover:bg-muted/50 rounded-lg transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                  aria-label="Close member details"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="space-y-4">
                <div className="flex items-center gap-4">
                  {selectedMember.avatar ? (
                    <img
                      src={selectedMember.avatar}
                      alt={selectedMember.name}
                      className="w-16 h-16 rounded-full object-cover border-2 border-border dark:border-border"
                    />
                  ) : (
                    <div className="w-16 h-16 bg-gradient-to-br from-accent to-accent/80 dark:from-accent dark:to-accent/80 rounded-full flex items-center justify-center text-accentForeground dark:text-accentForeground font-semibold text-xl">
                      {selectedMember.name.charAt(0).toUpperCase()}
                    </div>
                  )}
                  <div>
                    <h4 className="font-semibold text-foreground dark:text-foreground">{selectedMember.name}</h4>
                    <p className="text-mutedForeground dark:text-mutedForeground text-sm capitalize">{selectedMember.role}</p>
                  </div>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm">
                    <Mail className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
                    <span className="text-foreground dark:text-foreground">{selectedMember.email}</span>
                  </div>
                  {selectedMember.phone && (
                    <div className="flex items-center gap-2 text-sm">
                      <Phone className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
                      <span className="text-foreground dark:text-foreground">{selectedMember.phone}</span>
                    </div>
                  )}
                  <div className="flex items-center gap-2 text-sm">
                    <Calendar className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
                    <span className="text-foreground dark:text-foreground">
                      Joined {selectedMember.joinedAt.toLocaleDateString()}
                    </span>
                  </div>
                </div>

                {selectedMember.emergencyContact && (
                  <div className="border-t border-border dark:border-border pt-4">
                    <h5 className="font-medium text-foreground dark:text-foreground mb-2">Emergency Contact</h5>
                    <div className="space-y-1 text-sm text-foreground dark:text-foreground">
                      <p>{selectedMember.emergencyContact.name}</p>
                      <p>{selectedMember.emergencyContact.phone}</p>
                      <p className="text-mutedForeground dark:text-mutedForeground">{selectedMember.emergencyContact.relationship}</p>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

