'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, MapPin, Plus, X, Check, AlertCircle } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  date: string
  time: string
  location?: string
  attendees: string[]
  type: 'trip' | 'meeting' | 'task'
  status: 'pending' | 'confirmed' | 'cancelled'
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  availability: Record<string, boolean>
}

interface CalendarSchedulerProps {
  events?: CalendarEvent[]
  groupMembers?: GroupMember[]
  onEventCreate?: (event: Omit<CalendarEvent, 'id'>) => void
  onEventUpdate?: (id: string, event: Partial<CalendarEvent>) => void
  onEventDelete?: (id: string) => void
  onInviteSend?: (eventId: string, memberIds: string[]) => void
}

export function CalendarScheduler({
  events = DEFAULT_EVENTS,
  groupMembers = DEFAULT_GROUP_MEMBERS,
  onEventCreate = (event) => console.log('Create event:', event),
  onEventUpdate = (id, event) => console.log('Update event:', id, event),
  onEventDelete = (id) => console.log('Delete event:', id),
  onInviteSend = (eventId, memberIds) => console.log('Send invites:', eventId, memberIds)
}: CalendarSchedulerProps = {}) {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [selectedDate, setSelectedDate] = useState<string | null>(null)
  const [showEventForm, setShowEventForm] = useState(false)
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null)
  const [eventForm, setEventForm] = useState({
    title: '',
    date: '',
    time: '',
    location: '',
    type: 'trip' as const,
    attendees: [] as string[]
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear()
    const month = date.getMonth()
    const firstDay = new Date(year, month, 1)
    const lastDay = new Date(year, month + 1, 0)
    const daysInMonth = lastDay.getDate()
    const startingDayOfWeek = firstDay.getDay()

    const days = []

    for (let i = 0; i < startingDayOfWeek; i++) {
      days.push(null)
    }

    for (let day = 1; day <= daysInMonth; day++) {
      days.push(day)
    }

    return days
  }

  const getEventsForDate = (date: string) => {
    return events.filter(event => event.date === date)
  }

  const formatDate = (year: number, month: number, day: number) => {
    return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
  }

  const handleDateClick = (day: number) => {
    const dateStr = formatDate(currentDate.getFullYear(), currentDate.getMonth(), day)
    setSelectedDate(dateStr)
    setEventForm(prev => ({ ...prev, date: dateStr }))
  }

  const handleEventSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError(null)

    try {
      const newEvent = {
        ...eventForm,
        status: 'pending' as const
      }

      if (selectedEvent) {
        onEventUpdate(selectedEvent.id, newEvent)
      } else {
        onEventCreate(newEvent)
      }

      if (eventForm.attendees.length > 0) {
        const eventId = selectedEvent?.id || 'new-event'
        onInviteSend(eventId, eventForm.attendees)
      }

      setShowEventForm(false)
      setSelectedEvent(null)
      setEventForm({
        title: '',
        date: '',
        time: '',
        location: '',
        type: 'trip',
        attendees: []
      })
    } catch (error) {
      setError('Failed to save event. Please try again.')
      console.error('Error saving event:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleEventEdit = (event: CalendarEvent) => {
    setSelectedEvent(event)
    setEventForm({
      title: event.title,
      date: event.date,
      time: event.time,
      location: event.location || '',
      type: event.type,
      attendees: event.attendees
    })
    setShowEventForm(true)
  }

  const toggleAttendee = (memberId: string) => {
    setEventForm(prev => ({
      ...prev,
      attendees: prev.attendees.includes(memberId)
        ? prev.attendees.filter(id => id !== memberId)
        : [...prev.attendees, memberId]
    }))
  }

  const checkMemberAvailability = (memberId: string, date: string) => {
    const member = groupMembers.find(m => m.id === memberId)
    return member?.availability[date] !== false
  }

  const days = getDaysInMonth(currentDate)
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ]
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6">
        <div className="bg-surface dark:bg-surface rounded-xl shadow-md hover:shadow-lg transition-all duration-300 p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <Calendar className="w-6 h-6 text-primary dark:text-primary" />
              <h1 className="text-2xl font-bold text-foreground dark:text-foreground">Trip Scheduler</h1>
            </div>
            <button
              onClick={() => setShowEventForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 shadow-md hover:shadow-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
              aria-label="Create new event"
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">New Event</span>
            </button>
          </div>

          <div className="flex items-center justify-between mb-4">
            <button
              onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1))}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
              aria-label="Previous month"
            >
              ←
            </button>
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground">
              {monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}
            </h2>
            <button
              onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1))}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
              aria-label="Next month"
            >
              →
            </button>
          </div>

          <div className="grid grid-cols-7 gap-1 mb-4">
            {dayNames.map(day => (
              <div key={day} className="p-2 text-center text-sm font-medium text-mutedForeground dark:text-mutedForeground">
                {day}
              </div>
            ))}
            {days.map((day, index) => {
              if (!day) return <div key={index} className="p-2" />

              const dateStr = formatDate(currentDate.getFullYear(), currentDate.getMonth(), day)
              const dayEvents = getEventsForDate(dateStr)
              const isSelected = selectedDate === dateStr
              const isToday = new Date().toDateString() === new Date(currentDate.getFullYear(), currentDate.getMonth(), day).toDateString()

              return (
                <button
                  key={day}
                  onClick={() => handleDateClick(day)}
                  className={`
                    p-2 min-h-[44px] rounded-lg transition-all duration-150 relative hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none
                    ${isSelected ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground' : 'hover:bg-muted dark:hover:bg-muted'}
                    ${isToday ? 'ring-2 ring-accent dark:ring-accent' : ''}
                    ${dayEvents.length > 0 ? 'font-semibold' : ''}
                  `}
                  aria-label={`Select ${day} ${monthNames[currentDate.getMonth()]}`}
                >
                  <span className="text-sm">{day}</span>
                  {dayEvents.length > 0 && (
                    <div className="absolute bottom-1 left-1/2 transform -translate-x-1/2">
                      <div className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-primaryForeground dark:bg-primaryForeground' : 'bg-primary dark:bg-primary'}`} />
                    </div>
                  )}
                </button>
              )
            })}
          </div>
        </div>

        {selectedDate && (
          <div className="bg-surface dark:bg-surface rounded-xl shadow-md hover:shadow-lg transition-all duration-300 p-6 mb-6">
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">
              Events for {new Date(selectedDate).toLocaleDateString()}
            </h3>
            <div className="space-y-3">
              {getEventsForDate(selectedDate).map(event => (
                <div
                  key={event.id}
                  className="flex items-center justify-between p-4 bg-muted dark:bg-muted rounded-lg hover:bg-border dark:hover:bg-border hover:-translate-y-1 hover:shadow-lg transition-all duration-300"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="font-medium text-foreground dark:text-foreground">{event.title}</h4>
                      <span className={`
                        px-2 py-1 text-xs rounded-full font-medium
                        ${event.type === 'trip' ? 'bg-accent dark:bg-accent text-accentForeground dark:text-accentForeground' : ''}
                        ${event.type === 'meeting' ? 'bg-secondary dark:bg-secondary text-secondaryForeground dark:text-secondaryForeground' : ''}
                        ${event.type === 'task' ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground' : ''}
                      `}>
                        {event.type}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-sm text-mutedForeground dark:text-mutedForeground">
                      <div className="flex items-center gap-1">
                        <Clock className="w-4 h-4" />
                        {event.time}
                      </div>
                      {event.location && (
                        <div className="flex items-center gap-1">
                          <MapPin className="w-4 h-4" />
                          {event.location}
                        </div>
                      )}
                      <div className="flex items-center gap-1">
                        <Users className="w-4 h-4" />
                        {event.attendees.length}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handleEventEdit(event)}
                      className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-primary dark:hover:text-primary hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
                      aria-label="Edit event"
                    >
                      ✏️
                    </button>
                    <button
                      onClick={() => onEventDelete(event.id)}
                      className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
                      aria-label="Delete event"
                    >
                      🗑️
                    </button>
                  </div>
                </div>
              ))}
              {getEventsForDate(selectedDate).length === 0 && (
                <div className="text-center py-12">
                  <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                    <Calendar className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                  </div>
                  <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No events scheduled</h3>
                  <p className="text-mutedForeground dark:text-mutedForeground text-sm mb-4">Get started by creating your first event for this date</p>
                  <button
                    onClick={() => setShowEventForm(true)}
                    className="text-primary dark:text-primary hover:text-primary/80 dark:hover:text-primary/80 font-medium transition-colors duration-150 hover:underline focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none rounded px-2 py-1"
                  >
                    Create your first event
                  </button>
                </div>
              )}
            </div>
          </div>
        )}

        {showEventForm && (
          <div className="fixed inset-0 bg-black/60 dark:bg-black/80 flex items-center justify-center p-4 z-50 backdrop-blur-sm">
            <div className="bg-surface dark:bg-surface rounded-xl shadow-xl max-w-md w-full max-h-[90vh] overflow-y-auto animate-in fade-in-0 zoom-in-95 duration-200">
              <div className="p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-foreground dark:text-foreground">
                    {selectedEvent ? 'Edit Event' : 'Create Event'}
                  </h3>
                  <button
                    onClick={() => {
                      setShowEventForm(false)
                      setSelectedEvent(null)
                      setError(null)
                    }}
                    className="p-2 hover:bg-muted dark:hover:bg-muted rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
                    aria-label="Close form"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>

                {error && (
                  <div className="rounded-lg bg-destructive/10 dark:bg-destructive/20 border border-destructive/20 dark:border-destructive/30 p-4 mb-4">
                    <p className="text-sm text-destructive dark:text-destructive">{error}</p>
                  </div>
