                <form onSubmit={handleEventSubmit} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                      Event Title
                    </label>
                    <input
                      type="text"
                      value={eventForm.title}
                      onChange={(e) => setEventForm(prev => ({ ...prev, title: e.target.value }))}
                      className="w-full px-3 py-2 border border-border dark:border-border bg-background dark:bg-background text-foreground dark:text-foreground rounded-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:border-ring dark:focus:border-ring transition-all duration-200 focus:outline-none"
                      placeholder="Enter event title"
                      required
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                        Date
                      </label>
                      <input
                        type="date"
                        value={eventForm.date}
                        onChange={(e) => setEventForm(prev => ({ ...prev, date: e.target.value }))}
                        className="w-full px-3 py-2 border border-border dark:border-border bg-background dark:bg-background text-foreground dark:text-foreground rounded-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:border-ring dark:focus:border-ring transition-all duration-200 focus:outline-none"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                        Time
                      </label>
                      <input
                        type="time"
                        value={eventForm.time}
                        onChange={(e) => setEventForm(prev => ({ ...prev, time: e.target.value }))}
                        className="w-full px-3 py-2 border border-border dark:border-border bg-background dark:bg-background text-foreground dark:text-foreground rounded-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:border-ring dark:focus:border-ring transition-all duration-200 focus:outline-none"
                        required
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                      Location (Optional)
                    </label>
                    <input
                      type="text"
                      value={eventForm.location}
                      onChange={(e) => setEventForm(prev => ({ ...prev, location: e.target.value }))}
                      className="w-full px-3 py-2 border border-border dark:border-border bg-background dark:bg-background text-foreground dark:text-foreground rounded-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:border-ring dark:focus:border-ring transition-all duration-200 focus:outline-none"
                      placeholder="Enter location"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                      Event Type
                    </label>
                    <select
                      value={eventForm.type}
                      onChange={(e) => setEventForm(prev => ({ ...prev, type: e.target.value as any }))}
                      className="w-full px-3 py-2 border border-border dark:border-border bg-background dark:bg-background text-foreground dark:text-foreground rounded-lg focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:border-ring dark:focus:border-ring transition-all duration-200 focus:outline-none"
                    >
                      <option value="trip">Off-Road Trip</option>
                      <option value="meeting">Planning Meeting</option>
                      <option value="task">Task Assignment</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                      Invite Group Members
                    </label>
                    <div className="space-y-2 max-h-32 overflow-y-auto">
                      {groupMembers.map(member => {
                        const isSelected = eventForm.attendees.includes(member.id)
                        const isAvailable = checkMemberAvailability(member.id, eventForm.date)

                        return (
                          <label
                            key={member.id}
                            className={`
                              flex items-center gap-3 p-2 rounded-lg cursor-pointer transition-all duration-150 hover:scale-[1.01]
                              ${isSelected ? 'bg-primary/10 dark:bg-primary/20 border border-primary/20 dark:border-primary/30' : 'hover:bg-muted dark:hover:bg-muted'}
                              ${!isAvailable ? 'opacity-60' : ''}
                            `}
                          >
                            <input
                              type="checkbox"
                              checked={isSelected}
                              onChange={() => toggleAttendee(member.id)}
                              className="rounded border-border dark:border-border text-primary dark:text-primary focus:ring-ring dark:focus:ring-ring bg-background dark:bg-background"
                            />
                            <div className="flex-1">
                              <div className="flex items-center gap-2">
                                <span className="font-medium text-foreground dark:text-foreground">{member.name}</span>
                                {!isAvailable && (
                                  <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
                                )}
                              </div>
                              <span className="text-sm text-mutedForeground dark:text-mutedForeground">{member.email}</span>
                            </div>
                          </label>
                        )
                      })}
                    </div>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <button
                      type="button"
                      onClick={() => {
                        setShowEventForm(false)
                        setSelectedEvent(null)
                        setError(null)
                      }}
                      className="flex-1 px-4 py-2 border border-border dark:border-border text-foreground dark:text-foreground bg-background dark:bg-background rounded-lg hover:bg-muted dark:hover:bg-muted transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="flex-1 px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:bg-primary/90 dark:hover:bg-primary/90 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:outline-none"
                    >
                      {loading ? 'Saving...' : selectedEvent ? 'Update' : 'Create'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

