'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Plus, X, ChevronDown } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  role: 'organizer' | 'member'
}

interface TripLocation {
  id: string
  name: string
  coordinates: { lat: number; lng: number }
  type: 'trailhead' | 'campground' | 'scenic_point'
}

interface CreateTripFormProps {
  onSubmit?: (tripData: any) => void
  initialData?: Partial<any>
  isLoading?: boolean
}

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {},
  isLoading = false
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState({
    title: initialData.title || '',
    description: initialData.description || '',
    startDate: initialData.startDate || '',
    endDate: initialData.endDate || '',
    location: initialData.location || null,
    maxParticipants: initialData.maxParticipants || 8,
    difficulty: initialData.difficulty || 'moderate',
    vehicleRequirement: initialData.vehicleRequirement || '4wd',
    estimatedCost: initialData.estimatedCost || '',
    members: initialData.members || []
  })

  const [showLocationPicker, setShowLocationPicker] = useState(false)
  const [newMemberEmail, setNewMemberEmail] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const popularLocations: TripLocation[] = [
    { id: '1', name: 'Moab, Utah - Hell\'s Revenge Trail', coordinates: { lat: 38.5733, lng: -109.5498 }, type: 'trailhead' },
    { id: '2', name: 'Sedona, Arizona - Broken Arrow Trail', coordinates: { lat: 34.8697, lng: -111.7610 }, type: 'trailhead' },
    { id: '3', name: 'Big Bear, California - John Bull Trail', coordinates: { lat: 34.2439, lng: -116.9114 }, type: 'trailhead' },
    { id: '4', name: 'Ouray, Colorado - Black Bear Pass', coordinates: { lat: 38.0228, lng: -107.6712 }, type: 'trailhead' }
  ]

  const difficultyLevels = [
    { value: 'easy', label: 'Easy', description: 'Suitable for stock vehicles' },
    { value: 'moderate', label: 'Moderate', description: 'Some modifications recommended' },
    { value: 'difficult', label: 'Difficult', description: 'Heavily modified vehicles required' },
    { value: 'extreme', label: 'Extreme', description: 'Expert drivers only' }
  ]

  const vehicleRequirements = [
    { value: 'stock', label: 'Stock Vehicle', description: 'Any 4WD vehicle' },
    { value: '4wd', label: '4WD Required', description: 'Four-wheel drive necessary' },
    { value: 'lifted', label: 'Lifted Vehicle', description: 'Lift kit recommended' },
    { value: 'modified', label: 'Heavily Modified', description: 'Significant modifications required' }
  ]

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.title.trim()) {
      newErrors.title = 'Trip title is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (!formData.location) {
      newErrors.location = 'Location is required'
    }

    if (formData.maxParticipants < 2 || formData.maxParticipants > 20) {
      newErrors.maxParticipants = 'Group size must be between 2 and 20'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const addMember = () => {
    if (newMemberEmail && !formData.members.find((m: TripMember) => m.email === newMemberEmail)) {
      const newMember: TripMember = {
        id: Date.now().toString(),
        name: newMemberEmail.split('@')[0],
        email: newMemberEmail,
        role: 'member'
      }

      setFormData(prev => ({
        ...prev,
        members: [...prev.members, newMember]
      }))
      setNewMemberEmail('')
    }
  }

  const removeMember = (memberId: string) => {
    setFormData(prev => ({
      ...prev,
      members: prev.members.filter((m: TripMember) => m.id !== memberId)
    }))
  }

  const selectLocation = (location: TripLocation) => {
    setFormData(prev => ({ ...prev, location }))
    setShowLocationPicker(false)
    if (errors.location) {
      setErrors(prev => ({ ...prev, location: '' }))
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-muted dark:from-background dark:to-muted font-sans">
      <div className="max-w-2xl mx-auto px-4 py-6">
        <div className="bg-surface dark:bg-surface rounded-2xl shadow-lg border border-border dark:border-border hover:shadow-xl transition-all duration-300">
          <div className="p-6 border-b border-border dark:border-border">
            <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2">Plan Your Off-Road Adventure</h1>
            <p className="text-mutedForeground dark:text-mutedForeground">Create an epic trip and invite your crew</p>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Trip Title *
              </label>
              <input
                id="title"
                type="text"
                value={formData.title}
                onChange={(e) => {
                  setFormData(prev => ({ ...prev, title: e.target.value }))
                  if (errors.title) setErrors(prev => ({ ...prev, title: '' }))
                }}
                placeholder="Epic Moab Adventure 2024"
                className={`w-full px-4 py-3 bg-surface dark:bg-surface border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 ${
                  errors.title ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive' : 'border-border dark:border-border focus:border-primary dark:focus:border-primary'
                }`}
                aria-describedby={errors.title ? 'title-error' : undefined}
              />
              {errors.title && (
                <p id="title-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.title}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Description
              </label>
              <textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                placeholder="Tell your group what to expect on this adventure..."
                rows={3}
                className="w-full px-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 resize-none"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="startDate" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Start Date *
                </label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-mutedForeground dark:text-mutedForeground" />
                  <input
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => {
                      setFormData(prev => ({ ...prev, startDate: e.target.value }))
                      if (errors.startDate) setErrors(prev => ({ ...prev, startDate: '' }))
                    }}
                    className={`w-full pl-10 pr-4 py-3 bg-surface dark:bg-surface border rounded-xl text-foreground dark:text-foreground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 ${
                      errors.startDate ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive' : 'border-border dark:border-border focus:border-primary dark:focus:border-primary'
                    }`}
                    aria-describedby={errors.startDate ? 'start-date-error' : undefined}
                  />
                </div>
                {errors.startDate && (
                  <p id="start-date-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.startDate}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="endDate" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  End Date *
                </label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-mutedForeground dark:text-mutedForeground" />
                  <input
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => {
                      setFormData(prev => ({ ...prev, endDate: e.target.value }))
                      if (errors.endDate) setErrors(prev => ({ ...prev, endDate: '' }))
                    }}
                    className={`w-full pl-10 pr-4 py-3 bg-surface dark:bg-surface border rounded-xl text-foreground dark:text-foreground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 ${
                      errors.endDate ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive' : 'border-border dark:border-border focus:border-primary dark:focus:border-primary'
                    }`}
                    aria-describedby={errors.endDate ? 'end-date-error' : undefined}
                  />
                </div>
                {errors.endDate && (
                  <p id="end-date-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.endDate}
                  </p>
                )}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Location *
              </label>
              <div className="relative">
                <button
                  type="button"
                  onClick={() => setShowLocationPicker(!showLocationPicker)}
                  className={`w-full px-4 py-3 bg-surface dark:bg-surface border rounded-xl text-left focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 flex items-center justify-between hover:border-primary dark:hover:border-primary ${
                    errors.location ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive' : 'border-border dark:border-border focus:border-primary dark:focus:border-primary'
                  }`}
                  aria-expanded={showLocationPicker}
                  aria-haspopup="listbox"
                  aria-describedby={errors.location ? 'location-error' : undefined}
                >
                  <div className="flex items-center">
                    <MapPin className="h-5 w-5 text-mutedForeground dark:text-mutedForeground mr-3" />
                    <span className={formData.location ? 'text-foreground dark:text-foreground' : 'text-mutedForeground dark:text-mutedForeground'}>
                      {formData.location ? formData.location.name : 'Select a location'}
                    </span>
                  </div>
                  <ChevronDown className={`h-5 w-5 text-mutedForeground dark:text-mutedForeground transition-transform duration-200 ${showLocationPicker ? 'rotate-180' : ''}`} />
                </button>

                {showLocationPicker && (
                  <div className="absolute z-10 w-full mt-2 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl shadow-lg max-h-60 overflow-y-auto">
                    {popularLocations.map((location) => (
                      <button
                        key={location.id}
                        type="button"
                        onClick={() => selectLocation(location)}
                        className="w-full px-4 py-3 text-left hover:bg-muted dark:hover:bg-muted focus:bg-muted dark:focus:bg-muted focus:outline-none transition-colors duration-150 border-b border-border dark:border-border last:border-b-0"
                        role="option"
                        aria-selected={formData.location?.id === location.id}
                      >
                        <div className="flex items-center">
                          <MapPin className="h-4 w-4 text-primary dark:text-primary mr-3 flex-shrink-0" />
                          <span className="text-foreground dark:text-foreground font-medium">{location.name}</span>
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              {errors.location && (
                <p id="location-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="maxParticipants" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Maximum Group Size *
              </label>
              <div className="relative">
                <Users className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-mutedForeground dark:text-mutedForeground" />
                <input
                  id="maxParticipants"
                  type="number"
                  min="2"
                  max="20"
                  value={formData.maxParticipants}
                  onChange={(e) => {
                    setFormData(prev => ({ ...prev, maxParticipants: parseInt(e.target.value) || 2 }))
                    if (errors.maxParticipants) setErrors(prev => ({ ...prev, maxParticipants: '' }))
                  }}
                  className={`w-full pl-10 pr-4 py-3 bg-surface dark:bg-surface border rounded-xl text-foreground dark:text-foreground focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 ${
                    errors.maxParticipants ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive' : 'border-border dark:border-border focus:border-primary dark:focus:border-primary'
                  }`}
                  aria-describedby={errors.maxParticipants ? 'max-participants-error' : undefined}
                />
              </div>
              {errors.maxParticipants && (
                <p id="max-participants-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.maxParticipants}
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Difficulty Level
              </label>
              <div className="grid grid-cols-2 gap-3">
                {difficultyLevels.map((level) => (
                  <button
                    key={level.value}
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, difficulty: level.value }))}
                    className={`p-3 rounded-xl border-2 text-left transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] ${
                      formData.difficulty === level.value
                        ? 'border-primary dark:border-primary bg-muted dark:bg-muted'
                        : 'border-border dark:border-border bg-surface dark:bg-surface hover:border-primary/50 dark:hover:border-primary/50'
                    }`}
                    aria-pressed={formData.difficulty === level.value}
                  >
                    <div className="font-medium text-foreground dark:text-foreground">{level.label}</div>
                    <div className="text-sm text-mutedForeground dark:text-mutedForeground mt-1">{level.description}</div>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Vehicle Requirement
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {vehicleRequirements.map((requirement) => (
                  <button
                    key={requirement.value}
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, vehicleRequirement: requirement.value }))}
                    className={`p-3 rounded-xl border-2 text-left transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] ${
                      formData.vehicleRequirement === requirement.value
                        ? 'border-primary dark:border-primary bg-muted dark:bg-muted'
                        : 'border-border dark:border-border bg-surface dark:bg-surface hover:border-primary/50 dark:hover:border-primary/50'
                    }`}
                    aria-pressed={formData.vehicleRequirement === requirement.value}
                  >
                    <div className="font-medium text-foreground dark:text-foreground">{requirement.label}</div>
                    <div className="text-sm text-mutedForeground dark:text-mutedForeground mt-1">{requirement.description}</div>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label htmlFor="estimatedCost" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Estimated Cost Per Person
              </label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-mutedForeground dark:text-mutedForeground">$</span>
                <input
                  id="estimatedCost"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.estimatedCost}
                  onChange={(e) => setFormData(prev => ({ ...prev, estimatedCost: e.target.value }))}
                  placeholder="150.00"
                  className="w-full pl-8 pr-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Invite Group Members
              </label>
              <div className="flex gap-2 mb-3">
                <input
                  type="email"
                  value={newMemberEmail}
                  onChange={(e) => setNewMemberEmail(e.target.value)}
                  placeholder="friend@example.com"
                  className="flex-1 px-4 py-3 bg-surface dark:bg-surface border border-border dark:border-border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addMember())}
                />
                <button
                  type="button"
                  onClick={addMember}
                  disabled={!newMemberEmail}
                  className="px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-xl hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted dark:disabled:bg-muted disabled:text-mutedForeground dark:disabled:text-mutedForeground disabled:cursor-not-allowed transition-all duration-200 flex items-center justify-center min-w-[44px]"
                  aria-label="Add member"
                >
                  <Plus className="h-5 w-5" />
                </button>
              </div>

              {formData.members.length > 0 && (
                <div className="space-y-2">
                  {formData.members.map((member: TripMember) => (
                    <div key={member.id} className="flex items-center justify-between p-3 bg-muted dark:bg-muted rounded-xl hover:shadow-md transition-all duration-200">
                      <div>
                        <div className="font-medium text-foreground dark:text-foreground">{member.name}</div>
                        <div className="text-sm text-mutedForeground dark:text-mutedForeground">{member.email}</div>
                      </div>
                      <button
                        type="button"
                        onClick={() => removeMember(member.id)}
                        className="p-1 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive transition-colors duration-200 min-w-[44px] min-h-[44px] flex items-center justify-center hover:scale-110 active:scale-95"
                        aria-label={`Remove ${member.name}`}
                      >
                        <X className="h-4 w-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="pt-4">
              <button
                type="submit"
                disabled={isLoading}
                className="w-full px-6 py-4 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-xl hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted dark:disabled:bg-muted disabled:text-mutedForeground dark:disabled:text-mutedForeground disabled:cursor-not-allowed transition-all duration-200 font-medium text-lg shadow-lg hover:shadow-xl focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 focus:ring-offset-2"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-primaryForeground dark:border-primaryForeground mr-2"></div>
                    Creating Trip...
                  </div>
                ) : (
                  'Create Adventure'
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  )
}

