interface GroupMember {
  id: string
  name: string
  avatar?: string
  email: string
}

interface TripTasksPanelProps {
  tripId?: string
  tasks?: Task[]
  members?: GroupMember[]
  onTaskCreate?: (task: Omit<Task, 'id' | 'createdAt'>) => void
  onTaskUpdate?: (taskId: string, updates: Partial<Task>) => void
  onTaskDelete?: (taskId: string) => void
  isReadOnly?: boolean
  isLoading?: boolean
}

