    description: 'Verify all supplies are stocked and not expired',
    assignedTo: ['member-4'],
    dueDate: '2024-01-14T09:00:00Z',
    category: 'safety',
    completed: false,
    priority: 'high',
    createdAt: '2024-01-10T12:00:00Z'
  }
