  { value: 'food', label: 'Food & Meals', color: 'bg-[#F97316]/10 text-[#F97316] border-[#F97316]/20' },
  { value: 'gear', label: 'Gear & Equipment', color: 'bg-[#059669]/10 text-[#059669] border-[#059669]/20' },
