  { value: 'other', label: 'Other', color: 'bg-[#78716C]/10 text-[#78716C] border-[#78716C]/20' }
]

const PRIORITIES = [
  { value: 'low', label: 'Low', color: 'bg-[#059669]/10 text-[#059669]' },
  { value: 'medium', label: 'Medium', color: 'bg-[#F97316]/10 text-[#F97316]' },
  { value: 'high', label: 'High', color: 'bg-[#DC2626]/10 text-[#DC2626]' }
]

export function TripTasksPanel({
  tripId = 'trip-1',
  tasks = DEFAULT_TASKS,
  members = DEFAULT_MEMBERS,
  onTaskCreate = () => console.log('Task created'),
  onTaskUpdate = () => console.log('Task updated'),
  onTaskDelete = () => console.log('Task deleted'),
  isReadOnly = false,
  isLoading = false
}: TripTasksPanelProps = {}) {
  const [localTasks, setLocalTasks] = useState<Task[]>(tasks)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingTask, setEditingTask] = useState<string | null>(null)
  const [filter, setFilter] = useState<'all' | 'pending' | 'completed'>('all')
  const [categoryFilter, setCategoryFilter] = useState<string>('all')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    setLocalTasks(tasks)
  }, [tasks])

  const filteredTasks = localTasks.filter(task => {
    const statusMatch = filter === 'all' || 
      (filter === 'pending' && !task.completed) ||
      (filter === 'completed' && task.completed)

    const categoryMatch = categoryFilter === 'all' || task.category === categoryFilter

    return statusMatch && categoryMatch
  })

  const handleTaskToggle = (taskId: string) => {
    const updatedTasks = localTasks.map(task =>
      task.id === taskId
        ? {
            ...task,
            completed: !task.completed,
            completedAt: !task.completed ? new Date().toISOString() : undefined
          }
        : task
    )
    setLocalTasks(updatedTasks)

    const task = updatedTasks.find(t => t.id === taskId)
    if (task) {
      onTaskUpdate(taskId, {
        completed: task.completed,
        completedAt: task.completedAt
      })
    }
  }

  const handleTaskDelete = (taskId: string) => {
    setLocalTasks(prev => prev.filter(task => task.id !== taskId))
    onTaskDelete(taskId)
  }

  const getMemberName = (memberId: string) => {
    return members.find(m => m.id === memberId)?.name || 'Unknown'
  }

  const getCategoryInfo = (category: string) => {
    return CATEGORIES.find(c => c.value === category) || CATEGORIES[4]
  }

  const getPriorityInfo = (priority: string) => {
    return PRIORITIES.find(p => p.value === priority) || PRIORITIES[0]
  }

  const formatDueDate = (dateString?: string) => {
    if (!dateString) return null
    const date = new Date(dateString)
    const now = new Date()
    const diffDays = Math.ceil((date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))

    if (diffDays < 0) return 'Overdue'
    if (diffDays === 0) return 'Due today'
    if (diffDays === 1) return 'Due tomorrow'
    return `Due in ${diffDays} days`
  }

  const completedCount = localTasks.filter(t => t.completed).length
  const totalCount = localTasks.length
  const progressPercentage = totalCount > 0 ? (completedCount / totalCount) * 100 : 0

  const LoadingSkeleton = () => (
    <div className="space-y-4 animate-pulse">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-6">
          <div className="flex items-start gap-4">
            <div className="w-5 h-5 bg-[#F5F5F4] dark:bg-[#292524] rounded-full mt-1"></div>
            <div className="flex-1 space-y-3">
              <div className="h-4 bg-[#F5F5F4] dark:bg-[#292524] rounded w-3/4"></div>
              <div className="h-3 bg-[#F5F5F4] dark:bg-[#292524] rounded w-1/2"></div>
              <div className="flex gap-2">
                <div className="h-6 bg-[#F5F5F4] dark:bg-[#292524] rounded w-16"></div>
                <div className="h-6 bg-[#F5F5F4] dark:bg-[#292524] rounded w-12"></div>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )

  return (
    <div className="min-h-screen bg-[#FEFEFE] dark:bg-[#0C0A09] font-[Inter,-apple-system,BlinkMacSystemFont,system-ui,sans-serif]">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <div className="mb-8">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
            <div>
              <h1 className="text-2xl font-bold text-[#1C1917] dark:text-[#FAFAF9] mb-2">
                Trip Tasks
              </h1>
              <p className="text-[#78716C] dark:text-[#A8A29E]">
                Organize and track responsibilities for your off-road adventure
              </p>
            </div>

            {!isReadOnly && (
              <button
                onClick={() => setShowCreateForm(true)}
                className="flex items-center gap-2 px-4 py-2 bg-[#F97316] dark:bg-[#FB923C] text-[#FFFFFF] dark:text-[#1C1917] rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-sm hover:shadow-md min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09]"
                aria-label="Create new task"
              >
                <Plus className="w-4 h-4" />
                <span className="hidden sm:inline">Add Task</span>
              </button>
            )}
          </div>

          <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl p-4 border border-[#E7E5E4] dark:border-[#44403C] shadow-sm">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-[#1C1917] dark:text-[#FAFAF9]">
                Progress
              </span>
              <span className="text-sm text-[#78716C] dark:text-[#A8A29E]">
                {completedCount} of {totalCount} completed
              </span>
            </div>
            <div className="w-full bg-[#F5F5F4] dark:bg-[#292524] rounded-full h-2">
              <div
                className="bg-[#F97316] dark:bg-[#FB923C] h-2 rounded-full transition-all duration-300"
                style={{ width: `${progressPercentage}%` }}
              />
            </div>
          </div>
        </div>

        {error && (
          <div className="rounded-lg bg-[#DC2626]/10 dark:bg-[#EF4444]/10 border border-[#DC2626]/20 dark:border-[#EF4444]/20 p-4 mb-6">
            <p className="text-sm text-[#DC2626] dark:text-[#EF4444]">{error}</p>
          </div>
        )}

        <div className="mb-6 space-y-4">
          <div className="flex flex-wrap gap-2">
            {['all', 'pending', 'completed'].map((filterOption) => (
              <button
                key={filterOption}
                onClick={() => setFilter(filterOption as 'all' | 'pending' | 'completed')}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all duration-150 min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09] ${
                  filter === filterOption
                    ? 'bg-[#F97316] dark:bg-[#FB923C] text-[#FFFFFF] dark:text-[#1C1917] shadow-sm'
                    : 'bg-[#FFFFFF] dark:bg-[#1C1917] text-[#1C1917] dark:text-[#FAFAF9] border border-[#E7E5E4] dark:border-[#44403C] hover:bg-[#F5F5F4] dark:hover:bg-[#292524] hover:scale-[1.02] active:scale-[0.98]'
                }`}
              >
                {filterOption.charAt(0).toUpperCase() + filterOption.slice(1)} Tasks
              </button>
            ))}
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setCategoryFilter('all')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all duration-150 min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09] ${
                categoryFilter === 'all'
                  ? 'bg-[#1C1917] dark:bg-[#FAFAF9] text-[#FAFAF9] dark:text-[#1C1917] shadow-sm'
                  : 'bg-[#FFFFFF] dark:bg-[#1C1917] text-[#1C1917] dark:text-[#FAFAF9] border border-[#E7E5E4] dark:border-[#44403C] hover:bg-[#F5F5F4] dark:hover:bg-[#292524] hover:scale-[1.02] active:scale-[0.98]'
              }`}
            >
              All Categories
            </button>
            {CATEGORIES.map(category => (
              <button
                key={category.value}
                onClick={() => setCategoryFilter(category.value)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all duration-150 min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09] ${
                  categoryFilter === category.value
                    ? 'bg-[#1C1917] dark:bg-[#FAFAF9] text-[#FAFAF9] dark:text-[#1C1917] shadow-sm'
                    : 'bg-[#FFFFFF] dark:bg-[#1C1917] text-[#1C1917] dark:text-[#FAFAF9] border border-[#E7E5E4] dark:border-[#44403C] hover:bg-[#F5F5F4] dark:hover:bg-[#292524] hover:scale-[1.02] active:scale-[0.98]'
                }`}
              >
                {category.label}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          {isLoading ? (
            <LoadingSkeleton />
          ) : filteredTasks.length === 0 ? (
            <div className="text-center py-12 bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C]">
              <div className="w-16 h-16 bg-[#F5F5F4] dark:bg-[#292524] rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-[#78716C] dark:text-[#A8A29E]" />
              </div>
              <h3 className="text-lg font-medium text-[#1C1917] dark:text-[#FAFAF9] mb-2">
                No tasks found
              </h3>
              <p className="text-[#78716C] dark:text-[#A8A29E] mb-4">
                {filter === 'all' 
                  ? "Get started by creating your first task"
                  : `No ${filter} tasks match your current filters`
                }
              </p>
              {!isReadOnly && filter === 'all' && (
                <button
                  onClick={() => setShowCreateForm(true)}
                  className="px-4 py-2 bg-[#F97316] dark:bg-[#FB923C] text-[#FFFFFF] dark:text-[#1C1917] rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium min-h-[44px] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09]"
                >
                  Create First Task
                </button>
              )}
            </div>
          ) : (
            filteredTasks.map(task => (
              <div
                key={task.id}
                className={`bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-4 sm:p-6 transition-all duration-300 shadow-sm hover:shadow-md hover:-translate-y-1 ${
                  task.completed ? 'opacity-75' : ''
                }`}
              >
                <div className="flex items-start gap-4">
                  <button
                    onClick={() => handleTaskToggle(task.id)}
                    className="flex-shrink-0 mt-1 text-[#F97316] dark:text-[#FB923C] hover:scale-110 transition-all duration-150 min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FFFFFF] dark:focus:ring-offset-[#1C1917] rounded-lg"
                    aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
                    disabled={isReadOnly}
                  >
                    {task.completed ? (
                      <CheckCircle2 className="w-5 h-5" />
                    ) : (
                      <Circle className="w-5 h-5" />
                    )}
                  </button>

                  <div className="flex-1 min-w-0">
                    <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-2 mb-3">
                      <h3 className={`font-medium text-[#1C1917] dark:text-[#FAFAF9] ${
                        task.completed ? 'line-through' : ''
                      }`}>
                        {task.title}
                      </h3>

                      <div className="flex flex-wrap items-center gap-2">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${
                          getCategoryInfo(task.category).color
                        }`}>
                          {getCategoryInfo(task.category).label}
                        </span>

                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          getPriorityInfo(task.priority).color
                        }`}>
                          {getPriorityInfo(task.priority).label}
                        </span>
                      </div>
                    </div>

                    {task.description && (
                      <p className="text-[#78716C] dark:text-[#A8A29E] text-sm mb-3">
                        {task.description}
                      </p>
                    )}

                    <div className="flex flex-col sm:flex-row sm:items-center gap-3 text-sm text-[#78716C] dark:text-[#A8A29E]">
                      {task.assignedTo.length > 0 && (
                        <div className="flex items-center gap-1">
                          <User className="w-4 h-4" />
                          <span>
                            {task.assignedTo.map(memberId => getMemberName(memberId)).join(', ')}
                          </span>
                        </div>
                      )}

                      {task.dueDate && (
                        <div className="flex items-center gap-1">
                          <Calendar className="w-4 h-4" />
                          <span className={
                            formatDueDate(task.dueDate) === 'Overdue' 
                              ? 'text-[#DC2626] dark:text-[#EF4444] font-medium'
                              : formatDueDate(task.dueDate) === 'Due today'
                              ? 'text-[#F97316] dark:text-[#FB923C] font-medium'
                              : ''
                          }>
                            {formatDueDate(task.dueDate)}
                          </span>
                        </div>
                      )}

                      {task.completedAt && (
                        <div className="flex items-center gap-1 text-[#059669] dark:text-[#10B981]">
                          <Clock className="w-4 h-4" />
                          <span>
                            Completed {new Date(task.completedAt).toLocaleDateString()}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  {!isReadOnly && (
                    <div className="flex items-center gap-1">
                      <button
                        onClick={() => setEditingTask(task.id)}
                        className="p-2 text-[#78716C] dark:text-[#A8A29E] hover:text-[#1C1917] dark:hover:text-[#FAFAF9] hover:scale-110 transition-all duration-150 min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FFFFFF] dark:focus:ring-offset-[#1C1917] rounded-lg"
                        aria-label="Edit task"
                      >
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleTaskDelete(task.id)}
                        className="p-2 text-[#78716C] dark:text-[#A8A29E] hover:text-[#DC2626] dark:hover:text-[#EF4444] hover:scale-110 transition-all duration-150 min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-[#DC2626] dark:focus:ring-[#EF4444] focus:ring-offset-2 focus:ring-offset-[#FFFFFF] dark:focus:ring-offset-[#1C1917] rounded-lg"
                        aria-label="Delete task"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>

        {showCreateForm && (
          <div className="fixed inset-0 bg-black/60 flex items-center justify-center p-4 z-50 backdrop-blur-sm">
            <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl max-w-md w-full max-h-[90vh] overflow-y-auto shadow-xl">
