'use client'

import { useState } from 'react'
import { Eye, EyeOff, Mountain, Users, MapPin, Calendar } from 'lucide-react'

interface LoginPageProps {
  onLogin?: (email: string, password: string) => void;
  onSignUp?: (email: string, password: string, name: string) => void;
  onForgotPassword?: (email: string) => void;
}

export function LoginPage({
  onLogin = (email, password) => console.log('Login:', { email, password }),
  onSignUp = (email, password, name) => console.log('Sign up:', { email, password, name }),
  onForgotPassword = (email) => console.log('Forgot password:', email)
}: LoginPageProps = {}) {
  const [isSignUp, setIsSignUp] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [name, setName] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)
    setError('')

    try {
      if (isSignUp) {
        await onSignUp(email, password, name)
      } else {
        await onLogin(email, password)
      }
    } catch (error) {
      console.error('Authentication error:', error)
      setError('Authentication failed. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleForgotPassword = () => {
    if (email) {
      onForgotPassword(email)
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background flex flex-col font-sans">
      <div 
        className="absolute inset-0 bg-gradient-to-br from-primary/5 via-background to-secondary/5 dark:from-primary/10 dark:via-background dark:to-secondary/10"
        style={{
          background: 'linear-gradient(135deg, #F97316 0%, #DC2626 100%)',
          opacity: 0.03
        }}
      />

      <div className="relative z-10 flex flex-col min-h-screen">
        <div className="flex items-center justify-center pt-8 pb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-primary to-accent rounded-xl flex items-center justify-center shadow-lg hover:scale-105 transition-transform duration-200">
              <Mountain className="w-6 h-6 text-primaryForeground" />
            </div>
            <h1 className="text-2xl font-bold text-foreground">TrailPlan</h1>
          </div>
        </div>

        <div className="flex-1 flex items-center justify-center px-4 py-8">
          <div className="w-full max-w-md">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-bold text-foreground mb-3">
                {isSignUp ? 'Join the Adventure' : 'Welcome Back'}
              </h2>
              <p className="text-mutedForeground text-lg">
                {isSignUp 
                  ? 'Start planning epic off-road adventures with your crew'
                  : 'Ready for your next off-road adventure?'
                }
              </p>
            </div>

            <div className="grid grid-cols-3 gap-4 mb-8">
              <div className="text-center group">
                <div className="w-12 h-12 bg-surface border border-border rounded-xl flex items-center justify-center mx-auto mb-2 group-hover:border-primary/50 group-hover:shadow-md transition-all duration-200">
                  <MapPin className="w-6 h-6 text-primary" />
                </div>
                <p className="text-xs text-mutedForeground font-medium">Plan Routes</p>
              </div>
              <div className="text-center group">
                <div className="w-12 h-12 bg-surface border border-border rounded-xl flex items-center justify-center mx-auto mb-2 group-hover:border-primary/50 group-hover:shadow-md transition-all duration-200">
                  <Users className="w-6 h-6 text-primary" />
                </div>
                <p className="text-xs text-mutedForeground font-medium">Organize Crew</p>
              </div>
              <div className="text-center group">
                <div className="w-12 h-12 bg-surface border border-border rounded-xl flex items-center justify-center mx-auto mb-2 group-hover:border-primary/50 group-hover:shadow-md transition-all duration-200">
                  <Calendar className="w-6 h-6 text-primary" />
                </div>
                <p className="text-xs text-mutedForeground font-medium">Schedule Trips</p>
              </div>
            </div>

            <div className="bg-surface rounded-2xl p-6 border border-border shadow-lg hover:shadow-xl transition-all duration-300">
              {error && (
                <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-4 mb-4">
                  <p className="text-sm text-destructive">{error}</p>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-4">
                {isSignUp && (
                  <div>
                    <label htmlFor="name" className="block text-sm font-medium text-foreground mb-2">
                      Full Name
                    </label>
                    <input
                      id="name"
                      type="text"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="w-full px-4 py-3 bg-muted border border-border rounded-xl text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 transition-all duration-200 hover:border-ring/50"
                      placeholder="Enter your full name"
                      required={isSignUp}
                      aria-label="Full name"
                    />
                  </div>
                )}

                <div>
                  <label htmlFor="email" className="block text-sm font-medium text-foreground mb-2">
                    Email Address
                  </label>
                  <input
                    id="email"
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full px-4 py-3 bg-muted border border-border rounded-xl text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 transition-all duration-200 hover:border-ring/50"
                    placeholder="Enter your email"
                    required
                    aria-label="Email address"
                  />
                </div>

                <div>
                  <label htmlFor="password" className="block text-sm font-medium text-foreground mb-2">
                    Password
                  </label>
                  <div className="relative">
                    <input
                      id="password"
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full px-4 py-3 bg-muted border border-border rounded-xl text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 transition-all duration-200 pr-12 hover:border-ring/50"
                      placeholder="Enter your password"
                      required
                      minLength={6}
                      aria-label="Password"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 text-mutedForeground hover:text-foreground transition-colors duration-200 p-1 rounded-md hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring/20"
                      aria-label={showPassword ? 'Hide password' : 'Show password'}
                    >
                      {showPassword ? (
                        <EyeOff className="w-5 h-5" />
                      ) : (
                        <Eye className="w-5 h-5" />
                      )}
                    </button>
                  </div>
                </div>

                {!isSignUp && (
                  <div className="text-right">
                    <button
                      type="button"
                      onClick={handleForgotPassword}
                      className="text-sm text-primary hover:text-primary/80 transition-colors duration-200 font-medium hover:underline focus:outline-none focus:ring-2 focus:ring-ring/20 rounded px-1 py-1"
                      disabled={!email}
                      aria-label="Reset password"
                    >
                      Forgot Password?
                    </button>
                  </div>
                )}

                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full py-3 bg-primary text-primaryForeground rounded-xl font-semibold text-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 min-h-[48px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-ring/50"
                  aria-label={isSignUp ? 'Create account' : 'Sign in'}
                >
                  {isLoading ? (
                    <div className="w-6 h-6 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                  ) : (
                    isSignUp ? 'Create Account' : 'Sign In'
                  )}
                </button>
              </form>

              <div className="mt-6 text-center">
                <p className="text-mutedForeground">
                  {isSignUp ? 'Already have an account?' : "Don't have an account?"}
                  {' '}
                  <button
                    type="button"
                    onClick={() => {
                      setIsSignUp(!isSignUp)
                      setError('')
                    }}
                    className="text-primary hover:text-primary/80 transition-colors duration-200 font-medium hover:underline focus:outline-none focus:ring-2 focus:ring-ring/20 rounded px-1 py-1"
                    aria-label={isSignUp ? 'Switch to sign in' : 'Switch to sign up'}
                  >
                    {isSignUp ? 'Sign In' : 'Sign Up'}
                  </button>
                </p>
              </div>
            </div>

            <div className="mt-8 text-center">
              <p className="text-mutedForeground text-sm">
                Join thousands of adventurers planning epic off-road trips
              </p>
              <div className="flex items-center justify-center gap-2 mt-3">
                <div className="flex -space-x-2">
                  {[1, 2, 3, 4].map((i) => (
                    <div
                      key={i}
                      className="w-8 h-8 bg-gradient-to-br from-primary to-accent rounded-full border-2 border-background flex items-center justify-center shadow-sm hover:scale-110 transition-transform duration-200"
                    >
                      <span className="text-primaryForeground text-xs font-bold">{i}</span>
                    </div>
                  ))}
                </div>
                <span className="text-mutedForeground text-sm ml-2">+2.5k members</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function LoginPageDemo() {
  return <LoginPage />
}

