'use client'

import { useState, useEffect } from 'react'
import { 
  Mountain, 
  Calendar, 
  Users, 
  MessageSquare, 
  MapPin, 
  Settings,
  Menu,
  X,
  Home,
  UtensilsCrossed,
  CheckSquare
} from 'lucide-react'

interface AppLayoutProps {
  children?: React.ReactNode;
  currentPage?: string;
  onNavigate?: (page: string) => void;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  href: string;
}

const navigationItems: NavigationItem[] = [
  { id: 'dashboard', label: 'Dashboard', icon: Home, href: '/dashboard' },
  { id: 'trips', label: 'Trips', icon: Mountain, href: '/trips' },
  { id: 'locations', label: 'Locations', icon: MapPin, href: '/locations' },
  { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
  { id: 'tasks', label: 'Tasks', icon: CheckSquare, href: '/tasks' },
  { id: 'meals', label: 'Meals', icon: UtensilsCrossed, href: '/meals' },
  { id: 'chat', label: 'Chat', icon: MessageSquare, href: '/chat' },
  { id: 'group', label: 'Group', icon: Users, href: '/group' },
]

export function AppLayout({
  children,
  currentPage = 'dashboard',
  onNavigate = () => {}
}: AppLayoutProps = {}) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isOnline, setIsOnline] = useState(true)

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const handleNavigation = (page: string) => {
    onNavigate(page)
    setIsMobileMenuOpen(false)
  }

  const handleKeyDown = (event: React.KeyboardEvent, action: () => void) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      action()
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans text-foreground dark:text-foreground">
      {!isOnline && (
        <div className="bg-accent text-accentForeground px-4 py-2 text-center text-sm font-medium">
          You're offline. Some features may be limited.
        </div>
      )}

      <header className="lg:hidden bg-surface/80 dark:bg-surface/80 backdrop-blur-sm border-b border-border dark:border-border sticky top-0 z-50">
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <Mountain className="w-8 h-8 text-primary dark:text-primary" />
            <h1 className="text-xl font-bold text-foreground dark:text-foreground">TrailPlan</h1>
          </div>

          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            onKeyDown={(e) => handleKeyDown(e, () => setIsMobileMenuOpen(!isMobileMenuOpen))}
            className="p-2 rounded-lg bg-muted dark:bg-muted hover:bg-muted/80 dark:hover:bg-muted/80 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background hover:scale-[1.02] active:scale-[0.98]"
            aria-label={isMobileMenuOpen ? 'Close menu' : 'Open menu'}
            aria-expanded={isMobileMenuOpen}
          >
            {isMobileMenuOpen ? (
              <X className="w-6 h-6" />
            ) : (
              <Menu className="w-6 h-6" />
            )}
          </button>
        </div>

        {isMobileMenuOpen && (
          <div className="absolute top-full left-0 right-0 bg-surface/95 dark:bg-surface/95 backdrop-blur-sm border-b border-border dark:border-border shadow-lg">
            <nav className="px-4 py-2" role="navigation" aria-label="Mobile navigation">
              <div className="grid grid-cols-2 gap-2">
                {navigationItems.map((item) => {
                  const Icon = item.icon
                  const isActive = currentPage === item.id

                  return (
                    <button
                      key={item.id}
                      onClick={() => handleNavigation(item.id)}
                      onKeyDown={(e) => handleKeyDown(e, () => handleNavigation(item.id))}
                      className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-150 text-left min-h-[44px] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background hover:scale-[1.02] active:scale-[0.98] ${
                        isActive
                          ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-md'
                          : 'bg-muted/50 dark:bg-muted/50 text-mutedForeground dark:text-mutedForeground hover:bg-muted dark:hover:bg-muted hover:text-foreground dark:hover:text-foreground'
                      }`}
                      aria-current={isActive ? 'page' : undefined}
                    >
                      <Icon className="w-5 h-5 flex-shrink-0" />
                      <span className="font-medium text-sm">{item.label}</span>
                    </button>
                  )
                })}
              </div>
            </nav>
          </div>
        )}
      </header>

      <div className="flex">
        <aside className="hidden lg:flex lg:flex-col lg:w-64 lg:fixed lg:inset-y-0 bg-surface/50 dark:bg-surface/50 backdrop-blur-sm border-r border-border dark:border-border">
          <div className="flex items-center gap-3 px-6 py-6 border-b border-border dark:border-border">
            <Mountain className="w-8 h-8 text-primary dark:text-primary" />
            <h1 className="text-xl font-bold text-foreground dark:text-foreground">TrailPlan</h1>
          </div>

          <nav className="flex-1 px-4 py-6 space-y-2" role="navigation" aria-label="Main navigation">
            {navigationItems.map((item) => {
              const Icon = item.icon
              const isActive = currentPage === item.id

              return (
                <button
                  key={item.id}
                  onClick={() => handleNavigation(item.id)}
                  onKeyDown={(e) => handleKeyDown(e, () => handleNavigation(item.id))}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-150 text-left min-h-[44px] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background hover:scale-[1.02] active:scale-[0.98] ${
                    isActive
                      ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-md'
                      : 'text-mutedForeground dark:text-mutedForeground hover:bg-muted/50 dark:hover:bg-muted/50 hover:text-foreground dark:hover:text-foreground'
                  }`}
                  aria-current={isActive ? 'page' : undefined}
                >
                  <Icon className="w-5 h-5 flex-shrink-0" />
                  <span className="font-medium">{item.label}</span>
                </button>
              )
            })}
          </nav>

          <div className="px-4 py-6 border-t border-border dark:border-border">
            <button
              onClick={() => handleNavigation('settings')}
              onKeyDown={(e) => handleKeyDown(e, () => handleNavigation('settings'))}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-lg text-mutedForeground dark:text-mutedForeground hover:bg-muted/50 dark:hover:bg-muted/50 hover:text-foreground dark:hover:text-foreground transition-all duration-150 min-h-[44px] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background hover:scale-[1.02] active:scale-[0.98]"
              aria-label="Settings"
            >
              <Settings className="w-5 h-5" />
              <span className="font-medium">Settings</span>
            </button>
          </div>
        </aside>

        <main className="flex-1 lg:ml-64">
