                </li>
                <li className="flex items-start gap-3">
                  <div className="w-2 h-2 bg-destructive rounded-full mt-2 flex-shrink-0" />
                  Don't ignore loading and error states
                </li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

