'use client'

import React, { useState } from 'react'
import { z } from 'zod'

// Location Schema
export const LocationSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1, 'Location name is required'),
  address: z.string().min(1, 'Address is required'),
  coordinates: z.object({
    latitude: z.number().min(-90).max(90),
    longitude: z.number().min(-180).max(180)
  }),
  description: z.string().optional(),
  difficulty: z.enum(['easy', 'moderate', 'difficult', 'extreme']),
  terrain: z.enum(['desert', 'mountain', 'forest', 'beach', 'canyon', 'plains']),
  amenities: z.array(z.string()).default([]),
  images: z.array(z.string().url()).default([]),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
})

// Trip Schema
export const TripSchema = z.object({
  id: z.string().uuid(),
  title: z.string().min(1, 'Trip title is required'),
  description: z.string().optional(),
  locationId: z.string().uuid(),
  startDate: z.date(),
  endDate: z.date(),
  maxParticipants: z.number().min(1).max(50),
  difficulty: z.enum(['easy', 'moderate', 'difficult', 'extreme']),
  status: z.enum(['planning', 'confirmed', 'in-progress', 'completed', 'cancelled']).default('planning'),
  organizerId: z.string().uuid(),
  isPublic: z.boolean().default(false),
  requirements: z.array(z.string()).default([]),
  estimatedCost: z.number().min(0).optional(),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
}).refine(data => data.endDate >= data.startDate, {
  message: 'End date must be after start date',
  path: ['endDate']
})

// Participant Schema
export const ParticipantSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  userId: z.string().uuid(),
  status: z.enum(['invited', 'confirmed', 'declined', 'maybe']).default('invited'),
  role: z.enum(['organizer', 'participant', 'guide']).default('participant'),
  joinedAt: z.date().default(() => new Date()),
  notes: z.string().optional()
})

// Task Schema
export const TaskSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  title: z.string().min(1, 'Task title is required'),
  description: z.string().optional(),
  category: z.enum(['food', 'equipment', 'transportation', 'accommodation', 'safety', 'entertainment', 'other']),
  assignedTo: z.array(z.string().uuid()).default([]),
  dueDate: z.date().optional(),
  priority: z.enum(['low', 'medium', 'high', 'urgent']).default('medium'),
  status: z.enum(['pending', 'in-progress', 'completed', 'cancelled']).default('pending'),
  estimatedCost: z.number().min(0).optional(),
  actualCost: z.number().min(0).optional(),
  createdBy: z.string().uuid(),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
})

// Meal Schema
export const MealSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  name: z.string().min(1, 'Meal name is required'),
  type: z.enum(['breakfast', 'lunch', 'dinner', 'snack']),
  scheduledDate: z.date(),
  scheduledTime: z.string().regex(/^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/, 'Invalid time format'),
  description: z.string().optional(),
  ingredients: z.array(z.string()).default([]),
  servings: z.number().min(1),
  prepTime: z.number().min(0).optional(),
  cookTime: z.number().min(0).optional(),
  difficulty: z.enum(['easy', 'medium', 'hard']).default('easy'),
  dietaryRestrictions: z.array(z.string()).default([]),
  assignedTo: z.array(z.string().uuid()).default([]),
  estimatedCost: z.number().min(0).optional(),
  actualCost: z.number().min(0).optional(),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
})

// Chat Message Schema
export const ChatMessageSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  userId: z.string().uuid(),
  content: z.string().min(1, 'Message content is required'),
  type: z.enum(['text', 'image', 'file', 'location', 'system']).default('text'),
  attachments: z.array(z.object({
    id: z.string().uuid(),
    filename: z.string(),
    url: z.string().url(),
    size: z.number().min(0),
    mimeType: z.string()
  })).default([]),
  replyTo: z.string().uuid().optional(),
  isEdited: z.boolean().default(false),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
})

// Weather Schema
export const WeatherSchema = z.object({
  id: z.string().uuid(),
  locationId: z.string().uuid(),
  date: z.date(),
  temperature: z.object({
    min: z.number(),
    max: z.number(),
    current: z.number().optional()
  }),
  humidity: z.number().min(0).max(100),
  windSpeed: z.number().min(0),
  windDirection: z.number().min(0).max(360),
  precipitation: z.object({
    probability: z.number().min(0).max(100),
    amount: z.number().min(0).optional()
  }),
  conditions: z.enum(['sunny', 'cloudy', 'partly-cloudy', 'rainy', 'stormy', 'snowy', 'foggy']),
  uvIndex: z.number().min(0).max(11),
  visibility: z.number().min(0),
  pressure: z.number().min(0),
  sunrise: z.string().optional(),
  sunset: z.string().optional(),
  createdAt: z.date().default(() => new Date())
})

// Calendar Event Schema
export const CalendarEventSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  title: z.string().min(1, 'Event title is required'),
  description: z.string().optional(),
  startDate: z.date(),
  endDate: z.date(),
  isAllDay: z.boolean().default(false),
  location: z.string().optional(),
  attendees: z.array(z.string().uuid()).default([]),
  reminders: z.array(z.object({
    type: z.enum(['email', 'push', 'sms']),
    minutesBefore: z.number().min(0)
  })).default([]),
  recurrence: z.object({
    frequency: z.enum(['daily', 'weekly', 'monthly', 'yearly']),
    interval: z.number().min(1),
    endDate: z.date().optional(),
    count: z.number().min(1).optional()
  }).optional(),
  createdBy: z.string().uuid(),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
}).refine(data => data.endDate >= data.startDate, {
  message: 'End date must be after start date',
  path: ['endDate']
})

// User Profile Schema
export const UserProfileSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  firstName: z.string().min(1, 'First name is required'),
  lastName: z.string().min(1, 'Last name is required'),
  username: z.string().min(3, 'Username must be at least 3 characters'),
  avatar: z.string().url().optional(),
  bio: z.string().optional(),
  phone: z.string().optional(),
  emergencyContact: z.object({
    name: z.string(),
    phone: z.string(),
    relationship: z.string()
  }).optional(),
  preferences: z.object({
    notifications: z.object({
      email: z.boolean().default(true),
      push: z.boolean().default(true),
      sms: z.boolean().default(false)
    }),
    privacy: z.object({
      profileVisible: z.boolean().default(true),
      showEmail: z.boolean().default(false),
      showPhone: z.boolean().default(false)
    }),
    units: z.object({
      temperature: z.enum(['celsius', 'fahrenheit']).default('celsius'),
      distance: z.enum(['metric', 'imperial']).default('metric')
    })
  }).default({}),
  experience: z.object({
    level: z.enum(['beginner', 'intermediate', 'advanced', 'expert']).default('beginner'),
    specialties: z.array(z.string()).default([]),
    yearsExperience: z.number().min(0).optional()
  }).default({}),
  createdAt: z.date().default(() => new Date()),
  updatedAt: z.date().default(() => new Date())
})

// Invitation Schema
export const InvitationSchema = z.object({
  id: z.string().uuid(),
  tripId: z.string().uuid(),
  inviterId: z.string().uuid(),
  inviteeEmail: z.string().email(),
  inviteeId: z.string().uuid().optional(),
  status: z.enum(['pending', 'accepted', 'declined', 'expired']).default('pending'),
  message: z.string().optional(),
  expiresAt: z.date(),
  sentAt: z.date().default(() => new Date()),
  respondedAt: z.date().optional()
})

// Type exports
export type Location = z.infer<typeof LocationSchema>
export type Trip = z.infer<typeof TripSchema>
export type Participant = z.infer<typeof ParticipantSchema>
export type Task = z.infer<typeof TaskSchema>
export type Meal = z.infer<typeof MealSchema>
export type ChatMessage = z.infer<typeof ChatMessageSchema>
export type Weather = z.infer<typeof WeatherSchema>
export type CalendarEvent = z.infer<typeof CalendarEventSchema>
export type UserProfile = z.infer<typeof UserProfileSchema>
export type Invitation = z.infer<typeof InvitationSchema>

// Validation helper functions
export const validateLocation = (data: unknown): Location => {
  return LocationSchema.parse(data)
}

export const validateTrip = (data: unknown): Trip => {
  return TripSchema.parse(data)
}

export const validateParticipant = (data: unknown): Participant => {
  return ParticipantSchema.parse(data)
}

export const validateTask = (data: unknown): Task => {
  return TaskSchema.parse(data)
}

export const validateMeal = (data: unknown): Meal => {
  return MealSchema.parse(data)
}

export const validateChatMessage = (data: unknown): ChatMessage => {
  return ChatMessageSchema.parse(data)
}

export const validateWeather = (data: unknown): Weather => {
  return WeatherSchema.parse(data)
}

export const validateCalendarEvent = (data: unknown): CalendarEvent => {
  return CalendarEventSchema.parse(data)
}

export const validateUserProfile = (data: unknown): UserProfile => {
  return UserProfileSchema.parse(data)
}

export const validateInvitation = (data: unknown): Invitation => {
  return InvitationSchema.parse(data)
}

// Partial validation for updates
export const PartialLocationSchema = LocationSchema.partial()
export const PartialTripSchema = TripSchema.partial()
export const PartialTaskSchema = TaskSchema.partial()
export const PartialMealSchema = MealSchema.partial()
export const PartialUserProfileSchema = UserProfileSchema.partial()

export type PartialLocation = z.infer<typeof PartialLocationSchema>
export type PartialTrip = z.infer<typeof PartialTripSchema>
export type PartialTask = z.infer<typeof PartialTaskSchema>
export type PartialMeal = z.infer<typeof PartialMealSchema>
export type PartialUserProfile = z.infer<typeof PartialUserProfileSchema>

