    name: string
    phone: string
    relationship: string
  }
  vehicleInfo: {
    make: string
    model: string
    year: string
    capacity: number
  }
  skills: string[]
  preferences: {
    difficulty: 'beginner' | 'intermediate' | 'advanced'
    terrain: string[]
    notifications: boolean
  }
}

interface UserProfilePageProps {
  userId?: string
  onProfileUpdate?: (profile: UserProfile) => void
}

export function UserProfilePage({
  userId = 'user-1',
  onProfileUpdate = () => console.log('Profile updated')
}: UserProfilePageProps = {}) {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE)
  const [isEditing, setIsEditing] = useState(false)
  const [editedProfile, setEditedProfile] = useState<UserProfile>(DEFAULT_PROFILE)
  const [activeTab, setActiveTab] = useState<'profile' | 'vehicle' | 'preferences'>('profile')
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    setIsLoading(true)
    setTimeout(() => {
      setProfile(DEFAULT_PROFILE)
      setEditedProfile(DEFAULT_PROFILE)
      setIsLoading(false)
    }, 1000)
  }, [userId])

  const handleSave = async () => {
    setIsLoading(true)
    await new Promise(resolve => setTimeout(resolve, 1000))
    setProfile(editedProfile)
    setIsEditing(false)
    setIsLoading(false)
    onProfileUpdate(editedProfile)
  }

  const handleCancel = () => {
    setEditedProfile(profile)
    setIsEditing(false)
  }

  const updateField = (field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const updateNestedField = (parent: string, field: string, value: any) => {
    setEditedProfile(prev => ({
      ...prev,
      [parent]: {
        ...prev[parent as keyof UserProfile],
        [field]: value
      }
    }))
  }

  if (isLoading && !profile.id) {
    return <ProfileSkeleton />
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-lg hover:shadow-xl transition-all duration-300">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
            <div className="relative">
              <div className="w-20 h-20 bg-gradient-warm rounded-full flex items-center justify-center text-primaryForeground text-2xl font-bold">
                {profile.name.split(' ').map(n => n[0]).join('')}
              </div>
              <button 
                className="absolute -bottom-1 -right-1 w-8 h-8 bg-primary rounded-full flex items-center justify-center text-primaryForeground hover:bg-primary/90 hover:scale-105 active:scale-95 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                aria-label="Change profile picture"
              >
                <Camera className="w-4 h-4" />
              </button>
            </div>

            <div className="flex-1">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                  <h1 className="text-2xl font-bold text-foreground dark:text-foreground">{profile.name}</h1>
                  <p className="text-mutedForeground dark:text-mutedForeground flex items-center gap-2 mt-1">
                    <MapPin className="w-4 h-4" />
                    {profile.location}
                  </p>
                </div>

                <div className="flex gap-2">
                  {!isEditing ? (
                    <button
                      onClick={() => setIsEditing(true)}
                      className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                      aria-label="Edit profile"
                    >
                      <Edit3 className="w-4 h-4" />
                      Edit Profile
                    </button>
                  ) : (
                    <div className="flex gap-2">
                      <button
                        onClick={handleSave}
                        disabled={isLoading}
                        className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        aria-label="Save changes"
                      >
                        <Save className="w-4 h-4" />
                        {isLoading ? 'Saving...' : 'Save'}
                      </button>
                      <button
                        onClick={handleCancel}
                        className="px-4 py-2 bg-muted text-mutedForeground rounded-lg hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        aria-label="Cancel editing"
                      >
                        <X className="w-4 h-4" />
                        Cancel
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6 pt-6 border-t border-border dark:border-border">
            <div className="text-center">
              <div className="text-2xl font-bold text-primary">{profile.tripsCompleted}</div>
              <div className="text-sm text-mutedForeground dark:text-mutedForeground">Trips Completed</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-primary">{profile.favoriteTrails.length}</div>
              <div className="text-sm text-mutedForeground dark:text-mutedForeground">Favorite Trails</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-primary">{profile.skills.length}</div>
              <div className="text-sm text-mutedForeground dark:text-mutedForeground">Skills</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-primary">
                {new Date().getFullYear() - new Date(profile.joinDate).getFullYear()}
              </div>
              <div className="text-sm text-mutedForeground dark:text-mutedForeground">Years Active</div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 mb-6 bg-surface dark:bg-surface p-1 rounded-lg border border-border dark:border-border">
          {[
            { id: 'profile', label: 'Profile', icon: User },
            { id: 'vehicle', label: 'Vehicle', icon: Mountain },
            { id: 'preferences', label: 'Preferences', icon: Settings }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-md font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                activeTab === tab.id
                  ? 'bg-primary text-primaryForeground shadow-sm'
                  : 'text-mutedForeground hover:text-foreground hover:bg-muted'
              }`}
              aria-label={`Switch to ${tab.label} tab`}
            >
              <tab.icon className="w-4 h-4" />
              <span className="hidden sm:inline">{tab.label}</span>
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="space-y-6">
          {activeTab === 'profile' && (
            <ProfileTab
              profile={isEditing ? editedProfile : profile}
              isEditing={isEditing}
              onUpdate={updateField}
              onUpdateNested={updateNestedField}
            />
          )}

          {activeTab === 'vehicle' && (
            <VehicleTab
              profile={isEditing ? editedProfile : profile}
              isEditing={isEditing}
              onUpdate={updateNestedField}
            />
          )}

          {activeTab === 'preferences' && (
            <PreferencesTab
              profile={isEditing ? editedProfile : profile}
              isEditing={isEditing}
              onUpdate={updateNestedField}
            />
          )}
        </div>
      </div>
    </div>
  )
}

