function getNotificationDescription(key: string): string {
  const descriptions: Record<string, string> = {
    tripInvites: 'Get notified when you\'re invited to trips',
    taskAssignments: 'Receive alerts for new task assignments',
    weatherAlerts: 'Weather updates for your trips',
    groupMessages: 'New messages in group chats',
    reminderNotifications: 'Trip and task reminders',
    emailNotifications: 'Receive notifications via email',
    pushNotifications: 'Push notifications on your device'
  }
  return descriptions[key] || 'Notification setting'
}

function getPrivacyDescription(option: string): string {
  const descriptions: Record<string, string> = {
    public: 'Anyone can see your profile',
    friends: 'Only your friends can see your profile',
    private: 'Only you can see your profile'
  }
  return descriptions[option] || ''
}

function getPrivacySettingDescription(key: string): string {
  const descriptions: Record<string, string> = {
    locationSharing: 'Share your location during trips',
    activityHistory: 'Show your trip history to others',
    contactInfo: 'Allow others to see your contact information'
  }
  return descriptions[key] || 'Privacy setting'
}

