'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, MapPin, Users, Send, Check, X, Mail, Phone, AlertCircle } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
  phone?: string
  avatar?: string
  status: 'pending' | 'accepted' | 'declined'
  rsvpDate?: string
}

interface TripDetails {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  description: string
  organizer: string
}

interface CalendarInvitationsProps {
  tripDetails?: TripDetails
  members?: TripMember[]
  onSendInvites?: (memberIds: string[]) => Promise<void>
  onResendInvite?: (memberId: string) => Promise<void>
  onRemoveMember?: (memberId: string) => void
}

export function CalendarInvitations({
  tripDetails = DEFAULT_TRIP,
  members = DEFAULT_MEMBERS,
  onSendInvites = async () => console.log('Sending invites'),
  onResendInvite = async () => console.log('Resending invite'),
  onRemoveMember = () => console.log('Removing member')
}: CalendarInvitationsProps = {}) {
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [isSending, setIsSending] = useState(false)
  const [sentInvites, setSentInvites] = useState<Set<string>>(new Set())
  const [customMessage, setCustomMessage] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const pendingMembers = members.filter(m => m.status === 'pending')
  const acceptedMembers = members.filter(m => m.status === 'accepted')
  const declinedMembers = members.filter(m => m.status === 'declined')

  const handleSelectMember = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  const handleSendInvites = async () => {
    if (selectedMembers.length === 0) return

    setIsSending(true)
    setError(null)
    try {
      await onSendInvites(selectedMembers)
      setSentInvites(prev => new Set([...prev, ...selectedMembers]))
      setSelectedMembers([])
    } catch (error) {
      setError('Failed to send invites. Please try again.')
      console.error('Failed to send invites:', error)
    } finally {
      setIsSending(false)
    }
  }

  const handleResendInvite = async (memberId: string) => {
    try {
      await onResendInvite(memberId)
      setSentInvites(prev => new Set([...prev, memberId]))
    } catch (error) {
      setError('Failed to resend invite. Please try again.')
      console.error('Failed to resend invite:', error)
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    })
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'accepted': return 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800'
      case 'declined': return 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800'
      default: return 'bg-yellow-50 text-yellow-700 border-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:border-yellow-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'accepted': return <Check className="w-3 h-3" />
      case 'declined': return <X className="w-3 h-3" />
      default: return <Clock className="w-3 h-3" />
    }
  }

  const LoadingSkeleton = () => (
    <div className="space-y-4 animate-pulse">
      {[...Array(3)].map((_, i) => (
        <div key={i} className="flex items-center gap-3 p-4 bg-muted dark:bg-muted rounded-lg">
          <div className="w-10 h-10 bg-border dark:bg-border rounded-full"></div>
          <div className="flex-1 space-y-2">
            <div className="h-4 bg-border dark:bg-border rounded w-3/4"></div>
            <div className="h-3 bg-border dark:bg-border rounded w-1/2"></div>
          </div>
        </div>
      ))}
    </div>
  )

  const EmptyState = ({ title, description, icon: Icon }: { title: string, description: string, icon: any }) => (
    <div className="text-center py-12">
      <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
        <Icon className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
      </div>
      <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">{title}</h3>
      <p className="text-mutedForeground dark:text-mutedForeground text-sm">{description}</p>
    </div>
  )

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto p-6 space-y-6">
        {/* Trip Overview */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2">{tripDetails.title}</h1>
              <div className="flex items-center gap-6 text-mutedForeground dark:text-mutedForeground text-sm">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4" />
                  <span>{tripDetails.location}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" />
                  <span>{formatDate(tripDetails.startDate)} - {formatDate(tripDetails.endDate)}</span>
                </div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-sm text-mutedForeground dark:text-mutedForeground mb-1">Organized by</div>
              <div className="text-foreground dark:text-foreground font-medium">{tripDetails.organizer}</div>
            </div>
          </div>

          {tripDetails.description && (
            <p className="text-mutedForeground dark:text-mutedForeground text-sm leading-relaxed">{tripDetails.description}</p>
          )}
        </div>

        {/* Error State */}
        {error && (
          <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 text-red-600 dark:text-red-400" />
              <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
            </div>
          </div>
        )}

        {/* Send Invitations */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h2 className="text-2xl font-bold text-foreground dark:text-foreground mb-6 flex items-center gap-3">
            <Send className="w-6 h-6 text-primary dark:text-primary" />
            Send Calendar Invitations
          </h2>

          {/* Custom Message */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
              Custom Message (Optional)
            </label>
            <textarea
              value={customMessage}
              onChange={(e) => setCustomMessage(e.target.value)}
              placeholder="Add a personal message to the invitation..."
              className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 resize-none"
              rows={3}
            />
          </div>

          {/* Member Selection */}
          <div className="space-y-4 mb-6">
            <h3 className="text-lg font-semibold text-foreground dark:text-foreground">Select Members</h3>
            {isLoading ? (
              <LoadingSkeleton />
            ) : members.length === 0 ? (
              <EmptyState 
                title="No members added yet" 
                description="Add members to your trip to send calendar invitations"
                icon={Users}
              />
            ) : (
              <div className="grid gap-3">
                {members.map((member) => (
                  <div
                    key={member.id}
                    className={`flex items-center justify-between p-4 rounded-lg border transition-all duration-200 cursor-pointer hover:shadow-md hover:-translate-y-0.5 ${
                      selectedMembers.includes(member.id)
                        ? 'bg-primary/10 dark:bg-primary/10 border-primary/50 dark:border-primary/50'
                        : 'bg-background dark:bg-background border-border dark:border-border hover:border-border/80 dark:hover:border-border/80'
                    }`}
                    onClick={() => handleSelectMember(member.id)}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary dark:from-primary dark:to-secondary rounded-full flex items-center justify-center text-primaryForeground dark:text-primaryForeground font-semibold">
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <div className="text-foreground dark:text-foreground font-medium">{member.name}</div>
                        <div className="text-mutedForeground dark:text-mutedForeground text-sm flex items-center gap-4">
                          <span className="flex items-center gap-1">
                            <Mail className="w-3 h-3" />
                            {member.email}
                          </span>
                          {member.phone && (
                            <span className="flex items-center gap-1">
                              <Phone className="w-3 h-3" />
                              {member.phone}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border flex items-center gap-1 ${getStatusColor(member.status)}`}>
                        {getStatusIcon(member.status)}
                        {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                      </span>
                      {sentInvites.has(member.id) && (
                        <span className="text-green-600 dark:text-green-400 text-xs font-medium">Sent</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Send Button */}
          <button
            onClick={handleSendInvites}
            disabled={selectedMembers.length === 0 || isSending}
            className="w-full px-6 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted dark:disabled:bg-muted disabled:text-mutedForeground dark:disabled:text-mutedForeground disabled:cursor-not-allowed transition-all duration-150 font-medium shadow-sm hover:shadow-md flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
            aria-label={`Send calendar invitations to ${selectedMembers.length} selected members`}
          >
            {isSending ? (
              <>
                <div className="w-4 h-4 border-2 border-primaryForeground/30 dark:border-primaryForeground/30 border-t-primaryForeground dark:border-t-primaryForeground rounded-full animate-spin" />
                Sending Invitations...
              </>
            ) : (
              <>
                <Send className="w-4 h-4" />
                Send Calendar Invitations ({selectedMembers.length})
              </>
            )}
          </button>
        </div>

        {/* RSVP Status */}
        <div className="grid md:grid-cols-3 gap-6">
          {/* Accepted */}
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
            <h3 className="text-lg font-semibold text-green-600 dark:text-green-400 mb-4 flex items-center gap-2">
              <Check className="w-5 h-5" />
              Accepted ({acceptedMembers.length})
            </h3>
            <div className="space-y-3">
              {acceptedMembers.length === 0 ? (
                <div className="text-mutedForeground dark:text-mutedForeground text-sm text-center py-8">No acceptances yet</div>
              ) : (
                acceptedMembers.map((member) => (
                  <div key={member.id} className="flex items-center gap-3 p-3 bg-green-50 dark:bg-green-900/20 rounded-lg border border-green-200 dark:border-green-800 hover:shadow-sm transition-all duration-200">
                    <div className="w-8 h-8 bg-green-600 dark:bg-green-500 rounded-full flex items-center justify-center text-white text-sm font-semibold">
                      {member.name.charAt(0).toUpperCase()}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-foreground dark:text-foreground font-medium truncate">{member.name}</div>
                      {member.rsvpDate && (
                        <div className="text-green-600 dark:text-green-400 text-xs">
                          RSVP'd {new Date(member.rsvpDate).toLocaleDateString()}
                        </div>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Pending */}
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
            <h3 className="text-lg font-semibold text-yellow-600 dark:text-yellow-400 mb-4 flex items-center gap-2">
              <Clock className="w-5 h-5" />
              Pending ({pendingMembers.length})
            </h3>
            <div className="space-y-3">
              {pendingMembers.length === 0 ? (
                <div className="text-mutedForeground dark:text-mutedForeground text-sm text-center py-8">No pending invites</div>
              ) : (
                pendingMembers.map((member) => (
                  <div key={member.id} className="flex items-center justify-between p-3 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg border border-yellow-200 dark:border-yellow-800 hover:shadow-sm transition-all duration-200">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-yellow-600 dark:bg-yellow-500 rounded-full flex items-center justify-center text-white text-sm font-semibold">
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="text-foreground dark:text-foreground font-medium">{member.name}</div>
                    </div>
                    <button
                      onClick={() => handleResendInvite(member.id)}
                      className="px-3 py-1 bg-yellow-100 dark:bg-yellow-900/40 text-yellow-700 dark:text-yellow-300 rounded text-xs hover:bg-yellow-200 dark:hover:bg-yellow-900/60 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-yellow-500/50 dark:focus:ring-yellow-400/50"
                      aria-label={`Resend invitation to ${member.name}`}
                    >
                      Resend
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Declined */}
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
            <h3 className="text-lg font-semibold text-red-600 dark:text-red-400 mb-4 flex items-center gap-2">
              <X className="w-5 h-5" />
              Declined ({declinedMembers.length})
            </h3>
            <div className="space-y-3">
              {declinedMembers.length === 0 ? (
                <div className="text-mutedForeground dark:text-mutedForeground text-sm text-center py-8">No declined invites</div>
              ) : (
                declinedMembers.map((member) => (
                  <div key={member.id} className="flex items-center justify-between p-3 bg-red-50 dark:bg-red-900/20 rounded-lg border border-red-200 dark:border-red-800 hover:shadow-sm transition-all duration-200">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-red-600 dark:bg-red-500 rounded-full flex items-center justify-center text-white text-sm font-semibold">
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="text-foreground dark:text-foreground font-medium">{member.name}</div>
                    </div>
                    <button
                      onClick={() => onRemoveMember(member.id)}
                      className="px-3 py-1 bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 rounded text-xs hover:bg-red-200 dark:hover:bg-red-900/60 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-red-500/50 dark:focus:ring-red-400/50"
                      aria-label={`Remove ${member.name} from trip`}
                    >
                      Remove
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* Summary Stats */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-6 flex items-center gap-3">
            <Users className="w-6 h-6 text-primary dark:text-primary" />
            Invitation Summary
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <div className="text-center">
              <div className="text-3xl font-bold text-foreground dark:text-foreground">{members.length}</div>
              <div className="text-mutedForeground dark:text-mutedForeground text-sm">Total Invited</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-green-600 dark:text-green-400">{acceptedMembers.length}</div>
              <div className="text-mutedForeground dark:text-mutedForeground text-sm">Accepted</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-yellow-600 dark:text-yellow-400">{pendingMembers.length}</div>
              <div className="text-mutedForeground dark:text-mutedForeground text-sm">Pending</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-red-600 dark:text-red-400">{declinedMembers.length}</div>
              <div className="text-mutedForeground dark:text-mutedForeground text-sm">Declined</div>
            </div>
          </div>

          {members.length > 0 && (
            <div className="mt-6 pt-6 border-t border-border dark:border-border">
              <div className="flex items-center justify-between text-sm mb-3">
                <span className="text-mutedForeground dark:text-mutedForeground">Response Rate</span>
                <span className="text-foreground dark:text-foreground font-medium">
                  {Math.round(((acceptedMembers.length + declinedMembers.length) / members.length) * 100)}%
                </span>
              </div>
              <div className="w-full bg-muted dark:bg-muted rounded-full h-2">
                <div 
                  className="bg-primary dark:bg-primary h-2 rounded-full transition-all duration-500"
                  style={{ width: `${(acceptedMembers.length / members.length) * 100}%` }}
                />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

