'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageSquare, Utensils, CheckCircle, Clock, AlertCircle, Navigation, Thermometer, Cloud, Sun, CloudRain } from 'lucide-react'

interface TripLocation {
  id: string
  name: string
  coordinates: { lat: number; lng: number }
  difficulty: 'Easy' | 'Moderate' | 'Difficult'
  terrain: string
  saved: boolean
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar: string
  status: 'confirmed' | 'pending' | 'declined'
}

interface Task {
  id: string
  title: string
  assignedTo: string
  category: 'food' | 'equipment' | 'logistics'
  completed: boolean
  dueDate: string
}

interface WeatherData {
  date: string
  temp: { high: number; low: number }
  condition: 'sunny' | 'cloudy' | 'rainy'
  precipitation: number
}

interface Meal {
  id: string
  name: string
  day: string
  time: 'breakfast' | 'lunch' | 'dinner'
  assignedTo: string
}

interface ChatMessage {
  id: string
  sender: string
  message: string
  timestamp: string
}

interface OffRoadTripPlannerProps {
  initialTrip?: any
  onSaveTrip?: (trip: any) => void
}

export function OffRoadTripPlanner({
  initialTrip,
  onSaveTrip = () => console.log('Trip saved')
}: OffRoadTripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('locations')
  const [selectedLocation, setSelectedLocation] = useState<TripLocation | null>(null)
  const [groupMembers, setGroupMembers] = useState<GroupMember[]>(DEFAULT_MEMBERS)
  const [tasks, setTasks] = useState<Task[]>(DEFAULT_TASKS)
  const [meals, setMeals] = useState<Meal[]>(DEFAULT_MEALS)
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>(DEFAULT_MESSAGES)
  const [newMessage, setNewMessage] = useState('')
  const [tripDates, setTripDates] = useState({ start: '', end: '' })
  const [isLoading, setIsLoading] = useState(false)

  const locations: TripLocation[] = [
    {
      id: '1',
      name: 'Moab Desert Trail',
      coordinates: { lat: 38.5733, lng: -109.5498 },
      difficulty: 'Moderate',
      terrain: 'Rocky desert, sand dunes',
      saved: true
    },
    {
      id: '2',
      name: 'Black Hills Backcountry',
      coordinates: { lat: 43.8791, lng: -103.4591 },
      difficulty: 'Difficult',
      terrain: 'Mountain trails, forest paths',
      saved: false
    },
    {
      id: '3',
      name: 'Rubicon Trail',
      coordinates: { lat: 39.0968, lng: -120.1430 },
      difficulty: 'Difficult',
      terrain: 'Granite rocks, steep climbs',
      saved: true
    }
  ]

  const weatherData: WeatherData[] = [
    { date: '2024-03-15', temp: { high: 75, low: 45 }, condition: 'sunny', precipitation: 0 },
    { date: '2024-03-16', temp: { high: 72, low: 42 }, condition: 'cloudy', precipitation: 10 },
    { date: '2024-03-17', temp: { high: 68, low: 40 }, condition: 'rainy', precipitation: 60 }
  ]

  const toggleLocationSave = (locationId: string) => {
    const location = locations.find(l => l.id === locationId)
    if (location) {
      location.saved = !location.saved
    }
  }

  const toggleTaskComplete = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const sendMessage = () => {
    if (newMessage.trim()) {
      const message: ChatMessage = {
        id: Date.now().toString(),
        sender: 'You',
        message: newMessage,
        timestamp: new Date().toLocaleTimeString()
      }
      setChatMessages(prev => [...prev, message])
      setNewMessage('')
    }
  }

  const updateMemberStatus = (memberId: string, status: 'confirmed' | 'pending' | 'declined') => {
    setGroupMembers(prev => prev.map(member =>
      member.id === memberId ? { ...member, status } : member
    ))
  }

  const getWeatherIcon = (condition: string) => {
    switch (condition) {
      case 'sunny': return <Sun className="w-5 h-5 text-yellow-500" />
      case 'cloudy': return <Cloud className="w-5 h-5 text-gray-500 dark:text-gray-400" />
      case 'rainy': return <CloudRain className="w-5 h-5 text-blue-500" />
      default: return <Sun className="w-5 h-5 text-yellow-500" />
    }
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800'
      case 'Moderate': return 'bg-yellow-50 text-yellow-700 border-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:border-yellow-800'
      case 'Difficult': return 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800'
      default: return 'bg-gray-50 text-gray-700 border-gray-200 dark:bg-gray-900/20 dark:text-gray-300 dark:border-gray-800'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800'
      case 'pending': return 'bg-yellow-50 text-yellow-700 border-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:border-yellow-800'
      case 'declined': return 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800'
      default: return 'bg-gray-50 text-gray-700 border-gray-200 dark:bg-gray-900/20 dark:text-gray-300 dark:border-gray-800'
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
