                      <button
                        onClick={() => toggleTaskComplete(task.id)}
                        className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all duration-150 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                          task.completed
                            ? 'bg-green-500 border-green-500 text-white'
                            : 'border-mutedForeground dark:border-mutedForeground hover:border-green-500'
                        }`}
                        aria-label={task.completed ? 'Mark as incomplete' : 'Mark as complete'}
                      >
                        {task.completed && <CheckCircle className="w-3 h-3" />}
                      </button>

                      <div className="flex-1">
                        <h3 className={`font-medium ${task.completed ? 'text-mutedForeground dark:text-mutedForeground line-through' : 'text-foreground dark:text-foreground'}`}>
                          {task.title}
                        </h3>
                        <div className="flex items-center gap-4 mt-1">
                          <span className="text-sm text-mutedForeground dark:text-mutedForeground">
                            Assigned to: {groupMembers.find(m => m.id === task.assignedTo)?.name || 'Unassigned'}
                          </span>
                          <span className="text-sm text-mutedForeground dark:text-mutedForeground">Due: {task.dueDate}</span>
                        </div>
                      </div>

                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        task.category === 'food' ? 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300' :
                        task.category === 'equipment' ? 'bg-purple-50 text-purple-700 dark:bg-purple-900/20 dark:text-purple-300' :
                        'bg-gray-50 text-gray-700 dark:bg-gray-900/20 dark:text-gray-300'
