                      {new Date(day.date).toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
                    </h3>
                    {getWeatherIcon(day.condition)}
                  </div>

                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-mutedForeground dark:text-mutedForeground">High</span>
                      <span className="text-foreground dark:text-foreground font-semibold">{day.temp.high}°F</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-mutedForeground dark:text-mutedForeground">Low</span>
                      <span className="text-foreground dark:text-foreground font-semibold">{day.temp.low}°F</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-mutedForeground dark:text-mutedForeground">Rain</span>
                      <span className="text-foreground dark:text-foreground font-semibold">{day.precipitation}%</span>
                    </div>
                  </div>

                  {day.precipitation > 50 && (
                    <div className="mt-4 p-3 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                      <div className="flex items-center gap-2">
                        <AlertCircle className="w-4 h-4 text-yellow-600 dark:text-yellow-400" />
                        <span className="text-yellow-700 dark:text-yellow-300 text-sm font-medium">High chance of rain</span>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Chat Tab */}
        {activeTab === 'chat' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-foreground dark:text-foreground">Group Chat</h2>

            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border h-96 flex flex-col shadow-sm">
              <div className="flex-1 p-4 overflow-y-auto space-y-3">
                {chatMessages.length === 0 ? (
                  <div className="text-center py-8">
                    <div className="w-12 h-12 bg-muted dark:bg-muted rounded-full mx-auto mb-3 flex items-center justify-center">
                      <MessageSquare className="w-6 h-6 text-mutedForeground dark:text-mutedForeground" />
                    </div>
                    <p className="text-mutedForeground dark:text-mutedForeground text-sm">No messages yet. Start the conversation!</p>
                  </div>
                ) : (
                  chatMessages.map(message => (
                    <div key={message.id} className="flex gap-3">
                      <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-full flex items-center justify-center text-primaryForeground dark:text-primaryForeground text-sm font-semibold">
                        {message.sender.charAt(0)}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="font-medium text-foreground dark:text-foreground text-sm">{message.sender}</span>
                          <span className="text-xs text-mutedForeground dark:text-mutedForeground">{message.timestamp}</span>
                        </div>
                        <p className="text-foreground dark:text-foreground text-sm">{message.message}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>

              <div className="p-4 border-t border-border dark:border-border">
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
                    placeholder="Type a message..."
                    className="flex-1 px-3 py-2 bg-muted dark:bg-muted border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                    aria-label="Type a message"
                  />
                  <button
                    onClick={sendMessage}
                    disabled={!newMessage.trim()}
                    className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                    aria-label="Send message"
                  >
                    Send
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

