'use client'

import { createContext, useContext, useEffect, useState } from 'react'
import { User, Session, AuthError } from '@supabase/supabase-js'
import { supabase } from '@/lib/supabase-client'
import { Shield, AlertCircle, Loader2 } from 'lucide-react'

interface AuthContextType {
  user: User | null
  session: Session | null
  loading: boolean
  signIn: (email: string, password: string) => Promise<{ error: AuthError | null }>
  signUp: (email: string, password: string) => Promise<{ error: AuthError | null }>
  signOut: () => Promise<{ error: AuthError | null }>
  resetPassword: (email: string) => Promise<{ error: AuthError | null }>
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

interface SupabaseAuthProviderProps {
  children: React.ReactNode
  fallback?: React.ReactNode
  redirectTo?: string
}

export function SupabaseAuthProvider({
  children,
  fallback,
  redirectTo = '/dashboard'
}: SupabaseAuthProviderProps) {
  const [user, setUser] = useState<User | null>(null)
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const getInitialSession = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession()
        if (error) {
          console.error('Error getting session:', error)
          setError('Failed to authenticate')
        } else {
          setSession(session)
          setUser(session?.user ?? null)
        }
      } catch (err) {
        console.error('Session error:', err)
        setError('Authentication error')
      } finally {
        setLoading(false)
      }
    }

    getInitialSession()

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        setSession(session)
        setUser(session?.user ?? null)
        setLoading(false)
        setError(null)

        if (event === 'SIGNED_IN' && redirectTo) {
          window.location.href = redirectTo
        }
      }
    )

    return () => subscription.unsubscribe()
  }, [redirectTo])

  const signIn = async (email: string, password: string) => {
    setLoading(true)
    setError(null)

    const { error } = await supabase.auth.signInWithPassword({
      email,
      password
    })

    setLoading(false)

    if (error) {
      setError(error.message)
    }

    return { error }
  }

  const signUp = async (email: string, password: string) => {
    setLoading(true)
    setError(null)

    const { error } = await supabase.auth.signUp({
      email,
      password
    })

    setLoading(false)

    if (error) {
      setError(error.message)
    }

    return { error }
  }

  const signOut = async () => {
    setLoading(true)
    setError(null)

    const { error } = await supabase.auth.signOut()

    setLoading(false)

    if (error) {
      setError(error.message)
    }

    return { error }
  }

  const resetPassword = async (email: string) => {
    setLoading(true)
    setError(null)

    const { error } = await supabase.auth.resetPasswordForEmail(email)

    setLoading(false)

    if (error) {
      setError(error.message)
    }

    return { error }
  }

  const value: AuthContextType = {
    user,
    session,
    loading,
    signIn,
    signUp,
    signOut,
    resetPassword
  }

  if (loading && !fallback) {
    return (
      <div className="min-h-screen bg-background dark:bg-background flex items-center justify-center p-4 font-sans">
        <div className="bg-surface dark:bg-surface rounded-xl shadow-lg p-8 flex flex-col items-center gap-4 max-w-sm w-full border border-border dark:border-border">
          <div className="p-3 bg-muted dark:bg-muted rounded-full">
            <Shield className="w-6 h-6 text-primary dark:text-primary" />
          </div>
          <div className="flex items-center gap-2">
            <Loader2 className="w-4 h-4 animate-spin text-primary dark:text-primary" />
            <span className="text-foreground dark:text-foreground font-medium">Authenticating...</span>
          </div>
          <p className="text-sm text-mutedForeground dark:text-mutedForeground text-center">
            Setting up your adventure planning session
          </p>
        </div>
      </div>
    )
  }

  if (loading && fallback) {
    return <>{fallback}</>
  }

  if (error) {
    return (
      <div className="min-h-screen bg-background dark:bg-background flex items-center justify-center p-4 font-sans">
        <div className="bg-surface dark:bg-surface rounded-xl shadow-lg p-8 flex flex-col items-center gap-4 max-w-sm w-full border border-border dark:border-border">
          <div className="p-3 bg-destructive/10 dark:bg-destructive/10 rounded-full">
            <AlertCircle className="w-6 h-6 text-destructive dark:text-destructive" />
          </div>
          <h3 className="text-lg font-semibold text-foreground dark:text-foreground">Authentication Error</h3>
          <p className="text-sm text-mutedForeground dark:text-mutedForeground text-center">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:bg-primary/90 dark:hover:bg-primary/90 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Retry authentication"
          >
            Try Again
          </button>
        </div>
      </div>
    )
  }

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth must be used within a SupabaseAuthProvider')
  }
  return context
}

