export default function SupabaseAuthProviderDemo() {
  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-2xl mx-auto py-8">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2">
            Off-Road Adventure Auth
          </h1>
          <p className="text-mutedForeground dark:text-mutedForeground">
