'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Mountain, Plus, X } from 'lucide-react'

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  tags: string[]
}

interface CreateTripFormProps {
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {},
  isLoading = false
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    name: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    tags: [],
    ...initialData
  })

  const [newTag, setNewTag] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const difficultyOptions = [
    { value: 'easy', label: 'Easy', color: 'bg-green-500 dark:bg-green-600' },
    { value: 'moderate', label: 'Moderate', color: 'bg-yellow-500 dark:bg-yellow-600' },
    { value: 'hard', label: 'Hard', color: 'bg-red-500 dark:bg-red-600' }
  ]

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      onSubmit(formData)
    }
  }

  const handleInputChange = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const addTag = () => {
    if (newTag.trim() && !formData.tags.includes(newTag.trim())) {
      handleInputChange('tags', [...formData.tags, newTag.trim()])
      setNewTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    handleInputChange('tags', formData.tags.filter(tag => tag !== tagToRemove))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      addTag()
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border shadow-lg overflow-hidden">
          <div className="bg-gradient-to-r from-primary to-accent p-6">
            <div className="flex items-center gap-3">
              <Mountain className="w-8 h-8 text-primaryForeground" />
              <div>
                <h1 className="text-2xl font-bold text-primaryForeground">Create New Trip</h1>
                <p className="text-primaryForeground/90 text-sm">Plan your next off-road adventure</p>
              </div>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Trip Name *
              </label>
              <input
                id="name"
                type="text"
                value={formData.name}
                onChange={(e) => handleInputChange('name', e.target.value)}
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                placeholder="Enter trip name"
                disabled={isLoading}
                aria-describedby={errors.name ? 'name-error' : undefined}
              />
              {errors.name && (
                <p id="name-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.name}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="location" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                <MapPin className="w-4 h-4 inline mr-1" />
                Location *
              </label>
              <input
                id="location"
                type="text"
                value={formData.location}
                onChange={(e) => handleInputChange('location', e.target.value)}
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                placeholder="Enter destination"
                disabled={isLoading}
                aria-describedby={errors.location ? 'location-error' : undefined}
              />
              {errors.location && (
                <p id="location-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="startDate" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  <Calendar className="w-4 h-4 inline mr-1" />
                  Start Date *
                </label>
                <input
                  id="startDate"
                  type="date"
                  value={formData.startDate}
                  onChange={(e) => handleInputChange('startDate', e.target.value)}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                  disabled={isLoading}
                  aria-describedby={errors.startDate ? 'startDate-error' : undefined}
                />
                {errors.startDate && (
                  <p id="startDate-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.startDate}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="endDate" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  <Clock className="w-4 h-4 inline mr-1" />
                  End Date *
                </label>
                <input
                  id="endDate"
                  type="date"
                  value={formData.endDate}
                  onChange={(e) => handleInputChange('endDate', e.target.value)}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                  disabled={isLoading}
                  aria-describedby={errors.endDate ? 'endDate-error' : undefined}
                />
                {errors.endDate && (
                  <p id="endDate-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.endDate}
                  </p>
                )}
              </div>
            </div>

            <div>
              <label htmlFor="maxParticipants" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                <Users className="w-4 h-4 inline mr-1" />
                Max Participants
              </label>
              <input
                id="maxParticipants"
                type="number"
                min="1"
                max="50"
                value={formData.maxParticipants}
                onChange={(e) => handleInputChange('maxParticipants', parseInt(e.target.value) || 1)}
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                disabled={isLoading}
                aria-describedby={errors.maxParticipants ? 'maxParticipants-error' : undefined}
              />
              {errors.maxParticipants && (
                <p id="maxParticipants-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.maxParticipants}
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-3">
                Difficulty Level
              </label>
              <div className="grid grid-cols-3 gap-3">
                {difficultyOptions.map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    onClick={() => handleInputChange('difficulty', option.value)}
                    className={`p-3 rounded-lg border-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                      formData.difficulty === option.value
                        ? 'border-ring bg-primary/10 dark:bg-primary/20'
                        : 'border-border dark:border-border bg-background dark:bg-background hover:border-mutedForeground dark:hover:border-mutedForeground'
                    }`}
                    disabled={isLoading}
                    aria-pressed={formData.difficulty === option.value}
                    aria-label={`Select ${option.label} difficulty`}
                  >
                    <div className={`w-3 h-3 rounded-full ${option.color} mx-auto mb-1`} />
                    <span className="text-sm font-medium text-foreground dark:text-foreground">{option.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label htmlFor="newTag" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Tags
              </label>
              <div className="flex gap-2 mb-3">
                <input
                  id="newTag"
                  type="text"
                  value={newTag}
                  onChange={(e) => setNewTag(e.target.value)}
                  onKeyPress={handleKeyPress}
                  className="flex-1 px-4 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 font-sans"
                  placeholder="Add a tag"
                  disabled={isLoading}
                />
                <button
                  type="button"
                  onClick={addTag}
                  className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring/50"
                  disabled={isLoading || !newTag.trim()}
                  aria-label="Add tag"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
              {formData.tags.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {formData.tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-3 py-1 bg-primary/10 dark:bg-primary/20 text-primary dark:text-primary rounded-full text-sm border border-primary/30 dark:border-primary/30"
                    >
                      {tag}
                      <button
                        type="button"
                        onClick={() => removeTag(tag)}
                        className="hover:text-primary/70 dark:hover:text-primary/70 transition-colors duration-150 focus:outline-none focus:ring-1 focus:ring-ring/50 rounded"
                        disabled={isLoading}
