            <button
              type="submit"
              disabled={isLoading}
              className="w-full px-6 py-4 bg-gradient-to-r from-primary to-accent text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium text-lg shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring/50"
            >
              {isLoading ? (
