  name: string
  email: string
  phone?: string
  status: 'pending' | 'accepted' | 'declined'
  avatar?: string
}

interface InviteMembersProps {
  tripId?: string
  existingMembers?: Member[]
  onInviteSent?: (invites: string[]) => void
  onMemberRemoved?: (memberId: string) => void
}

export function InviteMembers({
  tripId = 'trip-123',
  existingMembers = [],
  onInviteSent = () => console.log('Invites sent'),
  onMemberRemoved = () => console.log('Member removed')
}: InviteMembersProps = {}) {
  const [inviteMethod, setInviteMethod] = useState<'email' | 'phone' | 'link'>('email')
  const [inviteInput, setInviteInput] = useState('')
  const [pendingInvites, setPendingInvites] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const [members, setMembers] = useState<Member[]>(existingMembers.length > 0 ? existingMembers : DEFAULT_MEMBERS)

  const handleAddInvite = () => {
    setError('')

    if (!inviteInput.trim()) {
      setError('Please enter a valid input')
      return
    }

    if (inviteMethod === 'email' && !isValidEmail(inviteInput)) {
      setError('Please enter a valid email address')
      return
    }

    if (inviteMethod === 'phone' && !isValidPhone(inviteInput)) {
      setError('Please enter a valid phone number')
      return
    }

    if (pendingInvites.includes(inviteInput)) {
      setError('This contact has already been added')
      return
    }

    setPendingInvites([...pendingInvites, inviteInput])
    setInviteInput('')
    setSuccess('Contact added successfully!')
    setTimeout(() => setSuccess(''), 3000)
  }

  const handleRemoveInvite = (invite: string) => {
    setPendingInvites(pendingInvites.filter(i => i !== invite))
  }

  const handleSendInvites = async () => {
    if (pendingInvites.length === 0) return

    setIsLoading(true)
    setError('')

    try {
      await new Promise(resolve => setTimeout(resolve, 1500))
      onInviteSent(pendingInvites)
      setPendingInvites([])
      setSuccess(`${pendingInvites.length} invite(s) sent successfully!`)
      setTimeout(() => setSuccess(''), 5000)
    } catch (err) {
      setError('Failed to send invites. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleRemoveMember = (memberId: string) => {
    setMembers(members.filter(m => m.id !== memberId))
    onMemberRemoved(memberId)
  }

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(`https://app.com/join/${tripId}`)
      setSuccess('Link copied to clipboard!')
      setTimeout(() => setSuccess(''), 3000)
    } catch (err) {
      setError('Failed to copy link')
      setTimeout(() => setError(''), 3000)
    }
  }

  const getStatusColor = (status: Member['status']) => {
    switch (status) {
      case 'accepted': return 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800'
      case 'declined': return 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800'
      default: return 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800'
    }
  }

  const getStatusIcon = (status: Member['status']) => {
    switch (status) {
      case 'accepted': return <Check className="w-3 h-3" />
      case 'declined': return <X className="w-3 h-3" />
      default: return <Mail className="w-3 h-3" />
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-2xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-2">Invite Trip Members</h1>
          <p className="text-mutedForeground dark:text-mutedForeground">Add friends and family to your travel adventure</p>
        </div>

        {/* Success/Error Messages */}
        {success && (
          <div className="mb-6 rounded-lg bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 p-4">
            <p className="text-sm text-green-800 dark:text-green-200">{success}</p>
          </div>
        )}

        {error && (
          <div className="mb-6 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4">
            <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
          </div>
        )}

        {/* Invite Methods */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h2 className="text-xl font-semibold text-foreground dark:text-foreground mb-4">Send Invitations</h2>

          {/* Method Selection */}
          <div className="flex gap-2 mb-4">
            <button
              onClick={() => setInviteMethod('email')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                inviteMethod === 'email'
                  ? 'bg-primary text-primaryForeground shadow-md'
                  : 'bg-muted text-mutedForeground hover:bg-muted/80'
              }`}
              aria-label="Invite by email"
            >
              <Mail className="w-4 h-4" />
              Email
            </button>
            <button
              onClick={() => setInviteMethod('phone')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                inviteMethod === 'phone'
                  ? 'bg-primary text-primaryForeground shadow-md'
                  : 'bg-muted text-mutedForeground hover:bg-muted/80'
              }`}
              aria-label="Invite by SMS"
            >
              <Phone className="w-4 h-4" />
              SMS
            </button>
            <button
              onClick={() => setInviteMethod('link')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                inviteMethod === 'link'
                  ? 'bg-primary text-primaryForeground shadow-md'
                  : 'bg-muted text-mutedForeground hover:bg-muted/80'
              }`}
              aria-label="Share invitation link"
            >
              <MessageSquare className="w-4 h-4" />
              Share Link
            </button>
          </div>

          {/* Input Section */}
          {inviteMethod !== 'link' && (
            <div className="flex gap-2 mb-4">
              <input
                type={inviteMethod === 'email' ? 'email' : 'tel'}
                value={inviteInput}
                onChange={(e) => setInviteInput(e.target.value)}
                placeholder={
                  inviteMethod === 'email' 
                    ? 'Enter email address...' 
                    : 'Enter phone number...'
                }
                className="flex-1 px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                onKeyPress={(e) => e.key === 'Enter' && handleAddInvite()}
                aria-label={inviteMethod === 'email' ? 'Email address' : 'Phone number'}
              />
              <button
                onClick={handleAddInvite}
                className="px-4 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring/50"
                aria-label="Add invite"
              >
                <UserPlus className="w-5 h-5" />
              </button>
            </div>
          )}

          {/* Share Link */}
          {inviteMethod === 'link' && (
            <div className="bg-muted rounded-lg p-4 mb-4">
              <p className="text-mutedForeground text-sm mb-2">Share this link with your group:</p>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={`https://app.com/join/${tripId}`}
                  readOnly
                  className="flex-1 px-3 py-2 bg-background border border-border rounded text-foreground text-sm focus:outline-none focus:ring-2 focus:ring-ring/50"
                  aria-label="Invitation link"
                />
                <button
                  onClick={handleCopyLink}
                  className="px-3 py-2 bg-primary text-primaryForeground rounded hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-ring/50"
                  aria-label="Copy link"
                >
                  Copy
                </button>
              </div>
            </div>
          )}

          {/* Pending Invites */}
          {pendingInvites.length > 0 && (
            <div className="mb-4">
              <h3 className="text-foreground font-medium mb-2">Pending Invites ({pendingInvites.length})</h3>
              <div className="space-y-2">
                {pendingInvites.map((invite, index) => (
                  <div key={index} className="flex items-center justify-between bg-muted rounded-lg p-3 hover:bg-muted/80 transition-colors duration-200">
                    <span className="text-foreground">{invite}</span>
                    <button
                      onClick={() => handleRemoveInvite(invite)}
                      className="p-1 text-mutedForeground hover:text-destructive transition-colors duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring/50 rounded"
                      aria-label={`Remove ${invite}`}
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
              <button
                onClick={handleSendInvites}
                disabled={isLoading}
                className="w-full mt-4 px-4 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 disabled:bg-muted disabled:text-mutedForeground disabled:cursor-not-allowed hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-sm hover:shadow-md flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring/50"
                aria-label={`Send ${pendingInvites.length} invites`}
              >
                {isLoading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                    Sending...
                  </>
                ) : (
                  <>
                    <Send className="w-4 h-4" />
                    Send {pendingInvites.length} Invite{pendingInvites.length !== 1 ? 's' : ''}
                  </>
                )}
              </button>
            </div>
          )}
        </div>

        {/* Current Members */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h2 className="text-xl font-semibold text-foreground dark:text-foreground mb-4">
            Trip Members ({members.length})
          </h2>

          {members.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-mutedForeground" />
              </div>
              <h3 className="text-lg font-medium text-foreground mb-2">No members yet</h3>
              <p className="text-mutedForeground text-sm">Start by inviting your travel companions</p>
            </div>
          ) : (
            <div className="space-y-3">
              {members.map((member) => (
                <div key={member.id} className="flex items-center justify-between bg-muted rounded-lg p-4 hover:bg-muted/80 hover:-translate-y-0.5 hover:shadow-lg transition-all duration-300">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center text-primaryForeground font-medium">
                      {member.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <h3 className="text-foreground font-medium">{member.name}</h3>
                      <p className="text-mutedForeground text-sm">{member.email}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className={`px-2 py-1 rounded-full text-xs font-medium border flex items-center gap-1 ${getStatusColor(member.status)}`}>
                      {getStatusIcon(member.status)}
                      {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                    </span>

                    {member.status === 'pending' && (
                      <button
                        onClick={() => handleRemoveMember(member.id)}
                        className="p-1 text-mutedForeground hover:text-destructive transition-colors duration-200 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring/50 rounded"
                        aria-label={`Remove ${member.name}`}
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

const isValidEmail = (email: string): boolean => {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

const isValidPhone = (phone: string): boolean => {
  return /^\+?[\d\s\-\(\)]{10,}$/.test(phone)
}

