}

interface GroupChatProps {
  tripId?: string
  messages?: Message[]
  currentUserId?: string
  onSendMessage?: (content: string, type?: Message['type'], metadata?: Message['metadata']) => void
  onLocationShare?: () => void
  onTaskCreate?: () => void
}

