export function GroupChat({
  tripId = 'trip-123',
  messages = DEFAULT_MESSAGES,
  currentUserId = 'user1',
  onSendMessage = (content, type, metadata) => console.log('Send message:', { content, type, metadata }),
  onLocationShare = () => console.log('Share location'),
  onTaskCreate = () => console.log('Create task')
}: GroupChatProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    onSendMessage(newMessage.trim())
    setNewMessage('')
    inputRef.current?.focus()
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.toDateString() === today.toDateString()) {
      return 'Today'
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    } else {
      return new Intl.DateTimeFormat('en-US', {
        month: 'short',
        day: 'numeric'
      }).format(date)
    }
  }

  const renderMessage = (message: Message, index: number) => {
    const isCurrentUser = message.userId === currentUserId
    const showAvatar = index === 0 || messages[index - 1].userId !== message.userId
    const showDate = index === 0 || formatDate(message.timestamp) !== formatDate(messages[index - 1].timestamp)

    return (
      <div key={message.id} className="space-y-2">
        {showDate && (
          <div className="flex justify-center py-2">
            <span className="px-3 py-1 bg-muted text-mutedForeground dark:bg-muted dark:text-mutedForeground text-xs font-medium rounded-full">
              {formatDate(message.timestamp)}
            </span>
          </div>
        )}

        <div className={`flex gap-3 ${isCurrentUser ? 'flex-row-reverse' : 'flex-row'}`}>
          {showAvatar && !isCurrentUser && (
            <div className="w-8 h-8 bg-primary text-primaryForeground dark:bg-primary dark:text-primaryForeground rounded-full flex items-center justify-center text-sm font-semibold flex-shrink-0 transition-all duration-150 hover:scale-105">
              {message.userAvatar}
            </div>
          )}

          <div className={`flex flex-col max-w-[280px] sm:max-w-sm ${isCurrentUser ? 'items-end' : 'items-start'}`}>
            {showAvatar && !isCurrentUser && (
              <span className="text-xs text-mutedForeground dark:text-mutedForeground font-medium mb-1 px-1">
                {message.userName}
              </span>
            )}

            <div className={`relative px-4 py-2 rounded-2xl transition-all duration-200 hover:shadow-md ${
              message.type === 'system'
                ? 'bg-muted text-mutedForeground dark:bg-muted dark:text-mutedForeground border border-border dark:border-border'
                : isCurrentUser
                ? 'bg-primary text-primaryForeground dark:bg-primary dark:text-primaryForeground shadow-sm'
                : 'bg-surface text-foreground dark:bg-surface dark:text-foreground border border-border dark:border-border shadow-sm'
            }`}>
              {message.type === 'location' && message.metadata?.location && (
                <div className="flex items-center gap-2 mb-2 p-2 bg-white/20 dark:bg-black/20 rounded-lg">
                  <MapPin className="w-4 h-4" />
                  <span className="text-sm font-medium">{message.metadata.location.name}</span>
                </div>
              )}

              {message.type === 'task' && message.metadata?.task && (
                <div className="flex items-center gap-2 mb-2 p-2 bg-white/20 dark:bg-black/20 rounded-lg">
                  <Calendar className="w-4 h-4" />
                  <div className="text-sm">
                    <div className="font-medium">{message.metadata.task.title}</div>
                    <div className="text-xs opacity-80">Due: {message.metadata.task.dueDate}</div>
                  </div>
                </div>
              )}

              <p className="text-sm leading-relaxed">{message.content}</p>
            </div>

            <span className={`text-xs text-mutedForeground dark:text-mutedForeground mt-1 px-1 ${isCurrentUser ? 'text-right' : 'text-left'}`}>
              {formatTime(message.timestamp)}
            </span>
          </div>

          {showAvatar && isCurrentUser && (
            <div className="w-8 h-8 bg-primary text-primaryForeground dark:bg-primary dark:text-primaryForeground rounded-full flex items-center justify-center text-sm font-semibold flex-shrink-0 transition-all duration-150 hover:scale-105">
              {message.userAvatar}
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-background dark:bg-background font-sans">
      <div className="flex items-center justify-between p-4 border-b border-border dark:border-border bg-surface dark:bg-surface sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-primary text-primaryForeground dark:bg-primary dark:text-primaryForeground rounded-full flex items-center justify-center transition-all duration-150 hover:scale-105">
            <Users className="w-5 h-5" />
          </div>
          <div>
            <h2 className="font-semibold text-foreground dark:text-foreground">Trip Chat</h2>
            <p className="text-sm text-mutedForeground dark:text-mutedForeground">5 members</p>
          </div>
        </div>

        <button
          className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-150 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
          aria-label="More options"
        >
          <MoreVertical className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No messages yet</h3>
            <p className="text-mutedForeground dark:text-mutedForeground text-sm">Start the conversation with your travel group</p>
          </div>
        ) : (
          messages.map((message, index) => renderMessage(message, index))
        )}

        {isTyping && (
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full flex items-center justify-center">
              <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-pulse" />
            </div>
            <div className="bg-surface dark:bg-surface border border-border dark:border-border px-4 py-2 rounded-2xl shadow-sm">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                <div className="w-2 h-2 bg-mutedForeground dark:bg-mutedForeground rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 border-t border-border dark:border-border bg-surface dark:bg-surface">
        <div className="flex items-end gap-3">
          <div className="flex gap-2">
            <button
              onClick={onLocationShare}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
              aria-label="Share location"
            >
              <MapPin className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>

            <button
              onClick={onTaskCreate}
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
              aria-label="Create task"
            >
              <Calendar className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>

            <button
              className="p-2 hover:bg-muted dark:hover:bg-muted rounded-full transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
              aria-label="Attach file"
            >
              <Paperclip className="w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
            </button>
          </div>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 pr-12 bg-muted dark:bg-muted border-0 rounded-2xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:bg-surface dark:focus:bg-surface focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring transition-all duration-200"
