'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, CheckCircle, AlertCircle, RefreshCw, X } from 'lucide-react'

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  status: 'busy' | 'free' | 'tentative'
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  calendarConnected: boolean
}

interface SharedCalendarCheckProps {
  groupMembers?: GroupMember[]
  proposedDates?: Date[]
  onDateSelect?: (date: Date) => void
  onMemberToggle?: (memberId: string) => void
}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', email: 'alex@example.com', calendarConnected: true },
  { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', calendarConnected: true },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', calendarConnected: false },
  { id: '4', name: 'Emma Wilson', email: 'emma@example.com', calendarConnected: true },
]

const DEFAULT_DATES = [
  new Date('2024-02-15'),
  new Date('2024-02-16'),
  new Date('2024-02-17'),
  new Date('2024-02-22'),
  new Date('2024-02-23'),
  new Date('2024-02-24'),
]

export function SharedCalendarCheck({
  groupMembers = DEFAULT_MEMBERS,
  proposedDates = DEFAULT_DATES,
  onDateSelect = () => {},
  onMemberToggle = () => {}
}: SharedCalendarCheckProps = {}) {
  const [selectedMembers, setSelectedMembers] = useState<Set<string>>(
    new Set(groupMembers.filter(m => m.calendarConnected).map(m => m.id))
  )
  const [loading, setLoading] = useState(false)
  const [calendarData, setCalendarData] = useState<Record<string, CalendarEvent[]>>({})
  const [selectedDate, setSelectedDate] = useState<Date | null>(null)

  useEffect(() => {
    const mockData: Record<string, CalendarEvent[]> = {}
    groupMembers.forEach(member => {
      if (member.calendarConnected) {
        mockData[member.id] = [
          {
            id: '1',
            title: 'Team Meeting',
            start: new Date('2024-02-15T10:00:00'),
            end: new Date('2024-02-15T11:00:00'),
            attendees: [member.email],
            status: 'busy'
          },
          {
            id: '2',
            title: 'Lunch Break',
            start: new Date('2024-02-16T12:00:00'),
            end: new Date('2024-02-16T13:00:00'),
            attendees: [member.email],
            status: 'busy'
          }
        ]
      }
    })
    setCalendarData(mockData)
  }, [groupMembers])

  const handleMemberToggle = (memberId: string) => {
    const newSelected = new Set(selectedMembers)
    if (newSelected.has(memberId)) {
      newSelected.delete(memberId)
    } else {
      newSelected.add(memberId)
    }
    setSelectedMembers(newSelected)
    onMemberToggle(memberId)
  }

  const checkAvailability = async () => {
    setLoading(true)
    await new Promise(resolve => setTimeout(resolve, 2000))
    setLoading(false)
  }

  const getDateAvailability = (date: Date) => {
    const selectedMembersList = Array.from(selectedMembers)
    let available = 0
    let busy = 0

    selectedMembersList.forEach(memberId => {
      const events = calendarData[memberId] || []
      const hasConflict = events.some(event => 
        event.start.toDateString() === date.toDateString() && event.status === 'busy'
      )
      if (hasConflict) {
        busy++
      } else {
        available++
      }
    })

    return { available, busy, total: selectedMembersList.length }
  }

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    })
  }

  return (
    <div className="min-h-screen bg-[#FEFEFE] dark:bg-[#0C0A09] p-4 font-['Inter,-apple-system,BlinkMacSystemFont,Segoe_UI,sans-serif'] transition-colors duration-300">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-6 mb-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center gap-3 mb-4">
            <Calendar className="w-6 h-6 text-[#F97316] dark:text-[#FB923C]" />
            <h1 className="text-xl font-semibold text-[#1C1917] dark:text-[#FAFAF9]">Check Group Availability</h1>
          </div>
          <p className="text-[#78716C] dark:text-[#A8A29E] text-sm">
            Select group members and check their calendar availability for your travel adventure
          </p>
        </div>

        {/* Group Members Selection */}
        <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-6 mb-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h2 className="text-lg font-medium text-[#1C1917] dark:text-[#FAFAF9] mb-4 flex items-center gap-2">
            <Users className="w-5 h-5 text-[#F97316] dark:text-[#FB923C]" />
            Group Members
          </h2>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {groupMembers.map(member => (
              <div
                key={member.id}
                className={`p-4 rounded-lg border transition-all duration-200 cursor-pointer hover:scale-[1.02] active:scale-[0.98] ${
                  selectedMembers.has(member.id)
                    ? 'border-[#F97316] dark:border-[#FB923C] bg-[#F97316]/10 dark:bg-[#FB923C]/10 shadow-sm'
                    : 'border-[#E7E5E4] dark:border-[#44403C] bg-[#F5F5F4] dark:bg-[#292524] hover:border-[#F97316] dark:hover:border-[#FB923C] hover:shadow-md'
                }`}
                onClick={() => handleMemberToggle(member.id)}
                role="button"
                tabIndex={0}
                aria-label={`Toggle ${member.name} selection`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    handleMemberToggle(member.id)
                  }
                }}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-[#F97316] dark:bg-[#FB923C] rounded-full flex items-center justify-center text-[#FFFFFF] dark:text-[#1C1917] text-sm font-medium">
                      {member.name.charAt(0)}
                    </div>
                    <div>
                      <p className="text-[#1C1917] dark:text-[#FAFAF9] font-medium text-sm">{member.name}</p>
                      <p className="text-[#78716C] dark:text-[#A8A29E] text-xs">{member.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {member.calendarConnected ? (
                      <CheckCircle className="w-4 h-4 text-[#F97316] dark:text-[#FB923C]" />
                    ) : (
                      <AlertCircle className="w-4 h-4 text-[#DC2626] dark:text-[#EF4444]" />
                    )}
                    {selectedMembers.has(member.id) && (
                      <div className="w-4 h-4 bg-[#F97316] dark:bg-[#FB923C] rounded-full flex items-center justify-center">
                        <CheckCircle className="w-3 h-3 text-[#FFFFFF] dark:text-[#1C1917]" />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>

          <button
            onClick={checkAvailability}
            disabled={selectedMembers.size === 0 || loading}
            className="w-full mt-4 px-4 py-3 bg-[#F97316] dark:bg-[#FB923C] text-[#FFFFFF] dark:text-[#1C1917] rounded-lg hover:scale-[1.02] active:scale-[0.98] disabled:bg-[#78716C] dark:disabled:bg-[#A8A29E] disabled:cursor-not-allowed transition-all duration-150 font-medium flex items-center justify-center gap-2 shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FEFEFE] dark:focus:ring-offset-[#0C0A09]"
            aria-label={loading ? "Checking calendars" : "Check availability for selected members"}
          >
            {loading ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                Checking Calendars...
              </>
            ) : (
              <>
                <Clock className="w-4 h-4" />
                Check Availability
              </>
            )}
          </button>
        </div>

        {/* Date Availability Grid */}
        <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <h2 className="text-lg font-medium text-[#1C1917] dark:text-[#FAFAF9] mb-4">Proposed Dates</h2>

          {selectedMembers.size === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-[#F5F5F4] dark:bg-[#292524] rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-[#78716C] dark:text-[#A8A29E]" />
              </div>
              <h3 className="text-lg font-medium text-[#1C1917] dark:text-[#FAFAF9] mb-2">No members selected</h3>
              <p className="text-[#78716C] dark:text-[#A8A29E] text-sm">Select group members to check availability</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {proposedDates.map(date => {
                const availability = getDateAvailability(date)
                const availabilityPercent = availability.total > 0 
                  ? (availability.available / availability.total) * 100 
                  : 0

                return (
                  <div
                    key={date.toISOString()}
                    className={`p-4 rounded-lg border transition-all duration-200 cursor-pointer hover:scale-[1.02] hover:shadow-md active:scale-[0.98] ${
                      selectedDate?.toDateString() === date.toDateString()
                        ? 'border-[#F97316] dark:border-[#FB923C] bg-[#F97316]/10 dark:bg-[#FB923C]/10 shadow-sm'
                        : 'border-[#E7E5E4] dark:border-[#44403C] bg-[#F5F5F4] dark:bg-[#292524] hover:border-[#F97316] dark:hover:border-[#FB923C]'
                    }`}
                    onClick={() => {
                      setSelectedDate(date)
                      onDateSelect(date)
                    }}
                    role="button"
                    tabIndex={0}
                    aria-label={`Select date ${formatDate(date)}`}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault()
                        setSelectedDate(date)
                        onDateSelect(date)
                      }
                    }}
                  >
                    <div className="text-center mb-3">
                      <p className="text-[#1C1917] dark:text-[#FAFAF9] font-medium">{formatDate(date)}</p>
                      <p className="text-[#78716C] dark:text-[#A8A29E] text-xs">{date.getFullYear()}</p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between text-xs">
                        <span className="text-[#F97316] dark:text-[#FB923C]">
                          {availability.available} available
                        </span>
                        <span className="text-[#DC2626] dark:text-[#EF4444]">
                          {availability.busy} busy
                        </span>
                      </div>

                      <div className="w-full bg-[#E7E5E4] dark:bg-[#44403C] rounded-full h-2">
                        <div
                          className="bg-[#F97316] dark:bg-[#FB923C] h-2 rounded-full transition-all duration-300"
                          style={{ width: `${availabilityPercent}%` }}
                        />
                      </div>

                      <div className="text-center">
                        <span className={`text-xs font-medium ${
                          availabilityPercent >= 80 ? 'text-[#F97316] dark:text-[#FB923C]' :
                          availabilityPercent >= 50 ? 'text-[#DC2626] dark:text-[#EF4444]' :
                          'text-[#DC2626] dark:text-[#EF4444]'
                        }`}>
                          {Math.round(availabilityPercent)}% available
                        </span>
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        {/* Selected Date Details */}
        {selectedDate && selectedMembers.size > 0 && (
          <div className="bg-[#FFFFFF] dark:bg-[#1C1917] rounded-xl border border-[#E7E5E4] dark:border-[#44403C] p-6 mt-6 shadow-sm hover:shadow-md transition-all duration-300">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-medium text-[#1C1917] dark:text-[#FAFAF9]">
                Details for {formatDate(selectedDate)}
              </h3>
              <button
                onClick={() => setSelectedDate(null)}
                className="p-1 text-[#78716C] dark:text-[#A8A29E] hover:text-[#1C1917] dark:hover:text-[#FAFAF9] transition-colors duration-200 rounded-md hover:bg-[#F5F5F4] dark:hover:bg-[#292524] focus:outline-none focus:ring-2 focus:ring-[#F97316] dark:focus:ring-[#FB923C] focus:ring-offset-2 focus:ring-offset-[#FFFFFF] dark:focus:ring-offset-[#1C1917]"
                aria-label="Close date details"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-3">
              {Array.from(selectedMembers).map(memberId => {
                const member = groupMembers.find(m => m.id === memberId)
                if (!member) return null

                const events = calendarData[memberId] || []
                const dayEvents = events.filter(event => 
                  event.start.toDateString() === selectedDate.toDateString()
                )

                return (
                  <div key={memberId} className="flex items-center justify-between p-3 bg-[#F5F5F4] dark:bg-[#292524] rounded-lg hover:bg-[#E7E5E4] dark:hover:bg-[#44403C] transition-colors duration-200">
                    <div className="flex items-center gap-3">
                      <div className="w-6 h-6 bg-[#F97316] dark:bg-[#FB923C] rounded-full flex items-center justify-center text-[#FFFFFF] dark:text-[#1C1917] text-xs font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <span className="text-[#1C1917] dark:text-[#FAFAF9] text-sm font-medium">{member.name}</span>
                    </div>

                    <div className="flex items-center gap-2">
                      {dayEvents.length > 0 ? (
                        <>
                          <AlertCircle className="w-4 h-4 text-[#DC2626] dark:text-[#EF4444]" />
                          <span className="text-[#DC2626] dark:text-[#EF4444] text-xs">
                            {dayEvents.length} conflict{dayEvents.length > 1 ? 's' : ''}
                          </span>
                        </>
                      ) : (
                        <>
                          <CheckCircle className="w-4 h-4 text-[#F97316] dark:text-[#FB923C]" />
                          <span className="text-[#F97316] dark:text-[#FB923C] text-xs">Available</span>
                        </>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

