'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageSquare, Utensils, CheckCircle, Settings, Plus, Search, Filter } from 'lucide-react'

interface Trip {
  id: string
  name: string
  location: string
  startDate: string
  endDate: string
  memberCount: number
  status: 'planning' | 'confirmed' | 'completed'
  image: string
}

interface TripPlannerProps {
  trips?: Trip[]
  onCreateTrip?: () => void
  onSelectTrip?: (tripId: string) => void
}

export function TripPlanner({
  trips = DEFAULT_TRIPS,
  onCreateTrip = () => console.log('Create trip'),
  onSelectTrip = () => console.log('Select trip')
}: TripPlannerProps = {}) {
  const [activeTab, setActiveTab] = useState('trips')
  const [searchQuery, setSearchQuery] = useState('')
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [isLoading, setIsLoading] = useState(false)
  const [isDarkMode, setIsDarkMode] = useState(false)

  useEffect(() => {
    const darkModeQuery = window.matchMedia('(prefers-color-scheme: dark)')
    setIsDarkMode(darkModeQuery.matches)

    const handleChange = (e: MediaQueryListEvent) => setIsDarkMode(e.matches)
    darkModeQuery.addEventListener('change', handleChange)

    return () => darkModeQuery.removeEventListener('change', handleChange)
  }, [])

  const filteredTrips = trips.filter(trip => {
    const matchesSearch = trip.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         trip.location.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesFilter = filterStatus === 'all' || trip.status === filterStatus
    return matchesSearch && matchesFilter
  })

  const handleCreateTrip = () => {
    setIsLoading(true)
    setTimeout(() => {
      setIsLoading(false)
      onCreateTrip()
    }, 1000)
  }

  return (
    <div className={`min-h-screen font-sans transition-colors duration-300 ${
      isDarkMode 
        ? 'bg-[#0C0A09] text-[#FAFAF9]' 
        : 'bg-[#FEFEFE] text-[#1C1917]'
    }`}>
      {/* Header */}
      <div className={`backdrop-blur-sm border-b sticky top-0 z-50 transition-colors duration-300 ${
        isDarkMode 
          ? 'bg-[#1C1917]/80 border-[#44403C]' 
          : 'bg-[#FFFFFF]/80 border-[#E7E5E4]'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-gradient-to-br from-[#F97316] to-[#DC2626] rounded-lg flex items-center justify-center shadow-sm">
                <MapPin className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold">TrailPlan</h1>
            </div>
            <button
              onClick={handleCreateTrip}
              disabled={isLoading}
              aria-label="Create new trip"
              className={`px-4 py-2 bg-[#F97316] text-[#FFFFFF] rounded-lg font-medium text-sm shadow-sm flex items-center gap-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#F97316]/50 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 ${
                isDarkMode 
                  ? 'hover:bg-[#FB923C] shadow-lg' 
                  : 'hover:bg-[#EA580C] shadow-md'
              }`}
            >
              {isLoading ? (
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <Plus className="w-4 h-4" />
              )}
              New Trip
            </button>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className={`backdrop-blur-sm border-b transition-colors duration-300 ${
        isDarkMode 
          ? 'bg-[#1C1917]/30 border-[#44403C]/50' 
          : 'bg-[#FFFFFF]/30 border-[#E7E5E4]/50'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex space-x-8 overflow-x-auto">
            {[
              { id: 'trips', label: 'My Trips', icon: MapPin },
              { id: 'calendar', label: 'Calendar', icon: Calendar },
              { id: 'groups', label: 'Groups', icon: Users },
              { id: 'chat', label: 'Chat', icon: MessageSquare },
              { id: 'meals', label: 'Meals', icon: Utensils }
            ].map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                aria-label={`Switch to ${label} tab`}
                className={`flex items-center gap-2 py-4 px-2 border-b-2 font-medium text-sm whitespace-nowrap transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-[#F97316]/50 focus:ring-offset-2 ${
                  activeTab === id
                    ? isDarkMode
                      ? 'border-[#FB923C] text-[#FB923C]'
                      : 'border-[#F97316] text-[#F97316]'
                    : isDarkMode
                      ? 'border-transparent text-[#A8A29E] hover:text-[#FAFAF9] hover:border-[#44403C]'
                      : 'border-transparent text-[#78716C] hover:text-[#1C1917] hover:border-[#E7E5E4]'
                } ${isDarkMode ? 'focus:ring-offset-[#0C0A09]' : 'focus:ring-offset-[#FEFEFE]'}`}
              >
                <Icon className="w-4 h-4" />
                {label}
              </button>
