                  isDarkMode ? 'text-[#A8A29E]' : 'text-[#78716C]'
                }`} />
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  aria-label="Filter by status"
                  className={`pl-10 pr-8 py-3 border rounded-xl appearance-none cursor-pointer transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-[#F97316]/50 ${
