'use client'

import { useState } from 'react'
import { MapPin, Users, Calendar, MessageSquare, Utensils, CheckCircle, AlertCircle, Loader2 } from 'lucide-react'

interface TripFormData {
  tripName: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
  difficulty: 'easy' | 'moderate' | 'hard'
  vehicleRequirements: string
  emergencyContact: string
  emergencyPhone: string
}

interface FormErrors {
  [key: string]: string
}

interface TripPlannerFormProps {
  onSubmit?: (data: TripFormData) => Promise<void>
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

export function TripPlannerForm({
  onSubmit = async (data) => {
    console.log('Trip data submitted:', data)
    await new Promise(resolve => setTimeout(resolve, 2000))
  },
  initialData = {},
  isLoading = false
}: TripPlannerFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    tripName: '',
    location: '',
    startDate: '',
    endDate: '',
    description: '',
    maxParticipants: 8,
    difficulty: 'moderate',
    vehicleRequirements: '',
    emergencyContact: '',
    emergencyPhone: '',
    ...initialData
  })

  const [errors, setErrors] = useState<FormErrors>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitSuccess, setSubmitSuccess] = useState(false)
  const [currentStep, setCurrentStep] = useState(1)

  const validateField = (name: string, value: string | number): string => {
    switch (name) {
      case 'tripName':
        return !value ? 'Trip name is required' : ''
      case 'location':
        return !value ? 'Location is required' : ''
      case 'startDate':
        return !value ? 'Start date is required' : ''
      case 'endDate':
        if (!value) return 'End date is required'
        if (formData.startDate && new Date(value) < new Date(formData.startDate)) {
          return 'End date must be after start date'
        }
        return ''
      case 'emergencyContact':
        return !value ? 'Emergency contact is required' : ''
      case 'emergencyPhone':
        const phoneRegex = /^\+?[\d\s\-\(\)]{10,}$/
        return !value ? 'Emergency phone is required' : !phoneRegex.test(value as string) ? 'Invalid phone number' : ''
      case 'maxParticipants':
        return (value as number) < 1 ? 'Must have at least 1 participant' : ''
      default:
        return ''
    }
  }

  const handleInputChange = (name: string, value: string | number) => {
    setFormData(prev => ({ ...prev, [name]: value }))

    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }))
    }
  }

  const validateStep = (step: number): boolean => {
    const stepErrors: FormErrors = {}

    if (step === 1) {
      stepErrors.tripName = validateField('tripName', formData.tripName)
      stepErrors.location = validateField('location', formData.location)
      stepErrors.startDate = validateField('startDate', formData.startDate)
      stepErrors.endDate = validateField('endDate', formData.endDate)
    } else if (step === 2) {
      stepErrors.maxParticipants = validateField('maxParticipants', formData.maxParticipants)
    } else if (step === 3) {
      stepErrors.emergencyContact = validateField('emergencyContact', formData.emergencyContact)
      stepErrors.emergencyPhone = validateField('emergencyPhone', formData.emergencyPhone)
    }

    const hasErrors = Object.values(stepErrors).some(error => error !== '')
    setErrors(stepErrors)
    return !hasErrors
  }

  const handleNext = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, 3))
    }
  }

  const handlePrevious = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateStep(1) || !validateStep(2) || !validateStep(3)) {
      return
    }

    setIsSubmitting(true)
    try {
      await onSubmit(formData)
      setSubmitSuccess(true)
      setTimeout(() => setSubmitSuccess(false), 3000)
    } catch (error) {
      console.error('Form submission error:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const renderStepIndicator = () => (
    <div className="flex items-center justify-center mb-8">
      {[1, 2, 3].map((step) => (
        <div key={step} className="flex items-center">
          <div
            className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-medium transition-all duration-200 ${
              step <= currentStep
                ? 'bg-primary text-primaryForeground shadow-md'
                : 'bg-muted text-mutedForeground'
            }`}
          >
            {step}
          </div>
          {step < 3 && (
            <div
              className={`w-16 h-1 mx-2 transition-all duration-200 ${
                step < currentStep ? 'bg-primary' : 'bg-muted'
              }`}
            />
          )}
        </div>
      ))}
    </div>
  )

  const renderStep1 = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <MapPin className="w-12 h-12 text-primary mx-auto mb-3" />
        <h2 className="text-2xl font-bold text-foreground mb-2">Trip Details</h2>
        <p className="text-mutedForeground">Let's start with the basics of your off-road adventure</p>
      </div>

      <div>
        <label htmlFor="tripName" className="block text-sm font-medium text-foreground mb-2">
          Trip Name *
        </label>
        <input
          id="tripName"
          type="text"
          value={formData.tripName}
          onChange={(e) => handleInputChange('tripName', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
            errors.tripName ? 'border-destructive' : 'border-border'
          }`}
          placeholder="e.g., Moab Desert Adventure"
          aria-describedby={errors.tripName ? 'tripName-error' : undefined}
        />
        {errors.tripName && (
          <p id="tripName-error" className="mt-1 text-sm text-destructive flex items-center">
            <AlertCircle className="w-4 h-4 mr-1" />
            {errors.tripName}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="location" className="block text-sm font-medium text-foreground mb-2">
          Location *
        </label>
        <input
          id="location"
          type="text"
          value={formData.location}
          onChange={(e) => handleInputChange('location', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
            errors.location ? 'border-destructive' : 'border-border'
          }`}
          placeholder="e.g., Moab, Utah"
          aria-describedby={errors.location ? 'location-error' : undefined}
        />
        {errors.location && (
          <p id="location-error" className="mt-1 text-sm text-destructive flex items-center">
            <AlertCircle className="w-4 h-4 mr-1" />
            {errors.location}
          </p>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <label htmlFor="startDate" className="block text-sm font-medium text-foreground mb-2">
            Start Date *
          </label>
          <input
            id="startDate"
            type="date"
            value={formData.startDate}
            onChange={(e) => handleInputChange('startDate', e.target.value)}
            min={new Date().toISOString().split('T')[0]}
            className={`w-full px-4 py-3 border rounded-lg text-foreground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
              errors.startDate ? 'border-destructive' : 'border-border'
            }`}
            aria-describedby={errors.startDate ? 'startDate-error' : undefined}
          />
          {errors.startDate && (
            <p id="startDate-error" className="mt-1 text-sm text-destructive flex items-center">
              <AlertCircle className="w-4 h-4 mr-1" />
              {errors.startDate}
            </p>
          )}
        </div>

        <div>
          <label htmlFor="endDate" className="block text-sm font-medium text-foreground mb-2">
            End Date *
          </label>
          <input
            id="endDate"
            type="date"
            value={formData.endDate}
            onChange={(e) => handleInputChange('endDate', e.target.value)}
            min={formData.startDate || new Date().toISOString().split('T')[0]}
            className={`w-full px-4 py-3 border rounded-lg text-foreground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
              errors.endDate ? 'border-destructive' : 'border-border'
            }`}
            aria-describedby={errors.endDate ? 'endDate-error' : undefined}
          />
          {errors.endDate && (
            <p id="endDate-error" className="mt-1 text-sm text-destructive flex items-center">
              <AlertCircle className="w-4 h-4 mr-1" />
              {errors.endDate}
            </p>
          )}
        </div>
      </div>

      <div>
        <label htmlFor="description" className="block text-sm font-medium text-foreground mb-2">
          Trip Description
        </label>
        <textarea
          id="description"
          value={formData.description}
          onChange={(e) => handleInputChange('description', e.target.value)}
          rows={4}
          className="w-full px-4 py-3 border border-border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 resize-none hover:border-primary/50"
          placeholder="Describe your adventure, what to expect, and any special requirements..."
        />
      </div>
    </div>
  )

  const renderStep2 = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <Users className="w-12 h-12 text-primary mx-auto mb-3" />
        <h2 className="text-2xl font-bold text-foreground mb-2">Group & Requirements</h2>
        <p className="text-mutedForeground">Set up your group size and trip requirements</p>
      </div>

      <div>
        <label htmlFor="maxParticipants" className="block text-sm font-medium text-foreground mb-2">
          Maximum Participants *
        </label>
        <input
          id="maxParticipants"
          type="number"
          min="1"
          max="50"
          value={formData.maxParticipants}
          onChange={(e) => handleInputChange('maxParticipants', parseInt(e.target.value) || 0)}
          className={`w-full px-4 py-3 border rounded-lg text-foreground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
            errors.maxParticipants ? 'border-destructive' : 'border-border'
          }`}
          aria-describedby={errors.maxParticipants ? 'maxParticipants-error' : undefined}
        />
        {errors.maxParticipants && (
          <p id="maxParticipants-error" className="mt-1 text-sm text-destructive flex items-center">
            <AlertCircle className="w-4 h-4 mr-1" />
            {errors.maxParticipants}
          </p>
        )}
      </div>

      <div>
        <label className="block text-sm font-medium text-foreground mb-3">
          Difficulty Level
        </label>
        <div className="grid grid-cols-3 gap-3">
          {(['easy', 'moderate', 'hard'] as const).map((level) => (
            <button
              key={level}
              type="button"
              onClick={() => handleInputChange('difficulty', level)}
              className={`px-4 py-3 rounded-lg border-2 transition-all duration-200 font-medium text-sm hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring ${
                formData.difficulty === level
                  ? 'border-primary bg-primary/10 text-primary'
                  : 'border-border bg-surface text-foreground hover:border-primary/50 hover:bg-muted/50'
              }`}
              aria-pressed={formData.difficulty === level}
            >
              {level.charAt(0).toUpperCase() + level.slice(1)}
            </button>
          ))}
        </div>
      </div>

      <div>
        <label htmlFor="vehicleRequirements" className="block text-sm font-medium text-foreground mb-2">
          Vehicle Requirements
        </label>
        <textarea
          id="vehicleRequirements"
          value={formData.vehicleRequirements}
          onChange={(e) => handleInputChange('vehicleRequirements', e.target.value)}
          rows={3}
          className="w-full px-4 py-3 border border-border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 resize-none hover:border-primary/50"
          placeholder="e.g., 4WD required, high clearance recommended, winch suggested..."
        />
      </div>
    </div>
  )

  const renderStep3 = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <MessageSquare className="w-12 h-12 text-primary mx-auto mb-3" />
        <h2 className="text-2xl font-bold text-foreground mb-2">Emergency Contact</h2>
        <p className="text-mutedForeground">Safety first - provide emergency contact information</p>
      </div>

      <div>
        <label htmlFor="emergencyContact" className="block text-sm font-medium text-foreground mb-2">
          Emergency Contact Name *
        </label>
        <input
          id="emergencyContact"
          type="text"
          value={formData.emergencyContact}
          onChange={(e) => handleInputChange('emergencyContact', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
