            <AlertCircle className="w-4 h-4 mr-1" />
            {errors.emergencyContact}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="emergencyPhone" className="block text-sm font-medium text-foreground mb-2">
          Emergency Phone Number *
        </label>
        <input
          id="emergencyPhone"
          type="tel"
          value={formData.emergencyPhone}
          onChange={(e) => handleInputChange('emergencyPhone', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg text-foreground placeholder-mutedForeground bg-surface focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent transition-all duration-200 hover:border-primary/50 ${
            errors.emergencyPhone ? 'border-destructive' : 'border-border'
          }`}
          placeholder="+1 (555) 123-4567"
          aria-describedby={errors.emergencyPhone ? 'emergencyPhone-error' : undefined}
        />
        {errors.emergencyPhone && (
          <p id="emergencyPhone-error" className="mt-1 text-sm text-destructive flex items-center">
            <AlertCircle className="w-4 h-4 mr-1" />
            {errors.emergencyPhone}
          </p>
        )}
      </div>

      <div className="bg-primary/5 border border-primary/20 rounded-lg p-4">
        <div className="flex items-start">
          <AlertCircle className="w-5 h-5 text-primary mt-0.5 mr-3 flex-shrink-0" />
          <div>
            <h4 className="text-sm font-medium text-foreground mb-1">Safety Reminder</h4>
            <p className="text-sm text-mutedForeground">
              Always inform someone reliable about your trip plans, expected return time, and route details. 
              Consider carrying emergency communication devices for remote areas.
            </p>
          </div>
        </div>
      </div>
    </div>
  )

  if (submitSuccess) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-primary/5 to-secondary/5 py-8 px-4 font-sans">
        <div className="max-w-md mx-auto p-6">
          <div className="bg-surface rounded-2xl shadow-lg p-8">
            <div className="text-center">
              <div className="w-16 h-16 bg-green-100 dark:bg-green-900/20 rounded-full flex items-center justify-center mx-auto mb-4">
                <CheckCircle className="w-8 h-8 text-green-500" />
              </div>
              <h2 className="text-2xl font-bold text-foreground mb-2">Trip Created!</h2>
              <p className="text-mutedForeground mb-6">
                Your off-road adventure has been successfully planned. Invitations will be sent to your group members.
              </p>
              <button
                onClick={() => setSubmitSuccess(false)}
                className="px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring"
                aria-label="Plan another trip"
              >
                Plan Another Trip
              </button>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary/5 to-secondary/5 py-8 px-4 font-sans">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface rounded-2xl shadow-lg shadow-primary/10 p-6 sm:p-8 hover:shadow-xl transition-all duration-300">
          <form onSubmit={handleSubmit} className="space-y-8">
            {renderStepIndicator()}

            {currentStep === 1 && renderStep1()}
            {currentStep === 2 && renderStep2()}
            {currentStep === 3 && renderStep3()}

            <div className="flex flex-col sm:flex-row gap-3 pt-6 border-t border-border">
              {currentStep > 1 && (
                <button
                  type="button"
                  onClick={handlePrevious}
                  className="px-6 py-3 bg-muted text-foreground rounded-lg hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium order-2 sm:order-1 focus:outline-none focus:ring-2 focus:ring-ring"
                  aria-label="Go to previous step"
                >
                  Previous
                </button>
              )}

              <div className="flex-1" />

              {currentStep < 3 ? (
                <button
                  type="button"
                  onClick={handleNext}
                  className="px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-md hover:shadow-lg order-1 sm:order-2 focus:outline-none focus:ring-2 focus:ring-ring"
                  aria-label="Go to next step"
                >
                  Next Step
                </button>
              ) : (
                <button
                  type="submit"
                  disabled={isSubmitting || isLoading}
                  className="px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 disabled:bg-muted disabled:text-mutedForeground disabled:cursor-not-allowed hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-md hover:shadow-lg order-1 sm:order-2 flex items-center justify-center min-h-[48px] focus:outline-none focus:ring-2 focus:ring-ring disabled:hover:scale-100"
                  aria-label={isSubmitting || isLoading ? 'Creating trip...' : 'Create trip'}
                >
                  {isSubmitting || isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin mr-2" />
                      Creating Trip...
                    </>
                  ) : (
                    'Create Trip'
                  )}
                </button>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  )
}

export default function TripPlannerFormDemo() {
  return <TripPlannerForm />
}

