'use client'

import { useState, useEffect } from 'react'
import { Calendar, Clock, Users, Plus, Edit3, Trash2, ChefHat, MapPin } from 'lucide-react'

interface Meal {
  id: string
  name: string
  type: 'breakfast' | 'lunch' | 'dinner' | 'snack'
  day: string
  time: string
  assignedTo: string[]
  ingredients: string[]
  servings: number
  notes?: string
  difficulty: 'easy' | 'medium' | 'hard'
  cookingTime: number
}

interface GroupMember {
  id: string
  name: string
  avatar?: string
  dietary?: string[]
}

interface MealPlanningSectionProps {
  tripId?: string
  groupMembers?: GroupMember[]
  tripDays?: string[]
  onMealUpdate?: (meal: Meal) => void
  onMealDelete?: (mealId: string) => void
}

export function MealPlanningSection({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  tripDays = DEFAULT_DAYS,
  onMealUpdate = () => console.log('Meal updated'),
  onMealDelete = () => console.log('Meal deleted')
}: MealPlanningSectionProps = {}) {
  const [meals, setMeals] = useState<Meal[]>(DEFAULT_MEALS)
  const [selectedDay, setSelectedDay] = useState(tripDays[0])
  const [showAddMeal, setShowAddMeal] = useState(false)
  const [editingMeal, setEditingMeal] = useState<Meal | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newMeal, setNewMeal] = useState<Partial<Meal>>({
    type: 'breakfast',
    day: selectedDay,
    time: '08:00',
    assignedTo: [],
    ingredients: [],
    servings: 4,
    difficulty: 'easy',
    cookingTime: 30
  })

  const mealTypes = [
    { value: 'breakfast', label: 'Breakfast', icon: '🌅' },
    { value: 'lunch', label: 'Lunch', icon: '☀️' },
    { value: 'dinner', label: 'Dinner', icon: '🌙' },
    { value: 'snack', label: 'Snack', icon: '🥨' }
  ]

  const filteredMeals = meals.filter(meal => meal.day === selectedDay)

  const handleAddMeal = async () => {
    if (!newMeal.name || !newMeal.type) {
      setError('Please fill in all required fields')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const meal: Meal = {
        id: `meal-${Date.now()}`,
        name: newMeal.name,
        type: newMeal.type as Meal['type'],
        day: selectedDay,
        time: newMeal.time || '12:00',
        assignedTo: newMeal.assignedTo || [],
        ingredients: newMeal.ingredients || [],
        servings: newMeal.servings || 4,
        difficulty: newMeal.difficulty || 'easy',
        cookingTime: newMeal.cookingTime || 30,
        notes: newMeal.notes
      }

      setMeals(prev => [...prev, meal])
      onMealUpdate(meal)
      setShowAddMeal(false)
      resetForm()
    } catch (err) {
      setError('Failed to add meal. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleEditMeal = (meal: Meal) => {
    setEditingMeal(meal)
    setNewMeal(meal)
    setShowAddMeal(true)
    setError(null)
  }

  const handleUpdateMeal = async () => {
    if (!editingMeal || !newMeal.name) {
      setError('Please fill in all required fields')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const updatedMeal: Meal = {
        ...editingMeal,
        ...newMeal,
        id: editingMeal.id
      } as Meal

      setMeals(prev => prev.map(m => m.id === editingMeal.id ? updatedMeal : m))
      onMealUpdate(updatedMeal)
      setEditingMeal(null)
      setShowAddMeal(false)
      resetForm()
    } catch (err) {
      setError('Failed to update meal. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleDeleteMeal = (mealId: string) => {
    setMeals(prev => prev.filter(m => m.id !== mealId))
    onMealDelete(mealId)
  }

  const resetForm = () => {
    setNewMeal({
      type: 'breakfast',
      day: selectedDay,
      time: '08:00',
      assignedTo: [],
      ingredients: [],
      servings: 4,
      difficulty: 'easy',
      cookingTime: 30
    })
  }

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-muted text-mutedForeground border-border'
      case 'medium': return 'bg-secondary/20 text-secondary border-secondary/30'
      case 'hard': return 'bg-destructive/20 text-destructive border-destructive/30'
      default: return 'bg-muted text-mutedForeground border-border'
    }
  }

  const getMealTypeColor = (type: string) => {
    switch (type) {
      case 'breakfast': return 'bg-primary/20 text-primary border-primary/30'
      case 'lunch': return 'bg-secondary/20 text-secondary border-secondary/30'
      case 'dinner': return 'bg-accent/20 text-accent border-accent/30'
      case 'snack': return 'bg-muted text-mutedForeground border-border'
      default: return 'bg-muted text-mutedForeground border-border'
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <ChefHat className="w-8 h-8 text-primary" />
            <h1 className="text-3xl font-bold text-foreground">Meal Planning</h1>
          </div>
          <p className="text-mutedForeground">Plan and organize meals for your off-road adventure</p>
        </div>

        {/* Day Selector */}
        <div className="mb-6">
          <div className="flex gap-2 overflow-x-auto pb-2">
            {tripDays.map((day) => (
              <button
                key={day}
                onClick={() => setSelectedDay(day)}
                className={`px-4 py-2 rounded-lg font-medium text-sm whitespace-nowrap transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                  selectedDay === day
                    ? 'bg-primary text-primaryForeground shadow-md'
                    : 'bg-surface text-mutedForeground hover:bg-muted border border-border'
                }`}
              >
                {day}
              </button>
            ))}
          </div>
        </div>

        {/* Add Meal Button */}
        <div className="mb-6">
          <button
            onClick={() => setShowAddMeal(true)}
            className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring/50"
            aria-label="Add new meal"
          >
            <Plus className="w-5 h-5" />
            Add Meal
          </button>
        </div>

        {/* Error State */}
        {error && (
          <div className="mb-6 rounded-lg bg-destructive/10 border border-destructive/20 p-4">
            <p className="text-sm text-destructive">{error}</p>
          </div>
        )}

        {/* Loading State */}
        {isLoading && (
          <div className="mb-6 space-y-4 animate-pulse">
            <div className="h-32 bg-muted rounded-xl"></div>
            <div className="h-32 bg-muted rounded-xl"></div>
          </div>
        )}

        {/* Meals List */}
        <div className="space-y-4 mb-6">
          {filteredMeals.length === 0 ? (
            <div className="bg-surface rounded-xl border border-border p-8 text-center">
              <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <ChefHat className="w-8 h-8 text-mutedForeground" />
              </div>
              <h3 className="text-lg font-semibold text-foreground mb-2">No meals planned</h3>
              <p className="text-mutedForeground mb-4">Start planning your meals for {selectedDay}</p>
              <button
                onClick={() => setShowAddMeal(true)}
                className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium focus:outline-none focus:ring-2 focus:ring-ring/50"
                aria-label="Add first meal"
              >
                Add First Meal
              </button>
            </div>
          ) : (
            filteredMeals
              .sort((a, b) => a.time.localeCompare(b.time))
              .map((meal) => (
                <div
                  key={meal.id}
                  className="bg-surface rounded-xl border border-border p-6 hover:border-primary/50 hover:-translate-y-1 hover:shadow-xl transition-all duration-300 shadow-sm"
                >
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="text-xl font-semibold text-foreground">{meal.name}</h3>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getMealTypeColor(meal.type)}`}>
                          {meal.type}
                        </span>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getDifficultyColor(meal.difficulty)}`}>
                          {meal.difficulty}
                        </span>
                      </div>
                      <div className="flex items-center gap-4 text-sm text-mutedForeground mb-3">
                        <div className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          {meal.time}
                        </div>
                        <div className="flex items-center gap-1">
                          <Users className="w-4 h-4" />
                          {meal.servings} servings
                        </div>
                        <div className="flex items-center gap-1">
                          <ChefHat className="w-4 h-4" />
                          {meal.cookingTime} min
                        </div>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleEditMeal(meal)}
                        className="p-2 text-mutedForeground hover:text-primary hover:bg-muted rounded-lg transition-all duration-200 hover:scale-[1.05] focus:outline-none focus:ring-2 focus:ring-ring/50"
                        aria-label="Edit meal"
                      >
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDeleteMeal(meal.id)}
                        className="p-2 text-mutedForeground hover:text-destructive hover:bg-muted rounded-lg transition-all duration-200 hover:scale-[1.05] focus:outline-none focus:ring-2 focus:ring-ring/50"
                        aria-label="Delete meal"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  {/* Assigned Members */}
                  {meal.assignedTo.length > 0 && (
                    <div className="mb-3">
                      <p className="text-sm text-mutedForeground mb-2">Assigned to:</p>
                      <div className="flex flex-wrap gap-2">
                        {meal.assignedTo.map((memberId) => {
                          const member = groupMembers.find(m => m.id === memberId)
                          return member ? (
                            <span
                              key={memberId}
                              className="px-3 py-1 bg-primary/20 text-primary rounded-full text-xs font-medium border border-primary/30"
                            >
                              {member.name}
                            </span>
                          ) : null
                        })}
                      </div>
                    </div>
                  )}

                  {/* Ingredients */}
                  {meal.ingredients.length > 0 && (
                    <div className="mb-3">
                      <p className="text-sm text-mutedForeground mb-2">Ingredients:</p>
                      <div className="flex flex-wrap gap-2">
                        {meal.ingredients.map((ingredient, index) => (
                          <span
                            key={index}
                            className="px-2 py-1 bg-muted text-mutedForeground rounded text-xs border border-border"
                          >
                            {ingredient}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Notes */}
                  {meal.notes && (
                    <div className="mt-3 p-3 bg-muted/50 rounded-lg border border-border">
                      <p className="text-sm text-foreground">{meal.notes}</p>
                    </div>
                  )}
                </div>
              ))
          )}
        </div>

        {/* Add/Edit Meal Modal */}
        {showAddMeal && (
          <div className="fixed inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
            <div className="bg-surface rounded-xl border border-border p-6 w-full max-w-md max-h-[90vh] overflow-y-auto shadow-xl">
              <h2 className="text-xl font-semibold text-foreground mb-6">
                {editingMeal ? 'Edit Meal' : 'Add New Meal'}
              </h2>

              <div className="space-y-4">
                {/* Meal Name */}
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Meal Name *
                  </label>
                  <input
                    type="text"
                    value={newMeal.name || ''}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    placeholder="Enter meal name"
                  />
                </div>

                {/* Meal Type */}
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Meal Type
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {mealTypes.map((type) => (
                      <button
                        key={type.value}
                        onClick={() => setNewMeal(prev => ({ ...prev, type: type.value as Meal['type'] }))}
                        className={`p-3 rounded-lg border text-sm font-medium transition-all duration-200 hover:scale-[1.02] focus:outline-none focus:ring-2 focus:ring-ring/50 ${
                          newMeal.type === type.value
                            ? 'bg-primary/20 border-primary text-primary'
                            : 'bg-muted border-border text-mutedForeground hover:border-border/80'
                        }`}
                      >
                        <div className="text-lg mb-1">{type.icon}</div>
                        {type.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Time and Servings */}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-foreground mb-2">
                      Time
                    </label>
                    <input
                      type="time"
                      value={newMeal.time || ''}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, time: e.target.value }))}
                      className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-foreground mb-2">
                      Servings
                    </label>
                    <input
                      type="number"
                      min="1"
                      value={newMeal.servings || ''}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, servings: parseInt(e.target.value) }))}
                      className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    />
                  </div>
                </div>

                {/* Difficulty and Cooking Time */}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-foreground mb-2">
                      Difficulty
                    </label>
                    <select
                      value={newMeal.difficulty || 'easy'}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, difficulty: e.target.value as Meal['difficulty'] }))}
                      className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    >
                      <option value="easy">Easy</option>
                      <option value="medium">Medium</option>
                      <option value="hard">Hard</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-foreground mb-2">
                      Cook Time (min)
                    </label>
                    <input
                      type="number"
                      min="5"
                      value={newMeal.cookingTime || ''}
                      onChange={(e) => setNewMeal(prev => ({ ...prev, cookingTime: parseInt(e.target.value) }))}
                      className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    />
                  </div>
                </div>

                {/* Assign Members */}
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Assign Members
                  </label>
                  <div className="space-y-2 max-h-32 overflow-y-auto">
                    {groupMembers.map((member) => (
                      <label key={member.id} className="flex items-center gap-3 p-2 hover:bg-muted/50 rounded-lg cursor-pointer transition-colors duration-200">
                        <input
                          type="checkbox"
                          checked={newMeal.assignedTo?.includes(member.id) || false}
                          onChange={(e) => {
                            const assignedTo = newMeal.assignedTo || []
                            if (e.target.checked) {
                              setNewMeal(prev => ({ ...prev, assignedTo: [...assignedTo, member.id] }))
                            } else {
                              setNewMeal(prev => ({ ...prev, assignedTo: assignedTo.filter(id => id !== member.id) }))
                            }
                          }}
                          className="w-4 h-4 text-primary bg-background border-border rounded focus:ring-ring focus:ring-2 transition-all duration-200"
                        />
                        <span className="text-foreground text-sm">{member.name}</span>
                      </label>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Notes
                  </label>
                  <textarea
                    value={newMeal.notes || ''}
                    onChange={(e) => setNewMeal(prev => ({ ...prev, notes: e.target.value }))}
                    rows={3}
                    className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 resize-none"
                    placeholder="Any special instructions or notes..."
                  />
                </div>
              </div>

              {/* Modal Actions */}
              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => {
                    setShowAddMeal(false)
                    setEditingMeal(null)
                    resetForm()
                    setError(null)
                  }}
                  className="flex-1 px-4 py-2 bg-muted text-mutedForeground rounded-lg hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium focus:outline-none focus:ring-2 focus:ring-ring/50"
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  onClick={editingMeal ? handleUpdateMeal : handleAddMeal}
                  disabled={!newMeal.name || isLoading}
                  className="flex-1 px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] disabled:bg-muted disabled:text-mutedForeground disabled:cursor-not-allowed transition-all duration-200 font-medium focus:outline-none focus:ring-2 focus:ring-ring/50"
                >
                  {isLoading ? 'Saving...' : editingMeal ? 'Update' : 'Add'} Meal
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

