'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar, MessageSquare, ChevronDown, ChevronUp } from 'lucide-react'

interface RsvpResponse {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  status: 'pending' | 'accepted' | 'declined' | 'maybe'
  respondedAt?: Date
  notes?: string
