interface TripDetails {
  id: string
  title: string
  location: string
  startDate: Date
  endDate: Date
  maxParticipants: number
  description: string
}

interface RsvpManagementProps {
  tripId?: string
  trip?: TripDetails
  responses?: RsvpResponse[]
  currentUserId?: string
  onRsvpUpdate?: (tripId: string, userId: string, status: RsvpResponse['status'], data?: Partial<RsvpResponse>) => void
  onSendReminder?: (tripId: string, userIds: string[]) => void
  isOrganizer?: boolean
  isLoading?: boolean
