export function RsvpManagement({
  tripId = 'trip-1',
  trip = DEFAULT_TRIP,
  responses = DEFAULT_RESPONSES,
  currentUserId = 'user-1',
  onRsvpUpdate = (tripId, userId, status, data) => console.log('RSVP updated:', { tripId, userId, status, data }),
  onSendReminder = (tripId, userIds) => console.log('Reminder sent:', { tripId, userIds }),
  isOrganizer = true,
  isLoading = false
}: RsvpManagementProps = {}) {
  const [expandedResponse, setExpandedResponse] = useState<string | null>(null)
  const [showRsvpForm, setShowRsvpForm] = useState(false)
  const [rsvpFormData, setRsvpFormData] = useState({
    status: 'pending' as RsvpResponse['status'],
    notes: '',
    dietaryRestrictions: [] as string[],
    emergencyContact: { name: '', phone: '' }
  })
  const [error, setError] = useState<string | null>(null)

  const currentUserResponse = responses.find(r => r.userId === currentUserId)
  const acceptedCount = responses.filter(r => r.status === 'accepted').length
  const pendingCount = responses.filter(r => r.status === 'pending').length
  const spotsRemaining = trip.maxParticipants - acceptedCount

  const getStatusColor = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted': return 'bg-green-50 dark:bg-green-900/20 text-green-800 dark:text-green-200 border-green-200 dark:border-green-800'
      case 'declined': return 'bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 border-red-200 dark:border-red-800'
      case 'maybe': return 'bg-yellow-50 dark:bg-yellow-900/20 text-yellow-800 dark:text-yellow-200 border-yellow-200 dark:border-yellow-800'
      default: return 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground border-border dark:border-border'
    }
  }

  const getStatusIcon = (status: RsvpResponse['status']) => {
    switch (status) {
      case 'accepted': return <Check className="w-4 h-4" />
      case 'declined': return <X className="w-4 h-4" />
      case 'maybe': return <Clock className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  const handleRsvpSubmit = () => {
    try {
      onRsvpUpdate(tripId, currentUserId, rsvpFormData.status, {
        notes: rsvpFormData.notes,
        dietaryRestrictions: rsvpFormData.dietaryRestrictions,
        emergencyContact: rsvpFormData.emergencyContact,
        respondedAt: new Date()
      })
      setShowRsvpForm(false)
      setError(null)
    } catch (err) {
      setError('Failed to submit RSVP. Please try again.')
    }
  }

  const handleSendReminders = () => {
    try {
      const pendingUserIds = responses
        .filter(r => r.status === 'pending')
        .map(r => r.userId)
      onSendReminder(tripId, pendingUserIds)
      setError(null)
    } catch (err) {
      setError('Failed to send reminders. Please try again.')
    }
  }

  const toggleDietaryRestriction = (restriction: string) => {
    setRsvpFormData(prev => ({
      ...prev,
      dietaryRestrictions: prev.dietaryRestrictions.includes(restriction)
        ? prev.dietaryRestrictions.filter(r => r !== restriction)
        : [...prev.dietaryRestrictions, restriction]
    }))
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-background font-sans">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="space-y-6 animate-pulse">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6">
              <div className="h-8 bg-muted dark:bg-muted rounded w-3/4 mb-4"></div>
              <div className="h-4 bg-muted dark:bg-muted rounded w-1/2 mb-6"></div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="h-16 bg-muted dark:bg-muted rounded-lg"></div>
                ))}
              </div>
            </div>
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6">
              <div className="h-6 bg-muted dark:bg-muted rounded w-1/4 mb-4"></div>
              <div className="space-y-3">
                {[...Array(3)].map((_, i) => (
                  <div key={i} className="h-16 bg-muted dark:bg-muted rounded-lg"></div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {error && (
          <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 mb-6">
            <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
          </div>
        )}

        {/* Trip Header */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-foreground dark:text-foreground mb-2">{trip.title}</h1>
              <div className="flex items-center gap-4 text-mutedForeground dark:text-mutedForeground text-sm">
                <div className="flex items-center gap-1">
                  <MapPin className="w-4 h-4" />
                  {trip.location}
                </div>
                <div className="flex items-center gap-1">
                  <Calendar className="w-4 h-4" />
                  {trip.startDate.toLocaleDateString()} - {trip.endDate.toLocaleDateString()}
                </div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-2xl font-bold text-primary dark:text-primary">{acceptedCount}/{trip.maxParticipants}</div>
              <div className="text-xs text-mutedForeground dark:text-mutedForeground">confirmed</div>
            </div>
          </div>

          {/* RSVP Stats */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
            <div className="bg-muted dark:bg-muted rounded-lg p-3 text-center hover:scale-[1.02] transition-all duration-150">
              <div className="text-lg font-bold text-green-600 dark:text-green-400">{acceptedCount}</div>
              <div className="text-xs text-mutedForeground dark:text-mutedForeground">Going</div>
            </div>
            <div className="bg-muted dark:bg-muted rounded-lg p-3 text-center hover:scale-[1.02] transition-all duration-150">
              <div className="text-lg font-bold text-yellow-600 dark:text-yellow-400">{responses.filter(r => r.status === 'maybe').length}</div>
              <div className="text-xs text-mutedForeground dark:text-mutedForeground">Maybe</div>
            </div>
            <div className="bg-muted dark:bg-muted rounded-lg p-3 text-center hover:scale-[1.02] transition-all duration-150">
              <div className="text-lg font-bold text-red-600 dark:text-red-400">{responses.filter(r => r.status === 'declined').length}</div>
              <div className="text-xs text-mutedForeground dark:text-mutedForeground">Can't Go</div>
            </div>
            <div className="bg-muted dark:bg-muted rounded-lg p-3 text-center hover:scale-[1.02] transition-all duration-150">
              <div className="text-lg font-bold text-mutedForeground dark:text-mutedForeground">{pendingCount}</div>
              <div className="text-xs text-mutedForeground dark:text-mutedForeground">Pending</div>
            </div>
          </div>

          {/* Current User RSVP */}
          {!currentUserResponse && (
            <button
              onClick={() => setShowRsvpForm(true)}
              className="w-full px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2"
              aria-label="Respond to trip invitation"
            >
              Respond to Invitation
            </button>
          )}

          {currentUserResponse && (
            <div className="flex items-center justify-between p-4 bg-muted dark:bg-muted rounded-lg">
              <div className="flex items-center gap-3">
                <div className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(currentUserResponse.status)} flex items-center gap-1`}>
                  {getStatusIcon(currentUserResponse.status)}
                  {currentUserResponse.status.charAt(0).toUpperCase() + currentUserResponse.status.slice(1)}
                </div>
                <span className="text-mutedForeground dark:text-mutedForeground text-sm">Your Response</span>
              </div>
              <button
                onClick={() => setShowRsvpForm(true)}
                className="px-3 py-1 text-primary dark:text-primary hover:text-secondary dark:hover:text-secondary text-sm transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-1"
                aria-label="Change RSVP response"
              >
                Change
              </button>
            </div>
          )}
        </div>

        {/* Organizer Actions */}
        {isOrganizer && pendingCount > 0 && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4 mb-6 shadow-sm hover:shadow-md transition-all duration-300">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-foreground dark:text-foreground font-medium">Pending Responses</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">{pendingCount} people haven't responded yet</p>
              </div>
              <button
                onClick={handleSendReminders}
                className="px-4 py-2 bg-secondary dark:bg-secondary text-secondaryForeground dark:text-secondaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2"
                aria-label="Send reminder to pending users"
              >
                Send Reminders
              </button>
            </div>
          </div>
        )}

        {/* Responses List */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-foreground dark:text-foreground flex items-center gap-2">
              <Users className="w-5 h-5" />
              Responses
            </h2>
            {spotsRemaining > 0 && (
              <div className="text-primary dark:text-primary text-sm">
                {spotsRemaining} spots remaining
              </div>
            )}
          </div>

          {responses.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
              </div>
              <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No responses yet</h3>
              <p className="text-mutedForeground dark:text-mutedForeground text-sm">Invitations are still pending</p>
            </div>
          ) : (
            <div className="space-y-3">
              {responses.map((response) => (
                <div key={response.id} className="bg-muted dark:bg-muted rounded-lg border border-border dark:border-border hover:-translate-y-1 hover:shadow-lg transition-all duration-300">
                  <div className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        {response.userAvatar ? (
                          <img
                            src={response.userAvatar}
                            alt={response.userName}
                            className="w-10 h-10 rounded-full object-cover"
                          />
                        ) : (
                          <div className="w-10 h-10 bg-secondary dark:bg-secondary rounded-full flex items-center justify-center">
                            <span className="text-secondaryForeground dark:text-secondaryForeground text-sm font-medium">
                              {response.userName.charAt(0)}
                            </span>
                          </div>
                        )}
                        <div>
                          <div className="text-foreground dark:text-foreground font-medium">{response.userName}</div>
                          {response.respondedAt && (
                            <div className="text-mutedForeground dark:text-mutedForeground text-xs">
                              Responded {response.respondedAt.toLocaleDateString()}
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(response.status)} flex items-center gap-1`}>
                          {getStatusIcon(response.status)}
                          {response.status.charAt(0).toUpperCase() + response.status.slice(1)}
                        </div>
                        {(response.notes || response.dietaryRestrictions?.length || response.emergencyContact) && (
                          <button
                            onClick={() => setExpandedResponse(expandedResponse === response.id ? null : response.id)}
                            className="p-1 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-1"
                            aria-label={`${expandedResponse === response.id ? 'Hide' : 'Show'} response details`}
                          >
                            {expandedResponse === response.id ? (
                              <ChevronUp className="w-4 h-4" />
                            ) : (
                              <ChevronDown className="w-4 h-4" />
                            )}
                          </button>
                        )}
                      </div>
                    </div>

                    {expandedResponse === response.id && (
                      <div className="mt-4 pt-4 border-t border-border dark:border-border space-y-3">
                        {response.notes && (
                          <div>
                            <div className="text-mutedForeground dark:text-mutedForeground text-xs mb-1">Notes</div>
                            <div className="text-foreground dark:text-foreground text-sm">{response.notes}</div>
                          </div>
                        )}
                        {response.dietaryRestrictions?.length && (
                          <div>
                            <div className="text-mutedForeground dark:text-mutedForeground text-xs mb-1">Dietary Restrictions</div>
                            <div className="flex flex-wrap gap-1">
                              {response.dietaryRestrictions.map((restriction) => (
                                <span
                                  key={restriction}
                                  className="px-2 py-1 bg-yellow-50 dark:bg-yellow-900/20 text-yellow-800 dark:text-yellow-200 rounded text-xs"
                                >
                                  {restriction}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                        {response.emergencyContact && (
                          <div>
                            <div className="text-mutedForeground dark:text-mutedForeground text-xs mb-1">Emergency Contact</div>
                            <div className="text-foreground dark:text-foreground text-sm">
                              {response.emergencyContact.name} - {response.emergencyContact.phone}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* RSVP Form Modal */}
        {showRsvpForm && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 w-full max-w-md max-h-[90vh] overflow-y-auto shadow-xl">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-bold text-foreground dark:text-foreground">RSVP Response</h3>
                <button
                  onClick={() => setShowRsvpForm(false)}
                  className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-1"
                  aria-label="Close RSVP form"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-6">
                {/* Status Selection */}
                <div>
                  <label className="block text-foreground dark:text-foreground text-sm font-medium mb-3">
                    Will you be joining us?
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      { value: 'accepted', label: 'Yes, I\'m going!', icon: Check, color: 'green' },
                      { value: 'declined', label: 'Can\'t make it', icon: X, color: 'red' },
                      { value: 'maybe', label: 'Maybe', icon: Clock, color: 'yellow' }
                    ].map(({ value, label, icon: Icon, color }) => (
                      <button
                        key={value}
                        onClick={() => setRsvpFormData(prev => ({ ...prev, status: value as RsvpResponse['status'] }))}
                        className={`p-3 rounded-lg border-2 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-1 ${
                          rsvpFormData.status === value
                            ? `border-${color}-500 bg-${color}-50 dark:bg-${color}-900/20`
                            : 'border-border dark:border-border bg-muted dark:bg-muted hover:border-ring dark:hover:border-ring'
                        }`}
                        aria-label={`Select ${label}`}
                      >
                        <Icon className={`w-5 h-5 mx-auto mb-1 ${
                          rsvpFormData.status === value ? `text-${color}-600 dark:text-${color}-400` : 'text-mutedForeground dark:text-mutedForeground'
                        }`} />
                        <div className={`text-xs ${
                          rsvpFormData.status === value ? `text-${color}-600 dark:text-${color}-400` : 'text-mutedForeground dark:text-mutedForeground'
                        }`}>
                          {label}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div>
                  <label className="block text-foreground dark:text-foreground text-sm font-medium mb-2">
                    Notes (optional)
                  </label>
                  <textarea
                    value={rsvpFormData.notes}
                    onChange={(e) => setRsvpFormData(prev => ({ ...prev, notes: e.target.value }))}
                    placeholder="Any additional information..."
                    className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 resize-none"
                    rows={3}
                    aria-label="Additional notes"
                  />
                </div>

                {/* Dietary Restrictions */}
                <div>
                  <label className="block text-foreground dark:text-foreground text-sm font-medium mb-3">
                    Dietary Restrictions
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {['vegetarian', 'vegan', 'gluten-free', 'dairy-free', 'nut-free', 'other'].map((restriction) => (
                      <button
                        key={restriction}
                        onClick={() => toggleDietaryRestriction(restriction)}
                        className={`p-2 rounded-lg border text-xs transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-1 ${
