'use client'

import { useState, useEffect } from 'react'
import { Database, CheckCircle, AlertCircle, Settings, Eye, EyeOff, ChevronDown } from 'lucide-react'

interface SupabaseConfigProps {
  onConfigSave?: (config: SupabaseConfig) => void;
  initialConfig?: Partial<SupabaseConfig>;
  showAdvanced?: boolean;
}

interface SupabaseConfig {
  url: string;
  anonKey: string;
  serviceKey?: string;
  projectRef: string;
  region: string;
  enableRLS: boolean;
  enableRealtimeAuth: boolean;
}

export function SupabaseConfig({
  onConfigSave = () => console.log('Config saved'),
  initialConfig = {},
  showAdvanced = false
}: SupabaseConfigProps = {}) {
  const [config, setConfig] = useState<SupabaseConfig>({
    url: initialConfig.url || '',
    anonKey: initialConfig.anonKey || '',
    serviceKey: initialConfig.serviceKey || '',
    projectRef: initialConfig.projectRef || '',
    region: initialConfig.region || 'us-east-1',
    enableRLS: initialConfig.enableRLS ?? true,
    enableRealtimeAuth: initialConfig.enableRealtimeAuth ?? true,
  });

  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [showKeys, setShowKeys] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(showAdvanced);

  const validateConfig = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!config.url) {
      newErrors.url = 'Supabase URL is required';
    } else if (!config.url.includes('supabase.co')) {
      newErrors.url = 'Invalid Supabase URL format';
    }

    if (!config.anonKey) {
      newErrors.anonKey = 'Anonymous key is required';
    } else if (config.anonKey.length < 100) {
      newErrors.anonKey = 'Invalid anonymous key format';
    }

    if (!config.projectRef) {
      newErrors.projectRef = 'Project reference is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const testConnection = async () => {
    if (!validateConfig()) return;

    setConnectionStatus('testing');

    setTimeout(() => {
      const isValid = config.url && config.anonKey && config.projectRef;
      setConnectionStatus(isValid ? 'success' : 'error');
    }, 2000);
  };

  const handleSave = () => {
    if (validateConfig()) {
      onConfigSave(config);
      setConnectionStatus('success');
    }
  };

  const regions = [
    { value: 'us-east-1', label: 'US East (N. Virginia)' },
    { value: 'us-west-1', label: 'US West (N. California)' },
    { value: 'eu-west-1', label: 'Europe (Ireland)' },
    { value: 'ap-southeast-1', label: 'Asia Pacific (Singapore)' },
  ];

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border shadow-lg hover:shadow-xl transition-all duration-300">
          <div className="p-6 border-b border-border dark:border-border">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-primary/10 dark:bg-primary/20 rounded-lg">
                <Database className="w-6 h-6 text-primary dark:text-primary" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-foreground dark:text-foreground">Supabase Configuration</h1>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm mt-1">Configure your Supabase connection for the off-road trip planner</p>
              </div>
            </div>
          </div>

          {connectionStatus !== 'idle' && (
            <div className="p-4 mx-6 mt-6 rounded-lg border border-border dark:border-border bg-muted/50 dark:bg-muted/50">
              <div className="flex items-center gap-3">
                {connectionStatus === 'testing' && (
                  <>
                    <div className="w-4 h-4 border-2 border-primary dark:border-primary border-t-transparent rounded-full animate-spin" />
                    <span className="text-foreground dark:text-foreground text-sm">Testing connection...</span>
                  </>
                )}
                {connectionStatus === 'success' && (
                  <>
                    <CheckCircle className="w-5 h-5 text-primary dark:text-primary" />
                    <span className="text-primary dark:text-primary text-sm">Connection successful!</span>
                  </>
                )}
                {connectionStatus === 'error' && (
                  <>
                    <AlertCircle className="w-5 h-5 text-destructive dark:text-destructive" />
                    <span className="text-destructive dark:text-destructive text-sm">Connection failed. Please check your configuration.</span>
                  </>
                )}
              </div>
            </div>
          )}

          <div className="p-6 space-y-6">
            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Project URL *
              </label>
              <input
                type="url"
                value={config.url}
                onChange={(e) => setConfig(prev => ({ ...prev, url: e.target.value }))}
                placeholder="https://your-project.supabase.co"
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                aria-label="Supabase project URL"
              />
              {errors.url && (
                <p className="text-destructive dark:text-destructive text-sm mt-1">{errors.url}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Anonymous Key *
              </label>
              <div className="relative">
                <input
                  type={showKeys ? 'text' : 'password'}
                  value={config.anonKey}
                  onChange={(e) => setConfig(prev => ({ ...prev, anonKey: e.target.value }))}
                  placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
                  className="w-full px-4 py-3 pr-12 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                  aria-label="Supabase anonymous key"
                />
                <button
                  type="button"
                  onClick={() => setShowKeys(!showKeys)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 rounded"
                  aria-label={showKeys ? 'Hide keys' : 'Show keys'}
                >
                  {showKeys ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
              {errors.anonKey && (
                <p className="text-destructive dark:text-destructive text-sm mt-1">{errors.anonKey}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Project Reference *
              </label>
              <input
                type="text"
                value={config.projectRef}
                onChange={(e) => setConfig(prev => ({ ...prev, projectRef: e.target.value }))}
                placeholder="abcdefghijklmnop"
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                aria-label="Supabase project reference"
              />
              {errors.projectRef && (
                <p className="text-destructive dark:text-destructive text-sm mt-1">{errors.projectRef}</p>
              )}
            </div>

            <button
              type="button"
              onClick={() => setIsAdvancedOpen(!isAdvancedOpen)}
              className="flex items-center gap-2 text-primary dark:text-primary hover:text-primary/80 dark:hover:text-primary/80 transition-colors duration-150 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 rounded p-1"
              aria-expanded={isAdvancedOpen}
              aria-label="Toggle advanced settings"
            >
              <Settings className="w-4 h-4" />
              Advanced Settings
              <ChevronDown className={`w-4 h-4 transition-transform duration-200 ${isAdvancedOpen ? 'rotate-180' : ''}`} />
            </button>

            {isAdvancedOpen && (
              <div className="space-y-6 pt-4 border-t border-border dark:border-border">
                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Region
                  </label>
                  <select
                    value={config.region}
                    onChange={(e) => setConfig(prev => ({ ...prev, region: e.target.value }))}
                    className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                    aria-label="Supabase region"
                  >
                    {regions.map(region => (
                      <option key={region.value} value={region.value} className="bg-background dark:bg-background text-foreground dark:text-foreground">
                        {region.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Service Role Key (Optional)
                  </label>
                  <input
                    type={showKeys ? 'text' : 'password'}
                    value={config.serviceKey}
                    onChange={(e) => setConfig(prev => ({ ...prev, serviceKey: e.target.value }))}
                    placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
                    className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 hover:border-ring/50 dark:hover:border-ring/50"
                    aria-label="Supabase service role key"
                  />
                  <p className="text-mutedForeground dark:text-mutedForeground text-xs mt-1">Only required for admin operations</p>
                </div>

                <div className="space-y-4">
                  <h3 className="text-sm font-medium text-foreground dark:text-foreground">Security Settings</h3>

                  <label className="flex items-start gap-3 cursor-pointer group">
                    <input
                      type="checkbox"
                      checked={config.enableRLS}
                      onChange={(e) => setConfig(prev => ({ ...prev, enableRLS: e.target.checked }))}
                      className="w-4 h-4 mt-0.5 text-primary dark:text-primary bg-background dark:bg-background border-border dark:border-border rounded focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-150"
                    />
                    <div className="group-hover:text-foreground/80 dark:group-hover:text-foreground/80 transition-colors duration-150">
                      <span className="text-foreground dark:text-foreground text-sm">Enable Row Level Security (RLS)</span>
                      <p className="text-mutedForeground dark:text-mutedForeground text-xs">Recommended for production environments</p>
                    </div>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer group">
                    <input
                      type="checkbox"
                      checked={config.enableRealtimeAuth}
                      onChange={(e) => setConfig(prev => ({ ...prev, enableRealtimeAuth: e.target.checked }))}
                      className="w-4 h-4 mt-0.5 text-primary dark:text-primary bg-background dark:bg-background border-border dark:border-border rounded focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-150"
                    />
                    <div className="group-hover:text-foreground/80 dark:group-hover:text-foreground/80 transition-colors duration-150">
                      <span className="text-foreground dark:text-foreground text-sm">Enable Realtime Authentication</span>
                      <p className="text-mutedForeground dark:text-mutedForeground text-xs">Required for live chat and updates</p>
                    </div>
                  </label>
                </div>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-3 pt-6 border-t border-border dark:border-border">
              <button
                type="button"
                onClick={testConnection}
                disabled={connectionStatus === 'testing'}
                className="flex-1 px-4 py-3 bg-muted dark:bg-muted text-foreground dark:text-foreground rounded-lg hover:bg-muted/80 dark:hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 shadow-sm hover:shadow-md"
                aria-label="Test database connection"
              >
                {connectionStatus === 'testing' ? 'Testing...' : 'Test Connection'}
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="flex-1 px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:bg-primary/90 dark:hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                aria-label="Save configuration"
              >
                Save Configuration
              </button>
            </div>
          </div>
        </div>

        <div className="mt-6 p-4 bg-surface/50 dark:bg-surface/50 rounded-lg border border-border dark:border-border hover:bg-surface/70 dark:hover:bg-surface/70 transition-colors duration-200">
          <h3 className="text-sm font-medium text-foreground dark:text-foreground mb-2">Need Help?</h3>
          <p className="text-mutedForeground dark:text-mutedForeground text-xs leading-relaxed">
            Find your Supabase credentials in your project dashboard under Settings → API. 
            The URL and anonymous key are safe to use in client-side code. Keep your service role key secure.
          </p>
        </div>
      </div>
    </div>
  );
}

export default function SupabaseConfigDemo() {
  return (
    <SupabaseConfig
      onConfigSave={(config) => console.log('Configuration saved:', config)}
      showAdvanced={false}
    />
  );
}

