'use client'

import { useState, useEffect } from 'react'
import { 
  Map, 
  Calendar, 
  Users, 
  MessageCircle, 
  UtensilsCrossed, 
  Settings,
  Menu,
  X,
  Bell,
  Search,
  Plus
} from 'lucide-react'

interface AppLayoutProps {
  children?: React.ReactNode;
  currentPage?: string;
  notifications?: number;
  userName?: string;
  userAvatar?: string;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  href: string;
  badge?: number;
}

export function AppLayout({
  children,
  currentPage = 'trips',
  notifications = 3,
  userName = 'Trail Explorer',
  userAvatar = '/api/placeholder/32/32'
}: AppLayoutProps = {}) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isSearchOpen, setIsSearchOpen] = useState(false)

  const navigationItems: NavigationItem[] = [
    { id: 'trips', label: 'Trips', icon: Map, href: '/trips' },
    { id: 'calendar', label: 'Calendar', icon: Calendar, href: '/calendar' },
    { id: 'group', label: 'Group', icon: Users, href: '/group' },
    { id: 'chat', label: 'Chat', icon: MessageCircle, href: '/chat', badge: 2 },
    { id: 'meals', label: 'Meals', icon: UtensilsCrossed, href: '/meals' },
    { id: 'settings', label: 'Settings', icon: Settings, href: '/settings' }
  ]

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement
      if (isMobileMenuOpen && !target.closest('.mobile-menu') && !target.closest('.menu-button')) {
        setIsMobileMenuOpen(false)
      }
    }

    document.addEventListener('click', handleClickOutside)
    return () => document.removeEventListener('click', handleClickOutside)
  }, [isMobileMenuOpen])

  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = 'unset'
    }

    return () => {
      document.body.style.overflow = 'unset'
    }
  }, [isMobileMenuOpen])

  const handleNavigation = (href: string) => {
    console.log(`Navigating to: ${href}`)
    setIsMobileMenuOpen(false)
  }

  const handleSearch = (query: string) => {
    console.log(`Searching for: ${query}`)
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <header className="sticky top-0 z-50 bg-surface/95 dark:bg-surface/95 backdrop-blur-sm border-b border-border dark:border-border">
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="menu-button p-2 text-mutedForeground hover:text-foreground hover:bg-muted rounded-lg transition-all duration-150 lg:hidden hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label="Toggle menu"
            >
              {isMobileMenuOpen ? (
                <X className="w-5 h-5" />
              ) : (
                <Menu className="w-5 h-5" />
              )}
            </button>

            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-gradient-to-br from-primary to-primary/80 rounded-lg flex items-center justify-center shadow-sm">
                <Map className="w-5 h-5 text-primaryForeground" />
              </div>
              <span className="text-foreground font-semibold text-lg hidden sm:block">
                TrailPlan
              </span>
            </div>
          </div>

          <div className="hidden md:flex flex-1 max-w-md mx-8">
            <div className="relative w-full">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-mutedForeground" />
              <input
                type="text"
                placeholder="Search trips, locations..."
                className="w-full pl-10 pr-4 py-2 bg-surface border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                onChange={(e) => handleSearch(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsSearchOpen(!isSearchOpen)}
              className="p-2 text-mutedForeground hover:text-foreground hover:bg-muted rounded-lg transition-all duration-150 md:hidden hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label="Search"
            >
              <Search className="w-5 h-5" />
            </button>

            <button
              onClick={() => console.log('Quick add trip')}
              className="p-2 text-mutedForeground hover:text-foreground hover:bg-muted rounded-lg transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label="Add new trip"
            >
              <Plus className="w-5 h-5" />
            </button>

            <button
              onClick={() => console.log('Show notifications')}
              className="relative p-2 text-mutedForeground hover:text-foreground hover:bg-muted rounded-lg transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label={`${notifications} notifications`}
            >
              <Bell className="w-5 h-5" />
              {notifications > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-accent text-accentForeground text-xs rounded-full flex items-center justify-center font-semibold shadow-md">
                  {notifications > 9 ? '9+' : notifications}
                </span>
              )}
            </button>

            <button
              onClick={() => console.log('Show profile menu')}
              className="flex items-center gap-2 p-1 hover:bg-muted rounded-lg transition-all duration-150 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring/50"
              aria-label="User menu"
            >
              <img
                src={userAvatar}
                alt={userName}
                className="w-8 h-8 rounded-full border-2 border-border shadow-sm"
              />
              <span className="text-foreground text-sm hidden sm:block max-w-24 truncate font-medium">
                {userName}
              </span>
            </button>
          </div>
        </div>

        {isSearchOpen && (
          <div className="px-4 pb-3 md:hidden">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-mutedForeground" />
              <input
                type="text"
                placeholder="Search trips, locations..."
                className="w-full pl-10 pr-4 py-2 bg-surface border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                onChange={(e) => handleSearch(e.target.value)}
                autoFocus
              />
            </div>
          </div>
        )}
      </header>

      <div className="flex min-h-[calc(100vh-73px)]">
        <aside className="hidden lg:flex flex-col w-64 bg-surface border-r border-border">
          <nav className="flex-1 p-4">
            <ul className="space-y-2">
              {navigationItems.map((item) => {
                const isActive = currentPage === item.id
                return (
                  <li key={item.id}>
