'use client'

import { useState, useEffect } from 'react'
import { User, Shield, Key, LogOut, AlertCircle, CheckCircle } from 'lucide-react'

interface AuthUser {
  id: string
  email: string
  name: string
  avatar?: string
  role: 'admin' | 'member' | 'guest'
  lastLogin: Date
  isOnline: boolean
}

interface AuthSession {
  user: AuthUser | null
  token: string | null
  expiresAt: Date | null
  isLoading: boolean
  error: string | null
}

interface AuthHelpersProps {
  onAuthChange?: (session: AuthSession) => void
  redirectPath?: string
  showUserInfo?: boolean
}

export function AuthHelpers({
  onAuthChange = () => {},
  redirectPath = '/dashboard',
  showUserInfo = true
}: AuthHelpersProps = {}) {
  const [session, setSession] = useState<AuthSession>({
    user: null,
    token: null,
    expiresAt: null,
    isLoading: true,
    error: null
  })

  const [showTokenInfo, setShowTokenInfo] = useState(false)

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('auth_token')
        if (token) {
          const mockUser: AuthUser = {
            id: '1',
            email: 'trail.rider@example.com',
            name: 'Trail Rider',
            avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face',
            role: 'admin',
            lastLogin: new Date(),
            isOnline: true
          }

          const newSession: AuthSession = {
            user: mockUser,
            token,
            expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
            isLoading: false,
            error: null
          }

          setSession(newSession)
          onAuthChange(newSession)
        } else {
          setSession(prev => ({ ...prev, isLoading: false }))
        }
      } catch (error) {
        setSession(prev => ({
          ...prev,
          isLoading: false,
          error: 'Failed to authenticate'
        }))
      }
    }

    checkAuth()
  }, [onAuthChange])

  const signIn = async (email: string, password: string) => {
    setSession(prev => ({ ...prev, isLoading: true, error: null }))

    try {
      await new Promise(resolve => setTimeout(resolve, 1000))

      const token = 'mock_jwt_token_' + Date.now()
      localStorage.setItem('auth_token', token)

      const mockUser: AuthUser = {
        id: '1',
        email,
        name: email.split('@')[0],
        role: 'member',
        lastLogin: new Date(),
        isOnline: true
      }

      const newSession: AuthSession = {
        user: mockUser,
        token,
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
        isLoading: false,
        error: null
      }

      setSession(newSession)
      onAuthChange(newSession)

      window.location.href = redirectPath
    } catch (error) {
      setSession(prev => ({
        ...prev,
        isLoading: false,
        error: 'Invalid credentials'
      }))
    }
  }

  const signOut = async () => {
    try {
      localStorage.removeItem('auth_token')
      const newSession: AuthSession = {
        user: null,
        token: null,
        expiresAt: null,
        isLoading: false,
        error: null
      }

      setSession(newSession)
      onAuthChange(newSession)

      window.location.href = '/login'
    } catch (error) {
      console.error('Sign out error:', error)
    }
  }

  const refreshToken = async () => {
    if (!session.token) return

    try {
      const newToken = 'refreshed_token_' + Date.now()
      localStorage.setItem('auth_token', newToken)

      setSession(prev => ({
        ...prev,
        token: newToken,
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000)
      }))
    } catch (error) {
      console.error('Token refresh failed:', error)
      signOut()
    }
  }

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin':
        return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      case 'member':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'guest':
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
      default:
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const formatTimeRemaining = (expiresAt: Date | null) => {
    if (!expiresAt) return 'No expiration'

    const now = new Date()
    const diff = expiresAt.getTime() - now.getTime()

    if (diff <= 0) return 'Expired'

    const hours = Math.floor(diff / (1000 * 60 * 60))
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))

    return `${hours}h ${minutes}m remaining`
  }

  if (session.isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-background to-surface dark:from-background dark:to-surface flex items-center justify-center p-4" style={{ fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif' }}>
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-8 max-w-md w-full shadow-lg">
          <div className="animate-pulse space-y-4">
            <div className="h-4 bg-muted dark:bg-muted rounded w-3/4"></div>
            <div className="h-4 bg-muted dark:bg-muted rounded w-1/2"></div>
            <div className="h-10 bg-muted dark:bg-muted rounded"></div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-surface dark:from-background dark:to-surface p-4" style={{ fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif' }}>
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center gap-3 mb-4">
            <Shield className="w-6 h-6 text-primary dark:text-primary" />
            <h1 className="text-xl font-semibold text-foreground dark:text-foreground" style={{ fontSize: '1.25rem', fontWeight: 600 }}>Authentication Helper</h1>
          </div>
          <p className="text-mutedForeground dark:text-mutedForeground text-sm" style={{ fontSize: '0.875rem', lineHeight: 1.5 }}>
            Manage authentication state and user sessions for your off-road trip planning app
          </p>
        </div>

        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-medium text-foreground dark:text-foreground" style={{ fontSize: '1.125rem', fontWeight: 500 }}>Authentication Status</h2>
            <div className="flex items-center gap-2">
              {session.user ? (
                <CheckCircle className="w-5 h-5 text-primary dark:text-primary" />
              ) : (
                <AlertCircle className="w-5 h-5 text-destructive dark:text-destructive" />
              )}
              <span className={`text-sm font-medium ${
                session.user ? 'text-primary dark:text-primary' : 'text-destructive dark:text-destructive'
              }`} style={{ fontSize: '0.875rem', fontWeight: 500 }}>
