              <p className="text-destructive dark:text-destructive text-sm" style={{ fontSize: '0.875rem' }}>{session.error}</p>
            </div>
          )}

          {session.user && showUserInfo && (
            <div className="space-y-4">
              <div className="flex items-center gap-4 p-4 bg-muted/50 dark:bg-muted/50 rounded-lg hover:bg-muted/70 dark:hover:bg-muted/70 transition-all duration-200">
                {session.user.avatar ? (
