                <MapPin className="w-6 h-6 text-primary dark:text-primary" />
              </div>
              <p className="text-xs text-mutedForeground dark:text-mutedForeground">Save Locations</p>
            </div>
            <div className="text-center">
              <div className="w-12 h-12 bg-primary/10 dark:bg-primary/20 rounded-xl flex items-center justify-center mx-auto mb-2 hover:bg-primary/20 dark:hover:bg-primary/30 transition-all duration-200 hover:scale-105">
                <Users className="w-6 h-6 text-primary dark:text-primary" />
              </div>
