                      errors.firstName ? 'border-destructive dark:border-destructive' : 'border-border dark:border-border'
                    }`}
                    placeholder="John"
                    aria-describedby={errors.firstName ? 'firstName-error' : undefined}
                  />
                  {errors.firstName && (
