                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  className={`w-full px-4 py-3 bg-background dark:bg-background border rounded-xl text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring transition-all duration-200 hover:border-primary/50 dark:hover:border-primary/50 ${
