'use client'

import { useState, useEffect } from 'react'
import { Check, X, Clock, Users, MapPin, Calendar, MessageCircle } from 'lucide-react'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'organizer' | 'member'
}

interface Trip {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  description: string
  organizerId: string
}

interface RSVPResponse {
  id: string
  memberId: string
  tripId: string
  status: 'pending' | 'accepted' | 'declined' | 'maybe'
  respondedAt?: string
  notes?: string
}

interface RSVPManagementProps {
  trip?: Trip
  members?: GroupMember[]
  responses?: RSVPResponse[]
  currentUserId?: string
  onUpdateRSVP?: (memberId: string, status: RSVPResponse['status'], notes?: string) => void
  onSendReminder?: (memberIds: string[]) => void
}

const DEFAULT_TRIP: Trip = {
  id: '1',
  title: 'Moab Desert Adventure',
  location: 'Moab, Utah',
  startDate: '2024-03-15',
  endDate: '2024-03-17',
  description: 'Epic off-road adventure through the red rocks of Moab',
  organizerId: '1'
}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', email: 'alex@example.com', role: 'organizer' },
  { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', role: 'member' },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', role: 'member' },
  { id: '4', name: 'Emily Davis', email: 'emily@example.com', role: 'member' },
  { id: '5', name: 'Tom Wilson', email: 'tom@example.com', role: 'member' }
]

const DEFAULT_RESPONSES: RSVPResponse[] = [
  { id: '1', memberId: '1', tripId: '1', status: 'accepted', respondedAt: '2024-02-20T10:00:00Z' },
  { id: '2', memberId: '2', tripId: '1', status: 'accepted', respondedAt: '2024-02-21T14:30:00Z', notes: 'Excited for this trip!' },
  { id: '3', memberId: '3', tripId: '1', status: 'maybe', respondedAt: '2024-02-22T09:15:00Z', notes: 'Need to check work schedule' },
  { id: '4', memberId: '4', tripId: '1', status: 'pending' },
  { id: '5', memberId: '5', tripId: '1', status: 'declined', respondedAt: '2024-02-23T16:45:00Z', notes: 'Family commitment that weekend' }
]

export function RSVPManagement({
  trip = DEFAULT_TRIP,
  members = DEFAULT_MEMBERS,
  responses = DEFAULT_RESPONSES,
  currentUserId = '1',
  onUpdateRSVP = () => console.log('RSVP updated'),
  onSendReminder = () => console.log('Reminder sent')
}: RSVPManagementProps = {}) {
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [showNotes, setShowNotes] = useState<string | null>(null)
  const [rsvpNotes, setRsvpNotes] = useState('')
  const [filter, setFilter] = useState<'all' | 'pending' | 'accepted' | 'declined' | 'maybe'>('all')

  const getMemberResponse = (memberId: string) => {
    return responses.find(r => r.memberId === memberId)
  }

  const getStatusColor = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'accepted': return 'bg-primary/20 text-primary dark:bg-primary/20 dark:text-primary border-primary/30'
      case 'declined': return 'bg-destructive/20 text-destructive dark:bg-destructive/20 dark:text-destructive border-destructive/30'
      case 'maybe': return 'bg-accent/20 text-accent dark:bg-accent/20 dark:text-accent border-accent/30'
      default: return 'bg-muted/20 text-mutedForeground dark:bg-muted/20 dark:text-mutedForeground border-border'
    }
  }

  const getStatusIcon = (status: RSVPResponse['status']) => {
    switch (status) {
      case 'accepted': return <Check className="w-4 h-4" />
      case 'declined': return <X className="w-4 h-4" />
      case 'maybe': return <Clock className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  const filteredMembers = members.filter(member => {
    if (filter === 'all') return true
    const response = getMemberResponse(member.id)
    const status = response?.status || 'pending'
    return status === filter
  })

  const stats = {
    total: members.length,
    accepted: responses.filter(r => r.status === 'accepted').length,
    declined: responses.filter(r => r.status === 'declined').length,
    maybe: responses.filter(r => r.status === 'maybe').length,
    pending: members.length - responses.length
  }

  const handleRSVPUpdate = (memberId: string, status: RSVPResponse['status']) => {
    onUpdateRSVP(memberId, status, rsvpNotes)
    setShowNotes(null)
    setRsvpNotes('')
  }

  const handleSendReminders = () => {
    const pendingMembers = members
      .filter(member => !getMemberResponse(member.id))
      .map(member => member.id)

    if (pendingMembers.length > 0) {
      onSendReminder(pendingMembers)
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    })
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <div className="bg-surface dark:bg-surface rounded-xl border border-border p-6 mb-6 shadow-lg hover:shadow-xl transition-all duration-300">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h1 className="text-2xl font-semibold text-foreground dark:text-foreground mb-2 leading-tight">{trip.title}</h1>
              <div className="flex items-center gap-4 text-mutedForeground text-sm">
                <div className="flex items-center gap-1">
                  <MapPin className="w-4 h-4" />
                  <span>{trip.location}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Calendar className="w-4 h-4" />
                  <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
                </div>
              </div>
            </div>
            <button
              onClick={handleSendReminders}
              className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 font-medium text-sm shadow-md hover:shadow-lg"
              aria-label="Send reminders to pending members"
            >
              Send Reminders
            </button>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
            <div className="bg-muted/50 dark:bg-muted/50 rounded-lg p-3 text-center border border-border">
              <div className="text-lg font-semibold text-foreground dark:text-foreground">{stats.total}</div>
              <div className="text-xs text-mutedForeground">Total</div>
            </div>
            <div className="bg-primary/20 dark:bg-primary/20 rounded-lg p-3 text-center border border-primary/30">
              <div className="text-lg font-semibold text-primary dark:text-primary">{stats.accepted}</div>
              <div className="text-xs text-primary dark:text-primary">Going</div>
            </div>
            <div className="bg-accent/20 dark:bg-accent/20 rounded-lg p-3 text-center border border-accent/30">
              <div className="text-lg font-semibold text-accent dark:text-accent">{stats.maybe}</div>
              <div className="text-xs text-accent dark:text-accent">Maybe</div>
            </div>
            <div className="bg-destructive/20 dark:bg-destructive/20 rounded-lg p-3 text-center border border-destructive/30">
              <div className="text-lg font-semibold text-destructive dark:text-destructive">{stats.declined}</div>
              <div className="text-xs text-destructive dark:text-destructive">Can't Go</div>
            </div>
            <div className="bg-muted/20 dark:bg-muted/20 rounded-lg p-3 text-center border border-border">
              <div className="text-lg font-semibold text-mutedForeground">{stats.pending}</div>
              <div className="text-xs text-mutedForeground">Pending</div>
            </div>
          </div>
        </div>

        <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
          {(['all', 'pending', 'accepted', 'maybe', 'declined'] as const).map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-4 py-2 rounded-lg font-medium text-sm whitespace-nowrap transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                filter === status
                  ? 'bg-primary text-primaryForeground shadow-md'
                  : 'bg-surface dark:bg-surface text-foreground dark:text-foreground hover:bg-muted dark:hover:bg-muted border border-border'
              }`}
              aria-label={`Filter by ${status} responses`}
            >
              {status.charAt(0).toUpperCase() + status.slice(1)}
            </button>
          ))}
        </div>

        <div className="space-y-3">
          {filteredMembers.map((member) => {
            const response = getMemberResponse(member.id)
            const status = response?.status || 'pending'
            const isCurrentUser = member.id === currentUserId

            return (
              <div
                key={member.id}
                className="bg-surface dark:bg-surface rounded-xl border border-border p-4 hover:border-primary/50 hover:-translate-y-1 hover:shadow-xl transition-all duration-300 shadow-sm"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-full flex items-center justify-center text-primaryForeground font-medium">
                      {member.name.charAt(0)}
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium text-foreground dark:text-foreground">{member.name}</span>
                        {member.role === 'organizer' && (
                          <span className="px-2 py-1 bg-secondary/20 text-secondary rounded-full text-xs font-medium border border-secondary/30">
                            Organizer
                          </span>
                        )}
                      </div>
                      <div className="text-sm text-mutedForeground">{member.email}</div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <div className={`px-3 py-1 rounded-full text-xs font-medium border flex items-center gap-1 ${getStatusColor(status)}`}>
                      {getStatusIcon(status)}
                      <span className="capitalize">{status}</span>
                    </div>

                    {isCurrentUser && status === 'pending' && (
                      <div className="flex gap-2">
                        <button
                          onClick={() => handleRSVPUpdate(member.id, 'accepted')}
                          className="px-3 py-1 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 text-sm font-medium"
                          aria-label="Accept invitation"
                        >
                          Accept
                        </button>
                        <button
                          onClick={() => handleRSVPUpdate(member.id, 'maybe')}
                          className="px-3 py-1 bg-accent text-accentForeground rounded-lg hover:bg-accent/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 text-sm font-medium"
                          aria-label="Mark as maybe"
                        >
                          Maybe
                        </button>
                        <button
                          onClick={() => setShowNotes(member.id)}
                          className="px-3 py-1 bg-destructive text-destructiveForeground rounded-lg hover:bg-destructive/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 text-sm font-medium"
                          aria-label="Decline invitation"
                        >
                          Decline
                        </button>
                      </div>
                    )}

                    {response?.notes && (
                      <button
                        onClick={() => setShowNotes(showNotes === member.id ? null : member.id)}
                        className="p-2 text-mutedForeground hover:text-foreground hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 rounded-lg"
                        aria-label="View notes"
                      >
                        <MessageCircle className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                {response?.respondedAt && (
                  <div className="mt-2 text-xs text-mutedForeground">
                    Responded {new Date(response.respondedAt).toLocaleDateString()}
                  </div>
                )}

                {showNotes === member.id && response?.notes && (
                  <div className="mt-3 p-3 bg-muted/50 dark:bg-muted/50 rounded-lg border border-border">
                    <div className="text-sm text-foreground dark:text-foreground">{response.notes}</div>
                  </div>
                )}

                {showNotes === member.id && !response?.notes && (
                  <div className="mt-3 space-y-3">
                    <textarea
                      value={rsvpNotes}
                      onChange={(e) => setRsvpNotes(e.target.value)}
                      placeholder="Add a note (optional)..."
                      className="w-full px-3 py-2 bg-background dark:bg-background border border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 text-sm font-sans"
                      rows={3}
                    />
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleRSVPUpdate(member.id, 'declined')}
                        className="px-4 py-2 bg-destructive text-destructiveForeground rounded-lg hover:bg-destructive/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 font-medium text-sm"
                      >
                        Decline
                      </button>
                      <button
                        onClick={() => setShowNotes(null)}
                        className="px-4 py-2 bg-muted text-mutedForeground rounded-lg hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 transition-all duration-150 font-medium text-sm"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )
          })}
        </div>

        {filteredMembers.length === 0 && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border p-8 text-center">
            <div className="w-16 h-16 bg-muted/50 dark:bg-muted/50 rounded-full mx-auto mb-4 flex items-center justify-center">
              <Users className="w-8 h-8 text-mutedForeground" />
            </div>
            <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No members found</h3>
            <p className="text-mutedForeground text-sm">Try adjusting your filter to see more results.</p>
          </div>
        )}
      </div>
    </div>
  )
}

export default function RSVPManagementDemo() {
  return <RSVPManagement />
}

