'use client'

import { useState } from 'react'
import { User, Mail, Phone, MapPin, Bell, Shield, Camera, Save, Edit3 } from 'lucide-react'

interface UserProfile {
  id: string
  name: string
  email: string
  phone: string
  location: string
  avatar?: string
  emergencyContact: {
    name: string
    phone: string
    relationship: string
  }
  preferences: {
    notifications: {
      tripInvites: boolean
      taskAssignments: boolean
      weatherAlerts: boolean
      groupMessages: boolean
    }
    privacy: {
      showLocation: boolean
      showPhone: boolean
      showEmail: boolean
    }
  }
}

interface ProfileSettingsProps {
  profile?: UserProfile
  onSave?: (profile: UserProfile) => void
}

export function ProfileSettings({
  profile = DEFAULT_PROFILE,
  onSave = () => console.log('Profile saved')
}: ProfileSettingsProps = {}) {
  const [editingProfile, setEditingProfile] = useState(profile)
  const [isEditing, setIsEditing] = useState(false)
  const [isSaving, setIsSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = async () => {
    setIsSaving(true)
    setError(null)
    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onSave(editingProfile)
      setIsEditing(false)
    } catch (error) {
      setError('Failed to save profile. Please try again.')
      console.error('Failed to save profile:', error)
    } finally {
      setIsSaving(false)
    }
  }

  const handleCancel = () => {
    setEditingProfile(profile)
    setIsEditing(false)
    setError(null)
  }

  const updateProfile = (field: string, value: any) => {
    setEditingProfile(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const updateNestedField = (section: string, field: string, value: any) => {
    setEditingProfile(prev => ({
      ...prev,
      [section]: {
        ...prev[section as keyof UserProfile],
        [field]: value
      }
    }))
  }

  const updateNotificationPreference = (key: string, value: boolean) => {
    setEditingProfile(prev => ({
      ...prev,
      preferences: {
        ...prev.preferences,
        notifications: {
          ...prev.preferences.notifications,
          [key]: value
        }
      }
    }))
  }

  const updatePrivacyPreference = (key: string, value: boolean) => {
    setEditingProfile(prev => ({
      ...prev,
      preferences: {
        ...prev.preferences,
        privacy: {
          ...prev.preferences.privacy,
          [key]: value
        }
      }
    }))
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background transition-colors duration-300">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6 font-sans">
        {error && (
          <div className="mb-6 rounded-lg bg-destructive/10 border border-destructive/20 p-4">
            <p className="text-sm text-destructive">{error}</p>
          </div>
        )}

        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-4xl font-bold text-foreground mb-2">Profile Settings</h1>
            <p className="text-mutedForeground">Manage your account and preferences</p>
          </div>
          <div className="flex gap-3">
            {isEditing ? (
              <>
                <button
                  onClick={handleCancel}
                  className="px-4 py-2 bg-surface border border-border text-mutedForeground rounded-lg hover:bg-muted hover:text-foreground focus:outline-none focus:ring-2 focus:ring-ring/50 focus:border-ring transition-all duration-200 font-medium text-sm"
                  aria-label="Cancel editing"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSave}
                  disabled={isSaving}
                  className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-medium text-sm shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center gap-2 min-w-[100px]"
                  aria-label="Save profile changes"
                >
                  {isSaving ? (
                    <div className="w-4 h-4 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                  ) : (
                    <Save className="w-4 h-4" />
                  )}
                  {isSaving ? 'Saving...' : 'Save'}
                </button>
              </>
            ) : (
              <button
                onClick={() => setIsEditing(true)}
                className="px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-medium text-sm shadow-md hover:shadow-lg flex items-center gap-2"
                aria-label="Edit profile"
              >
                <Edit3 className="w-4 h-4" />
                Edit Profile
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-surface border border-border rounded-xl p-6 shadow-sm hover:shadow-md hover:-translate-y-1 transition-all duration-300">
              <h2 className="text-xl font-semibold text-foreground mb-6 flex items-center gap-2">
                <User className="w-5 h-5 text-primary" />
                Basic Information
              </h2>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Full Name
                  </label>
                  {isEditing ? (
                    <input
                      type="text"
                      value={editingProfile.name}
                      onChange={(e) => updateProfile('name', e.target.value)}
                      className="w-full px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-sans"
                      placeholder="Enter your full name"
                    />
                  ) : (
                    <p className="text-foreground bg-background px-4 py-3 rounded-lg border border-border">
                      {editingProfile.name}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Email Address
                  </label>
                  {isEditing ? (
                    <input
                      type="email"
                      value={editingProfile.email}
                      onChange={(e) => updateProfile('email', e.target.value)}
                      className="w-full px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-sans"
                      placeholder="Enter your email"
                    />
                  ) : (
                    <p className="text-foreground bg-background px-4 py-3 rounded-lg border border-border flex items-center gap-2">
                      <Mail className="w-4 h-4 text-mutedForeground" />
                      {editingProfile.email}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Phone Number
                  </label>
                  {isEditing ? (
                    <input
                      type="tel"
                      value={editingProfile.phone}
                      onChange={(e) => updateProfile('phone', e.target.value)}
                      className="w-full px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-sans"
                      placeholder="Enter your phone number"
                    />
                  ) : (
                    <p className="text-foreground bg-background px-4 py-3 rounded-lg border border-border flex items-center gap-2">
                      <Phone className="w-4 h-4 text-mutedForeground" />
                      {editingProfile.phone}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground mb-2">
                    Location
                  </label>
                  {isEditing ? (
                    <input
                      type="text"
                      value={editingProfile.location}
                      onChange={(e) => updateProfile('location', e.target.value)}
                      className="w-full px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder-mutedForeground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 font-sans"
                      placeholder="Enter your location"
                    />
                  ) : (
                    <p className="text-foreground bg-background px-4 py-3 rounded-lg border border-border flex items-center gap-2">
                      <MapPin className="w-4 h-4 text-mutedForeground" />
                      {editingProfile.location}
                    </p>
                  )}
                </div>
              </div>
