'use client'

import { useState, useEffect } from 'react'
import { Calendar, Users, Clock, CheckCircle, AlertCircle, Sync, ExternalLink } from 'lucide-react'

interface CalendarProvider {
  id: string
  name: string
  type: 'google' | 'outlook' | 'apple' | 'other'
  connected: boolean
  email?: string
}

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  calendars: CalendarProvider[]
  availability: 'available' | 'busy' | 'unknown'
  lastSync?: Date
}

interface CalendarEvent {
  id: string
  title: string
  start: Date
  end: Date
  attendees: string[]
  source: string
}

interface CalendarSyncProps {
  tripId?: string
  groupMembers?: GroupMember[]
  onSyncComplete?: (results: any) => void
  onInviteSent?: (memberIds: string[]) => void
}

export function CalendarSync({
  tripId = 'trip-123',
  groupMembers = DEFAULT_MEMBERS,
  onSyncComplete = () => console.log('Sync complete'),
  onInviteSent = () => console.log('Invites sent')
}: CalendarSyncProps = {}) {
  const [isLoading, setIsLoading] = useState(false)
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle')
  const [selectedMembers, setSelectedMembers] = useState<string[]>([])
  const [conflicts, setConflicts] = useState<CalendarEvent[]>([])
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null)
  const [error, setError] = useState<string | null>(null)

  const handleConnectCalendar = async (memberId: string, provider: string) => {
    setIsLoading(true)
    setError(null)
    try {
      await new Promise(resolve => setTimeout(resolve, 1500))
      console.log(`Connecting ${provider} calendar for member ${memberId}`)
      setSyncStatus('success')
    } catch (error) {
      setSyncStatus('error')
      setError('Failed to connect calendar. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleSyncCalendars = async () => {
    setIsLoading(true)
    setSyncStatus('syncing')
    setError(null)

    try {
      await new Promise(resolve => setTimeout(resolve, 2000))

      const mockConflicts = [
        {
          id: '1',
          title: 'Work Meeting',
          start: new Date('2024-01-15T10:00:00'),
          end: new Date('2024-01-15T11:00:00'),
          attendees: ['john@example.com'],
          source: 'Google Calendar'
        }
      ]

      setConflicts(mockConflicts)
      setLastSyncTime(new Date())
      setSyncStatus('success')
      onSyncComplete({ conflicts: mockConflicts })
    } catch (error) {
      setSyncStatus('error')
      setError('Sync failed. Please check your connection and try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleSendInvites = async () => {
    if (selectedMembers.length === 0) return

    setIsLoading(true)
    setError(null)
    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onInviteSent(selectedMembers)
      setSelectedMembers([])
    } catch (error) {
      setError('Failed to send invites. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers(prev => 
      prev.includes(memberId) 
        ? prev.filter(id => id !== memberId)
        : [...prev, memberId]
    )
  }

  const getProviderIcon = (type: string) => {
    switch (type) {
      case 'google': return '📅'
      case 'outlook': return '📧'
      case 'apple': return '🍎'
      default: return '📆'
    }
  }

  const getAvailabilityColor = (availability: string) => {
    switch (availability) {
      case 'available': return 'text-primary bg-primary/10 border border-primary/20'
      case 'busy': return 'text-destructive bg-destructive/10 border border-destructive/20'
      default: return 'text-mutedForeground bg-muted border border-border'
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-4xl mx-auto space-y-6">
        {error && (
          <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-4">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 text-destructive" />
              <p className="text-sm text-destructive font-medium">{error}</p>
            </div>
          </div>
        )}

        <div className="bg-surface dark:bg-surface rounded-xl border border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center">
                <Calendar className="w-5 h-5 text-primary" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-foreground">Calendar Sync</h1>
                <p className="text-sm text-mutedForeground">Coordinate schedules with your group</p>
              </div>
            </div>
            <button
              onClick={handleSyncCalendars}
              disabled={isLoading}
              aria-label="Sync all calendars"
              className="flex items-center gap-2 px-4 py-2 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
            >
              <Sync className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
              {isLoading ? 'Syncing...' : 'Sync All'}
            </button>
          </div>

          {syncStatus !== 'idle' && (
            <div className={`flex items-center gap-2 p-3 rounded-lg border ${
              syncStatus === 'success' ? 'bg-primary/10 text-primary border-primary/20' :
              syncStatus === 'error' ? 'bg-destructive/10 text-destructive border-destructive/20' :
              'bg-accent/10 text-accent border-accent/20'
            }`}>
              {syncStatus === 'success' && <CheckCircle className="w-4 h-4" />}
              {syncStatus === 'error' && <AlertCircle className="w-4 h-4" />}
              {syncStatus === 'syncing' && <Sync className="w-4 h-4 animate-spin" />}
              <span className="text-sm font-medium">
                {syncStatus === 'success' && 'Calendars synced successfully'}
                {syncStatus === 'error' && 'Sync failed. Please try again.'}
                {syncStatus === 'syncing' && 'Syncing calendars...'}
              </span>
              {lastSyncTime && syncStatus === 'success' && (
                <span className="text-xs opacity-75 ml-auto">
                  {lastSyncTime.toLocaleTimeString()}
                </span>
              )}
            </div>
          )}
        </div>

        <div className="bg-surface dark:bg-surface rounded-xl border border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-secondary/10 rounded-lg flex items-center justify-center">
                <Users className="w-5 h-5 text-secondary" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-foreground">Group Members</h2>
                <p className="text-sm text-mutedForeground">{groupMembers.length} members in this trip</p>
              </div>
            </div>
            {selectedMembers.length > 0 && (
              <button
                onClick={handleSendInvites}
                disabled={isLoading}
                aria-label={`Send invites to ${selectedMembers.length} selected members`}
                className="px-4 py-2 bg-accent text-accentForeground rounded-lg hover:bg-accent/90 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              >
                Send Invites ({selectedMembers.length})
              </button>
            )}
          </div>

          {isLoading && groupMembers.length === 0 ? (
            <div className="space-y-4 animate-pulse">
              {[1, 2, 3].map((i) => (
                <div key={i} className="bg-muted rounded-lg p-4">
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-10 h-10 bg-border rounded-full"></div>
                    <div className="space-y-2">
                      <div className="h-4 bg-border rounded w-32"></div>
                      <div className="h-3 bg-border rounded w-48"></div>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <div className="h-3 bg-border rounded w-24"></div>
                    <div className="grid grid-cols-2 gap-2">
                      <div className="h-8 bg-border rounded"></div>
                      <div className="h-8 bg-border rounded"></div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : groupMembers.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-8 h-8 text-mutedForeground" />
              </div>
              <h3 className="text-lg font-medium text-foreground mb-2">No members yet</h3>
              <p className="text-mutedForeground text-sm">Invite people to join your trip</p>
            </div>
          ) : (
            <div className="space-y-4">
              {groupMembers.map((member) => (
                <div key={member.id} className="bg-muted/50 rounded-lg p-4 border border-border hover:border-primary/30 hover:-translate-y-0.5 hover:shadow-lg transition-all duration-300">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-primary text-primaryForeground rounded-full flex items-center justify-center text-sm font-medium">
                        {member.name.charAt(0)}
                      </div>
                      <div>
                        <h3 className="font-medium text-foreground">{member.name}</h3>
                        <p className="text-sm text-mutedForeground">{member.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getAvailabilityColor(member.availability)}`}>
                        {member.availability}
                      </span>
                      <label className="flex items-center cursor-pointer">
                        <input
                          type="checkbox"
                          checked={selectedMembers.includes(member.id)}
                          onChange={() => toggleMemberSelection(member.id)}
                          className="w-4 h-4 text-primary bg-background border-border rounded focus:ring-primary focus:ring-2 focus:ring-offset-2 transition-all duration-200"
                          aria-label={`Select ${member.name} for invite`}
                        />
                      </label>
                    </div>
                  </div>

                  <div className="space-y-3">
                    <h4 className="text-sm font-medium text-foreground">Connected Calendars</h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {member.calendars.map((calendar) => (
                        <div key={calendar.id} className="flex items-center justify-between p-3 bg-background rounded-lg border border-border hover:border-primary/30 transition-all duration-200">
                          <div className="flex items-center gap-2">
                            <span className="text-base">{getProviderIcon(calendar.type)}</span>
                            <span className="text-sm text-foreground font-medium">{calendar.name}</span>
                          </div>
                          {calendar.connected ? (
                            <CheckCircle className="w-4 h-4 text-primary" />
                          ) : (
                            <button
                              onClick={() => handleConnectCalendar(member.id, calendar.type)}
                              disabled={isLoading}
                              aria-label={`Connect ${calendar.name} for ${member.name}`}
                              className="px-3 py-1 bg-primary text-primaryForeground rounded-md text-xs font-medium hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1"
                            >
                              Connect
                            </button>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {conflicts.length > 0 && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border p-6 shadow-sm hover:shadow-md transition-all duration-300">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 bg-destructive/10 rounded-lg flex items-center justify-center">
                <AlertCircle className="w-5 h-5 text-destructive" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-foreground">Schedule Conflicts</h2>
                <p className="text-sm text-mutedForeground">{conflicts.length} conflicts found</p>
              </div>
            </div>
            <div className="space-y-3">
              {conflicts.map((conflict) => (
                <div key={conflict.id} className="bg-destructive/5 border border-destructive/20 rounded-lg p-4 hover:bg-destructive/10 transition-all duration-200">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
