'use client'

import { useState, useEffect } from 'react'
import { MapPin, Calendar, Users, MessageCircle, Star, Plus, Filter, Search, Navigation } from 'lucide-react'

interface Trip {
  id: string
  title: string
  location: string
  startDate: string
  endDate: string
  memberCount: number
  status: 'planning' | 'confirmed' | 'completed'
  difficulty: 'easy' | 'moderate' | 'hard'
  imageUrl: string
  description: string
  organizer: string
  isStarred: boolean
  lastActivity: string
}

interface TripListProps {
  trips?: Trip[]
  onTripSelect?: (tripId: string) => void
  onCreateTrip?: () => void
  showFilters?: boolean
}

export function TripList({
  trips = DEFAULT_TRIPS,
  onTripSelect = (id) => console.log('Trip selected:', id),
  onCreateTrip = () => console.log('Create trip'),
  showFilters = true
}: TripListProps = {}) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedFilter, setSelectedFilter] = useState<'all' | 'planning' | 'confirmed' | 'completed'>('all')
  const [filteredTrips, setFilteredTrips] = useState(trips)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    setIsLoading(true)
    const timer = setTimeout(() => {
      let filtered = trips

      if (selectedFilter !== 'all') {
        filtered = filtered.filter(trip => trip.status === selectedFilter)
      }

      if (searchQuery.trim()) {
        filtered = filtered.filter(trip =>
          trip.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          trip.location.toLowerCase().includes(searchQuery.toLowerCase())
        )
      }

      setFilteredTrips(filtered)
      setIsLoading(false)
    }, 200)

    return () => clearTimeout(timer)
  }, [searchQuery, selectedFilter, trips])

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-muted text-primary border-border dark:bg-muted dark:text-primary dark:border-border'
      case 'moderate': return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20'
      case 'hard': return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/10 dark:text-destructive dark:border-destructive/20'
      default: return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'planning': return 'bg-secondary/10 text-secondary border-secondary/20 dark:bg-secondary/10 dark:text-secondary dark:border-secondary/20'
      case 'confirmed': return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      case 'completed': return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
      default: return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div>
            <h1 className="text-3xl sm:text-4xl font-bold text-foreground dark:text-foreground mb-2 leading-tight">
              Off-Road Adventures
            </h1>
            <p className="text-mutedForeground dark:text-mutedForeground text-lg leading-normal">
              Plan and manage your outdoor expeditions
            </p>
          </div>

          <button
            onClick={onCreateTrip}
            className="flex items-center gap-2 px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 focus:bg-primary/90 active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background transition-all duration-150 font-medium shadow-sm hover:shadow-md disabled:opacity-50 disabled:cursor-not-allowed min-h-[44px]"
            aria-label="Create new trip"
          >
            <Plus className="w-5 h-5" />
            <span className="hidden sm:inline">New Trip</span>
            <span className="sm:hidden">New</span>
          </button>
        </div>

        {/* Search and Filters */}
        {showFilters && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-sm">
            <div className="flex flex-col sm:flex-row gap-4">
              {/* Search */}
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-mutedForeground dark:text-mutedForeground" />
                <input
                  type="text"
                  placeholder="Search trips or locations..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-md text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background transition-all duration-200 min-h-[44px] text-base"
                  aria-label="Search trips"
                />
              </div>

              {/* Filter Buttons */}
              <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0">
                {[
                  { key: 'all', label: 'All' },
                  { key: 'planning', label: 'Planning' },
                  { key: 'confirmed', label: 'Confirmed' },
                  { key: 'completed', label: 'Completed' }
                ].map((filter) => (
                  <button
                    key={filter.key}
                    onClick={() => setSelectedFilter(filter.key as any)}
                    className={`px-4 py-2 rounded-md font-medium text-sm whitespace-nowrap transition-all duration-150 min-h-[44px] min-w-[80px] focus:outline-none focus:ring-2 focus:ring-ring/50 focus:ring-offset-2 focus:ring-offset-background active:scale-[0.98] ${
                      selectedFilter === filter.key
                        ? 'bg-primary text-primaryForeground shadow-sm'
                        : 'bg-muted text-mutedForeground hover:bg-muted/80 dark:bg-muted dark:text-mutedForeground dark:hover:bg-muted/80'
                    }`}
                    aria-label={`Filter by ${filter.label}`}
                  >
                    {filter.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Trip Grid */}
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 animate-pulse">
                <div className="w-full h-48 bg-muted dark:bg-muted rounded-lg mb-4"></div>
                <div className="h-6 bg-muted dark:bg-muted rounded mb-2"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-3/4 mb-4"></div>
                <div className="flex gap-2 mb-4">
                  <div className="h-6 bg-muted dark:bg-muted rounded w-16"></div>
                  <div className="h-6 bg-muted dark:bg-muted rounded w-20"></div>
                </div>
                <div className="flex justify-between items-center">
                  <div className="h-4 bg-muted dark:bg-muted rounded w-24"></div>
                  <div className="h-4 bg-muted dark:bg-muted rounded w-16"></div>
                </div>
              </div>
            ))}
          </div>
        ) : filteredTrips.length === 0 ? (
          <div className="text-center py-16">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <Navigation className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-2">
              {searchQuery ? 'No trips found' : 'No trips yet'}
            </h3>
            <p className="text-mutedForeground dark:text-mutedForeground mb-6 max-w-md mx-auto leading-relaxed">
              {searchQuery 
                ? 'Try adjusting your search terms or filters'
                : 'Start planning your first off-road adventure'
              }
            </p>
            {!searchQuery && (
              <button
                onClick={onCreateTrip}
                className="px-6 py-3 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 focus:bg-primary/90 active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background transition-all duration-150 font-medium shadow-sm hover:shadow-md"
                aria-label="Create your first trip"
              >
                Create Your First Trip
              </button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredTrips.map((trip) => (
              <div
                key={trip.id}
                onClick={() => onTripSelect(trip.id)}
                className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:border-ring/50 dark:hover:border-ring/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300 shadow-sm cursor-pointer group focus:outline-none focus:ring-2 focus:ring-ring/50 focus:ring-offset-2 focus:ring-offset-background"
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onTripSelect(trip.id)
                  }
                }}
                aria-label={`View trip: ${trip.title}`}
              >
                {/* Trip Image */}
                <div className="relative mb-4 overflow-hidden rounded-lg">
                  <img
                    src={trip.imageUrl}
                    alt={trip.title}
                    className="w-full h-48 object-cover group-hover:scale-105 transition-transform duration-300"
                  />
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      console.log('Toggle star:', trip.id)
                    }}
                    className={`absolute top-3 right-3 p-2 rounded-full transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-ring/50 active:scale-[0.95] ${
                      trip.isStarred
                        ? 'bg-accent text-accentForeground shadow-sm'
                        : 'bg-background/80 dark:bg-background/80 text-foreground dark:text-foreground hover:bg-background dark:hover:bg-background backdrop-blur-sm'
                    }`}
                    aria-label={trip.isStarred ? 'Remove from favorites' : 'Add to favorites'}
                  >
                    <Star className={`w-4 h-4 ${trip.isStarred ? 'fill-current' : ''}`} />
                  </button>
                </div>

                {/* Trip Info */}
                <div className="space-y-3">
                  <div>
                    <h3 className="text-lg font-semibold text-foreground dark:text-foreground mb-1 group-hover:text-primary dark:group-hover:text-primary transition-colors leading-tight">
                      {trip.title}
                    </h3>
                    <div className="flex items-center gap-1 text-mutedForeground dark:text-mutedForeground text-sm">
                      <MapPin className="w-4 h-4" />
                      <span>{trip.location}</span>
                    </div>
                  </div>

                  <p className="text-mutedForeground dark:text-mutedForeground text-sm line-clamp-2 leading-relaxed">
                    {trip.description}
                  </p>

                  {/* Badges */}
                  <div className="flex gap-2 flex-wrap">
                    <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(trip.status)}`}>
                      {trip.status.charAt(0).toUpperCase() + trip.status.slice(1)}
                    </span>
                    <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getDifficultyColor(trip.difficulty)}`}>
                      {trip.difficulty.charAt(0).toUpperCase() + trip.difficulty.slice(1)}
                    </span>
                  </div>

                  {/* Trip Details */}
                  <div className="flex items-center justify-between text-sm text-mutedForeground dark:text-mutedForeground">
                    <div className="flex items-center gap-4">
                      <div className="flex items-center gap-1">
                        <Calendar className="w-4 h-4" />
                        <span>{formatDate(trip.startDate)} - {formatDate(trip.endDate)}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <Users className="w-4 h-4" />
                        <span>{trip.memberCount}</span>
                      </div>
                    </div>
                    <MessageCircle className="w-4 h-4" />
                  </div>

                  <div className="text-xs text-mutedForeground dark:text-mutedForeground border-t border-border dark:border-border pt-3">
                    Organized by {trip.organizer} • {trip.lastActivity}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

