code.database-schema:
'use client'

import { useState, useEffect, useRef } from 'react'
import { Send, Users, MapPin, Calendar, MoreVertical, Search, Paperclip, Smile } from 'lucide-react'

interface User {
  id: string
  name: string
  avatar?: string
  isOnline: boolean
  role: 'organizer' | 'member'
}

interface Message {
  id: string
  userId: string
  content: string
  timestamp: Date
  type: 'text' | 'location' | 'task' | 'system'
  metadata?: {
    location?: { lat: number; lng: number; name: string }
    taskId?: string
    taskName?: string
  }
}

interface GroupChatProps {
  tripId?: string
  currentUserId?: string
  initialMessages?: Message[]
  groupMembers?: User[]
  onSendMessage?: (message: Omit<Message, 'id' | 'timestamp'>) => void
  onLocationShare?: (location: { lat: number; lng: number; name: string }) => void
}

export function GroupChat({
  tripId = 'trip-1',
  currentUserId = 'user-1',
  initialMessages = DEFAULT_MESSAGES,
  groupMembers = DEFAULT_MEMBERS,
  onSendMessage = () => console.log('Message sent'),
  onLocationShare = () => console.log('Location shared')
}: GroupChatProps = {}) {
  const [messages, setMessages] = useState<Message[]>(initialMessages)
  const [newMessage, setNewMessage] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [showMembers, setShowMembers] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const handleSendMessage = () => {
    if (!newMessage.trim()) return

    const message: Omit<Message, 'id' | 'timestamp'> = {
      userId: currentUserId,
      content: newMessage.trim(),
      type: 'text'
    }

    const fullMessage: Message = {
      ...message,
      id: `msg-${Date.now()}`,
      timestamp: new Date()
    }

    setMessages(prev => [...prev, fullMessage])
    setNewMessage('')
    onSendMessage(message)
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const shareCurrentLocation = () => {
    if (navigator.geolocation) {
      setIsLoading(true)
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const location = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            name: 'Current Location'
          }

          const locationMessage: Message = {
            id: `msg-${Date.now()}`,
            userId: currentUserId,
            content: 'Shared location',
            timestamp: new Date(),
            type: 'location',
            metadata: { location }
          }

          setMessages(prev => [...prev, locationMessage])
          onLocationShare(location)
          setIsLoading(false)
        },
        (error) => {
          setError('Unable to access location. Please check your permissions.')
          setIsLoading(false)
          setTimeout(() => setError(''), 3000)
        }
      )
    } else {
      setError('Location sharing is not supported by your browser.')
      setTimeout(() => setError(''), 3000)
    }
  }

  const filteredMessages = messages.filter(message =>
    message.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
    groupMembers.find(member => member.id === message.userId)?.name
      .toLowerCase().includes(searchQuery.toLowerCase())
  )

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const getUserById = (userId: string) => {
    return groupMembers.find(member => member.id === userId)
  }

  const renderMessage = (message: Message) => {
    const user = getUserById(message.userId)
    const isCurrentUser = message.userId === currentUserId
    const isSystem = message.type === 'system'

    if (isSystem) {
      return (
        <div key={message.id} className="flex justify-center my-4">
          <div className="bg-[#F1F5F0] dark:bg-[#252B32] px-4 py-2 rounded-full text-sm text-[#6B7280] dark:text-[#9CA3AF] font-['Inter,-apple-system,BlinkMacSystemFont,Segoe_UI,Roboto,sans-serif']">
            {message.content}
          </div>
        </div>
      )
    }

    return (
      <div key={message.id} className={`flex gap-3 mb-4 ${isCurrentUser ? 'flex-row-reverse' : ''}`}>
        <div className="flex-shrink-0">
          <div className="w-8 h-8 bg-gradient-to-br from-[#2D5016] to-[#7FB069] dark:from-[#7FB069] dark:to-[#2D5016] rounded-full flex items-center justify-center text-[#FFFFFF] dark:text-[#0F1419] text-sm font-medium">
            {user?.name.charAt(0).toUpperCase() || '?'}
          </div>
        </div>

        <div className={`flex-1 max-w-xs sm:max-w-sm ${isCurrentUser ? 'text-right' : ''}`}>
          <div className={`inline-block px-4 py-2 rounded-2xl transition-all duration-150 ${
            isCurrentUser 
              ? 'bg-[#2D5016] dark:bg-[#7FB069] text-[#FFFFFF] dark:text-[#0F1419]' 
              : 'bg-[#F1F5F0] dark:bg-[#252B32] text-[#1F2937] dark:text-[#F9FAFB]'
          }`}>
            {message.type === 'location' && message.metadata?.location ? (
              <div className="flex items-center gap-2">
                <MapPin className="w-4 h-4" />
                <span className="text-sm">{message.metadata.location.name}</span>
              </div>
            ) : message.type === 'task' && message.metadata?.taskName ? (
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4" />
                <span className="text-sm">Task: {message.metadata.taskName}</span>
              </div>
            ) : (
              <p className="text-sm">{message.content}</p>
            )}
          </div>

          <div className={`text-xs text-[#6B7280] dark:text-[#9CA3AF] mt-1 ${
            isCurrentUser ? 'text-right' : 'text-left'
          }`}>
            {user?.name} • {formatTime(message.timestamp)}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen bg-[#FEFEFE] dark:bg-[#0F1419] font-['Inter,-apple-system,BlinkMacSystemFont,Segoe_UI,Roboto,sans-serif']">
      <div className="flex items-center justify-between p-4 border-b border-[#E5E7EB] dark:border-[#374151] bg-[#FEFEFE] dark:bg-[#0F1419]">
        <div className="flex items-center gap-3">
          <div className="relative">
            <Users className="w-6 h-6 text-[#1F2937] dark:text-[#F9FAFB]" />
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-[#2D5016] dark:bg-[#7FB069] rounded-full border-2 border-[#FEFEFE] dark:border-[#0F1419]"></div>
          </div>
          <div>
            <h1 className="font-semibold text-[#1F2937] dark:text-[#F9FAFB]">Trip Chat</h1>
            <p className="text-sm text-[#6B7280] dark:text-[#9CA3AF]">
              {groupMembers.filter(m => m.isOnline).length} online
            </p>
          </div>
        </div>

        <button
          onClick={() => setShowMembers(!showMembers)}
          className="p-2 hover:bg-[#F1F5F0] dark:hover:bg-[#252B32] rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50"
          aria-label="View group members"
        >
          <MoreVertical className="w-5 h-5 text-[#6B7280] dark:text-[#9CA3AF]" />
        </button>
      </div>

      <div className="p-4 border-b border-[#E5E7EB] dark:border-[#374151]">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[#6B7280] dark:text-[#9CA3AF]" />
          <input
            type="text"
            placeholder="Search messages..."
            value={searchQuery}
