      {isTyping && (
        <div className="px-4 py-2">
          <div className="flex items-center gap-2 text-sm text-[#6B7280] dark:text-[#9CA3AF]">
            <div className="flex gap-1">
              <div className="w-2 h-2 bg-[#6B7280] dark:bg-[#9CA3AF] rounded-full animate-bounce"></div>
              <div className="w-2 h-2 bg-[#6B7280] dark:bg-[#9CA3AF] rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
              <div className="w-2 h-2 bg-[#6B7280] dark:bg-[#9CA3AF] rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
            </div>
            <span>Someone is typing...</span>
          </div>
        </div>
      )}

      <div className="p-4 border-t border-[#E5E7EB] dark:border-[#374151] bg-[#FEFEFE] dark:bg-[#0F1419]">
        <div className="flex items-end gap-3">
          <div className="flex gap-2">
            <button
              onClick={shareCurrentLocation}
              disabled={isLoading}
              className="p-2 text-[#6B7280] dark:text-[#9CA3AF] hover:text-[#2D5016] dark:hover:text-[#7FB069] hover:bg-[#F1F5F0] dark:hover:bg-[#252B32] rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Share location"
            >
              <MapPin className="w-5 h-5" />
            </button>
            <button
              className="p-2 text-[#6B7280] dark:text-[#9CA3AF] hover:text-[#2D5016] dark:hover:text-[#7FB069] hover:bg-[#F1F5F0] dark:hover:bg-[#252B32] rounded-lg transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50"
              aria-label="Attach file"
            >
              <Paperclip className="w-5 h-5" />
            </button>
          </div>

          <div className="flex-1 relative">
            <input
              ref={inputRef}
              type="text"
              placeholder="Type a message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              className="w-full px-4 py-3 bg-[#FEFEFE] dark:bg-[#1A2025] border border-[#E5E7EB] dark:border-[#374151] rounded-xl text-[#1F2937] dark:text-[#F9FAFB] placeholder-[#6B7280] dark:placeholder-[#9CA3AF] focus:border-[#2D5016] dark:focus:border-[#7FB069] focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50 transition-all duration-200 pr-12"
            />
            <button
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1 text-[#6B7280] dark:text-[#9CA3AF] hover:text-[#2D5016] dark:hover:text-[#7FB069] transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50"
              aria-label="Add emoji"
            >
              <Smile className="w-5 h-5" />
            </button>
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim() || isLoading}
            className="p-3 bg-[#2D5016] dark:bg-[#7FB069] text-[#FFFFFF] dark:text-[#0F1419] rounded-xl hover:bg-[#1F3A0F] dark:hover:bg-[#6B9B5A] disabled:bg-[#E5E7EB] dark:disabled:bg-[#374151] disabled:text-[#6B7280] dark:disabled:text-[#9CA3AF] disabled:cursor-not-allowed transition-all duration-150 shadow-sm hover:shadow-md hover:scale-[1.02] active:scale-[0.98] min-w-[48px] min-h-[48px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-[#2D5016] dark:focus:ring-[#7FB069] focus:ring-opacity-50"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

