'use client'

import { useState } from 'react'
import { User, Mail, Phone, MapPin, Calendar, Shield, Camera, Edit3, Save, X } from 'lucide-react'

interface UserProfile {
  id: string
  email: string
  firstName: string
  lastName: string
  phone?: string
  emergencyContact?: {
    name: string
    phone: string
    relationship: string
  }
  location?: {
    city: string
    state: string
    country: string
  }
  preferences: {
    vehicleType: string
    experienceLevel: 'beginner' | 'intermediate' | 'advanced' | 'expert'
    dietaryRestrictions: string[]
    notifications: {
      email: boolean
      sms: boolean
      push: boolean
    }
  }
  avatar?: string
  bio?: string
  joinedAt: string
  lastActive: string
  tripsCompleted: number
  isVerified: boolean
}

interface UserProfileSchemaProps {
  profile?: UserProfile
  onSave?: (profile: UserProfile) => void
  onCancel?: () => void
  isEditing?: boolean
}

export function UserProfileSchema({
  profile = DEFAULT_PROFILE,
  onSave = () => console.log('Profile saved'),
  onCancel = () => console.log('Edit cancelled'),
  isEditing = false
}: UserProfileSchemaProps = {}) {
  const [editMode, setEditMode] = useState(isEditing)
  const [formData, setFormData] = useState<UserProfile>(profile)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'First name is required'
    }
    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Last name is required'
    }
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Invalid email format'
    }
    if (formData.phone && !/^\+?[\d\s\-\(\)]+$/.test(formData.phone)) {
      newErrors.phone = 'Invalid phone format'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSave = () => {
    if (validateForm()) {
      onSave(formData)
      setEditMode(false)
    }
  }

  const handleCancel = () => {
    setFormData(profile)
    setErrors({})
    setEditMode(false)
    onCancel()
  }

  const updateField = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const updateNestedField = (parent: string, field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [parent]: {
        ...prev[parent as keyof UserProfile] as any,
        [field]: value
      }
    }))
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-lg hover:shadow-xl transition-all duration-300">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className="relative">
                <div className="w-16 h-16 bg-primary/20 dark:bg-primary/20 rounded-full flex items-center justify-center border border-primary/30 dark:border-primary/30">
                  {formData.avatar ? (
                    <img 
                      src={formData.avatar} 
                      alt="Profile" 
                      className="w-full h-full rounded-full object-cover"
                    />
                  ) : (
                    <User className="w-8 h-8 text-primary dark:text-primary" />
                  )}
                </div>
                {formData.isVerified && (
                  <div className="absolute -top-1 -right-1 w-6 h-6 bg-primary dark:bg-primary rounded-full flex items-center justify-center">
                    <Shield className="w-3 h-3 text-primaryForeground dark:text-primaryForeground" />
                  </div>
                )}
              </div>
              <div>
                <h1 className="text-2xl font-bold text-foreground dark:text-foreground">
                  {formData.firstName} {formData.lastName}
                </h1>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">
                  {formData.preferences.experienceLevel} • {formData.tripsCompleted} trips completed
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              {!editMode ? (
                <button
                  onClick={() => setEditMode(true)}
                  className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-md hover:shadow-lg flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                  aria-label="Edit profile"
                >
                  <Edit3 className="w-4 h-4" />
                  Edit Profile
                </button>
              ) : (
                <div className="flex gap-2">
                  <button
                    onClick={handleSave}
                    className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-md hover:shadow-lg flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                    aria-label="Save changes"
                  >
                    <Save className="w-4 h-4" />
                    Save
                  </button>
                  <button
                    onClick={handleCancel}
                    className="px-4 py-2 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-md hover:shadow-lg flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
                    aria-label="Cancel editing"
                  >
                    <X className="w-4 h-4" />
                    Cancel
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Personal Information */}
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-lg hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground mb-4 flex items-center gap-2">
              <User className="w-5 h-5 text-primary dark:text-primary" />
              Personal Information
            </h2>
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    First Name
                  </label>
                  {editMode ? (
                    <div>
                      <input
                        type="text"
                        value={formData.firstName}
                        onChange={(e) => updateField('firstName', e.target.value)}
                        className={`w-full px-4 py-2.5 bg-background dark:bg-background border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 transition-all duration-200 ${
                          errors.firstName 
                            ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive focus:ring-destructive/50 dark:focus:ring-destructive/50' 
                            : 'border-border dark:border-border focus:border-primary dark:focus:border-primary focus:ring-primary/50 dark:focus:ring-primary/50'
                        }`}
                        placeholder="Enter first name"
                        aria-invalid={errors.firstName ? 'true' : 'false'}
                        aria-describedby={errors.firstName ? 'firstName-error' : undefined}
                      />
                      {errors.firstName && (
                        <p id="firstName-error" className="text-destructive dark:text-destructive text-xs mt-1">{errors.firstName}</p>
                      )}
                    </div>
                  ) : (
                    <p className="text-foreground dark:text-foreground bg-background dark:bg-background px-4 py-2.5 rounded-lg border border-border dark:border-border">
                      {formData.firstName}
                    </p>
                  )}
                </div>
                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Last Name
                  </label>
                  {editMode ? (
                    <div>
                      <input
                        type="text"
                        value={formData.lastName}
                        onChange={(e) => updateField('lastName', e.target.value)}
                        className={`w-full px-4 py-2.5 bg-background dark:bg-background border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 transition-all duration-200 ${
                          errors.lastName 
                            ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive focus:ring-destructive/50 dark:focus:ring-destructive/50' 
                            : 'border-border dark:border-border focus:border-primary dark:focus:border-primary focus:ring-primary/50 dark:focus:ring-primary/50'
                        }`}
                        placeholder="Enter last name"
                        aria-invalid={errors.lastName ? 'true' : 'false'}
                        aria-describedby={errors.lastName ? 'lastName-error' : undefined}
                      />
                      {errors.lastName && (
                        <p id="lastName-error" className="text-destructive dark:text-destructive text-xs mt-1">{errors.lastName}</p>
                      )}
                    </div>
                  ) : (
                    <p className="text-foreground dark:text-foreground bg-background dark:bg-background px-4 py-2.5 rounded-lg border border-border dark:border-border">
                      {formData.lastName}
                    </p>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Email
                </label>
                {editMode ? (
                  <div>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => updateField('email', e.target.value)}
                      className={`w-full px-4 py-2.5 bg-background dark:bg-background border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 transition-all duration-200 ${
                        errors.email 
                          ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive focus:ring-destructive/50 dark:focus:ring-destructive/50' 
                          : 'border-border dark:border-border focus:border-primary dark:focus:border-primary focus:ring-primary/50 dark:focus:ring-primary/50'
                      }`}
                      placeholder="Enter email address"
                      aria-invalid={errors.email ? 'true' : 'false'}
                      aria-describedby={errors.email ? 'email-error' : undefined}
                    />
                    {errors.email && (
                      <p id="email-error" className="text-destructive dark:text-destructive text-xs mt-1">{errors.email}</p>
                    )}
                  </div>
                ) : (
                  <p className="text-foreground dark:text-foreground bg-background dark:bg-background px-4 py-2.5 rounded-lg border border-border dark:border-border flex items-center gap-2">
                    <Mail className="w-4 h-4 text-primary dark:text-primary" />
                    {formData.email}
                  </p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Phone (Optional)
                </label>
                {editMode ? (
                  <div>
                    <input
                      type="tel"
                      value={formData.phone || ''}
                      onChange={(e) => updateField('phone', e.target.value)}
                      className={`w-full px-4 py-2.5 bg-background dark:bg-background border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:outline-none focus:ring-2 transition-all duration-200 ${
                        errors.phone 
                          ? 'border-destructive dark:border-destructive focus:border-destructive dark:focus:border-destructive focus:ring-destructive/50 dark:focus:ring-destructive/50' 
                          : 'border-border dark:border-border focus:border-primary dark:focus:border-primary focus:ring-primary/50 dark:focus:ring-primary/50'
                      }`}
                      placeholder="Enter phone number"
                      aria-invalid={errors.phone ? 'true' : 'false'}
                      aria-describedby={errors.phone ? 'phone-error' : undefined}
                    />
                    {errors.phone && (
                      <p id="phone-error" className="text-destructive dark:text-destructive text-xs mt-1">{errors.phone}</p>
                    )}
                  </div>
                ) : (
                  <p className="text-foreground dark:text-foreground bg-background dark:bg-background px-4 py-2.5 rounded-lg border border-border dark:border-border flex items-center gap-2">
                    <Phone className="w-4 h-4 text-primary dark:text-primary" />
                    {formData.phone || 'Not provided'}
                  </p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Bio (Optional)
                </label>
                {editMode ? (
                  <textarea
                    value={formData.bio || ''}
                    onChange={(e) => updateField('bio', e.target.value)}
                    rows={3}
                    className="w-full px-4 py-2.5 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/50 dark:focus:ring-primary/50 transition-all duration-200 resize-none"
                    placeholder="Tell us about yourself..."
                  />
                ) : (
                  <p className="text-foreground dark:text-foreground bg-background dark:bg-background px-4 py-2.5 rounded-lg border border-border dark:border-border min-h-[84px]">
                    {formData.bio || 'No bio provided'}
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Preferences */}
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-lg hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">
              Off-Road Preferences
            </h2>
