'use client'

import { useState } from 'react'
import { Calendar, User, MapPin, Clock, CheckCircle, AlertCircle, Users, Utensils, Flame, Car, Plus, X } from 'lucide-react'

interface TaskAssignment {
  id: string
  assigneeId: string
  assigneeName: string
  assigneeAvatar?: string
  assignedAt: Date
  status: 'pending' | 'accepted' | 'declined'
}

interface TaskDependency {
  id: string
  dependsOnTaskId: string
  dependencyType: 'blocks' | 'requires' | 'follows'
}

interface TaskLocation {
  id: string
  name: string
  coordinates: {
    lat: number
    lng: number
  }
  address?: string
}

interface TaskRecurrence {
  pattern: 'daily' | 'weekly' | 'monthly' | 'custom'
  interval: number
  endDate?: Date
  daysOfWeek?: number[]
}

interface TaskSchema {
  id: string
  tripId: string
  title: string
  description?: string
  category: 'meal' | 'setup' | 'cleanup' | 'safety' | 'navigation' | 'supplies' | 'entertainment' | 'maintenance' | 'other'
  priority: 'low' | 'medium' | 'high' | 'critical'
  status: 'pending' | 'in_progress' | 'completed' | 'cancelled' | 'overdue'

  scheduledStartTime?: Date
  scheduledEndTime?: Date
  estimatedDuration?: number
  actualStartTime?: Date
  actualEndTime?: Date

  assignments: TaskAssignment[]
  maxAssignees?: number
  requiredSkills?: string[]

  location?: TaskLocation
  isLocationRequired: boolean
  weatherDependent: boolean

  dependencies: TaskDependency[]
  blockedBy: string[]
  blocks: string[]

  requiredEquipment?: string[]
  estimatedCost?: number
  currency?: string

  progressPercentage: number
  checklistItems?: {
    id: string
    title: string
    completed: boolean
    assigneeId?: string
  }[]

  notes?: string
  attachments?: {
    id: string
    filename: string
    url: string
    uploadedBy: string
    uploadedAt: Date
  }[]

  recurrence?: TaskRecurrence
  parentTaskId?: string

  createdBy: string
  createdAt: Date
  updatedBy?: string
  updatedAt?: Date
  completedBy?: string
  completedAt?: Date

  reminderSettings?: {
    enabled: boolean
    reminderTimes: number[]
    notificationMethods: ('push' | 'email' | 'sms')[]
  }

  calendarEventId?: string
  weatherAlertThreshold?: {
    maxWindSpeed?: number
    minTemperature?: number
    maxTemperature?: number
    precipitationChance?: number
  }
}

interface TaskSchemaProps {
  tasks?: TaskSchema[]
  tripId?: string
  onTaskCreate?: (task: Partial<TaskSchema>) => void
  onTaskUpdate?: (taskId: string, updates: Partial<TaskSchema>) => void
  onTaskDelete?: (taskId: string) => void
  onAssignmentUpdate?: (taskId: string, assignment: TaskAssignment) => void
  isLoading?: boolean
}

const TASK_CATEGORIES = [
  { id: 'meal', label: 'Meals', icon: Utensils, color: 'bg-accent dark:bg-accent' },
  { id: 'setup', label: 'Setup', icon: Users, color: 'bg-primary dark:bg-primary' },
  { id: 'cleanup', label: 'Cleanup', icon: CheckCircle, color: 'bg-emerald-500 dark:bg-emerald-600' },
  { id: 'safety', label: 'Safety', icon: AlertCircle, color: 'bg-destructive dark:bg-destructive' },
  { id: 'navigation', label: 'Navigation', icon: MapPin, color: 'bg-primary dark:bg-primary' },
  { id: 'supplies', label: 'Supplies', icon: Car, color: 'bg-secondary dark:bg-secondary' },
  { id: 'entertainment', label: 'Entertainment', icon: Users, color: 'bg-pink-500 dark:bg-pink-600' },
  { id: 'maintenance', label: 'Maintenance', icon: Flame, color: 'bg-yellow-500 dark:bg-yellow-600' },
  { id: 'other', label: 'Other', icon: Clock, color: 'bg-muted dark:bg-muted' }
]

const PRIORITY_COLORS = {
  low: 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground border-border dark:border-border',
  medium: 'bg-yellow-50 dark:bg-yellow-900/20 text-yellow-700 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800',
  high: 'bg-orange-50 dark:bg-orange-900/20 text-orange-700 dark:text-orange-300 border-orange-200 dark:border-orange-800',
  critical: 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 border-red-200 dark:border-red-800'
}

const STATUS_COLORS = {
  pending: 'bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground',
  in_progress: 'bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300',
  completed: 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300',
  cancelled: 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300',
  overdue: 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300'
}

export function TaskSchema({
  tasks = DEFAULT_TASKS,
  tripId = 'trip-1',
  onTaskCreate = () => console.log('Task created'),
  onTaskUpdate = () => console.log('Task updated'),
  onTaskDelete = () => console.log('Task deleted'),
  onAssignmentUpdate = () => console.log('Assignment updated'),
  isLoading = false
}: TaskSchemaProps = {}) {
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [selectedTask, setSelectedTask] = useState<TaskSchema | null>(null)
  const [showCreateForm, setShowCreateForm] = useState(false)

  const filteredTasks = selectedCategory === 'all' 
    ? tasks 
    : tasks.filter(task => task.category === selectedCategory)

  const getCategoryIcon = (category: string) => {
    const categoryData = TASK_CATEGORIES.find(cat => cat.id === category)
    return categoryData ? categoryData.icon : Clock
  }

  const getCategoryColor = (category: string) => {
    const categoryData = TASK_CATEGORIES.find(cat => cat.id === category)
    return categoryData ? categoryData.color : 'bg-muted dark:bg-muted'
  }

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60)
    const mins = minutes % 60
    if (hours > 0) {
      return `${hours}h ${mins > 0 ? `${mins}m` : ''}`
    }
    return `${mins}m`
  }

  const getTaskProgress = (task: TaskSchema) => {
    if (task.checklistItems && task.checklistItems.length > 0) {
      const completed = task.checklistItems.filter(item => item.completed).length
      return Math.round((completed / task.checklistItems.length) * 100)
    }
    return task.progressPercentage
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
        <div className="max-w-6xl mx-auto">
          <div className="mb-8">
            <div className="h-8 bg-muted dark:bg-muted rounded w-64 mb-2 animate-pulse"></div>
            <div className="h-4 bg-muted dark:bg-muted rounded w-96 animate-pulse"></div>
          </div>
          <div className="mb-6">
            <div className="flex flex-wrap gap-2">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="h-10 bg-muted dark:bg-muted rounded-lg w-24 animate-pulse"></div>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 animate-pulse">
                <div className="h-6 bg-muted dark:bg-muted rounded w-3/4 mb-4"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-full mb-2"></div>
                <div className="h-4 bg-muted dark:bg-muted rounded w-2/3 mb-4"></div>
                <div className="h-2 bg-muted dark:bg-muted rounded w-full mb-4"></div>
                <div className="flex gap-2">
                  <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full"></div>
                  <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full"></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-foreground dark:text-foreground mb-2">Task Management</h1>
          <p className="text-mutedForeground dark:text-mutedForeground text-lg">Organize and assign tasks for your off-road adventure</p>
        </div>

        <div className="mb-6">
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                selectedCategory === 'all'
                  ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-md'
                  : 'bg-surface dark:bg-surface text-foreground dark:text-foreground hover:bg-muted dark:hover:bg-muted border border-border dark:border-border'
              }`}
              aria-label={`Show all tasks (${tasks.length} total)`}
            >
              All Tasks ({tasks.length})
            </button>
            {TASK_CATEGORIES.map(category => {
              const count = tasks.filter(task => task.category === category.id).length
              const Icon = category.icon
              return (
                <button
                  key={category.id}
                  onClick={() => setSelectedCategory(category.id)}
                  className={`px-4 py-2 rounded-lg font-medium text-sm transition-all duration-200 flex items-center gap-2 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                    selectedCategory === category.id
                      ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-md'
                      : 'bg-surface dark:bg-surface text-foreground dark:text-foreground hover:bg-muted dark:hover:bg-muted border border-border dark:border-border'
                  }`}
                  aria-label={`Show ${category.label} tasks (${count} total)`}
                >
                  <Icon className="w-4 h-4" />
                  {category.label} ({count})
                </button>
              )
            })}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTasks.map(task => {
            const Icon = getCategoryIcon(task.category)
            const progress = getTaskProgress(task)

            return (
              <div
                key={task.id}
                className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 hover:border-ring dark:hover:border-ring transition-all duration-300 shadow-sm hover:shadow-lg hover:-translate-y-1 cursor-pointer group"
                onClick={() => setSelectedTask(task)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    setSelectedTask(task)
                  }
                }}
                aria-label={`View task: ${task.title}`}
              >
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg ${getCategoryColor(task.category)}`}>
                      <Icon className="w-5 h-5 text-white" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-foreground dark:text-foreground text-lg group-hover:text-primary dark:group-hover:text-primary transition-colors duration-200">{task.title}</h3>
                      <p className="text-mutedForeground dark:text-mutedForeground text-sm capitalize">{task.category}</p>
                    </div>
                  </div>
                  <div className="flex flex-col gap-2">
                    <span className={`px-2 py-1 rounded-full text-xs font-medium border ${PRIORITY_COLORS[task.priority]}`}>
                      {task.priority}
                    </span>
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${STATUS_COLORS[task.status]}`}>
                      {task.status.replace('_', ' ')}
                    </span>
                  </div>
                </div>

                {task.description && (
                  <p className="text-mutedForeground dark:text-mutedForeground text-sm mb-4 line-clamp-2">{task.description}</p>
                )}

                <div className="mb-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-mutedForeground dark:text-mutedForeground text-sm">Progress</span>
                    <span className="text-primary dark:text-primary text-sm font-medium">{progress}%</span>
                  </div>
                  <div className="w-full bg-muted dark:bg-muted rounded-full h-2">
                    <div
