                        title={assignment.assigneeName}
                      >
                        <span className="text-primaryForeground dark:text-primaryForeground text-xs font-medium">
                          {assignment.assigneeName.charAt(0).toUpperCase()}
                        </span>
                      </div>
                    ))}
                    {task.assignments.length > 3 && (
                      <div className="w-8 h-8 bg-muted dark:bg-muted rounded-full border-2 border-surface dark:border-surface flex items-center justify-center">
                        <span className="text-mutedForeground dark:text-mutedForeground text-xs font-medium">
                          +{task.assignments.length - 3}
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {task.scheduledStartTime && (
                  <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground text-sm">
                    <Clock className="w-4 h-4" />
                    <span>
                      {new Date(task.scheduledStartTime).toLocaleDateString()} at{' '}
                      {new Date(task.scheduledStartTime).toLocaleTimeString([], { 
                        hour: '2-digit', 
                        minute: '2-digit' 
                      })}
                    </span>
                    {task.estimatedDuration && (
                      <span className="text-primary dark:text-primary">
                        ({formatDuration(task.estimatedDuration)})
                      </span>
                    )}
                  </div>
                )}

                {task.location && (
                  <div className="flex items-center gap-2 text-mutedForeground dark:text-mutedForeground text-sm mt-2">
                    <MapPin className="w-4 h-4" />
                    <span>{task.location.name}</span>
                  </div>
                )}
              </div>
            )
          })}
        </div>

        {filteredTasks.length === 0 && !isLoading && (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
            </div>
            <h3 className="text-xl font-semibold text-foreground dark:text-foreground mb-2">No tasks found</h3>
            <p className="text-mutedForeground dark:text-mutedForeground mb-6">
              {selectedCategory === 'all' 
                ? 'Create your first task to get started'
                : `No ${selectedCategory} tasks found`
