          </div>
        )}

        {filteredTasks.length > 0 && (
          <div className="fixed bottom-6 right-6">
            <button
              onClick={() => setShowCreateForm(true)}
              className="w-14 h-14 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-full shadow-lg hover:bg-primary/90 dark:hover:bg-primary/90 transition-all duration-200 hover:shadow-xl hover:scale-110 active:scale-95 flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
              aria-label="Create new task"
            >
