'use client'

import { useState, useEffect } from 'react'
import { Send, Mail, CheckCircle, AlertCircle, Clock, Users, Inbox, FileText } from 'lucide-react'

interface EmailTemplate {
  id: string
  name: string
  subject: string
  content: string
  type: 'invitation' | 'reminder' | 'update' | 'cancellation'
}

interface EmailRecipient {
  id: string
  name: string
  email: string
  status: 'pending' | 'sent' | 'delivered' | 'failed'
  sentAt?: Date
}

interface EmailCampaign {
  id: string
  templateId: string
  recipients: EmailRecipient[]
  scheduledAt?: Date
  sentAt?: Date
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed'
  tripId: string
  tripName: string
}

interface ResendServiceProps {
  tripId?: string
  onEmailSent?: (campaignId: string) => void
  onError?: (error: string) => void
}

export function ResendService({
  tripId = 'trip-1',
  onEmailSent = () => console.log('Email sent'),
  onError = () => console.log('Email error')
}: ResendServiceProps = {}) {
  const [templates, setTemplates] = useState<EmailTemplate[]>(DEFAULT_TEMPLATES)
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>(DEFAULT_CAMPAIGNS)
  const [selectedTemplate, setSelectedTemplate] = useState<string>('')
  const [recipients, setRecipients] = useState<EmailRecipient[]>(DEFAULT_RECIPIENTS)
  const [isLoading, setIsLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'send' | 'templates' | 'history'>('send')
  const [error, setError] = useState<string>('')

  const handleSendEmail = async () => {
    if (!selectedTemplate || recipients.length === 0) return

    setIsLoading(true)
    setError('')

    try {
      await new Promise(resolve => setTimeout(resolve, 2000))

      const newCampaign: EmailCampaign = {
        id: `campaign-${Date.now()}`,
        templateId: selectedTemplate,
        recipients: recipients.map(r => ({ ...r, status: 'sent', sentAt: new Date() })),
        sentAt: new Date(),
        status: 'sent',
        tripId,
        tripName: 'Moab Adventure Trip'
      }

      setCampaigns(prev => [newCampaign, ...prev])
      onEmailSent(newCampaign.id)
      setSelectedTemplate('')
    } catch (error) {
      const errorMessage = 'Failed to send emails. Please try again.'
      setError(errorMessage)
      onError(errorMessage)
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusIcon = (status: EmailRecipient['status']) => {
    switch (status) {
      case 'sent':
      case 'delivered':
        return <CheckCircle className="w-4 h-4 text-primary dark:text-primary" />
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
      default:
        return <Clock className="w-4 h-4 text-accent dark:text-accent" />
    }
  }

  const getStatusColor = (status: EmailCampaign['status']) => {
    switch (status) {
      case 'sent':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'sending':
        return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      case 'failed':
        return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      case 'scheduled':
        return 'bg-secondary/10 text-secondary border-secondary/20 dark:bg-secondary/20 dark:text-secondary dark:border-secondary/30'
      default:
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  const getTemplateTypeColor = (type: EmailTemplate['type']) => {
    switch (type) {
      case 'invitation':
        return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      case 'reminder':
        return 'bg-secondary/10 text-secondary border-secondary/20 dark:bg-secondary/20 dark:text-secondary dark:border-secondary/30'
      case 'update':
        return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'cancellation':
        return 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      default:
        return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-mutedForeground dark:border-border'
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 mb-6 shadow-md hover:shadow-lg transition-all duration-300">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-primary/10 dark:bg-primary/20 rounded-lg">
              <Mail className="w-6 h-6 text-primary dark:text-primary" />
            </div>
            <div>
              <h1 className="text-xl font-semibold text-foreground dark:text-foreground">Email Service</h1>
              <p className="text-mutedForeground dark:text-mutedForeground text-sm">Send trip invitations and updates</p>
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="flex gap-1 bg-muted dark:bg-muted rounded-lg p-1">
            {[
              { id: 'send', label: 'Send Email', icon: Send },
              { id: 'templates', label: 'Templates', icon: FileText },
              { id: 'history', label: 'History', icon: Inbox }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background ${
                  activeTab === tab.id
                    ? 'bg-primary text-primaryForeground shadow-sm dark:bg-primary dark:text-primaryForeground'
                    : 'text-mutedForeground hover:text-foreground hover:bg-surface dark:text-mutedForeground dark:hover:text-foreground dark:hover:bg-surface'
                }`}
                aria-label={`Switch to ${tab.label} tab`}
              >
                <tab.icon className="w-4 h-4" />
                <span className="hidden sm:inline">{tab.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Error State */}
        {error && (
          <div className="rounded-lg bg-destructive/10 dark:bg-destructive/20 border border-destructive/20 dark:border-destructive/30 p-4 mb-6">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 text-destructive dark:text-destructive" />
              <p className="text-sm text-destructive dark:text-destructive">{error}</p>
            </div>
          </div>
        )}

        {/* Send Email Tab */}
        {activeTab === 'send' && (
          <div className="space-y-6">
            {/* Template Selection */}
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
              <h2 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Select Template</h2>
              {isLoading ? (
                <div className="space-y-3 animate-pulse">
                  {[1, 2, 3].map(i => (
                    <div key={i} className="p-4 rounded-lg border border-border dark:border-border">
                      <div className="h-4 bg-muted dark:bg-muted rounded w-3/4 mb-2"></div>
                      <div className="h-3 bg-muted dark:bg-muted rounded w-1/2"></div>
                    </div>
                  ))}
                </div>
              ) : templates.length === 0 ? (
                <div className="text-center py-12">
                  <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                    <FileText className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                  </div>
                  <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No templates yet</h3>
                  <p className="text-mutedForeground dark:text-mutedForeground text-sm">Create your first email template to get started</p>
                </div>
              ) : (
                <div className="grid gap-3">
                  {templates.map(template => (
                    <div
                      key={template.id}
                      onClick={() => setSelectedTemplate(template.id)}
                      className={`p-4 rounded-lg border cursor-pointer transition-all duration-200 hover:scale-[1.01] hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background ${
                        selectedTemplate === template.id
                          ? 'border-primary bg-primary/5 dark:border-primary dark:bg-primary/10'
                          : 'border-border bg-background hover:border-primary/50 dark:border-border dark:bg-background dark:hover:border-primary/50'
                      }`}
                      tabIndex={0}
                      role="button"
                      aria-label={`Select ${template.name} template`}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault()
                          setSelectedTemplate(template.id)
                        }
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="font-medium text-foreground dark:text-foreground">{template.name}</h3>
                        <span className={`px-2 py-1 rounded text-xs font-medium border ${getTemplateTypeColor(template.type)}`}>
                          {template.type}
                        </span>
                      </div>
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground">{template.subject}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Recipients */}
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-foreground dark:text-foreground">Recipients</h2>
                <div className="flex items-center gap-2 text-sm text-mutedForeground dark:text-mutedForeground">
                  <Users className="w-4 h-4" />
                  {recipients.length} members
                </div>
              </div>
              {recipients.length === 0 ? (
                <div className="text-center py-12">
                  <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                    <Users className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                  </div>
                  <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No recipients</h3>
                  <p className="text-mutedForeground dark:text-mutedForeground text-sm">Add team members to send emails</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {recipients.map(recipient => (
                    <div
                      key={recipient.id}
                      className="flex items-center justify-between p-3 bg-background dark:bg-background rounded-lg border border-border dark:border-border hover:shadow-sm transition-all duration-200"
                    >
                      <div>
                        <p className="font-medium text-foreground dark:text-foreground">{recipient.name}</p>
                        <p className="text-sm text-mutedForeground dark:text-mutedForeground">{recipient.email}</p>
                      </div>
                      {getStatusIcon(recipient.status)}
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Send Button */}
            <button
              onClick={handleSendEmail}
              disabled={!selectedTemplate || recipients.length === 0 || isLoading}
              className="w-full px-6 py-4 bg-primary text-primaryForeground rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 font-medium shadow-md hover:shadow-lg hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:bg-primary dark:text-primaryForeground dark:hover:bg-primary/90"
              aria-label={isLoading ? 'Sending emails' : `Send email to ${recipients.length} recipients`}
            >
              {isLoading ? (
                <>
                  <div className="w-4 h-4 border-2 border-primaryForeground/30 border-t-primaryForeground rounded-full animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="w-4 h-4" />
                  Send Email to {recipients.length} Recipients
                </>
              )}
            </button>
          </div>
        )}

        {/* Templates Tab */}
        {activeTab === 'templates' && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Email Templates</h2>
            {templates.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <FileText className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                </div>
                <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No templates yet</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">Create your first email template to get started</p>
              </div>
            ) : (
              <div className="space-y-4">
                {templates.map(template => (
                  <div
                    key={template.id}
                    className="p-4 bg-background dark:bg-background rounded-lg border border-border dark:border-border hover:shadow-md hover:-translate-y-1 transition-all duration-300"
                  >
                    <div className="flex items-center justify-between mb-3">
                      <h3 className="font-medium text-foreground dark:text-foreground">{template.name}</h3>
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getTemplateTypeColor(template.type)}`}>
                        {template.type}
                      </span>
                    </div>
                    <p className="text-sm text-foreground dark:text-foreground mb-2">Subject: {template.subject}</p>
                    <p className="text-sm text-mutedForeground dark:text-mutedForeground line-clamp-2">{template.content}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* History Tab */}
        {activeTab === 'history' && (
          <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 shadow-md hover:shadow-lg transition-all duration-300">
            <h2 className="text-lg font-semibold text-foreground dark:text-foreground mb-4">Email History</h2>
            {campaigns.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <Inbox className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                </div>
                <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No campaigns yet</h3>
                <p className="text-mutedForeground dark:text-mutedForeground text-sm">Your email campaigns will appear here once sent</p>
              </div>
            ) : (
              <div className="space-y-4">
                {campaigns.map(campaign => (
                  <div
                    key={campaign.id}
                    className="p-4 bg-background dark:bg-background rounded-lg border border-border dark:border-border hover:shadow-md hover:-translate-y-1 transition-all duration-300"
                  >
                    <div className="flex items-center justify-between mb-3">
                      <div>
                        <h3 className="font-medium text-foreground dark:text-foreground">{campaign.tripName}</h3>
                        <p className="text-sm text-mutedForeground dark:text-mutedForeground">
                          {campaign.sentAt ? `Sent ${campaign.sentAt.toLocaleDateString()}` : 'Not sent'}
                        </p>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(campaign.status)}`}>
                        {campaign.status}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-sm text-mutedForeground dark:text-mutedForeground">
                      <span>{campaign.recipients.length} recipients</span>
                      <span>•</span>
                      <span>
                        {campaign.recipients.filter(r => r.status === 'sent').length} delivered
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

