    switch (condition) {
      case 'sunny': return <Sun className={`${iconClass} text-accent`} />
      case 'cloudy': return <Cloud className={`${iconClass} text-mutedForeground dark:text-muted-foreground`} />
      case 'rainy': return <CloudRain className={`${iconClass} text-primary dark:text-primary`} />
      case 'snowy': return <Snow className={`${iconClass} text-primary dark:text-primary`} />
      case 'windy': return <Wind className={`${iconClass} text-mutedForeground dark:text-muted-foreground`} />
      default: return <Sun className={`${iconClass} text-accent`} />
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'planning': return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20'
      case 'confirmed': return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      case 'completed': return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-muted-foreground dark:border-border'
      default: return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-muted-foreground dark:border-border'
    }
  }

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'food': return 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20'
      case 'gear': return 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
      case 'logistics': return 'bg-secondary/10 text-secondary border-secondary/20 dark:bg-secondary/10 dark:text-secondary dark:border-secondary/20'
      default: return 'bg-muted text-mutedForeground border-border dark:bg-muted dark:text-muted-foreground dark:border-border'
    }
  }

  const toggleTask = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const sendMessage = () => {
    if (newMessage.trim()) {
      const message = {
        id: Date.now().toString(),
        user: 'You',
        message: newMessage,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }
      setMessages(prev => [...prev, message])
      setNewMessage('')
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      sendMessage()
    }
  }

  const handleCreateTrip = () => {
    setIsLoading(true)
    setTimeout(() => {
      onCreateTrip({
        name: 'New Adventure',
        location: 'TBD',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        status: 'planning',
        memberCount: 1,
        weatherForecast: []
      })
      setIsLoading(false)
    }, 500)
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
