              <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary dark:from-primary dark:to-secondary rounded-lg flex items-center justify-center shadow-sm">
                <MapPin className="w-5 h-5 text-primaryForeground dark:text-primary-foreground" />
              </div>
              <h1 className="text-xl font-bold text-foreground dark:text-foreground">OffRoad Planner</h1>
            </div>
            <button 
              onClick={handleCreateTrip}
              disabled={isLoading}
              className="inline-flex items-center gap-2 px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primary-foreground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium text-sm shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100"
              aria-label="Create new trip"
            >
              {isLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Plus className="w-4 h-4" />
              )}
              New Trip
            </button>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="bg-surface/50 dark:bg-surface/50 backdrop-blur-sm border-b border-border dark:border-border">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex space-x-1 py-3 overflow-x-auto">
            {[
              { id: 'trips', label: 'Trips', icon: MapPin },
              { id: 'tasks', label: 'Tasks', icon: CheckSquare },
              { id: 'weather', label: 'Weather', icon: Sun },
              { id: 'chat', label: 'Chat', icon: MessageCircle }
