                  {selectedTrip.weatherForecast.map((weather, index) => (
                    <div key={index} className="bg-muted/50 dark:bg-muted/50 rounded-lg p-4 border border-border/50 dark:border-border/50 hover:border-border dark:hover:border-border transition-all duration-150">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-foreground dark:text-foreground font-medium">
                          {new Date(weather.date).toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' })}
                        </span>
                        {getWeatherIcon(weather.condition)}
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-mutedForeground dark:text-muted-foreground capitalize">{weather.condition}</span>
                        <span className="text-foreground dark:text-foreground font-medium">{weather.high}°/{weather.low}°</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="space-y-4">
            <div className="bg-surface dark:bg-surface backdrop-blur-sm border border-border dark:border-border rounded-xl shadow-sm overflow-hidden">
              <div className="p-4 border-b border-border dark:border-border">
                <h2 className="text-xl font-semibold text-foreground dark:text-foreground">Group Chat</h2>
              </div>
              <div className="h-96 overflow-y-auto p-4 space-y-3">
                {messages.length === 0 ? (
                  <div className="text-center py-8">
                    <div className="w-12 h-12 bg-muted dark:bg-muted rounded-full mx-auto mb-3 flex items-center justify-center">
                      <MessageCircle className="w-6 h-6 text-mutedForeground dark:text-muted-foreground" />
                    </div>
                    <h3 className="text-base font-medium text-foreground dark:text-foreground mb-1">No messages yet</h3>
                    <p className="text-mutedForeground dark:text-muted-foreground text-sm">Start the conversation</p>
                  </div>
                ) : (
                  messages.map((msg) => (
                    <div key={msg.id} className={`flex ${msg.user === 'You' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                        msg.user === 'You'
                          ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primary-foreground'
                          : 'bg-muted dark:bg-muted text-foreground dark:text-foreground'
                      }`}>
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-medium opacity-80">{msg.user}</span>
                          <span className="text-xs opacity-60">{msg.time}</span>
                        </div>
                        <p className="text-sm">{msg.message}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
              <div className="p-4 border-t border-border dark:border-border">
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder="Type a message..."
                    className="flex-1 px-4 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-muted-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background transition-all duration-150"
                  />
                  <button
                    onClick={sendMessage}
                    disabled={!newMessage.trim()}
                    className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primary-foreground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100"
                    aria-label="Send message"
                  >
                    Send
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

