export function OffRoadTripPlanner() {
  const [activeTab, setActiveTab] = useState('locations')
  const [locations, setLocations] = useState(MOCK_LOCATIONS)
  const [members, setMembers] = useState(MOCK_MEMBERS)
  const [tasks, setTasks] = useState(MOCK_TASKS)
  const [meals] = useState(MOCK_MEALS)
  const [chatMessages, setChatMessages] = useState(MOCK_CHAT)
  const [newMessage, setNewMessage] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const toggleLocationSave = (locationId: string) => {
    setLocations(prev => prev.map(loc => 
      loc.id === locationId ? { ...loc, saved: !loc.saved } : loc
    ))
  }

  const updateRSVP = (memberId: string, status: 'yes' | 'no' | 'maybe') => {
    setMembers(prev => prev.map(member =>
      member.id === memberId ? { ...member, rsvp: status } : member
    ))
  }

  const toggleTaskComplete = (taskId: string) => {
    setTasks(prev => prev.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ))
  }

  const sendMessage = () => {
    if (newMessage.trim()) {
      const message: ChatMessage = {
        id: Date.now().toString(),
        sender: 'You',
        message: newMessage,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        avatar: 'YU'
      }
      setChatMessages(prev => [...prev, message])
      setNewMessage('')
    }
  }

  const filteredLocations = locations.filter(location =>
    location.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    location.terrain.toLowerCase().includes(searchQuery.toLowerCase())
  )

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Easy': return 'bg-primary/20 text-primary border-primary/30 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'Moderate': return 'bg-accent/20 text-accent border-accent/30 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      case 'Difficult': return 'bg-destructive/20 text-destructive border-destructive/30 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      default: return 'bg-muted/20 text-mutedForeground border-border dark:bg-muted/20 dark:text-mutedForeground dark:border-border'
    }
  }

  const getRSVPColor = (rsvp: string) => {
    switch (rsvp) {
      case 'yes': return 'bg-primary/20 text-primary border-primary/30 dark:bg-primary/20 dark:text-primary dark:border-primary/30'
      case 'no': return 'bg-destructive/20 text-destructive border-destructive/30 dark:bg-destructive/20 dark:text-destructive dark:border-destructive/30'
      case 'maybe': return 'bg-accent/20 text-accent border-accent/30 dark:bg-accent/20 dark:text-accent dark:border-accent/30'
      default: return 'bg-muted/20 text-mutedForeground border-border dark:bg-muted/20 dark:text-mutedForeground dark:border-border'
    }
  }

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'food': return UtensilsCrossed
      case 'equipment': return Mountain
      case 'logistics': return Calendar
      default: return CheckSquare
    }
  }

