'use client'

import { useState } from 'react'
import { MapPin, Calendar, Users, MessageSquare, Utensils, CheckCircle, AlertCircle, Send } from 'lucide-react'

interface TripFormData {
  tripName: string
  location: string
  startDate: string
  endDate: string
  description: string
  maxParticipants: number
}

interface FormErrors {
  [key: string]: string
}

interface TripPlanningFormProps {
  onSubmit?: (data: TripFormData) => void
  initialData?: Partial<TripFormData>
  isLoading?: boolean
}

export function TripPlanningForm({
  onSubmit = (data) => console.log('Trip planned:', data),
  initialData = {},
  isLoading = false
}: TripPlanningFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    tripName: initialData.tripName || '',
    location: initialData.location || '',
    startDate: initialData.startDate || '',
    endDate: initialData.endDate || '',
    description: initialData.description || '',
    maxParticipants: initialData.maxParticipants || 8
  })

  const [errors, setErrors] = useState<FormErrors>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitSuccess, setSubmitSuccess] = useState(false)

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {}

    if (!formData.tripName.trim()) {
      newErrors.tripName = 'Trip name is required'
    }

    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }

    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }

    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) > new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    if (formData.maxParticipants < 1 || formData.maxParticipants > 50) {
      newErrors.maxParticipants = 'Participants must be between 1 and 50'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleInputChange = (field: keyof TripFormData, value: string | number) => {
    setFormData(prev => ({ ...prev, [field]: value }))

    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onSubmit(formData)
      setSubmitSuccess(true)

      setTimeout(() => {
        setSubmitSuccess(false)
        setFormData({
          tripName: '',
          location: '',
          startDate: '',
          endDate: '',
          description: '',
          maxParticipants: 8
        })
      }, 2000)
    } catch (error) {
      setErrors({ submit: 'Failed to create trip. Please try again.' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const inputClassName = "w-full px-4 py-3 bg-background dark:bg-surface border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-primary dark:focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/20 dark:focus:ring-ring/20 transition-all duration-200 text-base font-sans"
  const errorInputClassName = "w-full px-4 py-3 bg-background dark:bg-surface border border-destructive dark:border-destructive rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-destructive dark:focus:border-destructive focus:outline-none focus:ring-2 focus:ring-destructive/20 dark:focus:ring-destructive/20 transition-all duration-200 text-base font-sans"

  if (submitSuccess) {
    return (
      <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
        <div className="max-w-md mx-auto pt-20">
          <div className="bg-surface dark:bg-surface rounded-2xl p-8 text-center shadow-lg border border-border dark:border-border">
            <div className="w-16 h-16 bg-primary/10 dark:bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle className="w-8 h-8 text-primary dark:text-primary" />
            </div>
            <h2 className="text-2xl font-bold text-foreground dark:text-foreground mb-2">Trip Created!</h2>
            <p className="text-mutedForeground dark:text-mutedForeground mb-6">Your off-road adventure has been planned successfully. Invites will be sent to your group.</p>
            <div className="space-y-2 text-sm text-mutedForeground dark:text-mutedForeground">
              <div className="flex items-center justify-center gap-2">
                <MapPin className="w-4 h-4" />
                <span>{formData.location}</span>
              </div>
              <div className="flex items-center justify-center gap-2">
                <Calendar className="w-4 h-4" />
                <span>{new Date(formData.startDate).toLocaleDateString()} - {new Date(formData.endDate).toLocaleDateString()}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-md mx-auto">
        <div className="text-center mb-8 pt-8">
          <div className="w-16 h-16 bg-primary dark:bg-primary rounded-full flex items-center justify-center mx-auto mb-4 hover:scale-105 transition-transform duration-200">
