'use client'

import { useState } from 'react'
import { Calendar, MapPin, Users, Clock, Mountain, Plus, X } from 'lucide-react'

interface TripMember {
  id: string
  name: string
  email: string
}

interface CreateTripFormProps {
  onSubmit?: (tripData: TripFormData) => void
  initialData?: Partial<TripFormData>
}

interface TripFormData {
  name: string
  location: string
  startDate: string
  endDate: string
  description: string
  members: TripMember[]
  difficulty: 'easy' | 'moderate' | 'difficult'
  vehicleType: 'atv' | 'utv' | 'truck' | 'jeep' | 'motorcycle'
}

const DEFAULT_FORM_DATA: TripFormData = {
  name: '',
  location: '',
  startDate: '',
  endDate: '',
  description: '',
  members: [],
  difficulty: 'moderate',
  vehicleType: 'jeep'
}

export function CreateTripForm({
  onSubmit = (data) => console.log('Trip created:', data),
  initialData = {}
}: CreateTripFormProps = {}) {
  const [formData, setFormData] = useState<TripFormData>({
    ...DEFAULT_FORM_DATA,
    ...initialData
  })
  const [newMemberEmail, setNewMemberEmail] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name.trim()) {
      newErrors.name = 'Trip name is required'
    }
    if (!formData.location.trim()) {
      newErrors.location = 'Location is required'
    }
    if (!formData.startDate) {
      newErrors.startDate = 'Start date is required'
    }
    if (!formData.endDate) {
      newErrors.endDate = 'End date is required'
    }
    if (formData.startDate && formData.endDate && new Date(formData.startDate) >= new Date(formData.endDate)) {
      newErrors.endDate = 'End date must be after start date'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    setIsSubmitting(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1000))
      onSubmit(formData)

      setFormData(DEFAULT_FORM_DATA)
      setNewMemberEmail('')
      setErrors({})
    } catch (error) {
      console.error('Failed to create trip:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const addMember = () => {
    if (!newMemberEmail.trim() || !newMemberEmail.includes('@')) {
      return
    }

    const newMember: TripMember = {
      id: Date.now().toString(),
      name: newMemberEmail.split('@')[0],
      email: newMemberEmail.trim()
    }

    setFormData(prev => ({
      ...prev,
      members: [...prev.members, newMember]
    }))
    setNewMemberEmail('')
  }

  const removeMember = (memberId: string) => {
    setFormData(prev => ({
      ...prev,
      members: prev.members.filter(member => member.id !== memberId)
    }))
  }

  const updateField = (field: keyof TripFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background p-4 font-sans">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border shadow-lg overflow-hidden">
          <div className="bg-gradient-to-r from-primary to-primary/90 dark:from-primary dark:to-primary/90 p-6">
            <div className="flex items-center gap-3">
              <Mountain className="w-8 h-8 text-primaryForeground dark:text-primaryForeground" />
              <div>
                <h1 className="text-2xl font-bold text-primaryForeground dark:text-primaryForeground">Plan Your Adventure</h1>
                <p className="text-primaryForeground/80 dark:text-primaryForeground/80 text-sm">Create an epic off-roading trip</p>
              </div>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div>
              <label htmlFor="trip-name" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Trip Name
              </label>
              <input
                id="trip-name"
                type="text"
                value={formData.name}
                onChange={(e) => updateField('name', e.target.value)}
                placeholder="Epic Desert Adventure"
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                aria-describedby={errors.name ? "name-error" : undefined}
              />
              {errors.name && (
                <p id="name-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.name}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="location" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                <MapPin className="w-4 h-4 inline mr-1" />
                Location
              </label>
              <input
                id="location"
                type="text"
                value={formData.location}
                onChange={(e) => updateField('location', e.target.value)}
                placeholder="Moab, Utah"
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                aria-describedby={errors.location ? "location-error" : undefined}
              />
              {errors.location && (
                <p id="location-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                  {errors.location}
                </p>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="start-date" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  <Calendar className="w-4 h-4 inline mr-1" />
                  Start Date
                </label>
                <input
                  id="start-date"
                  type="date"
                  value={formData.startDate}
                  onChange={(e) => updateField('startDate', e.target.value)}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  aria-describedby={errors.startDate ? "start-date-error" : undefined}
                />
                {errors.startDate && (
                  <p id="start-date-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.startDate}
                  </p>
                )}
              </div>

              <div>
                <label htmlFor="end-date" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  <Clock className="w-4 h-4 inline mr-1" />
                  End Date
                </label>
                <input
                  id="end-date"
                  type="date"
                  value={formData.endDate}
                  onChange={(e) => updateField('endDate', e.target.value)}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  aria-describedby={errors.endDate ? "end-date-error" : undefined}
                />
                {errors.endDate && (
                  <p id="end-date-error" className="mt-1 text-sm text-destructive dark:text-destructive" role="alert">
                    {errors.endDate}
                  </p>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="difficulty" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Difficulty Level
                </label>
                <select
                  id="difficulty"
                  value={formData.difficulty}
                  onChange={(e) => updateField('difficulty', e.target.value as TripFormData['difficulty'])}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                >
                  <option value="easy">Easy - Beginner Friendly</option>
                  <option value="moderate">Moderate - Some Experience</option>
                  <option value="difficult">Difficult - Expert Level</option>
                </select>
              </div>

              <div>
                <label htmlFor="vehicle-type" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                  Vehicle Type
                </label>
                <select
                  id="vehicle-type"
                  value={formData.vehicleType}
                  onChange={(e) => updateField('vehicleType', e.target.value as TripFormData['vehicleType'])}
                  className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                >
                  <option value="jeep">Jeep/4x4</option>
                  <option value="truck">Pickup Truck</option>
                  <option value="atv">ATV</option>
                  <option value="utv">UTV/Side-by-Side</option>
                  <option value="motorcycle">Motorcycle</option>
                </select>
              </div>
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                Description
              </label>
              <textarea
                id="description"
                value={formData.description}
                onChange={(e) => updateField('description', e.target.value)}
                placeholder="Describe your adventure, what to expect, what to bring..."
                rows={4}
                className="w-full px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200 resize-none"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-foreground dark:text-foreground mb-3">
                <Users className="w-4 h-4 inline mr-1" />
                Group Members ({formData.members.length})
              </label>

              <div className="flex gap-2 mb-4">
                <input
                  type="email"
                  value={newMemberEmail}
                  onChange={(e) => setNewMemberEmail(e.target.value)}
                  placeholder="friend@email.com"
                  className="flex-1 px-4 py-3 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-mutedForeground dark:placeholder-mutedForeground focus:border-ring dark:focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50 transition-all duration-200"
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addMember())}
                />
                <button
                  type="button"
                  onClick={addMember}
                  className="px-4 py-3 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium min-w-[44px] min-h-[44px] flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                  aria-label="Add member"
                >
                  <Plus className="w-5 h-5" />
                </button>
              </div>

              {formData.members.length > 0 ? (
                <div className="space-y-2">
                  {formData.members.map((member) => (
                    <div
                      key={member.id}
                      className="flex items-center justify-between p-3 bg-muted dark:bg-muted rounded-lg border border-border dark:border-border hover:-translate-y-0.5 hover:shadow-md transition-all duration-200"
                    >
                      <div>
                        <p className="text-foreground dark:text-foreground font-medium">{member.name}</p>
                        <p className="text-mutedForeground dark:text-mutedForeground text-sm">{member.email}</p>
                      </div>
                      <button
                        type="button"
                        onClick={() => removeMember(member.id)}
                        className="p-2 text-mutedForeground dark:text-mutedForeground hover:text-destructive dark:hover:text-destructive transition-colors duration-150 min-w-[44px] min-h-[44px] flex items-center justify-center rounded-md hover:bg-destructive/10 dark:hover:bg-destructive/10 focus:outline-none focus:ring-2 focus:ring-ring/50 dark:focus:ring-ring/50"
                        aria-label={`Remove ${member.name}`}
                      >
                        <X className="w-4 h-4" />
