    date: new Date(2024, 2, 15, 18, 0),
    startTime: '18:00',
    endTime: '19:30',
    type: 'meal',
    assignedTo: ['user2'],
    description: 'Campfire chili and cornbread'
  }
]

const DEFAULT_MEMBERS = [
  { id: 'user1', name: 'Alex Chen' },
  { id: 'user2', name: 'Sarah Miller' },
  { id: 'user3', name: 'Mike Johnson' },
  { id: 'user4', name: 'Emma Davis' }
]

export function TripScheduler({
  tripId = 'trip-1',
  startDate = new Date(2024, 2, 15),
  endDate = new Date(2024, 2, 17),
  events = DEFAULT_EVENTS,
  groupMembers = DEFAULT_MEMBERS,
  onEventCreate = (event) => console.log('Create event:', event),
  onEventUpdate = (id, updates) => console.log('Update event:', id, updates),
  onEventDelete = (id) => console.log('Delete event:', id)
}: TripScheduleProps = {}) {
  const [currentDate, setCurrentDate] = useState(startDate)
  const [selectedEvent, setSelectedEvent] = useState<TripEvent | null>(null)
  const [showEventForm, setShowEventForm] = useState(false)
  const [viewMode, setViewMode] = useState<'day' | 'timeline'>('day')

  const tripDates = []
  const current = new Date(startDate)
  while (current <= endDate) {
    tripDates.push(new Date(current))
    current.setDate(current.getDate() + 1)
  }

  const dayEvents = events.filter(event => 
    event.date.toDateString() === currentDate.toDateString()
  ).sort((a, b) => a.startTime.localeCompare(b.startTime))

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    })
  }

  const formatTime = (time: string) => {
    const [hours, minutes] = time.split(':')
    const hour = parseInt(hours)
    const ampm = hour >= 12 ? 'PM' : 'AM'
    const displayHour = hour % 12 || 12
    return `${displayHour}:${minutes} ${ampm}`
  }

  const getEventTypeColor = (type: TripEvent['type']) => {
    switch (type) {
      case 'meal': return 'bg-accent dark:bg-accent'
      case 'activity': return 'bg-primary dark:bg-primary'
      case 'task': return 'bg-secondary dark:bg-secondary'
      case 'travel': return 'bg-primary dark:bg-primary'
      default: return 'bg-muted dark:bg-muted'
    }
  }

  const getEventTypeBg = (type: TripEvent['type']) => {
    switch (type) {
      case 'meal': return 'bg-surface dark:bg-surface border-accent/20 dark:border-accent/20'
      case 'activity': return 'bg-surface dark:bg-surface border-primary/20 dark:border-primary/20'
      case 'task': return 'bg-surface dark:bg-surface border-secondary/20 dark:border-secondary/20'
      case 'travel': return 'bg-surface dark:bg-surface border-primary/20 dark:border-primary/20'
      default: return 'bg-surface dark:bg-surface border-border dark:border-border'
    }
  }

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate)
    newDate.setDate(newDate.getDate() + (direction === 'next' ? 1 : -1))

    if (newDate >= startDate && newDate <= endDate) {
      setCurrentDate(newDate)
    }
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background text-foreground dark:text-foreground font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6">
        <div className="mb-6">
          <h1 className="text-3xl font-bold mb-2 text-foreground dark:text-foreground">Trip Schedule</h1>
          <p className="text-mutedForeground dark:text-mutedForeground">Plan and coordinate your off-road adventure</p>
        </div>

        <div className="flex items-center justify-between mb-6">
          <div className="flex bg-surface dark:bg-surface rounded-lg p-1 border border-border dark:border-border">
            <button
              onClick={() => setViewMode('day')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                viewMode === 'day'
                  ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-sm'
                  : 'text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground'
              }`}
              aria-label="Switch to day view"
            >
              Day View
            </button>
            <button
              onClick={() => setViewMode('timeline')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background ${
                viewMode === 'timeline'
                  ? 'bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground shadow-sm'
                  : 'text-mutedForeground dark:text-mutedForeground hover:text-foreground dark:hover:text-foreground'
              }`}
              aria-label="Switch to timeline view"
            >
              Timeline
            </button>
          </div>

          <button
            onClick={() => setShowEventForm(true)}
            className="flex items-center gap-2 px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-background dark:focus:ring-offset-background"
            aria-label="Add new event"
          >
            <Plus className="w-4 h-4" />
            Add Event
          </button>
        </div>

        {viewMode === 'day' ? (
          <>
            <div className="flex items-center justify-between mb-6 bg-surface dark:bg-surface rounded-xl p-4 border border-border dark:border-border">
              <button
                onClick={() => navigateDate('prev')}
                disabled={currentDate <= startDate}
                className="p-2 rounded-lg hover:bg-muted dark:hover:bg-muted transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
                aria-label="Previous day"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="text-center">
                <h2 className="text-xl font-semibold text-foreground dark:text-foreground">{formatDate(currentDate)}</h2>
                <p className="text-sm text-mutedForeground dark:text-mutedForeground">
                  Day {tripDates.findIndex(date => date.toDateString() === currentDate.toDateString()) + 1} of {tripDates.length}
                </p>
              </div>

              <button
                onClick={() => navigateDate('next')}
                disabled={currentDate >= endDate}
                className="p-2 rounded-lg hover:bg-muted dark:hover:bg-muted transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
                aria-label="Next day"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-4">
              {dayEvents.length === 0 ? (
                <div className="text-center py-12 bg-surface dark:bg-surface rounded-xl border border-border dark:border-border">
                  <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                    <Calendar className="w-8 h-8 text-mutedForeground dark:text-mutedForeground" />
                  </div>
                  <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No events scheduled</h3>
                  <p className="text-mutedForeground dark:text-mutedForeground mb-4">Add your first event to get started</p>
                  <button
                    onClick={() => setShowEventForm(true)}
                    className="px-4 py-2 bg-primary dark:bg-primary text-primaryForeground dark:text-primaryForeground rounded-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
                    aria-label="Add first event"
                  >
                    Add Event
                  </button>
                </div>
              ) : (
                dayEvents.map((event) => (
                  <div
                    key={event.id}
                    className={`bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4 hover:border-primary/50 dark:hover:border-primary/50 hover:-translate-y-1 hover:shadow-lg transition-all duration-300 cursor-pointer ${getEventTypeBg(event.type)}`}
                    onClick={() => setSelectedEvent(event)}
                  >
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <div className={`w-3 h-3 rounded-full ${getEventTypeColor(event.type)}`} />
                        <h3 className="font-semibold text-foreground dark:text-foreground">{event.title}</h3>
                      </div>
                      <span className="text-xs px-2 py-1 bg-muted dark:bg-muted text-mutedForeground dark:text-mutedForeground rounded-full capitalize">
                        {event.type}
                      </span>
                    </div>

                    <div className="flex items-center gap-4 text-sm text-mutedForeground dark:text-mutedForeground mb-3">
                      <div className="flex items-center gap-1">
                        <Clock className="w-4 h-4" />
                        <span>
                          {formatTime(event.startTime)}
                          {event.endTime && ` - ${formatTime(event.endTime)}`}
                        </span>
                      </div>
                      {event.location && (
                        <div className="flex items-center gap-1">
                          <MapPin className="w-4 h-4" />
                          <span>{event.location}</span>
                        </div>
                      )}
                    </div>

                    {event.description && (
                      <p className="text-sm text-mutedForeground dark:text-mutedForeground mb-3">{event.description}</p>
                    )}

                    {event.assignedTo && event.assignedTo.length > 0 && (
                      <div className="flex items-center gap-2">
                        <Users className="w-4 h-4 text-mutedForeground dark:text-mutedForeground" />
                        <div className="flex gap-1">
                          {event.assignedTo.map((userId) => {
                            const member = groupMembers.find(m => m.id === userId)
                            return (
                              <span
                                key={userId}
                                className="text-xs px-2 py-1 bg-primary/10 dark:bg-primary/10 text-primary dark:text-primary rounded-full"
                              >
                                {member?.name || 'Unknown'}
                              </span>
                            )
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>
          </>
        ) : (
          <div className="bg-surface dark:bg-surface rounded-xl p-6 border border-border dark:border-border">
            <h3 className="text-lg font-semibold mb-4 text-foreground dark:text-foreground">Trip Timeline</h3>
            <div className="space-y-6">
              {tripDates.map((date) => {
                const dateEvents = events.filter(event => 
                  event.date.toDateString() === date.toDateString()
                ).sort((a, b) => a.startTime.localeCompare(b.startTime))

                return (
                  <div key={date.toISOString()} className="border-l-2 border-border dark:border-border pl-4">
                    <h4 className="font-medium text-primary dark:text-primary mb-2">{formatDate(date)}</h4>
                    {dateEvents.length === 0 ? (
                      <p className="text-mutedForeground dark:text-mutedForeground text-sm">No events scheduled</p>
                    ) : (
                      <div className="space-y-2">
                        {dateEvents.map((event) => (
                          <div
                            key={event.id}
                            className="flex items-center gap-3 p-2 bg-muted dark:bg-muted rounded-lg hover:bg-accent/10 dark:hover:bg-accent/10 hover:scale-[1.02] transition-all duration-200 cursor-pointer focus:outline-none focus:ring-2 focus:ring-ring dark:focus:ring-ring focus:ring-offset-2 focus:ring-offset-surface dark:focus:ring-offset-surface"
                            onClick={() => setSelectedEvent(event)}
                            tabIndex={0}
                            role="button"
                            aria-label={`View event: ${event.title}`}
                          >
                            <div className={`w-2 h-2 rounded-full ${getEventTypeColor(event.type)}`} />
                            <span className="text-sm font-medium text-foreground dark:text-foreground">{formatTime(event.startTime)}</span>
                            <span className="text-sm text-foreground dark:text-foreground">{event.title}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-6">
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-border dark:border-border hover:shadow-md transition-all duration-300">
            <div className="text-2xl font-bold text-accent dark:text-accent">{events.filter(e => e.type === 'meal').length}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Meals</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-border dark:border-border hover:shadow-md transition-all duration-300">
            <div className="text-2xl font-bold text-primary dark:text-primary">{events.filter(e => e.type === 'activity').length}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Activities</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-border dark:border-border hover:shadow-md transition-all duration-300">
            <div className="text-2xl font-bold text-secondary dark:text-secondary">{events.filter(e => e.type === 'task').length}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Tasks</div>
          </div>
          <div className="bg-surface dark:bg-surface rounded-xl p-4 text-center border border-border dark:border-border hover:shadow-md transition-all duration-300">
            <div className="text-2xl font-bold text-primary dark:text-primary">{tripDates.length}</div>
            <div className="text-sm text-mutedForeground dark:text-mutedForeground">Days</div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function TripSchedulerDemo() {
  return <TripScheduler />
}

