'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, MoreVertical, MapPin, Calendar, Users, Image, Paperclip } from 'lucide-react'

interface Message {
  id: string
  userId: string
  userName: string
  userAvatar: string
  content: string
  timestamp: Date
  type: 'text' | 'location' | 'event' | 'image'
  metadata?: {
    location?: { lat: number; lng: number; name: string }
    event?: { title: string; date: string }
    imageUrl?: string
  }
}

interface GroupChatUIProps {
  tripId?: string
  messages?: Message[]
  currentUserId?: string
  onSendMessage?: (content: string, type: 'text' | 'location' | 'event' | 'image') => void
  onLoadMore?: () => void
  isLoading?: boolean
}

export function GroupChatUI({
  tripId = 'trip-1',
  messages = DEFAULT_MESSAGES,
  currentUserId = 'user-1',
  onSendMessage = (content, type) => console.log('Send message:', content, type),
  onLoadMore = () => console.log('Load more messages'),
  isLoading = false
}: GroupChatUIProps = {}) {
  const [newMessage, setNewMessage] = useState('')
  const [showAttachments, setShowAttachments] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      onSendMessage(newMessage.trim(), 'text')
      setNewMessage('')
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto'
      }
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewMessage(e.target.value)

    const textarea = e.target
    textarea.style.height = 'auto'
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px'
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(date)
  }

  const formatDate = (date: Date) => {
    const today = new Date()
    const messageDate = new Date(date)

    if (messageDate.toDateString() === today.toDateString()) {
      return 'Today'
    }

    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (messageDate.toDateString() === yesterday.toDateString()) {
      return 'Yesterday'
    }

    return messageDate.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric' 
    })
  }

  const renderMessage = (message: Message) => {
    const isOwn = message.userId === currentUserId

    return (
      <div
        key={message.id}
        className={`flex gap-3 ${isOwn ? 'flex-row-reverse' : 'flex-row'}`}
      >
        {!isOwn && (
          <div className="flex-shrink-0">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-primary/80 flex items-center justify-center text-primaryForeground text-sm font-medium">
              {message.userName.charAt(0).toUpperCase()}
            </div>
          </div>
        )}

        <div className={`flex flex-col max-w-[75%] ${isOwn ? 'items-end' : 'items-start'}`}>
          {!isOwn && (
            <span className="text-xs text-mutedForeground mb-1 px-1 font-medium">
              {message.userName}
            </span>
          )}

          <div
            className={`rounded-2xl px-4 py-3 transition-all duration-150 hover:scale-[1.02] ${
              isOwn
                ? 'bg-primary text-primaryForeground shadow-sm'
                : 'bg-muted text-foreground border border-border shadow-sm'
            }`}
          >
            {message.type === 'text' && (
              <p className="text-sm leading-relaxed whitespace-pre-wrap">
                {message.content}
              </p>
            )}

            {message.type === 'location' && message.metadata?.location && (
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${isOwn ? 'bg-primaryForeground/20' : 'bg-primary/10'}`}>
                  <MapPin className={`w-4 h-4 ${isOwn ? 'text-primaryForeground' : 'text-primary'}`} />
                </div>
                <div>
                  <p className="text-sm font-semibold">{message.metadata.location.name}</p>
                  <p className={`text-xs ${isOwn ? 'text-primaryForeground/75' : 'text-mutedForeground'}`}>
                    Shared location
                  </p>
                </div>
              </div>
            )}

            {message.type === 'event' && message.metadata?.event && (
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${isOwn ? 'bg-primaryForeground/20' : 'bg-secondary/10'}`}>
                  <Calendar className={`w-4 h-4 ${isOwn ? 'text-primaryForeground' : 'text-secondary'}`} />
                </div>
                <div>
                  <p className="text-sm font-semibold">{message.metadata.event.title}</p>
                  <p className={`text-xs ${isOwn ? 'text-primaryForeground/75' : 'text-mutedForeground'}`}>
                    {message.metadata.event.date}
                  </p>
                </div>
              </div>
            )}

            {message.type === 'image' && message.metadata?.imageUrl && (
              <div>
                <img
                  src={message.metadata.imageUrl}
                  alt="Shared image"
                  className="rounded-lg max-w-full h-auto"
                />
                {message.content && (
                  <p className="text-sm mt-2">{message.content}</p>
                )}
              </div>
            )}
          </div>

          <span className={`text-xs text-mutedForeground mt-1 px-1 ${isOwn ? 'text-right' : 'text-left'}`}>
            {formatTime(message.timestamp)}
          </span>
        </div>
      </div>
    )
  }

  const groupMessagesByDate = (messages: Message[]) => {
    const groups: { [key: string]: Message[] } = {}

    messages.forEach(message => {
      const dateKey = message.timestamp.toDateString()
      if (!groups[dateKey]) {
        groups[dateKey] = []
      }
      groups[dateKey].push(message)
    })

    return groups
  }

  const messageGroups = groupMessagesByDate(messages)

  return (
    <div className="flex flex-col h-screen bg-background font-sans">
      <div className="flex items-center justify-between p-4 border-b border-border bg-surface shadow-sm">
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            {DEFAULT_PARTICIPANTS.slice(0, 3).map((participant, index) => (
              <div
                key={participant.id}
                className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-primary/80 flex items-center justify-center text-primaryForeground text-xs font-semibold border-2 border-background shadow-sm"
                style={{ zIndex: 10 - index }}
              >
                {participant.name.charAt(0).toUpperCase()}
              </div>
            ))}
            {DEFAULT_PARTICIPANTS.length > 3 && (
              <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-mutedForeground text-xs font-semibold border-2 border-background shadow-sm">
                +{DEFAULT_PARTICIPANTS.length - 3}
              </div>
            )}
          </div>
          <div>
            <h2 className="font-semibold text-foreground text-lg">Moab Adventure</h2>
            <p className="text-xs text-mutedForeground">{DEFAULT_PARTICIPANTS.length} members</p>
          </div>
        </div>

        <button
          className="p-2 hover:bg-muted rounded-lg transition-all duration-150 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 active:scale-95"
          aria-label="Chat options"
        >
          <MoreVertical className="w-5 h-5 text-mutedForeground" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {isLoading && (
          <div className="flex justify-center py-8">
            <div className="space-y-4 animate-pulse w-full max-w-md">
              <div className="h-4 bg-muted rounded w-3/4"></div>
              <div className="h-4 bg-muted rounded w-1/2"></div>
              <div className="h-4 bg-muted rounded w-2/3"></div>
            </div>
          </div>
        )}

        {messages.length === 0 && !isLoading ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
              <Users className="w-8 h-8 text-mutedForeground" />
            </div>
            <h3 className="text-lg font-semibold text-foreground mb-2">No messages yet</h3>
            <p className="text-mutedForeground text-sm">Start the conversation with your group</p>
          </div>
        ) : (
          Object.entries(messageGroups).map(([dateKey, dayMessages]) => (
            <div key={dateKey}>
              <div className="flex justify-center mb-6">
                <span className="px-3 py-1 bg-muted text-mutedForeground text-xs rounded-full font-medium border border-border">
                  {formatDate(new Date(dateKey))}
                </span>
              </div>

              <div className="space-y-4">
                {dayMessages.map(renderMessage)}
              </div>
            </div>
          ))
        )}

        <div ref={messagesEndRef} />
      </div>

      {showAttachments && (
        <div className="p-4 border-t border-border bg-surface">
          <div className="flex gap-3">
            <button
              onClick={() => {
                onSendMessage('Current location shared', 'location')
                setShowAttachments(false)
              }}
              className="flex flex-col items-center gap-2 p-4 bg-background rounded-xl border border-border hover:border-primary/30 hover:bg-primary/5 transition-all duration-200 min-w-0 flex-1 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              aria-label="Share location"
            >
              <MapPin className="w-6 h-6 text-primary" />
              <span className="text-xs text-mutedForeground font-medium">Location</span>
            </button>

            <button
              onClick={() => {
                onSendMessage('Event shared', 'event')
                setShowAttachments(false)
              }}
              className="flex flex-col items-center gap-2 p-4 bg-background rounded-xl border border-border hover:border-secondary/30 hover:bg-secondary/5 transition-all duration-200 min-w-0 flex-1 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              aria-label="Share event"
            >
              <Calendar className="w-6 h-6 text-secondary" />
              <span className="text-xs text-mutedForeground font-medium">Event</span>
            </button>

            <button
              onClick={() => {
                onSendMessage('Photo shared', 'image')
                setShowAttachments(false)
              }}
              className="flex flex-col items-center gap-2 p-4 bg-background rounded-xl border border-border hover:border-accent/30 hover:bg-accent/5 transition-all duration-200 min-w-0 flex-1 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              aria-label="Share photo"
            >
              <Image className="w-6 h-6 text-accent" />
              <span className="text-xs text-mutedForeground font-medium">Photo</span>
            </button>
          </div>
        </div>
      )}

      <div className="p-4 border-t border-border bg-surface">
        <div className="flex items-end gap-3">
          <button
            onClick={() => setShowAttachments(!showAttachments)}
            className={`p-3 rounded-full transition-all duration-200 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
              showAttachments 
                ? 'bg-primary/10 text-primary border border-primary/20' 
                : 'hover:bg-muted text-mutedForeground border border-transparent'
            }`}
            aria-label="Attach file"
          >
            <Paperclip className="w-5 h-5" />
          </button>

          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={newMessage}
              onChange={handleTextareaChange}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              className="w-full px-4 py-3 bg-background border border-border rounded-2xl text-foreground placeholder-mutedForeground focus:border-primary focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 resize-none min-h-[48px] max-h-[120px] shadow-sm"
              rows={1}
            />
          </div>

          <button
            onClick={handleSendMessage}
            disabled={!newMessage.trim()}
            className="p-3 bg-primary text-primaryForeground rounded-full hover:bg-primary/90 disabled:bg-muted disabled:text-mutedForeground disabled:cursor-not-allowed transition-all duration-200 shadow-md hover:shadow-lg active:scale-95 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:hover:scale-100"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  )
}

