'use client'

import { useState, useEffect } from 'react'
import { Users, CheckCircle2, Circle, Calendar, MapPin, Utensils, Flame, Car, Tent, Plus, X, Edit3 } from 'lucide-react'

interface GroupMember {
  id: string
  name: string
  email: string
  avatar?: string
  isOnline: boolean
}

interface Task {
  id: string
  title: string
  description: string
  category: 'food' | 'equipment' | 'logistics' | 'safety' | 'entertainment'
  assignedTo: string[]
  dueDate: string
  isCompleted: boolean
  priority: 'low' | 'medium' | 'high'
  estimatedTime: string
}

interface TaskAssignmentProps {
  tripId?: string
  groupMembers?: GroupMember[]
  initialTasks?: Task[]
  onTaskUpdate?: (task: Task) => void
  onTaskCreate?: (task: Omit<Task, 'id'>) => void
  onTaskDelete?: (taskId: string) => void
}

const DEFAULT_MEMBERS: GroupMember[] = [
  { id: '1', name: 'Alex Chen', email: 'alex@example.com', isOnline: true },
  { id: '2', name: 'Sarah Johnson', email: 'sarah@example.com', isOnline: false },
  { id: '3', name: 'Mike Rodriguez', email: 'mike@example.com', isOnline: true },
  { id: '4', name: 'Emma Davis', email: 'emma@example.com', isOnline: true }
]

const DEFAULT_TASKS: Task[] = [
  {
