const CATEGORY_ICONS = {
  food: Utensils,
  equipment: Tent,
  logistics: Car,
  safety: CheckCircle2,
  entertainment: Users
}

const CATEGORY_COLORS = {
  food: 'bg-accent/10 text-accent border-accent/20 dark:bg-accent/10 dark:text-accent dark:border-accent/20',
  equipment: 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20',
  logistics: 'bg-secondary/10 text-secondary border-secondary/20 dark:bg-secondary/10 dark:text-secondary dark:border-secondary/20',
  safety: 'bg-destructive/10 text-destructive border-destructive/20 dark:bg-destructive/10 dark:text-destructive dark:border-destructive/20',
  entertainment: 'bg-primary/10 text-primary border-primary/20 dark:bg-primary/10 dark:text-primary dark:border-primary/20'
}

const PRIORITY_COLORS = {
  low: 'bg-muted text-muted-foreground dark:bg-muted dark:text-muted-foreground',
  medium: 'bg-accent/10 text-accent dark:bg-accent/10 dark:text-accent',
  high: 'bg-destructive/10 text-destructive dark:bg-destructive/10 dark:text-destructive'
}

export function TaskAssignmentComponent({
  tripId = 'trip-1',
  groupMembers = DEFAULT_MEMBERS,
  initialTasks = DEFAULT_TASKS,
  onTaskUpdate = () => {},
  onTaskCreate = () => {},
  onTaskDelete = () => {}
}: TaskAssignmentProps = {}) {
  const [tasks, setTasks] = useState<Task[]>(initialTasks)
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingTask, setEditingTask] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    category: 'food' as Task['category'],
    assignedTo: [] as string[],
    dueDate: '',
    priority: 'medium' as Task['priority'],
    estimatedTime: ''
  })

  const categories = [
    { id: 'all', label: 'All Tasks', icon: Users },
    { id: 'food', label: 'Food & Meals', icon: Utensils },
    { id: 'equipment', label: 'Equipment', icon: Tent },
    { id: 'logistics', label: 'Logistics', icon: Car },
    { id: 'safety', label: 'Safety', icon: CheckCircle2 }
  ]

  const filteredTasks = selectedCategory === 'all' 
    ? tasks 
    : tasks.filter(task => task.category === selectedCategory)

  const completedTasks = tasks.filter(task => task.isCompleted).length
  const totalTasks = tasks.length
  const progressPercentage = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0

  const toggleTaskCompletion = (taskId: string) => {
    setTasks(prev => prev.map(task => {
      if (task.id === taskId) {
        const updatedTask = { ...task, isCompleted: !task.isCompleted }
        onTaskUpdate(updatedTask)
        return updatedTask
      }
      return task
    }))
  }

  const handleCreateTask = () => {
    if (!newTask.title.trim()) {
      setError('Task title is required')
      return
    }

    setError(null)
    const task: Task = {
      id: Date.now().toString(),
      ...newTask,
      isCompleted: false
    }

    setTasks(prev => [...prev, task])
    onTaskCreate(task)
    setNewTask({
      title: '',
      description: '',
      category: 'food',
      assignedTo: [],
      dueDate: '',
      priority: 'medium',
      estimatedTime: ''
    })
    setShowCreateForm(false)
  }

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(task => task.id !== taskId))
    onTaskDelete(taskId)
  }

  const getMemberName = (memberId: string) => {
    return groupMembers.find(member => member.id === memberId)?.name || 'Unknown'
  }

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').toUpperCase()
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  return (
    <div className="min-h-screen bg-background dark:bg-background font-sans">
      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-foreground dark:text-foreground mb-1">Task Assignment</h1>
              <p className="text-muted-foreground dark:text-muted-foreground text-sm">Organize responsibilities for your off-road adventure</p>
            </div>
            <button
              onClick={() => setShowCreateForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              aria-label="Create new task"
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">New Task</span>
            </button>
          </div>

          {/* Progress Bar */}
          <div className="bg-surface dark:bg-surface rounded-xl p-4 border border-border dark:border-border shadow-sm">
            <div className="flex items-center justify-between mb-2">
              <span className="text-foreground dark:text-foreground text-sm font-medium">Trip Progress</span>
              <span className="text-muted-foreground dark:text-muted-foreground text-sm">{completedTasks}/{totalTasks} completed</span>
            </div>
            <div className="w-full bg-muted dark:bg-muted rounded-full h-2">
              <div 
                className="bg-primary dark:bg-primary h-2 rounded-full transition-all duration-300"
                style={{ width: `${progressPercentage}%` }}
              />
            </div>
          </div>
        </div>

        {/* Error State */}
        {error && (
          <div className="mb-6 rounded-lg bg-destructive/10 dark:bg-destructive/10 border border-destructive/20 dark:border-destructive/20 p-4">
            <p className="text-sm text-destructive dark:text-destructive">{error}</p>
          </div>
        )}

        {/* Category Filter */}
        <div className="mb-6">
          <div className="flex gap-2 overflow-x-auto pb-2">
            {categories.map(category => {
              const Icon = category.icon
              const isActive = selectedCategory === category.id
              return (
                <button
                  key={category.id}
                  onClick={() => setSelectedCategory(category.id)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap transition-all duration-150 hover:scale-[1.02] active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 ${
                    isActive
                      ? 'bg-primary text-primary-foreground shadow-md'
                      : 'bg-surface text-muted-foreground hover:bg-muted border border-border dark:bg-surface dark:text-muted-foreground dark:hover:bg-muted dark:border-border'
                  }`}
                  aria-label={`Filter by ${category.label}`}
                >
                  <Icon className="w-4 h-4" />
                  <span className="text-sm font-medium">{category.label}</span>
                </button>
              )
            })}
          </div>
        </div>

        {/* Loading State */}
        {isLoading ? (
          <div className="space-y-4 animate-pulse">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-4">
                <div className="flex items-start gap-3">
                  <div className="w-5 h-5 bg-muted dark:bg-muted rounded-full"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-muted dark:bg-muted rounded w-3/4"></div>
                    <div className="h-3 bg-muted dark:bg-muted rounded w-1/2"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          /* Tasks List */
          <div className="space-y-4 mb-6">
            {filteredTasks.length === 0 ? (
              <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-12 text-center">
                <div className="w-16 h-16 bg-muted dark:bg-muted rounded-full mx-auto mb-4 flex items-center justify-center">
                  <Users className="w-8 h-8 text-muted-foreground dark:text-muted-foreground" />
                </div>
                <h3 className="text-lg font-medium text-foreground dark:text-foreground mb-2">No tasks found</h3>
                <p className="text-muted-foreground dark:text-muted-foreground text-sm mb-4">
                  {selectedCategory === 'all' 
                    ? 'Create your first task to get started organizing your trip'
                    : `No ${selectedCategory} tasks assigned yet`
                  }
                </p>
                <button
                  onClick={() => setShowCreateForm(true)}
                  className="px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                >
                  Create Task
                </button>
              </div>
            ) : (
              filteredTasks.map(task => {
                const CategoryIcon = CATEGORY_ICONS[task.category]
                return (
                  <div
                    key={task.id}
                    className={`bg-surface dark:bg-surface rounded-xl border p-4 transition-all duration-200 hover:-translate-y-1 hover:shadow-lg ${
                      task.isCompleted 
                        ? 'border-primary/30 bg-primary/5 dark:border-primary/30 dark:bg-primary/5' 
                        : 'border-border hover:border-primary/50 dark:border-border dark:hover:border-primary/50'
                    }`}
                  >
                    <div className="flex items-start gap-3">
                      <button
                        onClick={() => toggleTaskCompletion(task.id)}
                        className="mt-1 transition-all duration-150 hover:scale-110 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 rounded-full"
                        aria-label={task.isCompleted ? 'Mark as incomplete' : 'Mark as complete'}
                      >
                        {task.isCompleted ? (
                          <CheckCircle2 className="w-5 h-5 text-primary dark:text-primary" />
                        ) : (
                          <Circle className="w-5 h-5 text-muted-foreground hover:text-primary dark:text-muted-foreground dark:hover:text-primary" />
                        )}
                      </button>

                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-2">
                          <div className="flex items-center gap-2 flex-wrap">
                            <h3 className={`font-medium ${
                              task.isCompleted ? 'text-muted-foreground line-through dark:text-muted-foreground' : 'text-foreground dark:text-foreground'
                            }`}>
                              {task.title}
                            </h3>
                            <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-xs border ${CATEGORY_COLORS[task.category]}`}>
                              <CategoryIcon className="w-3 h-3" />
                              <span className="capitalize">{task.category}</span>
                            </div>
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${PRIORITY_COLORS[task.priority]}`}>
                              {task.priority}
                            </span>
                          </div>
                          <button
                            onClick={() => handleDeleteTask(task.id)}
                            className="text-muted-foreground hover:text-destructive transition-colors duration-150 p-1 rounded hover:bg-destructive/10 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                            aria-label="Delete task"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>

                        {task.description && (
                          <p className={`text-sm mb-3 ${
                            task.isCompleted ? 'text-muted-foreground dark:text-muted-foreground' : 'text-muted-foreground dark:text-muted-foreground'
                          }`}>
                            {task.description}
                          </p>
                        )}

                        <div className="flex items-center gap-4 text-xs text-muted-foreground dark:text-muted-foreground mb-3">
                          <div className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            <span>{formatDate(task.dueDate)}</span>
                          </div>
                          {task.estimatedTime && (
                            <div className="flex items-center gap-1">
                              <span>⏱️</span>
                              <span>{task.estimatedTime}</span>
                            </div>
                          )}
                        </div>

                        {/* Assigned Members */}
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-muted-foreground dark:text-muted-foreground">Assigned to:</span>
                          <div className="flex items-center gap-1">
                            {task.assignedTo.map(memberId => {
                              const member = groupMembers.find(m => m.id === memberId)
                              if (!member) return null
                              return (
                                <div
                                  key={memberId}
                                  className="flex items-center gap-1 px-2 py-1 bg-muted dark:bg-muted rounded-full hover:bg-muted/80 transition-colors duration-150"
                                  title={member.name}
                                >
                                  <div className="w-5 h-5 bg-primary text-primary-foreground rounded-full flex items-center justify-center text-xs font-medium">
                                    {getInitials(member.name)}
                                  </div>
                                  <span className="text-xs text-foreground dark:text-foreground hidden sm:inline">
                                    {member.name.split(' ')[0]}
                                  </span>
                                  {member.isOnline && (
                                    <div className="w-2 h-2 bg-primary rounded-full" />
                                  )}
                                </div>
                              )
                            })}
                            {task.assignedTo.length === 0 && (
                              <span className="text-xs text-muted-foreground dark:text-muted-foreground italic">Unassigned</span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )
              })
            )}
          </div>
        )}

        {/* Create Task Form */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
            <div className="bg-surface dark:bg-surface rounded-xl border border-border dark:border-border p-6 w-full max-w-md max-h-[90vh] overflow-y-auto shadow-xl">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-foreground dark:text-foreground">Create New Task</h2>
                <button
                  onClick={() => {
                    setShowCreateForm(false)
                    setError(null)
                  }}
                  className="text-muted-foreground hover:text-foreground transition-colors duration-150 p-1 rounded hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  aria-label="Close form"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                    Task Title *
                  </label>
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask(prev => ({ ...prev, title: e.target.value }))}
                    className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-muted-foreground dark:placeholder-muted-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    placeholder="Enter task title"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                    Description
                  </label>
                  <textarea
                    value={newTask.description}
                    onChange={(e) => setNewTask(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-muted-foreground dark:placeholder-muted-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200 resize-none"
                    rows={3}
                    placeholder="Describe the task"
                  />
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                      Category
                    </label>
                    <select
                      value={newTask.category}
                      onChange={(e) => setNewTask(prev => ({ ...prev, category: e.target.value as Task['category'] }))}
                      className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    >
                      <option value="food">Food & Meals</option>
                      <option value="equipment">Equipment</option>
                      <option value="logistics">Logistics</option>
                      <option value="safety">Safety</option>
                      <option value="entertainment">Entertainment</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                      Priority
                    </label>
                    <select
                      value={newTask.priority}
                      onChange={(e) => setNewTask(prev => ({ ...prev, priority: e.target.value as Task['priority'] }))}
                      className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    >
                      <option value="low">Low</option>
                      <option value="medium">Medium</option>
                      <option value="high">High</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                    Due Date
                  </label>
                  <input
                    type="datetime-local"
                    value={newTask.dueDate}
                    onChange={(e) => setNewTask(prev => ({ ...prev, dueDate: e.target.value }))}
                    className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-1">
                    Estimated Time
                  </label>
                  <input
                    type="text"
                    value={newTask.estimatedTime}
                    onChange={(e) => setNewTask(prev => ({ ...prev, estimatedTime: e.target.value }))}
                    className="w-full px-3 py-2 bg-background dark:bg-background border border-border dark:border-border rounded-lg text-foreground dark:text-foreground placeholder-muted-foreground dark:placeholder-muted-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all duration-200"
                    placeholder="e.g., 2 hours, 30 minutes"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-foreground dark:text-foreground mb-2">
                    Assign to Members
                  </label>
                  <div className="space-y-2 max-h-32 overflow-y-auto">
                    {groupMembers.map(member => (
                      <label key={member.id} className="flex items-center gap-2 cursor-pointer hover:bg-muted/50 p-1 rounded transition-colors duration-150">
                        <input
                          type="checkbox"
                          checked={newTask.assignedTo.includes(member.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setNewTask(prev => ({ ...prev, assignedTo: [...prev.assignedTo, member.id] }))
                            } else {
                              setNewTask(prev => ({ ...prev, assignedTo: prev.assignedTo.filter(id => id !== member.id) }))
                            }
                          }}
                          className="w-4 h-4 text-primary bg-background border-border rounded focus:ring-ring focus:ring-2"
                        />
                        <div className="flex items-center gap-2">
                          <div className="w-6 h-6 bg-primary text-primary-foreground rounded-full flex items-center justify-center text-xs font-medium">
                            {getInitials(member.name)}
                          </div>
                          <span className="text-sm text-foreground dark:text-foreground">{member.name}</span>
                          {member.isOnline && (
                            <div className="w-2 h-2 bg-primary rounded-full" />
                          )}
                        </div>
                      </label>
                    ))}
                  </div>
                </div>

                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => {
                      setShowCreateForm(false)
                      setError(null)
                    }}
                    className="flex-1 px-4 py-2 bg-muted text-muted-foreground rounded-lg hover:bg-muted/80 hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleCreateTask}
                    disabled={!newTask.title.trim()}
                    className="flex-1 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:bg-muted disabled:text-muted-foreground hover:scale-[1.02] active:scale-[0.98] transition-all duration-150 font-medium focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:hover:scale-100"
                  >
                    Create Task
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default function TaskAssignmentDemo() {
  return <TaskAssignmentComponent />
}
